      s.Gender, s.DateOfBirth, s.Address, s.ProvinceCode, s.QualificationCode, s.Specialized, s.YearExperience,
      s.StartDate, s.EndDate, s.Position, s.PositionCode, s.CertificateCode, s.SMHyundaiCode, s.IdentityCardNo,
      s.WebsiteLink, s.FacebookLink, s.FanpageLink, s.GroupLink, s.ZaloLink, s.AccountHTA }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/salesmen", async (SalesManDto dto, AppDbContext db, ITenantContext t) =>
{
    // audit 2026-09-03: bổ sung guard đúng nguồn FrmCreateSalesMan.btnSave_Click (trước chỉ check SalesManName)
    if (string.IsNullOrWhiteSpace(dto.SMHyundaiCode)) return Results.BadRequest(new { error = "Chưa nhập Mã nhân viên Hyundai!" });
    if (string.IsNullOrWhiteSpace(dto.IdentityCardNo)) return Results.BadRequest(new { error = "Chưa nhập Số CMND/ thẻ CCCD!" });
    if (string.IsNullOrWhiteSpace(dto.DepartmentCode)) return Results.BadRequest(new { error = "Chưa chọn Mã phòng ban!" });
    if (string.IsNullOrWhiteSpace(dto.SalesType)) return Results.BadRequest(new { error = "Chưa chọn Mã loại nhân viên!" });
    if (string.IsNullOrWhiteSpace(dto.SalesManName)) return Results.BadRequest(new { error = "Chưa nhập Họ và tên nhân viên!" });
    if (string.IsNullOrWhiteSpace(dto.Gender)) return Results.BadRequest(new { error = "Chưa chọn Giới tính!" });
    if (dto.DateOfBirth is null) return Results.BadRequest(new { error = "Chưa nhập Ngày sinh!" });
    if (string.IsNullOrWhiteSpace(dto.Phone)) return Results.BadRequest(new { error = "Chưa nhập Số điện thoại nhân viên!" });
    if (!System.Text.RegularExpressions.Regex.IsMatch(dto.Phone.Trim(), @"^0\d{9,10}$")) return Results.BadRequest(new { error = "Số điện thoại không hợp lệ!" });
    if (string.IsNullOrWhiteSpace(dto.Status) || dto.Status == "0") return Results.BadRequest(new { error = "Chưa chọn Trạng thái!" });
    if (string.IsNullOrWhiteSpace(dto.PositionCode)) return Results.BadRequest(new { error = "Chưa nhập Chức vụ!" });
    if (!string.IsNullOrWhiteSpace(dto.Email) && !System.Text.RegularExpressions.Regex.IsMatch(dto.Email, @"^[^@\s]+@[^@\s]+\.[^@\s]+$"))
        return Results.BadRequest(new { error = "Email không hợp lệ!" });
    if (string.IsNullOrWhiteSpace(dto.Address)) return Results.BadRequest(new { error = "Chưa nhập Địa chỉ!" });
    if (string.IsNullOrWhiteSpace(dto.ProvinceCode)) return Results.BadRequest(new { error = "Chưa chọn Quê quán!" });
    if (string.IsNullOrWhiteSpace(dto.Specialized)) return Results.BadRequest(new { error = "Chưa nhập Chuyên ngành!" });
    if (string.IsNullOrWhiteSpace(dto.QualificationCode)) return Results.BadRequest(new { error = "Chưa chọn Trình độ chuyên môn!" });
    if (string.IsNullOrWhiteSpace(dto.CertificateCode)) return Results.BadRequest(new { error = "Chưa chọn Chứng chỉ!" });
    if (dto.StartDate is null) return Results.BadRequest(new { error = "Chưa nhập Ngày bắt đầu!" });
    if (dto.SalesType.Trim().Equals("TVBH", StringComparison.OrdinalIgnoreCase))
    {
        if (string.IsNullOrWhiteSpace(dto.WebsiteLink)) return Results.BadRequest(new { error = "Chưa nhập Website!" });
        if (string.IsNullOrWhiteSpace(dto.FacebookLink)) return Results.BadRequest(new { error = "Chưa nhập Facebook cá nhân!" });
        if (string.IsNullOrWhiteSpace(dto.FanpageLink)) return Results.BadRequest(new { error = "Chưa nhập Fanpage!" });
        if (string.IsNullOrWhiteSpace(dto.GroupLink)) return Results.BadRequest(new { error = "Chưa nhập Group!" });
        if (string.IsNullOrWhiteSpace(dto.ZaloLink)) return Results.BadRequest(new { error = "Chưa nhập Zalo!" });
    }
    var code = string.IsNullOrWhiteSpace(dto.SalesManCode) ? "NV" + DateTime.Now.ToString("yyMMddHHmmss") : dto.SalesManCode.Trim().ToUpperInvariant();
    var s = await db.SalesMen.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SalesManCode == code);
    if (s is null) { s = new SalesMan { OrgId = t.OrgId, SalesManCode = code }; db.SalesMen.Add(s); }
    s.SalesManName = dto.SalesManName.Trim(); s.DealerCode = dto.DealerCode; s.DepartmentCode = dto.DepartmentCode; s.SalesType = dto.SalesType;
    s.Phone = dto.Phone; s.Email = dto.Email; s.Status = dto.Status ?? "1";
    s.Gender = dto.Gender; s.DateOfBirth = dto.DateOfBirth; s.Address = dto.Address; s.ProvinceCode = dto.ProvinceCode;
    s.QualificationCode = dto.QualificationCode; s.Specialized = dto.Specialized; s.YearExperience = dto.YearExperience;
    s.StartDate = dto.StartDate; s.EndDate = dto.EndDate; s.Position = dto.Position; s.PositionCode = dto.PositionCode;
    s.CertificateCode = dto.CertificateCode; s.SMHyundaiCode = dto.SMHyundaiCode; s.IdentityCardNo = dto.IdentityCardNo;
    s.WebsiteLink = dto.WebsiteLink; s.FacebookLink = dto.FacebookLink; s.FanpageLink = dto.FanpageLink;
    s.GroupLink = dto.GroupLink; s.ZaloLink = dto.ZaloLink; s.AccountHTA = dto.AccountHTA;
    await db.SaveChangesAsync();
    return Results.Ok(new { s.SalesManCode, s.SalesManName, s.Status });
}).RequireAuthorization();

// ===== Sửa PHÒNG BAN / LOẠI NVBH theo lô (Support_Mst_SalesMan_UpdateDepartmentAndSMType —
// 2010.HTC Biz.HTC.WH.hkt.cs:7470). TWIN: chỉ `TERP.WSHTC.64` (99643). =====
// 🔴 Nguồn có **BA nhánh update** tuỳ trường nào thực sự đổi (cả hai / chỉ phòng ban / chỉ loại) —
//    chỉ ghi đúng cột đã đổi, không đụng cột kia. Giá trị mới để trống ⇒ **giữ giá trị hiện tại**.
// 🔴 Guard nguồn: cặp (`DepartmentCode`, `SMType`) mới phải tồn tại trong `Mst_SalesManType`
//    (master khoá kép) — MiniHTC CÓ master này nên guard đã port đủ.
app.MapGet("/api/salesmen/dept-smtype-history", async (AppDbContext db, ITenantContext t, string? smCode) =>
{
    var qy = db.SalesManUpdDeptSMTypeHiss.Where(h => h.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(smCode)) qy = qy.Where(h => h.SMCode == smCode.Trim().ToUpperInvariant());
    var items = await qy.OrderByDescending(h => h.Id).Take(500)
        .Select(h => new { h.SMCode, h.DepartmentCodeOld, h.DepartmentCodeNew, h.SMTypeOld, h.SMTypeNew, h.UpdDTime, h.UpdBy }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/salesmen/update-dept-smtype", async (SalesManUpdDeptDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var rows = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.SMCode)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Chưa chọn nhân viên nào." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    int changedDept = 0, changedType = 0, skipped = 0;
    foreach (var r in rows)
    {
        var code = r.SMCode!.Trim().ToUpperInvariant();
        var sm = await db.SalesMen.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SalesManCode == code);
        if (sm is null) return Results.BadRequest(new { error = $"Không tìm thấy nhân viên {code}." });

        var deptOld = sm.DepartmentCode ?? "";
        var typeOld = sm.SalesType ?? "";
        // Giá trị mới để trống ⇒ giữ nguyên giá trị hiện tại (nguồn gán lại từ DB).
        var deptNew = string.IsNullOrWhiteSpace(r.DepartmentCodeNew) ? deptOld : r.DepartmentCodeNew!.Trim().ToUpperInvariant();
        var typeNew = string.IsNullOrWhiteSpace(r.SMTypeNew) ? typeOld : r.SMTypeNew!.Trim().ToUpperInvariant();

        var deptChanged = !string.Equals(deptOld, deptNew, StringComparison.OrdinalIgnoreCase);
        var typeChanged = !string.Equals(typeOld, typeNew, StringComparison.OrdinalIgnoreCase);
        if (!deptChanged && !typeChanged) { skipped++; continue; }

        // Guard: cặp (phòng ban, loại NVBH) phải có trong master khoá kép.
        var okPair = await db.SalesManTypes.AnyAsync(x => x.OrgId == t.OrgId && x.DepartmentCode == deptNew && x.SMType == typeNew);
        if (!okPair) return Results.BadRequest(new { error = $"Cặp phòng ban/loại NVBH ({deptNew}/{typeNew}) không có trong danh mục." });

        db.SalesManUpdDeptSMTypeHiss.Add(new SalesManUpdDeptSMTypeHis
        {
            OrgId = t.OrgId, SMCode = code,
            DepartmentCodeOld = deptOld, DepartmentCodeNew = deptNew,
            SMTypeOld = typeOld, SMTypeNew = typeNew,
            UpdDTime = now, UpdBy = who,
        });
        // Ba nhánh của nguồn: chỉ ghi đúng cột đã đổi.
        if (deptChanged) { sm.DepartmentCode = deptNew; changedDept++; }
        if (typeChanged) { sm.SalesType = typeNew; changedType++; }
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { rows = rows.Count, changedDept, changedType, skipped });
}).RequireAuthorization();

app.MapDelete("/api/salesmen/{code}", async (string code, AppDbContext db, ITenantContext t) =>
{
    code = code.Trim().ToUpperInvariant();
    var s = await db.SalesMen.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SalesManCode == code);
    if (s is null) return Results.NotFound(new { code });
    db.SalesMen.Remove(s); await db.SaveChangesAsync();
    return Results.Ok(new { deleted = code });
}).RequireAuthorization();

// Import hàng loạt NVBH thật từ Mst_SalesMan (SQL nguồn 2010.HTC, 18490 dòng thật). Dedupe theo SalesManCode.
app.MapPost("/api/import/salesmen", async (List<ImportSalesManDto> rows, AppDbContext db, ITenantContext t) =>
{
    if (rows is null || rows.Count == 0) return Results.BadRequest(new { error = "Không có dữ liệu import." });
    int added = 0, skipped = 0;
    foreach (var r in rows)
    {
        if (string.IsNullOrWhiteSpace(r.SMCode) || string.IsNullOrWhiteSpace(r.SMName)) { skipped++; continue; }
        var code = r.SMCode.Trim().ToUpperInvariant();
        if (await db.SalesMen.AnyAsync(x => x.OrgId == t.OrgId && x.SalesManCode == code)) { skipped++; continue; }
        db.SalesMen.Add(new SalesMan
        {
            OrgId = t.OrgId, SalesManCode = code, SalesManName = r.SMName.Trim(), DealerCode = r.DealerCode, DepartmentCode = r.DepartmentCode,
            SalesType = r.SMType, Phone = r.SMPhoneNo, Email = r.SMEmail, Status = r.SMStatus == "0" ? "0" : "1",
            Gender = r.SMGender, DateOfBirth = DateTime.TryParse(r.SMDateOfBirth, out var dob) ? dob : null, Address = r.SMAddress,
            ProvinceCode = r.ProvinceCode, QualificationCode = r.QualificationCode, Specialized = r.SMSpecialized,
            StartDate = DateTime.TryParse(r.SMStartDate, out var sd) ? sd : null, PositionCode = r.SMPostionCode,
            SMHyundaiCode = r.SMHyundaiCode, IdentityCardNo = r.IdentityCardNo,
            WebsiteLink = r.WebsiteLink, FacebookLink = r.FacebookLink, FanpageLink = r.FanpageLink, GroupLink = r.GroupLink, ZaloLink = r.ZaloLink, AccountHTA = r.AccountHTA
        });
        added++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { added, skipped, total = rows.Count });
}).RequireAuthorization();

// ===== Báo cáo đại lý (port 1:1 kiểu FrmBC*/Rpt — read-only + lọc + tổng hợp) =====
app.MapGet("/api/reports/dealers", async (AppDbContext db, ITenantContext t, string? province, string? status) =>
{
    var q = db.Dealers.Where(d => d.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(province)) q = q.Where(d => d.ProvinceCode == province);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(d => d.Status == status);
    var rows = await q.OrderBy(d => d.ProvinceCode).ThenBy(d => d.DealerCode)
        .Select(d => new { d.DealerCode, d.DealerName, d.ProvinceCode, d.Phone, d.Status }).ToListAsync();
    var byProvince = rows.GroupBy(r => r.ProvinceCode ?? "(chưa có)")
        .Select(g => new { province = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    return Results.Ok(new
    {
        total = rows.Count,
        active = rows.Count(r => r.Status == "1"),
        inactive = rows.Count(r => r.Status != "1"),
        byProvince,
        rows
    });
}).RequireAuthorization();

