    var items = await q.OrderByDescending(c => c.Id).Take(500).Select(c => new
    { c.Code, c.Vin, c.CancelTypeCode, c.CarCancelRemark, c.FlagEarlyCancel, c.FlagMapVIN, c.Status, c.CreatedAt, c.ApprovedAt,
      // #201 §12: trạng thái THẬT của xe nằm ở `Car_Car.FlagActive`, không phải cột Status của nhật ký.
      flagActive = db.CarVinMasters.Where(m => m.OrgId == t.OrgId && m.VIN == c.Vin).Select(m => m.FlagActive).FirstOrDefault(),
      carCancelDate = db.CarVinMasters.Where(m => m.OrgId == t.OrgId && m.VIN == c.Vin).Select(m => m.CarCancelDate).FirstOrDefault() }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// ===== 🔴 #201 HUỶ XE — `CarCarCancel_New20181119` (DataWH/Biz.HTC.WH.cs:59995) =====
// BƯỚC 3B: md5 **vùng hàm** 59995-60400 = `38788ac1` KHỚP 2 máy (file này có lệch ở chỗ khác — xem #196/#197).
// TWIN: **cả hai bit** WSHTC 32 và 64 cùng gọi `_New20181119` ⇒ không lệch. Cặp lệnh của nguồn đúng HAI cái:
//   `CarCarCancel_New20181119` (huỷ) và `CarCarReActive_New20181119` (60200, kích hoạt lại) — KHÔNG có
//   lệnh duyệt/từ chối nào ⇒ `/api/cancels/{code}/{action}` cũ là BỊA (đã gỡ, xem ghi chú bên dưới).
//
// 🔴 Nguồn KHÔNG có bảng huỷ riêng: ghi thẳng **5 cột của `Car_Car`** —
//   huỷ: `FlagActive="0"`, `CarCancelType`, `CarCancelRemark`, `CarCancelDate=hôm nay`, `CarCancelBy`;
//   kích hoạt lại: `FlagActive="1"`, `CarCancelType="NONE"`, `CarCancelRemark`, hai cột mốc về **NULL**.
//   Bảng `CarCancels` của port cũ giữ lại làm NHẬT KÝ, nhưng nay phải ghi kèm 5 cột thật.
//
// BỐN GUARD của nguồn (60064-60140), port đủ:
//  1. `CarCancelType` rỗng ⇒ `CarCarCancel_InvalidCarCancelType`;
//  2. xe phải tồn tại và đang `FlagActive = Active`;
//  3. 🔴 **tổng thanh toán phải bằng 0** — còn dòng `Pmt_PaymentDetail` ⇒ `CarCarCancel_PaymentMustBeZero`;
//  4. 🔴 **không được có lệnh giao xe** — còn dòng `Car_DeliveryOrderDetail` ⇒ `CarCarCancel_CarDeliveryOrderExisting`.
app.MapPost("/api/cancels", async (CancelDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    if (string.IsNullOrWhiteSpace(dto.Vin)) return Results.BadRequest(new { error = "Cần Vin." });
    if (string.IsNullOrWhiteSpace(dto.CancelTypeCode)) return Results.BadRequest(new { error = "Cần loại hủy (CancelTypeCode)." });

    var vinC = dto.Vin.Trim().ToUpperInvariant();
    var cvmC = await db.CarVinMasters.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.VIN == vinC);
    // guard 2 — xe phải tồn tại và đang hoạt động (nguồn: strFlagActiveListToCheck = Flag.Active).
    if (cvmC is null) return Results.NotFound(new { error = $"Không tìm thấy xe {vinC}.", vin = vinC });
    if ((cvmC.FlagActive ?? "1") != "1")
        return Results.BadRequest(new { error = $"Xe {vinC} đang không hoạt động — không huỷ lại được." });
    // guard 3 — còn phát sinh thanh toán thì KHÔNG huỷ.
    if (await db.PmtLines.AnyAsync(x => x.OrgId == t.OrgId && x.RefNo == vinC))
        return Results.BadRequest(new { error = $"Xe {vinC} đã phát sinh thanh toán — tổng thanh toán phải bằng 0." });
    // guard 4 — đã nằm trong lệnh giao xe thì KHÔNG huỷ.
    if (await db.DeliveryOrderCars.AnyAsync(x => x.OrgId == t.OrgId && x.Vin == vinC))
        return Results.BadRequest(new { error = $"Xe {vinC} đang nằm trong lệnh giao xe — không huỷ được." });
    var code = "HX" + DateTime.Now.ToString("yyMMddHHmmss");
    var c = new CarCancel
    {
        OrgId = t.OrgId, Code = code, Vin = dto.Vin.Trim().ToUpperInvariant(),
        CancelTypeCode = dto.CancelTypeCode.Trim(), CarCancelRemark = dto.CarCancelRemark,
        FlagEarlyCancel = dto.FlagEarlyCancel, FlagMapVIN = dto.FlagMapVIN,
        Status = "Requested"
    };
    db.CarCancels.Add(c);
    // #201: ghi 5 cột THẬT của `Car_Car` — đây mới là chỗ nguồn lưu trạng thái huỷ.
    cvmC.FlagActive = "0";
    cvmC.CarCancelType = dto.CancelTypeCode.Trim();
    cvmC.CarCancelRemark = dto.CarCancelRemark;
    cvmC.CarCancelDate = DateTime.Now;
    cvmC.CarCancelBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    cvmC.LogLUDateTime = DateTime.Now; cvmC.LogLUBy = cvmC.CarCancelBy;
    await db.SaveChangesAsync();
    return Results.Ok(new { c.Code, c.Vin, status = c.Status, flagActive = cvmC.FlagActive,
                            cvmC.CarCancelType, cvmC.CarCancelDate, cvmC.CarCancelBy });
}).RequireAuthorization();

// ⚠️ #201 ĐÃ BỎ `POST /api/cancels/{code}/{action}` (approve|reject) — **nguồn KHÔNG có lệnh duyệt huỷ xe**.
//    Đã quét CẢ HAI cổng `TERP.WSHTC` (32-bit) và `TERP.WSHTC.64` (đúng luật `C0-ducentesimusnonagesimusquartus`):
//    toàn hệ chỉ có **hai** lệnh cho việc này — `CarCarCancel_New20181119` và `CarCarReActive_New20181119`.
//    Huỷ xe có hiệu lực NGAY khi gọi lệnh (ghi `Car_Car.FlagActive="0"`), không qua bước duyệt nào;
//    "kích hoạt lại" là lệnh RIÊNG, không phải trạng thái của phiếu huỷ.
//    ⇒ Từ vựng `Requested/Approved/Rejected` của port cũ cũng không có ở nguồn; cột `CarCancel.Status`
//    nay chỉ còn là nhãn nhật ký nội bộ, trạng thái thật nằm ở `CarVinMaster.FlagActive`.

// ===== Cấu hình hệ thống (port 1:1 FrmMngConfig*/Setup) =====
app.MapGet("/api/configs", async (AppDbContext db, ITenantContext t, string? q) =>
{
    var query = db.Configs.Where(c => c.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(q)) query = query.Where(c => c.ConfigKey.Contains(q));
    var items = await query.OrderBy(c => c.ConfigKey).Select(c => new { c.ConfigKey, c.ConfigValue, c.Description, c.UpdatedAt }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/configs", async (ConfigDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.ConfigKey)) return Results.BadRequest(new { error = "Cần ConfigKey." });
    var key = dto.ConfigKey.Trim();
    var c = await db.Configs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ConfigKey == key);
    if (c is null) { c = new SysConfig { OrgId = t.OrgId, ConfigKey = key }; db.Configs.Add(c); }
    c.ConfigValue = dto.ConfigValue ?? ""; c.Description = dto.Description; c.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { c.ConfigKey, c.ConfigValue });
}).RequireAuthorization();

app.MapDelete("/api/configs/{key}", async (string key, AppDbContext db, ITenantContext t) =>
{
    var c = await db.Configs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ConfigKey == key);
    if (c is null) return Results.NotFound(new { key });
    db.Configs.Remove(c); await db.SaveChangesAsync();
    return Results.Ok(new { deleted = key });
}).RequireAuthorization();

// ===== Kế hoạch/chỉ tiêu KD (port 1:1 FrmMngBusinessPlan) =====
app.MapGet("/api/plans", async (AppDbContext db, ITenantContext t, string? month, string? dealer) =>
{
    var q = db.BusinessPlans.Where(p => p.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(month)) q = q.Where(p => p.Month == month);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(p => p.DealerCode == dealer);
    var rows = await q.OrderBy(p => p.Month).ThenBy(p => p.DealerCode).Take(500).Select(p => new
    { p.DealerCode, p.ModelCode, p.Month, p.TargetQty, p.ActualQty, achieve = p.TargetQty == 0 ? 0 : Math.Round(p.ActualQty * 100.0 / p.TargetQty, 1) }).ToListAsync();
    return Results.Ok(new { count = rows.Count, totalTarget = rows.Sum(r => r.TargetQty), totalActual = rows.Sum(r => r.ActualQty), rows });
}).RequireAuthorization();

app.MapPost("/api/plans", async (PlanDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.DealerCode) || string.IsNullOrWhiteSpace(dto.ModelCode) || string.IsNullOrWhiteSpace(dto.Month))
        return Results.BadRequest(new { error = "Cần DealerCode, ModelCode, Month (YYYYMM)." });
    var dealer = dto.DealerCode.Trim().ToUpperInvariant(); var model = dto.ModelCode.Trim().ToUpperInvariant(); var month = dto.Month.Trim();
    var p = await db.BusinessPlans.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealerCode == dealer && x.ModelCode == model && x.Month == month);
    if (p is null) { p = new BusinessPlan { OrgId = t.OrgId, DealerCode = dealer, ModelCode = model, Month = month }; db.BusinessPlans.Add(p); }
    p.TargetQty = dto.TargetQty; if (dto.ActualQty.HasValue) p.ActualQty = dto.ActualQty.Value; p.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { p.DealerCode, p.ModelCode, p.Month, p.TargetQty, p.ActualQty });
}).RequireAuthorization();

// audit 2026-09-03: vòng đời duyệt kế hoạch KD (FrmMngBusinessPlan) — Pending→Approved1→Approved2(→Cancelled nếu ACTUAL).
app.MapGet("/api/planheaders", async (AppDbContext db, ITenantContext t, string? dealer, string? status, int? year) =>
{
    var q = db.BusinessPlanHeaders.Where(h => h.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(h => h.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(h => h.Status == status);
    if (year.HasValue) q = q.Where(h => h.YearPlan == year.Value);
    var items = await q.OrderByDescending(h => h.Id).Take(500)
        .Select(h => new { h.BusinessPlanCode, h.DealerCode, h.YearPlan, h.Version, h.Status, h.HTCStaffInCharge, h.CreatedAt, h.Approve1At, h.Approve2At, h.CancelledAt,
            h.Approve1By, h.Approve2By, h.TimesPlan }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/planheaders", async (PlanHeaderDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Cần DealerCode." });
    if (dto.YearPlan <= 0) return Results.BadRequest(new { error = "Cần YearPlan." });
    var dealer = dto.DealerCode.Trim().ToUpperInvariant();
    var code = $"BPL{dto.YearPlan}-{dealer}-{(await db.BusinessPlanHeaders.CountAsync(h => h.OrgId == t.OrgId) + 1):D4}";
    var h = new BusinessPlanHeader
    {
        OrgId = t.OrgId, BusinessPlanCode = code, DealerCode = dealer, YearPlan = dto.YearPlan,
        Version = dto.Version == "ACTUAL" ? "ACTUAL" : "INIT",
        Status = "P",   // TConst.BusinessPlanStatus.Pending (BizHTC.zTemp.cs:48481)
        HTCStaffInCharge = dto.HTCStaffInCharge
    };
    db.BusinessPlanHeaders.Add(h); await db.SaveChangesAsync();
    return Results.Ok(new { h.BusinessPlanCode, h.Status });
}).RequireAuthorization();

app.MapPost("/api/planheaders/{code}/approve1", async (string code, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var h = await db.BusinessPlanHeaders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.BusinessPlanCode == code);
    if (h is null) return Results.NotFound(new { code });
    if (h.Status != "P") return Results.BadRequest(new { error = "Trạng thái kế hoạch kinh doanh không hợp lệ!" });
    h.Status = "A1"; h.Approve1At = DateTime.Now; h.Approve1By = user.Identity?.Name ?? "system";
    await db.SaveChangesAsync();
    return Results.Ok(new { h.BusinessPlanCode, h.Status });
}).RequireAuthorization();

app.MapPost("/api/planheaders/{code}/approve2", async (string code, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var h = await db.BusinessPlanHeaders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.BusinessPlanCode == code);
    if (h is null) return Results.NotFound(new { code });
    if (h.Status != "A1") return Results.BadRequest(new { error = "Trạng thái kế hoạch kinh doanh không hợp lệ!" });
    h.Status = "A2"; h.Approve2At = DateTime.Now; h.Approve2By = user.Identity?.Name ?? "system";
    // 🔴 Nguồn ghi trạng thái DÒNG là "A" (KHÔNG phải "A2" như header) — BizHTC.zTemp.cs:50221.
    var dtls = await db.BusinessPlanDtls.Where(x => x.OrgId == t.OrgId && x.BusinessPlanCode == code).ToListAsync();
    foreach (var dl in dtls) dl.BusinessPlanDtlStatus = "A";
    await db.SaveChangesAsync();
    return Results.Ok(new { h.BusinessPlanCode, h.Status });
}).RequireAuthorization();

// ===== #177 BỎ DUYỆT CẤP 2 kế hoạch kinh doanh — `BPL_BusinessPlan_UnApprove2` =====
// Nguồn: `TERP.BizHTC/DataWH/BizHTC.zTemp.cs:50378` (csproj 276). BƯỚC 3B: md5 cả file `dbb71f7d` KHỚP 2 máy.
//
// 🔴 TWIN LỆCH BIT — hai bề mặt KHÁC HẲN NHAU về số cấp duyệt:
//    · WS **32-bit**: `BPL_BusinessPlan_Approve` + `_UnApprove`          (duyệt MỘT cấp)
//    · WS **64-bit**: `_Approve1` + `_Approve2` + `_UnApprove2`          (duyệt HAI cấp)
//    Canonical = 64-bit (hai cấp) — đúng như port đang làm.
//
// 🔴 SỬA MỘT HIỂU SAI HÀNH ĐỘNG (cùng lớp #167 `PRD_..._Cancel` và #172 `_RejectGrtClaim`):
//    Port cũ đặt endpoint này là `/cancel` và **chỉ ghi `CancelledAt`, giữ nguyên `Status = "A2"`**,
//    kèm ghi chú "nguồn không có mã huỷ nên giữ A2". Guard thì trace ĐÚNG (`A2` + `ACTUAL`),
//    nhưng **hành động thì sai**: nguồn không huỷ gì cả — nó **BỎ DUYỆT**, đưa kế hoạch **về "P"**
//    và **XOÁ SẠCH** `Appr1DTime`/`Appr1By`/`Appr2DTime`/`Appr2By`/`TimesPlan` (nguồn gán `DBNull.Value`).
//    Hệ quả của port cũ: kế hoạch **kẹt vĩnh viễn ở "A2"**, không bao giờ sửa/duyệt lại được.
//    ⇒ Đổi tên endpoint theo NGHĨA THẬT: `/unapprove2`.
//
// Guard nguồn (`BPL_BusinessPlan_CheckDB`): `BusinessPlanStatus = "A2"` **và** `Version = "ACTUAL"`
//   ⇒ chỉ bỏ duyệt được bản kế hoạch THỰC TẾ đã duyệt cấp 2, không đụng bản "INIT".
// RBAC: nguồn gọi `myCommon_CheckHTCDirect` — nợ chung fleet.
app.MapPost("/api/planheaders/{code}/unapprove2", async (string code, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var h = await db.BusinessPlanHeaders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.BusinessPlanCode == code);
    if (h is null) return Results.NotFound(new { code });
    if (h.Status != "A2")
        return Results.BadRequest(new { error = $"Kế hoạch đang ở '{h.Status}' — chỉ bỏ duyệt được bản đã duyệt cấp 2 (A2)." });
    if (h.Version != "ACTUAL")
        return Results.BadRequest(new { error = $"Phiên bản '{h.Version}' — chỉ bỏ duyệt được bản THỰC TẾ (ACTUAL)." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    // Nguồn ghi lại đúng bộ này: trạng thái về "P", Version giữ "ACTUAL", năm cột mốc duyệt về NULL.
    h.Status = "P";
    h.Version = "ACTUAL";
    h.Approve1At = null; h.Approve1By = null;
    h.Approve2At = null; h.Approve2By = null;
    h.TimesPlan = null;
    h.LogLUDateTime = DateTime.Now; h.LogLUBy = who;
    await db.SaveChangesAsync();
    return Results.Ok(new { h.BusinessPlanCode, h.Status, h.Version,
        h.Approve1At, h.Approve1By, h.Approve2At, h.Approve2By, h.TimesPlan, h.LogLUDateTime, h.LogLUBy });
}).RequireAuthorization();


