app.MapPost("/api/docreqs", async (DocReqDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Cần DealerCode." });
    var vins = (dto.Cars ?? new()).Where(c => !string.IsNullOrWhiteSpace(c.Vin)).ToList();
    if (vins.Count == 0) return Results.BadRequest(new { error = "Cần ít nhất 1 VIN." });
    var dupe = vins.GroupBy(c => c.Vin.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"VIN {dupe.Key} bị trùng!" });
    var no = "DR" + DateTime.Now.ToString("yyMMddHHmmss");
    // 🔴 `TypeCRR` quyết định luồng duyệt (NORMAL duyệt 1 lần là xong) — nguồn có 3 đường tạo riêng
    //    (CreateHTC / CreateDealer / TCGCreateDealer) chỉ khác nhau ở loại này.
    var typeCRR = (dto.TypeCRR ?? "NORMAL").Trim().ToUpperInvariant();
    if (typeCRR is not ("NORMAL" or "SPECIAL" or "DEALER" or "DEALERTCG"))
        return Results.BadRequest(new { error = "TypeCRR = NORMAL | SPECIAL | DEALER | DEALERTCG." });
    var d = new DocReq { OrgId = t.OrgId, DocReqNo = no, DealerCode = dto.DealerCode.Trim().ToUpperInvariant(), TypeCRR = typeCRR, Status = "P", CreatedBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system" };
    db.DocReqs.Add(d); await db.SaveChangesAsync();
    foreach (var c in vins)
        db.DocReqCars.Add(new DocReqCar { OrgId = t.OrgId, DocReqId = d.Id, Vin = c.Vin.Trim().ToUpperInvariant(), ModelCode = c.ModelCode, ColorCode = c.ColorCode, EngineNo = c.EngineNo, AmountTotal = c.AmountTotal });
    await db.SaveChangesAsync();
    return Results.Ok(new { d.DocReqNo, d.DealerCode, cars = vins.Count, status = d.Status });
}).RequireAuthorization();

app.MapGet("/api/docreqs/{no}/cars", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var d = await db.DocReqs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DocReqNo == no);
    if (d is null) return Results.NotFound(new { no });
    var cars = await db.DocReqCars.Where(c => c.OrgId == t.OrgId && c.DocReqId == d.Id)
        .Select(c => new { c.Vin, c.ModelCode, c.ColorCode, c.EngineNo, c.AmountTotal, c.LetterRepresentationDate, c.LetterRepresentationNo, c.LoanSupportDay, c.DRDtlStatus, c.ApprovedDate1, c.ApprovedBy1, c.ApprovedDate2, c.ApprovedBy2, c.RejectDate, c.RejectBy, c.Remark }).ToListAsync();
    return Results.Ok(new { d.DocReqNo, d.Status, d.TypeCRR, d.CreatedBy, d.ApprovedBy1, d.ApprovedBy2, d.CancelDate, d.CancelBy, count = cars.Count, cars, total = cars.Sum(x => x.AmountTotal) });
}).RequireAuthorization();

// Sửa hàng loạt ngày/số tờ trình + số ngày hỗ trợ vay vốn theo VIN (port 1:1 FrmUpdateDocReq, 2010.HTC/Sales)
app.MapPost("/api/docreqs/{no}/edit-support", async (string no, DocReqSupportDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var d = await db.DocReqs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DocReqNo == no);
    if (d is null) return Results.NotFound(new { no });
    var rows = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.Vin)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Không có dữ liệu được thay đổi" });
    int updated = 0; var notFound = new List<string>();
    foreach (var r in rows)
    {
        var vin = r.Vin!.Trim().ToUpperInvariant();
        var c = await db.DocReqCars.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DocReqId == d.Id && x.Vin == vin);
        if (c is null) { notFound.Add(vin); continue; }
        c.LetterRepresentationDate = r.LetterRepresentationDate; c.LetterRepresentationNo = r.LetterRepresentationNo; c.LoanSupportDay = r.LoanSupportDay;
        updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { updated, notFound = notFound.Distinct().Take(20) });
}).RequireAuthorization();

// 🔴 DUYỆT CẤP 1 ở HEADER — `CarDocReqApprove1_New20181119` (Biz.HTC.WH.cs:82296-82380). Vào từ "P".
//    ⚠️ Luật rẽ nhánh theo LOẠI ĐỀ NGHỊ: `TypeCRR == "NORMAL"` ⇒ **nhảy thẳng "A2"** và ghi luôn
//    ApprovedDate2/By2 (đề nghị thường duyệt một lần là xong); loại khác chỉ lên "A1", còn phải
//    duyệt cấp 2 **theo TỪNG XE**. Port cũ có submit/complete phẳng — mất hẳn nhánh này.
app.MapPost("/api/docreqs/{no}/approve1", async (string no, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var d = await db.DocReqs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DocReqNo == no);
    if (d is null) return Results.NotFound(new { no });
    if (d.Status != "P") return Results.BadRequest(new { error = "Chỉ duyệt cấp 1 đề nghị đang chờ duyệt (P)." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    d.ApprovedDate1 = now; d.ApprovedBy1 = who;
    if (string.Equals(d.TypeCRR, "NORMAL", StringComparison.OrdinalIgnoreCase))
    { d.Status = "A2"; d.ApprovedDate2 = now; d.ApprovedBy2 = who; }
    else d.Status = "A1";
    // Dòng đi theo header ở bước này (nguồn duyệt cấp 2 vào từ "A1" của DÒNG).
    foreach (var c in await db.DocReqCars.Where(x => x.OrgId == t.OrgId && x.DocReqId == d.Id && x.DRDtlStatus == "P").ToListAsync())
        c.DRDtlStatus = d.Status;
    await db.SaveChangesAsync();
    return Results.Ok(new { d.DocReqNo, status = d.Status, d.TypeCRR, oneStep = d.Status == "A2" });
}).RequireAuthorization();

// 🔴 HUỶ CẢ ĐỀ NGHỊ — `CarDocReqListCancel_New20181119` (Biz.HTC.WH.cs:84912-85170).
// Khác hẳn huỷ từng xe: chỉ vào từ **"P"** (đề nghị chưa duyệt), và **lan trạng thái "C" xuống MỌI dòng**.
app.MapPost("/api/docreqs/{no}/cancel", async (string no, DocReqCarActionDto? dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var d = await db.DocReqs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DocReqNo == no);
    if (d is null) return Results.NotFound(new { no });
    if (d.Status != "P") return Results.BadRequest(new { error = "Chỉ huỷ được đề nghị đang chờ duyệt (P)." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";

    // 🔴 RBAC theo NGƯỜI TẠO, không theo đại lý ghi trên đề nghị: nguồn lấy `CreatedBy` → đại lý của
    //    người đó → `myCommon_CheckAccessDealerData(BUPattern, BUCode)`. Nguyên văn comment nguồn:
    //    "Đại lý được Hủy đề nghị do Đại lý tạo ra. Không được hủy đề nghị do HTC tạo hộ".
    //    ⚠️ MiniHTC chưa có tầng BUPattern/ability ⇒ tạm kiểm bằng chính người tạo; đã ghi nợ RBAC.
    if (!string.IsNullOrWhiteSpace(d.CreatedBy) && !string.Equals(d.CreatedBy, who, StringComparison.OrdinalIgnoreCase))
        return Results.BadRequest(new { error = $"Đề nghị do '{d.CreatedBy}' tạo — bạn không huỷ được đề nghị người khác tạo hộ." });

    var cars = await db.DocReqCars.Where(x => x.OrgId == t.OrgId && x.DocReqId == d.Id).ToListAsync();
    var vins = cars.Select(x => x.Vin).ToList();

    // Huỷ đề nghị NORMAL thì phải huỷ đề nghị SPECIAL của cùng xe TRƯỚC (nguồn kiểm từng VIN).
    if (string.Equals(d.TypeCRR, "NORMAL", StringComparison.OrdinalIgnoreCase))
    {
        var specialIds = db.DocReqs.Where(x => x.OrgId == t.OrgId && x.TypeCRR == "SPECIAL" && x.Id != d.Id).Select(x => x.Id);
        var blocked = await db.DocReqCars.Where(x => x.OrgId == t.OrgId && vins.Contains(x.Vin) && specialIds.Contains(x.DocReqId))
            .Select(x => x.Vin).FirstOrDefaultAsync();
        if (blocked != null)
            return Results.BadRequest(new { error = $"Xe {blocked} còn đề nghị loại đặc biệt — phải huỷ đề nghị đặc biệt trước." });
    }
    // Guard hạ nguồn: đề nghị giải chấp (ReqDMNo) và đề nghị hoá đơn (ReqIVNo).
    var dm = await db.RedeemRequestLines.Where(x => x.OrgId == t.OrgId && vins.Contains(x.VIN!)).Select(x => x.VIN).FirstOrDefaultAsync();
    if (dm != null) return Results.BadRequest(new { error = $"Xe {dm} đã có đề nghị giải chấp — không huỷ được đề nghị hồ sơ." });
    var iv = await db.RedeemInvoiceRequestLines.Where(x => x.OrgId == t.OrgId && vins.Contains(x.VIN!)).Select(x => x.VIN).FirstOrDefaultAsync();
    if (iv != null) return Results.BadRequest(new { error = $"Xe {iv} đã có đề nghị hoá đơn — không huỷ được đề nghị hồ sơ." });

    var now = DateTime.Now;
    d.Status = "C"; d.CancelDate = now; d.CancelBy = who;
    // Nguồn lan xuống MỌI dòng bằng một câu update (không lọc theo trạng thái dòng).
    foreach (var c in cars) c.DRDtlStatus = "C";

    // Nguồn gửi email thông báo khi đề nghị do ĐẠI LÝ tạo (`TypeCRR == DEALER`) — nhánh dễ bị bỏ sót.
    var mailed = false;
    if (string.Equals(d.TypeCRR, "DEALER", StringComparison.OrdinalIgnoreCase))
    {
        db.EmailSends.Add(new EmailSend
        {
            OrgId = t.OrgId,
            BatchNo = "DRCANCEL" + now.ToString("yyMMddHHmmss"),
            Email = "",
            EmailType = "DOCREQ_CANCEL",
            Subject = $"Huỷ đề nghị giấy tờ {d.DocReqNo}",
            Body = $"Đề nghị {d.DocReqNo} (đại lý {d.DealerCode}, {cars.Count} xe) đã bị huỷ bởi {who}." + (dto?.Remark is null ? "" : $" Lý do: {dto.Remark}"),
            DealerCode = d.DealerCode,
            Status = "0",   // hàng đợi — đúng cờ nguồn, chưa gửi
        });
        mailed = true;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { d.DocReqNo, status = d.Status, statusName = "Huỷ", carsCancelled = cars.Count, mailQueued = mailed });
}).RequireAuthorization();

// 🔴 DUYỆT CẤP 2 / TỪ CHỐI / HUỶ — nguồn thao tác theo **TỪNG XE**, không theo cả đề nghị:
//    `CarDocReqDtlApprove2_New20181119` (82492) · `CarDocReqDtlReject_New20181119` (83426) ·
//    `CarDocReqDtlCancel_New20210223` (82986).
//    ⚠️ TWIN: WS 32-bit gọi bản Cancel `_New20181119`, còn **`TERP.WSHTC.64` gọi `_New20210223`**
//    (bản 64-bit là bản CI/CD đang chạy) ⇒ port theo `_New20210223`.
app.MapPost("/api/docreqs/{no}/cars/{vin}/{action}", async (string no, string vin, string action, DocReqCarActionDto? dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    if (action is not ("approve2" or "reject" or "cancel"))
        return Results.BadRequest(new { error = "action = approve2|reject|cancel" });
    no = no.Trim().ToUpperInvariant(); vin = vin.Trim().ToUpperInvariant();
    var d = await db.DocReqs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DocReqNo == no);
    if (d is null) return Results.NotFound(new { no });
    var c = await db.DocReqCars.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DocReqId == d.Id && x.Vin == vin);
    if (c is null) return Results.NotFound(new { no, vin });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;

    if (action == "approve2")
    {
        // 🔴 Luồng TCG dùng hàm RIÊNG `CarDocReqTCGDtlApprove2_New20181119` (Biz.HTC.WH.cs:82847-82931):
        //    vào từ **"P"** (không phải "A1") rồi lên thẳng "A2", và ghi **CẢ BỐN** cột duyệt cùng lúc —
        //    duyệt một lần là qua cả hai cấp.
        //    ⚠️ Nợ cấu trúc: nguồn để luồng TCG ở **bảng RIÊNG** `Car_DocReqTCGList`/`Car_DocReqTCGDtl`
        //    (cột trạng thái `DRTCGDtlStatus`), MiniHTC đang gộp chung và phân biệt bằng `TypeCRR`.
        if (string.Equals(d.TypeCRR, "DEALERTCG", StringComparison.OrdinalIgnoreCase))
        {
            if (c.DRDtlStatus != "P") return Results.BadRequest(new { error = $"Xe {vin} (luồng TCG) phải đang chờ duyệt (P)." });
            c.DRDtlStatus = "A2";
            c.ApprovedDate1 = now; c.ApprovedBy1 = who; c.ApprovedDate2 = now; c.ApprovedBy2 = who;
            await db.SaveChangesAsync();
            return Results.Ok(new { no, vin, status = c.DRDtlStatus, statusName = "Duyệt cấp 2 (TCG, một bước)" });
        }
        // Nguồn: `strRequestStatusListToCheck = Stage.Approved1` ⇒ CHỈ từ "A1".
        if (c.DRDtlStatus != "A1") return Results.BadRequest(new { error = $"Xe {vin} phải ở trạng thái duyệt cấp 1 (A1)." });
        c.DRDtlStatus = "A2"; c.ApprovedDate2 = now; c.ApprovedBy2 = who;
        await db.SaveChangesAsync();
        return Results.Ok(new { no, vin, status = c.DRDtlStatus, statusName = "Duyệt cấp 2" });
    }

    // Hai nhánh còn lại đều yêu cầu HEADER thuộc "P,A1,A2,F" (nguồn guard cả hai tầng).
    if (d.Status is not ("P" or "A1" or "A2" or "F"))
        return Results.BadRequest(new { error = $"Đề nghị đang ở trạng thái '{d.Status}' — không thao tác được." });

    if (action == "reject")
    {
        // 🔴 Nguồn cho từ chối CHỈ từ "A2" — tức là **từ chối SAU khi đã duyệt cấp 2**, không phải trước.
        if (c.DRDtlStatus != "A2") return Results.BadRequest(new { error = $"Xe {vin} chỉ từ chối được sau khi đã duyệt cấp 2 (A2)." });
        c.DRDtlStatus = "R"; c.RejectDate = now; c.RejectBy = who; c.Remark = dto?.Remark;
        await db.SaveChangesAsync();
        return Results.Ok(new { no, vin, status = c.DRDtlStatus, statusName = "Từ chối" });
    }

    // cancel: dòng phải thuộc "A1,A2" + 3 ràng buộc hạ nguồn của nguồn.
    if (c.DRDtlStatus is not ("A1" or "A2"))
        return Results.BadRequest(new { error = $"Xe {vin} chỉ huỷ được khi đang ở A1 hoặc A2." });
    // (1) Đã phát hành hoá đơn HTC hoặc TCG cho xe ⇒ cấm huỷ.
    if (await db.InvoiceLines.AnyAsync(x => x.OrgId == t.OrgId && x.Vin == vin))
        return Results.BadRequest(new { error = $"Xe {vin} đã có hoá đơn — không huỷ được đề nghị hồ sơ." });
    // (2) Đã có đề nghị giải chấp (`ReqDMNo`) ⇒ cấm.
    if (await db.RedeemRequestLines.AnyAsync(x => x.OrgId == t.OrgId && x.VIN == vin))
        return Results.BadRequest(new { error = $"Xe {vin} đã có đề nghị giải chấp — không huỷ được." });
    // (3) Xe đang nằm trong một đề nghị loại SPECIAL khác ⇒ cấm.
    var specialIds = db.DocReqs.Where(x => x.OrgId == t.OrgId && x.TypeCRR == "SPECIAL" && x.Id != d.Id).Select(x => x.Id);
    if (await db.DocReqCars.AnyAsync(x => x.OrgId == t.OrgId && x.Vin == vin && specialIds.Contains(x.DocReqId)))
        return Results.BadRequest(new { error = $"Xe {vin} đang thuộc một đề nghị loại đặc biệt khác — không huỷ được." });
    c.DRDtlStatus = "C"; c.Remark = dto?.Remark;
    await db.SaveChangesAsync();
    return Results.Ok(new { no, vin, status = c.DRDtlStatus, statusName = "Huỷ" });}).RequireAuthorization();

// ===== Thiết lập hóa đơn theo model (InvoiceSetup — port 1:1 FrmMst_InvoiceSetup, 2010.HTC/Admin/Product) =====
app.MapGet("/api/invoicesetups", async (AppDbContext db, ITenantContext t, string? active, string? model) =>
{
    var q = db.InvoiceSetups.Where(s => s.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(active)) q = q.Where(s => s.FlagActive == active);
    if (!string.IsNullOrWhiteSpace(model)) q = q.Where(s => s.ModelCode == model);
    var items = await q.OrderByDescending(s => s.Id).Take(500).Select(s => new { s.ModelCode, s.FlagInvoiceHTMV, s.FlagInvoiceTCG, s.FlagActive, s.LogLUDateTime, s.LogLUBy }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/invoicesetups", async (InvoiceSetupDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.ModelCode)) return Results.BadRequest(new { error = "Chưa nhập model." });
    var md = dto.ModelCode.Trim().ToUpperInvariant();
    var ex = await db.InvoiceSetups.FirstOrDefaultAsync(s => s.OrgId == t.OrgId && s.ModelCode == md);
    if (ex is not null) { ex.FlagInvoiceHTMV = dto.FlagInvoiceHTMV == "1" ? "1" : "0"; ex.FlagInvoiceTCG = dto.FlagInvoiceTCG == "1" ? "1" : "0"; ex.FlagActive = "1"; await db.SaveChangesAsync(); return Results.Ok(new { ex.ModelCode, updated = true }); }
    var s2 = new InvoiceSetup { OrgId = t.OrgId, ModelCode = md, FlagInvoiceHTMV = dto.FlagInvoiceHTMV == "1" ? "1" : "0", FlagInvoiceTCG = dto.FlagInvoiceTCG == "1" ? "1" : "0", FlagActive = "1" };
    db.InvoiceSetups.Add(s2); await db.SaveChangesAsync();
    return Results.Ok(new { s2.ModelCode, updated = false });
}).RequireAuthorization();

// ===== #185 THIẾT LẬP HOÁ ĐƠN theo model — cụm `Mst_InvoiceSetup_*` =====
// Nguồn: `TERP.BizHTC/DataWH/Biz.HTC.WH.cs` (csproj 272) — `_CreateMulti` (206588), `_Update` (207257).
// BƯỚC 3B: hàm `_Update` bắt đầu **KHÁC DÒNG** (laptop 207257 / máy 150 207262) — căn theo MỐC HÀM
//   (luật #156), vùng 160 dòng md5 `5cdaec42` KHỚP. Đã liệt kê ranh giới hàm: 207257 → 207415.
// 🔴 TWIN: cụm này **CHỈ có ở WS 64-bit** (`_CreateMulti` · `_Get` · `_Update`); WS 32-bit **không có hàm nào**.
//
// 🔴 Cách tìm ra: danh sách 36 hàm field-mask (#184). Đây là hàm thứ BA được port.
//    Port cũ chỉ có POST upsert đơn — **ghi CẢ HAI cờ mỗi lần gọi**, tức rộng hơn nguồn.
//
// 🔴 `_CreateMulti` — tạo HÀNG LOẠT, ba guard mỗi dòng:
//    · `Mst_InvoiceSetup_CheckDB(..., Flag.No)` — model **CHƯA có** thiết lập (chặn trùng);
//    · `Mst_CarModel_CheckDB_New20210604(..., Flag.Yes)` — model phải TỒN TẠI trong master xe;
//    · hai cờ phải là **đúng "0" hoặc "1"**, rỗng cũng là lỗi
//      (`CreateMulti_InvalidFlagInvoiceHTMV` / `_InvalidFlagInvoiceTCG`).
//      ⚠️ Port cũ dùng `dto.X == "1" ? "1" : "0"` ⇒ **nuốt mọi giá trị rác thành "0"** thay vì báo lỗi.
app.MapPost("/api/invoicesetups/create-multi", async (InvoiceSetupMultiDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var rows = (dto.Items ?? new()).Where(x => !string.IsNullOrWhiteSpace(x.ModelCode)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Chưa có dòng thiết lập nào." });   // CreateMulti_TableBlank
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    var built = new List<InvoiceSetup>();
    foreach (var r in rows)
    {
        var md = r.ModelCode!.Trim().ToUpperInvariant();
        if (await db.InvoiceSetups.AnyAsync(s => s.OrgId == t.OrgId && s.ModelCode == md))
            return Results.BadRequest(new { error = $"Model {md} đã có thiết lập hoá đơn.", modelCode = md });
        if (!await db.CarModelStds.AnyAsync(m => m.OrgId == t.OrgId && m.ModelCode == md))
            return Results.BadRequest(new { error = $"Model {md} không tồn tại trong danh mục xe.", modelCode = md });
        // Hai cờ PHẢI là "0" hoặc "1" — rỗng/giá trị lạ đều là LỖI, không tự quy về "0".
        if (r.FlagInvoiceHTMV is not ("0" or "1"))
            return Results.BadRequest(new { error = $"Model {md}: cờ hoá đơn HTMV phải là \"0\" hoặc \"1\".", modelCode = md });
        if (r.FlagInvoiceTCG is not ("0" or "1"))
            return Results.BadRequest(new { error = $"Model {md}: cờ hoá đơn TCG phải là \"0\" hoặc \"1\".", modelCode = md });
        built.Add(new InvoiceSetup { OrgId = t.OrgId, ModelCode = md,
            FlagInvoiceHTMV = r.FlagInvoiceHTMV!, FlagInvoiceTCG = r.FlagInvoiceTCG!,
            FlagActive = "1", CreatedAt = now, LogLUDateTime = now, LogLUBy = who });
    }
    db.InvoiceSetups.AddRange(built);
    await db.SaveChangesAsync();
    return Results.Ok(new { created = built.Count, models = built.Select(x => x.ModelCode) });
}).RequireAuthorization();

// 🔴 `_Update` (207257) — FIELD-MASK hai cờ:
//    `bUpd_FlagInvoiceHTMV = mask.Contains("Mst_InvoiceSetup.FlagInvoiceHTMV".ToUpper())`
//    `bUpd_FlagInvoiceTCG  = mask.Contains("Mst_InvoiceSetup.FlagInvoiceTCG".ToUpper())`
//    Chỉ cờ có trong mask mới được ghi; `LogLUDateTime`/`LogLUBy` **luôn** ghi.
//    Guard duy nhất: `Mst_InvoiceSetup_CheckDB(..., Flag.Yes)` — bản ghi phải tồn tại.
//    ⚠️ **KHÔNG có guard theo cột** ở lệnh này (khác #184) — mask chỉ chọn cột, không kéo theo kiểm tra.
// ⚠️ LỆCH CÓ CHỦ ĐÍCH: nguồn ghi `LogLUDateTime` với format **"yyyyMMddHH:mm:ss"** (thiếu dấu gạch/khoảng
//    trắng) — toàn hệ dùng "yyyy-MM-dd HH:mm:ss" ở **671** chỗ, format kia chỉ **10** chỗ ⇒ lỗi gõ của nguồn,
//    không phải quy ước. Ghi mốc bằng `DateTime` chuẩn (luật `C0-ducentesimustricesimussecundus`).
app.MapPost("/api/invoicesetups/{model}/update", async (string model, InvoiceSetupUpdateDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    model = model.Trim().ToUpperInvariant();
    var s = await db.InvoiceSetups.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ModelCode == model);
    if (s is null) return Results.NotFound(new { model });

    var mask = (dto.FtColsUpd ?? "").ToUpperInvariant();
    var updHTMV = mask.Contains("MST_INVOICESETUP.FLAGINVOICEHTMV");
    var updTCG = mask.Contains("MST_INVOICESETUP.FLAGINVOICETCG");

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    if (updHTMV) s.FlagInvoiceHTMV = (dto.FlagInvoiceHTMV ?? "").Trim();
    if (updTCG) s.FlagInvoiceTCG = (dto.FlagInvoiceTCG ?? "").Trim();
    s.LogLUDateTime = DateTime.Now; s.LogLUBy = who;
    await db.SaveChangesAsync();
    return Results.Ok(new { s.ModelCode, updatedHTMV = updHTMV, updatedTCG = updTCG,
        s.FlagInvoiceHTMV, s.FlagInvoiceTCG, s.LogLUDateTime, s.LogLUBy });
}).RequireAuthorization();

app.MapPost("/api/invoicesetups/{model}/toggle", async (string model, AppDbContext db, ITenantContext t) =>
{
    model = model.Trim().ToUpperInvariant();
    var s = await db.InvoiceSetups.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ModelCode == model);
    if (s is null) return Results.NotFound(new { model });
    s.FlagActive = s.FlagActive == "1" ? "0" : "1";
    await db.SaveChangesAsync();
    return Results.Ok(new { s.ModelCode, flagActive = s.FlagActive });
}).RequireAuthorization();

// ===== Ngưỡng tồn kho bán hàng (SalesInventoryThreshold — port 1:1 FrmMstSalesInventoryThreshold, 2010.HTC/Admin/Product) =====
app.MapGet("/api/salesinvthresholds", async (AppDbContext db, ITenantContext t, string? dealer, string? model, string? active) =>
{
    var q = db.SalesInventoryThresholds.Where(x => x.OrgId == t.OrgId);
