})).RequireAuthorization();

app.MapGet("/api/bankgrts", async (AppDbContext db, ITenantContext t, string? dealer, string? bank, string? grtNo, string? status, string? type, string? settled,
    string? bankAbilityPattern, string? buAbilityPattern) =>
{
    var q = db.BankGuarantees.Where(g => g.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(g => g.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(bank)) q = q.Where(g => g.BankCode == bank);
    if (!string.IsNullOrWhiteSpace(grtNo)) q = q.Where(g => g.GuaranteeNo.Contains(grtNo!) || g.BankGuaranteeNo.Contains(grtNo!));
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(g => g.Status == status);
    if (!string.IsNullOrWhiteSpace(type)) q = q.Where(g => g.GuaranteeType == type);
    if (!string.IsNullOrWhiteSpace(settled)) q = q.Where(g => g.FlagSettled == settled);
    // 🔴 RBAC của cổng ngân hàng (`TERP.BizBank/Report.cs:703-713`) — **RẼ NHÁNH THEO VAI TRÒ**:
    //   GuaranteeType "0" (NH GIÁM SÁT)  ⇒ lọc `BankCodeMonitor like @strAbilityOfBank`
    //   GuaranteeType "1" (NH PHÁT HÀNH) ⇒ lọc `BankBUCode      like @strAbilityOfUser`
    // Port cũ KHÔNG có tầng lọc này ⇒ một ngân hàng đăng nhập **thấy bảo lãnh của mọi ngân hàng khác**.
    // Truyền pattern rỗng = xem tất cả (người dùng nội bộ HTC).
    if (!string.IsNullOrWhiteSpace(bankAbilityPattern))
    {
        var pm = bankAbilityPattern!.Trim().Replace("%", "");
        q = q.Where(g => g.GuaranteeType != "0" || g.BankCodeMonitor.Contains(pm));
    }
    if (!string.IsNullOrWhiteSpace(buAbilityPattern))
    {
        var pu = buAbilityPattern!.Trim().Replace("%", "");
        q = q.Where(g => g.GuaranteeType != "1" || (g.BankBUCode != null && g.BankBUCode.Contains(pu)));
    }
    var items = await q.OrderByDescending(g => g.Id).Take(500).Select(g => new
    {
        g.GuaranteeNo, g.DealerCode, g.BankCode, g.BankGuaranteeNo, g.GuaranteeType, g.Term, g.DateOpen, g.DateExpired, g.DateEnd, g.DateRecieveGrtRoot, g.TotalAmount, g.Status, g.FlagSettled, g.CreatedAt, g.ApprovedAt,
        cars = db.BankGuaranteeDtls.Count(c => c.OrgId == t.OrgId && c.GuaranteeId == g.Id)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/bankgrts", async (BankGrtDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Chưa chọn đại lý." });
    if (string.IsNullOrWhiteSpace(dto.BankCode)) return Results.BadRequest(new { error = "Chưa chọn ngân hàng bảo lãnh." });
    var cars = (dto.Cars ?? new()).Where(c => !string.IsNullOrWhiteSpace(c.VIN)).ToList();
    if (cars.Count == 0) return Results.BadRequest(new { error = "Chưa có chi tiết xe bảo lãnh." });
    var dupe = cars.GroupBy(c => c.VIN.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"VIN {dupe.Key} bị trùng!" });
    // 🔴 #186 SỬA BUG DỮ LIỆU: `GuaranteeType` KHÔNG phải cờ 0/1 mà là **loại bảo lãnh**
    //    (`TConst.GuaranteeType`, Const.Main.cs:1139): **"BL"** bảo lãnh · **"LCTC"** LC trả chậm
    //    · **"LCUP"** LC Upas · **"EPLC"**. Port cũ ép `dto.GuaranteeType == "1" ? "1" : "0"`
    //    ⇒ MỌI loại bảo lãnh đều thành "0"/"1" và guard ở #161 (`grtType == "BL"` ⇒ BANKBL,
    //    `LCTC`/`LCUP` ⇒ BANKLC) **KHÔNG BAO GIỜ khớp** — bug câm LIÊN CỤM.
    var gtIn = (dto.GuaranteeType ?? "").Trim().ToUpperInvariant();
    if (gtIn is not ("BL" or "LCTC" or "LCUP" or "EPLC"))
        return Results.BadRequest(new { error = "Loại bảo lãnh phải là BL | LCTC | LCUP | EPLC." });
    var gtype = gtIn;
    // 🔴 `LCUP` BẮT BUỘC có số ngày trả chậm >= 0 (`_InvalidNumberOfDaysDeferredPayment`).
    if (gtype == "LCUP" && (dto.NumberOfDaysDeferredPayment is null || dto.NumberOfDaysDeferredPayment < 0))
        return Results.BadRequest(new { error = "Bảo lãnh LC Upas (LCUP) phải có số ngày trả chậm >= 0." });
    var no = "BLNH" + DateTime.Now.ToString("yyMMddHHmmss");
    var g2 = new BankGuarantee
    {
        OrgId = t.OrgId, GuaranteeNo = no, DealerCode = dto.DealerCode.Trim(), BankCode = dto.BankCode.Trim(),
        NumberOfDaysDeferredPayment = dto.NumberOfDaysDeferredPayment,
        BankGuaranteeNo = dto.BankGuaranteeNo ?? "", GuaranteeType = gtype, Term = dto.Term,
        BankCodeMonitor = dto.BankCodeMonitor ?? "", BankBUCode = dto.BankBUCode,
        DateOpen = dto.DateOpen, DateExpired = dto.DateExpired, DateEnd = dto.DateEnd, Remark = dto.Remark ?? "",
        // Nguồn tạo ở "P" (TConst.Stage.Pending) — BizHTC.zTemp.cs:14542.
        Status = "P", FlagSettled = "0", TotalAmount = cars.Sum(c => c.GrtValue)
    };
    db.BankGuarantees.Add(g2); await db.SaveChangesAsync();
    foreach (var c in cars)
        db.BankGuaranteeDtls.Add(new BankGuaranteeDtl { OrgId = t.OrgId, GuaranteeId = g2.Id, VIN = c.VIN.Trim().ToUpperInvariant(), GrtValue = c.GrtValue, GrtPercent = c.GrtPercent, DiscountValue = c.DiscountValue, DiscountPercent = c.DiscountPercent, DateStart = c.DateStart, DateWarning = c.DateWarning, DateExpired = c.DateExpired,
            GuaranteeDetailStatus = "P" });   // nguồn tạo dòng ở Pending (BizHTC.zTemp.cs:14573)
    await db.SaveChangesAsync();
    return Results.Ok(new { g2.GuaranteeNo, cars = cars.Count, totalAmount = g2.TotalAmount });
}).RequireAuthorization();

app.MapGet("/api/bankgrts/{no}/cars", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var g = await db.BankGuarantees.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.GuaranteeNo == no);
    if (g is null) return Results.NotFound(new { no });
    var cars = await db.BankGuaranteeDtls.Where(c => c.OrgId == t.OrgId && c.GuaranteeId == g.Id)
        .Select(c => new { c.VIN, c.GrtValue, c.GrtPercent, c.DiscountValue, c.DiscountPercent, c.DateStart, c.DateWarning, c.DateExpired, c.GuaranteeDetailStatus, c.DateEnd, c.DeferredPaymentDays, c.FlagDtlDiscount }).ToListAsync();
    return Results.Ok(new { g.GuaranteeNo, g.DealerCode, g.BankCode, g.Status, g.FlagSettled, g.TotalAmount, count = cars.Count, cars });
}).RequireAuthorization();

// Sửa bảo lãnh — cập nhật ngày hết hạn + ngày kết thúc theo VIN (port 1:1 FrmEditGrtExpiredDate, TCMotor/Sales/Payment).
app.MapPost("/api/bankgrts/{no}/edit-expiry", async (string no, GrtExpiryEditDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var g = await db.BankGuarantees.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.GuaranteeNo == no);
    if (g is null) return Results.NotFound(new { no });
    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.VIN)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Không có xe thay đổi." });
    foreach (var l in lines)
        if (l.DateExpired.HasValue && l.DateEnd.HasValue && l.DateEnd < l.DateExpired)
            return Results.BadRequest(new { error = $"VIN {l.VIN}: ngày kết thúc phải >= ngày hết hạn." });
    var cars = await db.BankGuaranteeDtls.Where(c => c.OrgId == t.OrgId && c.GuaranteeId == g.Id).ToListAsync();
    var byVin = cars.ToDictionary(c => c.VIN.ToUpperInvariant(), c => c);
    int updated = 0; var notFound = new List<string>();
    foreach (var l in lines)
    {
        var key = l.VIN!.Trim().ToUpperInvariant();
        if (!byVin.TryGetValue(key, out var c)) { notFound.Add(l.VIN!.Trim()); continue; }
        if (l.DateExpired.HasValue) c.DateExpired = l.DateExpired;
        if (l.DateEnd.HasValue) c.DateEnd = l.DateEnd;
        updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { updated, notFound = notFound.Distinct().Take(20) });
}).RequireAuthorization();

// Cập nhật giá trị bảo lãnh theo VIN (port 1:1 FrmEditGrtValue, 2010.HTC).
app.MapPost("/api/bankgrts/{no}/edit-value", async (string no, GrtValueEditDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var g = await db.BankGuarantees.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.GuaranteeNo == no);
    if (g is null) return Results.NotFound(new { no });
    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.VIN)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Không có xe thay đổi." });
    if (lines.Any(l => l.GrtValue < 0)) return Results.BadRequest(new { error = "Giá trị bảo lãnh không được âm." });
    var cars = await db.BankGuaranteeDtls.Where(c => c.OrgId == t.OrgId && c.GuaranteeId == g.Id).ToListAsync();
    var byVin = cars.ToDictionary(c => c.VIN.ToUpperInvariant(), c => c);
    int updated = 0; var notFound = new List<string>();
    foreach (var l in lines)
    {
        var key = l.VIN!.Trim().ToUpperInvariant();
        if (!byVin.TryGetValue(key, out var c)) { notFound.Add(l.VIN!.Trim()); continue; }
        c.GrtValue = l.GrtValue; updated++;
    }
    // cập nhật lại tổng giá trị bảo lãnh trên header
    g.TotalAmount = cars.Sum(c => c.GrtValue);
    await db.SaveChangesAsync();
    return Results.Ok(new { updated, totalAmount = g.TotalAmount, notFound = notFound.Distinct().Take(20) });
}).RequireAuthorization();

// Sửa bảo lãnh: ngày hiệu lực + giá trị + cờ chiết khấu theo VIN (port 1:1 FrmEditGrt, 2010.HTC) — khớp btnApply_Click gốc (chỉ dòng EDIT status mới gửi).
app.MapPost("/api/bankgrts/{no}/edit-start", async (string no, GrtStartEditDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var g = await db.BankGuarantees.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.GuaranteeNo == no);
    if (g is null) return Results.NotFound(new { no });
    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.VIN)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Không có dữ liệu được thay đổi" });
    var cars = await db.BankGuaranteeDtls.Where(c => c.OrgId == t.OrgId && c.GuaranteeId == g.Id).ToListAsync();
    var byVin = cars.ToDictionary(c => c.VIN.ToUpperInvariant(), c => c);
    int updated = 0; var notFound = new List<string>();
    foreach (var l in lines)
    {
        var key = l.VIN!.Trim().ToUpperInvariant();
        if (!byVin.TryGetValue(key, out var c)) { notFound.Add(l.VIN!.Trim()); continue; }
        if (l.DateStart.HasValue) c.DateStart = l.DateStart;
        if (l.DateExpired.HasValue) c.DateExpired = l.DateExpired;
        if (l.GrtValue.HasValue) c.GrtValue = l.GrtValue.Value;
        c.FlagDtlDiscount = l.FlagDtlDiscount;
        updated++;
    }
    if (lines.Any(l => l.GrtValue.HasValue)) g.TotalAmount = cars.Sum(c => c.GrtValue);
    await db.SaveChangesAsync();
    return Results.Ok(new { updated, notFound = notFound.Distinct().Take(20) });
}).RequireAuthorization();

// Cập nhật số ngày trả chậm (TCLC) theo VIN (port 1:1 FrmEditGrtSoNgayTCLC, 2010.HTC).
app.MapPost("/api/bankgrts/{no}/edit-deferred", async (string no, GrtDeferredEditDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var g = await db.BankGuarantees.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.GuaranteeNo == no);
    if (g is null) return Results.NotFound(new { no });
    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.VIN)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Không có xe thay đổi." });
    if (lines.Any(l => l.DeferredPaymentDays < 0)) return Results.BadRequest(new { error = "Số ngày trả chậm không được âm." });
    var cars = await db.BankGuaranteeDtls.Where(c => c.OrgId == t.OrgId && c.GuaranteeId == g.Id).ToListAsync();
    var byVin = cars.ToDictionary(c => c.VIN.ToUpperInvariant(), c => c);
    int updated = 0; var notFound = new List<string>();
    foreach (var l in lines)
    {
        var key = l.VIN!.Trim().ToUpperInvariant();
        if (!byVin.TryGetValue(key, out var c)) { notFound.Add(l.VIN!.Trim()); continue; }
        c.DeferredPaymentDays = l.DeferredPaymentDays; updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { updated, notFound = notFound.Distinct().Take(20) });
}).RequireAuthorization();

// Cập nhật hàng loạt "Ngày nhận LC/BL gốc" theo số bảo lãnh NH (port 1:1 FrmEditDateRecieveGrtRoot/FrmUpdateGrtDate, 2010.HTC/Sales/Payment).
// Khớp gốc: khóa theo BankGuaranteeNo (không phải VIN) — 1 dòng lưới = 1 bảo lãnh; cảnh báo (không chặn) nếu BankGuaranteeNo trùng nhiều bản ghi, áp dụng cho tất cả bản trùng.
app.MapPost("/api/bankgrts/date-recieve-root", async (GrtDateRecieveRootDto dto, AppDbContext db, ITenantContext t) =>
{
    var rows = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.BankGuaranteeNo)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Không có dữ liệu được thay đổi." });
    if (rows.Any(r => r.DateRecieveGrtRoot is null)) return Results.BadRequest(new { error = "Ngày nhận LC/BL gốc không được trống!" });
    int updated = 0; var notFound = new List<string>();
    foreach (var r in rows)
    {
        var no = r.BankGuaranteeNo!.Trim();
        var matches = await db.BankGuarantees.Where(g => g.OrgId == t.OrgId && g.BankGuaranteeNo == no).ToListAsync();
        if (matches.Count == 0) { notFound.Add(no); continue; }
        foreach (var g in matches) { g.DateRecieveGrtRoot = r.DateRecieveGrtRoot; updated++; }
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { updated, notFound = notFound.Distinct().Take(20) });
}).RequireAuthorization();

app.MapPost("/api/bankgrts/{no}/{action}", async (
    string no, string action, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user, int? termActualQ, string? remark) =>
{
    if (action is not ("approve" or "reject" or "settle")) return Results.BadRequest(new { error = "action = approve|reject|settle" });
    no = no.Trim().ToUpperInvariant();
    var g = await db.BankGuarantees.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.GuaranteeNo == no);
    if (g is null) return Results.NotFound(new { no });
    if (action is "approve" or "reject")
    {
        if (g.Status != "P") return Results.BadRequest(new { error = $"Bảo lãnh không ở trạng thái chờ duyệt (đang: {g.Status})." });
        if (action == "approve")
        {
            // Guard của nguồn (Biz.HTC.WH.My.cs:10600-10630): CẢ kỳ hạn đăng ký LẪN kỳ hạn thực tế
            // phải >= WarningPeriod, mỗi cái một mã lỗi riêng.
            var termActual = termActualQ ?? g.TermActual;
            if (g.Term < BankGrtWarningPeriod)
                return Results.BadRequest(new { error = $"Kỳ hạn bảo lãnh phải >= {BankGrtWarningPeriod} (đang: {g.Term})." });
            if (termActual < BankGrtWarningPeriod)
                return Results.BadRequest(new { error = $"Kỳ hạn thực tế phải >= {BankGrtWarningPeriod} (đang: {termActual})." });
            g.Status = "A"; g.ApprovedAt = DateTime.Now;
            g.TermActual = termActual;
            // Giá trị DẪN XUẤT của nguồn — không phải nhập tay.
            g.TermWarning = termActual - BankGrtWarningPeriod;
        }
        else
        {
            g.Status = "R";
            if (!string.IsNullOrWhiteSpace(remark)) g.RemarkReject = remark!.Trim();
        }
        g.ApprovedBy = user.Identity?.Name ?? "system";

        // 🔴 Nguồn LAN trạng thái xuống TẤT CẢ dòng chi tiết (Biz.HTC.WH.My.cs:10675-10681).
        var dtls = await db.BankGuaranteeDtls.Where(x => x.OrgId == t.OrgId && x.GuaranteeId == g.Id).ToListAsync();
        foreach (var d in dtls) d.GuaranteeDetailStatus = g.Status;
    }
    else // settle = tất toán
    {
        if (g.Status != "A") return Results.BadRequest(new { error = "Chỉ tất toán bảo lãnh đã duyệt." });
        if (g.FlagSettled == "1") return Results.BadRequest(new { error = "Bảo lãnh đã tất toán." });
        g.FlagSettled = "1"; g.SettledAt = DateTime.Now;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { g.GuaranteeNo, g.Status, g.FlagSettled, g.TermActual, g.TermWarning, g.RemarkReject });
}).RequireAuthorization();

// ===== Lệnh xuất xe - NH xác nhận nhận xe (BankDeliveryOrder — port 1:1 FrmBankDO, cụm Bank) =====
app.MapGet("/api/bankdos", async (AppDbContext db, ITenantContext t, string? dealer, string? doNo, string? status,
    string? bankAbilityPattern, string? buAbilityPattern) =>
{
    var q = db.BankDeliveryOrders.Where(d => d.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(d => d.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(doNo)) q = q.Where(d => d.DONo.Contains(doNo!) || d.SOCode.Contains(doNo!));
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(d => d.Status == status);
    // 🔴 RBAC cổng ngân hàng — RẼ NHÁNH THEO VAI TRÒ (TERP.BizBank/Report.cs:282-294).
    // Port cũ KHÔNG có tầng lọc ⇒ ngân hàng đăng nhập thấy DO của mọi ngân hàng khác.
    if (!string.IsNullOrWhiteSpace(bankAbilityPattern))
    { var pm = bankAbilityPattern!.Trim().Replace("%", ""); q = q.Where(d => d.GuaranteeType != "0" || d.BankCodeMonitor.Contains(pm)); }
    if (!string.IsNullOrWhiteSpace(buAbilityPattern))
    { var pu = buAbilityPattern!.Trim().Replace("%", ""); q = q.Where(d => d.GuaranteeType != "1" || (d.BankBUCode != null && d.BankBUCode.Contains(pu))); }
    var items = await q.OrderByDescending(d => d.Id).Take(500).Select(d => new
    {
        d.DONo, d.DealerCode, d.SOCode, d.Status, d.CreatedAt, d.ConfirmedAt,
        d.BankCode, d.BankCodeMonitor, d.BankBUCode, d.GuaranteeType,
        cars = db.BankDoCars.Count(c => c.OrgId == t.OrgId && c.DeliveryOrderId == d.Id),
        confirmed = db.BankDoCars.Count(c => c.OrgId == t.OrgId && c.DeliveryOrderId == d.Id && c.ConfirmStatus == "1")
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/bankdos", async (BankDoDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Chưa chọn đại lý." });
    var cars = (dto.Cars ?? new()).Where(c => !string.IsNullOrWhiteSpace(c.VIN)).ToList();
    if (cars.Count == 0) return Results.BadRequest(new { error = "Chưa có xe trên lệnh xuất." });
    var dupe = cars.GroupBy(c => c.VIN.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"VIN {dupe.Key} bị trùng!" });
    var no = "DO" + DateTime.Now.ToString("yyMMddHHmmss");
    var d2 = new BankDeliveryOrder { OrgId = t.OrgId, DONo = no, BankCode = dto.BankCode ?? "", BankCodeMonitor = dto.BankCodeMonitor ?? "", BankBUCode = dto.BankBUCode, GuaranteeType = (dto.GuaranteeType ?? "").Trim().ToUpperInvariant(), DealerCode = dto.DealerCode.Trim(), SOCode = dto.SOCode ?? "", Status = "Open" };
    db.BankDeliveryOrders.Add(d2); await db.SaveChangesAsync();
    foreach (var c in cars)
        db.BankDoCars.Add(new BankDoCar { OrgId = t.OrgId, DeliveryOrderId = d2.Id, VIN = c.VIN.Trim().ToUpperInvariant(), CarId = c.CarId ?? "", BankGrtNo = c.BankGrtNo ?? "", SpecCode = c.SpecCode ?? "", ColorCode = c.ColorCode ?? "", DeliveryExpectedDate = c.DeliveryExpectedDate, DeliveryOutDate = c.DeliveryOutDate, ConfirmStatus = "0" });
    await db.SaveChangesAsync();
    return Results.Ok(new { d2.DONo, cars = cars.Count });
}).RequireAuthorization();

