// ===== Gán VÙNG THỊ TRƯỜNG cho đại lý (Mst_Dealer_UpdateMRKAMCode — port 1:1
// `Mst_Dealer_UpdateMRKAMCode_New20181115`, 2010.HTC BizHTC.Marketing.cs:12035).
// TWIN: WSHTC.cs:37369 và WSHTC.64:50350. =====
// Nguồn chỉ ghi ĐÚNG MỘT cột `MRKAMCode` của `Mst_Dealer` (alColumnEffective chỉ có cột này),
// sau khi kiểm đại lý tồn tại và vùng thị trường tồn tại (`MRK_Mst_AreaMarket_CheckDB`).
app.MapPost("/api/dealers/update-mrkamcode", async (DealerMrkamCodeDto dto, AppDbContext db, ITenantContext t) =>
{
    var dealer = (dto.DealerCode ?? "").Trim();
    var code = (dto.MRKAMCode ?? "").Trim();
    var row = await db.Dealers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealerCode == dealer);
    if (row is null) return Results.NotFound(new { error = $"Không có đại lý {dealer}." });
    // Guard nguồn: vùng thị trường phải tồn tại trong MRK_Mst_AreaMarket.
    if (!await db.MrkMstAreaMarkets.AnyAsync(x => x.OrgId == t.OrgId && x.MRKAMCode == code))
        return Results.BadRequest(new { error = $"Vùng thị trường {code} không tồn tại." });
    row.MRKAMCode = code;
    await db.SaveChangesAsync();
    return Results.Ok(new { row.DealerCode, row.MRKAMCode });
}).RequireAuthorization();

// ===== Sinh mã dùng chung (Seq_Common_Get — port 1:1 `Seq_Common_Get_New20181115` (16924) →
// `Seq_Common_MyGet` (16868) → `Seq_Common_Raw` (16854), 2010.HTC BizHTC.Marketing.cs).
// TWIN: WSHTC.cs:592 và WSHTC.64:962. =====
// 🔴 Mỗi loại mã có BA tham số riêng: bảng đếm, chuỗi format, và MODULO (nMaxSeq) — số đếm được
//    lấy dư theo modulo nên mã sẽ QUAY VÒNG khi vượt ngưỡng. Đó là thiết kế của nguồn.
// 🔴 HAI cặp loại mã dùng CHUNG bộ đếm: TCGIV + HTCIV → `Seq_PrintVAT`; CTRM + CDV → `Seq_CarReq`.
// 🔴 Placeholder {3} là MÃ NGÀY 3 ký tự, mã hoá theo bảng "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ":
//    ký tự[năm - 2010] + ký tự[tháng] + ký tự[ngày]. Ví dụ 2026-09-06 → "G96".
//    Bảng chỉ có 36 ký tự nên năm ≥ 2046 sẽ vượt chỉ số — giới hạn sẵn có của nguồn, giữ nguyên.
var seqMap = new Dictionary<string, (string Table, string Format, long MaxSeq)>(StringComparer.OrdinalIgnoreCase)
{
    ["ID"] = ("Seq_Id", "{0}{1}{2}", 999000000000L),
    ["MRKFP"] = ("Seq_MRKFilePath", "{0}MRKFP.{3}.{1:00000}{2}", 100000L),
    ["PL"] = ("Seq_HMCList", "{0}PL.{3}.{1:00000}{2}", 100000L),
    ["GPSUNMAPVINNO"] = ("Seq_GPSUnMapVINNo", "{0}{1}{2:00000}", 100000L),
    ["TCGIV"] = ("Seq_PrintVAT", "{0}{1}{2:00000}", 100000L),
    ["HTCIV"] = ("Seq_PrintVAT", "{0}{1}{2:00000}", 100000L),
    ["BULKINFO"] = ("Seq_BulkInfo", "{0}{1}{2:00000}", 100000L),
    ["REQUESTID"] = ("Seq_RequestId", "{0}{1}{2:00000}", 100000L),
    ["CTRM"] = ("Seq_CarReq", "{0}{1}{2:00000}", 100000L),
    ["CDV"] = ("Seq_CarReq", "{0}{1}{2:00000}", 100000L),
    ["ATAPPRORDNO"] = ("Seq_ATApprOrdNo", "{0}ATAORDNO.{3}.{1:00000}{2}", 100000L),
    ["GRTCEXTNO"] = ("Seq_GrtClaimExtNo", "{0}GRTCEXTNO.{3}.{1:00000}{2}", 100000L),
};

app.MapPost("/api/seqcommon/get", async (SeqCommonDto dto, AppDbContext db, ITenantContext t) =>
{
    var type = (dto.SequenceType ?? "").Trim();
    if (!seqMap.TryGetValue(type, out var map))
        return Results.BadRequest(new { error = $"Loại mã không hợp lệ. Cho phép: {string.Join(", ", seqMap.Keys)}." });

    // Nguồn mượn IDENTITY của SQL Server; ở đây tăng bộ đếm theo tên bảng Seq_* tương ứng.
    var counter = await db.SeqCounters.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SeqTableName == map.Table);
    if (counter is null)
    {
        counter = new SeqCounter { OrgId = t.OrgId, SeqTableName = map.Table, LastValue = 0 };
        db.SeqCounters.Add(counter);
    }
    counter.LastValue += 1;
    await db.SaveChangesAsync();

    // Mã ngày {3}: ký tự[năm-2010] + ký tự[tháng] + ký tự[ngày] trên bảng 36 ký tự.
    const string enc = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    var now = DateTime.Now;
    var yIdx = now.Year - 2010; // TConst.BizMix.Default_RootYear
    if (yIdx < 0 || yIdx >= enc.Length)
        return Results.BadRequest(new { error = $"Năm {now.Year} nằm ngoài bảng mã 36 ký tự của nguồn." });
    var dateCode = $"{enc[yIdx]}{enc[now.Month]}{enc[now.Day]}";

    var seq = counter.LastValue % map.MaxSeq; // 🔴 lấy DƯ — mã quay vòng khi vượt ngưỡng
    var code = string.Format(map.Format, dto.ParamPrefix ?? "", seq, dto.ParamPostfix ?? "", dateCode);
    return Results.Ok(new { sequenceType = type, seqTable = map.Table, seq, dateCode, code });
}).RequireAuthorization();

// Xem bộ đếm hiện tại (không cấp số mới) — tiện cho vận hành, nguồn không có hàm tương ứng.
app.MapGet("/api/seqcommon", async (AppDbContext db, ITenantContext t) =>
{
    var items = await db.SeqCounters.Where(x => x.OrgId == t.OrgId)
        .OrderBy(x => x.SeqTableName).Select(x => new { x.SeqTableName, x.LastValue }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// ===== Master của module Marketing (port 1:1 các hàm `*_Get` trong BizHTC.Marketing.cs:
// Mst_KPI(7662) · Mst_KPIType(7949) · MRK_Mst_AreaMarket(11828) · Mst_DocType(12238) ·
// Mst_EvenType(12490) · Mst_Quater(12749) · Mst_FileType(13008) · Mst_Disbursment(13256) ·
// Mst_Doc Get(13515)/Create(13726)/Delete(13904)). TWIN: cả WS 32-bit lẫn 64-bit. =====
// 🔴 Ba master Mst_KPI / Mst_KPIType / MRK_Mst_AreaMarket dùng cột cờ tên `FlagAcitve` —
//    SAI CHÍNH TẢ NGUYÊN VĂN trong DB nguồn (dòng 7808 / 8080 / 11961). Giữ nguyên, không "sửa".
// Đây là các master mà những lượt trước phải ghi nợ vì MiniHTC chưa có
// (Mst_KPI #112 · Mst_Quater #110 · Mst_EvenType + Mst_FileType #111).
// ===== 🔴 #329 BÁO CÁO KPI XƯỞNG DỊCH VỤ (`Report_KPI`) — MiniHTC chưa có bản ghi báo cáo =====
// Cụm lệch LỚN NHẤT của sweep #320 (**44 cột**). TRACE TWIN: WS `:27809` gọi
//   `Report_KPICreate_New20221101` (**100 cột**) ⇒ bản trần (56 cột) CHẾT.
// ⚠️ Cả hai bản nằm trong `BizCarSv.zzzzCode.cs` — tên file gợi ý "code rác" nhưng **bản LIVE ở đó**.
//   Bài học: **đừng loại hàm theo tên file**, chỉ WS mới quyết định (cùng lệ "đừng loại theo tên hàm").
// 📌 Bề mặt KPI của nguồn có **9 WebMethod**: Create · Update · Approved · Get · Get_Real · Get_WH ·
//   Get_Real_WH · Create_AutoAllDealer · Create_AutoDealer. Lượt này port **bản ghi + Create/Get**;
//   duyệt (`Approved`) và hai job tự sinh theo đại lý là **NỢ ĐÃ KHAI**.
// ===== 🔴 #410 BỘ LỌC TRẠNG THÁI CỦA MÀN DANH SÁCH KPI **KHÔNG BAO GIỜ CHẠY** =====
// TRACE: `FrmReportDisplay_KPI` (`:336`, `:759`) → `DBSerReportKPI.RptKPIGet` (`:230`) → WS `RptKPIGet`
//   (`WSCarSv.asmx.cs:13471`) → biz `RptKPIGet` (`Service.Report.cs:4391`) → **`RptKPIGetWithParams`**
//   (`:4527` — hàm `private` chứa toàn bộ SQL; bản `RptKPIGet` chỉ là vỏ bọc gán tên hàm/mã lỗi).
//
// 🔴 **LỖI THẬT**: form gọi với `Constants.Flag.Active`, mà `Flag.Active = "1"` (`Const.Main.cs:28`) —
//   một giá trị **TRẦN, không có toán tử**. Biz đưa thẳng vào `SqlUtils.BuildClause("and", "t.Status", "1", …)`.
//   Đọc thân `BuildClause` (`CommonUtils/DataUtils.cs:1074`): nó nhận diện tiền tố `=` `!=` `>=` `<=` `>` `<`
//   `LIKE` `NOT LIKE` `IS NULL` `IS NOT NULL` `IN` `NOT IN`. Không khớp cái nào ⇒ `nCase` giữ **0**,
//   **không nhánh nào chạy**, hàm trả `""` ⇒ **mệnh đề lọc biến mất, không lỗi, không log**.
//   ⇒ Màn danh sách tưởng đang lọc "chỉ báo cáo còn hiệu lực" nhưng thật ra **trả về MỌI trạng thái**,
//     kể cả bản đã huỷ. So sánh: `RptYear`/`RptMonth` được tầng service ghép `"=" +` nên **có** chạy.
//     Ba tham số, ba số phận khác nhau, trong cùng một lời gọi.
//   📌 MiniHTC **giữ bộ lọc hoạt động** (mặc định) vì bỏ đi là chặn hồi quy bản port trước; muốn tái hiện
//     đúng nguồn thì truyền `statusFilter=source`. Cả hai chiều đều báo cờ, không im lặng.
//
// 🔴 **HAI PHÉP NỐI ẨN, cả hai đều LOẠI BỎ DÒNG mà màn hình không hề nói**:
//   1. `join mst_Dealer dl on t.DealerCode = dl.DealerCode **and dl.FlagDealerHTC = '1'**`
//      ⇒ báo cáo của đại lý **ngoài mạng lưới HTC** có trong bảng nhưng **không hiện**.
//   2. `join sys_user u on t.RptBy = u.UserCode **and t.DealerCode = u.DealerCode**` — nối TRONG.
//      ⇒ người lập báo cáo **nghỉ việc / bị xoá / CHUYỂN SANG ĐẠI LÝ KHÁC** thì **cả dòng KPI biến mất**
//        khỏi danh sách, dù báo cáo vẫn nằm nguyên trong CSDL và có thể đã được duyệt.
//        Đây là mất dữ liệu **lúc ĐỌC**: không ai xoá gì cả, chỉ là không còn nhìn thấy.
//
// ⚠️ Thứ tự nguồn: `order by t.RptYear, CAST(t.RptMonth AS INT)` — tháng lưu **CHỮ** nhưng sắp **SỐ**
//   (sắp theo chữ sẽ ra 1, 10, 11, 12, 2…). ⚠️ Và nếu có bản ghi `RptMonth` không phải số thì `CAST`
//   **ném lỗi và cả truy vấn hỏng** — không phải một dòng sai, mà là màn hình trắng.
// ⚠️ `BuildClause` gọi `.ToUpper()` trên **cả chuỗi điều kiện lẫn giá trị tham số** ⇒ so sánh luôn ở dạng
//   HOA. Giá trị lưu dạng thường trong CSDL sẽ **không khớp**.
// ⚠️ Mọi chỉ tiêu số đều bọc `isnull(...,0)` ⇒ NULL và 0 **trả về giống hệt nhau**. Nghĩa là khác biệt
//   NULL-hay-0 giữa lệnh TẠO (#403) và lệnh SỬA (#404) **không nhìn thấy được qua endpoint này**;
//   nó chỉ lộ ra ở các báo cáo tổng hợp khác. Ghi lại để khỏi tưởng #404 đã tự hết.
// ⚠️ Tham số `strDealerCode` của tầng service là **THAM SỐ CHẾT**: thân hàm bỏ qua nó và luôn truyền
//   `"=" + SystemGlobal.strDealerCode` (phiên đăng nhập). Hiện các nơi gọi đều truyền đúng giá trị đó
//   nên chưa gây sai; nhưng ai đó lọc theo đại lý khác sẽ **âm thầm nhận dữ liệu đại lý mình**.
app.MapGet("/api/reportkpis", async (AppDbContext db, ITenantContext t, string? dealer, string? status,
    long? autoId, string? year, string? month, string? statusFilter) =>
{
    var qy = db.ReportKpis.Where(x => x.OrgId == t.OrgId);
    if (autoId.HasValue) qy = qy.Where(x => x.Id == autoId.Value);
    if (!string.IsNullOrWhiteSpace(dealer)) qy = qy.Where(x => x.DealerCode == dealer!.Trim().ToUpperInvariant());
    if (!string.IsNullOrWhiteSpace(year)) qy = qy.Where(x => x.RptYear == year!.Trim());
    if (!string.IsNullOrWhiteSpace(month)) qy = qy.Where(x => x.RptMonth == month!.Trim());
    // `statusFilter=source` ⇒ tái hiện đúng nguồn: BỎ QUA bộ lọc trạng thái.
    var statusDropped = string.Equals(statusFilter, "source", StringComparison.OrdinalIgnoreCase);
    if (!statusDropped && !string.IsNullOrWhiteSpace(status)) qy = qy.Where(x => x.Status == status);

    var all = await qy.ToListAsync();
    var beforeJoins = all.Count;

    // --- Phép nối ẩn 1: chỉ đại lý thuộc mạng lưới HTC.
    var htcDealers = (await db.Dealers.Where(d => d.OrgId == t.OrgId && d.FlagDealerHTC == "1")
        .Select(d => d.DealerCode).ToListAsync()).ToHashSet();
    var afterDealer = all.Where(x => x.DealerCode != null && htcDealers.Contains(x.DealerCode)).ToList();
    var droppedByDealerFlag = beforeJoins - afterDealer.Count;

    // --- Phép nối ẩn 2: người lập phải còn trong sys_user VÀ vẫn thuộc đúng đại lý đó.
    var users = await db.SysUsers.Where(u => u.OrgId == t.OrgId)
        .Select(u => new { u.UserCode, u.DealerCode, u.UserName }).ToListAsync();
    var userKey = users.Where(u => u.DealerCode != null)
        .GroupBy(u => u.UserCode + "\u0001" + u.DealerCode)
        .ToDictionary(g => g.Key, g => g.First().UserName);
    var kept = afterDealer.Where(x => x.RptBy != null && x.DealerCode != null
        && userKey.ContainsKey(x.RptBy + "\u0001" + x.DealerCode)).ToList();
    var droppedByAuthorJoin = afterDealer.Count - kept.Count;

    // --- Thứ tự nguồn: năm tăng, rồi THÁNG SẮP THEO SỐ (nguồn CAST(RptMonth AS INT)).
    var nonNumericMonths = kept.Where(x => !int.TryParse((x.RptMonth ?? "").Trim(), out _))
        .Select(x => x.RptMonth).Distinct().ToList();
    var items = kept
        .OrderBy(x => x.RptYear)
        .ThenBy(x => int.TryParse((x.RptMonth ?? "").Trim(), out var mi) ? mi : int.MaxValue)
        .Take(500).Select(x => new
    {
        // #410 Cột dẫn xuất do SQL nguồn tính, không lưu trong bảng.
        UserName = x.RptBy != null && x.DealerCode != null
            && userKey.TryGetValue(x.RptBy + "\u0001" + x.DealerCode, out var un) ? un : null,
        RptMonthText = x.RptMonth == null ? null : "Tháng " + x.RptMonth,
        EmployeeNumber = (x.EnginerNumber ?? 0) + (x.AdvisoryNumber ?? 0)
                       + (x.EnginerBP ?? 0) + (x.StaffOrther ?? 0),
        CavityNumber = (x.CavityRONumber ?? 0) + (x.CavityBPNumber ?? 0) + (x.CavityParkingNumber ?? 0),
        x.Id,
        // #403 §12 ky bao cao
        x.RptYear, x.RptMonth, x.RptBy,
        x.AccessoryAmountAfterVAT,
        x.AccessoryAmountOut,
        x.AdvisoryNumber,
        x.ApprovedBy,
        x.ApprovedDate,
        x.CabinetPaintNumber,
        x.CarPerAdviserDay,
        x.CavityBPNumber,
        x.CavityCopperNumber,
        x.CavityMaintainNumber,
        x.CavityOtherNumber,
        x.CavityParkingNumber,
        x.CavityQtyPerEngineerBDNSCC,
        x.CavityRONumber,
        x.CountBDD,
        x.CountBDDLocal,
        x.CountBDDPerCavityMaintain,
        x.CountBDDRoRepair,
        x.CountCarService,
        x.CountSCC,
        x.CountSCCLocal,
        x.CountSCCPerCavityRO,
        x.CountSCCRoInsurance,
        x.CountSCCRoRepair,
        x.CountSCCRoWarranty,
        x.CountSCD,
        x.CountSCDLocal,
        x.CountSCDPerCavityCopper,
        x.CountSCDRoInsurance,
        x.CountSCDRoRepair,
        x.CountSCDRoWarranty,
        x.CountSCS,
        x.CountSCSLocal,
        x.CountSCSPerCabinetPaint,
        x.CountSCSPerCavityBP,
        x.CountSCSRoInsurance,
        x.CountSCSRoRepair,
        x.CountSCSRoWarranty,
        x.CountSPK,
        x.CountSPKLocal,
        x.CountPDI,   // #335 §12
        x.CountPDIRoRepair,   // #335 §12
        x.CountPDILocal,   // #335 §12
        x.CountSPKRoRepair,
        x.DateReport,
        x.DealerCode,
        x.EmploymentRate,
        x.EnginerBP,
        x.EnginerNumber,
        x.LaborProductivity,
        x.LogLUBy,
        x.LogLUDateTime,
        x.PaintingTechnicianQty,
        x.PartAmountLocal,
        x.PartAmountOut,
        x.PartAmountRoInsurance,
        x.PartAmountRoRepair,
        x.PartAmountRoWarranty,
        x.PartAmountShell,
        x.PartProfitRate,
        x.RevenuePerAdviser,
        x.RevenuePerKTVBDN,
        x.RevenuePerKTVSCC,
        x.RevenuePerKTVSCD,
        x.RevenuePerKTVSCS,
        x.SerProfitRate,
        x.ServiceAmountBDDLocal,
        x.ServiceAmountBDDRoRepair,
        x.ServiceAmountSCCLocal,
        x.ServiceAmountSCCRoInsurance,
        x.ServiceAmountSCCRoRepair,
        x.ServiceAmountSCCRoWarranty,
        x.ServiceAmountSCDLocal,
        x.ServiceAmountSCDRoInsurance,
        x.ServiceAmountSCDRoRepair,
        x.ServiceAmountSCDRoWarranty,
        x.ServiceAmountSCSLocal,
        x.ServiceAmountSCSRoInsurance,
        x.ServiceAmountSCSRoRepair,
        x.ServiceAmountSCSRoWarranty,
        x.ServiceAmountSPKLocal,
        x.ServiceAmountPDIRoRepair,   // #336 §12
        x.ServiceAmountPDILocal,   // #336 §12
        x.ServiceAmountSPKRoRepair,
        x.ServiceProductivity,
        x.ServiceTechnicianQty,
        x.ShellAmountOut,
        x.SparePartsStaff,
        x.StaffOrther,
        x.Status,
        x.UnitPriceBDN,
        x.UnitPriceSCC,
        x.UnitPriceSCD,
        x.UnitPriceSCS,
        x.WorkDayQty,
        x.WorkHourActualQty,
        x.WorkHourBDNQty,
        x.WorkHourFeeQty,
        x.WorkHourPerCarRO,
        x.WorkHourQty,
        x.WorkHourSCCQty,
        x.WorkHourSCDQty,
        x.WorkHourSCSQty,
        x.CreatedBy, x.CreatedAt,
    }).ToList();   // #410 co: `kept` da la List trong bo nho (hai phep noi an loc trong C#)

    return Results.Ok(new
    {
        count = items.Count,
        matchedBeforeJoins = beforeJoins,
        droppedByDealerFlag,
        droppedByDealerFlagNote = droppedByDealerFlag > 0
            ? "Bị loại vì đại lý KHÔNG có FlagDealerHTC = '1'. Nguồn nối mst_Dealer kèm điều kiện này "
              + "nên báo cáo của đại lý ngoài mạng lưới HTC tồn tại trong bảng nhưng không bao giờ hiện."
            : null,
        droppedByAuthorJoin,
        droppedByAuthorJoinNote = droppedByAuthorJoin > 0
            ? "Bị loại vì người lập (RptBy) không còn trong sys_user, HOẶC đã chuyển sang đại lý khác "
              + "(nguồn nối TRONG theo cả UserCode LẪN DealerCode). Báo cáo vẫn nằm trong CSDL, chỉ là "
              + "không ai nhìn thấy nữa — mất dữ liệu lúc ĐỌC, không phải lúc ghi."
            : null,
        statusFilterApplied = !statusDropped,
        statusFilterNote = statusDropped
            ? "Đang tái hiện NGUỒN: bộ lọc trạng thái BỊ BỎ. Nguồn truyền Flag.Active = \"1\" (không có "
              + "toán tử) vào BuildClause ⇒ nCase = 0 ⇒ mệnh đề biến mất, không lỗi, không log."
            : "MiniHTC ĐANG lọc theo trạng thái. Nguồn thì KHÔNG (Flag.Active = \"1\" thiếu toán tử nên "
              + "BuildClause bỏ qua) ⇒ màn WinForm trả về MỌI trạng thái. Truyền statusFilter=source để so.",
        nonNumericMonths,
        nonNumericMonthNote = nonNumericMonths.Count > 0
            ? "Có RptMonth không phải số. Nguồn sắp bằng CAST(RptMonth AS INT) ⇒ những bản ghi này làm "
              + "CẢ TRUY VẤN ném lỗi (màn hình trắng), không phải sai một dòng. MiniHTC đẩy chúng xuống cuối."
            : null,
        derivedComputed = new[] { "EmployeeNumber", "CavityNumber", "RptMonthText", "UserName" },
        derivedNotComputable = new[]
        {
            "CountCarGJ", "CountCarBP", "CountCarService(SQL)", "AmountGJ", "AmountBP",
            "AmountService", "AmountPart", "AmountWork", "HourWork",
        },
        derivedNotComputableNote = "Nguồn còn tính 9 cột tổng nữa, nhưng các cột NGUỒN của chúng "
            + "(CountPaymentGJ/CountWarrantyGJ/CountLocalGJ/CountPaymentBP/…, AmountGJ*/AmountBP*/"
            + "AmountPart*/AmountService*/Hour*) CHƯA có trong entity ReportKpi ⇒ không tính được. "
            + "Lưu ý CountCarService: nguồn DẪN XUẤT bằng phép cộng, MiniHTC lại LƯU thành cột — hai "
            + "nguồn sự thật cho cùng một con số.",
        nullFlattenedNote = "Nguồn bọc isnull(...,0) mọi chỉ tiêu ⇒ NULL và 0 trả về GIỐNG HỆT NHAU. "
            + "Khác biệt NULL-hay-0 giữa lệnh TẠO (#403) và SỬA (#404) KHÔNG nhìn thấy qua endpoint này.",
        deadParamNote = "Tầng service có tham số strDealerCode nhưng BỎ QUA nó, luôn dùng "
            + "SystemGlobal.strDealerCode của phiên đăng nhập — tham số chết.",
        items,
    });
}).RequireAuthorization();

// ===== 🔴 #330 DUYỆT BÁO CÁO KPI (`Report_KPIApproved`, `zzzzCode.cs:1635`) =====
// 🔴 "DUYỆT" Ở ĐÂY **KHÔNG ĐỔI TRẠNG THÁI** — chỉ đóng dấu người/thời điểm:
//   `Report_KPICreate` đã đặt `Status = Stage.Finished` (**"F"**) **NGAY LÚC TẠO** (`zzzzCode.cs:`1285`);
//   `Report_KPIApproved` đặt lại **đúng giá trị đó** rồi ghi `ApprovedDate` / `ApprovedBy` / LogLU*.
//   ⇒ Không có luồng Pending→Approved cho báo cáo KPI, dù tên hàm gợi ý thế. Port giữ đúng: không dựng
//     trạng thái trung gian, chỉ đóng dấu.
// ⚠️ KHOÁ tra là **cặp (DealerCode, DateReport)**, KHÔNG phải Id.
// ⚠️ `ApprovedDate` dùng `"yyyy-MM-dd HH:mm:ss"` ⇒ **GIỮ GIÂY** — khác các mốc của lệnh sửa chữa vốn cắt
//   tới PHÚT (#321/#328). Độ chính xác thời gian **không đồng nhất** giữa các màn; port theo từng chỗ.
app.MapPost("/api/reportkpis/approve", async (ReportKpiApproveDto dto, AppDbContext db, ITenantContext t) =>
{
    var dealer = (dto.DealerCode ?? "").Trim().ToUpperInvariant();
    if (dealer.Length == 0 || dto.DateReport is null)
        return Results.BadRequest(new { error = "Cần DealerCode và DateReport (khoá tra của nguồn)." });

    var rows = await db.ReportKpis.Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer
        && x.DateReport == dto.DateReport).ToListAsync();
    if (rows.Count == 0) return Results.NotFound(new { dealer, dto.DateReport });

    var now = DateTime.Now;   // giữ GIÂY, đúng nguồn
    foreach (var r in rows)
    {
        r.Status = "F";                 // Stage.Finished — vốn đã là "F" từ lúc tạo
        r.ApprovedDate = now;
        r.ApprovedBy = dto.ApprovedBy;
        r.LogLUDateTime = now;
        r.LogLUBy = dto.ApprovedBy;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        dealerCode = dealer, dto.DateReport, approved = rows.Count,
        status = "F",
        note = "Duyệt KPI chỉ đóng dấu ApprovedDate/ApprovedBy — Status đã là \"F\" từ lúc TẠO, không đổi.",
    });
}).RequireAuthorization();

// ===== 🔴 #330 SINH BÁO CÁO KPI TỰ ĐỘNG — hai job LIVE, **ghi KHÁC SỐ CỘT** =====
// TRACE TWIN cả hai (WS `:30350` và `:30418`) rồi lần tiếp xuống hàm chúng gọi:
//   `Report_KPICreate_AutoAllDealer`        (LIVE) → gọi `Report_KPICreateX`            ⇒ **61 cột**
//   `Report_KPICreate_AutoDealer_New20221101` (LIVE) → gọi `Report_KPICreateX_New20221101` ⇒ **105 cột**
//   (`Report_KPICreate_AutoDealer` bản trần KHÔNG được WS gọi ⇒ chết.)
// 🔴 ⇒ **Chạy job "TẤT CẢ đại lý" ghi 61 cột; chạy job "MỘT đại lý" ghi 105 cột — cùng bảng `Report_KPI`.**
//   Báo cáo sinh hàng loạt **thiếu 44 cột** so với sinh lẻ. Đây là bất nhất CÓ THẬT trong nguồn,
//   không phải port sót — trả cờ `columnSetNote` để người đối chiếu thấy ngay.
//
// ⚠️ GUARD NGÀY BÁO CÁO (chỉ có ở `AutoAllDealer`):
//   `if (strDateReport.CompareTo(DateTime.Now.ToString("yyyy-MM-01")) > 0) throw …_InvalidDateReport`
//   ⇒ **so CHUỖI**, không phải so ngày: chỉ cho sinh báo cáo cho **kỳ ≤ ngày 1 tháng hiện tại**.
//   Port so chuỗi y hệt để biên giới trùng khớp với nguồn.
app.MapPost("/api/reportkpis/auto", async (ReportKpiAutoDto dto, AppDbContext db, ITenantContext t) =>
{
    if (dto.DateReport is null) return Results.BadRequest(new { error = "Cần DateReport." });
    var dateStr = dto.DateReport.Value.ToString("yyyy-MM-dd");
    var boundary = DateTime.Now.ToString("yyyy-MM-01");
    // so CHUỖI đúng như nguồn (CompareTo trên chuỗi "yyyy-MM-dd")
    if (string.CompareOrdinal(dateStr, boundary) > 0)
        return Results.BadRequest(new
        {
            error = "Kỳ báo cáo không hợp lệ: chỉ sinh cho kỳ ≤ ngày 1 tháng hiện tại.",
            dateReport = dateStr, boundary,
        });

    // ===== 🔴 #335 LỌC ĐẠI LÝ — #330 port THIẾU HẲN, đây là GAP của chính lượt trước =====
    // Nguồn (`ZTemp.cs`, trong cả hai job auto):
    //   `from Mst_Dealer t where t.DealerCode not in ('VN101') -- Đại lý idocNet Test`
    //   `and t.FlagActive = '1' and t.FlagDealerHTC = '1'`
    // #330 dùng `db.Dealers.Where(d => d.OrgId == t.OrgId)` — **không lọc gì** ⇒ sẽ sinh báo cáo KPI cho
    //   đại lý đã ngừng hoạt động, đại lý KHÔNG thuộc HTC, và cả **đại lý TEST VN101**. Nay vá đủ ba điều kiện.
    var oneDealer = (dto.DealerCode ?? "").Trim().ToUpperInvariant();
    var allDealers = oneDealer.Length == 0;

    var dq = db.Dealers.Where(d => d.OrgId == t.OrgId
        && d.DealerCode != "VN101"          // đại lý idocNet Test — nguồn loại đích danh
        && d.FlagActive == "1"
        && d.FlagDealerHTC == "1");
    if (!allDealers) dq = dq.Where(d => d.DealerCode == oneDealer);
    var dealers = await dq.Select(d => d.DealerCode).ToListAsync();

    // ===== 🔴 #335 CỬA SỔ KỲ BÁO CÁO — nguồn tính từ `strDateReport` =====
    //   `strDateFrom = dtimeReport.ToString("yyyy-MM-01")`  (mùng 1 của tháng kỳ)
    //   `strDateTo   = dtimeReport.AddMonths(1).ToString("yyyy-MM-01") rồi AddDays(-1)` (ngày cuối tháng)
    var rp = dto.DateReport!.Value;
    var dateFrom = new DateTime(rp.Year, rp.Month, 1);
    var dateTo = dateFrom.AddMonths(1).AddDays(-1);

    // ===== 🔴 #335 QUẦN THỂ LỆNH được tính (`#tbl_Ser_RO`) =====
    //   `and sr.ActualDeliveryDate >= @strDateFrom and sr.ActualDeliveryDate <= @strDateTo`
    //   `and sr.[status] in ('FNS')`
    // ⚠️ Mốc lọc là **ActualDeliveryDate (giờ giao xe thực tế)**, KHÔNG phải ngày lập lệnh hay
    //   `FinishedDate` ⇒ lệnh hoàn tất cuối tháng trước mà giao xe tháng này thì tính vào **tháng này**.
    // ⚠️ `'FNS'` là từ vựng của nguồn; MiniHTC dùng nhãn `"Finished"` cho cùng trạng thái đó.
    var roIds = await db.RepairOrders
        .Where(r => r.OrgId == t.OrgId && r.Status == "Finished"
            && r.ActualDeliveryDate != null
            && r.ActualDeliveryDate >= dateFrom && r.ActualDeliveryDate <= dateTo)
        .Select(r => new { r.Id, r.DealerCode, r.ActualDeliveryDate }).ToListAsync();

    // #336: thêm Factor/Price/Vat để tính DOANH THU TIỀN CÔNG, ngoài phân loại để ĐẾM LƯỢT (#335).
    var items = await db.RoServiceItems.Where(i => i.OrgId == t.OrgId)
        .Select(i => new { i.RoId, i.ROType, i.ExpenseType, i.Factor, i.Price, i.Vat }).ToListAsync();

    // ===== 🔴 #336 THAM SỐ ĐƠN GIÁ CÔNG — nguồn đọc `#tbl_Mst_Param` theo `ParamCode` =====
    // `UnitPriceBDN` · `UnitPriceSCC` · `UnitPriceSCD` · `UnitPriceSCS` (đã có sẵn trong catalog
    //   `DealerServiceOptCatalog` của MiniHTC).
    // ⚠️ **BDD dùng tham số tên BDN**: loại công việc là `BDD` (Bảo Dưỡng) nhưng đơn giá tra bằng
    //   `UnitPrice**BDN**` (Bảo Dưỡng Nhanh). Lệch tên CÓ THẬT trong nguồn — không phải gõ nhầm ở đây.
    var prm = (await db.DealerServiceOptions.Where(x => x.OrgId == t.OrgId).ToListAsync())
        .GroupBy(x => x.ParamCode).ToDictionary(g => g.Key, g => g.First().ParamValue);
    decimal Prm(string code) => prm.TryGetValue(code, out var v)
        && decimal.TryParse(v, out var d) ? d : 0m;
    var upBDN = Prm("UnitPriceBDN"); var upSCC = Prm("UnitPriceSCC");
    var upSCD = Prm("UnitPriceSCD"); var upSCS = Prm("UnitPriceSCS");

    // ===== 🔴 #337 DOANH THU PHỤ TÙNG =====
    // Danh sách mã **dầu nhớt** — nguồn đọc từ web.config; ở đây là tham số `ListShellCode`.
    var shellCodes = (prm.TryGetValue("ListShellCode", out var sc) ? sc : "")
        .Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
        .Select(x => x.ToUpperInvariant()).ToHashSet();

    // ⚠️ Nguồn `inner join Ser_Mst_Part smp` ⇒ dòng phụ tùng **không có trong danh mục** bị LOẠI khỏi
    //   doanh thu (không phải cộng 0 — mà biến mất). Giữ đúng: lọc theo tập mã có trong danh mục.
    var partMaster = (await db.ServiceParts.Where(p => p.OrgId == t.OrgId)
        .Select(p => p.PartCode).ToListAsync()).ToHashSet();

    var parts = await db.RoPartItems.Where(p => p.OrgId == t.OrgId)
        .Select(p => new { p.RoId, p.PartCode, p.ExpenseType, p.FlagAccessory,
            p.Factor, p.NeedQty, p.UnitPrice, p.Vat }).ToListAsync();

    // ===== 🔴 #338 DANH MỤC KTV và KHOANG — cùng MỘT vị từ hiệu lực theo ngày =====
    // Nguồn (cho cả `Ser_Engineer` lẫn `Ser_Cavity`): `Isactive = '1'` **và** ba nhánh
    //   `(Start is null and Finish is null)`
    //   `or (Start <= @strDateTo and Finish is null)`
    //   `or (Start <= @strDateTo and Finish >= @strDateTo)`
    // 🔴 Ngay phía trên là **bản CŨ bị comment** dùng `@strDateFrom`, kèm chú thích
    //   *"20221220. HuongTTT. Ms Đông confirm luật cũ là sai. Đúng là lấy những KTV có Ngày bắt đầu
    //   trong tháng tìm kiếm"* ⇒ port **bản ACTIVE (mốc dateTo)**, không port dòng comment.
    // ⚠️ Nhánh 3 đòi `Finish >= dateTo` ⇒ **KTV nghỉ giữa tháng bị loại HẲN** khỏi kỳ đó
    //   (không tính theo tỉ lệ ngày công). Đó là luật của nguồn, giữ nguyên.
    bool Effective(DateTime? start, DateTime? finish) =>
        (start == null && finish == null)
        || (start != null && start <= dateTo && finish == null)
        || (start != null && start <= dateTo && finish != null && finish >= dateTo);

    static DateTime? AsDate(string? s) => DateTime.TryParse(s, out var v) ? v : (DateTime?)null;
    bool EffectiveStr(string? start, string? finish) => Effective(AsDate(start), AsDate(finish));

    var engineers = (await db.ServiceEngineers.Where(e => e.OrgId == t.OrgId && e.Status == "1")
            .Select(e => new { e.DealerCode, e.EngineerType, e.StartWorkDate, e.FinishWorkDate }).ToListAsync())
        .Where(e => Effective(e.StartWorkDate, e.FinishWorkDate)).ToList();

    var cavities = (await db.Cavities.Where(c => c.OrgId == t.OrgId && c.FlagActive == "1")
            .Select(c => new { c.DealerCode, c.CavityType, c.StartUseDate, c.FinishUseDate }).ToListAsync())
        // Cavity luu ngay dang CHUOI (khac ServiceEngineer dung DateTime) => doi truoc khi so.
        //   Chuoi rong / khong parse duoc coi nhu NULL, dung nhu isnull cua nguon.
        .Where(c => EffectiveStr(c.StartUseDate, c.FinishUseDate)).ToList();

    var created = 0;
    foreach (var d in dealers)
    {
        // Không sinh trùng kỳ cho cùng đại lý.
        if (await db.ReportKpis.AnyAsync(x => x.OrgId == t.OrgId && x.DealerCode == d
                && x.DateReport == dto.DateReport)) continue;

        var ro = roIds.Where(r => r.DealerCode == d).Select(r => r.Id).ToHashSet();
        // ===== 🔴 #335 CÁCH ĐẾM: đếm **LỆNH (lượt xe)**, KHÔNG đếm dòng dịch vụ =====
        //   `select count(0) from #tbl_Ser_RO q where q.ROID in (select t.ROID from items where …)`
        //   ⇒ một lệnh có 5 dòng SCC vẫn chỉ tính **1 lượt**. Đếm dòng dịch vụ là SAI.
        //   ⇒ cũng vì thế `CountSCC` **KHÔNG** bằng tổng 4 mã nguồn tiền: một lệnh vừa có dòng
        //     khách trả tiền vừa có dòng bảo hành sẽ được đếm ở **cả hai**.
        int N(string type, string? exp = null) => items
            .Where(i => ro.Contains(i.RoId) && i.ROType == type
                && (exp == null || i.ExpenseType == exp))
            .Select(i => i.RoId).Distinct().Count();

        // ===== 🔴 #336 DOANH THU TIỀN CÔNG theo cặp loại×nguồn-tiền =====
        //   `SUM(isnull(sri.Factor,0) * isnull(sri.Price,0) * (1 + (sri.VAT * 0.01)))`
        //   ⇒ **ĐÃ GỒM VAT**; `Factor` là hệ số giờ công. Không có `distinct`: tính TỪNG DÒNG dịch vụ
        //     (khác nhóm ĐẾM ở #335 vốn `distinct` theo lệnh) — hai nhóm chỉ tiêu, hai đơn vị.
        decimal A(string type, string exp) => items
            .Where(i => ro.Contains(i.RoId) && i.ROType == type && i.ExpenseType == exp)
            .Sum(i => i.Factor * i.Price * (1m + i.Vat * 0.01m));

        var aBDD = A("BDD", "ROREPAIR") + A("BDD", "LOCAL");
        var aSCC = A("SCC", "ROREPAIR") + A("SCC", "ROWARRANTY") + A("SCC", "ROINSURANCE") + A("SCC", "LOCAL");
        var aSCD = A("SCD", "ROREPAIR") + A("SCD", "ROWARRANTY") + A("SCD", "ROINSURANCE") + A("SCD", "LOCAL");
        var aSCS = A("SCS", "ROREPAIR") + A("SCS", "ROWARRANTY") + A("SCS", "ROINSURANCE") + A("SCS", "LOCAL");

        // ===== 🔴 #336 GIỜ CÔNG = DOANH THU ÷ ĐƠN GIÁ CÔNG (không phải giờ bấm máy) =====
        //   `case when UnitPriceX = 0 then 0 else Round(round(<doanh thu>, 0) / UnitPriceX, 1) end`
        //   ⚠️ Làm tròn **HAI BƯỚC**: doanh thu về 0 số lẻ TRƯỚC khi chia, thương về 1 số lẻ.
        //   ⚠️ Đơn giá = 0 ⇒ trả 0, KHÔNG chia (guard chia-cho-không của nguồn).
        decimal WH(decimal amount, decimal unitPrice) => unitPrice == 0m ? 0m
            : Math.Round(Math.Round(amount, 0, MidpointRounding.AwayFromZero) / unitPrice, 1,
                MidpointRounding.AwayFromZero);
        var whBDN = WH(aBDD, upBDN); var whSCC = WH(aSCC, upSCC);
        var whSCD = WH(aSCD, upSCD); var whSCS = WH(aSCS, upSCS);

        // ===== 🔴 #336 SỐ NGÀY LÀM VIỆC — chú thích nguồn MÂU THUẪN với code =====
        //   Chú thích: *"Bằng tổng số ngày **tạo RO** trong tháng"*
        //   Code:      `group by t.DealerCode, t.**ActualDeliveryFormatDate**` rồi đếm nhóm
        //   ⇒ thực chất là **số ngày CÓ GIAO XE** phân biệt, KHÔNG phải ngày tạo lệnh.
        //     Port theo **CODE** (lệ: nguồn sự thật là câu lệnh đang chạy, không phải chú thích).
        var workDayQty = roIds.Where(r => r.DealerCode == d && r.ActualDeliveryDate != null)
            .Select(r => r.ActualDeliveryDate!.Value.Date).Distinct().Count();

        // ===== 🔴 #338 ĐẾM KTV / KHOANG theo đại lý, rồi ra giờ công hành chính và các tỉ lệ =====
        int NE(string type) => engineers.Count(e => e.DealerCode == d && e.EngineerType == type);
        int NC(string type) => cavities.Count(c => c.DealerCode == d && c.CavityType == type);

        // A.I — số lượng nhân sự theo vai trò (đếm từ danh mục, KHÔNG do người dùng khai).
        var advisoryNumber = NE("CVDV");     // cố vấn dịch vụ
        var enginerNumber = NE("SCC");       // KTV sửa chữa chung

        // A.II — số khoang theo loại. Mã loại khoang: BDN · SCC · KHAC · KD (đồng) · KS (sơn) · BS (buồng sơn).
        var cavMaintain = NC("BDN"); var cavRO = NC("SCC"); var cavOther = NC("KHAC");
        var cavCopper = NC("KD"); var cavBP = NC("KS"); var cabinetPaint = NC("BS");

        // A.I — bốn vai trò còn lại. Bảy mã `IsEngineer` của nguồn phủ đủ ở đây:
        //   CVDV (cố vấn) · BDN · SCC · KTVD (đồng) · KTVS (sơn) · NVPT (phụ tùng) · KHAC.
        var serviceTechQty = NE("BDN");      // KTV bảo dưỡng nhanh
        var enginerBP = NE("KTVD");          // KTV đồng
        var paintingTechQty = NE("KTVS");    // KTV sơn
        var sparePartsStaff = NE("NVPT");    // nhân viên phụ tùng
        var staffOrther = NE("KHAC");        // nhân viên khác (rửa xe, thu ngân…)

        // A.IV.2 — giờ công HÀNH CHÍNH = (số KTV 4 loại) × số ngày làm việc × 8.
        // ⚠️ Nguồn có **HAI công thức cũ bị comment** dùng tập loại KTV khác hẳn
        //   (KTVD/KTVS/NVPT/KHAC, và một bản đếm theo KHOANG) — chỉ port bản **đang chạy**:
        //   `BDN + SCC + KTVD + KTVS`.
        var ktvCount = NE("BDN") + NE("SCC") + NE("KTVD") + NE("KTVS");
        var workHourQty = (decimal)ktvCount * workDayQty * 8m;

        // Tỉ lệ — mẫu chung: `<tử> / <mẫu1> / <mẫu2>`, làm tròn 1 số lẻ,
        //   guard `khi mẫu nào = 0 thì trả 0` (không chia).
        // Mẫu MỘT mẫu số (nguồn: `case when <mẫu> = 0 then 0 else Round(tử/mẫu, 1) end`).
        decimal Ratio1(decimal num, decimal den) =>
            den == 0m ? 0m : Math.Round(num / den, 1, MidpointRounding.AwayFromZero);

        decimal Ratio(decimal num, decimal den1, decimal den2) =>
            den1 == 0m || den2 == 0m ? 0m
            : Math.Round(num / den1 / den2, 1, MidpointRounding.AwayFromZero);

        // ===== 🔴 #337 DOANH THU PHỤ TÙNG theo nguồn tiền =====
        //   `SUM(isnull(Factor,0) * isnull(Quantity,0) * isnull(Price,0) * (1 + VAT*0.01))`
        //   ⚠️ Công thức phụ tùng có **THÊM `Quantity`** so với công thức tiền công (#336) —
        //     tiền công chỉ `Factor × Price × (1+VAT)`. Bốn thừa số, không phải ba.
        //   Bộ lọc chung: `ExpenseType = <mã>` **và** `FlagAccessory = '0'` (loại phụ kiện)
        //     **và** `PartCode NOT IN <danh sách dầu nhớt>` **và** có trong danh mục phụ tùng.
        decimal PA(string exp) => parts
            .Where(p => ro.Contains(p.RoId) && p.ExpenseType == exp
                && p.FlagAccessory == "0"
                && !shellCodes.Contains(p.PartCode.ToUpperInvariant())
                && partMaster.Contains(p.PartCode))
            .Sum(p => p.Factor * p.NeedQty * p.UnitPrice * (1m + p.Vat * 0.01m));

        // 🔴 NHÓM DẦU NHỚT LỌC **KHÁC HẲN** bốn nhóm trên: chỉ `PartCode IN <danh sách>` —
        //   **KHÔNG** lọc `ExpenseType`, **KHÔNG** lọc `FlagAccessory`. Bất đối xứng CÓ THẬT trong nguồn
        //   ⇒ một dòng dầu nhớt là phụ kiện, hoặc thuộc nguồn tiền bất kỳ, vẫn được cộng vào đây.
        var paShell = parts
            .Where(p => ro.Contains(p.RoId)
                && shellCodes.Contains(p.PartCode.ToUpperInvariant())
                && partMaster.Contains(p.PartCode))
            .Sum(p => p.Factor * p.NeedQty * p.UnitPrice * (1m + p.Vat * 0.01m));

        db.ReportKpis.Add(new ReportKpi
        {
            OrgId = t.OrgId, DealerCode = d, DateReport = dto.DateReport,

            // #337 doanh thu phụ tùng — nguồn `round(..., 0)` khi ghi ra báo cáo.
            PartAmountRoRepair = Math.Round(PA("ROREPAIR"), 0, MidpointRounding.AwayFromZero),
            PartAmountRoWarranty = Math.Round(PA("ROWARRANTY"), 0, MidpointRounding.AwayFromZero),
            PartAmountRoInsurance = Math.Round(PA("ROINSURANCE"), 0, MidpointRounding.AwayFromZero),
            PartAmountLocal = Math.Round(PA("LOCAL"), 0, MidpointRounding.AwayFromZero),
            PartAmountShell = Math.Round(paShell, 0, MidpointRounding.AwayFromZero),

            // #336 doanh thu tiền công — 18 cặp, đúng bộ mà `Report_KPICreateX_New20221101` ghi.
            ServiceAmountBDDRoRepair = A("BDD", "ROREPAIR"), ServiceAmountBDDLocal = A("BDD", "LOCAL"),
            ServiceAmountSCCRoRepair = A("SCC", "ROREPAIR"), ServiceAmountSCCRoWarranty = A("SCC", "ROWARRANTY"),
            ServiceAmountSCCRoInsurance = A("SCC", "ROINSURANCE"), ServiceAmountSCCLocal = A("SCC", "LOCAL"),
            ServiceAmountSCDRoRepair = A("SCD", "ROREPAIR"), ServiceAmountSCDRoWarranty = A("SCD", "ROWARRANTY"),
            ServiceAmountSCDRoInsurance = A("SCD", "ROINSURANCE"), ServiceAmountSCDLocal = A("SCD", "LOCAL"),
            ServiceAmountSCSRoRepair = A("SCS", "ROREPAIR"), ServiceAmountSCSRoWarranty = A("SCS", "ROWARRANTY"),
            ServiceAmountSCSRoInsurance = A("SCS", "ROINSURANCE"), ServiceAmountSCSLocal = A("SCS", "LOCAL"),
            ServiceAmountSPKRoRepair = A("SPK", "ROREPAIR"), ServiceAmountSPKLocal = A("SPK", "LOCAL"),
            ServiceAmountPDIRoRepair = A("PDI", "ROREPAIR"), ServiceAmountPDILocal = A("PDI", "LOCAL"),

            // #336 giờ công quy từ doanh thu + tổng giờ công có tính phí (= tổng 4 nhóm).
            WorkHourBDNQty = whBDN, WorkHourSCCQty = whSCC,
            WorkHourSCDQty = whSCD, WorkHourSCSQty = whSCS,
            WorkHourFeeQty = whBDN + whSCC + whSCD + whSCS,
            WorkDayQty = workDayQty,

            // #338 nhân sự / khoang / giờ công hành chính.
            AdvisoryNumber = advisoryNumber, EnginerNumber = enginerNumber,
            CavityMaintainNumber = cavMaintain, CavityRONumber = cavRO, CavityOtherNumber = cavOther,
            CavityCopperNumber = cavCopper, CavityBPNumber = cavBP, CabinetPaintNumber = cabinetPaint,
            WorkHourQty = workHourQty,

            // #338 tỉ lệ khai thác — lượt xe / nguồn lực / ngày.
            // #339 số lượng nhân sự theo vai trò.
            ServiceTechnicianQty = serviceTechQty, EnginerBP = enginerBP,
            PaintingTechnicianQty = paintingTechQty, SparePartsStaff = sparePartsStaff,
            StaffOrther = staffOrther,

            // ===== 🔴 #339 CHỤP LẠI THAM SỐ vào chính bản báo cáo =====
            // Nguồn ghi thẳng `SerProfitRate`/`PartProfitRate`/`UnitPrice*` vào `Report_KPI`.
            // ⇒ Báo cáo giữ **ảnh chụp** tham số tại thời điểm sinh; sửa tham số sau đó **không**
            //   làm đổi báo cáo cũ. Nhờ vậy mới truy ngược được vì sao giờ công tháng trước ra thế.
            SerProfitRate = Prm("SerProfitRate"), PartProfitRate = Prm("PartProfitRate"),
            UnitPriceBDN = upBDN, UnitPriceSCC = upSCC, UnitPriceSCD = upSCD, UnitPriceSCS = upSCS,

            // #339 doanh thu tiền công bình quân đầu KTV — mỗi loại chia cho ĐÚNG vai trò của nó.
            RevenuePerKTVBDN = Ratio1(aBDD, serviceTechQty),
            RevenuePerKTVSCC = Ratio1(aSCC, enginerNumber),
            RevenuePerKTVSCD = Ratio1(aSCD, enginerBP),
            RevenuePerKTVSCS = Ratio1(aSCS, paintingTechQty),

            // #339 năng suất xưởng = giờ công CÓ TÍNH PHÍ / giờ công HÀNH CHÍNH.
            ServiceProductivity = Ratio1(whBDN + whSCC + whSCD + whSCS, workHourQty),
            // #339 số khoang BDN+SCC trên mỗi KTV BDN+SCC.
            CavityQtyPerEngineerBDNSCC = Ratio1(cavMaintain + cavRO, serviceTechQty + enginerNumber),

            CarPerAdviserDay = Ratio(ro.Count, advisoryNumber, workDayQty),
            CountBDDPerCavityMaintain = Ratio(N("BDD"), cavMaintain, workDayQty),
            CountSCCPerCavityRO = Ratio(N("SCC"), cavRO, workDayQty),
            CountSCDPerCavityCopper = Ratio(N("SCD"), cavCopper, workDayQty),
            CountSCSPerCavityBP = Ratio(N("SCS"), cavBP, workDayQty),
            CountSCSPerCabinetPaint = Ratio(N("SCS"), cabinetPaint, workDayQty),
            Status = "F",                       // nguồn đặt Finished ngay lúc tạo
            CreatedBy = dto.CreatedBy,

            // I. Tổng số lượt xe dịch vụ = đếm TOÀN BỘ lệnh trong kỳ (không lọc theo loại).
            CountCarService = ro.Count,

            // 1. Bảo dưỡng — chỉ có ROREPAIR và LOCAL (không có bảo hành/bảo hiểm).
            CountBDD = N("BDD"), CountBDDRoRepair = N("BDD", "ROREPAIR"), CountBDDLocal = N("BDD", "LOCAL"),
            // 2. Sửa chữa chung — đủ bốn nguồn tiền.
            CountSCC = N("SCC"), CountSCCRoRepair = N("SCC", "ROREPAIR"),
            CountSCCRoWarranty = N("SCC", "ROWARRANTY"), CountSCCRoInsurance = N("SCC", "ROINSURANCE"),
            CountSCCLocal = N("SCC", "LOCAL"),
            // 3. Sửa chữa đồng.
            CountSCD = N("SCD"), CountSCDRoRepair = N("SCD", "ROREPAIR"),
            CountSCDRoWarranty = N("SCD", "ROWARRANTY"), CountSCDRoInsurance = N("SCD", "ROINSURANCE"),
            CountSCDLocal = N("SCD", "LOCAL"),
            // 4. Sửa chữa sơn.
            CountSCS = N("SCS"), CountSCSRoRepair = N("SCS", "ROREPAIR"),
            CountSCSRoWarranty = N("SCS", "ROWARRANTY"), CountSCSRoInsurance = N("SCS", "ROINSURANCE"),
            CountSCSLocal = N("SCS", "LOCAL"),
            // 5. Phụ kiện — chỉ ROREPAIR và LOCAL.
            CountSPK = N("SPK"), CountSPKRoRepair = N("SPK", "ROREPAIR"), CountSPKLocal = N("SPK", "LOCAL"),
            // 6. PDI — chỉ ROREPAIR và LOCAL.
            CountPDI = N("PDI"), CountPDIRoRepair = N("PDI", "ROREPAIR"), CountPDILocal = N("PDI", "LOCAL"),
        });
        created++;
    }
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        dateReport = dateStr, mode = allDealers ? "AutoAllDealer" : "AutoDealer",
        dealers = dealers.Count, created,
        dateFrom = dateFrom.ToString("yyyy-MM-dd"), dateTo = dateTo.ToString("yyyy-MM-dd"),
        // 📌 #335: đã port **nhóm ĐẾM LƯỢT** (25 chỉ tiêu: tổng lượt xe + 6 tổng theo loại + 18 cặp
        //   loại×nguồn-tiền). Các nhóm còn lại của nguồn **CHƯA** port ⇒ khai rõ, không nhận vơ:
        //   – doanh thu tiền công `ServiceAmount*` (SUM Factor×Price×(1+VAT/100) theo 18 cặp)
        //   – giờ công `WorkHour*` (= doanh thu ÷ tham số đơn giá `UnitPrice{BDN,SCC,SCD,SCS}`)
        //   – các tỉ lệ /khoang /CVDV /ngày, doanh thu phụ tùng, lợi nhuận gộp
        computedFigures = "counts+amounts+feehours",
        computedGroups = new[]
        {
            "CountCarService", "Count<Loại>", "Count<Loại><NguồnTiền>",           // #335
            "ServiceAmount<Loại><NguồnTiền> (18 cặp)",                            // #336
            "WorkHour{BDN,SCC,SCD,SCS}Qty", "WorkHourFeeQty", "WorkDayQty",       // #336
            "PartAmount{RoRepair,RoWarranty,RoInsurance,Local,Shell}",            // #337
            "AdvisoryNumber/EnginerNumber", "Cavity*Number/CabinetPaintNumber",   // #338
            "WorkHourQty", "CarPerAdviserDay", "Count<Loại>Per<Khoang>",          // #338
            "ServiceTechnicianQty/EnginerBP/PaintingTechnicianQty/SparePartsStaff/StaffOrther", // #339
            "SerProfitRate/PartProfitRate/UnitPrice* (ảnh chụp tham số)",         // #339
            "RevenuePerKTV*", "ServiceProductivity", "CavityQtyPerEngineerBDNSCC",// #339
        },
        // 🔴 #338 `CavityParkingNumber`: nguồn có cột nhưng **câu tính đã bị COMMENT**
        //   (`--, (select count(0) … CavityType='BS') CavityParkingNumber`) ⇒ **luôn rỗng trong MỌI
        //   báo cáo**, giống họ `Count*Local_SCL` ở #335. Không tính, và nói rõ vì sao.
        alwaysEmptyInSource = new[] { "CavityParkingNumber" },
        // 🔴 #337 Danh sách mã dầu nhớt CHƯA khai ⇒ `PartAmountShell` = 0 và bốn nhóm kia **không loại**
        //   dầu nhớt ra, nên bị cộng dư. Trả cờ để phân biệt "chưa cấu hình" với "không có số liệu".
        shellCodeConfigured = shellCodes.Count > 0,
        // Còn lại — vẫn CHƯA port, cần dữ liệu MiniHTC hiện chưa có:
        //   `WorkHourQty` cần **danh mục KTV theo loại** (`Ser_Engineer.IsEngineer` ∈ BDN/SCC/KTVD/KTVS);
        //   `WorkHourActualQty` cần **phút sửa chữa thực tế từng lệnh** (trừ thời gian tạm dừng);
        //   `PartAmount*` cần dòng phụ tùng theo nguồn tiền; các tỉ lệ /khoang /CVDV /ngày ăn theo hai cái trên.
        // `PartAmountOut` CHƯA port: nguồn lấy từ **phiếu XUẤT KHO** (`Ser_Inv_StockOut` + chi tiết),
        //   không phải dòng phụ tùng của lệnh; lại lọc bằng `smpt.TypeName <> N'Phụ kiện'` —
        //   **so khớp theo TÊN loại phụ tùng**, không theo mã ⇒ đổi tên danh mục là hỏng bộ lọc.
        // Còn lại đều cần dữ liệu MiniHTC chưa theo dõi: `WorkHourActualQty` (phút sửa chữa thực tế,
        //   trừ thời gian tạm dừng) — và `WorkHourPerCarRO` ăn theo nó; `PartAmountOut` (phiếu xuất kho).
        // Còn lại đều **chặn bởi dữ liệu**, không phải bởi công thức:
        //   `WorkHourActualQty` (phút sửa chữa thực tế, trừ tạm dừng) — và `WorkHourPerCarRO`,
        //     `LaborProductivity`, `EmploymentRate` đều chia cho nó nên cùng bị chặn;
        //   `PartAmountOut` · `ShellAmountOut` · `AccessoryAmountOut` · `AccessoryAmountAfterVAT`
        //     lấy từ **phiếu xuất kho**, và `RevenuePerAdviser` cộng chúng qua `AllPartAmount`
        //     ⇒ tính bây giờ sẽ ra số **THẤP HƠN thực tế**, nên KHÔNG tính, thà để trống.
        pendingGroups = new[] { "WorkHourActualQty", "WorkHourPerCarRO", "LaborProductivity", "EmploymentRate",
            "PartAmountOut", "ShellAmountOut", "AccessoryAmountOut", "AccessoryAmountAfterVAT", "RevenuePerAdviser" },
        unitPrices = new { upBDN, upSCC, upSCD, upSCS },
        // 🔴 Đơn giá = 0 ⇒ mọi giờ công của nhóm đó bằng 0 (guard của nguồn), KHÔNG phải lỗi tính.
        unitPriceMissing = new[] { upBDN, upSCC, upSCD, upSCS }.Count(v => v == 0m),
        // 🔴 Nguồn ĐÓNG CỨNG 0 cho các chỉ tiêu tách nội bộ: `, 0 CountSCCLocal_SCL` và
        //   `, 0 CountSCCLocal_Khac` (lặp cho BDD/SCD/SCS) ⇒ "số lượt sửa chữa lại" và "khác
        //   (PDI, xe lưu kho, xe lái thử)" **luôn bằng 0 trong MỌI báo cáo**, không phải do thiếu dữ liệu.
        alwaysZeroInSource = new[] { "Count*Local_SCL", "Count*Local_Khac" },
        columnSetNote = allDealers
            ? "Nguồn: job TẤT CẢ đại lý gọi Report_KPICreateX (61 cột) — THIẾU 44 cột so với job một đại lý."
            : "Nguồn: job MỘT đại lý gọi Report_KPICreateX_New20221101 (105 cột) — bộ đầy đủ.",
        note = "Guard kỳ báo cáo so CHUỖI với ngày 1 tháng hiện tại, đúng như nguồn.",
    });
}).RequireAuthorization();

// ===== 🔴 #403 ĐÍNH CHÍNH: nguồn CÓ guard duy nhất (đại lý, năm, tháng) =====
// TRACE 4 tầng của màn `FrmReportCreate_KPI`: form → `DBSerReportKPI.RptKPICreate` (37 tham số)
//   → WS `RptKPICreate` → biz `RptKPICreate` (`BizCarSv.Service.Report.cs:3759`).
//
// 🔴 Chú thích cũ ở đây ghi *"Nguồn không chặn trường nào ở mức biz"* — **SAI**. Đọc biz thấy khối
//   `#region //Check` gọi `CheckExistRptKPIYearMonth(DealerCode, RptYear, RptMonth)`
//   ⇒ **một đại lý chỉ có MỘT báo cáo KPI cho mỗi cặp (năm, tháng)**. Thiếu guard này thì mỗi lần
//     bấm Tạo lại sinh thêm một bản trùng kỳ, và mọi báo cáo tổng hợp đếm hai lần.
// ⚠️ Nguồn gán **luôn luôn** năm cột khung: `DealerCode` · `RptYear` · `RptMonth` · `RptBy` · `Status`;
//   còn **mọi chỉ tiêu số** chỉ gán khi **khác rỗng** (`if (!StringUtils.IsEmpty(...))`) ⇒ ô để trống
//   thành **NULL**, không phải 0. Giữ đúng: DTO dùng kiểu nullable, không ép về 0.
// ⚠️ Ghi bằng `_dbMain.SaveData("Rpt_KPI", dt_KPI)` — **dạng HAI THAM SỐ**, tức ghi mọi cột của
//   DataTable (lệ đã đo ở #374/#381), và chỉ ghi trên **DB Main** (không WH/Dealer).
// ===== 🔴 #404 SỬA BÁO CÁO KPI (`RptKPIUpdate`, `Service.Report.cs:4096`) =====
// Cùng màn `FrmReportCreate_KPI` với #403, nhưng **hai thao tác cư xử KHÁC NHAU** ở hai điểm:
//
// 🔴 1. **GUARD KHÁC NHAU** — và đây là một lỗ hổng của nguồn:
//    · TẠO   dùng `CheckExistRptKPIYearMonth(DealerCode, RptYear, RptMonth)` ⇒ **chống trùng kỳ**.
//    · SỬA   dùng `CheckExistRptKPI(strAutoID)` ⇒ **chỉ kiểm bản ghi có tồn tại**.
//    ⇒ Sửa **được phép dời báo cáo sang một kỳ đã có báo cáo khác** — không ai chặn. Cửa sau đúng
//      vào cái mà guard lúc tạo cố ngăn. Port giữ 1:1 và **báo cờ** khi phát hiện trùng kỳ.
// 🔴 2. **Ô ĐỂ TRỐNG mang HAI nghĩa tuỳ THAO TÁC**:
//    · TẠO: chỉ gán khi khác rỗng (`14` ô) ⇒ để trống thành **NULL**.
//    · SỬA: `if (IsEmpty(x)) x = TConst.Flag.Inactive` với `Inactive = "0"` (`26` ô)
//           ⇒ để trống thành **SỐ 0**.
//    ⇒ Cùng một ô trên cùng một form: tạo xong để trống thì cột NULL, sửa xong để trống thì cột 0.
//      Báo cáo tổng hợp phân biệt NULL với 0 sẽ ra hai kết quả khác nhau tuỳ người dùng bấm gì.
// ⚠️ `alColumnEffective` của SỬA **có liệt kê cột** (khác lệnh TẠO dùng `SaveData` hai tham số).
// ===== 🔴 #405 SỐ KPI **THỰC TẾ** (`RptKPIGetReal`) — và một BẤT ĐỒNG MÃ HOÁ nguy hiểm =====
// TRACE (theo lệ #400, đọc thân từng tầng): form `FrmReportCreate_KPI` → `DBSerReportKPI.RptKPIGetReal`
//   → WS `RptKPIGetReal` → biz **`RptKPIGetReal_New20160602`** (`CampaignMarketing/BizCarSv.ZTemp.cs:2438`).
//   ⚠️ Có bản `RptKPIGetReal` **không hậu tố** ở `Service.Report.cs:4758` — **KHÔNG phải bản LIVE**;
//     đọc nhầm bản đó là chuyện suýt xảy ra ở chính lượt này.
//
// 🔴 **CÙNG MỘT CỘT, HAI BẢNG MÃ KHÁC NHAU** trong cùng cây nguồn:
//   · Bản LIVE (2016) đếm nhân sự bằng **SỐ**: `IsEngineer=1` (cố vấn DV) · `=2` (KTV) · `=3` (KTV đồng sơn)
//     · `=4` (nhân viên khác); và khoang bằng `CavityType=1/2/3`.
//   · Các hàm mới hơn (ví dụ `Report_KPIGet_Real_WH_New20221101`, 2022) so cùng cột đó với **CHUỖI**:
//     `'CVDV'` · `'KTVD'` · `'KTVS'` · `'BDN'` · `'SCC'` · `'KHAC'` · `'NVPT'` (đo được: 20 chỗ dùng số, 45 chỗ dùng chuỗi).
//   ⇒ Nếu dữ liệu hiện dùng mã CHỮ thì **bốn chỉ tiêu nhân sự của màn KPI luôn bằng 0** — đúng kiểu
//     'số 0 câm': báo cáo vẫn chạy, vẫn ra kết quả, chỉ là sai.
// 📌 MiniHTC lưu mã CHỮ (`ServiceEngineer.EngineerType`, `Cavity.CavityType`) ⇒ endpoint đếm theo mã chữ
//   và trả kèm **phân bố mã thực có** để người dùng tự đối chiếu, thay vì im lặng trả 0.
// ===== 🔴 #411 GUARD "ĐỦ 12 THÁNG" TRƯỚC KHI KẾT XUẤT — kiểm tra bằng **VỊ TRÍ DÒNG** =====
// Nguồn: `FrmReportDisplay_KPI.exportToExcelByXML` (`:331`). Trước khi ghi file, form bắt buộc
//   **mọi tháng từ 1 đến tháng hiện tại** của năm đang xem phải có báo cáo KPI đã lưu.
//
// 🔴 Cách kiểm tra **KHÔNG tra theo tháng, mà tra theo CHỈ SỐ DÒNG**:
//     `if (iMonth != Convert.ToInt16(dt.Rows[iMonth - 1][RptMonth])) { cảnh báo; return; }`
//   Tức nó **giả định dòng thứ i-1 chính là tháng i**. Điều đó chỉ đúng nhờ `order by t.RptYear,`
//   `CAST(t.RptMonth AS INT)` ở biz (#410) — một **phụ thuộc ngầm giữa hai tầng**: đổi ORDER BY của
//   truy vấn là guard này sai ngay, mà không ai sửa dòng nào ở form.
//   ⚠️ Truy vấn lọc theo NĂM lấy từ ô `txtNam`. Ô đó **để trống** thì không có mệnh đề năm ⇒ dòng của
//     **nhiều năm** trộn vào nhau, `Rows[0]` là tháng 1 của năm CŨ NHẤT ⇒ guard so nhầm năm mà vẫn
//     có thể **PASS**. Kết xuất ra file với dữ liệu năm khác.
//
// ⚠️ `catch { cảnh báo "tháng N chưa lưu"; return; }` **nuốt MỌI ngoại lệ**, không riêng thiếu dòng.
//   Lỗi ép kiểu (tháng chứa chữ) cũng bị báo thành *"tháng N chưa được lưu"* ⇒ **chẩn đoán sai**,
//   người dùng đi tạo lại báo cáo đã có sẵn.
// ⚠️ Mốc trên là `iMonth < GetServerDateTime().Month + 1` ⇒ tháng 1..tháng HIỆN TẠI **theo giờ SERVER**,
//   không theo năm đang xem: xem năm cũ vào tháng 3 thì chỉ đòi 3 tháng, xem vào tháng 12 thì đòi 12.
// ⚠️ Mẫu file cứng ở `C://DMSTemp//Tmp.KPI.xml` (`File.Copy`) — không có mẫu thì ném lỗi. Không port được.
app.MapGet("/api/reportkpis/export-check", async (AppDbContext db, ITenantContext t,
    string? dealer, string? year, int? upToMonth) =>
{
    if (string.IsNullOrWhiteSpace(dealer))
        return Results.BadRequest(new { error = "Thiếu mã đại lý." });

    var y = (year ?? "").Trim();
    var rows = await db.ReportKpis
        .Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer!.Trim().ToUpperInvariant())
        .Select(x => new { x.RptYear, x.RptMonth }).ToListAsync();
    // Ô năm để TRỐNG ⇒ nguồn KHÔNG lọc năm. Giữ 1:1 và báo cờ.
    var yearFilterMissing = y.Length == 0;
    if (!yearFilterMissing) rows = rows.Where(x => x.RptYear == y).ToList();

    // Thứ tự nguồn (#410): năm tăng, rồi tháng theo SỐ.
    var ordered = rows
        .OrderBy(x => x.RptYear)
        .ThenBy(x => int.TryParse((x.RptMonth ?? "").Trim(), out var mi) ? mi : int.MaxValue)
        .ToList();

    var last = upToMonth ?? DateTime.Now.Month;   // nguồn: tháng hiện tại theo giờ SERVER
    string? firstMissingReason = null;
    int? firstMissingMonth = null;
    for (var m = 1; m <= last; m++)
    {
        // 🔴 TRA THEO VỊ TRÍ, đúng nguồn: dòng thứ m-1 phải là tháng m.
        if (ordered.Count < m)
        {
            firstMissingMonth = m; firstMissingReason = "thiếu dòng ở vị trí " + (m - 1); break;
        }
        if (!int.TryParse((ordered[m - 1].RptMonth ?? "").Trim(), out var got))
        {
            firstMissingMonth = m;
            firstMissingReason = "RptMonth không phải số ('" + ordered[m - 1].RptMonth + "') — nguồn ném "
                + "lỗi ép kiểu rồi BÁO NHẦM thành 'tháng chưa lưu'";
            break;
        }
        if (got != m)
        {
            firstMissingMonth = m;
            firstMissingReason = "vị trí " + (m - 1) + " đang là tháng " + got + ", không phải tháng " + m;
            break;
        }
    }

    var ok = firstMissingMonth == null;
    var yearsPresent = ordered.Select(x => x.RptYear).Distinct().ToList();
    return Results.Ok(new
    {
        dealer, year = y, upToMonth = last, canExport = ok,
        firstMissingMonth, firstMissingReason,
        message = ok ? null : $"Dữ liệu báo cáo KPI của tháng {firstMissingMonth} chưa được lưu.",
        monthsFound = ordered.Select(x => x.RptMonth).ToList(),
        positionalCheckNote = "Nguồn KHÔNG tra theo tháng mà tra theo VỊ TRÍ DÒNG (Rows[i-1] phải là "
            + "tháng i) — chỉ đúng nhờ ORDER BY của biz. Đổi ORDER BY là guard sai ngay, không ai sửa form.",
        yearFilterMissing,
        yearFilterMissingNote = yearFilterMissing
            ? "KHÔNG truyền năm ⇒ nguồn không lọc năm ⇒ dòng NHIỀU NĂM trộn vào nhau, vị trí 0 là tháng 1 "
              + "của năm CŨ NHẤT ⇒ guard có thể PASS nhầm và kết xuất dữ liệu năm khác."
            : null,
        yearsPresent,
        serverMonthNote = "Mốc trên lấy theo tháng HIỆN TẠI của server, không theo năm đang xem: xem năm "
            + "cũ vào tháng 3 thì chỉ đòi 3 tháng, xem vào tháng 12 thì đòi đủ 12.",
        templateNote = "Nguồn còn File.Copy mẫu cứng C://DMSTemp//Tmp.KPI.xml — phần dựng file XML không "
            + "port được sang API.",
    });
}).RequireAuthorization();

// ===== 🔴 #432 CHỐT ĐƯỢC CÂU HỎI TREO TỪ #405: `IsEngineer` lưu **MÃ CHỮ**, không phải số =====
// Bằng chứng nằm trong `SerEmployeeGetStatus` (`BizCarSv.Service.cs:12368`) — hàm nạp danh sách nhân sự
// cho màn báo giá lịch hẹn (`FrmQuotationApp`, bản 2023):
//     `LEFT JOIN [@strDBName_CommonCenter].[dbo].Mst_Staff ms ON sp.**IsEngineer = ms.StaffCode**`
//     `SELECT … ms.StaffName TypeEngineer`
// ⇒ `IsEngineer` **là khoá ngoại trỏ tới `Mst_Staff.StaffCode`** — một **mã loại nhân sự** ở danh mục
//   trung tâm, và tên loại lấy từ `StaffName`. Không phải cờ số 1..4.
// ⇒ Thêm bằng chứng từ nơi GỌI: `FrmQuotationApp` truyền thẳng chuỗi `"CVDV"` vào tham số `strIsEngineer`.
//
// 📌 **KẾT LUẬN cho #405/#412**: dữ liệu hiện dùng **mã chữ** ⇒ hàm KPI 2016
//   (`RptKPIGetReal_New20160602`) so `IsEngineer = 1..4` sẽ **không khớp dòng nào** ⇒ bốn chỉ tiêu nhân sự
//   của màn KPI **luôn bằng 0**. Đây chính là "số 0 câm" đã cảnh báo ở #405 — nay có căn cứ, không còn là
//   giả thuyết. MiniHTC đang đếm theo mã chữ ⇒ **đúng hướng**; `mappingUnverifiedNote` vẫn giữ vì bảng ánh
//   xạ số→chữ (1↔CVDV…) thì chưa có nguồn nào xác nhận, chỉ suy từ chú thích.
//
// 🔴 **VÀ MỘT LỖI SỐNG PHÁT HIỆN KÈM** (cùng gốc #427/#428 — lần thứ BA):
//   Tầng service dựng `strIsEngineerConditionList = "=" + strIsEngineer` ⇒ `"=CVDV"`,
//   nhưng biz đưa nó vào `SqlUtils.BuildClauseConditionList("and", "sp.IsEngineer", …, "|")` —
//   hàm **KHÔNG đọc toán tử**, mọi token đều thành GIÁ TRỊ ⇒ SQL thành `sp.IsEngineer in (N'=CVDV')`
//   ⇒ **không khớp gì**. Nghĩa là danh sách **cố vấn dịch vụ trên màn báo giá lịch hẹn là RỖNG**.
//   Ba ô lọc khác cùng hàm (`EngineerID`, `EngineerNo`, `EngineerName`) đi qua `BuildClause` nên **chạy đúng**.
//
// 📌 **KẾT QUẢ ÂM TÍNH đã kiểm**: `strStatus` truyền **trần** `"1"` — theo lệ #410 tưởng chết câm, **nhưng**
//   biz **không** đưa nó qua `BuildClause` mà tự viết tay `if (strStatusConditionList == "1") …` ⇒ **chạy đúng**.
//
// 🔴 **HAI ĐỊNH NGHĨA "ĐANG LÀM VIỆC" KHÁC NHAU trong cùng hệ**:
//   · `SerEmployeeGetStatus` (trạng thái "1"): `StartWorkDate is null **or** = ''` **VẪN TÍNH LÀ ĐANG LÀM**;
//   · `RptKPIGetReal_New20160602` (#412): đòi `substring(StartWorkDate,1,7) <= kỳ` ⇒ ngày trống **BỊ LOẠI**.
//   ⇒ Nhân sự chưa khai ngày vào làm **có mặt ở màn báo giá nhưng biến mất khỏi KPI**. Cùng một người,
//     hai màn trả lời khác nhau câu hỏi "đang làm việc?".
app.MapGet("/api/serviceengineers/by-type", async (AppDbContext db, ITenantContext t,
    string? engineerType, string? status, string? dealer) =>
{
    var all = await db.ServiceEngineers.Where(e => e.OrgId == t.OrgId
            && (dealer == null || e.DealerCode == dealer)).ToListAsync();

    // Lọc theo MÃ LOẠI NHÂN SỰ (mã chữ, khoá ngoại tới Mst_Staff.StaffCode).
    var typeQ = (engineerType ?? "").Trim();
    var byType = typeQ.Length == 0 ? all
        : all.Where(e => string.Equals(e.EngineerType, typeQ, StringComparison.OrdinalIgnoreCase)).ToList();

    // Trạng thái làm việc — nguồn tự viết tay SQL, KHÔNG qua BuildClause.
    var now = DateTime.Now;
    bool Working(ServiceEngineer e)
        => e.StartWorkDate == null                                   // 🔴 ngày trống = ĐANG LÀM (theo màn này)
        || (e.StartWorkDate <= now && e.FinishWorkDate == null)
        || (e.StartWorkDate <= now && e.FinishWorkDate >= now);

    var rows = status switch
    {
        "1" => byType.Where(Working).ToList(),
        "2" => byType.Where(e => !Working(e)).ToList(),
        _ => byType,
    };

    var noStartDate = byType.Count(e => e.StartWorkDate == null);
    var typeDistribution = all.GroupBy(e => e.EngineerType ?? "(null)")
        .Select(g => new { code = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();

    return Results.Ok(new
    {
        count = rows.Count,
        rows = rows.Select(e => new
        {
            e.EngineerNo, e.EngineerName, e.EngineerType, e.GroupRCode, e.DealerCode,
            e.Status, e.StartWorkDate, e.FinishWorkDate,
        }),
        typeDistribution,
        isEngineerIsCodeNote = "CHỐT #405: IsEngineer là KHOÁ NGOẠI tới Mst_Staff.StaffCode (mã CHỮ), "
            + "bằng chứng: LEFT JOIN Mst_Staff ms ON sp.IsEngineer = ms.StaffCode, và màn FrmQuotationApp "
            + "truyền thẳng chuỗi \"CVDV\". ⇒ Hàm KPI 2016 so IsEngineer = 1..4 KHÔNG khớp dòng nào ⇒ bốn "
            + "chỉ tiêu nhân sự của màn KPI luôn bằng 0.",
        sourceTypeFilterBroken = true,
        sourceTypeFilterNote = "Trong NGUỒN, bộ lọc loại nhân sự HỎNG: service dựng \"=CVDV\" rồi đưa vào "
            + "BuildClauseConditionList (hàm KHÔNG đọc toán tử) ⇒ SQL thành sp.IsEngineer in (N'=CVDV') "
            + "⇒ không khớp gì ⇒ danh sách cố vấn dịch vụ trên màn báo giá lịch hẹn là RỖNG. Ba ô lọc khác "
            + "cùng hàm đi qua BuildClause nên chạy đúng. Đây là lần thứ BA của cùng một gốc (#427/#428).",
        statusFilterOkNote = "KẾT QUẢ ÂM TÍNH: strStatus truyền trần \"1\" — tưởng chết câm theo lệ #410, "
            + "nhưng biz KHÔNG dùng BuildClause mà tự viết tay if (strStatusConditionList == \"1\") ⇒ chạy đúng.",
        noStartDate,
        workingDefinitionConflictNote = "HAI định nghĩa 'đang làm việc' khác nhau: màn này coi "
            + "StartWorkDate rỗng LÀ ĐANG LÀM; còn RptKPIGetReal (#412) đòi StartWorkDate <= kỳ nên ngày "
            + "trống BỊ LOẠI ⇒ nhân sự chưa khai ngày vào làm có mặt ở màn báo giá nhưng biến mất khỏi KPI.",
    });
}).RequireAuthorization();

app.MapGet("/api/reportkpis/real", async (AppDbContext db, ITenantContext t,
    string? dealer, string? year, string? month) =>
{
    if (string.IsNullOrWhiteSpace(dealer))
        return Results.BadRequest(new { error = "Thiếu mã đại lý." });

    // ===== 🔴 #412 ĐÍNH CHÍNH #405: nhân sự phải đếm **TẠI THỜI ĐIỂM CỦA KỲ**, không phải hiện tại =====
    // Đọc lại thân `RptKPIGetReal_New20160602` (`ZTemp.cs:2438`) cho phần tôi bỏ sót ở #405:
    //   `or ((substring(e.StartWorkDate,1,7) <= '@RptMonth' and e.FinishWorkDate is null))`
    //   `or ((substring(e.StartWorkDate,1,7) <= '@RptMonth' and substring(e.FinishWorkDate,1,7) >= '@RptMonth'))`
    //   và y hệt cho khoang với `StartUseDate`/`FinishUseDate`.
    // ⇒ Đây là **ảnh chụp NHÂN SỰ CỦA THÁNG ĐÓ**: người vào sau kỳ **không** được tính, người đã nghỉ
    //   trước kỳ **không** được tính, người còn làm (`FinishWorkDate is null`) thì tính.
    // 🔴 Bản #405 đếm **toàn bộ nhân sự hiện tại** ⇒ mở lại báo cáo KPI của một kỳ CŨ sẽ ra **số của hôm
    //   nay**, không phải số của kỳ đó. Báo cáo quá khứ **tự đổi giá trị theo thời gian** — sai câm.
    // ⚠️ Nguồn so bằng `substring(...,1,7)` ⇒ **so CHUỖI `yyyy-MM`**, giữ nguyên cách so đó.
    // ⚠️ Nguồn đệm số 0 cho tháng một chữ số bằng `TConst.Flag.Inactive` — một hằng tên là **"Inactive"**
    //   dùng làm **ký tự số 0**. Tên hằng nói một đằng, công dụng một nẻo.
    // ⚠️ `strRptYear.Substring(2, 2)` ⇒ năm dưới 4 ký tự là **ném lỗi**; và mã kỳ ghép lại (`"2609"`)
    //   được dùng để lọc `t.rono like '%-@RptYearMonth%'` — tức **lọc kỳ bằng cách bóc chuỗi SỐ RO**,
    //   không phải bằng cột ngày. Đổi quy tắc đánh số RO là hỏng toàn bộ báo cáo này.
    var mm = (month ?? "").Trim();
    if (mm.Length == 1) mm = "0" + mm;              // đúng nguồn: đệm 0 cho tháng một chữ số
    var yy = (year ?? "").Trim();
    var periodKey = yy.Length == 4 && mm.Length == 2 ? yy + "-" + mm : null;   // "yyyy-MM"
    var yearTooShort = yy.Length > 0 && yy.Length < 4;
    var roYearMonth = yy.Length >= 4 && mm.Length == 2 ? yy.Substring(2, 2) + mm : null;

    // Cửa sổ hiệu lực: bắt đầu <= kỳ, VÀ (chưa kết thúc HOẶC kết thúc >= kỳ). So CHUỖI yyyy-MM.
    bool InPeriod(string? start, string? finish)
    {
        if (periodKey == null) return true;                       // không đủ kỳ ⇒ không lọc (đúng nguồn)
        var s = (start ?? "");
        if (s.Length < 7 || string.CompareOrdinal(s.Substring(0, 7), periodKey) > 0) return false;
        var f = (finish ?? "");
        if (f.Length < 7) return true;                            // FinishDate is null ⇒ còn hiệu lực
        return string.CompareOrdinal(f.Substring(0, 7), periodKey) >= 0;
    }

    var engineersAll = await db.ServiceEngineers
        .Where(e => e.OrgId == t.OrgId && e.DealerCode == dealer)
        .Select(e => new { e.EngineerType, e.StartWorkDate, e.FinishWorkDate }).ToListAsync();
    var cavitiesAll = await db.Cavities
        .Where(c => c.OrgId == t.OrgId && c.DealerCode == dealer)
        .Select(c => new { c.CavityType, c.StartUseDate, c.FinishUseDate }).ToListAsync();

    var engineers = engineersAll.Where(e => InPeriod(
            e.StartWorkDate?.ToString("yyyy-MM"), e.FinishWorkDate?.ToString("yyyy-MM")))
        .Select(e => new { e.EngineerType }).ToList();
    var cavities = cavitiesAll.Where(c => InPeriod(c.StartUseDate, c.FinishUseDate))
        .Select(c => new { c.CavityType }).ToList();
    var engineersExcludedByPeriod = engineersAll.Count - engineers.Count;
    var cavitiesExcludedByPeriod = cavitiesAll.Count - cavities.Count;

    int NE(params string[] codes) => engineers.Count(e => e.EngineerType != null && codes.Contains(e.EngineerType));
    int NC(params string[] codes) => cavities.Count(c => c.CavityType != null && codes.Contains(c.CavityType));

    return Results.Ok(new
    {
        dealer, year, month,
        // Bốn chỉ tiêu NHÂN SỰ — nguồn LIVE đếm bằng số 1..4, MiniHTC đếm bằng mã chữ tương ứng.
        advisoryNumber = NE("CVDV"),
        enginerNumber = NE("KTVD"),
        enginerBP = NE("KTVS"),
        staffOrther = NE("NVPT", "KHAC"),
        // Ba chỉ tiêu KHOANG — nguồn LIVE đếm bằng CavityType 1/2/3.
        cavityRONumber = NC("SCC"),
        cavityBPNumber = NC("BS"),
        cavityParkingNumber = NC("KD"),
        // Phân bố mã THỰC CÓ trong dữ liệu — để đối chiếu, không đoán.
        engineerTypeDistribution = engineers.GroupBy(e => e.EngineerType ?? "(null)")
            .Select(g => new { code = g.Key, count = g.Count() }).OrderByDescending(x => x.count),
        cavityTypeDistribution = cavities.GroupBy(c => c.CavityType ?? "(null)")
            .Select(g => new { code = g.Key, count = g.Count() }).OrderByDescending(x => x.count),
        // #412 các cờ về CỬA SỔ HIỆU LỰC theo kỳ
        periodKey, engineersExcludedByPeriod, cavitiesExcludedByPeriod,
        periodScopeNote = periodKey == null
            ? "KHÔNG đủ (năm 4 chữ số + tháng) ⇒ không lọc theo kỳ, đếm toàn bộ — giống nguồn khi thiếu tham số."
            : "Chỉ đếm nhân sự/khoang CÓ HIỆU LỰC trong kỳ " + periodKey + " (bắt đầu <= kỳ, và chưa kết "
              + "thúc hoặc kết thúc >= kỳ). Bản #405 đếm toàn bộ hiện tại ⇒ báo cáo kỳ cũ tự đổi số theo "
              + "thời gian; nay đã sửa.",
        yearTooShort,
        yearTooShortNote = yearTooShort
            ? "Năm dưới 4 ký tự: nguồn gọi strRptYear.Substring(2,2) ⇒ NÉM LỖI. MiniHTC không ném, chỉ báo cờ."
            : null,
        roYearMonth,
        roNumberFilterNote = "Nguồn còn lọc kỳ bằng t.rono like '%-<yyMM>%' — BÓC CHUỖI SỐ RO chứ không "
            + "dùng cột ngày. Đổi quy tắc đánh số RO là hỏng toàn bộ báo cáo này. MiniHTC chưa mô hình hoá "
            + "quy tắc đánh số RO nên KHÔNG áp bộ lọc đó — ghi rõ thay vì giả vờ đủ.",
        padConstantNote = "Nguồn đệm 0 cho tháng một chữ số bằng hằng TConst.Flag.Inactive — hằng tên "
            + "'Inactive' dùng làm KÝ TỰ SỐ 0.",
        encodingConflict = true,
        encodingNote = "Cùng cột IsEngineer/CavityType: bản LIVE (2016) so với SỐ 1..4, các hàm 2022 so với "
            + "CHUỖI (CVDV/KTVD/KTVS/BDN/SCC/KHAC/NVPT). Đo được 20 chỗ dùng số, 45 chỗ dùng chuỗi.",
        zeroRiskNote = "Nếu dữ liệu dùng mã CHỮ thì bốn chỉ tiêu nhân sự của bản LIVE luôn bằng 0 — báo cáo "
            + "vẫn chạy, chỉ là sai. Xem *Distribution để biết mã thực tế đang có.",
        mappingUnverifiedNote = "Ánh xạ số→chữ (1↔CVDV, 2↔KTVD, 3↔KTVS, 4↔NVPT/KHAC; khoang 1↔SCC, 2↔BS, "
            + "3↔KD) suy từ chú thích nguồn, CHƯA đối chiếu được với dữ liệu thật — cần nghiệp vụ xác nhận.",
        liveTwinNote = "Bản LIVE là RptKPIGetReal_New20160602 (ZTemp.cs:2438); bản không hậu tố ở "
            + "Service.Report.cs:4758 KHÔNG phải bản WS gọi.",
    });
}).RequireAuthorization();

app.MapPut("/api/reportkpis/{id:long}", async (long id, ReportKpiDto dto, AppDbContext db, ITenantContext t) =>
{
    var r = await db.ReportKpis.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (r is null) return Results.NotFound(new { id });

    // Bốn cột khung: SỬA gán VÔ ĐIỀU KIỆN (nằm đầu alColumnEffective của nguồn).
    r.RptYear = dto.RptYear; r.RptMonth = dto.RptMonth; r.RptBy = dto.RptBy;
    if (!string.IsNullOrWhiteSpace(dto.Status)) r.Status = dto.Status;
    if (!string.IsNullOrWhiteSpace(dto.DealerCode)) r.DealerCode = dto.DealerCode;

    // 🔴 Ô để trống ⇒ SỐ 0 (khác lệnh TẠO để NULL). Áp cho MỌI chỉ tiêu số.
    var eProps = typeof(ReportKpi).GetProperties()
        .Where(p => p.CanWrite && (p.PropertyType == typeof(decimal?) || p.PropertyType == typeof(decimal)))
        .ToDictionary(p => p.Name);
    var zeroed = new List<string>(); var copied = 0;
    foreach (var dp in typeof(ReportKpiDto).GetProperties())
    {
        if (!eProps.TryGetValue(dp.Name, out var ep)) continue;
        var v = dp.GetValue(dto);
        if (v is null) { ep.SetValue(r, ep.PropertyType == typeof(decimal?) ? (decimal?)0m : 0m); zeroed.Add(dp.Name); }
        else { ep.SetValue(r, v); copied++; }
    }

    // Nguồn KHÔNG chặn trùng kỳ khi sửa — vẫn lưu, nhưng ta báo ra.
    var periodClash = !string.IsNullOrWhiteSpace(r.DealerCode)
        && !string.IsNullOrWhiteSpace(r.RptYear) && !string.IsNullOrWhiteSpace(r.RptMonth)
        && await db.ReportKpis.AnyAsync(x => x.OrgId == t.OrgId && x.Id != r.Id
            && x.DealerCode == r.DealerCode && x.RptYear == r.RptYear && x.RptMonth == r.RptMonth);

    r.LogLUDateTime = DateTime.Now; r.LogLUBy = dto.RptBy;
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        r.Id, r.DealerCode, r.RptYear, r.RptMonth, r.Status,
        figuresCopied = copied, figuresZeroed = zeroed.Count,
        emptyMeansZeroNote = "Khi SỬA, ô để trống thành SỐ 0 (nguồn: `if (IsEmpty(x)) x = Flag.Inactive`, "
            + "Inactive = \"0\"). Khác lệnh TẠO — ở đó ô trống để NULL.",
        periodClash,
        periodClashNote = periodClash
            ? "Kỳ này ĐÃ CÓ báo cáo khác. Nguồn KHÔNG chặn khi sửa (guard lúc sửa chỉ kiểm bản ghi tồn tại) "
              + "⇒ giữ 1:1 và chỉ báo cờ; đây là cửa sau vòng qua guard chống trùng kỳ lúc tạo."
            : null,
        guardDiffNote = "TẠO dùng CheckExistRptKPIYearMonth (chống trùng kỳ); SỬA dùng CheckExistRptKPI "
            + "(chỉ kiểm tồn tại) — hai thao tác, hai guard khác nhau.",
    });
}).RequireAuthorization();

app.MapPost("/api/reportkpis", async (ReportKpiDto dto, AppDbContext db, ITenantContext t) =>
{
    // 🔴 #403 Guard của nguồn: KHÔNG cho hai báo cáo cùng (đại lý, năm, tháng).
    if (!string.IsNullOrWhiteSpace(dto.DealerCode)
        && !string.IsNullOrWhiteSpace(dto.RptYear) && !string.IsNullOrWhiteSpace(dto.RptMonth))
    {
        var dup = await db.ReportKpis.AnyAsync(x => x.OrgId == t.OrgId
            && x.DealerCode == dto.DealerCode
            && x.RptYear == dto.RptYear && x.RptMonth == dto.RptMonth);
        if (dup)
            return Results.BadRequest(new
            {
                error = "Ser_RptKPI_Create_Exist",
                message = "Đại lý này đã có báo cáo KPI cho kỳ (năm, tháng) đó.",
                dto.DealerCode, dto.RptYear, dto.RptMonth,
            });
    }

    var r = new ReportKpi
    {
        OrgId = t.OrgId,
        // #403 §12 kỳ báo cáo
        RptYear = dto.RptYear, RptMonth = dto.RptMonth, RptBy = dto.RptBy,
        AccessoryAmountAfterVAT = dto.AccessoryAmountAfterVAT,
        AccessoryAmountOut = dto.AccessoryAmountOut,
        AdvisoryNumber = dto.AdvisoryNumber,
        ApprovedBy = dto.ApprovedBy,
        ApprovedDate = dto.ApprovedDate,
        CabinetPaintNumber = dto.CabinetPaintNumber,
        CarPerAdviserDay = dto.CarPerAdviserDay,
        CavityBPNumber = dto.CavityBPNumber,
        CavityCopperNumber = dto.CavityCopperNumber,
        CavityMaintainNumber = dto.CavityMaintainNumber,
        CavityOtherNumber = dto.CavityOtherNumber,
        CavityParkingNumber = dto.CavityParkingNumber,
        CavityQtyPerEngineerBDNSCC = dto.CavityQtyPerEngineerBDNSCC,
        CavityRONumber = dto.CavityRONumber,
        CountBDD = dto.CountBDD,
        CountBDDLocal = dto.CountBDDLocal,
        CountBDDPerCavityMaintain = dto.CountBDDPerCavityMaintain,
        CountBDDRoRepair = dto.CountBDDRoRepair,
        CountCarService = dto.CountCarService,
        CountSCC = dto.CountSCC,
        CountSCCLocal = dto.CountSCCLocal,
        CountSCCPerCavityRO = dto.CountSCCPerCavityRO,
        CountSCCRoInsurance = dto.CountSCCRoInsurance,
        CountSCCRoRepair = dto.CountSCCRoRepair,
        CountSCCRoWarranty = dto.CountSCCRoWarranty,
