// 🔴 Save: cờ FlagIsDelete = "1" thì xoá CẢ SÁU bảng; ngược lại xoá rồi chèn lại cả sáu.
app.MapPost("/api/mrkcampaigndls/save", async (MrkCampaignDLSaveDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var dealer = (dto.DealerCode ?? "").Trim();
    var year = (dto.MRKCamDLYear ?? "").Trim();
    var quarter = (dto.MRKCamDLQuarter ?? "").Trim();
    if (dealer.Length < 1) return Results.BadRequest(new { error = "Mã đại lý rỗng." });
    if (year.Length < 1) return Results.BadRequest(new { error = "Năm rỗng." });
    if (quarter.Length < 1) return Results.BadRequest(new { error = "Quý rỗng." });

    var cur = await db.MrkCampaignDLs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId
        && x.DealerCode == dealer && x.MRKCamDLYear == year && x.MRKCamDLQuarter == quarter);
    if (cur is not null && cur.MRKCamDLStatus != "P")
        return Results.BadRequest(new { error = $"Chiến dịch đại lý đang {cur.MRKCamDLStatus}, chỉ sửa/xoá được khi 'P'." });

    // Gom sẵn bản ghi cũ của cả sáu bảng theo khoá ba.
    var oldReg = await db.MrkCampaignDLRegisters.Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer && x.MRKCamDLYear == year && x.MRKCamDLQuarter == quarter).ToListAsync();
    var oldRegDtl = await db.MrkCampaignDLRegisterDtls.Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer && x.MRKCamDLYear == year && x.MRKCamDLQuarter == quarter).ToListAsync();
    var oldAct = await db.MrkCampaignDLActuals.Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer && x.MRKCamDLYear == year && x.MRKCamDLQuarter == quarter).ToListAsync();
    var oldActDtl = await db.MrkCampaignDLActualDtls.Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer && x.MRKCamDLYear == year && x.MRKCamDLQuarter == quarter).ToListAsync();
    var oldQKPI = await db.MrkCampaignDLQuarterKPIs.Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer && x.MRKCamDLYear == year && x.MRKCamDLQuarter == quarter).ToListAsync();

    var isDelete = (dto.FlagIsDelete ?? "").Trim() == "1";
    if (isDelete && cur is null)
        return Results.Ok(new { deleted = 0, note = "Không có bản ghi — nguồn coi là thành công." });

    var createdAt = cur?.CreateDateTime ?? DateTime.Now;
    var createdBy = cur?.CreateBy;
    db.MrkCampaignDLRegisters.RemoveRange(oldReg);
    db.MrkCampaignDLRegisterDtls.RemoveRange(oldRegDtl);
    db.MrkCampaignDLActuals.RemoveRange(oldAct);
    db.MrkCampaignDLActualDtls.RemoveRange(oldActDtl);
    db.MrkCampaignDLQuarterKPIs.RemoveRange(oldQKPI);
    if (cur is not null) db.MrkCampaignDLs.Remove(cur);
    if (isDelete)
    {
        await db.SaveChangesAsync();
        return Results.Ok(new { deleted = 1, dealer, year, quarter });
    }
    await db.SaveChangesAsync();

    var now = DateTime.Now;
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    db.MrkCampaignDLs.Add(new MrkCampaignDL
    {
        OrgId = t.OrgId, DealerCode = dealer, MRKCamDLYear = year, MRKCamDLQuarter = quarter,
        BonusPoint = dto.BonusPoint, ObligationKPI = dto.ObligationKPI, KPIRank = dto.KPIRank,
        RegisterFilePath = dto.RegisterFilePath, ResultFilePath = dto.ResultFilePath,
        MRKCamDLStatus = "P", Remark = dto.Remark,
        LUDateTime = now, LUBy = who,
        CreateDateTime = createdAt, CreateBy = createdBy ?? who,
        LogLUDateTime = now, LogLUBy = who,
    });
    foreach (var r in dto.Registers ?? new())
        db.MrkCampaignDLRegisters.Add(new MrkCampaignDLRegister
        {
            OrgId = t.OrgId, MRKCamDLRegisterNo = (r.MRKCamDLRegisterNo ?? "").Trim(),
            DealerCode = dealer, MRKCamDLYear = year, MRKCamDLQuarter = quarter,
            MRKPICamDLRegisterName = r.MRKPICamDLRegisterName,
            RegisterFilePath = r.RegisterFilePath, ReportFilePath = r.ReportFilePath,
            EffDateStart = r.EffDateStart, EffDateEnd = r.EffDateEnd, ReportDateEnd = r.ReportDateEnd,
            MRKCamDLStatusRegister = "P", Remark = r.Remark, LogLUDateTime = now, LogLUBy = who,
        });
    foreach (var r in dto.RegisterDtls ?? new())
        db.MrkCampaignDLRegisterDtls.Add(new MrkCampaignDLRegisterDtl
        {
            OrgId = t.OrgId, MRKCamDLRegisterNo = (r.MRKCamDLRegisterNo ?? "").Trim(),
            DealerCode = dealer, MRKCamDLYear = year, MRKCamDLQuarter = quarter,
            KPICode = (r.KPICode ?? "").Trim(), KPIType = r.KPIType,
            QtyRegister = r.QtyRegister, ValQualityRegister = r.ValQualityRegister,
            MRKCamDLStatusRegisterDtl = "P", LogLUDateTime = now, LogLUBy = who,
        });
    foreach (var r in dto.Actuals ?? new())
        db.MrkCampaignDLActuals.Add(new MrkCampaignDLActual
        {
            OrgId = t.OrgId, MRKCamDLActualNo = (r.MRKCamDLActualNo ?? "").Trim(),
            DealerCode = dealer, MRKCamDLYear = year, MRKCamDLQuarter = quarter,
            MRKPICamDLActualName = r.MRKPICamDLActualName,
            RegisterFilePath = r.RegisterFilePath, ReportFilePath = r.ReportFilePath,
            EffDateStart = r.EffDateStart, EffDateEnd = r.EffDateEnd, ReportDateEnd = r.ReportDateEnd,
            MRKCamDLStatusActual = "P", Remark = r.Remark, LogLUDateTime = now, LogLUBy = who,
        });
    foreach (var r in dto.ActualDtls ?? new())
        db.MrkCampaignDLActualDtls.Add(new MrkCampaignDLActualDtl
        {
            OrgId = t.OrgId, MRKCamDLActualNo = (r.MRKCamDLActualNo ?? "").Trim(),
            DealerCode = dealer, MRKCamDLYear = year, MRKCamDLQuarter = quarter,
            KPICode = (r.KPICode ?? "").Trim(), KPIType = r.KPIType,
            QtyActual = r.QtyActual, ValQualityActual = r.ValQualityActual,
            MRKCamDLStatusActualDtl = "P", LogLUDateTime = now, LogLUBy = who,
        });
    foreach (var r in dto.QuarterKPIs ?? new())
        db.MrkCampaignDLQuarterKPIs.Add(new MrkCampaignDLQuarterKPI
        {
            OrgId = t.OrgId, DealerCode = dealer, MRKCamDLYear = year, MRKCamDLQuarter = quarter,
            KPICode = (r.KPICode ?? "").Trim(), KPIType = r.KPIType,
            RegisterStandardPoint = r.RegisterStandardPoint,
            TotalQtyRegister = r.TotalQtyRegister, TotalQtyActual = r.TotalQtyActual,
            AvgValQualityActual = r.AvgValQualityActual, ActualPoint = r.ActualPoint,
            MRKCamDLStatusQKPI = "P", Remark = r.Remark, LogLUDateTime = now, LogLUBy = who,
        });
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        dealer, year, quarter, status = "P",
        registers = (dto.Registers ?? new()).Count, registerDtls = (dto.RegisterDtls ?? new()).Count,
        actuals = (dto.Actuals ?? new()).Count, actualDtls = (dto.ActualDtls ?? new()).Count,
        quarterKPIs = (dto.QuarterKPIs ?? new()).Count,
    });
}).RequireAuthorization();

// 🔴 Update CHỈ sửa ba trường; các cột điểm do hệ thống tính nên KHÔNG nhận từ client.
app.MapPost("/api/mrkcampaigndls/update", async (MrkCampaignDLUpdateDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var dealer = (dto.DealerCode ?? "").Trim();
    var year = (dto.MRKCamDLYear ?? "").Trim();
    var quarter = (dto.MRKCamDLQuarter ?? "").Trim();
    var row = await db.MrkCampaignDLs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId
        && x.DealerCode == dealer && x.MRKCamDLYear == year && x.MRKCamDLQuarter == quarter);
    if (row is null) return Results.NotFound(new { error = $"Không có chiến dịch đại lý {dealer}/{year}/{quarter}." });
    if (row.MRKCamDLStatus != "P")
        return Results.BadRequest(new { error = $"Đang {row.MRKCamDLStatus}, chỉ sửa được khi 'P'." });

    row.BonusPoint = dto.BonusPoint;
    row.ObligationKPI = dto.ObligationKPI;
    row.KPIRank = dto.KPIRank;

    // ===== 🔴 #345 TÍNH LẠI 5 CỘT TỔNG HỢP — port cũ chỉ ghi 3 trường người dùng nhập =====
    // Nguồn `myMRK_CampaignDL_Update` (`BizHTC.Marketing.cs:8365`, bản canonical `.Release.2025`,
    //   md5 giống hệt 2 máy). Năm cột này được ghi bằng **SQL `update … set`** (dạng ghi thứ 4,
    //   lệ #314) nên máy quét đếm theo `["X"] =` **không thấy** — phải grep thêm `t.Col = f.Col`.
    //
    // Nguồn số liệu: `MRK_CampaignDLQuarterKPI` của **đúng** (đại lý, năm, quý), tách theo `KPIType`:
    //   `SalePromotionPoint` = SUM(`ActualPoint`) khi `KPIType = 'SALEPROMOTION'`
    //   `BrandingPoint`      = SUM(`ActualPoint`) khi `KPIType = 'BRANDING'`
    //   `TotalRegisterPoint` = SUM(`RegisterStandardPoint`) — **KHÔNG lọc KPIType** (cả hai loại)
    //   `TotalRealPoint`     = SalePromotion + Branding + **BonusPoint**
    //   `DegreeCompletionKPI`= TotalRealPoint / TotalRegisterPoint
    // ⚠️ `BonusPoint` vừa được người dùng sửa ở ngay trên và là **đầu vào** của `TotalRealPoint`
    //   ⇒ bắt buộc tính lại SAU khi gán, không phải trước.
    var kpis = await db.MrkCampaignDLQuarterKPIs
        .Where(k => k.OrgId == t.OrgId && k.DealerCode == dealer
            && k.MRKCamDLYear == year && k.MRKCamDLQuarter == quarter)
        .Select(k => new { k.KPIType, k.ActualPoint, k.RegisterStandardPoint }).ToListAsync();

    row.SalePromotionPoint = kpis.Where(k => k.KPIType == "SALEPROMOTION").Sum(k => k.ActualPoint);
    row.BrandingPoint = kpis.Where(k => k.KPIType == "BRANDING").Sum(k => k.ActualPoint);
    row.TotalRegisterPoint = kpis.Sum(k => k.RegisterStandardPoint);
    row.TotalRealPoint = row.SalePromotionPoint + row.BrandingPoint + row.BonusPoint;

    // 🔴 LỆCH CÓ CHỦ ĐÍCH: nguồn chia THẲNG, **không guard mẫu = 0**:
    //   `((f.SalePromotionPoint + f.BrandingPoint + t.BonusPoint) / f.TotalRegisterPoint) DegreeCompletionKPI`
    //   ⇒ đại lý chưa đăng ký điểm nào (`TotalRegisterPoint = 0`) sẽ làm **CẢ CÂU UPDATE ném lỗi**
    //     chia-cho-không, hỏng luôn những đại lý khác trong cùng mẻ. Khác hẳn các tỉ lệ KPI xưởng
    //     dịch vụ (#338) vốn đều có `case when <mẫu> = 0 then 0`.
    //   ⇒ Không bắt chước (lệ #272/#275): trả 0 và **báo cờ** để chỗ đối chiếu biết vì sao web có số
    //     mà WinForm thì lỗi.
    var noRegisterPoint = row.TotalRegisterPoint == 0m;
    row.DegreeCompletionKPI = noRegisterPoint ? 0m : row.TotalRealPoint / row.TotalRegisterPoint;
    row.LUDateTime = DateTime.Now;
    row.LUBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    row.LogLUDateTime = row.LUDateTime.Value; row.LogLUBy = row.LUBy;
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        dealer, year, quarter, row.BonusPoint, row.ObligationKPI, row.KPIRank,
        // #345 §12: năm cột tổng hợp vừa tính lại phải NHÌN THẤY ĐƯỢC ở kết quả.
        row.SalePromotionPoint, row.BrandingPoint, row.TotalRegisterPoint,
        row.TotalRealPoint, row.DegreeCompletionKPI,
        // 🔴 Đại lý chưa đăng ký điểm nào: nguồn CHIA CHO 0 ⇒ cả câu update ném lỗi;
        //   web trả 0 và bật cờ này để lệch là lệch nhìn thấy được.
        noRegisterPoint,
        degreeNote = noRegisterPoint
            ? "TotalRegisterPoint = 0 ⇒ web trả DegreeCompletionKPI = 0; nguồn sẽ LỖI chia-cho-không."
            : null,
    });
}).RequireAuthorization();

// 🔴 Approve đồng bộ trạng thái xuống CẢ NĂM bảng con.
app.MapPost("/api/mrkcampaigndls/approve", async (MrkCampaignDLKeyDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var dealer = (dto.DealerCode ?? "").Trim();
    var year = (dto.MRKCamDLYear ?? "").Trim();
    var quarter = (dto.MRKCamDLQuarter ?? "").Trim();
    var row = await db.MrkCampaignDLs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId
        && x.DealerCode == dealer && x.MRKCamDLYear == year && x.MRKCamDLQuarter == quarter);
    if (row is null) return Results.NotFound(new { error = $"Không có chiến dịch đại lý {dealer}/{year}/{quarter}." });
    if (row.MRKCamDLStatus != "P")
        return Results.BadRequest(new { error = $"Đang {row.MRKCamDLStatus}, chỉ duyệt được khi 'P'." });

    var now = DateTime.Now;
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    row.MRKCamDLStatus = "A"; row.ApproveDateTime = now; row.ApproveBy = who;
    row.LogLUDateTime = now; row.LogLUBy = who;
    var reg = await db.MrkCampaignDLRegisters.Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer && x.MRKCamDLYear == year && x.MRKCamDLQuarter == quarter).ToListAsync();
    foreach (var r in reg) { r.MRKCamDLStatusRegister = "A"; r.LogLUDateTime = now; r.LogLUBy = who; }
    var regDtl = await db.MrkCampaignDLRegisterDtls.Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer && x.MRKCamDLYear == year && x.MRKCamDLQuarter == quarter).ToListAsync();
    foreach (var r in regDtl) { r.MRKCamDLStatusRegisterDtl = "A"; r.LogLUDateTime = now; r.LogLUBy = who; }
    var act = await db.MrkCampaignDLActuals.Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer && x.MRKCamDLYear == year && x.MRKCamDLQuarter == quarter).ToListAsync();
    foreach (var r in act) { r.MRKCamDLStatusActual = "A"; r.LogLUDateTime = now; r.LogLUBy = who; }
    var actDtl = await db.MrkCampaignDLActualDtls.Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer && x.MRKCamDLYear == year && x.MRKCamDLQuarter == quarter).ToListAsync();
    foreach (var r in actDtl) { r.MRKCamDLStatusActualDtl = "A"; r.LogLUDateTime = now; r.LogLUBy = who; }
    var qkpi = await db.MrkCampaignDLQuarterKPIs.Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer && x.MRKCamDLYear == year && x.MRKCamDLQuarter == quarter).ToListAsync();
    foreach (var r in qkpi) { r.MRKCamDLStatusQKPI = "A"; r.LogLUDateTime = now; r.LogLUBy = who; }
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        dealer, year, quarter, status = "A",
        synced = new { registers = reg.Count, registerDtls = regDtl.Count, actuals = act.Count, actualDtls = actDtl.Count, quarterKPIs = qkpi.Count },
    });
}).RequireAuthorization();

// ===== Chiến dịch marketing (MRK_Campaign — port 1:1 cụm 3 hàm Get(15916) / Save(16167) /
// Approve(16628), 2010.HTC BizHTC.Marketing.cs). TWIN: 3/3, cả WS 32-bit lẫn 64-bit. =====
// 🔴 Hằng trạng thái riêng `TConst.MRKCampaignStatus` (Const.Main.cs:832): chỉ "P" và "A".
// 🔴 `Save` mang cờ `strFlagIsDelete` (luật C0-centesimusdecimus): "1" thì CHỈ XOÁ; ngược lại UPSERT.
//    Sửa bản ghi đã có thì nó phải đang "P".
// 🔴 `Approve` cập nhật CẢ HAI bảng: đầu + đồng bộ `MRKCampaignStatusDetail` từng dòng.
// ⚠️ Guard `Mst_EvenType_CheckDB` và `Mst_FileType_CheckDB` chưa port — MiniHTC chưa có hai master đó.
app.MapGet("/api/mrkcampaigns", async (AppDbContext db, ITenantContext t, string? no, string? dealerCode, string? status) =>
{
    var qy = db.MrkCampaigns.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(no)) qy = qy.Where(x => x.MRKCampaignNo == no);
    if (!string.IsNullOrWhiteSpace(dealerCode)) qy = qy.Where(x => x.DealerCode == dealerCode);
    if (!string.IsNullOrWhiteSpace(status)) qy = qy.Where(x => x.MRKCampaignStatus == status);
    var items = await qy.OrderByDescending(x => x.Id).Select(x => new
    {
        x.MRKCampaignNo, x.MRKCampaignName, x.DealerCode, x.EvenType, x.StartDate, x.EndDate,
        x.MRKCampaignStatus, x.Remark, x.CreatedDateTime, x.CreatedBy,
        x.LUDateTime, x.LUBy, x.ApproveDateTime, x.ApproveBy, x.LogLUDateTime, x.LogLUBy,
    }).ToListAsync();
    var nos = items.Select(i => i.MRKCampaignNo).ToList();
    var dtls = await db.MrkCampaignDetails.Where(d => d.OrgId == t.OrgId && nos.Contains(d.MRKCampaignNo))
        .Select(d => new
        {
            d.MRKCampaignNo, d.FileType, d.FileNameActual, d.FilePath,
            d.MRKCampaignStatusDetail, d.LUDateTime, d.LUBy, d.LogLUDateTime, d.LogLUBy,
        }).ToListAsync();
    return Results.Ok(new { count = items.Count, items, details = dtls });
}).RequireAuthorization();

app.MapPost("/api/mrkcampaigns/save", async (MrkCampaignSaveDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var no = (dto.MRKCampaignNo ?? "").Trim();
    if (no.Length < 1) return Results.BadRequest(new { error = "Số chiến dịch rỗng." });
    var cur = await db.MrkCampaigns.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.MRKCampaignNo == no);

    // 🔴 Nhánh XOÁ: nguồn không đòi bảng chi tiết; không có bản ghi thì coi là thành công.
    if ((dto.FlagIsDelete ?? "").Trim() == "1")
    {
        if (cur is null) return Results.Ok(new { deleted = 0, no, note = "Không có bản ghi — nguồn coi là thành công." });
        if (cur.MRKCampaignStatus != "P")
            return Results.BadRequest(new { error = $"Chiến dịch {no} đang {cur.MRKCampaignStatus}, chỉ xoá được khi 'P'." });
        var curDtls = await db.MrkCampaignDetails.Where(d => d.OrgId == t.OrgId && d.MRKCampaignNo == no).ToListAsync();
        db.MrkCampaignDetails.RemoveRange(curDtls);
        db.MrkCampaigns.Remove(cur);
        await db.SaveChangesAsync();
        return Results.Ok(new { deleted = 1, detailsDeleted = curDtls.Count, no });
    }

    var name = (dto.MRKCampaignName ?? "").Trim();
    var dealer = (dto.DealerCode ?? "").Trim();
    if (name.Length < 1) return Results.BadRequest(new { error = "Tên chiến dịch rỗng." });
    if (dealer.Length < 1) return Results.BadRequest(new { error = "Chưa chọn đại lý." });

    var createdAt = DateTime.Now;
    var createdBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    if (cur is not null)
    {
        if (cur.MRKCampaignStatus != "P")
            return Results.BadRequest(new { error = $"Chiến dịch {no} đang {cur.MRKCampaignStatus}, chỉ sửa được khi 'P'." });
        createdAt = cur.CreatedDateTime; createdBy = cur.CreatedBy ?? createdBy;
        db.MrkCampaignDetails.RemoveRange(
            await db.MrkCampaignDetails.Where(d => d.OrgId == t.OrgId && d.MRKCampaignNo == no).ToListAsync());
        db.MrkCampaigns.Remove(cur);
        await db.SaveChangesAsync();
    }

    var now = DateTime.Now;
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    db.MrkCampaigns.Add(new MrkCampaign
    {
        OrgId = t.OrgId, MRKCampaignNo = no, MRKCampaignName = name, DealerCode = dealer,
        EvenType = dto.EvenType, StartDate = dto.StartDate, EndDate = dto.EndDate,
        MRKCampaignStatus = "P", Remark = dto.Remark,
        CreatedDateTime = createdAt, CreatedBy = createdBy,
        LUDateTime = now, LUBy = who, LogLUDateTime = now, LogLUBy = who,
    });
    var files = dto.Details ?? new();
    foreach (var f in files)
        db.MrkCampaignDetails.Add(new MrkCampaignDetail
        {
            OrgId = t.OrgId, MRKCampaignNo = no,
            FileType = f.FileType, FileNameActual = f.FileNameActual, FilePath = f.FilePath,
            MRKCampaignStatusDetail = "P",
            LUDateTime = now, LUBy = who, LogLUDateTime = now, LogLUBy = who,
        });
    await db.SaveChangesAsync();
    return Results.Ok(new { no, details = files.Count, status = "P" });
}).RequireAuthorization();

app.MapPost("/api/mrkcampaigns/approve", async (MrkCampaignKeyDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var no = (dto.MRKCampaignNo ?? "").Trim();
    var row = await db.MrkCampaigns.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.MRKCampaignNo == no);
    if (row is null) return Results.NotFound(new { error = $"Không có chiến dịch {no}." });
    if (row.MRKCampaignStatus != "P")
        return Results.BadRequest(new { error = $"Chiến dịch đang {row.MRKCampaignStatus}, chỉ duyệt được khi 'P'." });

    var now = DateTime.Now;
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    row.MRKCampaignStatus = "A";
    row.ApproveDateTime = now; row.ApproveBy = who; row.LogLUDateTime = now; row.LogLUBy = who;
    var dtls = await db.MrkCampaignDetails.Where(d => d.OrgId == t.OrgId && d.MRKCampaignNo == no).ToListAsync();
    foreach (var d in dtls) { d.MRKCampaignStatusDetail = "A"; d.LogLUDateTime = now; d.LogLUBy = who; }
    await db.SaveChangesAsync();
    return Results.Ok(new { no, status = "A", detailsSynced = dtls.Count });
}).RequireAuthorization();

// ===== Hồ sơ KPI / giải ngân marketing theo quý (MRK_KPIDisbursment — port 1:1 cụm 2 hàm
// Get(15243) / Save(15545), 2010.HTC BizHTC.Marketing.cs). TWIN: 2/2, cả WS 32-bit lẫn 64-bit. =====
// 🔴 MỘT hàm Save làm CẢ HAI việc: `strFlagIsDelete = "1"` thì CHỈ XOÁ; ngược lại là UPSERT
//    (xoá theo khoá bốn rồi chèn lại). Nguồn KHÔNG có hàm Delete riêng — port giữ đúng hình dạng đó.
// 🔴 `KPIDisbursmentType` (TConst.KPIDisburmentType — tên lớp hằng thiếu chữ s so với tên cột):
//    KPICOMMIT (cam kết KPI) · KPIRESULT (kết quả KPI) · KPIDBTable (bảng giải ngân).
//    Giá trị thứ ba KHÔNG viết hoa toàn bộ; nguồn so sánh IgnoreCase nhưng ghi xuống DB giữ nguyên dạng.
// ⚠️ Guard `Mst_Quater_CheckDB` chưa port: MiniHTC không có master Mst_Quater (ghi nợ, không bịa master).
string[] MrkKpiDisbTypes = { "KPICOMMIT", "KPIRESULT", "KPIDBTable" };

app.MapGet("/api/mrkkpidisbursments", async (AppDbContext db, ITenantContext t, string? year, string? quaterCode, string? dealerCode, string? type) =>
{
    var qy = db.MrkKpiDisbursments.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(year)) qy = qy.Where(x => x.KPIDisbursmentYear == year);
    if (!string.IsNullOrWhiteSpace(quaterCode)) qy = qy.Where(x => x.QuaterCode == quaterCode);
    if (!string.IsNullOrWhiteSpace(dealerCode)) qy = qy.Where(x => x.DealerCode == dealerCode);
    if (!string.IsNullOrWhiteSpace(type)) qy = qy.Where(x => x.KPIDisbursmentType == type);
    var items = await qy.OrderBy(x => x.KPIDisbursmentYear).ThenBy(x => x.QuaterCode).ThenBy(x => x.DealerCode)
        .Select(x => new
        {
            x.KPIDisbursmentYear, x.QuaterCode, x.DealerCode, x.KPIDisbursmentType,
            x.FileNameActual, x.FilePath, x.FlagActive,
            x.CreatedDateTime, x.CreatedBy, x.LogLUDateTime, x.LogLUBy,
        }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/mrkkpidisbursments/save", async (MrkKpiDisbursmentSaveDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var year = (dto.KPIDisbursmentYear ?? "").Trim();
    var quater = (dto.QuaterCode ?? "").Trim();
    var dealer = (dto.DealerCode ?? "").Trim();
    var type = (dto.KPIDisbursmentType ?? "").Trim();
    if (year.Length < 1) return Results.BadRequest(new { error = "Năm rỗng." });
    if (quater.Length < 1) return Results.BadRequest(new { error = "Mã quý rỗng." });
    if (dealer.Length < 1) return Results.BadRequest(new { error = "Mã đại lý rỗng." });
    // So sánh KHÔNG phân biệt hoa thường, đúng như `StringEqualIgnoreCase` của nguồn.
    var matched = MrkKpiDisbTypes.FirstOrDefault(x => string.Equals(x, type, StringComparison.OrdinalIgnoreCase));
    if (matched is null)
        return Results.BadRequest(new { error = $"Loại KPI/giải ngân không hợp lệ. Cho phép: {string.Join(", ", MrkKpiDisbTypes)}." });

    // Khoá bốn — dùng chung cho cả nhánh xoá lẫn nhánh upsert.
    var old = await db.MrkKpiDisbursments.Where(x => x.OrgId == t.OrgId
        && x.KPIDisbursmentYear == year && x.QuaterCode == quater
        && x.DealerCode == dealer && x.KPIDisbursmentType == matched).ToListAsync();

    var isDelete = (dto.FlagIsDelete ?? "").Trim() == "1"; // TConst.Flag.Yes
    if (isDelete)
    {
        db.MrkKpiDisbursments.RemoveRange(old);
        await db.SaveChangesAsync();
        return Results.Ok(new { deleted = old.Count, year, quater, dealer, type = matched });
    }

    var now = DateTime.Now;
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    // Giữ nguyên dấu vết tạo của bản ghi cũ, đúng như nguồn đọc lại CreatedDateTime/CreatedBy trước khi xoá.
    var createdAt = old.Count > 0 ? old[0].CreatedDateTime : now;
    var createdBy = old.Count > 0 ? (old[0].CreatedBy ?? who) : who;
    db.MrkKpiDisbursments.RemoveRange(old);
    db.MrkKpiDisbursments.Add(new MrkKpiDisbursment
    {
        OrgId = t.OrgId, KPIDisbursmentYear = year, QuaterCode = quater,
        DealerCode = dealer, KPIDisbursmentType = matched,
        FileNameActual = dto.FileNameActual, FilePath = dto.FilePath,
        FlagActive = "1", // nguồn luôn ghi Flag.Active khi lưu
        CreatedDateTime = createdAt, CreatedBy = createdBy,
        LogLUDateTime = now, LogLUBy = who,
    });
    await db.SaveChangesAsync();
    return Results.Ok(new { saved = 1, replaced = old.Count, year, quater, dealer, type = matched });
}).RequireAuthorization();

// ===== Hạn mức ngân sách marketing theo năm (MRK_ScopeLimit — port 1:1 cụm 4 hàm
// Get(14570) / Save(14092) / Approve(14808) / Detail_Get(15031), 2010.HTC BizHTC.Marketing.cs).
// TWIN: 4/4 hàm, cả WS 32-bit lẫn 64-bit. =====
// 🔴 Cụm này dùng hằng trạng thái RIÊNG `TConst.MRKScopLimitStatus` (tên hằng thiếu chữ e) — chỉ
//    "P" (chờ duyệt) và "A" (đã duyệt). KHÔNG có "R"/"F"/"M" như cụm chi phí marketing.
// 🔴 4 QUÝ hạn mức nhưng 6 ĐỢT giải ngân — bất đối xứng đúng theo nghiệp vụ, không phải lỗi.
//    Tên cột giữ nguyên chính tả nguồn: `Quater` (Quarter) và `Disbursment` (Disbursement).
app.MapGet("/api/mrkscopelimits", async (AppDbContext db, ITenantContext t, string? no, string? year, string? status) =>
{
    var qy = db.MrkScopeLimits.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(no)) qy = qy.Where(x => x.MRKScopeLimitNo == no);
    if (!string.IsNullOrWhiteSpace(year)) qy = qy.Where(x => x.MRKScopeLimitYear == year);
    if (!string.IsNullOrWhiteSpace(status)) qy = qy.Where(x => x.MRKScopeLimitStatus == status);
    var items = await qy.OrderByDescending(x => x.Id).Select(x => new
    {
        x.MRKScopeLimitNo, x.MRKScopeLimitYear, x.MRKScopeLimitStatus,
        x.CreatedDateTime, x.CreatedBy, x.LUDateTime, x.LUBy,
        x.ApproveDateTime, x.ApproveBy, x.LogLUDateTime, x.LogLUBy,
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Tương ứng `MRK_ScopeLimitDetail_Get` — nguồn tách thành hàm đọc riêng cho phần chi tiết.
app.MapGet("/api/mrkscopelimitdetails", async (AppDbContext db, ITenantContext t, string? no, string? dealerCode) =>
{
    var qy = db.MrkScopeLimitDetails.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(no)) qy = qy.Where(x => x.MRKScopeLimitNo == no);
    if (!string.IsNullOrWhiteSpace(dealerCode)) qy = qy.Where(x => x.DealerCode == dealerCode);
    var items = await qy.OrderBy(x => x.DealerCode).Select(d => new
    {
        d.MRKScopeLimitNo, d.DealerCode,
        d.Amount1QuaterScopeLimit, d.Amount2QuaterScopeLimit, d.Amount3QuaterScopeLimit, d.Amount4QuaterScopeLimit,
        d.Amount1DisbursmentCash, d.Amount2DisbursmentCash, d.Amount3DisbursmentCash, d.Amount4DisbursmentCash, d.Amount5DisbursmentCash, d.Amount6DisbursmentCash,
        d.MRKScopeLimitStatusDetail, d.Remark, d.LUDateTime, d.LUBy, d.LogLUDateTime, d.LogLUBy,
        QuaterTotal = d.Amount1QuaterScopeLimit + d.Amount2QuaterScopeLimit + d.Amount3QuaterScopeLimit + d.Amount4QuaterScopeLimit,
        DisbursmentTotal = d.Amount1DisbursmentCash + d.Amount2DisbursmentCash + d.Amount3DisbursmentCash + d.Amount4DisbursmentCash + d.Amount5DisbursmentCash + d.Amount6DisbursmentCash,
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// 🔴 Save = XOÁ TRẮNG rồi INSERT lại cả đầu lẫn chi tiết. Bản ghi đã có thì PHẢI đang "P",
//    và `CreatedDateTime`/`CreatedBy` gốc được GIỮ NGUYÊN (nguồn đọc lại từ DB trước khi xoá).
app.MapPost("/api/mrkscopelimits/save", async (MrkScopeLimitSaveDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var no = (dto.MRKScopeLimitNo ?? "").Trim();
    var year = (dto.MRKScopeLimitYear ?? "").Trim();
    if (no.Length < 1) return Results.BadRequest(new { error = "Số hạn mức rỗng." });
    if (year.Length < 1) return Results.BadRequest(new { error = "Năm hạn mức rỗng." });
    // 🔴 Cờ `FlagIsDelete` của nguồn (`strFlagIsDelete == "1"`): CHỈ XOÁ, không đòi bảng chi tiết.
    // Bản ghi không tồn tại thì nguồn `goto MyCodeLabel_Done` — coi là THÀNH CÔNG, không báo lỗi.
    if ((dto.FlagIsDelete ?? "").Trim() == "1")
    {
        var cur = await db.MrkScopeLimits.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.MRKScopeLimitNo == no);
        if (cur is null) return Results.Ok(new { deleted = 0, no, note = "Không có bản ghi — nguồn coi là thành công." });
        if (cur.MRKScopeLimitStatus != "P")
            return Results.BadRequest(new { error = $"Hạn mức {no} đang {cur.MRKScopeLimitStatus}, chỉ xoá được khi 'P'." });
        var curDtls = await db.MrkScopeLimitDetails.Where(d => d.OrgId == t.OrgId && d.MRKScopeLimitNo == no).ToListAsync();
        db.MrkScopeLimitDetails.RemoveRange(curDtls);
        db.MrkScopeLimits.Remove(cur);
        await db.SaveChangesAsync();
        return Results.Ok(new { deleted = 1, detailsDeleted = curDtls.Count, no });
    }

    var rows = (dto.Details ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.DealerCode)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Bảng chi tiết rỗng." });

    var seen = new HashSet<string>();
    foreach (var r in rows)
    {
        if (!seen.Add(r.DealerCode!.Trim()))
            return Results.BadRequest(new { error = $"Đại lý {r.DealerCode} bị lặp trong bảng chi tiết." });
        // Guard nguồn: cả 10 số tiền đều không được âm (một mã lỗi chung).
        if (r.Amount1QuaterScopeLimit < 0m || r.Amount2QuaterScopeLimit < 0m || r.Amount3QuaterScopeLimit < 0m || r.Amount4QuaterScopeLimit < 0m || r.Amount1DisbursmentCash < 0m || r.Amount2DisbursmentCash < 0m || r.Amount3DisbursmentCash < 0m || r.Amount4DisbursmentCash < 0m || r.Amount5DisbursmentCash < 0m || r.Amount6DisbursmentCash < 0m)
            return Results.BadRequest(new { error = $"Đại lý {r.DealerCode}: có số tiền âm." });
    }

    var old = await db.MrkScopeLimits.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.MRKScopeLimitNo == no);
    var createdAt = DateTime.Now;
    var createdBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    if (old is not null)
    {
        if (old.MRKScopeLimitStatus != "P")
            return Results.BadRequest(new { error = $"Hạn mức {no} đang {old.MRKScopeLimitStatus}, chỉ sửa được khi 'P'." });
        // Giữ nguyên dấu vết tạo ban đầu.
        createdAt = old.CreatedDateTime; createdBy = old.CreatedBy ?? createdBy;
        db.MrkScopeLimitDetails.RemoveRange(
            await db.MrkScopeLimitDetails.Where(d => d.OrgId == t.OrgId && d.MRKScopeLimitNo == no).ToListAsync());
        db.MrkScopeLimits.Remove(old);
        await db.SaveChangesAsync();
    }

    var now = DateTime.Now;
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    db.MrkScopeLimits.Add(new MrkScopeLimit
    {
        OrgId = t.OrgId, MRKScopeLimitNo = no, MRKScopeLimitYear = year, MRKScopeLimitStatus = "P",
        CreatedDateTime = createdAt, CreatedBy = createdBy,
        LUDateTime = now, LUBy = who, LogLUDateTime = now, LogLUBy = who,
    });
    foreach (var r in rows)
        db.MrkScopeLimitDetails.Add(new MrkScopeLimitDetail
        {
            OrgId = t.OrgId, MRKScopeLimitNo = no, DealerCode = r.DealerCode!.Trim(),
            Amount1QuaterScopeLimit = r.Amount1QuaterScopeLimit ?? 0m, Amount2QuaterScopeLimit = r.Amount2QuaterScopeLimit ?? 0m, Amount3QuaterScopeLimit = r.Amount3QuaterScopeLimit ?? 0m, Amount4QuaterScopeLimit = r.Amount4QuaterScopeLimit ?? 0m,
            Amount1DisbursmentCash = r.Amount1DisbursmentCash ?? 0m, Amount2DisbursmentCash = r.Amount2DisbursmentCash ?? 0m, Amount3DisbursmentCash = r.Amount3DisbursmentCash ?? 0m, Amount4DisbursmentCash = r.Amount4DisbursmentCash ?? 0m, Amount5DisbursmentCash = r.Amount5DisbursmentCash ?? 0m, Amount6DisbursmentCash = r.Amount6DisbursmentCash ?? 0m,
            MRKScopeLimitStatusDetail = "P", Remark = r.Remark,
            LUDateTime = now, LUBy = who, LogLUDateTime = now, LogLUBy = who,
        });
    await db.SaveChangesAsync();
    return Results.Ok(new { no, year, details = rows.Count, status = "P" });
}).RequireAuthorization();

// 🔴 Duyệt cập nhật CẢ HAI bảng: phần đầu và đồng bộ xuống MRKScopeLimitStatusDetail của từng dòng.
app.MapPost("/api/mrkscopelimits/approve", async (MrkScopeLimitKeyDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var no = (dto.MRKScopeLimitNo ?? "").Trim();
    var row = await db.MrkScopeLimits.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.MRKScopeLimitNo == no);
    if (row is null) return Results.NotFound(new { error = $"Không có hạn mức {no}." });
    if (row.MRKScopeLimitStatus != "P")
        return Results.BadRequest(new { error = $"Hạn mức đang {row.MRKScopeLimitStatus}, chỉ duyệt được khi 'P'." });

    var now = DateTime.Now;
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    row.MRKScopeLimitStatus = "A";
    row.ApproveDateTime = now; row.ApproveBy = who;
    row.LogLUDateTime = now; row.LogLUBy = who;
    var dtls = await db.MrkScopeLimitDetails.Where(d => d.OrgId == t.OrgId && d.MRKScopeLimitNo == no).ToListAsync();
    foreach (var d in dtls) { d.MRKScopeLimitStatusDetail = "A"; d.LogLUDateTime = now; d.LogLUBy = who; }
    await db.SaveChangesAsync();
    return Results.Ok(new { no, status = "A", detailsSynced = dtls.Count });
}).RequireAuthorization();

// ===== File đính kèm của dòng chi phí marketing (MKT_MarketingFeeDetailAttach — port 1:1 cụm 4 hàm
// Get(4990) / Save(5169) / Approved(5603) / Rejected(5888), 2010.HTC BizHTC.Marketing.cs).
// TWIN: 4/4 hàm, cả WS 32-bit lẫn 64-bit. Đây là mắt xích ghi `Status*` mà `Finished` (#106) và
// `UpdateHTCLimit` (#107) chỉ ĐỌC. =====
// 🔴 TỪ CHỐI hồ sơ ghi trạng thái **"M" (Stage.Modify)**, KHÔNG phải "R" — đúng chỗ mà hằng số
//    `Stage.Modify` chú thích "Chỉ dùng cho Marketing". Nghĩa là *trả lại cho đại lý sửa*, không phải bác bỏ.
// 🔴 `Save` XOÁ rồi INSERT lại **theo TỪNG LOẠI hồ sơ**: nộp lại ảnh thiết kế không đụng hợp đồng/hoá đơn.
//    Sau khi lưu, loại nào có file thì `Status<Loại>` về **"P"** kèm ghi chú của đại lý.
// 🔴 Đã duyệt thì KHÔNG nộp lại được: `Save` chặn nếu `Status<Loại>` đang "A".
string[] MktAttachTypes = { "DESIGNIMAGE", "ACTUALIMAGE", "CONTRACT", "INVOICE" };

app.MapGet("/api/mktfeeattaches", async (AppDbContext db, ITenantContext t, string? feeCode, string? activityCode, string? fileAttachType) =>
{
    var qy = db.MktFeeDetailAttaches.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(feeCode)) qy = qy.Where(x => x.MKTFeeCode == feeCode);
    if (!string.IsNullOrWhiteSpace(activityCode)) qy = qy.Where(x => x.MKTActivityCode == activityCode);
    if (!string.IsNullOrWhiteSpace(fileAttachType)) qy = qy.Where(x => x.FileAttachType == fileAttachType.Trim().ToUpperInvariant());
    var items = await qy.OrderBy(x => x.FileAttachType).ThenBy(x => x.Idx).Select(x => new
    {
        x.MKTFeeCode, x.MKTActivityCode, x.FileAttachType, x.Idx,
        x.FilePath, x.FileDesc, x.FileType, x.LogLUDateTime, x.LogLUBy,
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Nộp hồ sơ MỘT loại: thay thế trọn bộ file của đúng loại đó.
app.MapPost("/api/mktfeeattaches/save", async (MktFeeAttachSaveDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var code = (dto.MKTFeeCode ?? "").Trim();
    var act = (dto.MKTActivityCode ?? "").Trim();
    var kind = (dto.FileAttachType ?? "").Trim().ToUpperInvariant();
    if (!MktAttachTypes.Contains(kind))
        return Results.BadRequest(new { error = $"Loại hồ sơ không hợp lệ. Cho phép: {string.Join(", ", MktAttachTypes)}." });

    var fee = await db.MktFees.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.MKTFeeCode == code);
    if (fee is null) return Results.NotFound(new { error = $"Không có phiếu {code}." });
    if (fee.MKTStatus != "P" && fee.MKTStatus != "A")
        return Results.BadRequest(new { error = $"Phiếu đang {fee.MKTStatus}, chỉ nộp hồ sơ khi 'P' hoặc 'A'." });
    var row = await db.MktFeeDetails.FirstOrDefaultAsync(d => d.OrgId == t.OrgId && d.MKTFeeCode == code && d.MKTActivityCode == act);
    if (row is null) return Results.NotFound(new { error = $"Phiếu {code} không có dòng {act}." });
    if (row.MKTFeeDetailStatus != "P" && row.MKTFeeDetailStatus != "A")
        return Results.BadRequest(new { error = $"Dòng đang {row.MKTFeeDetailStatus}, chỉ nộp hồ sơ khi 'P' hoặc 'A'." });

    var files = (dto.Files ?? new()).ToList();
    // 🔴 Guard nguồn: loại hồ sơ đã được duyệt thì không nộp lại được nữa.
    var curStatus = kind switch
    {
        "DESIGNIMAGE" => row.StatusDesignImage,
        "ACTUALIMAGE" => row.StatusActualImage,
        "CONTRACT" => row.StatusContract,
        _ => row.StatusInvoice,
    };
    if (files.Count > 0 && curStatus == "A")
        return Results.BadRequest(new { error = "Hồ sơ loại này đã được duyệt, không nộp lại được." });

    var seen = new HashSet<string>();
    foreach (var f in files)
    {
        if (string.IsNullOrWhiteSpace(f.FilePath)) return Results.BadRequest(new { error = "Có file thiếu đường dẫn." });
        if (!seen.Add($"|{code}||{act}||{kind}||{f.Idx}|"))
            return Results.BadRequest(new { error = $"Số thứ tự file {f.Idx} bị lặp trong loại {kind}." });
    }

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    // Xoá rồi chèn lại — CHỈ đúng loại hồ sơ này.
    var old = await db.MktFeeDetailAttaches
        .Where(x => x.OrgId == t.OrgId && x.MKTFeeCode == code && x.MKTActivityCode == act && x.FileAttachType == kind)
        .ToListAsync();
    db.MktFeeDetailAttaches.RemoveRange(old);
    foreach (var f in files)
        db.MktFeeDetailAttaches.Add(new MktFeeDetailAttach
        {
            OrgId = t.OrgId, MKTFeeCode = code, MKTActivityCode = act, FileAttachType = kind,
            Idx = f.Idx ?? 0, FilePath = f.FilePath!.Trim(), FileDesc = f.FileDesc, FileType = f.FileType,
            LogLUDateTime = now, LogLUBy = who,
        });

    // Có nộp file thì trạng thái loại đó về "P" kèm ghi chú của đại lý.
    if (files.Count > 0)
        switch (kind)
        {
            case "DESIGNIMAGE": row.StatusDesignImage = "P"; row.RemarkDlrDesignImage = dto.RemarkDlr; break;
            case "ACTUALIMAGE": row.StatusActualImage = "P"; row.RemarkDlrActualImage = dto.RemarkDlr; break;
            case "CONTRACT": row.StatusContract = "P"; row.RemarkDlrContract = dto.RemarkDlr; break;
            default: row.StatusInvoice = "P"; row.RemarkDlrInvoice = dto.RemarkDlr; break;
        }
    row.LogLUDateTime = now; row.LogLUBy = who;
    await db.SaveChangesAsync();
    return Results.Ok(new { code, act, kind, removed = old.Count, saved = files.Count });
}).RequireAuthorization();

// Duyệt / trả lại hồ sơ một loại. 🔴 TRẢ LẠI ghi "M" (Modify), KHÔNG phải "R".
app.MapPost("/api/mktfeeattaches/approve", async (MktFeeAttachDecisionDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
    await MktAttachDecide(dto, "A", db, t, user)).RequireAuthorization();

app.MapPost("/api/mktfeeattaches/reject", async (MktFeeAttachDecisionDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
    await MktAttachDecide(dto, "M", db, t, user)).RequireAuthorization();

// Thân chung của duyệt/trả lại: nguồn tách hai hàm nhưng chỉ khác giá trị đích ("A" vs "M").
// Cả hai đòi phiếu "A", dòng "A", và trạng thái loại hồ sơ đang "P".
async Task<IResult> MktAttachDecide(MktFeeAttachDecisionDto dto, string target, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user)
{
    var code = (dto.MKTFeeCode ?? "").Trim();
    var act = (dto.MKTActivityCode ?? "").Trim();
    var kind = (dto.FileAttachType ?? "").Trim().ToUpperInvariant();
    if (!MktAttachTypes.Contains(kind))
        return Results.BadRequest(new { error = $"Loại hồ sơ không hợp lệ. Cho phép: {string.Join(", ", MktAttachTypes)}." });

    var fee = await db.MktFees.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.MKTFeeCode == code);
    if (fee is null) return Results.NotFound(new { error = $"Không có phiếu {code}." });
    if (fee.MKTStatus != "A") return Results.BadRequest(new { error = $"Phiếu đang {fee.MKTStatus}, chỉ xét hồ sơ khi phiếu 'A'." });
    var row = await db.MktFeeDetails.FirstOrDefaultAsync(d => d.OrgId == t.OrgId && d.MKTFeeCode == code && d.MKTActivityCode == act);
    if (row is null) return Results.NotFound(new { error = $"Phiếu {code} không có dòng {act}." });
    if (row.MKTFeeDetailStatus != "A") return Results.BadRequest(new { error = $"Dòng đang {row.MKTFeeDetailStatus}, chỉ xét hồ sơ khi dòng 'A'." });

    var cur = kind switch
    {
        "DESIGNIMAGE" => row.StatusDesignImage,
        "ACTUALIMAGE" => row.StatusActualImage,
        "CONTRACT" => row.StatusContract,
        _ => row.StatusInvoice,
    };
    if (cur != "P") return Results.BadRequest(new { error = $"Hồ sơ loại {kind} đang ở '{cur}', chỉ xét được khi 'P'." });

    var now = DateTime.Now;
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    switch (kind)
    {
        case "DESIGNIMAGE":
            row.StatusDesignImage = target; row.RemarkHTCDesignImage = dto.RemarkImage;
            row.ApprovedDateDesignImage = now; row.ApprovedByDesignImage = who; break;
        case "ACTUALIMAGE":
            row.StatusActualImage = target; row.RemarkHTCActualImage = dto.RemarkImage;
            row.ApprovedDateActualImage = now; row.ApprovedByActualImage = who; break;
        case "CONTRACT":
            row.StatusContract = target; row.RemarkHTCContract = dto.RemarkImage;
            row.ApprovedDateContract = now; row.ApprovedByContract = who; break;
        default:
            row.StatusInvoice = target; row.RemarkHTCInvoice = dto.RemarkImage;
            row.ApprovedDateInvoice = now; row.ApprovedByInvoice = who; break;
    }
    row.LogLUDateTime = now; row.LogLUBy = who;
    await db.SaveChangesAsync();
    return Results.Ok(new { code, act, kind, status = target });
}

// ===== Dòng chi phí marketing (MKT_MarketingFeeDetail — port 1:1 cụm 6 hàm
// Create(4157) / Update(3858) / UpdateHTCLimit(3608) / Approved(4555) / Rejected(4696) / Delete(4400),
// 2010.HTC BizHTC.Marketing.cs). TWIN: 6/6 hàm, cả WS 32-bit lẫn 64-bit. =====
// 🔴 Trạng thái PHIẾU mà mỗi lệnh đòi hỏi KHÁC NHAU, đọc kỹ kẻo port lẫn:
//    · Create / Update / Delete dòng: phiếu ở **"P" HOẶC "A"** (vẫn thêm/sửa/xoá được sau khi phiếu đã duyệt);
//    · Approved / Rejected / UpdateHTCLimit: phiếu phải **"A"**.
//    Còn TRẠNG THÁI DÒNG thì: Create/Update/Delete/Approved/Rejected đòi dòng **"P"**;
//    riêng UpdateHTCLimit đòi dòng **"A"**.
// 🔴 Approved và Rejected ghi CHUNG hai cột `ApprovedDetailDate`/`ApprovedDetailBy` — cột tên "Approved"
//    nhưng cũng lưu dấu vết TỪ CHỐI. Đừng suy trạng thái từ việc hai cột này có giá trị.
// ⚠️ Xem `### C0-bug7`: cả Approved lẫn Rejected của nguồn gán `LogLUDateTime = strPartnerUserCode`
//    (ghi MÃ NGƯỜI DÙNG vào cột NGÀY GIỜ). Port ghi đúng thời gian, không nhân bản lỗi.
app.MapPost("/api/mktfeedetails/create", async (MktFeeDetailCreateDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var code = (dto.MKTFeeCode ?? "").Trim();
    var act = (dto.MKTActivityCode ?? "").Trim();
    var fee = await db.MktFees.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.MKTFeeCode == code);
    if (fee is null) return Results.NotFound(new { error = $"Không có phiếu {code}." });
    // Nguồn: strMKTStatusListToCheck = "P,A" — thêm dòng được cả khi phiếu ĐÃ duyệt.
    if (fee.MKTStatus != "P" && fee.MKTStatus != "A")
        return Results.BadRequest(new { error = $"Phiếu đang {fee.MKTStatus}, chỉ thêm dòng khi 'P' hoặc 'A'." });
    if (dto.Qty is null || dto.Qty <= 0) return Results.BadRequest(new { error = "Số lượng phải > 0." });
    if (dto.Price is null || dto.Price <= 0m) return Results.BadRequest(new { error = "Đơn giá phải > 0." });
    if (!await db.MktActivities.AnyAsync(x => x.OrgId == t.OrgId && x.MKTActivityCode == act && x.FlagActive == "1"))
        return Results.BadRequest(new { error = $"Hoạt động {act} không tồn tại hoặc đã ngưng." });
    if (await db.MktFeeDetails.AnyAsync(d => d.OrgId == t.OrgId && d.MKTFeeCode == code && d.MKTActivityCode == act))
        return Results.BadRequest(new { error = $"Phiếu {code} đã có dòng cho hoạt động {act}." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    db.MktFeeDetails.Add(new MktFeeDetail
    {
        OrgId = t.OrgId, MKTFeeCode = code, MKTActivityCode = act,
        Qty = dto.Qty!.Value, Price = dto.Price!.Value, Remark = dto.Remark,
        MKTFeeDetailStatus = "P", LogLUDateTime = DateTime.Now, LogLUBy = who,
    });
    await db.SaveChangesAsync();
    return Results.Ok(new { code, act, mktFeeDetailStatus = "P" });
}).RequireAuthorization();

app.MapPost("/api/mktfeedetails/update", async (MktFeeDetailUpdateDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var code = (dto.MKTFeeCode ?? "").Trim();
    var act = (dto.MKTActivityCode ?? "").Trim();
    var fee = await db.MktFees.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.MKTFeeCode == code);
    if (fee is null) return Results.NotFound(new { error = $"Không có phiếu {code}." });
    if (fee.MKTStatus != "P" && fee.MKTStatus != "A")
        return Results.BadRequest(new { error = $"Phiếu đang {fee.MKTStatus}, chỉ sửa dòng khi 'P' hoặc 'A'." });
    var row = await db.MktFeeDetails.FirstOrDefaultAsync(d => d.OrgId == t.OrgId && d.MKTFeeCode == code && d.MKTActivityCode == act);
    if (row is null) return Results.NotFound(new { error = $"Phiếu {code} không có dòng {act}." });
    if (row.MKTFeeDetailStatus != "P")
        return Results.BadRequest(new { error = $"Dòng đang {row.MKTFeeDetailStatus}, chỉ sửa được khi 'P'." });
    if (dto.Qty is null || dto.Qty <= 0) return Results.BadRequest(new { error = "Số lượng phải > 0." });
    if (dto.Price is null || dto.Price <= 0m) return Results.BadRequest(new { error = "Đơn giá phải > 0." });

    row.Qty = dto.Qty!.Value; row.Price = dto.Price!.Value; row.Remark = dto.Remark;
    row.LogLUDateTime = DateTime.Now;
    row.LogLUBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    await db.SaveChangesAsync();
    return Results.Ok(new { code, act, row.Qty, row.Price });
}).RequireAuthorization();

// 🔴 Nhập TIỀN HTC HỖ TRỢ: nguồn chỉ cho khi phiếu "A", dòng "A", VÀ — nếu số tiền > 0 — bắt buộc
//    đã có file đính kèm loại HOÁ ĐƠN với `StatusInvoice = "A"`. Số tiền = 0 thì không đòi hồ sơ.
app.MapPost("/api/mktfeedetails/updatehtclimit", async (MktFeeDetailLimitDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var code = (dto.MKTFeeCode ?? "").Trim();
    var act = (dto.MKTActivityCode ?? "").Trim();
    var fee = await db.MktFees.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.MKTFeeCode == code);
    if (fee is null) return Results.NotFound(new { error = $"Không có phiếu {code}." });
    if (fee.MKTStatus != "A") return Results.BadRequest(new { error = $"Phiếu đang {fee.MKTStatus}, chỉ nhập tiền hỗ trợ khi phiếu 'A'." });
    var row = await db.MktFeeDetails.FirstOrDefaultAsync(d => d.OrgId == t.OrgId && d.MKTFeeCode == code && d.MKTActivityCode == act);
    if (row is null) return Results.NotFound(new { error = $"Phiếu {code} không có dòng {act}." });
    if (row.MKTFeeDetailStatus != "A") return Results.BadRequest(new { error = $"Dòng đang {row.MKTFeeDetailStatus}, chỉ nhập tiền hỗ trợ khi dòng 'A'." });

    var total = dto.TotalHTCSuport ?? 0m;
    if (total > 0m && row.StatusInvoice != "A")
        return Results.BadRequest(new { error = "Chỉ nhập được tiền hỗ trợ khi hoá đơn đính kèm đã được duyệt." });
    row.TotalHTCSuport = total;
    row.LogLUDateTime = DateTime.Now;
    row.LogLUBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    await db.SaveChangesAsync();
    return Results.Ok(new { code, act, row.TotalHTCSuport });
}).RequireAuthorization();


// Duyệt/từ chối một dòng chi phí: nguồn có hai hàm riêng nhưng thân giống hệt nhau.
// Cả hai đều đòi phiếu "A" + dòng "P", và ghi chung ApprovedDetailDate/By.
static async Task<IResult> MktFeeDetailSetStatus(MktFeeDetailKeyDto dto, string target, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user)
{
    var code = (dto.MKTFeeCode ?? "").Trim();
    var act = (dto.MKTActivityCode ?? "").Trim();
    var fee = await db.MktFees.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.MKTFeeCode == code);
    if (fee is null) return Results.NotFound(new { error = $"Không có phiếu {code}." });
    if (fee.MKTStatus != "A") return Results.BadRequest(new { error = $"Phiếu đang {fee.MKTStatus}, chỉ chốt dòng khi phiếu 'A'." });
    var row = await db.MktFeeDetails.FirstOrDefaultAsync(d => d.OrgId == t.OrgId && d.MKTFeeCode == code && d.MKTActivityCode == act);
    if (row is null) return Results.NotFound(new { error = $"Phiếu {code} không có dòng {act}." });
    if (row.MKTFeeDetailStatus != "P") return Results.BadRequest(new { error = $"Dòng đang {row.MKTFeeDetailStatus}, chỉ chốt được khi 'P'." });

    var now = DateTime.Now;
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    row.MKTFeeDetailStatus = target;
    row.ApprovedDetailDate = now; row.ApprovedDetailBy = who;
    // 🔴 C0-bug7: nguồn gán LogLUDateTime = mã người dùng. Ở đây ghi đúng thời gian.
    row.LogLUDateTime = now; row.LogLUBy = who;
    await db.SaveChangesAsync();
    return Results.Ok(new { code, act, row.MKTFeeDetailStatus });
}

// Duyệt / từ chối MỘT dòng. Nguồn tách thành hai hàm riêng nhưng thân giống hệt, chỉ khác giá trị đích.
app.MapPost("/api/mktfeedetails/approve", async (MktFeeDetailKeyDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
    await MktFeeDetailSetStatus(dto, "A", db, t, user)).RequireAuthorization();

app.MapPost("/api/mktfeedetails/reject", async (MktFeeDetailKeyDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
    await MktFeeDetailSetStatus(dto, "R", db, t, user)).RequireAuthorization();

app.MapPost("/api/mktfeedetails/delete", async (MktFeeDetailKeyDto dto, AppDbContext db, ITenantContext t) =>
{
    var code = (dto.MKTFeeCode ?? "").Trim();
    var act = (dto.MKTActivityCode ?? "").Trim();
    var fee = await db.MktFees.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.MKTFeeCode == code);
    if (fee is null) return Results.NotFound(new { error = $"Không có phiếu {code}." });
    if (fee.MKTStatus != "P" && fee.MKTStatus != "A")
        return Results.BadRequest(new { error = $"Phiếu đang {fee.MKTStatus}, chỉ xoá dòng khi 'P' hoặc 'A'." });
    var row = await db.MktFeeDetails.FirstOrDefaultAsync(d => d.OrgId == t.OrgId && d.MKTFeeCode == code && d.MKTActivityCode == act);
    if (row is null) return Results.NotFound(new { error = $"Phiếu {code} không có dòng {act}." });
    if (row.MKTFeeDetailStatus != "P")
        return Results.BadRequest(new { error = $"Dòng đang {row.MKTFeeDetailStatus}, chỉ xoá được khi 'P'." });
    db.MktFeeDetails.Remove(row); // nguồn XOÁ THẬT
    await db.SaveChangesAsync();
    return Results.Ok(new { deleted = $"{code}/{act}" });
}).RequireAuthorization();

// ===== Phiếu chi phí marketing (MKT_MarketingFee — port 1:1 cụm 7 hàm
// Get/Create/Update/Finished/Delete/ForceDelete/Approve_New20181115, 2010.HTC BizHTC.Marketing.cs
// 6764 / 6259 / 6582 / 2981 / 7037 / 7235 / 7395). TWIN: 7/7 hàm, cả WS 32-bit lẫn 64-bit. =====
// 🔴 Vòng đời MKTStatus: "P" tạo → "A" duyệt / "R" từ chối → "F" kết thúc.
// 🔴 HAI cách xoá KHÁC HẲN: Delete chỉ khi "P" (và chặn nếu có dòng đã "A");
//    ForceDelete chỉ khi "A", có RBAC CheckHTCDirect, và xoá dây chuyền Attach + Detail trước.
app.MapGet("/api/mktfees", async (AppDbContext db, ITenantContext t, string? feeCode, string? dealerCode, string? mktStatus) =>
{
    var qy = db.MktFees.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(feeCode)) qy = qy.Where(x => x.MKTFeeCode == feeCode);
    if (!string.IsNullOrWhiteSpace(dealerCode)) qy = qy.Where(x => x.DealerCode == dealerCode);
    if (!string.IsNullOrWhiteSpace(mktStatus)) qy = qy.Where(x => x.MKTStatus == mktStatus);
    var items = await qy.OrderByDescending(x => x.Id).Select(x => new
    {
        x.MKTFeeCode, x.MKTFeeName, x.DealerCode, x.DateStart, x.DateEnd, x.Remark, x.MKTStatus,
        x.ApprovedDate, x.ApprovedBy, x.CreatedDate, x.CreatedBy, x.LogLUDateTime, x.LogLUBy,
    }).ToListAsync();
    var codes = items.Select(i => i.MKTFeeCode).ToList();
    var dtls = await db.MktFeeDetails.Where(d => d.OrgId == t.OrgId && codes.Contains(d.MKTFeeCode))
        .Select(d => new
        {
            d.MKTFeeCode, d.MKTActivityCode, d.Qty, d.Price, d.Remark, d.MKTFeeDetailStatus,
            d.StatusDesignImage, d.StatusActualImage, d.StatusContract, d.StatusInvoice,
            d.TotalHTCSuport, d.ApprovedDetailDate, d.ApprovedDetailBy, d.LogLUDateTime, d.LogLUBy,
            d.RemarkDlrDesignImage, d.RemarkHTCDesignImage, d.ApprovedDateDesignImage, d.ApprovedByDesignImage,
            d.RemarkDlrActualImage, d.RemarkHTCActualImage, d.ApprovedDateActualImage, d.ApprovedByActualImage,
            d.RemarkDlrContract, d.RemarkHTCContract, d.ApprovedDateContract, d.ApprovedByContract,
            d.RemarkDlrInvoice, d.RemarkHTCInvoice, d.ApprovedDateInvoice, d.ApprovedByInvoice,
        }).ToListAsync();
    return Results.Ok(new { count = items.Count, items, details = dtls });
}).RequireAuthorization();

app.MapPost("/api/mktfees/create", async (MktFeeCreateDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var code = (dto.MKTFeeCode ?? "").Trim();
    var name = (dto.MKTFeeName ?? "").Trim();
    var dealer = (dto.DealerCode ?? "").Trim();
    if (code.Length < 1) return Results.BadRequest(new { error = "Mã phiếu chi phí rỗng." });
    if (await db.MktFees.AnyAsync(x => x.OrgId == t.OrgId && x.MKTFeeCode == code))
        return Results.BadRequest(new { error = $"Phiếu {code} đã tồn tại." });
    if (name.Length < 1) return Results.BadRequest(new { error = "Tên phiếu chi phí rỗng." });
    if (dealer.Length < 1) return Results.BadRequest(new { error = "Chưa chọn đại lý." });

    var rows = dto.Details ?? new();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Bảng chi tiết rỗng." });
    // Nguồn dựng khoá "|MKTFeeCode||MKTActivityCode|" để bắt TRÙNG ngay trong bảng đầu vào.
    var seen = new HashSet<string>();
    foreach (var r in rows)
    {
        var act = (r.MKTActivityCode ?? "").Trim();
        if (!seen.Add($"|{code}||{act}|"))
            return Results.BadRequest(new { error = $"Hoạt động {act} bị lặp trong phiếu." });
        if (r.Qty is null || r.Qty <= 0) return Results.BadRequest(new { error = $"Hoạt động {act}: Số lượng phải > 0." });
        if (r.Price is null || r.Price <= 0m) return Results.BadRequest(new { error = $"Hoạt động {act}: Đơn giá phải > 0." });
        // Guard nguồn: hoạt động phải tồn tại VÀ đang Active ("1").
        var ok = await db.MktActivities.AnyAsync(x => x.OrgId == t.OrgId && x.MKTActivityCode == act && x.FlagActive == "1");
        if (!ok) return Results.BadRequest(new { error = $"Hoạt động {act} không tồn tại hoặc đã ngưng." });
    }

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    db.MktFees.Add(new MktFee
    {
        OrgId = t.OrgId, MKTFeeCode = code, MKTFeeName = name, DealerCode = dealer,
        DateStart = dto.DateStart, DateEnd = dto.DateEnd, Remark = dto.Remark,
        MKTStatus = "P", CreatedDate = now, CreatedBy = who, LogLUDateTime = now, LogLUBy = who,
    });
    foreach (var r in rows)
        db.MktFeeDetails.Add(new MktFeeDetail
        {
            OrgId = t.OrgId, MKTFeeCode = code, MKTActivityCode = r.MKTActivityCode!.Trim(),
            Qty = r.Qty!.Value, Price = r.Price!.Value, Remark = r.Remark,
            MKTFeeDetailStatus = "P", LogLUDateTime = now, LogLUBy = who,
        });
    await db.SaveChangesAsync();
    return Results.Ok(new { code, details = rows.Count, mktStatus = "P" });
}).RequireAuthorization();

// Sửa phần đầu: nguồn chỉ cho khi phiếu còn "P", và luôn ghi 4 cột Name/DateStart/DateEnd/Remark.
app.MapPost("/api/mktfees/update", async (MktFeeUpdateDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var code = (dto.MKTFeeCode ?? "").Trim();
    var row = await db.MktFees.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.MKTFeeCode == code);
    if (row is null) return Results.NotFound(new { error = $"Không có phiếu {code}." });
    if (row.MKTStatus != "P") return Results.BadRequest(new { error = $"Phiếu đang {row.MKTStatus}, chỉ sửa được khi 'P'." });
    var name = (dto.MKTFeeName ?? "").Trim();
    if (name.Length < 1) return Results.BadRequest(new { error = "Tên phiếu chi phí rỗng." });
    row.MKTFeeName = name; row.DateStart = dto.DateStart; row.DateEnd = dto.DateEnd; row.Remark = dto.Remark;
    row.LogLUDateTime = DateTime.Now;
    row.LogLUBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    await db.SaveChangesAsync();
    return Results.Ok(new { row.MKTFeeCode, row.MKTStatus });
}).RequireAuthorization();

// Duyệt / từ chối: nguồn dùng CHUNG một hàm, cờ `bApprove` quyết định "A" hay "R".
app.MapPost("/api/mktfees/approve", async (MktFeeApproveDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var code = (dto.MKTFeeCode ?? "").Trim();
    var row = await db.MktFees.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.MKTFeeCode == code);
    if (row is null) return Results.NotFound(new { error = $"Không có phiếu {code}." });
    if (row.MKTStatus != "P") return Results.BadRequest(new { error = $"Phiếu đang {row.MKTStatus}, chỉ duyệt được khi 'P'." });
    var dtls = await db.MktFeeDetails.Where(d => d.OrgId == t.OrgId && d.MKTFeeCode == code).ToListAsync();
    // Guard nguồn: mọi dòng chi tiết phải còn "P" (dòng để trống trạng thái thì bỏ qua).
    var bad = dtls.Where(d => !string.IsNullOrWhiteSpace(d.MKTFeeDetailStatus) && d.MKTFeeDetailStatus != "P")
                  .Select(d => d.MKTActivityCode).ToList();
    if (bad.Count > 0) return Results.BadRequest(new { error = $"Dòng chi tiết không ở 'P': {string.Join(", ", bad.Take(10))}." });

    var now = DateTime.Now;
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    row.MKTStatus = dto.Approve == false ? "R" : "A";
    row.ApprovedDate = now; row.ApprovedBy = who; row.LogLUDateTime = now; row.LogLUBy = who;
    await db.SaveChangesAsync();
    return Results.Ok(new { row.MKTFeeCode, row.MKTStatus });
}).RequireAuthorization();

// Kết thúc phiếu: "A" → "F".
// 🔴 C0-bug6 — nguồn viết guard "A hoặc R" thành `!= "A" || != "R"`, biểu thức LUÔN ĐÚNG nên hàm
//    Finished của legacy không bao giờ chạy lọt. Ở đây port theo **Ý ĐỊNH ghi trong comment nguồn**
//    ("Check tất cả HĐ trạng thái là A hoặc R") — tức `&&`. Khác biệt có chủ đích, đã ghi sổ để người quyết.
app.MapPost("/api/mktfees/finish", async (MktFeeKeyDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var code = (dto.MKTFeeCode ?? "").Trim();
    var row = await db.MktFees.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.MKTFeeCode == code);
    if (row is null) return Results.NotFound(new { error = $"Không có phiếu {code}." });
    if (row.MKTStatus != "A") return Results.BadRequest(new { error = $"Phiếu đang {row.MKTStatus}, chỉ kết thúc được khi 'A'." });
    var dtls = await db.MktFeeDetails.Where(d => d.OrgId == t.OrgId && d.MKTFeeCode == code).ToListAsync();
    if (dtls.Count == 0) return Results.BadRequest(new { error = "Phiếu không có dòng chi tiết nào." });

    var acts = dtls.Select(d => d.MKTActivityCode).ToList();
    var actMap = await db.MktActivities.Where(x => x.OrgId == t.OrgId && acts.Contains(x.MKTActivityCode))
        .ToDictionaryAsync(x => x.MKTActivityCode);
    foreach (var d in dtls)
    {
        if (d.MKTFeeDetailStatus != "A" && d.MKTFeeDetailStatus != "R")
            return Results.BadRequest(new { error = $"Dòng {d.MKTActivityCode} chưa chốt (trạng thái {d.MKTFeeDetailStatus}), phải là 'A' hoặc 'R'." });
        if (d.MKTFeeDetailStatus != "A") continue; // chỉ dòng được duyệt mới bị soi hồ sơ
        actMap.TryGetValue(d.MKTActivityCode, out var act);
        // Ba cờ hồ sơ chỉ bắt buộc khi hoạt động bật cờ = "1"…
        if (act?.FlagDesignImage == "1" && d.StatusDesignImage != "A")
            return Results.BadRequest(new { error = $"Dòng {d.MKTActivityCode}: ảnh thiết kế chưa được duyệt." });
        if (act?.FlagActualImage == "1" && d.StatusActualImage != "A")
            return Results.BadRequest(new { error = $"Dòng {d.MKTActivityCode}: ảnh thực tế chưa được duyệt." });
        if (act?.FlagContract == "1" && d.StatusContract != "A")
            return Results.BadRequest(new { error = $"Dòng {d.MKTActivityCode}: hợp đồng chưa được duyệt." });
        // …riêng hoá đơn KHÔNG có cờ gate, nguồn LUÔN bắt buộc "A".
        if (d.StatusInvoice != "A")
            return Results.BadRequest(new { error = $"Dòng {d.MKTActivityCode}: hoá đơn chưa được duyệt." });
    }
    row.MKTStatus = "F";
    row.LogLUDateTime = DateTime.Now;
    row.LogLUBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    await db.SaveChangesAsync();
    return Results.Ok(new { row.MKTFeeCode, row.MKTStatus });
}).RequireAuthorization();

// Xoá thường: chỉ khi "P", và CHẶN nếu đã có dòng chi tiết được duyệt.
app.MapPost("/api/mktfees/delete", async (MktFeeKeyDto dto, AppDbContext db, ITenantContext t) =>
{
    var code = (dto.MKTFeeCode ?? "").Trim();
    var row = await db.MktFees.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.MKTFeeCode == code);
    if (row is null) return Results.NotFound(new { error = $"Không có phiếu {code}." });
    if (row.MKTStatus != "P") return Results.BadRequest(new { error = $"Phiếu đang {row.MKTStatus}, chỉ xoá được khi 'P'." });
    var dtls = await db.MktFeeDetails.Where(d => d.OrgId == t.OrgId && d.MKTFeeCode == code).ToListAsync();
    var approved = dtls.Where(d => d.MKTFeeDetailStatus == "A").Select(d => d.MKTActivityCode).ToList();
    if (approved.Count > 0)
        return Results.BadRequest(new { error = $"Đã có dòng được duyệt, không xoá được: {string.Join(", ", approved.Take(10))}." });
    db.MktFeeDetails.RemoveRange(dtls);
    db.MktFees.Remove(row);
    await db.SaveChangesAsync();
    return Results.Ok(new { deleted = code });
}).RequireAuthorization();

// Xoá cưỡng chế: NGƯỢC LẠI — chỉ khi phiếu ĐÃ DUYỆT ("A"), xoá dây chuyền Attach + Detail rồi mới xoá đầu.
// ⚠️ Nguồn còn một câu xoá `MKT_MarketingFeeAttach` nhưng ĐANG BỊ COMMENT — bảng đó chưa port, ghi nợ.
// ⚠️ RBAC `myCommon_CheckHTCDirect` của nguồn chưa port (nợ chung toàn fleet).
app.MapPost("/api/mktfees/forcedelete", async (MktFeeKeyDto dto, AppDbContext db, ITenantContext t) =>
{
    var code = (dto.MKTFeeCode ?? "").Trim();
    var row = await db.MktFees.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.MKTFeeCode == code);
    if (row is null) return Results.NotFound(new { error = $"Không có phiếu {code}." });
    if (row.MKTStatus != "A") return Results.BadRequest(new { error = $"Xoá cưỡng chế chỉ áp dụng cho phiếu đã duyệt ('A'), phiếu đang {row.MKTStatus}." });
    var dtls = await db.MktFeeDetails.Where(d => d.OrgId == t.OrgId && d.MKTFeeCode == code).ToListAsync();
    db.MktFeeDetails.RemoveRange(dtls);
    db.MktFees.Remove(row);
    await db.SaveChangesAsync();
    return Results.Ok(new { forceDeleted = code, detailsRemoved = dtls.Count });
}).RequireAuthorization();

// ===== Master LOẠI hoạt động marketing (Mst_MarketingActivityType — port 1:1 cụm 4 hàm
// Get/_Create/_Update/_Delete_New20181115, 2010.HTC BizHTC.Marketing.cs 90/260/416/579) =====
// 🔴 Delete của nguồn là XOÁ THẬT (DataRow.Delete()), KHÔNG phải hạ FlagActive — và nguồn KHÔNG
//    kiểm tra loại này còn hoạt động nào đang dùng. Port giữ nguyên hành vi, chỉ trả kèm số hoạt động
//    sẽ bị mồ côi để người dùng thấy (`orphaned`), không tự ý thêm guard nguồn không có.
// 🔴 FlagActive theo TConst.Flag: "1" = Active, "0" = Inactive (KHÔNG phải "Y"/"N").
// ⚠️ RBAC nguồn CheckHTCDirect chưa port — nợ chung toàn fleet.
app.MapGet("/api/mktactivitytypes", async (AppDbContext db, ITenantContext t, string? code, string? flagActive) =>
{
    var qy = db.MktActivityTypes.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(code)) qy = qy.Where(x => x.MKTActivityTypeCode == code);
    if (!string.IsNullOrWhiteSpace(flagActive)) qy = qy.Where(x => x.FlagActive == flagActive);
