// ===== Hạn mức & thanh toán marketing theo năm/đại lý (Rpt_Marketing — port 1:1 cụm 5 hàm
// Rpt_MarketingGet/Create/UpdateMulti/Update/Approve_New20181115, 2010.HTC BizHTC.Marketing.cs
// 1617 / 1811 / 2182 / 2567 / 2822). TWIN: cả WS 32-bit lẫn 64-bit gọi cùng bản _New20181115. =====
// 🔴 RptStatus theo TConst.Stage: tạo = "P", duyệt = "A".
// 🔴 DUYỆT THEO NĂM, không theo đại lý: nguồn chạy `where MKTYear = @strMKTYear` — một phát cả năm.
// 🔴 UpdateMulti = XOÁ TRẮNG cả năm rồi INSERT lại (không sửa từng dòng); dòng mới về "P".
// ⚠️ RBAC nguồn (CheckHTCDirect + CheckAccessDealerData theo BUPattern) chưa port — nợ chung toàn fleet.
static bool MktYearValid(string y) =>
    y.Length == 4 && int.TryParse(y, out var n) && n >= 1900 && n <= 2100;

app.MapGet("/api/rptmarketing", async (AppDbContext db, ITenantContext t, string? mktYear, string? dealerCode, string? rptStatus) =>
{
    var qy = db.RptMarketings.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(mktYear)) qy = qy.Where(x => x.MKTYear == mktYear);
    if (!string.IsNullOrWhiteSpace(dealerCode)) qy = qy.Where(x => x.DealerCode == dealerCode);
    if (!string.IsNullOrWhiteSpace(rptStatus)) qy = qy.Where(x => x.RptStatus == rptStatus);
    var items = await qy.OrderBy(x => x.MKTYear).ThenBy(x => x.DealerCode).Select(x => new
    {
        x.Id, x.MKTYear, x.DealerCode,
        x.Limit1, x.Limit2, x.Limit3, x.Limit4,
        x.Payment1, x.Payment2, x.Payment3, x.Payment4,
        x.Remark, x.RptStatus, x.CreatedDate, x.CreatedBy, x.LogLUDateTime, x.LogLUBy,
        LimitTotal = (x.Limit1 ?? 0) + (x.Limit2 ?? 0) + (x.Limit3 ?? 0) + (x.Limit4 ?? 0),
        PaymentTotal = (x.Payment1 ?? 0) + (x.Payment2 ?? 0) + (x.Payment3 ?? 0) + (x.Payment4 ?? 0),
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Kiểm tra Limit/Payment âm — nguồn ném 8 mã lỗi riêng InvalidLimit1..4 / InvalidPayment1..4.
static string? MktNegative(RptMarketingRowDto r)
{
    if (r.Limit1 < 0) return "Limit1 âm."; if (r.Limit2 < 0) return "Limit2 âm.";
    if (r.Limit3 < 0) return "Limit3 âm."; if (r.Limit4 < 0) return "Limit4 âm.";
    if (r.Payment1 < 0) return "Payment1 âm."; if (r.Payment2 < 0) return "Payment2 âm.";
    if (r.Payment3 < 0) return "Payment3 âm."; if (r.Payment4 < 0) return "Payment4 âm.";
    return null;
}

app.MapPost("/api/rptmarketing/create", async (RptMarketingCreateDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var year = (dto.MKTYear ?? "").Trim();
    if (!MktYearValid(year)) return Results.BadRequest(new { error = "Năm không hợp lệ (4 chữ số, 1900..2100)." });
    var rows = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.DealerCode)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Bảng Rpt_Marketing đầu vào rỗng." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    foreach (var r in rows)
    {
        var neg = MktNegative(r);
        if (neg is not null) return Results.BadRequest(new { error = $"Đại lý {r.DealerCode}: {neg}" });
        // 🔴 Guard nguồn Rpt_MarketingActive_CheckDB với FlagExistToCheck = "N": cặp (năm, đại lý) PHẢI CHƯA có.
        var dup = await db.RptMarketings.AnyAsync(x => x.OrgId == t.OrgId && x.MKTYear == year && x.DealerCode == r.DealerCode);
        if (dup) return Results.BadRequest(new { error = $"Năm {year} đã có dòng cho đại lý {r.DealerCode}." });
    }
    foreach (var r in rows)
        db.RptMarketings.Add(new RptMarketing
        {
            OrgId = t.OrgId, MKTYear = year, DealerCode = r.DealerCode!.Trim(),
            Limit1 = r.Limit1, Limit2 = r.Limit2, Limit3 = r.Limit3, Limit4 = r.Limit4,
            Payment1 = r.Payment1, Payment2 = r.Payment2, Payment3 = r.Payment3, Payment4 = r.Payment4,
            Remark = r.Remark, RptStatus = "P",
            CreatedDate = now, CreatedBy = who, LogLUDateTime = now, LogLUBy = who,
        });
    await db.SaveChangesAsync();
    return Results.Ok(new { created = rows.Count, mktYear = year, rptStatus = "P" });
}).RequireAuthorization();

// 🔴 Nguồn XOÁ TRẮNG cả năm rồi insert lại — thay thế toàn bộ, không merge theo đại lý.
app.MapPost("/api/rptmarketing/updatemulti", async (RptMarketingCreateDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var year = (dto.MKTYear ?? "").Trim();
    if (!MktYearValid(year)) return Results.BadRequest(new { error = "Năm không hợp lệ (4 chữ số, 1900..2100)." });
    var rows = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.DealerCode)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Bảng Rpt_Marketing đầu vào rỗng." });
    foreach (var r in rows)
    {
        var neg = MktNegative(r);
        if (neg is not null) return Results.BadRequest(new { error = $"Đại lý {r.DealerCode}: {neg}" });
    }
    var old = await db.RptMarketings.Where(x => x.OrgId == t.OrgId && x.MKTYear == year).ToListAsync();
    // Guard nguồn Rpt_MarketingActive_CheckDB_Year: cả năm phải đang chờ duyệt.
    var notPending = old.Where(x => x.RptStatus != "P").Select(x => x.DealerCode).Distinct().ToList();
    if (notPending.Count > 0)
        return Results.BadRequest(new { error = $"Năm {year} đã duyệt/khoá ở các đại lý: {string.Join(", ", notPending.Take(10))}." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    db.RptMarketings.RemoveRange(old);
    foreach (var r in rows)
        db.RptMarketings.Add(new RptMarketing
        {
            OrgId = t.OrgId, MKTYear = year, DealerCode = r.DealerCode!.Trim(),
            Limit1 = r.Limit1, Limit2 = r.Limit2, Limit3 = r.Limit3, Limit4 = r.Limit4,
            Payment1 = r.Payment1, Payment2 = r.Payment2, Payment3 = r.Payment3, Payment4 = r.Payment4,
            Remark = r.Remark, RptStatus = "P",
            CreatedDate = now, CreatedBy = who, LogLUDateTime = now, LogLUBy = who,
        });
    await db.SaveChangesAsync();
    return Results.Ok(new { deleted = old.Count, created = rows.Count, mktYear = year });
}).RequireAuthorization();

// Sửa MỘT dòng: nguồn chỉ ghi cột có giá trị parse được (alColumnEffective); Remark luôn ghi đè.
app.MapPost("/api/rptmarketing/update", async (RptMarketingUpdateDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var year = (dto.MKTYear ?? "").Trim();
    var dealer = (dto.DealerCode ?? "").Trim();
    var row = await db.RptMarketings.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.MKTYear == year && x.DealerCode == dealer);
    if (row is null) return Results.NotFound(new { error = $"Không có dòng marketing năm {year} cho đại lý {dealer}." });
    // Guard nguồn: chỉ sửa được khi còn chờ duyệt.
    if (row.RptStatus != "P") return Results.BadRequest(new { error = $"Dòng đang ở trạng thái {row.RptStatus}, chỉ sửa được khi 'P'." });
    var neg = MktNegative(new RptMarketingRowDto(dealer, dto.Limit1, dto.Limit2, dto.Limit3, dto.Limit4, dto.Payment1, dto.Payment2, dto.Payment3, dto.Payment4, dto.Remark));
    if (neg is not null) return Results.BadRequest(new { error = neg });

    if (dto.Limit1 is not null) row.Limit1 = dto.Limit1;
    if (dto.Limit2 is not null) row.Limit2 = dto.Limit2;
    if (dto.Limit3 is not null) row.Limit3 = dto.Limit3;
    if (dto.Limit4 is not null) row.Limit4 = dto.Limit4;
    if (dto.Payment1 is not null) row.Payment1 = dto.Payment1;
    if (dto.Payment2 is not null) row.Payment2 = dto.Payment2;
    if (dto.Payment3 is not null) row.Payment3 = dto.Payment3;
    if (dto.Payment4 is not null) row.Payment4 = dto.Payment4;
    row.Remark = dto.Remark; // nguồn luôn ghi Remark, kể cả rỗng
    row.LogLUDateTime = DateTime.Now;
    row.LogLUBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    await db.SaveChangesAsync();
    return Results.Ok(new { row.MKTYear, row.DealerCode, row.RptStatus });
}).RequireAuthorization();

// 🔴 Duyệt CẢ NĂM một phát (nguồn: update … where MKTYear = @strMKTYear), không nhận DealerCode.
app.MapPost("/api/rptmarketing/approve", async (RptMarketingApproveDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var year = (dto.MKTYear ?? "").Trim();
    if (!MktYearValid(year)) return Results.BadRequest(new { error = "Năm không hợp lệ (4 chữ số, 1900..2100)." });
    var rows = await db.RptMarketings.Where(x => x.OrgId == t.OrgId && x.MKTYear == year).ToListAsync();
    if (rows.Count == 0) return Results.BadRequest(new { error = $"Năm {year} chưa có dòng marketing nào." });
    var notPending = rows.Where(x => x.RptStatus != "P").Select(x => x.DealerCode).Distinct().ToList();
    if (notPending.Count > 0)
        return Results.BadRequest(new { error = $"Năm {year} có dòng không ở trạng thái 'P': {string.Join(", ", notPending.Take(10))}." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    foreach (var r in rows) { r.RptStatus = "A"; r.LogLUDateTime = now; r.LogLUBy = who; }
    await db.SaveChangesAsync();
    return Results.Ok(new { approved = rows.Count, mktYear = year, rptStatus = "A" });
}).RequireAuthorization();

// ===== Nhật ký gọi API SBHOnline (OS_SBHOnline_Log — port 1:1 OS_SBHOnline_Log_Create,
// 2010.HTC BizHTC.DealerSales.cs:4433; 17 điểm gọi ở Biz.HTC.WH.cs + Biz.HTC.WH.hkt.cs) =====
// 🔴 HAI trục tên khác nhau: `FuncCall` = hàm nghiệp vụ ERP kích hoạt (DealerSalesDealCreate /
//    DealerSalesDealUpdateMulti / DealerSalesDealDelete); `FuncCode` = lệnh API SBHOnline
//    (fleet_owner_create / fleet_owner_update / fleet_create / fleet_update / fleet_car_id).
// 🔴 `ErrCode` KHÔNG phải mã số: "0" = thành công, ngược lại là THÔNG ĐIỆP lỗi nguyên văn
//    (`response.errorMessage`, hoặc `ex.Message + "/" + response.errorMessage`).
// 🔴 Nguồn KHÔNG có guard nào và catch nuốt trọn ⇒ POST không bao giờ trả 4xx vì lý do nghiệp vụ.
app.MapGet("/api/sbhonlineapilogs", async (AppDbContext db, ITenantContext t, string? dealNo, string? carId, string? funcCall, string? funcCode, string? createdBy, bool? onlyError) =>
{
    var qy = db.SbhOnlineApiLogs.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealNo)) qy = qy.Where(x => x.DealNo == dealNo);
    if (!string.IsNullOrWhiteSpace(carId)) qy = qy.Where(x => x.CarId == carId);
    if (!string.IsNullOrWhiteSpace(funcCall)) qy = qy.Where(x => x.FuncCall == funcCall);
    if (!string.IsNullOrWhiteSpace(funcCode)) qy = qy.Where(x => x.FuncCode == funcCode);
    if (!string.IsNullOrWhiteSpace(createdBy)) qy = qy.Where(x => x.CreatedBy == createdBy);
    // `ErrCode` khác "0" nghĩa là lỗi — bản thân nó CHÍNH LÀ thông điệp lỗi.
    if (onlyError == true) qy = qy.Where(x => x.ErrCode != "0");
    var items = await qy.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.FuncCall, x.FuncCode, x.RQ, x.RT, x.DealNo, x.CarId, x.ErrCode, x.CreatedDateTime, x.CreatedBy,
        Success = x.ErrCode == "0",
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/sbhonlineapilogs", async (SbhOnlineApiLogDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    // Nguồn không kiểm tra gì cả (region Check rỗng) — giữ nguyên, chỉ chuẩn hoá khoảng trắng.
    db.SbhOnlineApiLogs.Add(new SbhOnlineApiLog
    {
        OrgId = t.OrgId,
        FuncCall = dto.FuncCall, FuncCode = dto.FuncCode,
        RQ = dto.RQ, RT = dto.RT,
        DealNo = (dto.DealNo ?? "").Trim(), CarId = (dto.CarId ?? "").Trim(),
        ErrCode = string.IsNullOrWhiteSpace(dto.ErrCode) ? "0" : dto.ErrCode,
        CreatedDateTime = DateTime.Now,
        CreatedBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system",
    });
    await db.SaveChangesAsync();
    return Results.Ok(new { logged = true, success = string.IsNullOrWhiteSpace(dto.ErrCode) || dto.ErrCode == "0" });
}).RequireAuthorization();

// ===== Nhật ký đẩy xe đã bán sang CarService (DLS_LogCarSv — port 1:1 DSL_LogCarSvCreate,
// 2010.HTC BizHTC.DealerSales.cs:3974 / DSL_LogCarSvGet_New20181115:4104).
// TWIN: cả WSHTC 32-bit (WSHTC.cs:26209) lẫn 64-bit đều gọi cùng bản `_New20181115`. =====
// 🔴 `ErrCode = "0"` là THÀNH CÔNG; khác "0" là mã lỗi CarService trả về.
// 🔴 `FuncCode`: nhánh thành công ghi tên lệnh (`SerCustomerCarSalesCreate`, `OS_Ser_CarSalesUpd`,
//    `OS_Ser_CarSalesDelX`); nhánh lỗi ghi `PVal` — function code nơi phát sinh lỗi.
// 🔴 Nguồn NUỐT lỗi (catch chỉ rollback, không ném): ghi log hỏng KHÔNG được làm hỏng luồng bán xe.
//    Vì vậy POST dưới đây trả 200 kèm `logged=false` + `reason` thay vì 400.
// ⚠️ Nguồn lọc thêm theo `Mst_Dealer.BUCode like @strBUPatternOfUser` (RBAC) — nợ chung toàn fleet.
app.MapGet("/api/carsvlogs", async (AppDbContext db, ITenantContext t, string? dealNo, string? dealerCode, string? carId, string? vin, string? funcCode, string? errCode, string? createdBy, bool? onlyError) =>
{
    var qy = db.CarSvLogs.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealNo)) qy = qy.Where(x => x.DealNo == dealNo);
    if (!string.IsNullOrWhiteSpace(dealerCode)) qy = qy.Where(x => x.DealerCode == dealerCode);
    if (!string.IsNullOrWhiteSpace(carId)) qy = qy.Where(x => x.CarId == carId);
    if (!string.IsNullOrWhiteSpace(vin)) qy = qy.Where(x => x.VIN == vin);
    if (!string.IsNullOrWhiteSpace(funcCode)) qy = qy.Where(x => x.FuncCode == funcCode);
    if (!string.IsNullOrWhiteSpace(errCode)) qy = qy.Where(x => x.ErrCode == errCode);
    if (!string.IsNullOrWhiteSpace(createdBy)) qy = qy.Where(x => x.CreatedBy == createdBy);
    // Tiện dụng: chỉ lấy các lần đẩy LỖI (ErrCode khác "0").
    if (onlyError == true) qy = qy.Where(x => x.ErrCode != "0");
    var items = await qy.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.DealNo, x.DealerCode, x.CarId, x.VIN, x.FuncCode, x.ErrCode, x.CreatedDateTime, x.CreatedBy,
        Success = x.ErrCode == "0",
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/carsvlogs", async (CarSvLogDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var dealNo = (dto.DealNo ?? "").Trim();
    var carId = (dto.CarId ?? "").Trim();
    var vin = (dto.VIN ?? "").Trim();
    // 🔴 Guard nguồn, nhưng thất bại thì NUỐT (không ném) — đúng như `catch` của `DSL_LogCarSvCreate`.
    // MinLengthCode = 5 (TConst.HTCConst, Const.Main.cs:322).
    string? reason = null;
    if (dealNo.Length < 5) reason = "DealNo ngắn hơn MinLengthCode (5).";
    else if (vin.Length < 1) reason = "VIN rỗng.";
    else if (carId.Length < 1) reason = "CarId rỗng.";
    if (reason is not null) return Results.Ok(new { logged = false, reason });

    db.CarSvLogs.Add(new CarSvLog
    {
        OrgId = t.OrgId, DealNo = dealNo, DealerCode = (dto.DealerCode ?? "").Trim(),
        CarId = carId, VIN = vin, FuncCode = dto.FuncCode, ErrCode = dto.ErrCode ?? "0",
        CreatedDateTime = DateTime.Now,
        CreatedBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system",
    });
    await db.SaveChangesAsync();
    return Results.Ok(new { logged = true, success = (dto.ErrCode ?? "0") == "0" });
}).RequireAuthorization();

// ===== Nhật ký gọi API GPS (GPS_LogGPS — port 1:1 GPS_LogGPS_Add,
// 2010.HTC StorageFG/BizHTC.ConnGPSVelocaDMS.cs:1476) =====
// 🔴 Mỗi lần gọi API ghi HAI dòng chung một `LogId`: "RQ" trước khi gửi (Status rỗng) và
//    "RS" sau khi nhận (Status = kết quả, hoặc "FALSE" khi lỗi). Endpoint dưới đây phơi đúng mô hình đó.
// 🔴 `FunctionType` theo `TConst.TypeCallGPS`: MAPVIN · OUTSTO · GETADDRESSONLINE · SEARCHADDRESSS ·
//    DMSUNMAPVIN (giữ nguyên "SEARCHADDRESSS" thừa một chữ S của nguồn).
app.MapGet("/api/gpscalllogs", async (AppDbContext db, ITenantContext t, string? logId, string? logType, string? functionType, string? status) =>
{
    var qy = db.GpsCallLogs.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(logId)) qy = qy.Where(x => x.LogId == logId);
    if (!string.IsNullOrWhiteSpace(logType)) qy = qy.Where(x => x.LogType == logType.Trim().ToUpperInvariant());
    if (!string.IsNullOrWhiteSpace(functionType)) qy = qy.Where(x => x.FunctionType == functionType.Trim().ToUpperInvariant());
    if (!string.IsNullOrWhiteSpace(status)) qy = qy.Where(x => x.Status == status);
    var items = await qy.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.LogId, x.LogType, x.Status, x.Exception, x.DataSend, x.DataResponse,
        x.IDMSKey, x.FunctionName, x.FunctionType, x.Trycount, x.Url, x.Remark, x.CreatedAt
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Ghi một dòng nhật ký (dùng cho cả RQ lẫn RS — đúng như nguồn gọi cùng một hàm `GPS_LogGPS_Add`).
app.MapPost("/api/gpscalllogs", async (GpsCallLogDto dto, AppDbContext db, ITenantContext t) =>
{
    var logType = (dto.LogType ?? "RQ").Trim().ToUpperInvariant();
    if (logType is not ("RQ" or "RS")) return Results.BadRequest(new { error = "LogType = RQ | RS (TConst.LogTypeGPS)." });
    var fnType = string.IsNullOrWhiteSpace(dto.FunctionType) ? null : dto.FunctionType!.Trim().ToUpperInvariant();
    string[] okTypes = { "MAPVIN", "OUTSTO", "GETADDRESSONLINE", "SEARCHADDRESSS", "DMSUNMAPVIN" };
    if (fnType is not null && !okTypes.Contains(fnType))
        return Results.BadRequest(new { error = $"FunctionType không hợp lệ. Cho phép: {string.Join(", ", okTypes)}." });
    var logId = string.IsNullOrWhiteSpace(dto.LogId) ? Guid.NewGuid().ToString("N") : dto.LogId!.Trim();
    var row = new GpsCallLog
    {
        OrgId = t.OrgId, LogId = logId, LogType = logType,
        // Nguồn để Status RỖNG ở dòng RQ; "FALSE" khi lỗi phía RS.
        Status = logType == "RQ" ? "" : dto.Status,
        Exception = dto.Exception, DataSend = dto.DataSend, DataResponse = dto.DataResponse,
        IDMSKey = dto.IDMSKey, FunctionName = dto.FunctionName, FunctionType = fnType,
        Trycount = string.IsNullOrWhiteSpace(dto.Trycount) ? "1" : dto.Trycount, // nguồn luôn truyền "1"
        Url = dto.Url, Remark = dto.Remark,
    };
    db.GpsCallLogs.Add(row);
    await db.SaveChangesAsync();
    return Results.Ok(new { row.LogId, row.LogType, row.FunctionType, row.Status });
}).RequireAuthorization();

// Tra một lần gọi trọn vẹn: ghép cặp RQ + RS theo LogId.
app.MapGet("/api/gpscalllogs/{logId}/pair", async (string logId, AppDbContext db, ITenantContext t) =>
{
    var rows = await db.GpsCallLogs.Where(x => x.OrgId == t.OrgId && x.LogId == logId)
        .OrderBy(x => x.Id).ToListAsync();
    if (rows.Count == 0) return Results.NotFound(new { logId });
    var rq = rows.FirstOrDefault(x => x.LogType == "RQ");
    var rs = rows.FirstOrDefault(x => x.LogType == "RS");
    return Results.Ok(new
    {
        logId,
        request = rq is null ? null : new { rq.FunctionType, rq.FunctionName, rq.Url, rq.DataSend, rq.CreatedAt },
        response = rs is null ? null : new { rs.Status, rs.DataResponse, rs.Exception, rs.CreatedAt },
        completed = rq is not null && rs is not null,
    });
}).RequireAuthorization();

// ===== Kế hoạch bán lẻ theo tháng (Rpt_PlanRetail — port 1:1 Rpt_PlanRetail_Create/Approve/Cancel,
// 2010.HTC BizHTC.Report.cs:33001/33644/33900). TWIN: chỉ `TERP.WSHTC.64` (95765/95832/95901). =====
// 🔴 Trạng thái `TConst.PRStatus`: "P" mới tạo · "A" duyệt · "C" từ chối.
// ⚠️ Guard phản trực giác: **duyệt vào từ "P" HOẶC "C"** (bản đã từ chối duyệt lại được);
//    **từ chối chỉ vào từ "P"**.
// ⚠️ Phần sinh dữ liệu tổng hợp (`mySql_Rpt_PlanRetail_Create`) CHƯA port — endpoint nhận dòng từ client.
app.MapGet("/api/planretails", async (AppDbContext db, ITenantContext t, string? month, string? dealer, string? status) =>
{
    var qy = db.PlanRetails.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(month)) qy = qy.Where(x => x.PlanMonth == month);
    if (!string.IsNullOrWhiteSpace(dealer)) qy = qy.Where(x => x.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(status)) qy = qy.Where(x => x.PRStatus == status);
    var items = await qy.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.Id, x.PlanMonth, x.PlanTimes, x.PlanTimesPrev, x.DealerCode, x.PRStatus,
        x.ApprovedBy, x.ApprovedDate, x.CancelBy, x.CancelDate, x.CreatedBy, x.CreatedAt,
        lines = db.PlanRetailDtls.Count(l => l.OrgId == t.OrgId && l.PlanRetailId == x.Id),
        totalQty = db.PlanRetailDtls.Where(l => l.OrgId == t.OrgId && l.PlanRetailId == x.Id).Sum(l => (int?)l.Quantity) ?? 0
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/planretails", async (PlanRetailDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    if (string.IsNullOrWhiteSpace(dto.PlanMonth)) return Results.BadRequest(new { error = "Cần PlanMonth (YYYY-MM)." });
    if (string.IsNullOrWhiteSpace(dto.PlanTimes)) return Results.BadRequest(new { error = "Cần PlanTimes (lần lập trong tháng)." });
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Cần DealerCode." });
    var month = dto.PlanMonth.Trim(); var times = dto.PlanTimes.Trim(); var dealer = dto.DealerCode.Trim().ToUpperInvariant();
    // Khoá nghiệp vụ của nguồn: PlanMonth + PlanTimes + DealerCode.
    if (await db.PlanRetails.AnyAsync(x => x.OrgId == t.OrgId && x.PlanMonth == month && x.PlanTimes == times && x.DealerCode == dealer))
        return Results.BadRequest(new { error = $"Kế hoạch {month} lần {times} của đại lý {dealer} đã tồn tại!" });

    var h = new PlanRetail
    {
        OrgId = t.OrgId, PlanMonth = month, PlanTimes = times, PlanTimesPrev = dto.PlanTimesPrev,
        DealerCode = dealer, PRStatus = "P",
        CreatedBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system",
    };
    db.PlanRetails.Add(h); await db.SaveChangesAsync();
    var lines = (dto.Lines ?? new()).Where(l => l.Quantity > 0).ToList();
    foreach (var l in lines)
        db.PlanRetailDtls.Add(new PlanRetailDtl { OrgId = t.OrgId, PlanRetailId = h.Id, ModelCode = l.ModelCode, SpecCode = l.SpecCode, ColorCode = l.ColorCode, Quantity = l.Quantity });
    // Nguồn ghi CÙNG LÚC bảng gộp theo model (Rpt_PlanRetailModel) — gộp từ chi tiết.
    foreach (var g in lines.Where(l => !string.IsNullOrWhiteSpace(l.ModelCode)).GroupBy(l => l.ModelCode!.Trim().ToUpperInvariant()))
        db.PlanRetailModels.Add(new PlanRetailModel { OrgId = t.OrgId, PlanRetailId = h.Id, ModelCode = g.Key, Quantity = g.Sum(x => x.Quantity) });
    await db.SaveChangesAsync();
    return Results.Ok(new { h.Id, h.PlanMonth, h.PlanTimes, h.DealerCode, status = h.PRStatus, lines = lines.Count });
}).RequireAuthorization();

app.MapGet("/api/planretails/{id}/lines", async (long id, AppDbContext db, ITenantContext t) =>
{
    var h = await db.PlanRetails.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (h is null) return Results.NotFound(new { id });
    var lines = await db.PlanRetailDtls.Where(l => l.OrgId == t.OrgId && l.PlanRetailId == id)
        .Select(l => new { l.ModelCode, l.SpecCode, l.ColorCode, l.Quantity }).ToListAsync();
    var byModel = await db.PlanRetailModels.Where(m => m.OrgId == t.OrgId && m.PlanRetailId == id)
        .Select(m => new { m.ModelCode, m.Quantity }).ToListAsync();
    return Results.Ok(new { h.Id, h.PlanMonth, h.PlanTimes, h.DealerCode, h.PRStatus, count = lines.Count, lines, byModel });
}).RequireAuthorization();

app.MapPost("/api/planretails/{id}/{action}", async (long id, string action, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    if (action is not ("approve" or "cancel")) return Results.BadRequest(new { error = "action = approve|cancel" });
    var h = await db.PlanRetails.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (h is null) return Results.NotFound(new { id });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    if (action == "approve")
    {
        // Guard nguồn `Rpt_PlanRetail_Approve`: strPRStatusListToCheck = "P, C".
        if (h.PRStatus is not ("P" or "C"))
            return Results.BadRequest(new { error = $"Kế hoạch đang ở '{h.PRStatus}' — chỉ duyệt khi mới tạo (P) hoặc đã từ chối (C)." });
        h.PRStatus = "A"; h.ApprovedDate = DateTime.Now; h.ApprovedBy = who;
    }
    else
    {
        // Guard nguồn `Rpt_PlanRetail_Cancel`: PRStatus.Pending ⇒ CHỈ từ "P".
        if (h.PRStatus != "P")
            return Results.BadRequest(new { error = $"Kế hoạch đang ở '{h.PRStatus}' — chỉ từ chối khi còn mới tạo (P)." });
        h.PRStatus = "C"; h.CancelDate = DateTime.Now; h.CancelBy = who;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { h.Id, status = h.PRStatus });
}).RequireAuthorization();

// Tra LỊCH SỬ đẩy SBH online (`Rpt_PushSBHOnline_History`).
app.MapGet("/api/sbhonline/push-history", async (AppDbContext db, ITenantContext t, string? vin, string? dealNo) =>
{
    var qy = db.SbhOnlinePushHistories.Where(h => h.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(vin)) qy = qy.Where(h => h.VIN == vin.Trim().ToUpperInvariant());
    if (!string.IsNullOrWhiteSpace(dealNo)) qy = qy.Where(h => h.DealNo == dealNo);
    var items = await qy.OrderByDescending(h => h.Id).Take(500)
        .Select(h => new { h.VIN, h.CarId, h.DealNo, h.PushDate, h.PushBy, h.PushTo, h.PushStatus, h.FlagSucsess }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// ===== Đẩy Sổ Bảo Hành online (SbhOnline — port 1:1 Frm_RePostSBHOnline, SalesDealer) =====
app.MapGet("/api/sbhonline", async (AppDbContext db, ITenantContext t, string? dealNo, string? vin, string? status) =>
{
    var q = db.SbhOnlines.Where(s => s.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealNo)) q = q.Where(s => s.DealNo.Contains(dealNo!));
    if (!string.IsNullOrWhiteSpace(vin)) q = q.Where(s => s.VIN.Contains(vin!.ToUpper()));
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(s => s.PostStatus == status);
    var items = await q.OrderByDescending(s => s.Id).Take(500)
        .Select(s => new { s.VIN, s.CarId, s.DealNo, s.DealerCode, s.DeliveryDate, s.WarrantyExpiresDate, s.PostStatus, s.PushCount, s.LastPushAt }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/sbhonline", async (SbhOnlineDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.VIN)) return Results.BadRequest(new { error = "Chưa nhập số khung (VIN)." });
    var vin = dto.VIN.Trim().ToUpperInvariant();
    var ex = await db.SbhOnlines.FirstOrDefaultAsync(s => s.OrgId == t.OrgId && s.VIN == vin);
    if (ex is not null)
    {
        ex.CarId = dto.CarId ?? ""; ex.DealNo = dto.DealNo ?? ""; ex.DealerCode = dto.DealerCode ?? ""; ex.DeliveryDate = dto.DeliveryDate; ex.WarrantyExpiresDate = dto.WarrantyExpiresDate ?? ex.WarrantyExpiresDate;
        await db.SaveChangesAsync();
        return Results.Ok(new { ex.VIN, updated = true });
    }
    var s2 = new SbhOnline { OrgId = t.OrgId, VIN = vin, CarId = dto.CarId ?? "", DealNo = dto.DealNo ?? "", DealerCode = dto.DealerCode ?? "", DeliveryDate = dto.DeliveryDate, WarrantyExpiresDate = dto.WarrantyExpiresDate, PostStatus = "Pending" };
    db.SbhOnlines.Add(s2); await db.SaveChangesAsync();
    return Results.Ok(new { s2.VIN, updated = false });
}).RequireAuthorization();

// Đẩy / đẩy lại SBH lên online: Pending->Posted (hoặc Posted->Posted = đẩy lại), tăng PushCount.
app.MapPost("/api/sbhonline/{vin}/push", async (string vin, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    vin = vin.Trim().ToUpperInvariant();
    var s = await db.SbhOnlines.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.VIN == vin);
    if (s is null) return Results.NotFound(new { vin });
    // 🔴 Guard nguồn `RePush_SBHOnline` (Biz.HTC.WH.hkt.cs:5867): xe KHÔNG có ngày hết hạn bảo hành
    //    thì chặn đẩy (`RePush_SBHOnline_InvalidWarrantyExpiresDate`).
    if (s.WarrantyExpiresDate is null)
        return Results.BadRequest(new { error = $"Xe {vin} chưa có ngày hết hạn bảo hành — không đẩy được SBH online." });
    var wasRepush = s.PostStatus == "Posted";
    var now = DateTime.Now;
    s.PostStatus = "Posted"; s.PushCount += 1; s.LastPushAt = now;
    // 🔴 Nguồn ghi lịch sử mỗi lần đẩy (`SBHOnline_HistoryCreate` → `Rpt_PushSBHOnline_History`) —
    //    port cũ chỉ tăng bộ đếm, không lưu ai đẩy / đẩy đi đâu / kết quả ra sao.
    db.SbhOnlinePushHistories.Add(new SbhOnlinePushHistory
    {
        OrgId = t.OrgId, DealNo = s.DealNo, CarId = s.CarId, VIN = s.VIN,
        PushDate = now, PushBy = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system",
        PushTo = "SBHOnline", PushStatus = s.PostStatus, FlagSucsess = "1",
    });
    await db.SaveChangesAsync();
    return Results.Ok(new { s.VIN, status = s.PostStatus, s.PushCount, rePush = wasRepush, message = "Đẩy thành công!" });
}).RequireAuthorization();

// Đẩy hàng loạt VIN đã chọn.
app.MapPost("/api/sbhonline/pushbatch", async (SbhBatchDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var vins = (dto.Vins ?? new()).Select(v => (v ?? "").Trim().ToUpperInvariant()).Where(v => v != "").Distinct().ToList();
    if (vins.Count == 0) return Results.BadRequest(new { error = "Chưa chọn VIN để đẩy." });
    var rows = await db.SbhOnlines.Where(s => s.OrgId == t.OrgId && vins.Contains(s.VIN)).ToListAsync();
    // 🔴 Cùng guard với đẩy đơn lẻ: xe chưa có ngày hết hạn bảo hành thì nguồn chặn đẩy.
    var blocked = rows.Where(x => x.WarrantyExpiresDate is null).Select(x => x.VIN).ToList();
    if (blocked.Count > 0)
        return Results.BadRequest(new { error = $"Các xe sau chưa có ngày hết hạn bảo hành: {string.Join(", ", blocked.Take(10))}" });
    var now = DateTime.Now;
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    foreach (var s in rows)
    {
        s.PostStatus = "Posted"; s.PushCount += 1; s.LastPushAt = now;
        // Mỗi VIN được đẩy đều ghi một dòng lịch sử, đúng như nguồn gọi `SBHOnline_HistoryCreate` theo từng xe.
        db.SbhOnlinePushHistories.Add(new SbhOnlinePushHistory
        {
            OrgId = t.OrgId, DealNo = s.DealNo, CarId = s.CarId, VIN = s.VIN,
            PushDate = now, PushBy = who, PushTo = "SBHOnline", PushStatus = s.PostStatus, FlagSucsess = "1",
        });
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { pushed = rows.Count, message = "Đẩy thành công!" });
}).RequireAuthorization();

// ===== Đồng bộ VIN↔GPS từ file (GpsVinSync — port 1:1 FrmDongBoVIN, StoFGPS) =====
app.MapGet("/api/gpsvinsync", async (AppDbContext db, ITenantContext t, string? vin, string? gpsId, string? batch) =>
{
    var q = db.GpsVinSyncs.Where(s => s.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(vin)) q = q.Where(s => s.VIN.Contains(vin!.ToUpper()));
    if (!string.IsNullOrWhiteSpace(gpsId)) q = q.Where(s => s.GpsId.Contains(gpsId!));
    if (!string.IsNullOrWhiteSpace(batch)) q = q.Where(s => s.BatchNo == batch);
    var items = await q.OrderByDescending(s => s.Id).Take(500)
        .Select(s => new { s.BatchNo, s.VIN, s.GpsId, s.MapTime, s.CreatedAt }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Đồng bộ 1 lô VIN-GPS (validate từng dòng + phát hiện trùng trong file).
app.MapPost("/api/gpsvinsync", async (GpsVinSyncDto dto, AppDbContext db, ITenantContext t) =>
{
    var rows = dto.Rows ?? new();
    if (rows.Count == 0) return Results.BadRequest(new { error = "File Excel import không có dữ liệu!" });
    var seen = new HashSet<string>();
    var parsed = new List<(string vin, string gps, DateTime mt)>();
    foreach (var r in rows)
    {
        if (string.IsNullOrWhiteSpace(r.VIN)) return Results.BadRequest(new { error = "VIN không được trống!" });
        if (string.IsNullOrWhiteSpace(r.GpsId)) return Results.BadRequest(new { error = "GPS ID không được trống!" });
        if (string.IsNullOrWhiteSpace(r.MapTime)) return Results.BadRequest(new { error = "Thời điểm map không được trống!" });
        if (!DateTime.TryParse(r.MapTime, out var mt)) return Results.BadRequest(new { error = "Thời điểm map không phải kiểu ngày tháng!" });
        var vin = r.VIN.Trim().ToUpperInvariant(); var gps = r.GpsId.Trim();
        var key = vin + "|" + gps;
        if (!seen.Add(key)) return Results.BadRequest(new { error = $"VIN: '{vin}' - GPS ID: '{gps}' bị lặp trong file excel!" });
        parsed.Add((vin, gps, mt));
    }
    var batchNo = "SYNC" + DateTime.Now.ToString("yyMMddHHmmss");
    foreach (var (vin, gps, mt) in parsed)
        db.GpsVinSyncs.Add(new GpsVinSync { OrgId = t.OrgId, BatchNo = batchNo, VIN = vin, GpsId = gps, MapTime = mt });
    await db.SaveChangesAsync();
    return Results.Ok(new { batchNo, synced = parsed.Count, message = "Đồng bộ thành công!" });
}).RequireAuthorization();

// ===== Nhà vận chuyển xác nhận biên bản giao nhận (TranspDlvConfirm — port 1:1 FrmMngDlvMinutes, TERP.TranspClient) =====
app.MapGet("/api/transpdlv", async (AppDbContext db, ITenantContext t, string? transporter, string? no, string? status) =>
{
    var q = db.TranspDlvConfirms.Where(m => m.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(transporter)) q = q.Where(m => m.TransporterCode == transporter);
    if (!string.IsNullOrWhiteSpace(no)) q = q.Where(m => m.DlvMinutesNo.Contains(no!));
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(m => m.ConfirmStatus == status);
    var items = await q.OrderByDescending(m => m.Id).Take(500).Select(m => new
    {
        m.DlvMinutesNo, m.TransporterCode, m.DealerCode, m.ConfirmStatus, m.Remark, m.ConfirmDate, m.CreatedAt,
        m.FDlvMnStatus, m.TDlvMnStatus, m.FApprovedDate, m.FApprovedBy, m.TApprovedDate, m.TApprovedBy,
        m.TranspReqNo, m.TranspReqType, m.RefOrdNo, m.FStorageCode, m.TStorageCode, m.DlvStartDate, m.DlvEndDate,
        m.GPSDvNo, m.DlvEndGPSDateTime,
        cars = db.TranspDlvConfirmCars.Count(c => c.OrgId == t.OrgId && c.TranspDlvConfirmId == m.Id)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/transpdlv", async (TranspDlvDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.TransporterCode)) return Results.BadRequest(new { error = "Chưa chọn đơn vị vận tải." });
    var cars = (dto.Cars ?? new()).Where(c => !string.IsNullOrWhiteSpace(c.VIN)).ToList();
    if (cars.Count == 0) return Results.BadRequest(new { error = "Chưa có xe trên biên bản giao nhận." });
    var dupe = cars.GroupBy(c => c.VIN.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"VIN {dupe.Key} bị trùng!" });
    var no = "BBGN" + DateTime.Now.ToString("yyMMddHHmmss");
    var m2 = new TranspDlvConfirm
    {
        OrgId = t.OrgId, DlvMinutesNo = no, TransporterCode = dto.TransporterCode.Trim(),
        DealerCode = dto.DealerCode ?? "", ConfirmStatus = "Pending",
        // Hai phía duyệt độc lập, đều bắt đầu ở P (TConst.Stage.Pending).
        FDlvMnStatus = "P", TDlvMnStatus = "P",
        TranspReqNo = dto.TranspReqNo, TranspReqType = dto.TranspReqType, RefOrdNo = dto.RefOrdNo,
        FStorageCode = dto.FStorageCode, TStorageCode = dto.TStorageCode,
        FAddress = dto.FAddress, TAddress = dto.TAddress,
        DlvStartDate = dto.DlvStartDate, PlateNo = dto.PlateNo, DriverId = dto.DriverId
    };
    db.TranspDlvConfirms.Add(m2); await db.SaveChangesAsync();
    foreach (var c in cars)
        db.TranspDlvConfirmCars.Add(new TranspDlvConfirmCar { OrgId = t.OrgId, TranspDlvConfirmId = m2.Id, VIN = c.VIN.Trim().ToUpperInvariant(), ModelCode = c.ModelCode ?? "" });
    await db.SaveChangesAsync();
    return Results.Ok(new { m2.DlvMinutesNo, cars = cars.Count });
}).RequireAuthorization();

app.MapGet("/api/transpdlv/{no}/cars", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var m = await db.TranspDlvConfirms.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlvMinutesNo == no);
    if (m is null) return Results.NotFound(new { no });
    var cars = await db.TranspDlvConfirmCars.Where(c => c.OrgId == t.OrgId && c.TranspDlvConfirmId == m.Id)
        .Select(c => new { c.VIN, c.ModelCode }).ToListAsync();
    return Results.Ok(new { m.DlvMinutesNo, m.TransporterCode, m.ConfirmStatus, m.Remark, m.ConfirmDate, count = cars.Count, cars });
}).RequireAuthorization();

// ⚠️ #199 ĐÃ BỎ `POST /api/transpdlv/{no}/confirm` — **nguồn KHÔNG có lệnh này**. Ba bằng chứng độc lập:
//   1. Hệ nhà vận chuyển `TERP.WSTransp/App_Code/WSTransp.cs` chỉ có **MỘT** lệnh ghi:
//      `Sto_TranspPlanApprovedByTransporter` — duyệt **KẾ HOẠCH VẬN CHUYỂN**, không phải biên bản giao nhận.
//      (Lệnh đó ĐÃ port: `POST /api/transplans/{vinPlan}/transporter-approve`.)
//   2. Màn gốc `TERP.TranspClient/Views/Transp/FrmMngDlvMinutes.cs` (717 dòng) có đúng **ba** nút:
//      `btnExport` · `btnSearch` · `btnClose` ⇒ **màn CHỈ ĐỌC**, không có nút xác nhận nào.
//   3. Grep toàn `TERP.BizHTC`: bảng `Sto_DlvMinutes` **không có cột `ConfirmStatus`**; trục trạng thái
//      thật là `FDlvMnStatus`/`TDlvMnStatus` (P/A/R) — đã port ở `/api/dlvminutes/{no}/approve` (#159).
//   ⇒ Cùng cách xử lý với `/dlrcontracts/{no}/finish` (#198) và `/deliver`+`/reject` (#175).

// ===== Biên bản giao nhận xe: duyệt HAI PHÍA + bảng kiểm tra tình trạng xe =====
// Port 1:1 FrmHTCMngDlvMinutes + FrmHTCNewDlvMinutes (2010.HTC TERP.HTCClient/Views/Sales/DlvMinutes).
// TWIN đã trace: WSHTC.Sto_DlvMinutes_Approved → biz Sto_DlvMinutes_Approve_New20190416 (KHÔNG phải hàm trùng tên).

// Danh mục mục kiểm tra — đúng phần đuôi các cột FSTATUS_*/TSTATUS_* của bảng Sto_DlvMinutes.
// Nguồn trải thành 68 cột phẳng (34 mục × 2 phía); ở đây giữ nguyên danh mục nhưng lưu theo dòng.
var dlvCheckItemCatalog = new (string Group, string Code)[]
{
    // OS — ngoại thất
    ("OS", "Chassis"), ("OS", "Paint"), ("OS", "Glass"), ("OS", "Wipers"), ("OS", "Mirrors"),
    ("OS", "LightSystem"), ("OS", "Antenna"), ("OS", "Logo"), ("OS", "Moulding"), ("OS", "CementDust"),
    // IS — nội thất
    ("IS", "InstrumentPanel"), ("IS", "Switchs"), ("IS", "Sunvisor"), ("IS", "CigarLighter"), ("IS", "Mirror"),
    ("IS", "RadioCD"), ("IS", "AirCondition"), ("IS", "Seats"), ("IS", "RoofLamps"), ("IS", "RoofMat"),
    ("IS", "FloorPanel"), ("IS", "TrimPanel"), ("IS", "KeyAndRemote"), ("IS", "Filter"),
    // SP — phụ tùng kèm xe
    ("SP", "SpareWheel"), ("SP", "WheelCover"), ("SP", "ToolBag"), ("SP", "KeyEnvelope"),
    // DA — giấy tờ kèm xe
    ("DA", "OriginalCertificate"), ("DA", "UserManual"), ("DA", "CDGuaranty"),
    ("DA", "GuarantyBooklet"), ("DA", "OriginalInvoice"), ("DA", "StampedInvoice"),
};
var dlvCheckItemCodes = dlvCheckItemCatalog.Select(i => i.Code).ToHashSet(StringComparer.OrdinalIgnoreCase);

// Danh mục mục kiểm tra để client dựng form (nguồn là các nhãn cố định trên FrmHTCNewDlvMinutes).
app.MapGet("/api/transpdlv/checkitems", () => Results.Ok(new
{
    count = dlvCheckItemCatalog.Length,
    groups = dlvCheckItemCatalog.GroupBy(i => i.Group)
        .Select(g => new { group = g.Key, items = g.Select(i => i.Code).ToArray() })
})).RequireAuthorization();

// Bảng kiểm tra tình trạng xe của một biên bản, kèm trạng thái duyệt hai phía.
app.MapGet("/api/transpdlv/{no}/checkitems", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var m = await db.TranspDlvConfirms.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlvMinutesNo == no);
    if (m is null) return Results.NotFound(new { no });
    var items = await db.DlvMinutesCheckItems
        .Where(i => i.OrgId == t.OrgId && i.TranspDlvConfirmId == m.Id)
        .Select(i => new { i.ItemGroup, i.ItemCode, i.FStatus, i.TStatus }).ToListAsync();
    return Results.Ok(new
    {
        m.DlvMinutesNo, m.TranspReqNo, m.TranspReqType,
        m.FDlvMnStatus, m.TDlvMnStatus, m.FApprovedDate, m.FApprovedBy, m.TApprovedDate, m.TApprovedBy,
        m.FStorageCode, m.TStorageCode, m.FAddress, m.TAddress, m.DlvStartDate, m.DlvEndDate,
        m.PlateNo, m.DriverId, m.TPlateNo, m.TDriverId, m.FRemark, m.TRemark,
        m.FStatusIaKm, m.TStatusIaKm, m.FStatusIaRemark, m.TStatusIaRemark,
        count = items.Count, items
    });
}).RequireAuthorization();

// Ghi bảng kiểm tra + thông tin tuyến của MỘT phía (side = F bên giao, T bên nhận).
// Nguồn chỉ cho sửa khi biên bản CHƯA duyệt phía F (btnUpdate_Click).
app.MapPost("/api/transpdlv/{no}/checkitems", async (
    string no, DlvCheckSheetDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var m = await db.TranspDlvConfirms.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlvMinutesNo == no);
    if (m is null) return Results.NotFound(new { no });

    var side = (dto.Side ?? "").Trim().ToUpperInvariant();
    if (side is not ("F" or "T")) return Results.BadRequest(new { error = "Side = F (bên giao) | T (bên nhận)" });

    // Giữ nguyên câu thông báo của form gốc.
    if (m.FDlvMnStatus == "A")
        return Results.BadRequest(new { error = "Biên bản giao nhận đã được phê duyệt, không được phép sửa" });

    var lines = dto.Items ?? new();
    var unknown = lines.FirstOrDefault(l => !dlvCheckItemCodes.Contains((l.ItemCode ?? "").Trim()));
    if (unknown is not null)
        return Results.BadRequest(new { error = $"Mục kiểm tra không hợp lệ: {unknown.ItemCode}" });
    var duplicated = lines.GroupBy(l => l.ItemCode!.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (duplicated is not null)
        return Results.BadRequest(new { error = $"Mục kiểm tra {duplicated.Key} bị trùng!" });

    var existing = await db.DlvMinutesCheckItems
        .Where(i => i.OrgId == t.OrgId && i.TranspDlvConfirmId == m.Id).ToListAsync();
    foreach (var line in lines)
    {
        var code = line.ItemCode!.Trim();
        var row = existing.FirstOrDefault(i => string.Equals(i.ItemCode, code, StringComparison.OrdinalIgnoreCase));
        if (row is null)
        {
            row = new DlvMinutesCheckItem
            {
                OrgId = t.OrgId, TranspDlvConfirmId = m.Id, ItemCode = code,
                ItemGroup = dlvCheckItemCatalog.First(i => string.Equals(i.Code, code, StringComparison.OrdinalIgnoreCase)).Group
            };
            db.DlvMinutesCheckItems.Add(row);
            existing.Add(row);
        }
        // Chỉ ghi đè cột của đúng phía đang nhập — phía kia giữ nguyên kết quả đã chấm.
        if (side == "F") row.FStatus = line.Status; else row.TStatus = line.Status;
    }

    if (side == "F")
    {
        m.FStorageCode = dto.StorageCode ?? m.FStorageCode;
        m.FAddress = dto.Address ?? m.FAddress;
        m.PlateNo = dto.PlateNo ?? m.PlateNo;
        m.DriverId = dto.DriverId ?? m.DriverId;
        m.FRemark = dto.Remark ?? m.FRemark;
        m.FStatusIaKm = dto.StatusIaKm ?? m.FStatusIaKm;
        m.FStatusIaRemark = dto.StatusIaRemark ?? m.FStatusIaRemark;
        m.DlvStartDate = dto.DlvDate ?? m.DlvStartDate;
    }
    else
    {
        m.TStorageCode = dto.StorageCode ?? m.TStorageCode;
        m.TAddress = dto.Address ?? m.TAddress;
        m.TPlateNo = dto.PlateNo ?? m.TPlateNo;
        m.TDriverId = dto.DriverId ?? m.TDriverId;
        m.TRemark = dto.Remark ?? m.TRemark;
        m.TStatusIaKm = dto.StatusIaKm ?? m.TStatusIaKm;
        m.TStatusIaRemark = dto.StatusIaRemark ?? m.TStatusIaRemark;
        m.DlvEndDate = dto.DlvDate ?? m.DlvEndDate;
    }

    await db.SaveChangesAsync();
    return Results.Ok(new { m.DlvMinutesNo, side, saved = lines.Count });
}).RequireAuthorization();

// ⚠️ #200 HỢP NHẤT — ĐÃ BỎ `POST /api/transpdlv/{no}/approve`: **trùng lặp** với
//    `POST /api/dlvminutes/{no}/approve` (#159). Hai route cùng ghi MỘT bảng (`TranspDlvConfirms`) và cùng
//    port MỘT hàm nguồn `Sto_DlvMinutes_Approve_New20190416` — vi phạm §1, chỉ lộ ra khi audit nợ sweep #194.
//    · Bản #159 có **side-effect ghi ngược ngày xuất kho lên 4 chứng từ nguồn**; bản này KHÔNG có ⇒ gọi nhầm
//      route sẽ duyệt biên bản mà bỏ trắng toàn bộ side-effect.
//    · Đổi lại, bản này có guard `FDlvMnStatus == "P"` mà #159 thiếu ⇒ đã **mang guard sang bản #159**
//      trước khi gỡ (đúng luật `C0-ducentesimusnonagesimusprimus`: không được gỡ mất thứ chỉ bản kia có).
//    · `side=T` là **BỊA**: chữ ký nguồn chỉ có `strDlvMnNo` + `strFromFlagUnapprove`, không có tham số phía;
//      dòng ghi `TDlvMnStatus` trong nguồn bị comment cố ý (--20131126). Không lệnh nào của WS duyệt phía T.
//    🔴 TWIN FILE: `Sto_DlvMinutes_Approve_New20190416` có ở CẢ `DataWH/Biz.HTC.WH.cs:138340` LẪN
//      `DataWH/Biz.HTC.WH.Rel.20230823.cs:130768`; file `.Rel.20230823.cs` **không có trong csproj** ⇒ FILE CHẾT.
//      Bản LIVE là `Biz.HTC.WH.cs` (csproj dòng 272) — đúng bản #159 đã dùng.

// Sửa thông tin bàn giao cho đại lý — chỉ mở khi CẢ HAI phía đã duyệt (btnUpdateDealer_Click).
app.MapPost("/api/transpdlv/{no}/updatedealer", async (
    string no, DlvUpdateDealerDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var m = await db.TranspDlvConfirms.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlvMinutesNo == no);
    if (m is null) return Results.NotFound(new { no });

    if (m.FDlvMnStatus != "A" || m.TDlvMnStatus != "A")
        return Results.BadRequest(new { error = "Biên bản bàn gian chưa phê duyệt, không được phép sửa cho đại lý" });

    if (!string.IsNullOrWhiteSpace(dto.DealerCode)) m.DealerCode = dto.DealerCode.Trim().ToUpperInvariant();
    m.TAddress = dto.TAddress ?? m.TAddress;
    m.DlvEndDate = dto.DlvEndDate ?? m.DlvEndDate;
    m.TRemark = dto.TRemark ?? m.TRemark;

    await db.SaveChangesAsync();
    return Results.Ok(new { m.DlvMinutesNo, m.DealerCode, m.TAddress, m.DlvEndDate });
}).RequireAuthorization();

// ===== Báo cáo bán hàng HMC (HmcSalesRecord — port 1:1 FrmHMCReport, SalesDealer) =====
app.MapPost("/api/hmcsales", async (HmcSalesDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.VIN)) return Results.BadRequest(new { error = "Chưa nhập số khung (VIN)." });
    if (dto.TransactionDate is null) return Results.BadRequest(new { error = "Chưa nhập ngày giao dịch." });
    var r = new HmcSalesRecord { OrgId = t.OrgId, VIN = dto.VIN.Trim().ToUpperInvariant(), DealerCode = dto.DealerCode ?? "", ModelCode = dto.ModelCode ?? "", TransactionDate = dto.TransactionDate.Value, DeliveryType = dto.DeliveryType ?? "", SalesType = dto.SalesType ?? "" };
    db.HmcSalesRecords.Add(r); await db.SaveChangesAsync();
    return Results.Ok(new { r.VIN });
}).RequireAuthorization();

// Báo cáo HMC theo khoảng ngày: dòng theo VIN (ngày yyyyMMdd, loại giao, loại bán tách N/O) + tổng hợp.
app.MapGet("/api/hmcreport", async (AppDbContext db, ITenantContext t, DateTime? from, DateTime? to, string? dealer) =>
{
    var q = db.HmcSalesRecords.Where(r => r.OrgId == t.OrgId);
    if (from is not null) q = q.Where(r => r.TransactionDate >= from.Value.Date);
    if (to is not null) q = q.Where(r => r.TransactionDate < to.Value.Date.AddDays(1));
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(r => r.DealerCode == dealer);
    var recs = await q.OrderBy(r => r.TransactionDate).Take(2000).ToListAsync();
    var rows = recs.Select(r => new
    {
        transactionDate = r.TransactionDate.ToString("yyyyMMdd"),
        r.VIN, r.DealerCode, r.ModelCode, r.DeliveryType, r.SalesType,
        n = r.SalesType.Length >= 1 ? r.SalesType.Substring(0, 1) : "",   // ký tự 1 (field N)
        o = r.SalesType.Length >= 2 ? r.SalesType.Substring(1, 1) : ""    // ký tự 2 (field O)
    }).ToList();
    var byDelivery = recs.GroupBy(r => string.IsNullOrEmpty(r.DeliveryType) ? "(chưa rõ)" : r.DeliveryType)
        .Select(g => new { deliveryType = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    var bySalesType = recs.GroupBy(r => string.IsNullOrEmpty(r.SalesType) ? "(chưa rõ)" : r.SalesType)
        .Select(g => new { salesType = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    return Results.Ok(new { total = rows.Count, byDelivery, bySalesType, rows });
}).RequireAuthorization();

// ===== Báo cáo back-order / đơn hàng chưa giao (BackOrder — port 1:1 FrmBackOrderByModel + FrmBackOrderByDealer) =====
app.MapPost("/api/backorder", async (BackOrderDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.ModelCode)) return Results.BadRequest(new { error = "Chưa nhập model." });
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Chưa nhập đại lý." });
    if (dto.QtyOrder <= 0) return Results.BadRequest(new { error = "Số lượng đặt phải > 0." });
    var deliv = Math.Max(0, Math.Min(dto.QtyDelivered, dto.QtyOrder));
    var b = new BackOrder { OrgId = t.OrgId, DealerCode = dto.DealerCode.Trim(), DealerName = dto.DealerName ?? "", ModelCode = dto.ModelCode.Trim(), SpecDesc = dto.SpecDesc ?? "", QtyOrder = dto.QtyOrder, QtyDelivered = deliv };
    db.BackOrders.Add(b); await db.SaveChangesAsync();
    return Results.Ok(new { b.ModelCode, b.DealerCode, backOrder = b.QtyOrder - b.QtyDelivered });
}).RequireAuthorization();

// Báo cáo back-order theo MODEL (gom theo model/spec).
app.MapGet("/api/backorder/bymodel", async (AppDbContext db, ITenantContext t, string? dealer) =>
{
    var q = db.BackOrders.Where(b => b.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(b => b.DealerCode == dealer);
    var recs = await q.ToListAsync();
    var rows = recs.GroupBy(b => new { b.ModelCode, b.SpecDesc })
        .Select(g => new { modelCode = g.Key.ModelCode, specDesc = g.Key.SpecDesc, qtyOrder = g.Sum(x => x.QtyOrder), qtyDelivered = g.Sum(x => x.QtyDelivered), backOrder = g.Sum(x => x.QtyOrder - x.QtyDelivered) })
        .Where(x => true).OrderByDescending(x => x.backOrder).ToList();
    return Results.Ok(new { totalBackOrder = rows.Sum(x => x.backOrder), rows });
}).RequireAuthorization();

// Báo cáo back-order theo ĐẠI LÝ (gom theo đại lý).
app.MapGet("/api/backorder/bydealer", async (AppDbContext db, ITenantContext t, string? model) =>
{
    var q = db.BackOrders.Where(b => b.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(model)) q = q.Where(b => b.ModelCode == model);
    var recs = await q.ToListAsync();
    var rows = recs.GroupBy(b => new { b.DealerCode, b.DealerName })
        .Select(g => new { dealerCode = g.Key.DealerCode, dealerName = g.Key.DealerName, qtyOrder = g.Sum(x => x.QtyOrder), qtyDelivered = g.Sum(x => x.QtyDelivered), backOrder = g.Sum(x => x.QtyOrder - x.QtyDelivered) })
        .OrderByDescending(x => x.backOrder).ToList();
    return Results.Ok(new { totalBackOrder = rows.Sum(x => x.backOrder), rows });
}).RequireAuthorization();

// ===== Báo cáo bảo lãnh đến hạn thanh toán (port 1:1 FrmBLDenHanThanhToan) — tái dùng BankGuarantee =====
app.MapGet("/api/report/bldenhan", async (AppDbContext db, ITenantContext t, DateTime? from, DateTime? to) =>
{
    if (from is null) return Results.BadRequest(new { error = "Phải chọn ngày báo cáo từ" });
    var toDate = to ?? DateTime.Today;
    if (toDate.Date > DateTime.Today) return Results.BadRequest(new { error = "Ngày kết thúc bảo lãnh đến không được lớn hơn ngày hiện tại!" });
    var f = from.Value.Date; var e = toDate.Date.AddDays(1);
    // BL đến hạn = ngày hết hạn (DateExpired) rơi vào [from, to], đã duyệt, chưa tất toán.
    var recs = await db.BankGuarantees.Where(g => g.OrgId == t.OrgId && g.Status == "Approved" && g.FlagSettled != "1"
                    && g.DateExpired != null && g.DateExpired >= f && g.DateExpired < e).ToListAsync();
    var detail = recs.OrderBy(g => g.DateExpired).Select(g => new
    {
        g.GuaranteeNo, g.DealerCode, g.BankCode, g.BankGuaranteeNo, g.TotalAmount,
        dateExpired = g.DateExpired!.Value.ToString("yyyy-MM-dd"),
        daysLeft = (int)(g.DateExpired!.Value.Date - DateTime.Today).TotalDays
    }).ToList();
    var byBank = recs.GroupBy(g => string.IsNullOrEmpty(g.BankCode) ? "(chưa rõ)" : g.BankCode)
        .Select(g => new { bankCode = g.Key, count = g.Count(), totalAmount = g.Sum(x => x.TotalAmount) })
        .OrderByDescending(x => x.totalAmount).ToList();
    return Results.Ok(new { total = detail.Count, totalAmount = recs.Sum(g => g.TotalAmount), byBank, detail });
}).RequireAuthorization();

// ===== Báo cáo dư nợ bảo lãnh (port 1:1 FrmBaocaoBaolanh) — tái dùng BankGuarantee, gom theo NH + trạng thái =====
app.MapGet("/api/report/guarantee", async (AppDbContext db, ITenantContext t, string? grtNo, DateTime? openFrom, DateTime? openTo, string? bank) =>
{
    var q = db.BankGuarantees.Where(g => g.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(grtNo)) q = q.Where(g => g.GuaranteeNo.Contains(grtNo!) || g.BankGuaranteeNo.Contains(grtNo!));
    if (!string.IsNullOrWhiteSpace(bank)) q = q.Where(g => g.BankCode == bank);
    if (openFrom is not null) q = q.Where(g => g.DateOpen != null && g.DateOpen >= openFrom.Value.Date);
    if (openTo is not null) q = q.Where(g => g.DateOpen != null && g.DateOpen < openTo.Value.Date.AddDays(1));
    var recs = await q.ToListAsync();
    // Dư nợ BL = tổng giá trị BL đã duyệt, CHƯA tất toán.
    decimal Debit(BankGuarantee g) => g.Status == "Approved" && g.FlagSettled != "1" ? g.TotalAmount : 0;
    var byBank = recs.GroupBy(g => string.IsNullOrEmpty(g.BankCode) ? "(chưa rõ)" : g.BankCode)
        .Select(g => new { bankCode = g.Key, count = g.Count(), totalAmount = g.Sum(x => x.TotalAmount), debit = g.Sum(Debit), settled = g.Count(x => x.FlagSettled == "1") })
        .OrderByDescending(x => x.debit).ToList();
    var byStatus = recs.GroupBy(g => g.Status)
        .Select(g => new { status = g.Key, count = g.Count(), totalAmount = g.Sum(x => x.TotalAmount) })
        .OrderByDescending(x => x.count).ToList();
    var detail = recs.OrderByDescending(g => g.DateOpen).Take(500).Select(g => new
    {
        g.GuaranteeNo, g.DealerCode, g.BankCode, g.BankGuaranteeNo, g.TotalAmount, g.Status, g.FlagSettled,
        dateOpen = g.DateOpen != null ? g.DateOpen.Value.ToString("yyyy-MM-dd") : "",
        debit = Debit(g),
        g.TermActual, g.TermWarning, g.RemarkReject, g.ApprovedBy, g.BankCodeMonitor, g.BankBUCode
    }).ToList();
    return Results.Ok(new { total = recs.Count, totalDebit = recs.Sum(Debit), totalAmount = recs.Sum(g => g.TotalAmount), byBank, byStatus, detail });
}).RequireAuthorization();

// Cập nhật ngày mốc SO theo lô (port 1:1 FrmMng_SO_Approved_Date, 2010.HTC): ngày duyệt / hết hạn nghĩa vụ cọc / hết hạn BL / đến hạn giao xe.
app.MapGet("/api/salesorders/sodates", async (AppDbContext db, ITenantContext t, string? dealer, string? so) =>
{
    var q = db.SalesOrders.Where(o => o.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(o => o.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(so)) q = q.Where(o => o.SoCode.Contains(so!));
    var items = await q.OrderByDescending(o => o.Id).Take(500).Select(o => new {
        o.SoCode, o.DealerCode, o.Status, o.ApprovedDate, o.DepositDutyEndDate, o.GrtEndDate, o.CarDueDate, o.PenalizeActual
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, totalPenalize = items.Sum(x => x.PenalizeActual), items });
}).RequireAuthorization();

app.MapPost("/api/salesorders/edit-dates", async (SoEditDatesDto dto, AppDbContext db, ITenantContext t) =>
{
    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.SOCode)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Không có SO thay đổi." });
    foreach (var l in lines)
        if (l.DepositDutyEndDate.HasValue && l.CarDueDate.HasValue && l.CarDueDate < l.DepositDutyEndDate)
            return Results.BadRequest(new { error = $"SO {l.SOCode}: ngày đến hạn giao xe phải >= ngày hết hạn nghĩa vụ cọc." });
    var codes = lines.Select(l => l.SOCode!.Trim()).ToHashSet();
    var orders = await db.SalesOrders.Where(o => o.OrgId == t.OrgId && codes.Contains(o.SoCode)).ToListAsync();
    var byCode = orders.ToDictionary(o => o.SoCode, o => o);
    int updated = 0; var notFound = new List<string>();
    foreach (var l in lines)
    {
        var code = l.SOCode!.Trim();
        if (!byCode.TryGetValue(code, out var o)) { notFound.Add(code); continue; }
        if (l.ApprovedDate.HasValue) o.ApprovedDate = l.ApprovedDate;
        if (l.DepositDutyEndDate.HasValue) o.DepositDutyEndDate = l.DepositDutyEndDate;
        if (l.GrtEndDate.HasValue) o.GrtEndDate = l.GrtEndDate;
        if (l.CarDueDate.HasValue) o.CarDueDate = l.CarDueDate;
        updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { updated, notFound = notFound.Distinct().Take(20) });
}).RequireAuthorization();

// Cập nhật tiền phạt trả chậm thực tế theo SO (port 1:1 FrmUpdatePenaltyPmtDelayReal, 2010.HTC).
app.MapPost("/api/salesorders/edit-penalty", async (SoEditPenaltyDto dto, AppDbContext db, ITenantContext t) =>
{
    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.SOCode)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Không có SO thay đổi." });
    if (lines.Any(l => l.PenalizeActual < 0)) return Results.BadRequest(new { error = "Tiền phạt không được âm." });
    var codes = lines.Select(l => l.SOCode!.Trim()).ToHashSet();
    var orders = await db.SalesOrders.Where(o => o.OrgId == t.OrgId && codes.Contains(o.SoCode)).ToListAsync();
    var byCode = orders.ToDictionary(o => o.SoCode, o => o);
    int updated = 0; var notFound = new List<string>();
    foreach (var l in lines)
    {
        var code = l.SOCode!.Trim();
        if (!byCode.TryGetValue(code, out var o)) { notFound.Add(code); continue; }
        o.PenalizeActual = l.PenalizeActual; updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { updated, totalPenalize = orders.Sum(o => o.PenalizeActual), notFound = notFound.Distinct().Take(20) });
}).RequireAuthorization();

// ===== Báo cáo bán hàng đại lý (port 1:1 FrmBanHangDL) — tái dùng SalesOrder + SalesOrderLine =====
app.MapGet("/api/report/salesbydealer", async (AppDbContext db, ITenantContext t, string? dealer, string? status, string? orderType, DateTime? from, DateTime? to) =>
{
    var q = db.SalesOrders.Where(o => o.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(o => o.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(o => o.Status == status);
    if (!string.IsNullOrWhiteSpace(orderType)) q = q.Where(o => o.OrderType == orderType);
    if (from is not null) q = q.Where(o => o.CreatedAt >= from.Value.Date);
    if (to is not null) q = q.Where(o => o.CreatedAt < to.Value.Date.AddDays(1));
    var orders = await q.ToListAsync();
    var ids = orders.Select(o => o.Id).ToHashSet();
    var lines = await db.SalesOrderLines.Where(l => l.OrgId == t.OrgId && ids.Contains(l.SalesOrderId)).ToListAsync();
    var lineByOrder = lines.GroupBy(l => l.SalesOrderId).ToDictionary(g => g.Key, g => g.ToList());
    int ReqQty(long oid) => lineByOrder.TryGetValue(oid, out var ls) ? ls.Sum(x => x.RequestedQuantity) : 0;
    int AppQty(long oid) => lineByOrder.TryGetValue(oid, out var ls) ? ls.Sum(x => x.ApprovedQuantity ?? 0) : 0;
    decimal Amount(long oid) => lineByOrder.TryGetValue(oid, out var ls) ? ls.Sum(x => x.UnitPrice * x.RequestedQuantity) : 0;
    var byDealer = orders.GroupBy(o => string.IsNullOrEmpty(o.DealerCode) ? "(chưa rõ)" : o.DealerCode)
        .Select(g => new { dealerCode = g.Key, orders = g.Count(), reqQty = g.Sum(o => ReqQty(o.Id)), appQty = g.Sum(o => AppQty(o.Id)), amount = g.Sum(o => Amount(o.Id)) })
        .OrderByDescending(x => x.amount).ToList();
    var byStatus = orders.GroupBy(o => o.Status).Select(g => new { status = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    var detail = orders.OrderByDescending(o => o.Id).Take(500).Select(o => new
    {
        o.SoCode, o.DealerCode, o.OrderType, o.PayType, o.Status, createdAt = o.CreatedAt.ToString("yyyy-MM-dd"),
        reqQty = ReqQty(o.Id), appQty = AppQty(o.Id), amount = Amount(o.Id)
    }).ToList();
    return Results.Ok(new { totalOrders = orders.Count, totalReqQty = orders.Sum(o => ReqQty(o.Id)), totalAmount = orders.Sum(o => Amount(o.Id)), byDealer, byStatus, detail });
}).RequireAuthorization();

// ===== Báo cáo tổng hợp (port 1:1 FrmBaoCaoTongHop) — dashboard gộp các entity chính, tái dùng =====
app.MapGet("/api/report/summary", async (AppDbContext db, ITenantContext t) =>
{
    var org = t.OrgId;
    // Đơn hàng bán
    var so = await db.SalesOrders.Where(o => o.OrgId == org).Select(o => o.Status).ToListAsync();
    var soLineAmt = await db.SalesOrderLines.Where(l => l.OrgId == org).SumAsync(l => (decimal?)(l.UnitPrice * l.RequestedQuantity)) ?? 0;
    // Bán buôn ĐL->ĐL
    var ws = await db.WholesaleDeals.Where(w => w.OrgId == org).Select(w => new { w.Status, w.TotalAmount }).ToListAsync();
    // Bảo lãnh ngân hàng
    var grt = await db.BankGuarantees.Where(g => g.OrgId == org).Select(g => new { g.Status, g.FlagSettled, g.TotalAmount }).ToListAsync();
    // Phiếu thanh toán
    var pm = await db.PmtPayments.Where(p => p.OrgId == org).Select(p => new { p.PaymentStatus, p.TotalAmount }).ToListAsync();
    // Hợp đồng đại lý bán lẻ
    var dc = await db.DlrContracts.Where(c => c.OrgId == org).CountAsync();
    // Back-order
    var bo = await db.BackOrders.Where(b => b.OrgId == org).Select(b => new { b.QtyOrder, b.QtyDelivered }).ToListAsync();

    var summary = new
    {
        salesOrders = new { count = so.Count, byStatus = so.GroupBy(s => s).Select(g => new { status = g.Key, count = g.Count() }).ToList(), totalAmount = soLineAmt },
        wholesaleDeals = new { count = ws.Count, confirmed = ws.Count(w => w.Status == "Confirmed"), totalAmount = ws.Sum(w => w.TotalAmount) },
        guarantees = new { count = grt.Count, approved = grt.Count(g => g.Status == "Approved"), debit = grt.Where(g => g.Status == "Approved" && g.FlagSettled != "1").Sum(g => g.TotalAmount), settled = grt.Count(g => g.FlagSettled == "1") },
        payments = new { count = pm.Count, approved = pm.Count(p => p.PaymentStatus == "Approved"), totalAmount = pm.Sum(p => p.TotalAmount) },
        dealerContracts = new { count = dc },
        backOrder = new { totalOrder = bo.Sum(b => b.QtyOrder), totalDelivered = bo.Sum(b => b.QtyDelivered), backOrder = bo.Sum(b => b.QtyOrder - b.QtyDelivered) }
    };
    return Results.Ok(summary);
}).RequireAuthorization();

// ===== Báo cáo tình trạng hiệu lực bảo lãnh (port 1:1 FrmBCTinhTrangHoSoHieuLucBaoLanh) — tái dùng BankGuarantee =====
app.MapGet("/api/report/grtvalidity", async (AppDbContext db, ITenantContext t, string? bank, int? soonDays) =>
{
    var soon = soonDays is > 0 ? soonDays.Value : 30;   // ngưỡng "sắp hết hạn" (mặc định 30 ngày)
    var q = db.BankGuarantees.Where(g => g.OrgId == t.OrgId && g.Status == "Approved" && g.FlagSettled != "1");
    if (!string.IsNullOrWhiteSpace(bank)) q = q.Where(g => g.BankCode == bank);
    var recs = await q.ToListAsync();
    var today = DateTime.Today;
    string Classify(BankGuarantee g)
    {
        if (g.DateExpired is null) return "NoDate";
        var days = (g.DateExpired.Value.Date - today).Days;
        if (days < 0) return "Expired";
        if (days <= soon) return "ExpiringSoon";
        return "Valid";
    }
    var detail = recs.OrderBy(g => g.DateExpired ?? DateTime.MaxValue).Take(500).Select(g => new
    {
        g.GuaranteeNo, g.DealerCode, g.BankCode, g.BankGuaranteeNo, g.TotalAmount,
        dateExpired = g.DateExpired != null ? g.DateExpired.Value.ToString("yyyy-MM-dd") : "",
        daysLeft = g.DateExpired != null ? (int)(g.DateExpired.Value.Date - today).TotalDays : (int?)null,
        validity = Classify(g)
    }).ToList();
    var byValidity = recs.GroupBy(Classify)
        .Select(g => new { validity = g.Key, count = g.Count(), totalAmount = g.Sum(x => x.TotalAmount) }).ToList();
    return Results.Ok(new
    {
        soonDays = soon,
        total = recs.Count,
        valid = recs.Count(g => Classify(g) == "Valid"),
        expiringSoon = recs.Count(g => Classify(g) == "ExpiringSoon"),
        expired = recs.Count(g => Classify(g) == "Expired"),
        byValidity, detail
    });
}).RequireAuthorization();

// ===== Báo cáo phiếu thanh toán ngân hàng (port 1:1 báo cáo Pmt_PM) — tái dùng BankPayment =====
app.MapGet("/api/report/payment", async (AppDbContext db, ITenantContext t, string? bank, string? status, string? dealer, DateTime? from, DateTime? to) =>
{
    var q = db.PmtPayments.Where(p => p.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(bank)) q = q.Where(p => p.BankCodeReceive == bank || p.BankCodeSend == bank);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(p => p.PaymentStatus == status);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(p => p.DealerCode == dealer);
    if (from is not null) q = q.Where(p => p.CreatedDate >= from.Value.Date);
    if (to is not null) q = q.Where(p => p.CreatedDate < to.Value.Date.AddDays(1));
    var recs = await q.ToListAsync();
    var byBank = recs.GroupBy(p => string.IsNullOrEmpty(p.BankCodeReceive) ? "(chưa rõ)" : p.BankCodeReceive)
        .Select(g => new { bankCode = g.Key, count = g.Count(), totalAmount = g.Sum(x => x.TotalAmount), approved = g.Count(x => x.PaymentStatus == "Approved") })
        .OrderByDescending(x => x.totalAmount).ToList();
    var byStatus = recs.GroupBy(p => p.PaymentStatus).Select(g => new { status = g.Key, count = g.Count(), totalAmount = g.Sum(x => x.TotalAmount) }).OrderByDescending(x => x.count).ToList();
    var byFunds = recs.GroupBy(p => string.IsNullOrEmpty(p.Funds) ? "(chưa rõ)" : p.Funds).Select(g => new { funds = g.Key, count = g.Count(), totalAmount = g.Sum(x => x.TotalAmount) }).OrderByDescending(x => x.totalAmount).ToList();
    var detail = recs.OrderByDescending(p => p.Id).Take(500).Select(p => new
    {
        p.PaymentNo, p.BankPaymentNo, p.DealerCode, p.BankCodeSend, p.BankCodeReceive, p.Funds, p.TotalAmount, p.PaymentStatus, p.AccountingRecordNo,
        createdAt = p.CreatedDate.ToString("yyyy-MM-dd")
    }).ToList();
    return Results.Ok(new { total = recs.Count, totalAmount = recs.Sum(p => p.TotalAmount), approvedAmount = recs.Where(p => p.PaymentStatus == "Approved").Sum(p => p.TotalAmount), byBank, byStatus, byFunds, detail });
}).RequireAuthorization();

// ===== Báo cáo hóa đơn VAT HTC (port 1:1 báo cáo VAT_HTCInvoice) — tái dùng VatInvoice + VatInvoiceCar =====
app.MapGet("/api/report/vatinvoice", async (AppDbContext db, ITenantContext t, string? dealer, string? status, string? adjType, DateTime? from, DateTime? to) =>
{
    var q = db.VatInvoices.Where(v => v.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(v => v.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(v => v.VatHTCStatus == status);
    if (adjType == "adj") q = q.Where(v => v.InvoiceAdjType != "");
    else if (adjType == "root") q = q.Where(v => v.InvoiceAdjType == "");
    if (from is not null) q = q.Where(v => v.CreatedAt >= from.Value.Date);
    if (to is not null) q = q.Where(v => v.CreatedAt < to.Value.Date.AddDays(1));
    var invs = await q.ToListAsync();
    var ids = invs.Select(v => v.Id).ToHashSet();
    var carAgg = await db.VatInvoiceCars.Where(c => c.OrgId == t.OrgId && ids.Contains(c.VatInvoiceId))
        .GroupBy(c => c.VatInvoiceId).Select(g => new { g.Key, cars = g.Count(), amount = g.Sum(x => x.HTCUnitPrice) }).ToListAsync();
    var carMap = carAgg.ToDictionary(x => x.Key, x => (x.cars, x.amount));
    int Cars(long id) => carMap.TryGetValue(id, out var v) ? v.cars : 0;
    decimal Amt(long id) => carMap.TryGetValue(id, out var v) ? v.amount : 0;
    var byDealer = invs.GroupBy(v => string.IsNullOrEmpty(v.DealerCode) ? "(chưa rõ)" : v.DealerCode)
        .Select(g => new { dealerCode = g.Key, count = g.Count(), cars = g.Sum(v => Cars(v.Id)), amount = g.Sum(v => Amt(v.Id)) }).OrderByDescending(x => x.amount).ToList();
    var byStatus = invs.GroupBy(v => v.VatHTCStatus).Select(g => new { status = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    var detail = invs.OrderByDescending(v => v.Id).Take(500).Select(v => new
    {
        v.HTCInvoiceCode, v.HTCInvoiceNo, v.InvoiceIDCode, v.DealerCode, v.VAT, v.InvoiceAdjType, v.VatHTCStatus, v.OS_HDDT_InvoiceCode,
        cars = Cars(v.Id), amount = Amt(v.Id), createdAt = v.CreatedAt.ToString("yyyy-MM-dd")
    }).ToList();
    return Results.Ok(new { total = invs.Count, totalCars = invs.Sum(v => Cars(v.Id)), totalAmount = invs.Sum(v => Amt(v.Id)),
        pending = invs.Count(v => v.VatHTCStatus == "P"), issued = invs.Count(v => v.VatHTCStatus == "F"),
        cancelled = invs.Count(v => v.VatHTCStatus == "C"), rejected = invs.Count(v => v.VatHTCStatus == "R"), byDealer, byStatus, detail });
}).RequireAuthorization();

// ===== Báo cáo bán buôn ĐL→ĐL (port 1:1 báo cáo Deal To Dealer) — tái dùng WholesaleDeal + Car =====
app.MapGet("/api/report/wholesale", async (AppDbContext db, ITenantContext t, string? buyer, string? status, string? salesman, DateTime? from, DateTime? to) =>
{
    var q = db.WholesaleDeals.Where(w => w.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(buyer)) q = q.Where(w => w.BuyerDealerCode == buyer);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(w => w.Status == status);
    if (!string.IsNullOrWhiteSpace(salesman)) q = q.Where(w => w.SalesManCode == salesman);
    if (from is not null) q = q.Where(w => w.CreatedAt >= from.Value.Date);
    if (to is not null) q = q.Where(w => w.CreatedAt < to.Value.Date.AddDays(1));
    var deals = await q.ToListAsync();
    var ids = deals.Select(d => d.Id).ToHashSet();
    var carCount = await db.WholesaleDealCars.Where(c => c.OrgId == t.OrgId && ids.Contains(c.WholesaleDealId))
        .GroupBy(c => c.WholesaleDealId).Select(g => new { g.Key, cars = g.Count() }).ToListAsync();
    var carMap = carCount.ToDictionary(x => x.Key, x => x.cars);
    int Cars(long id) => carMap.TryGetValue(id, out var v) ? v : 0;
    var byBuyer = deals.GroupBy(d => string.IsNullOrEmpty(d.BuyerDealerCode) ? "(chưa rõ)" : d.BuyerDealerCode)
        .Select(g => new { buyerDealerCode = g.Key, count = g.Count(), cars = g.Sum(d => Cars(d.Id)), amount = g.Sum(d => d.TotalAmount), confirmed = g.Count(d => d.Status == "Confirmed") })
        .OrderByDescending(x => x.amount).ToList();
    var byStatus = deals.GroupBy(d => d.Status).Select(g => new { status = g.Key, count = g.Count(), amount = g.Sum(x => x.TotalAmount) }).OrderByDescending(x => x.count).ToList();
    var bySalesman = deals.Where(d => !string.IsNullOrEmpty(d.SalesManCode)).GroupBy(d => d.SalesManCode)
        .Select(g => new { salesManCode = g.Key, count = g.Count(), amount = g.Sum(x => x.TotalAmount) }).OrderByDescending(x => x.amount).ToList();
    var detail = deals.OrderByDescending(d => d.Id).Take(500).Select(d => new
    {
        d.DealNo, d.DealNoUser, d.BuyerDealerCode, d.SalesManCode, d.Status, d.TotalAmount, cars = Cars(d.Id), createdAt = d.CreatedAt.ToString("yyyy-MM-dd")
    }).ToList();
    return Results.Ok(new { total = deals.Count, totalAmount = deals.Sum(d => d.TotalAmount), confirmedAmount = deals.Where(d => d.Status == "Confirmed").Sum(d => d.TotalAmount), totalCars = deals.Sum(d => Cars(d.Id)), byBuyer, byStatus, bySalesman, detail });
}).RequireAuthorization();

// ===== Báo cáo yêu cầu bảo hiểm (port 1:1 báo cáo Ins_InsuranceReq) — tái dùng InsuranceReq + Dtl =====
app.MapGet("/api/report/insurance", async (AppDbContext db, ITenantContext t, string? company, string? status, string? insType, DateTime? from, DateTime? to, string? insCompanyPattern) =>
{
    var q = db.InsuranceReqs.Where(r => r.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(company)) q = q.Where(r => r.InsCompanyCode == company);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(r => r.Status == status);
    // 🔴 RBAC của nguồn (TERP.BizInsurance/InsReq.cs): người dùng công ty bảo hiểm CHỈ thấy dữ liệu
    // của công ty mình — nguồn lọc bằng PATTERN `InsCompanyCode like @strAbilityOfUser`.
    // Port cũ KHÔNG có tầng lọc này ở BẤT KỲ đường đọc nào.
    if (!string.IsNullOrWhiteSpace(insCompanyPattern)) { var _p = insCompanyPattern!.Trim().Replace("%", ""); q = q.Where(r => r.InsCompanyCode.Contains(_p)); }
    if (!string.IsNullOrWhiteSpace(insType)) q = q.Where(r => r.InsTypeCode == insType);
    if (from is not null) q = q.Where(r => r.CreatedAt >= from.Value.Date);
    if (to is not null) q = q.Where(r => r.CreatedAt < to.Value.Date.AddDays(1));
    var reqs = await q.ToListAsync();
    var ids = reqs.Select(r => r.Id).ToHashSet();
    var dtlAgg = await db.InsuranceReqDtls.Where(c => c.OrgId == t.OrgId && ids.Contains(c.InsuranceReqId))
        .GroupBy(c => c.InsuranceReqId).Select(g => new { g.Key, cars = g.Count(), insAmount = g.Sum(x => x.InsAmount), fee = g.Sum(x => x.Price) }).ToListAsync();
    var m = dtlAgg.ToDictionary(x => x.Key, x => (x.cars, x.insAmount, x.fee));
    int Cars(long id) => m.TryGetValue(id, out var v) ? v.cars : 0;
    decimal InsAmt(long id) => m.TryGetValue(id, out var v) ? v.insAmount : 0;
    decimal Fee(long id) => m.TryGetValue(id, out var v) ? v.fee : 0;
    var byCompany = reqs.GroupBy(r => string.IsNullOrEmpty(r.InsCompanyCode) ? "(chưa rõ)" : r.InsCompanyCode)
        .Select(g => new { company = g.Key, count = g.Count(), cars = g.Sum(r => Cars(r.Id)), insAmount = g.Sum(r => InsAmt(r.Id)), fee = g.Sum(r => Fee(r.Id)) }).OrderByDescending(x => x.insAmount).ToList();
    var byStatus = reqs.GroupBy(r => r.Status).Select(g => new { status = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    var byType = reqs.GroupBy(r => string.IsNullOrEmpty(r.InsTypeCode) ? "(chưa rõ)" : r.InsTypeCode).Select(g => new { insType = g.Key, count = g.Count(), cars = g.Sum(r => Cars(r.Id)) }).OrderByDescending(x => x.count).ToList();
    var detail = reqs.OrderByDescending(r => r.Id).Take(500).Select(r => new
    {
        r.InsReqNo, r.InsCompanyCode, r.InsTypeCode, r.Status, cars = Cars(r.Id), insAmount = InsAmt(r.Id), fee = Fee(r.Id), createdAt = r.CreatedAt.ToString("yyyy-MM-dd")
    }).ToList();
    return Results.Ok(new { total = reqs.Count, totalCars = reqs.Sum(r => Cars(r.Id)), totalInsAmount = reqs.Sum(r => InsAmt(r.Id)), totalFee = reqs.Sum(r => Fee(r.Id)), byCompany, byStatus, byType, detail });
}).RequireAuthorization();

// ===== Báo cáo công văn bảo lãnh/claim đại lý (port 1:1 báo cáo GrtClaim) — tái dùng GrtClaim + GrtClaimDetail =====
app.MapGet("/api/report/grtclaim", async (AppDbContext db, ITenantContext t, string? dealer, string? status, string? flag, DateTime? from, DateTime? to) =>
{
    var q = db.GrtClaims.Where(g => g.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(g => g.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(g => g.Status == status);
    if (!string.IsNullOrWhiteSpace(flag)) q = q.Where(g => g.FlagisHTC == flag);
    if (from is not null) q = q.Where(g => g.CreatedAt >= from.Value.Date);
    if (to is not null) q = q.Where(g => g.CreatedAt < to.Value.Date.AddDays(1));
    var claims = await q.ToListAsync();
    var ids = claims.Select(c => c.Id).ToHashSet();
    var dtlAgg = await db.GrtClaimDetails.Where(c => c.OrgId == t.OrgId && ids.Contains(c.GrtClaimId))
        .GroupBy(c => c.GrtClaimId).Select(g => new { g.Key, cars = g.Count(), amount = g.Sum(x => x.UnitPrice) }).ToListAsync();
    var m = dtlAgg.ToDictionary(x => x.Key, x => (x.cars, x.amount));
    int Cars(long id) => m.TryGetValue(id, out var v) ? v.cars : 0;
    decimal Amt(long id) => m.TryGetValue(id, out var v) ? v.amount : 0;
    var byDealer = claims.GroupBy(g => string.IsNullOrEmpty(g.DealerCode) ? "(chưa rõ)" : g.DealerCode)
        .Select(g => new { dealerCode = g.Key, count = g.Count(), cars = g.Sum(c => Cars(c.Id)), amount = g.Sum(c => Amt(c.Id)), issued = g.Count(c => c.Status == "Issued") }).OrderByDescending(x => x.amount).ToList();
    var byStatus = claims.GroupBy(g => g.Status).Select(g => new { status = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    var byFlag = claims.GroupBy(g => string.IsNullOrEmpty(g.FlagisHTC) ? "(chưa rõ)" : g.FlagisHTC).Select(g => new { flag = g.Key, count = g.Count(), cars = g.Sum(c => Cars(c.Id)) }).OrderByDescending(x => x.count).ToList();
    var detail = claims.OrderByDescending(g => g.Id).Take(500).Select(g => new
    {
        g.GrtClaimNo, g.DealerCode, g.FlagisHTC, g.Status, cars = Cars(g.Id), amount = Amt(g.Id), createdAt = g.CreatedAt.ToString("yyyy-MM-dd")
    }).ToList();
    return Results.Ok(new { total = claims.Count, totalCars = claims.Sum(g => Cars(g.Id)), totalAmount = claims.Sum(g => Amt(g.Id)),
        issued = claims.Count(g => g.Status == "Issued"), byDealer, byStatus, byFlag, detail });
}).RequireAuthorization();

// ===== Báo cáo hợp đồng bán lẻ (port 1:1 báo cáo Dlr_Contract) — tái dùng DlrContract + DlrContractDetail =====
app.MapGet("/api/report/dlrcontract", async (AppDbContext db, ITenantContext t, string? dealer, string? salesType, string? status, string? salesman, DateTime? from, DateTime? to) =>
{
    var q = db.DlrContracts.Where(c => c.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(c => c.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(salesType)) q = q.Where(c => c.SalesType == salesType);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(c => c.Status == status);
    if (!string.IsNullOrWhiteSpace(salesman)) q = q.Where(c => c.SalesManCode == salesman);
    if (from is not null) q = q.Where(c => c.SignDate >= from.Value.Date);
    if (to is not null) q = q.Where(c => c.SignDate < to.Value.Date.AddDays(1));
    var cons = await q.ToListAsync();
    var ids = cons.Select(c => c.Id).ToHashSet();
    var dtlAgg = await db.DlrContractDetails.Where(l => l.OrgId == t.OrgId && ids.Contains(l.ContractId))
        .GroupBy(l => l.ContractId).Select(g => new { g.Key, qty = g.Sum(x => x.Qty), total = g.Sum(x => x.TotalAmountAfterVAT) }).ToListAsync();
    var m = dtlAgg.ToDictionary(x => x.Key, x => (x.qty, x.total));
    int Qty(long id) => m.TryGetValue(id, out var v) ? v.qty : 0;
    decimal Total(long id) => m.TryGetValue(id, out var v) ? v.total : 0;
    var byDealer = cons.GroupBy(c => string.IsNullOrEmpty(c.DealerCode) ? "(chưa rõ)" : c.DealerCode)
        .Select(g => new { dealerCode = g.Key, count = g.Count(), qty = g.Sum(c => Qty(c.Id)), amount = g.Sum(c => Total(c.Id)), active = g.Count(c => c.Status == "Active") }).OrderByDescending(x => x.amount).ToList();
    var bySalesType = cons.GroupBy(c => string.IsNullOrEmpty(c.SalesType) ? "(chưa rõ)" : c.SalesType).Select(g => new { salesType = g.Key, count = g.Count(), qty = g.Sum(c => Qty(c.Id)), amount = g.Sum(c => Total(c.Id)) }).OrderByDescending(x => x.amount).ToList();
    var bySalesman = cons.Where(c => !string.IsNullOrEmpty(c.SalesManCode)).GroupBy(c => c.SalesManCode).Select(g => new { salesManCode = g.Key, count = g.Count(), amount = g.Sum(c => Total(c.Id)) }).OrderByDescending(x => x.amount).ToList();
    var detail = cons.OrderByDescending(c => c.Id).Take(500).Select(c => new
    {
        c.DlrContractNo, c.DlrContractNoUser, c.DealerCode, c.SalesManCode, c.SalesType, c.CustomerName, c.Status,
        qty = Qty(c.Id), amount = Total(c.Id), signDate = c.SignDate.ToString("yyyy-MM-dd")
    }).ToList();
    return Results.Ok(new { total = cons.Count, totalQty = cons.Sum(c => Qty(c.Id)), totalAmount = cons.Sum(c => Total(c.Id)),
        active = cons.Count(c => c.Status == "Active"), byDealer, bySalesType, bySalesman, detail });
}).RequireAuthorization();

// ===== Báo cáo CRM: lượt khách thăm & lái thử (port 1:1 báo cáo CtmVisit/DriveTest) — tái dùng CtmVisit + DriveTest =====
app.MapGet("/api/report/crm", async (AppDbContext db, ITenantContext t, string? dealer, string? model, DateTime? from, DateTime? to) =>
{
    var vq = db.CtmVisits.Where(v => v.OrgId == t.OrgId);
    var dq = db.DriveTests.Where(d => d.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) { vq = vq.Where(v => v.DealerCode == dealer); dq = dq.Where(d => d.DealerCode == dealer); }
    if (!string.IsNullOrWhiteSpace(model)) { vq = vq.Where(v => v.ModelCode == model); dq = dq.Where(d => d.TestModelCode == model); }
    if (from is not null) dq = dq.Where(d => d.DriveDate >= from.Value.Date);
    if (to is not null) dq = dq.Where(d => d.DriveDate < to.Value.Date.AddDays(1));
    var visits = await vq.ToListAsync();
    var drives = await dq.ToListAsync();
    string GenderLabel(string g) => g == "1" ? "Nữ" : g == "0" ? "Nam" : "(chưa rõ)";
    var visitByDealer = visits.GroupBy(v => string.IsNullOrEmpty(v.DealerCode) ? "(chưa rõ)" : v.DealerCode).Select(g => new { dealerCode = g.Key, visits = g.Count() }).OrderByDescending(x => x.visits).ToList();
    var visitByGender = visits.GroupBy(v => GenderLabel(v.Gender)).Select(g => new { gender = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    var visitByAge = visits.GroupBy(v => string.IsNullOrEmpty(v.RangeAge) ? "(chưa rõ)" : v.RangeAge).Select(g => new { rangeAge = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    var visitByModel = visits.GroupBy(v => string.IsNullOrEmpty(v.ModelCode) ? "(chưa rõ)" : v.ModelCode).Select(g => new { modelCode = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    var driveByModel = drives.GroupBy(d => string.IsNullOrEmpty(d.TestModelCode) ? "(chưa rõ)" : d.TestModelCode).Select(g => new { modelCode = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    var driveByType = drives.GroupBy(d => string.IsNullOrEmpty(d.DriverTestType) ? "(chưa rõ)" : d.DriverTestType).Select(g => new { driveType = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    // Tỉ lệ chuyển đổi thăm -> lái thử
    var convRate = visits.Count > 0 ? Math.Round(drives.Count * 100.0 / visits.Count, 1) : 0;
    return Results.Ok(new { totalVisits = visits.Count, totalDrives = drives.Count, conversionRatePct = convRate,
        visitByDealer, visitByGender, visitByAge, visitByModel, driveByModel, driveByType });
}).RequireAuthorization();

// ===== Báo cáo xe đang thế chấp (port 1:1 báo cáo BankCarMortage) — tái dùng BankCarMortage =====
app.MapGet("/api/report/mortgage", async (AppDbContext db, ITenantContext t, string? mortageBank, string? dealer, string? guaranteeType, string? active) =>
{
    var q = db.BankCarMortages.Where(m => m.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(mortageBank)) q = q.Where(m => m.MortageBankCode == mortageBank);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(m => m.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(guaranteeType)) q = q.Where(m => m.GuaranteeType == guaranteeType);
    if (!string.IsNullOrWhiteSpace(active)) q = q.Where(m => m.FlagActive == active);
    var recs = await q.ToListAsync();
    var byBank = recs.GroupBy(m => string.IsNullOrEmpty(m.MortageBankCode) ? "(chưa rõ)" : m.MortageBankCode)
        .Select(g => new { mortageBank = g.Key, count = g.Count(), active = g.Count(x => x.FlagActive == "1"), released = g.Count(x => x.FlagActive != "1") }).OrderByDescending(x => x.count).ToList();
    var byDealer = recs.GroupBy(m => string.IsNullOrEmpty(m.DealerCode) ? "(chưa rõ)" : m.DealerCode).Select(g => new { dealerCode = g.Key, count = g.Count(), active = g.Count(x => x.FlagActive == "1") }).OrderByDescending(x => x.count).ToList();
    string GtLabel(string g) => g == "1" ? "NH phát hành" : "NH giám sát";
    var byGrtType = recs.GroupBy(m => GtLabel(m.GuaranteeType)).Select(g => new { guaranteeType = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    string RangeLabel(string r) => r switch { "DlvThisWeek" => "Trong tuần", "DlvNextWeek" => "Tuần tới", _ => "Giao ngay" };
    var byRange = recs.Where(m => m.FlagActive == "1").GroupBy(m => RangeLabel(m.DeliveryRangeType)).Select(g => new { range = g.Key, count = g.Count() }).ToList();
    var detail = recs.OrderByDescending(m => m.Id).Take(500).Select(m => new
    {
        m.VIN, m.DealerCode, m.MortageBankCode, m.BankCode, m.ModelCode, guaranteeType = GtLabel(m.GuaranteeType), deliveryRange = RangeLabel(m.DeliveryRangeType), m.FlagActive
    }).ToList();
    return Results.Ok(new { total = recs.Count, active = recs.Count(m => m.FlagActive == "1"), released = recs.Count(m => m.FlagActive != "1"), byBank, byDealer, byGrtType, byRange, detail });
}).RequireAuthorization();

// ===== Báo cáo đơn hàng nâng cấp (port 1:1 báo cáo Upgrade Order) — tái dùng UpgradeOrder =====
app.MapGet("/api/report/upgradeorder", async (AppDbContext db, ITenantContext t, string? dealer, string? month, string? type, string? status) =>
{
