    x.MapLongitude = dto.MapLongitude; x.MapLatitude = dto.MapLatitude; x.GPSAddress = dto.GPSAddress;
    x.GPSStatus = dto.GPSStatus; x.CallGPSStatus = dto.CallGPSStatus; x.Remark = dto.Remark;
