// ===== #B04 BÁO CÁO GIAO XE SAI ĐỊA ĐIỂM ĐẠI LÝ ĐĂNG KÝ =====
// Port 1:1 `FrmRptGiaoXeSaiDDDaiLyDangKy` (2010.HTC TERP.HTCClient/Views/StoFGPS).
// Trace twin LIVE: btnSearch_Click:151 → `ReportStoFGPSService.Rpt_CarDeliveryNotAddressDealerRegis` (:265)
//   rẽ theo `checkWH`: false → WS (`WSHTC.asmx.cs:45424`) → `_biz.Rpt_CarDeliveryNotAddressDealerRegis_New20181115`
//   (`BizHTC.ZTempGPS.cs:8721`, `_dbMain`); true → WS `..._WH` (:69449) → `..._WH_New20181119`
//   (`Biz.HTC.WH.cs:150195`, `_dbWH`). Bản CHẾT đã loại: `Delete.BizHTC.Report.cs:167094` và `_New20181021`.
// ✅ Đã grep `ws.` / `WSNM` trong trọn thân hàm (luật C0-…tertius): **KHÔNG gọi WS ngoài** — tên temp
//    `#input_Veloca_Sto_DlvMinutes` chỉ là TÊN, dữ liệu vị trí đọc thẳng từ bảng `GPS_DlvMinutesAddress`.
// Nghiệp vụ: xe giao xong (có mốc GPS) mà **không khớp điểm nhận đã đăng ký** ⇒ `PointRegisCode` rỗng/null.
app.MapGet("/api/reports/car-delivery-not-dealer-point", async (
    AppDbContext db, ITenantContext t,
    string? dealerCode, string? vin, DateTime? fromDate, DateTime? toDate, string? dataWH, string? buPattern) =>
{
    var dealerKey = string.IsNullOrWhiteSpace(dealerCode) ? null : dealerCode.Trim().ToUpperInvariant();
    var vinKey = string.IsNullOrWhiteSpace(vin) ? null : vin.Trim().ToUpperInvariant();
    var pattern = string.IsNullOrWhiteSpace(buPattern) ? null : buPattern.Trim().TrimEnd('%').ToUpperInvariant();

    // --- Khối 1: `#tbl_Sto_DlvMinutes_Filter` (BizHTC.ZTempGPS.cs:8746-8770) ---
    // `Sto_DlvMinutes` ở MiniHTC = `TranspDlvConfirm` (header) + `TranspDlvConfirmCar` (dòng xe) —
    // hợp nhất thực thể song trùng đã làm ở #60; header ĐÃ SẴN `GPSDvNo`/`DlvEndGPSDateTime`/`TranspReqType`
    // (#169) ⇒ lượt này **không phát sinh cột DB mới**.
    var q = db.TranspDlvConfirms.Where(h => h.OrgId == t.OrgId
        && h.DlvMinutesNo != ""                    // `sdn.DlvMnNo is not null and <> ''`
        && h.DlvEndGPSDateTime != null             // `sdn.DlvEndGPSDateTime is not null and <> ' '`
        // `inner join Sto_StoBalanceGPS on ssbgps.StorageCode = 'STOGPS' and sdn.GPSDvNo = ssbgps.GPSDvNo`
        && db.GpsInstalls.Any(g => g.OrgId == t.OrgId && g.StorageCode == "STOGPS" && g.GpsNo == h.GPSDvNo));
    if (dealerKey is not null) q = q.Where(h => h.DealerCode == dealerKey);
    if (fromDate is not null) q = q.Where(h => h.DlvEndGPSDateTime >= fromDate);
    if (toDate is not null) q = q.Where(h => h.DlvEndGPSDateTime <= toDate);
    // Nguồn lọc `sdn.VIN` ở HEADER; MiniHTC VIN nằm ở DÒNG XE ⇒ lọc qua dòng xe của chính biên bản đó.
    if (vinKey is not null)
        q = q.Where(h => db.TranspDlvConfirmCars.Any(c => c.OrgId == t.OrgId && c.TranspDlvConfirmId == h.Id && c.VIN == vinKey));

    // --- Khối 2: ghép với `GPS_DlvMinutesAddress` + master (SQL khối 2, :8825-8862) ---
    var heads = await q.Select(h => new { h.Id, h.DlvMinutesNo, h.GPSDvNo, h.DealerCode, h.DlvEndGPSDateTime, h.TranspReqType }).ToListAsync();
    var nos = heads.Select(h => h.DlvMinutesNo).Distinct().ToList();
    var addrs = await db.GpsDlvMinutesAddresses.Where(a => a.OrgId == t.OrgId && nos.Contains(a.DlvMnNo)).ToListAsync();
    var dealers = await db.Dealers.Where(d => d.OrgId == t.OrgId).Select(d => new { d.DealerCode, d.DealerName, d.BUCode }).ToListAsync();
    var addrVins = addrs.Select(a => a.VIN).Distinct().ToList();
    var cars = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId && addrVins.Contains(c.VIN))
        .Select(c => new { c.VIN, c.ModelCode, c.SpecCode, c.ColorCode, c.DealerCode }).ToListAsync();
    var models = await db.CarModelStds.Where(m => m.OrgId == t.OrgId).Select(m => new { m.ModelCode, m.ModelName }).ToListAsync();
    var colors = await db.MstCarColors.Where(c => c.OrgId == t.OrgId).Select(c => new { c.ModelCode, c.ColorCode, c.ColorExtName, c.ColorExtNameVN }).ToListAsync();
    var specs = await db.CarSpecs.Where(s => s.OrgId == t.OrgId).Select(s => new { s.SpecCode, s.SpecDesc }).ToListAsync();

    var items = new List<object>();
    int skipHasPoint = 0, skipRearrange = 0, skipGpsStatus = 0, skipNoCar = 0, skipNoDealer = 0;
    foreach (var h in heads)
    {
        // `sdm.TranspReqType not in ('STORAGEREARRANGE')` — loại biên bản ĐIỀU CHUYỂN KHO (không phải giao đại lý).
        if (string.Equals(h.TranspReqType, "STORAGEREARRANGE", StringComparison.OrdinalIgnoreCase)) { skipRearrange++; continue; }
        if (string.IsNullOrWhiteSpace(h.GPSDvNo)) continue;                  // `sdm.GPSDvNo is not null`
        foreach (var a in addrs.Where(x => x.DlvMnNo == h.DlvMinutesNo))
        {
            // 🔴 ĐIỀU KIỆN CỐT LÕI: điểm đăng ký RỖNG ⇒ xe được giao ở nơi KHÔNG khớp đăng ký.
            if (!string.IsNullOrWhiteSpace(a.PointRegisCode)) { skipHasPoint++; continue; }
            if (a.GPSStatus != "0") { skipGpsStatus++; continue; }           // `gpsdmna.GPSStatus = '0'`
            // Nguồn còn 2 điều kiện `(gpsdmna.MapLongitude != '' or gpsdmna.MapLongitude is null)` (và Latitude).
            // Cột nguồn là chuỗi nên chúng chỉ loại giá trị CHUỖI RỖNG; ở MiniHTC hai cột là `decimal?`
            // ⇒ trạng thái "chuỗi rỗng" KHÔNG tồn tại, điều kiện luôn đúng. Ghi rõ, KHÔNG tự đổi thành `!= 0`.
            // `inner join Sto_StoBalanceGPS on StorageCode='STOGPS' and gpsdmna.GPSDvNo = ssbgps.GPSDvNo`
            if (!db.GpsInstalls.Any(g => g.OrgId == t.OrgId && g.StorageCode == "STOGPS" && g.GpsNo == a.GPSDvNo)) continue;
            var car = cars.FirstOrDefault(c => c.VIN == a.VIN);              // `inner join Car_VIN`
            if (car is null) { skipNoCar++; continue; }
            var dl = dealers.FirstOrDefault(d => d.DealerCode == h.DealerCode);   // `inner join Mst_Dealer`
            if (dl is null) { skipNoDealer++; continue; }
            // `md.BUCode like @strBUPatternOfUser` — MiniHTC chưa có tầng ability ⇒ nhận pattern từ query (nợ chung fleet).
            if (pattern is not null && !(dl.BUCode ?? "").ToUpperInvariant().StartsWith(pattern)) { skipNoDealer++; continue; }
            var colorCode = car.ColorCode;   // `cv.ColorCode` — cột #B04 vừa bổ sung vào CarVinMaster
            var mo = models.FirstOrDefault(x => x.ModelCode == car.ModelCode);
            var co = colors.FirstOrDefault(x => x.ModelCode == car.ModelCode && x.ColorCode == colorCode);
            var sp = specs.FirstOrDefault(x => x.SpecCode == car.SpecCode);
            items.Add(new
            {
                dlvMnNo = h.DlvMinutesNo, gpsDvNo = h.GPSDvNo, vin = a.VIN,
                dealerCode = h.DealerCode, dealerName = dl.DealerName,
                modelCode = car.ModelCode, modelName = mo?.ModelName,
                colorCode, colorExtName = co?.ColorExtName, colorExtNameVN = co?.ColorExtNameVN,
                specCode = car.SpecCode, specDescription = sp?.SpecDesc,
                dlvEndGPSDateTime = h.DlvEndGPSDateTime,
                dealerPointRegisCode = a.PointRegisCode,   // nguồn đặt alias `DealerPointRegisCode`
                mapLongitude = a.MapLongitude, mapLatitude = a.MapLatitude, gpsAddress = a.GPSAddress
            });
        }
    }

    return Results.Ok(new
    {
        count = items.Count, items,
        dataWH = dataWH == "1" || dataWH == "true",
        dataWHNote = "Nguồn có 2 hàm (Main/WH) cùng thuật toán, khác DB đích; MiniHTC 1 DB ⇒ cờ không đổi kết quả.",

        skipHasPoint, skipRearrange, skipGpsStatus, skipNoCar, skipNoDealer,
        note = items.Count == 0 ? "Lưới danh sách dữ liệu trống!" : null   // đúng thông điệp form (:191)
    });
}).RequireAuthorization();

// ===== #B05 BÁO CÁO XE CHUYỂN SAI VÙNG THỊ TRƯỜNG CHÍNH (TỈNH) =====
// Port 1:1 `FrmRptXeChuyenSaiVungTTChinh` (2010.HTC TERP.HTCClient/Views/StoFGPS).
// Trace twin LIVE: btnSearch_Click:176 → `ReportStoFGPSService.Rpt_CarChangeProvinceWhenDelivery` (:313)
//   rẽ theo `checkWH` → WS (`WSHTC.asmx.cs:45495`) → `_biz.…_New20181115` (`BizHTC.ZTempGPS.cs:8982`, `_dbMain`)
//   / WS `…_WH` (:69520) → `…_WH_New20181119` (`Biz.HTC.WH.cs:150464`, `_dbWH`).
//   Bản CHẾT: `Delete.BizHTC.Report.cs:167673` và `…_New20181017`.
// ✅ Đã grep `ws.`/`WSNM` trọn thân hàm ⇒ **không gọi WS ngoài** (luật C0-…tertius).
// Nghiệp vụ: xe đã giao (có mốc GPS) nhưng SAU đó GPS báo xe sang tỉnh KHÁC tỉnh của đại lý.

// Nạp nhật ký "xe đổi tỉnh" do hệ GPS/Veloca trả về (bảng `DMS_CHANGE_CITY` → `Rpt_CarChangeProvince`).
// ⚠️ NỢ: job đồng bộ thật `Rpt_CarChangeProvince_Save_New20181119` (Biz.HTC.WH.cs:135185) gọi WS Veloca —
//    MiniHTC không tới được ⇒ nhận qua payload, KHÔNG bịa dữ liệu.
app.MapPost("/api/carchangeprovinces/import", async (List<CarChangeProvinceDto> rows, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user, string? storageCode) =>
{
    var list = (rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.VIN) && !string.IsNullOrWhiteSpace(r.GPSDvNo)).ToList();
    if (list.Count == 0) return Results.BadRequest(new { error = "Không có dòng đổi tỉnh để nạp." });
    var who = user.Identity?.Name ?? "system"; var now = DateTime.Now;
    var code = string.IsNullOrWhiteSpace(storageCode) ? "STOGPS" : storageCode!.Trim().ToUpperInvariant();
    int added = 0, skipped = 0;
    foreach (var r in list)
    {
        var vin = r.VIN!.Trim().ToUpperInvariant(); var dv = r.GPSDvNo!.Trim().ToUpperInvariant();
        // Nguồn chèn có `inner join Car_VIN` + `inner join Sto_StoBalanceGPS` (:135386-135390):
        // VIN chưa khai hoặc thiết bị chưa khai ⇒ **không nhận dòng**.
        if (!await db.CarVinMasters.AnyAsync(c => c.OrgId == t.OrgId && c.VIN == vin)) { skipped++; continue; }
        if (!await db.GpsInstalls.AnyAsync(g => g.OrgId == t.OrgId && g.GpsNo == dv)) { skipped++; continue; }
        if (await db.RptCarChangeProvinces.AnyAsync(x => x.OrgId == t.OrgId && x.AutoID == r.AutoID && r.AutoID != 0)) { skipped++; continue; }
        db.RptCarChangeProvinces.Add(new RptCarChangeProvince
        {
            OrgId = t.OrgId, AutoID = r.AutoID, StorageCode = code, GPSDvNo = dv, VIN = vin,
            GPSProvinceCode = r.GPSProvinceCode, ChangeDateTime = r.ChangeDateTime,
            MapLongitude = r.MapLongitude, MapLatitude = r.MapLatitude, GPSAddress = r.Address,
            Remark = "",                       // nguồn ghi chuỗi rỗng, không phải NULL (:135381)
            LogLUDateTime = now, LogLUBy = who
        });
        added++;
    }
    await db.SaveChangesAsync();
    // `Rpt_MaxAutoIDChangeProvince` của nguồn = mốc nước `max(AutoID)` cho lần đồng bộ sau.
    var maxAutoId = await db.RptCarChangeProvinces.Where(x => x.OrgId == t.OrgId).Select(x => (long?)x.AutoID).MaxAsync() ?? 0;
    return Results.Ok(new { added, skipped, maxAutoId });
}).RequireAuthorization();

app.MapGet("/api/carchangeprovinces", async (AppDbContext db, ITenantContext t, string? vin, string? device) =>
{
    var q = db.RptCarChangeProvinces.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(vin)) q = q.Where(x => x.VIN == vin!.Trim().ToUpperInvariant());
    if (!string.IsNullOrWhiteSpace(device)) q = q.Where(x => x.GPSDvNo == device!.Trim().ToUpperInvariant());
    var items = await q.OrderByDescending(x => x.ChangeDateTime).Take(1000).Select(x => new
    { x.AutoID, x.StorageCode, x.GPSDvNo, x.VIN, x.GPSProvinceCode, x.ChangeDateTime,
      x.MapLongitude, x.MapLatitude, x.GPSAddress, x.Remark, x.LogLUDateTime, x.LogLUBy }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Danh mục tỉnh phía GPS + ánh xạ sang mã tỉnh DMS (`GPS_Mst_Province`, `Map_ProvinceGPS_DMS`).
app.MapGet("/api/gpsprovinces", async (AppDbContext db, ITenantContext t) =>
{
    var provinces = await db.GpsMstProvinces.Where(x => x.OrgId == t.OrgId)
        .OrderBy(x => x.GPSProvinceCode).Select(x => new { x.GPSProvinceCode, x.GPSProvinceName }).ToListAsync();
    var maps = await db.MapProvinceGpsDmses.Where(x => x.OrgId == t.OrgId)
        .OrderBy(x => x.GPSProvinceCode).Select(x => new { x.GPSProvinceCode, x.ProvinceCode }).ToListAsync();
    return Results.Ok(new { provinces, maps });
}).RequireAuthorization();

app.MapPost("/api/gpsprovinces", async (GpsProvinceImportDto dto, AppDbContext db, ITenantContext t) =>
{
    int p = 0, m = 0;
    foreach (var r in dto.Provinces ?? new())
    {
        if (string.IsNullOrWhiteSpace(r.GPSProvinceCode)) continue;
        var code = r.GPSProvinceCode!.Trim().ToUpperInvariant();
        var x = await db.GpsMstProvinces.FirstOrDefaultAsync(v => v.OrgId == t.OrgId && v.GPSProvinceCode == code);
        if (x is null) { x = new GpsMstProvince { OrgId = t.OrgId, GPSProvinceCode = code }; db.GpsMstProvinces.Add(x); }
        x.GPSProvinceName = r.GPSProvinceName; p++;
    }
    foreach (var r in dto.Maps ?? new())
    {
        if (string.IsNullOrWhiteSpace(r.GPSProvinceCode) || string.IsNullOrWhiteSpace(r.ProvinceCode)) continue;
        var gc = r.GPSProvinceCode!.Trim().ToUpperInvariant(); var pc = r.ProvinceCode!.Trim().ToUpperInvariant();
        var x = await db.MapProvinceGpsDmses.FirstOrDefaultAsync(v => v.OrgId == t.OrgId && v.GPSProvinceCode == gc);
        if (x is null) { x = new MapProvinceGpsDms { OrgId = t.OrgId, GPSProvinceCode = gc }; db.MapProvinceGpsDmses.Add(x); }
        x.ProvinceCode = pc; m++;
    }
    if (p == 0 && m == 0) return Results.BadRequest(new { error = "Không có dòng danh mục/ánh xạ tỉnh GPS để nạp." });
    await db.SaveChangesAsync();
    return Results.Ok(new { provinces = p, maps = m });
}).RequireAuthorization();

app.MapGet("/api/reports/car-change-province-when-delivery", async (
    AppDbContext db, ITenantContext t,
    string? dealerCode, string? vin, DateTime? fromDate, DateTime? toDate, string? dataWH, string? buPattern) =>
{
    var dealerKey = string.IsNullOrWhiteSpace(dealerCode) ? null : dealerCode.Trim().ToUpperInvariant();
    var vinKey = string.IsNullOrWhiteSpace(vin) ? null : vin.Trim().ToUpperInvariant();
    var pattern = string.IsNullOrWhiteSpace(buPattern) ? null : buPattern.Trim().TrimEnd('%').ToUpperInvariant();

    // `from Sto_DlvMinutes sdm` + `inner join Sto_StoBalanceGPS ssbagps on StorageCode='STOGPS' and GPSDvNo`
    // + `and sdm.VIN = ssbagps.VIN` (điều kiện RỜI ở cuối where, :9114) ⇒ thiết bị phải đang gắn ĐÚNG xe đó.
    var q = db.TranspDlvConfirms.Where(h => h.OrgId == t.OrgId
        && h.DlvEndGPSDateTime != null);          // `sdm.DlvEndGPSDateTime is not null and <> ''`
    if (dealerKey is not null) q = q.Where(h => h.DealerCode == dealerKey);   // nguồn lọc `sdm.DealerCode`
    // Nguồn dùng CÙNG cột `sdm.DlvEndGPSDateTime` cho CẢ HAI bộ lọc ngày (:9128-9129 — `strDDDDeliveryDate…`
    // cũng build trên `sdm.DlvEndGPSDateTime`, KHÔNG phải `ddd.DeliveryDate` như tên gợi ý). Port đúng vậy.
    if (fromDate is not null) q = q.Where(h => h.DlvEndGPSDateTime >= fromDate);
    if (toDate is not null) q = q.Where(h => h.DlvEndGPSDateTime <= toDate);

    var heads = await q.Select(h => new { h.Id, h.DlvMinutesNo, h.GPSDvNo, h.DealerCode, h.DlvEndGPSDateTime, h.RefOrdNo }).ToListAsync();
    var headIds = heads.Select(h => h.Id).ToList();
    var headCars = await db.TranspDlvConfirmCars.Where(c => c.OrgId == t.OrgId && headIds.Contains(c.TranspDlvConfirmId))
        .Select(c => new { c.TranspDlvConfirmId, c.VIN }).ToListAsync();
    var allVins = headCars.Select(c => c.VIN).Distinct().ToList();
    var cars = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId && allVins.Contains(c.VIN))
        .Select(c => new { c.VIN, c.ModelCode, c.SpecCode, c.ColorCode }).ToListAsync();
    var changes = await db.RptCarChangeProvinces.Where(x => x.OrgId == t.OrgId && allVins.Contains(x.VIN)).ToListAsync();
    var maps = await db.MapProvinceGpsDmses.Where(x => x.OrgId == t.OrgId).Select(x => new { x.GPSProvinceCode, x.ProvinceCode }).ToListAsync();
    var gpsProvinces = await db.GpsMstProvinces.Where(x => x.OrgId == t.OrgId).Select(x => new { x.GPSProvinceCode, x.GPSProvinceName }).ToListAsync();
    var dealers = await db.Dealers.Where(d => d.OrgId == t.OrgId).Select(d => new { d.DealerCode, d.DealerName, d.BUCode, d.ProvinceCode }).ToListAsync();
    var provinces = await db.MstProvinces.Where(p => p.OrgId == t.OrgId).Select(p => new { p.ProvinceCode, p.ProvinceName }).ToListAsync();
    var models = await db.CarModelStds.Where(m => m.OrgId == t.OrgId).Select(m => new { m.ModelCode, m.ModelName }).ToListAsync();
    var colors = await db.MstCarColors.Where(c => c.OrgId == t.OrgId).Select(c => new { c.ModelCode, c.ColorCode, c.ColorExtName, c.ColorExtNameVN }).ToListAsync();
    var specs = await db.CarSpecs.Where(s => s.OrgId == t.OrgId).Select(s => new { s.SpecCode, s.SpecDesc }).ToListAsync();
    var doCars = await db.DeliveryOrderCars.Where(c => c.OrgId == t.OrgId).Select(c => new { c.DoId, c.Vin, c.ConfirmStatus }).ToListAsync();
    var dos = await db.DeliveryOrders.Where(o => o.OrgId == t.OrgId).Select(o => new { o.Id, DeliveryOrderNo = o.DoNo }).ToListAsync();   // `Car_DeliveryOrder.DeliveryOrderNo` ↔ MiniHTC `DoNo`

    var items = new List<object>();
    int skipNoDo = 0, skipNoChange = 0, skipNoMap = 0, skipSameProvince = 0, skipChangeBefore = 0, skipNoDealer = 0, skipNoCar = 0, skipDeviceVin = 0;
    foreach (var h in heads)
        foreach (var hc in headCars.Where(c => c.TranspDlvConfirmId == h.Id))
        {
            if (vinKey is not null && hc.VIN != vinKey) continue;             // `sdm.VIN` filter
            // `and sdm.VIN = ssbagps.VIN` + `ssbagps.StorageCode = 'STOGPS' and sdm.GPSDvNo = ssbagps.GPSDvNo`
            if (!db.GpsInstalls.Any(g => g.OrgId == t.OrgId && g.StorageCode == "STOGPS"
                                         && g.GpsNo == h.GPSDvNo && g.Vin == hc.VIN)) { skipDeviceVin++; continue; }
            var car = cars.FirstOrDefault(c => c.VIN == hc.VIN);              // `inner join Car_VIN cv`
            if (car is null) { skipNoCar++; continue; }
            // `inner join Car_DeliveryOrderDetail cdod on sdm.RefOrdNo = cdod.DeliveryOrderNo
            //  and cc.CarId = cdod.CarId and cdod.ConfirmStatus in ('A','F')`
            var doId = dos.FirstOrDefault(o => o.DeliveryOrderNo == h.RefOrdNo)?.Id;
            var dline = doId is null ? null : doCars.FirstOrDefault(c => c.DoId == doId && c.Vin == hc.VIN);
            if (dline is null || (dline.ConfirmStatus != "A" && dline.ConfirmStatus != "F")) { skipNoDo++; continue; }
            var dl = dealers.FirstOrDefault(d => d.DealerCode == h.DealerCode);
            if (dl is null) { skipNoDealer++; continue; }                     // `inner join Mst_Province on md.ProvinceCode`
            if (pattern is not null && !(dl.BUCode ?? "").ToUpperInvariant().StartsWith(pattern)) { skipNoDealer++; continue; }
            var mo = models.FirstOrDefault(x => x.ModelCode == car.ModelCode);
            var co = colors.FirstOrDefault(x => x.ModelCode == car.ModelCode && x.ColorCode == car.ColorCode);
            var sp = specs.FirstOrDefault(x => x.SpecCode == car.SpecCode);
            var prov = provinces.FirstOrDefault(x => x.ProvinceCode == dl.ProvinceCode);
            if (prov is null) { skipNoDealer++; continue; }
            foreach (var ch in changes.Where(c => c.VIN == hc.VIN))           // `inner join Rpt_CarChangeProvince`
            {
                var map = maps.FirstOrDefault(x => x.GPSProvinceCode == ch.GPSProvinceCode);
                if (map is null) { skipNoMap++; continue; }                   // `inner join Map_ProvinceGPS_DMS`
                // 🔴 ĐIỀU KIỆN CỐT LÕI 1: tỉnh GPS (đã quy đổi) KHÁC tỉnh của đại lý.
                if (string.Equals(map.ProvinceCode, dl.ProvinceCode, StringComparison.OrdinalIgnoreCase)) { skipSameProvince++; continue; }
                // 🔴 ĐIỀU KIỆN CỐT LÕI 2: lần đổi tỉnh xảy ra SAU thời điểm giao xe.
                if (ch.ChangeDateTime is null || ch.ChangeDateTime < h.DlvEndGPSDateTime) { skipChangeBefore++; continue; }
                var gp = gpsProvinces.FirstOrDefault(x => x.GPSProvinceCode == ch.GPSProvinceCode);
                if (gp is null) { skipNoMap++; continue; }                    // `inner join GPS_Mst_Province`
                items.Add(new
                {
                    dlvMnNo = h.DlvMinutesNo, gpsDvNo = h.GPSDvNo, vin = hc.VIN,
                    dealerCode = h.DealerCode, dealerName = dl.DealerName,
                    provinceCode = dl.ProvinceCode, provinceName = prov.ProvinceName,
                    gpsProvinceCode = map.GPSProvinceCode, gpsProvinceName = gp.GPSProvinceName,
                    modelCode = car.ModelCode, modelName = mo?.ModelName,
                    colorCode = car.ColorCode, colorExtName = co?.ColorExtName, colorExtNameVN = co?.ColorExtNameVN,
                    specCode = car.SpecCode, specDescription = sp?.SpecDesc,
                    changeProvinceDateTime = ch.ChangeDateTime,     // alias `ChangeProvinceDateTime` của nguồn
                    gpsAddress = ch.GPSAddress
                });
            }
        }

    return Results.Ok(new
    {
        count = items.Count, items,
        dataWH = dataWH == "1" || dataWH == "true",
        dataWHNote = "Nguồn có 2 hàm (Main/WH) cùng thuật toán, khác DB đích; MiniHTC 1 DB ⇒ cờ không đổi kết quả.",
        dealerChainNote = "Nguồn lấy đại lý qua chuỗi Car_Car→Dls_DealDetail→DLS_Deal(FlagInitDeal='0')→Mst_Dealer (3 bảng đầu chưa có trong MiniHTC) rồi so md.ProvinceCode; ở đây dùng đại lý trên chính biên bản (sdm.DealerCode) — XẤP XỈ CÓ NHÃN.",
        skipDeviceVin, skipNoCar, skipNoDo, skipNoChange, skipNoMap, skipSameProvince, skipChangeBefore, skipNoDealer,
        note = items.Count == 0 ? "Lưới danh sách dữ liệu trống!" : null
    });
}).RequireAuthorization();

// ===== #152: CẤP SỐ IN HOÁ ĐƠN (Seq_Invoice_PrintNo) =====
// Nguồn: HDDTIntergration/BizHTC.HDDTIntergration.cs (csproj 282) — hàm `Seq_Invoice_PrintNo` (20836).
// 🔴 Ba điểm của nguồn, port nguyên:
//   (1) `YearPrint` KHÔNG phải năm — nguồn gán `dtimeTDate.ToString("yyyy-MM-dd")` ⇒ bộ đếm cấp lại THEO NGÀY;
//   (2) chưa có dòng cho bộ ba (InvoiceIDType, SourceInvoiceCode, YearPrint) ⇒ tạo với LastPrintNo = 0;
//       rồi đọc, **+1**, rồi ghi lại — KHÔNG dùng identity của DB;
//   (3) số in trả về ghép `{0:000}.{ddMMyy}/{19HTC}/{hậu tố}`; "19HTC" là **mẫu số fix cứng trong code**
//       (nguồn ghi chú: "Nguyễn Kiều Ngân báo fix cứng"); hậu tố theo SourceInvoiceCode:
//       INVOICEREPLACE ⇒ "BBTHHĐ", INVOICEADJ ⇒ "BBĐCHĐ", còn lại rỗng.
app.MapGet("/api/invoiceprintno", async (AppDbContext db, ITenantContext t, string? invoiceIdType, string? sourceCode) =>
{
    var q = db.SeqInvoicePrintNos.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(invoiceIdType)) q = q.Where(x => x.InvoiceIDType == invoiceIdType);
    if (!string.IsNullOrWhiteSpace(sourceCode)) q = q.Where(x => x.SourceInvoiceCode == sourceCode);
    var items = await q.OrderByDescending(x => x.Id).Take(1000).Select(x => new {
        x.InvoiceIDType, x.YearPrint, x.SourceInvoiceCode, x.LastPrintNo, x.Remark,
        x.LogLUDateTime, x.LogLUBy }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/invoiceprintno/next", async (InvoicePrintNoDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var idType = (dto.InvoiceIDType ?? "").Trim().ToUpperInvariant();
    var src = (dto.SourceInvoiceCode ?? "").Trim().ToUpperInvariant();
    if (idType.Length == 0 || src.Length == 0) return Results.BadRequest(new { error = "Cần InvoiceIDType và SourceInvoiceCode." });
    if (src is not ("INVOICEROOT" or "INVOICEREPLACE" or "INVOICEADJ"))
        return Results.BadRequest(new { error = "SourceInvoiceCode = INVOICEROOT | INVOICEREPLACE | INVOICEADJ (TConst.SourceInvoiceCode)." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system"; var now = DateTime.Now;
    var yearPrint = now.ToString("yyyy-MM-dd");     // nguồn gán NGÀY vào cột tên "YearPrint"
    var row = await db.SeqInvoicePrintNos.FirstOrDefaultAsync(x => x.OrgId == t.OrgId
        && x.InvoiceIDType == idType && x.SourceInvoiceCode == src && x.YearPrint == yearPrint);
    if (row is null)
    {
        row = new SeqInvoicePrintNo { OrgId = t.OrgId, InvoiceIDType = idType, SourceInvoiceCode = src,
            YearPrint = yearPrint, LastPrintNo = 0, Remark = dto.Remark, LogLUDateTime = now, LogLUBy = who };
        db.SeqInvoicePrintNos.Add(row);
    }
    var next = row.LastPrintNo + 1;
    row.LastPrintNo = next; row.LogLUDateTime = now; row.LogLUBy = who;
    if (dto.Remark is not null) row.Remark = dto.Remark;
    await db.SaveChangesAsync();
    var suffix = src == "INVOICEREPLACE" ? "BBTHHĐ" : src == "INVOICEADJ" ? "BBĐCHĐ" : "";
    var printNo = string.Format("{0:000}.{1}/{2}/{3}", next, dto.InvoiceDate.ToString("ddMMyy"), "19HTC", suffix);
    return Results.Ok(new { invoiceIdType = idType, sourceInvoiceCode = src, yearPrint, lastPrintNo = next, printNo });
}).RequireAuthorization();

// ===== #151: GÓI BẢO TRÌ THEO DÒNG XE (Mst_MaintainType + MtnTp_MaintainTaskItem + MtnTp_Part) =====
// Nguồn: DataWH/Biz.HTC.WH.cs (csproj 272) — _Add_New20181119 (7711) ghi 3 bảng tại 8068/8093/8119;
//        _Update_New20181119 (8213) ghi lại 2 bảng con tại 8602/8628.
// TWIN: cả hai WS đều gọi đủ bộ _Add/_Update/_Delete/_Get_New20181119 ⇒ không lệch.
app.MapGet("/api/maintaintypes", async (AppDbContext db, ITenantContext t, string? model, string? mtnTp, string? flagActive) =>
{
    var q = db.MstMaintainTypes.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(model)) q = q.Where(x => x.ModelCode == model);
    if (!string.IsNullOrWhiteSpace(mtnTp)) q = q.Where(x => x.MtnTp == mtnTp);
    if (!string.IsNullOrWhiteSpace(flagActive)) q = q.Where(x => x.FlagActive == flagActive);
    var items = await q.OrderBy(x => x.ModelCode).ThenBy(x => x.MtnTp).Take(1000).Select(x => new {
        x.MtnTp, x.ModelCode, x.MtnTpName, x.MtnTimes, x.FlagActive, x.LogLUDateTime, x.LogLUBy,
        tasks = db.MtnTpMaintainTaskItems.Count(l => l.OrgId == t.OrgId && l.MtnTp == x.MtnTp && l.ModelCode == x.ModelCode),
        parts = db.MtnTpParts.Count(l => l.OrgId == t.OrgId && l.MtnTp == x.MtnTp && l.ModelCode == x.ModelCode) }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapGet("/api/maintaintypes/{mtnTp}/{model}", async (string mtnTp, string model, AppDbContext db, ITenantContext t) =>
{
    mtnTp = mtnTp.Trim().ToUpperInvariant(); model = model.Trim().ToUpperInvariant();
    var h = await db.MstMaintainTypes.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.MtnTp == mtnTp && x.ModelCode == model);
    if (h is null) return Results.NotFound(new { mtnTp, model });
    var tasks = await db.MtnTpMaintainTaskItems.Where(x => x.OrgId == t.OrgId && x.MtnTp == mtnTp && x.ModelCode == model)
        .Select(x => new { x.MtnTkCode, x.MtnTkItemCode, x.FlagActive, x.LogLUDateTime, x.LogLUBy }).ToListAsync();
    var parts = await db.MtnTpParts.Where(x => x.OrgId == t.OrgId && x.MtnTp == mtnTp && x.ModelCode == model)
        .Select(x => new { x.PartCode, x.Qty, x.FlagActive, x.LogLUDateTime, x.LogLUBy }).ToListAsync();
    return Results.Ok(new { header = new { h.MtnTp, h.ModelCode, h.MtnTpName, h.MtnTimes, h.FlagActive,
        h.LogLUDateTime, h.LogLUBy }, tasks, parts });
}).RequireAuthorization();

// Thêm gói — guard nguồn: cặp (MtnTp, ModelCode) PHẢI CHƯA tồn tại (CheckDB(…, TConst.Flag.No)).
app.MapPost("/api/maintaintypes", async (MaintainTypeDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var mtnTp = (dto.MtnTp ?? "").Trim().ToUpperInvariant();
    var model = (dto.ModelCode ?? "").Trim().ToUpperInvariant();
    if (mtnTp.Length == 0 || model.Length == 0) return Results.BadRequest(new { error = "Cần cả mã gói bảo trì và mã dòng xe (khoá kép)." });
    if (dto.MtnTimes < 0) return Results.BadRequest(new { error = "Số lần bảo trì không được âm." });
    if (await db.MstMaintainTypes.AnyAsync(x => x.OrgId == t.OrgId && x.MtnTp == mtnTp && x.ModelCode == model))
        return Results.Conflict(new { error = $"Gói {mtnTp} của dòng xe {model} đã tồn tại." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system"; var now = DateTime.Now;
    db.MstMaintainTypes.Add(new MstMaintainType { OrgId = t.OrgId, MtnTp = mtnTp, ModelCode = model,
        MtnTpName = dto.MtnTpName, MtnTimes = dto.MtnTimes, FlagActive = "1", LogLUDateTime = now, LogLUBy = who });
    foreach (var k in dto.Tasks ?? new())
        db.MtnTpMaintainTaskItems.Add(new MtnTpMaintainTaskItem { OrgId = t.OrgId, MtnTp = mtnTp, ModelCode = model,
            MtnTkCode = k.MtnTkCode, MtnTkItemCode = (k.MtnTkItemCode ?? "").Trim().ToUpperInvariant(),
            FlagActive = "1", LogLUDateTime = now, LogLUBy = who });
    foreach (var p in dto.Parts ?? new())
        db.MtnTpParts.Add(new MtnTpPart { OrgId = t.OrgId, MtnTp = mtnTp, ModelCode = model,
            PartCode = (p.PartCode ?? "").Trim().ToUpperInvariant(), Qty = p.Qty,
            FlagActive = "1", LogLUDateTime = now, LogLUBy = who });
    await db.SaveChangesAsync();
    return Results.Ok(new { mtnTp, model, tasks = (dto.Tasks ?? new()).Count, parts = (dto.Parts ?? new()).Count });
}).RequireAuthorization();

// Sửa gói — port 1:1 `_Update_New20181119`: UPDATE bảng đầu, rồi **DELETE rồi INSERT LẠI** hai bảng con
// (Biz.HTC.WH.cs:8570/8580 delete → 8602/8628 insert). Không có "sửa từng dòng con".
app.MapPut("/api/maintaintypes/{mtnTp}/{model}", async (string mtnTp, string model, MaintainTypeDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    mtnTp = mtnTp.Trim().ToUpperInvariant(); model = model.Trim().ToUpperInvariant();
    var h = await db.MstMaintainTypes.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.MtnTp == mtnTp && x.ModelCode == model);
    if (h is null) return Results.NotFound(new { mtnTp, model });
    if (dto.MtnTimes < 0) return Results.BadRequest(new { error = "Số lần bảo trì không được âm." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system"; var now = DateTime.Now;
    h.MtnTpName = dto.MtnTpName ?? h.MtnTpName; h.MtnTimes = dto.MtnTimes;
    h.LogLUDateTime = now; h.LogLUBy = who;
    db.MtnTpMaintainTaskItems.RemoveRange(await db.MtnTpMaintainTaskItems.Where(x => x.OrgId == t.OrgId && x.MtnTp == mtnTp && x.ModelCode == model).ToListAsync());
    db.MtnTpParts.RemoveRange(await db.MtnTpParts.Where(x => x.OrgId == t.OrgId && x.MtnTp == mtnTp && x.ModelCode == model).ToListAsync());
    foreach (var k in dto.Tasks ?? new())
        db.MtnTpMaintainTaskItems.Add(new MtnTpMaintainTaskItem { OrgId = t.OrgId, MtnTp = mtnTp, ModelCode = model,
            MtnTkCode = k.MtnTkCode, MtnTkItemCode = (k.MtnTkItemCode ?? "").Trim().ToUpperInvariant(),
            FlagActive = "1", LogLUDateTime = now, LogLUBy = who });
    foreach (var p in dto.Parts ?? new())
        db.MtnTpParts.Add(new MtnTpPart { OrgId = t.OrgId, MtnTp = mtnTp, ModelCode = model,
            PartCode = (p.PartCode ?? "").Trim().ToUpperInvariant(), Qty = p.Qty,
            FlagActive = "1", LogLUDateTime = now, LogLUBy = who });
    await db.SaveChangesAsync();
    return Results.Ok(new { mtnTp, model, tasks = (dto.Tasks ?? new()).Count, parts = (dto.Parts ?? new()).Count,
        note = "Nguồn xoá sạch 2 bảng con rồi ghi lại — không sửa từng dòng." });
}).RequireAuthorization();

