    var specs = await db.MstCarColorSpecs.Where(x => x.OrgId == t.OrgId && x.ModelCode == model && x.ColorCode == color)
        .OrderBy(x => x.SpecCode).Select(x => new { x.SpecCode, x.LogLUDateTime, x.LogLUBy }).ToListAsync();
