app.MapPost("/api/partlocations/import", async (PartLocationImportDto dto, AppDbContext db, ITenantContext t) =>
{
    var rows = dto.Rows ?? new();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Không có dòng nào để nhập." });
    var errors = new List<object>();
    var seen = new HashSet<string>();
    int created = 0, updated = 0;
    for (int i = 0; i < rows.Count; i++)
    {
        var r = rows[i]; var line = i + 1;
        var code = (r.LocationCode ?? "").Trim().ToUpperInvariant();
        if (string.IsNullOrEmpty(code)) { errors.Add(new { line, error = "Thiếu mã vị trí." }); continue; }
        if (string.IsNullOrWhiteSpace(r.LocationName)) { errors.Add(new { line, code, error = "Thiếu tên vị trí." }); continue; }
        if (!seen.Add(code)) { errors.Add(new { line, code, error = "Mã vị trí bị trùng trong file nhập." }); continue; }
        var ex = await db.PartLocations.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.LocationCode == code);
        if (ex is not null) { ex.LocationName = r.LocationName; ex.LocationType = r.LocationType; ex.LocationSurface = r.LocationSurface; ex.LocationHeight = r.LocationHeight; ex.StockNo = r.StockNo; ex.FlagActive = "1"; updated++; }
        else { db.PartLocations.Add(new PartLocation { OrgId = t.OrgId, LocationCode = code, LocationName = r.LocationName, LocationType = r.LocationType, LocationSurface = r.LocationSurface, LocationHeight = r.LocationHeight, StockNo = r.StockNo, FlagActive = "1" }); created++; }
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { total = rows.Count, created, updated, errorCount = errors.Count, errors });
}).RequireAuthorization();

// Nhập tồn kho + vị trí phụ tùng hàng loạt (port 1:1 FrmImportInventory) — set ServicePart.Quantity + Location.
app.MapPost("/api/serviceparts/inventory-import", async (InventoryImportDto dto, AppDbContext db, ITenantContext t) =>
{
    var rows = dto.Rows ?? new();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Không có dòng nào để nhập." });
    var errors = new List<object>();
    int updatedParts = 0;
    for (int i = 0; i < rows.Count; i++)
    {
        var r = rows[i]; var line = i + 1;
        var code = (r.PartCode ?? "").Trim().ToUpperInvariant();
        if (string.IsNullOrEmpty(code)) { errors.Add(new { line, error = "Thiếu mã phụ tùng." }); continue; }
        if (r.Quantity < 0) { errors.Add(new { line, code, error = "Tồn kho không hợp lệ." }); continue; }
        var part = await db.ServiceParts.FirstOrDefaultAsync(p => p.OrgId == t.OrgId && p.PartCode == code);
        if (part is null) { errors.Add(new { line, code, error = "Phụ tùng không có trong danh mục." }); continue; }
        part.Quantity = r.Quantity;
        if (!string.IsNullOrWhiteSpace(r.LocationCode)) part.Location = r.LocationCode.Trim().ToUpperInvariant();
        updatedParts++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { total = rows.Count, updatedParts, errorCount = errors.Count, errors });
}).RequireAuthorization();

// ===== Danh mục dịch vụ/công (ServiceItemMst — port 1:1 FrmService/FrmImportService, TCMotor) =====
app.MapGet("/api/serviceitems", async (AppDbContext db, ITenantContext t, string? q, string? model, string? active) =>
{
    var query = db.ServiceItemMsts.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(q)) query = query.Where(x => x.SerCode.Contains(q!.ToUpper()) || (x.SerName != null && x.SerName.Contains(q!)));
    if (!string.IsNullOrWhiteSpace(model)) query = query.Where(x => x.Model == model);
    if (!string.IsNullOrWhiteSpace(active)) query = query.Where(x => x.FlagActive == active);
    var items = await query.OrderBy(x => x.SerCode).Take(500)
        // #297 §12: 6 cột bổ sung có mặt ở CẢ GET lẫn POST
        .Select(x => new { x.SerCode, x.SerName, x.Cost, x.Price, x.Model, x.Vat, x.Note, x.FlagActive,
            x.DealerCode, x.SerTypeID, x.StdManHour, x.Factor, x.Status, x.FlagWarranty }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/serviceitems", async (ServiceItemDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.SerCode)) return Results.BadRequest(new { error = "Chưa nhập mã dịch vụ." });
    if (string.IsNullOrWhiteSpace(dto.SerName)) return Results.BadRequest(new { error = "Chưa nhập tên dịch vụ." });
    // ===== 🔴 #252 txtMaDV — MỘT tên control, HAI nghĩa ở hai màn =====
    // `Views/Services/FrmServices.cs:409` và `:645` kiểm `this.regex.IsMatch(txtMaDV.Text)`
    //   ⇒ ở màn này `txtMaDV` bind vào **`SerCode`** (mã DỊCH VỤ) — xem :169, :227, :281.
    // ⚠️ Thông điệp của nguồn ở đây là `MSG_WARNING_KEYSPE_PARTCODE` = "Mã **phụ tùng** không được phép
    //    chứa các ký tự đặc biệt" — **SAI nghĩa** (chép từ màn phụ tùng), nhưng đây là 1:1 nên GIỮ NGUYÊN.
    if (HasSpecialChar(dto.SerCode.Trim()))
        return Results.BadRequest(new { error = "Mã phụ tùng không được phép chứa các ký tự đặc biệt" });
    if (dto.Price < 0 || dto.Cost < 0 || dto.Vat < 0) return Results.BadRequest(new { error = "Giá/vốn/VAT không hợp lệ." });
    var code = dto.SerCode.Trim().ToUpperInvariant();

    // ===== 🔴 #297 LUẬT GHI ĐÈ TỪ DANH MỤC CÔNG BẢO HÀNH CỦA HÃNG =====
    // Nguồn `Ser_Mst_Service_Create` (`BizCarSv.Service.cs`), chú thích **của chính tác giả**:
    //   *"Tạo mới nếu mã CV trùng mới mã CV bảo hành của HTV thì lấy từ master CV bảo hàng xuống,
    //     Đại lý ko dc tạo mới"*
    // ⇒ nếu `SerCode` trùng một công bảo hành **đang hiệu lực** trong `Ser_MST_ROWarrantyWork` thì **MỌI**
    //   trường người dùng nhập bị **GHI ĐÈ** bằng giá trị của danh mục hãng, kèm `SerTypeID = "1"` và
    //   `FlagWarranty` bật. Người dùng nhập gì cũng không có tác dụng — đây là **dữ liệu của HÃNG**.
    // ⚠️ Ánh xạ cột: `ROWWorkName`→SerName · `RateHour`→StdManHour · `RatePrice`→Cost · `Price`→Price ·
    //   `VAT`→Vat · `Model`→Model · `Remark`→Note. `FlagWarranty` mặc định TẮT, chỉ bật ở nhánh này.
    var ww = await db.WarrantyWorkMsts.FirstOrDefaultAsync(w => w.OrgId == t.OrgId
        && w.ROWWorkCode == code && w.FlagActive == "1");

    var serName = dto.SerName; var cost = dto.Cost; var price = dto.Price;
    var vat = dto.Vat; var model = dto.Model; var note = dto.Note;
    var serTypeId = dto.SerTypeID; var stdManHour = dto.StdManHour;
    var flagWarranty = "0";                       // nguồn: Constants.Flag.Inactive
    if (ww is not null)
    {
        serName = ww.ROWWorkName; serTypeId = "1";
        stdManHour = ww.RateHour; cost = ww.RatePrice; price = ww.Price;
        vat = ww.VAT; model = ww.ModelCode; note = ww.Remark;
        flagWarranty = "1";                       // Constants.Flag.Active
    }

    var ex = await db.ServiceItemMsts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SerCode == code);
    if (ex is not null)
    {
        ex.SerName = serName; ex.Cost = cost; ex.Price = price; ex.Model = model; ex.Vat = vat; ex.Note = note; ex.FlagActive = "1";
        ex.DealerCode = dto.DealerCode?.Trim().ToUpperInvariant();
        // Nguồn ghi **DBNull khi rỗng** cho SerTypeID, không ghi chuỗi rỗng.
        ex.SerTypeID = string.IsNullOrWhiteSpace(serTypeId) ? null : serTypeId;
        ex.StdManHour = stdManHour; ex.Factor = dto.Factor;
        ex.Status = dto.Status; ex.FlagWarranty = flagWarranty;
        await db.SaveChangesAsync();
        return Results.Ok(new { ex.SerCode, updated = true, fromWarrantyWork = ww is not null });
    }
    var r = new ServiceItemMst
    {
        OrgId = t.OrgId, SerCode = code, SerName = serName, Cost = cost, Price = price,
        Model = model, Vat = vat, Note = note, FlagActive = "1",
        DealerCode = dto.DealerCode?.Trim().ToUpperInvariant(),
        SerTypeID = string.IsNullOrWhiteSpace(serTypeId) ? null : serTypeId,
        StdManHour = stdManHour, Factor = dto.Factor, Status = dto.Status, FlagWarranty = flagWarranty,
    };
    db.ServiceItemMsts.Add(r); await db.SaveChangesAsync();
    return Results.Ok(new { r.SerCode, updated = false, fromWarrantyWork = ww is not null,
        note = ww is not null ? "Mã trùng công bảo hành của hãng — toàn bộ thông tin lấy từ danh mục hãng." : null });
}).RequireAuthorization();

