    if (x is null) return Results.NotFound(new { code });
    x.FlagActive = x.FlagActive == "1" ? "0" : "1";
    await db.SaveChangesAsync();
    return Results.Ok(new { x.GroupCode, flagActive = x.FlagActive });
}).RequireAuthorization();

// ===== Công nợ khách hàng dịch vụ + thu tiền (CusDebit — port 1:1 FrmCusDebitCreate/FrmCusPaymentCreate, TCMotor) =====
// ===== 🔴 #555 CÔNG NỢ **BẢO HIỂM** VÀ **NHÀ CUNG CẤP** — MỘT BẢNG, BA LOẠI =====
// Nguồn: `BizCarSv.Debit.cs:1314 SerInsuranceDebitDetailGet` · `:1475 SerSupplierDebitDetailGet`.
// Endpoint: `GET /api/debits/detail?debitType=1|2|3`. **§12**: thêm `DebitType` · `InsNo` ·
//   `SupplierCode` · `StockInID` vào `CusDebit`.
//
// 📐 **DIFF BA HÀM ANH EM** (#554 là loại 1) — cùng khuôn *ba bảng*, khác đúng bốn chỗ:
//   · bảng **đối tượng**: `Ser_Customer` / `Ser_Insurance` / `Ser_Mst_supplier`
//   · **khoá lọc**: `d.CusID` / `d.InsNo` / `d.SupplierID`
//   · **hằng loại**: `DebitType/PaymentType = '1'` / `'2'` / `'3'`
//   · **khoá nối chứng từ**: loại 1 và 2 nối `Ser_RO` qua `d.ROID`; loại **3** nối
//     `Ser_Inv_StockIn` qua `d.**StockInID**` ⇒ **cùng một bảng công nợ, hai khoá nối khác nhau**.
// 🔴 **CẢ BA LOẠI DÙNG CHUNG BẢNG `Ser_CusDebit`** — tên bảng nói "Cus" nhưng chứa cả nợ bảo hiểm
//   và nợ nhà cung cấp. ⇒ Bất kỳ truy vấn nào **quên `DebitType`** sẽ **trộn ba loại nợ** vào một.
//   MiniHTC trước nay chỉ có loại 1 và **không có cột `DebitType`** ⇒ nay bổ sung; endpoint cũ
//   `/api/cusdebits` vẫn giữ nguyên hành vi vì dữ liệu cũ mặc định `'1'`.
// 🔴 **Bộ lọc lại dùng chung alias `d` cho cả ba câu** (như #554): với loại 2 thì `d.InsNo` phải tồn tại
//   trên **cả** `Ser_Insurance`, `Ser_CusDebit` **và** `Ser_Payment` — ba bảng bắt buộc có cùng tên cột,
//   nếu một bảng đổi tên cột là **SQL nổ** (lớp lỗi alias #537).
// ⚠️ **Hai quy ước khoá đọc trong CÙNG một file**: bản bảo hiểm viết `with(nolock)` **thẳng**,
//   bản khách và bản nhà cung cấp dùng dấu `--//[mylock]`. Chép nguyên trạng, không "sửa cho đều".
// ⚠️ Bản nhà cung cấp lọc theo tham số tên `strSupplierIDConditionList` nhưng cột select là
//   `d.SupplierCode` — **tên tham số và tên cột lệch nhau** (ID vs Code).
app.MapGet("/api/debits/detail", async (AppDbContext db, ITenantContext t,
    string? debitType, string? cusId, string? insNo, string? supplierCode, string? dealerCode) =>
{
    var type = (debitType ?? "1").Trim();
    if (type is not ("1" or "2" or "3"))
        return Results.BadRequest(new { error = "debitType chỉ nhận 1 (khách), 2 (bảo hiểm), 3 (nhà cung cấp)." });

    // ===== 🔴🔴 #558 SỬA LẠI #555: MiniHTC **ĐÃ CÓ BA BẢNG RIÊNG**, không phải một bảng ba loại =====
    // #555 đọc `db.CusDebits` cho **cả ba** loại vì nguồn dùng chung `Ser_CusDebit`. Nhưng grep route
    //   (`/api/debits/search`, `:27235` — cụm #213/#214/#215) cho thấy MiniHTC **từ trước** đã tách:
    //   `CusDebits` (khách) · `InsDebits` (bảo hiểm) · `SupplierDebits` (nhà cung cấp).
    // ⇒ Nếu giữ nguyên #555 thì `debitType=2|3` **luôn trả rỗng** — dữ liệu nằm ở hai bảng kia.
    //   Nay đọc **đúng bảng theo loại**; cột `DebitType` thêm ở #555 vẫn giữ để đánh dấu nguồn gốc
    //   dữ liệu nhập từ hệ cũ (nơi cả ba loại nằm chung một bảng).
    // 📌 Bài học quy trình: BƯỚC 2 phải grep **cả ROUTE** (`MapGet("/api/…")`), không chỉ tên hàm nguồn —
    //   ở đây tên hàm `SerCusDebitSearch` chỉ xuất hiện trong **chú thích** nên grep tên trượt,
    //   và lỗi lộ ra ở **cảnh báo route trùng** lúc build chứ không phải lúc đọc.
    object? party = null;
    var debits = new List<object>();
    var debitIds = new List<long>();
    if (type == "1")
    {
        var cus = (cusId ?? "").Trim();
        if (cus.Length == 0) return Results.BadRequest(new { error = "Loại 1 cần cusId." });
        var c = await db.ServiceCustomers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CusCode == cus);
        party = c is null ? null : new { c.CusCode, c.CusName, c.Address, c.ContName };
        var rows1 = await db.CusDebits.Where(x => x.OrgId == t.OrgId && x.CusId == cus)
            .OrderByDescending(x => x.Id)
            .Select(x => new { x.Id, x.DebitNo, key = x.CusId, name = x.CusName, doc = x.RONo,
                x.DebitAmount, x.PaidAmount, balance = x.DebitAmount - x.PaidAmount,
                x.DebitDate, x.Status, x.Note }).ToListAsync();
        debits.AddRange(rows1);
        debitIds.AddRange(rows1.Select(x => x.Id));
    }
    else if (type == "2")
    {
        var ins = (insNo ?? "").Trim();
        if (ins.Length == 0) return Results.BadRequest(new { error = "Loại 2 cần insNo." });
        // MiniHTC lưu danh mục bảo hiểm theo InsCompanyCode (nguồn dùng Ser_Insurance.InsNo).
        var i = await db.MstInsuranceCompanies.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.InsCompanyCode == ins);
        party = i is null ? null : new { i.InsCompanyCode, i.InsCompanyName, i.FlagActive };
        var rows2 = await db.InsDebits.Where(x => x.OrgId == t.OrgId && x.InsNo == ins)
            .OrderByDescending(x => x.Id)
            .Select(x => new { x.Id, x.DebitNo, key = x.InsNo, name = x.InsName, doc = x.RONo,
                x.DebitAmount, x.PaidAmount, balance = x.DebitAmount - x.PaidAmount,
                x.DebitDate, x.Status, x.Note }).ToListAsync();
        debits.AddRange(rows2);
        debitIds.AddRange(rows2.Select(x => x.Id));
    }
    else
    {
        var sup = (supplierCode ?? "").Trim();
        if (sup.Length == 0) return Results.BadRequest(new { error = "Loại 3 cần supplierCode." });
        var sp = await db.SerMstSuppliers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SupplierCode == sup);
        party = sp is null ? null : new { sp.SupplierCode, sp.SupplierName, sp.Address, sp.Phone };
        var rows3 = await db.SupplierDebits.Where(x => x.OrgId == t.OrgId && x.SupplierCode == sup)
            .OrderByDescending(x => x.Id)
            .Select(x => new { x.Id, DebitNo = (string?)null, key = x.SupplierCode, name = (string?)null, doc = x.StockInNo,
                x.DebitAmount, x.PaidAmount, balance = x.DebitAmount - x.PaidAmount,
                x.DebitDate, x.Status, x.Note }).ToListAsync();
        debits.AddRange(rows3);
        debitIds.AddRange(rows3.Select(x => x.Id));
    }


    // Mỗi loại nợ có bảng phiếu thu RIÊNG trong MiniHTC (nguồn dùng chung Ser_Payment + PaymentType).
    List<object> payments = new();
    if (type == "1")
    {
        var pq = db.CusDebitPayments.Where(x => x.OrgId == t.OrgId && debitIds.Contains(x.CusDebitId));
        if (!string.IsNullOrWhiteSpace(dealerCode)) pq = pq.Where(x => x.DealerCode == dealerCode!.Trim());
        payments.AddRange((await pq.OrderByDescending(x => x.Id)
            .Select(x => new { x.Id, debitId = x.CusDebitId, x.PaymentNo, x.DealerCode, x.PayPersonName,
                x.PaymentAmount, x.PayDate, x.Note }).ToListAsync()).Cast<object>());
    }
    else if (type == "2")
    {
        payments.AddRange((await db.InsDebitPayments.Where(x => x.OrgId == t.OrgId && debitIds.Contains(x.InsDebitId))
            .OrderByDescending(x => x.Id)
            .Select(x => new { x.Id, debitId = x.InsDebitId, x.PaymentNo, x.PaymentAmount, x.PayDate, x.Note })
            .ToListAsync()).Cast<object>());
    }
    else
    {
        payments.AddRange((await db.SupplierDebitPayments.Where(x => x.OrgId == t.OrgId && debitIds.Contains(x.SupplierDebitId))
            .OrderByDescending(x => x.Id)
            .Select(x => new { x.Id, debitId = x.SupplierDebitId, x.PaymentNo, x.PaymentAmount, x.PayDate, x.Note })
            .ToListAsync()).Cast<object>());
    }

    return Results.Ok(new
    {
        debitType = type, party, partyFound = party is not null,
        debits, debitCount = debits.Count,
        payments, paymentCount = payments.Count,
        oneTableThreeDebitTypesInSource = "Ser_CusDebit chua ca no khach (1), bao hiem (2), nha cung cap (3)",
        miniHtcUsesThreeSeparateTables = "CusDebits / InsDebits / SupplierDebits — sua lai #555",
        documentJoinKeyDiffersByType = "loai 1/2 noi Ser_RO qua ROID; loai 3 noi Ser_Inv_StockIn qua StockInID",
        filterAliasSharedAcrossThreeTables = true,
        insuranceVariantUsesRawNolock = true,
        supplierParamNameVsColumnMismatch = "strSupplierIDConditionList vs cot d.SupplierCode",
    });
}).RequireAuthorization();

// ===== 🔴 #554 CHI TIẾT CÔNG NỢ KHÁCH — BA BẢNG, MỘT BỘ LỌC DÙNG CHUNG QUA **ALIAS** =====
// Nguồn: `BizCarSv.Debit.cs:997 SerCusDebitDetailGet`. Endpoint: `GET /api/cusdebits/{cusId}/detail`.
// Nguồn trả **ba bảng** trong một lời gọi: `Ser_Customer` · `Ser_CusDebit` · `Ser_Payment`.
//
// 🔴 **`JOIN Ser_Car` (INNER) Ở CÂU KHÁCH HÀNG — HAI HẬU QUẢ CÙNG LÚC**:
//     `FROM Ser_Customer d JOIN Ser_Car car ON d.CusID = car.CusID`
//   · Khách **chưa có xe** ⇒ **không ra dòng nào** ⇒ màn công nợ **không hiện được tên khách**
//     dù bảng công nợ bên dưới vẫn có số (luật #410).
//   · Khách có **nhiều xe** ⇒ bảng "khách hàng" trả **nhiều dòng cho một khách** (mỗi xe một dòng)
//     ⇒ hình dạng kết quả **không phải một-khách-một-dòng** như tên bảng gợi ý (§12: "một bản ghi là gì?").
//   Port: lấy khách **một dòng**, kèm **danh sách biển số**, và đếm `plateCount`.
// 🔴 **MỘT CẶP MỆNH ĐỀ LỌC DÙNG LẠI CHO CẢ BA CÂU QUA ALIAS `d`**:
//   `BuildClause("and", "**d**.DealerCode", …)` · `BuildClause("and", "**d**.CusID", …)` — mà `d` lần lượt là
//   `Ser_Customer` · `Ser_CusDebit` · `Ser_Payment`. Tiết kiệm nhưng **giòn**: đổi alias ở **một** câu là
//   mệnh đề bám sang bảng khác hoặc **SQL nổ** (đúng lớp lỗi alias của #537).
// ⚠️ **Câu thứ nhất KHÔNG có dấu `;`** kết thúc (hai câu sau đều có) — hợp lệ với SQL Server nên chỉ là
//   bất nhất về hình thức; ghi lại để lượt sau khỏi tưởng thiếu câu.
// ⚠️ HẰNG literal: `DebitType = '1'` (công nợ **khách hàng**) và `PaymentType = '1'` (thu **của khách**)
//   — hai bảng dùng **hai tên cột khác nhau** cho cùng ý "loại 1".
// ⚠️ **Phạm vi dữ liệu khác nhau**: `Ser_Payment` nằm ở `[@strDBName_CommonCenter].[dbo]` (**dùng chung**
//   toàn hệ) còn `Ser_Customer`/`Ser_CusDebit` ở **DB hiện hành** — cùng lớp phát hiện với #541.
// ⚪ Hai `left join` ở câu công nợ (`Ser_RO`, `ser_car`) **còn sống**: không điều kiện WHERE nào trên chúng
//   ⇒ công nợ **không gắn lệnh sửa chữa** vẫn ra dòng, chỉ trống `RONo`/`PlateNo` (kiểm tra âm tính).
// ===== 🔴🔴 #561 API TVO: KHÁCH ĐÃ LÀM DỊCH VỤ (MỜI KHẢO SÁT) — **BỐN LỖI SQL Ở NGUỒN** =====
// Nguồn: `BizCarSv.TVO.cs:159-425 HTCMobileTVO_GetCustomersUsedService` (một hàm, không sinh đôi).
// Chuỗi ba bảng tạm `_Draft_01` → `_Draft` (đánh `identity`) → `_Filter` (cắt trang), rồi câu trả về.
// Tiêu chí nghiệp vụ (chép từ chú thích nguồn): làm dịch vụ tại đại lý + có báo giá · loại việc BDD/SCC/SCD/SCS
//   · đối tượng thanh toán là khách · phát sinh phí > 0 · trạng thái báo giá `FNS` (đã giao xe).
//
// 🔴🔴 **LỖI 1 — `left join` VIẾT SAI ĐIỀU KIỆN, THÀNH TÍCH ĐỀ-CÁC**:
//     `left join TVO_Ser_RO_RollbackStatus tvo_ro on **t.ROID = ro.ROID**`
//   Điều kiện **không hề nhắc alias `tvo_ro`** — nó so hai bảng **khác** (và luôn đúng, vì `ro` đã nối theo
//   `t.ROID`) ⇒ mỗi dòng kết quả **nhân với TOÀN BỘ số dòng** của `TVO_Ser_RO_RollbackStatus`.
//   Câu trả về **không có `distinct`** ⇒ **nở dòng thật**. Mà không cột nào của `tvo_ro` được chọn
//   ⇒ phép nối vừa **thừa** vừa **phá kết quả**. Chính là câu hỏi thứ ba của luật #414.
// 🔴 **LỖI 2 — `left join` bị điều kiện `where` biến thành `inner`**: `rosi` (`Ser_ROServiceItems`) nối
//   `left` nhưng `where` có `and rosi.ROType in (...)` **và** `and rosi.ExpenseType in (...)` ⇒ RO nào
//   **chỉ có phụ tùng** (không có dòng công) **rơi hết**, dù khối `or` phía trên có nhánh tính riêng `ropi`.
//   ⚠️ Chú thích *"-- Đối tượng thanh toán: Khách hàng"* đặt **trên** dòng `rosi.ExpenseType` nhưng thực ra
//     nằm **giữa** hai điều kiện khác — chú thích và điều kiện **lệch nhau**.
// 🔴 **LỖI 3 — `Convert(nvarchar, …, N)` CẮT CỤT CHUỖI Ở 30 KÝ TỰ**: trong SQL Server, tham số thứ ba của
//   `CONVERT` là **style**, **không phải độ dài**; `nvarchar` **không ghi độ dài** ⇒ mặc định **30**.
//   ⇒ `Convert(nvarchar, ro.CusAddress, **200**) CustomerAddress` **vẫn chỉ trả 30 ký tự** — con số 200
//     trông như "cho rộng hơn" nhưng **không có tác dụng gì**. Tên khách, địa chỉ dài **bị cắt câm**.
//   ⚠️ Riêng `Left(Convert(nvarchar, ro.ActualDeliveryDate, 120), 19)` thì **đúng**: với ngày, 120 **là**
//     mã style thật (`yyyy-mm-dd hh:mi:ss`) — cùng một cách viết, chỗ đúng chỗ sai.
// 🔴 **LỖI 4 — `<= @strToDate` mất ngày cuối** (#415): `ro.LogLUDateTime <= @strToDate`; nếu client gửi
//   `00:00:00` thì **cả ngày cuối biến mất**. Port dùng **< ngày-kế-tiếp** và nêu cờ.
// ⚠️ Phân trang: `nFilterRecordEnd = 0 + Convert.ToInt64(strCount) - 1` ⇒ `strCount` **rỗng thì ném lỗi**,
//   `"0"` thì `end = -1` ⇒ **rỗng**; và luôn bắt đầu từ **0**, **không có tham số trang**.
// ⚪ Kiểm tra âm tính: `union all` với `TVO_Ser_RO_RollbackStatus` (đơn hàng bị thu hồi trạng thái) là **cố ý**
//   — `AutoId = 0` ⇒ `IsDeleted='0'`; khác 0 ⇒ `IsDeleted='1'` + `DeletionTime`. Đây là cơ chế báo **xoá**
//   cho phía TVO, **không** phải rác. MiniHTC chưa có bảng thu hồi ⇒ mọi dòng `isDeleted="0"`, nêu cờ.
app.MapGet("/api/tvo/customers-used-service", async (AppDbContext db, ITenantContext t,
    string? fromDate, string? toDate, int? count) =>
{
    if (!DateTime.TryParse(fromDate, out var f) || !DateTime.TryParse(toDate, out var to))
        return Results.BadRequest(new { error = "fromDate/toDate không hợp lệ." });
    var n = count ?? 0;
    if (n <= 0)
        return Results.BadRequest(new { error = "count phải > 0 (nguồn: count=0 ⇒ end=-1 ⇒ rỗng câm)." });
    var toEx = to.Date == to ? to.AddDays(1) : to;   // #415 — nguồn dùng <=, mất ngày cuối

    var ROTYPES = new[] { "BDD", "SCC", "SCD", "SCS" };
    var EXPENSES = new[] { "ROREPAIR", "ROINSURANCE" };

    // Bước 1: RO đủ điều kiện. Nguồn lọc rosi.ROType + rosi.ExpenseType trong WHERE trên bảng left join
    //   ⇒ hoá inner. Port GIỮ đúng phạm vi đó (RO phải có dòng công hợp lệ) nhưng ĐẾM số RO bị loại.
    var baseQ = db.RepairOrders.Where(r => r.OrgId == t.OrgId
        && r.Status == "FNS" && (r.IsReRepair == null || r.IsReRepair == "0")
        && r.LogLUDateTime != null && r.LogLUDateTime >= f && r.LogLUDateTime < toEx);

    var withSer = await (from r in baseQ
                         join si in db.RoServiceItems.Where(x => x.OrgId == t.OrgId) on r.Id equals si.RoId
                         where si.ROType != null && ROTYPES.Contains(si.ROType)
                               && si.ExpenseType != null && EXPENSES.Contains(si.ExpenseType)
                               && (si.Price * si.Factor) * (si.Vat / 100m + 1m) - (si.InsurancePrice ?? 0m) > 0m
                         select r.Id).Distinct().ToListAsync();

    // Số RO chỉ có phụ tùng (đủ phí) mà nguồn LÀM RƠI vì left join hoá inner.
    var partOnly = await (from r in baseQ
                          join pi in db.RoPartItems.Where(x => x.OrgId == t.OrgId) on r.Id equals pi.RoId
                          where (pi.UnitPrice * pi.NeedQty * pi.Factor) * (pi.Vat / 100m + 1m) - (pi.InsurancePrice ?? 0m) > 0m
                                && !withSer.Contains(r.Id)
                          select r.Id).Distinct().CountAsync();

    var rows = await (from r in db.RepairOrders.Where(x => x.OrgId == t.OrgId && withSer.Contains(x.Id))
                      join c in db.ServiceCustomers.Where(x => x.OrgId == t.OrgId)
                          on r.CusID equals c.CusCode into gc
                      from c in gc.DefaultIfEmpty()
                      join car in db.CustomerCars.Where(x => x.OrgId == t.OrgId)
                          on r.LicensePlate equals car.PlateNo into gcar
                      from car in gcar.DefaultIfEmpty()
                      orderby r.LogLUDateTime
                      select new
                      {
                          cusId = r.CusID, roId = r.Id, r.RONo,
                          customerCode = c == null ? null : c.CusCode,
                          customerName = c == null ? r.CusName : c.CusName,
                          customerMobile = c == null ? r.CusMobile : c.Mobile,
                          r.ActualDeliveryDate,
                          customerAddress = r.CusAddress,          // KHÔNG cắt 30 ký tự như nguồn
                          r.CarID, plateNo = r.LicensePlate,
                          vin = car == null ? r.Vin : car.FrameNo,
                          modelCode = car == null ? null : car.ModelCode,
                          r.DealerCode,
                          deletionTime = (DateTime?)null, isDeleted = "0",
                          createDateTime = r.CheckInDate, r.LogLUDateTime,
                      }).Skip(0).Take(n).ToListAsync();

    return Results.Ok(new
    {
        count = rows.Count, rows,
        criteria = new { status = "FNS", roTypes = ROTYPES, expenseTypes = EXPENSES, feeGreaterThanZero = true },
        sourceCartesianJoinOnRollbackTable = "left join TVO_Ser_RO_RollbackStatus tvo_ro ON t.ROID = ro.ROID — dieu kien KHONG nhac tvo_ro => no dong, va khong cot nao cua no duoc chon",
        sourceLeftJoinTurnedInnerByWhere = "rosi.ROType/ExpenseType nam trong WHERE tren bang left join",
        droppedByThatBug_partOnlyRoCount = partOnly,
        sourceTruncatesStringsAt30 = "Convert(nvarchar, x, N): N la STYLE khong phai do dai; nvarchar khong ghi do dai => mac dinh 30 ky tu",
        sourceCusAddressDeclared200ButGets30 = true,
        dateUpperBoundFixed = "nguon <= @strToDate (mat ngay cuoi); port dung < ngay ke tiep",
        pagingAlwaysFromZero = "nguon: nFilterRecordStart = 0 co dinh, khong co tham so trang",
        rollbackRowsNotModelled = "TVO_Ser_RO_RollbackStatus chua co trong MiniHTC => moi dong isDeleted=0",
    });
}).RequireAuthorization();

// ===== 🔴 #560 BẢN `_WH` CỦA CHI TIẾT CÔNG NỢ — **BA NGUỒN DỮ LIỆU TUỲ HÀM** =====
// Nguồn: `BizCarSv.Debit.cs:1155 SerCusDebitDetailGet_WH` — sinh đôi của `:997` (đã port #554).
// 📐 **DIFF hai bản** (luật #414) — khác đúng **hai** chỗ, và cả hai đều về **NGUỒN DỮ LIỆU**:
//   1) Bản chính đọc bằng `_dbDealer.ExecQuery(...)`; bản `_WH` đọc bằng `_dbWH.ExecQuery(...)`.
//   2) Bản chính lấy phiếu thu từ `[@strDBName_CommonCenter].[dbo].**Ser_Payment**` (**cross-DB**);
//      bản `_WH` lấy `Ser_Payment` **tại chỗ** (không tiền tố) ⇒ đọc bảng thu **của DB kho**.
//   ⇒ **Cùng một câu hỏi nghiệp vụ ("khách này nợ bao nhiêu?"), ba nguồn dữ liệu khác nhau**:
//     nợ ở **DB đại lý** hoặc **DB kho**; thu ở **CommonCenter** hoặc **DB kho**.
//     Hai màn có thể cho **hai con số khác nhau** mà không màn nào sai theo định nghĩa của nó.
// ⚠️ Câu SQL còn lại **giống hệt** — kể cả `JOIN Ser_Car` (INNER) làm rơi khách chưa có xe (#554)
//   và cặp mệnh đề lọc dùng chung alias `d`. Sai sót của bản chính **được sao y** sang bản kho.
// 📌 MiniHTC **một DB** ⇒ không tái hiện được sự lệch; thêm tham số `scope=main|wh` để **đánh dấu**
//   người gọi đang hỏi theo phạm vi nào, và trả cờ nêu rõ nguồn dữ liệu của từng bản.
app.MapGet("/api/cusdebits/{cusId}/detail", async (string cusId, AppDbContext db, ITenantContext t,
    string? dealerCode, string? scope) =>
{
    const string kDebitTypeCustomer = "1";     // DebitType = '1'
    const string kPaymentTypeCustomer = "1";   // PaymentType = '1'
    var cus = (cusId ?? "").Trim();
    if (cus.Length == 0) return Results.BadRequest(new { error = "Cần cusId." });

    // Bảng 1 — khách hàng. Nguồn INNER JOIN xe ⇒ ở đây lấy MỘT dòng + danh sách biển số.
    var customer = await db.ServiceCustomers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CusCode == cus);
    var plates = await db.ServiceCars.Where(x => x.OrgId == t.OrgId && x.CusID == cus)
        .Select(x => x.PlateNo).ToListAsync();

    // Bảng 2 — công nợ khách (DebitType = 1).
    var debitQuery = db.CusDebits.Where(x => x.OrgId == t.OrgId && x.CusId == cus);
    var debits = await debitQuery.OrderByDescending(x => x.Id)
        .Select(x => new { x.Id, x.DebitNo, x.CusId, x.CusName, x.RONo, x.DebitAmount, x.PaidAmount,
            balance = x.DebitAmount - x.PaidAmount, x.DebitDate, x.Status, x.Note })
        .ToListAsync();
    var debitIds = debits.Select(x => x.Id).ToList();

    // Bảng 3 — phiếu thu của khách (PaymentType = 1).
    var payQuery = db.CusDebitPayments.Where(x => x.OrgId == t.OrgId && debitIds.Contains(x.CusDebitId));
    if (!string.IsNullOrWhiteSpace(dealerCode)) payQuery = payQuery.Where(x => x.DealerCode == dealerCode!.Trim());
    var payments = await payQuery.OrderByDescending(x => x.Id)
        .Select(x => new { x.Id, x.CusDebitId, x.PaymentNo, x.DealerCode, x.PayPersonName,
            x.PayPersonIDCardNo, x.PaymentAmount, x.PayDate, x.Note })
        .ToListAsync();

    return Results.Ok(new
    {
        customer = customer is null ? null : new
        {
            customer.CusCode, customer.CusName, customer.Address, customer.ContName,
            plateNos = plates,
        },
        customerFound = customer is not null,
        plateCount = plates.Count,
        // Nguồn INNER JOIN xe ⇒ khách chưa có xe thì BẢNG KHÁCH RỖNG dù công nợ vẫn có.
        sourceInnerJoinCarDropsCarlessCustomer = plates.Count == 0,
        sourceDuplicatesCustomerPerCar = plates.Count > 1,
        debits, debitCount = debits.Count,
        payments, paymentCount = payments.Count,
        totalDebit = debits.Sum(x => x.DebitAmount),
        totalPaid = debits.Sum(x => x.PaidAmount),
        totalBalance = debits.Sum(x => x.balance),
        // ===== #560 =====
        scope = string.Equals((scope ?? "main").Trim(), "wh", StringComparison.OrdinalIgnoreCase) ? "wh" : "main",
        sourceReadsDifferentDbPerVariant = "ban chinh: _dbDealer + Ser_Payment o CommonCenter; ban _WH: _dbWH + Ser_Payment tai cho",
        twoVariantsMayReturnDifferentNumbers = true,
        whVariantCopiesSameInnerJoinFlaw = "JOIN Ser_Car (INNER) va alias dung chung — sao y ban chinh",
        filterAliasSharedAcrossThreeTables = "d.DealerCode / d.CusID — alias d lan luot la Ser_Customer, Ser_CusDebit, Ser_Payment",
        constants = new { debitType = kDebitTypeCustomer, paymentType = kPaymentTypeCustomer },
        paymentTableIsCommonCenter = true,
        firstStatementHasNoSemicolonInSource = true,
        leftJoinsOnDebitAreAlive = true,
    });
}).RequireAuthorization();

app.MapGet("/api/cusdebits", async (AppDbContext db, ITenantContext t, string? q, string? status) =>
{
    var query = db.CusDebits.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(q)) query = query.Where(x => x.DebitNo.Contains(q!) || (x.CusName != null && x.CusName.Contains(q!)) || (x.RONo != null && x.RONo.Contains(q!)));
    if (!string.IsNullOrWhiteSpace(status)) query = query.Where(x => x.Status == status);
    var items = await query.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.DebitNo, x.CusId, x.CusName, x.RONo, x.DebitAmount, x.PaidAmount, balance = x.DebitAmount - x.PaidAmount, x.Status, x.Note,
        debitDate = x.DebitDate.HasValue ? x.DebitDate.Value.ToString("yyyy-MM-dd") : ""
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, totalDebit = items.Sum(i => i.DebitAmount), totalPaid = items.Sum(i => i.PaidAmount), totalBalance = items.Sum(i => i.balance), items });
}).RequireAuthorization();

// Tạo công nợ (theo RO/khách). DebitAmount > 0.
// ===== 🔴 #557 XOÁ CÔNG NỢ — **GUARD ĐỌC MỘT DB, THAO TÁC BA DB** =====
// Nguồn: `BizCarSv.Debit.cs:850 SerCusDebitDelete`. Endpoint: `POST /api/cusdebits/{id}/delete`.
//
// 🔴🔴 **GUARD KIỂM TRÊN `_dbDealer` NHƯNG XOÁ Ở CẢ BA DB**:
//     `this.CheckExistCusDebit(**_dbDealer**, …)`
//     rồi `_dbMain.ExecQuery(delete …)` · `_dbWH.ExecQuery(…)` · `_dbDealer.ExecQuery(…)` (nếu cần).
//   ⇒ Nếu DB **đại lý** chưa có bản ghi (mà Main/WH thì có — chuyện thường gặp khi ba DB lệch nhau),
//     hàm **báo "không tồn tại"** và **không xoá được gì**, dù dữ liệu vẫn nằm ở Main.
//   ⇒ Ngược lại, nếu chỉ Dealer có thì guard qua và ba lệnh xoá vẫn chạy (hai lệnh đầu xoá 0 dòng).
//   **Guard và thao tác không cùng phạm vi** — lớp lỗi mới, khác họ #530 (guard sai toán tử).
// 🔴 **KHÔNG kiểm phiếu thu trước khi xoá**: công nợ đã có `Ser_Payment` vẫn bị xoá ⇒ **phiếu thu mồ côi**
//   (cùng lớp #541/#549). Port **đếm và chặn** (lệch cố ý, có cờ) vì tiền đã thu là dữ liệu kế toán.
// ⚪ **Đối chứng lành thứ hai về tham số hoá** (sau #549): câu xoá dùng `@CusDebitID` + `@DealerCode`,
//   `ExecQuery` có truyền tham số ⇒ **không** bake (khác #536/#538/#540).
// ⚠️ Điều kiện xoá là **CẶP** `(CusDebitID, DealerCode)` — không phải riêng khoá chính ⇒ gọi đúng ID mà
//   sai `DealerCode` thì **xoá 0 dòng và KHÔNG báo lỗi** (nguồn không kiểm số dòng ảnh hưởng).
app.MapPost("/api/cusdebits/{id:long}/delete", async (long id, AppDbContext db, ITenantContext t,
    string? dealerCode, bool? force) =>
{
    // CheckExistCusDebit — nguồn đọc trên _dbDealer; MiniHTC một DB nên không tái hiện được sự lệch.
    var r = await db.CusDebits.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (r is null) return Results.NotFound(new { error = "CheckExistCusDebit: không tìm thấy công nợ.", id });

    // Nguồn xoá theo CẶP (ID, DealerCode) — sai DealerCode là xoá 0 dòng, im lặng.
    var dealerMismatch = !string.IsNullOrWhiteSpace(dealerCode) && r.DealerCode != dealerCode!.Trim();
    if (dealerMismatch)
        return Results.BadRequest(new
        {
            error = "DealerCode không khớp — nguồn sẽ xoá 0 dòng mà KHÔNG báo lỗi.",
            requested = dealerCode, actual = r.DealerCode,
            sourceDeletesZeroRowsSilently = true,
        });

    // LỆCH CỐ Ý: nguồn KHÔNG kiểm phiếu thu ⇒ mồ côi. Ở đây chặn, trừ khi force = true.
    var payCount = await db.CusDebitPayments.CountAsync(x => x.OrgId == t.OrgId && x.CusDebitId == id);
    if (payCount > 0 && force != true)
        return Results.BadRequest(new
        {
            error = "Công nợ đã có phiếu thu — xoá sẽ làm phiếu thu mồ côi.",
            paymentCount = payCount,
            sourceHasNoPaymentGuard = true,
            hint = "Gọi lại với force=true nếu thực sự muốn xoá đúng như nguồn.",
        });

    var removedPayments = 0;
    if (payCount > 0 && force == true)
    {
        // Nguồn KHÔNG xoá phiếu thu; ở đây cũng KHÔNG xoá — chỉ nêu rõ chúng thành mồ côi.
        removedPayments = 0;
    }
    db.CusDebits.Remove(r);
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        deletedId = id, r.DebitNo, r.DebitType, r.DealerCode,
        orphanedPayments = payCount, removedPayments,
        guardReadsDealerDbButDeletesThree = "CheckExistCusDebit(_dbDealer) roi xoa _dbMain + _dbWH + _dbDealer",
        sourceHasNoPaymentGuard = true,
        sourceDeleteIsParameterised = "@CusDebitID + @DealerCode",
        deleteKeyIsPair = "(CusDebitID, DealerCode)",
    });
}).RequireAuthorization();

// ===== 🔴 #556 TẠO / SỬA CÔNG NỢ — **CREATE BẮT BUỘC BA TRƯỜNG, UPDATE CHO XOÁ TRẮNG CHÚNG** =====
// Nguồn: `BizCarSv.Debit.cs:432 SerCusDebitCreate` · `:645 SerCusDebitUpdate`.
// Endpoint: `POST /api/cusdebits` (vá guard) + `POST /api/cusdebits/{id}/update` (mới).
//
// 📐 **DIFF CẶP CREATE/UPDATE** (luật #404) — khác nhau ở **guard** và ở **nghĩa của rỗng**:
//   · `Create`: `checkCusDebitFieldEmpty(strDealerCode, strDebitAmount, strDebitDate)` ⇒ **ba trường
//     BẮT BUỘC**. Khuôn ghi: `if (!IsEmpty) gán` (rỗng ⇒ **bỏ qua**, cột giữ mặc định).
//   · `Update`: **CHỈ** `CheckExistCusDebit(ID)` — **KHÔNG có `checkCusDebitFieldEmpty`**!
//     Khuôn ghi: `if (!IsEmpty) gán **else DBNull**` (rỗng ⇒ **XOÁ**).
//   🔴 ⇒ **Ba trường mà Create bắt buộc thì Update cho phép xoá trắng**: gửi `DebitDate` rỗng khi sửa là
//     công nợ **mất ngày**; `Note` cũng vậy. Lỗ hổng nằm ở **guard thiếu**, không ở câu ghi.
//     Port: **kiểm cả hai vế** (lệch cố ý, an toàn hơn) và nêu cờ `sourceUpdateSkipsFieldEmptyGuard`.
// ⚠️ `DebitDate` ở nhánh sửa còn bị chuẩn hoá `Convert.ToDateTime(x).ToString("yyyy-MM-dd **HH:mm**")`
//   ⇒ **mất giây**, và **chỉ ở nhánh sửa** — tạo mới ghi thẳng chuỗi người dùng gửi.
//   ⇒ Cùng một cột, hai độ chính xác tuỳ đường ghi.
// ⚠️ `DebitAmount` / `Note` ở nhánh **tạo** gán **thẳng, không guard rỗng** (chỉ có guard tổng ở
//   `checkCusDebitFieldEmpty`) — nên số tiền rỗng bị chặn ở guard chứ không ở câu gán.
// ⚠️ Cột `SupplierID` (không phải `SupplierCode`) mới là tên cột thật trên `Ser_CusDebit` ở hàm ghi —
//   trong khi câu ĐỌC của #555 select `d.SupplierCode`. **Hai tên cho một khái niệm**; MiniHTC dùng
//   `SupplierCode` (theo câu đọc) và nêu cờ.
app.MapPost("/api/cusdebits", async (CusDebitDto dto, AppDbContext db, ITenantContext t) =>
{
    // checkCusDebitFieldEmpty(DealerCode, DebitAmount, DebitDate) — BA trường bắt buộc của nguồn.
    if (string.IsNullOrWhiteSpace(dto.DealerCode))
        return Results.BadRequest(new { error = "checkCusDebitFieldEmpty: thiếu DealerCode." });
    if (dto.DebitAmount <= 0) return Results.BadRequest(new { error = "Số tiền công nợ phải lớn hơn 0." });
    if (dto.DebitDate is null)
        return Results.BadRequest(new { error = "checkCusDebitFieldEmpty: thiếu DebitDate." });

    var type = string.IsNullOrWhiteSpace(dto.DebitType) ? "1" : dto.DebitType!.Trim();
    if (type is not ("1" or "2" or "3"))
        return Results.BadRequest(new { error = "DebitType chỉ nhận 1 (khách), 2 (bảo hiểm), 3 (nhà cung cấp)." });

    var no = "CD" + DateTime.Now.ToString("yyMMddHHmmss");
    var r = new CusDebit
    {
        OrgId = t.OrgId, DebitNo = no, DebitType = type, DealerCode = dto.DealerCode!.Trim(),   // #557 §12
        CusId = dto.CusId, CusName = dto.CusName, RONo = dto.RONo,
        // Rỗng ⇒ BỎ QUA (đúng khuôn `if (!IsEmpty)` của nhánh TẠO).
        InsNo = string.IsNullOrWhiteSpace(dto.InsNo) ? null : dto.InsNo,
        SupplierCode = string.IsNullOrWhiteSpace(dto.SupplierCode) ? null : dto.SupplierCode,
        StockInID = string.IsNullOrWhiteSpace(dto.StockInID) ? null : dto.StockInID,
        DebitAmount = dto.DebitAmount, PaidAmount = 0,
        DebitDate = dto.DebitDate, Note = dto.Note, Status = "Open",
    };
    db.CusDebits.Add(r); await db.SaveChangesAsync();
    return Results.Ok(new
    {
        r.DebitNo, r.DebitType, r.DealerCode,
        requiredFields = new[] { "DealerCode", "DebitAmount", "DebitDate" },
        emptyMeansSkipOnCreate = true,
    });
}).RequireAuthorization();

app.MapPost("/api/cusdebits/{id:long}/update", async (long id, CusDebitDto dto,
    AppDbContext db, ITenantContext t) =>
{
    // CheckExistCusDebit(ID) — guard DUY NHẤT của nguồn ở nhánh sửa.
    var r = await db.CusDebits.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (r is null) return Results.NotFound(new { error = "CheckExistCusDebit: không tìm thấy công nợ.", id });

    // LỆCH CỐ Ý: nguồn KHÔNG kiểm ba trường bắt buộc ở nhánh sửa ⇒ cho xoá trắng. Ở đây kiểm.
    if (string.IsNullOrWhiteSpace(dto.DealerCode) || dto.DebitAmount <= 0 || dto.DebitDate is null)
        return Results.BadRequest(new
        {
            error = "checkCusDebitFieldEmpty (bo sung o nhanh SUA): can DealerCode, DebitAmount > 0, DebitDate.",
            sourceUpdateSkipsFieldEmptyGuard = true,
        });

    // Rỗng ⇒ DBNull (đúng khuôn nhánh SỬA — ngược nhánh TẠO).
    r.DealerCode = dto.DealerCode!.Trim();   // #557 §12 — nguồn ghi thẳng, không guard rỗng ở câu gán
    r.CusId = string.IsNullOrWhiteSpace(dto.CusId) ? null : dto.CusId;
    r.CusName = string.IsNullOrWhiteSpace(dto.CusName) ? null : dto.CusName;
    r.RONo = string.IsNullOrWhiteSpace(dto.RONo) ? null : dto.RONo;
    r.InsNo = string.IsNullOrWhiteSpace(dto.InsNo) ? null : dto.InsNo;
    r.SupplierCode = string.IsNullOrWhiteSpace(dto.SupplierCode) ? null : dto.SupplierCode;
    r.StockInID = string.IsNullOrWhiteSpace(dto.StockInID) ? null : dto.StockInID;
    r.DebitAmount = dto.DebitAmount;
    // Nguồn chuẩn hoá "yyyy-MM-dd HH:mm" ⇒ MẤT GIÂY, và chỉ ở nhánh sửa.
    r.DebitDate = new DateTime(dto.DebitDate!.Value.Year, dto.DebitDate.Value.Month, dto.DebitDate.Value.Day,
        dto.DebitDate.Value.Hour, dto.DebitDate.Value.Minute, 0);
    r.Note = string.IsNullOrWhiteSpace(dto.Note) ? null : dto.Note;
    if (!string.IsNullOrWhiteSpace(dto.DebitType)) r.DebitType = dto.DebitType!.Trim();
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        r.Id, r.DebitNo, r.DebitType, r.DealerCode, r.DebitAmount, r.DebitDate, r.Status,
        emptyMeansClearOnUpdate = true,
        contrastWithCreate = "nhanh TAO: rong = BO QUA; nhanh SUA: rong = XOA",
        sourceUpdateSkipsFieldEmptyGuard = "nguon chi co CheckExistCusDebit(ID)",
        debitDateLosesSecondsOnUpdateOnly = "Convert.ToDateTime(x).ToString(\"yyyy-MM-dd HH:mm\")",
        supplierColumnNameDiffersBetweenReadAndWrite = "ghi: SupplierID / doc: SupplierCode",
    });
}).RequireAuthorization();

app.MapGet("/api/cusdebits/{no}/payments", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.CusDebits.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DebitNo == no);
    if (h is null) return Results.NotFound(new { no });
    var pays = await db.CusDebitPayments.Where(p => p.OrgId == t.OrgId && p.CusDebitId == h.Id).OrderBy(p => p.Id)
        .Select(p => new { p.PaymentAmount, p.Note, p.PaymentNo, p.DealerCode, p.PayPersonName, p.PayPersonIDCardNo, payDate = p.PayDate.HasValue ? p.PayDate.Value.ToString("yyyy-MM-dd") : "" }).ToListAsync();
    return Results.Ok(new { h.DebitNo, h.DebitAmount, h.PaidAmount, balance = h.DebitAmount - h.PaidAmount, h.Status, count = pays.Count, payments = pays });
}).RequireAuthorization();

// Thu tiền công nợ (không vượt số dư; đủ tiền -> Paid).
app.MapPost("/api/cusdebits/{no}/payments", async (string no, CusDebitPaymentDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.CusDebits.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DebitNo == no);
    if (h is null) return Results.NotFound(new { no });
    if (dto.PaymentAmount <= 0) return Results.BadRequest(new { error = "Số tiền thu phải lớn hơn 0." });
    // Guard của nguồn (checkPaymentFieldEmpty): đại lý + người nộp + CMND/CCCD + ngày thu đều BẮT BUỘC.
    // ⚠️ CusID KHÔNG bắt buộc — nguồn đã COMMENT dòng truyền strCusID vào hàm check (luật "port dòng active").
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Chưa nhập mã đại lý." });
    if (string.IsNullOrWhiteSpace(dto.PayPersonName)) return Results.BadRequest(new { error = "Chưa nhập tên người nộp tiền." });
    if (string.IsNullOrWhiteSpace(dto.PayPersonIDCardNo)) return Results.BadRequest(new { error = "Chưa nhập số CMND/CCCD người nộp tiền." });
    if (dto.PayDate is null) return Results.BadRequest(new { error = "Chưa nhập ngày thu tiền." });
    var balance = h.DebitAmount - h.PaidAmount;
    if (dto.PaymentAmount > balance) return Results.BadRequest(new { error = $"Số tiền thu vượt số dư công nợ ({balance})." });
    db.CusDebitPayments.Add(new CusDebitPayment { OrgId = t.OrgId, CusDebitId = h.Id, PaymentAmount = dto.PaymentAmount, PayDate = dto.PayDate ?? DateTime.Now, Note = dto.Note,
        PaymentNo = "PM" + DateTime.Now.ToString("yyMMddHHmmss"), DealerCode = dto.DealerCode, PayPersonName = dto.PayPersonName, PayPersonIDCardNo = dto.PayPersonIDCardNo });
    h.PaidAmount += dto.PaymentAmount;
    if (h.PaidAmount >= h.DebitAmount) h.Status = "Paid";
    await db.SaveChangesAsync();
    return Results.Ok(new { h.DebitNo, paidAmount = h.PaidAmount, balance = h.DebitAmount - h.PaidAmount, status = h.Status });
}).RequireAuthorization();

// ===== Đề nghị bảo hành dịch vụ (ServiceWarrantyClaim — port 1:1 FrmWarrantyReportDealerSearch/HTCSearch/HTCApproved, TCMotor) =====
// ===== 🔴 #302 NHÃN TRẠNG THÁI PHIẾU ĐỀ NGHỊ BẢO HÀNH — nguồn LIVE `WarrantyReport.cs:13503` =====
//   `SENT` Chờ xem xét · `PEND` Chưa gửi · `CONF` Chờ duyệt · `ACCE` Chấp thuận B.H · `REJ` Không duyệt
//   `REVERT` HTC Hoàn trả.  **KHÔNG có nhánh `else`** ⇒ mã lạ cho ra nhãn NULL (ô trống), không gộp.
//   ⚠️ `PEND` nghĩa là **"Chưa gửi"**, KHÔNG phải "đang chờ xử lý" — dễ dịch ngược nghĩa.
// ===== 🔴 #394 HAI BỘ NHÃN cho CÙNG SÁU trạng thái bảo hành (`FrmWarrantyReportHTCApproved`) =====
// Màn duyệt BCBH của HTC là một **hộp thoại**: nó KHÔNG gọi service nào, chỉ dựng bảng trạng thái
// rồi trả về form cha qua `frmWarrantyReportHTCSeach.UpdateRowStatus(...)` — nên phần port được
// của nó là **BẢNG MÃ + luật nhập liệu**, không phải một endpoint ghi.
//
// 🔴 Hằng trong `Constants.cs:294` là **NHÃN TIẾNG VIỆT**, không phải mã. Và có **TÁM** hằng cho
//   **SÁU** trạng thái, vì hai trạng thái có **hai cách gọi khác nhau**:
//     `VAULE_WARR_REJECT`     = *"Không chấp nhận B.H"*   ⟷ `VAULE_WARR_REJECTBiz` = *"Không duyệt"*
//     `VAULE_WARR_REVERT`     = *"HTC hoàn trả Đại lý"*   ⟷ `VAULE_WARR_REVERTBiz` = *"HTC Hoàn trả"*
//   ⇒ Bản đồ cũ của MiniHTC dùng nhãn **Biz** cho cả hai, nên **màn duyệt hiển thị sai chữ** so với
//     nguồn. Không chọn một bên: giữ **CẢ HAI**, tách theo màn (cùng mẫu `…ByScreen` của #264).
// ⚠️ Trong chính hộp thoại này, phần lớn guard nhập liệu **đã bị comment** — chỉ còn **một** guard sống
//   (bắt buộc chọn dòng trước khi duyệt, `:904`). Đừng port các dòng đã comment.
var warrantyClaimStatusNamesByScreen = new Dictionary<string, Dictionary<string, string>>
{
    // Bộ nhãn NGHIỆP VỤ (mặc định) — dùng ở danh sách/báo cáo.
    ["biz"] = new()
    {
        ["Sent"] = "Chờ xem xét", ["Pending"] = "Chưa gửi", ["Confirmed"] = "Chờ duyệt",
        ["Accepted"] = "Chấp thuận B.H", ["Rejected"] = "Không duyệt", ["Reverted"] = "HTC Hoàn trả",
    },
    // Bộ nhãn của MÀN DUYỆT (hộp thoại HTC) — hai ô cuối khác chữ.
    ["approve"] = new()
    {
        ["Sent"] = "Chờ xem xét", ["Pending"] = "Chưa gửi", ["Confirmed"] = "Chờ duyệt",
        ["Accepted"] = "Chấp thuận B.H",
        ["Rejected"] = "Không chấp nhận B.H",
        ["Reverted"] = "HTC hoàn trả Đại lý",
    },
};
var warrantyClaimStatusNames = warrantyClaimStatusNamesByScreen["biz"];

// ===== 🔴 #302 CHI TIẾT PHIẾU ĐỀ NGHỊ BẢO HÀNH — LUẬT ĐỌC của bản LIVE =====
// TRACE TWIN: `Ser_ROWarrantyReport` có **BỐN** bản Get (`_GetOld` :12318 · bản trần :12605 ·
//   `_New20230220` :12973 · `_New20230417` :13388). WS `WSCarSv.asmx.cs:19855` gọi **`_New20230417`**
//   ⇒ ba bản kia CHẾT.
//
// 🔴 BẢN LIVE ĐÃ ĐỔI LUẬT ĐỌC — điểm dễ port sai nhất ở màn này:
//   Bản `_New20230220` (CHẾT) đọc thông tin xe qua `isnull(td.X, car.X)` — bản chụp của PHIẾU, dự phòng
//   là XE. Bản LIVE **bỏ hết chuỗi isnull đó** và lấy thẳng `ro.FrameNo` / `ro.PlateNo` / `ro.BatteryNo` /
//   `ro.SerialNo` / `ro.WarrantyRegistrationDate` / `ro.WarrantyExpiresDate` — tức **lấy BẢN CHỤP CỦA LỆNH
//   SỬA CHỮA**, không phải của phiếu, cũng không phải của master xe.
//   ⇒ Đi theo bản chụp của phiếu (như sweep gợi ý) là port đúng bản CHẾT. Nguồn sự thật = `ro`.
//   Cột duy nhất còn lấy từ master xe: `car.CusConfirmedWarrantyDate`.
//
// ⚠️ `WarrantyRegistrationDate` nguồn `convert(nvarchar, …, 23)` ⇒ trả **CHUỖI yyyy-MM-dd**, trong khi
//   `WarrantyExpiresDate` để nguyên datetime. Bất đối xứng có thật, giữ đúng.
//
// ⚠️ QUYẾT ĐỊNH NGHIỆP VỤ CÓ GHI LÝ DO (nên BẮT CHƯỚC, theo lệ #275): nguồn **cố ý bỏ** điều kiện
//   `and td.cusID = car.CusID` kèm chú thích *"2022-05-23. Confirm vs Ms.Đông KH ko bắt buộc phải giống
//   nhau"* ⇒ khách trên phiếu bảo hành **KHÔNG bắt buộc** là chủ xe. Ghép xe **CHỈ theo `CarID`**.
// ===== 🔴 #369 GUARD DUYỆT BCBH theo "lần thay PHỤ TÙNG CHÍNH gần nhất" =====
// Nguồn: `BizCarSv.WarrantyReport.cs` — `ROWarrantyReport_Approve_Check_CreatedDate_OtherROActualDeliveryDate`
//   (7120) và biến thể `…DeliveryDate2` (7276). Bản ở 7015 là **khối comment ⇒ luật ĐÃ CHẾT** (lệ #305).
//
// 🔴 HAI BIẾN THỂ ĐỀU LIVE, và điều kiện **NGƯỢC CHIỀU NHAU** — chọn theo loại BCBH:
//   • `XM`/`W` (5839) và `SB`/`W` (6019) → bản **2**: từ chối khi phụ tùng chính được thay
//     **TRONG VÒNG 6 tháng** VÀ xe mới chạy **DƯỚI 10.000 km**. Ý nghĩa: lần thay trước còn
//     trong hạn bảo hành của chính nó, không cho khai lại.
//   • `PT`/`S` (6065) → bản **1**: từ chối khi phụ tùng chính được thay **QUÁ 6 tháng** hoặc xe đã
//     chạy **TRÊN 10.000 km**. Ý nghĩa: bảo hành PHỤ TÙNG chỉ còn hiệu lực trong hạn đó.
//   ⇒ Đây **không phải mâu thuẫn**: hai chế độ bảo hành khác nhau trên cùng một mốc 6 tháng /
//     10.000 km. **Port chung một luật cho cả hai là sai đúng một nửa số hồ sơ.**
//
// 🔴 NHÁNH CHẾT trong bản 2 (giữ 1:1 nhưng phải biết): nguồn viết
//   `if (kmDiff < 10000 && trong6Thang) { if (trong6Thang) {…throw…} if (kmDiff < 10000) {…throw…} }`
//   ⇒ `if` trong cùng LUÔN đúng nên luôn ném trước; lỗi *"Xe chạy chưa được 10.000 KM…"* của nhánh
//     thứ hai **KHÔNG BAO GIỜ hiện ra được**. Người dùng chỉ thấy lý do 6 tháng.
//
// ⚠️ Truy vấn tìm RO gần nhất chạy trên **DB Main** và **KHÔNG lọc đại lý** — cố ý: *"Check theo VIN
//   không phân biệt đại lý"*. Lọc thêm đại lý sẽ bỏ sót lần thay ở đại lý khác.
// ⚠️ Nó là `select top 1 … order by sr.ActualDeliveryDate desc` — **có** `order by`, nên KHÔNG thuộc
//   nhóm "top 1 không tất định"; cột `order` nằm trong danh sách select, chỉ không đứng đầu.
// 📌 Đối chiếu 2 máy: md5 CẢ FILE **khác nhau** (laptop `ba1fb715` / 150 `19b741ca`) nhưng md5 **vùng
//   7120-7440** giống hệt (`42a367f1`) ⇒ khác biệt nằm ngoài guard, port an toàn.
app.MapPost("/api/warrantyclaims/{id:long}/approve-check", async (long id, AppDbContext db, ITenantContext t) =>
{
    var c = await db.ServiceWarrantyClaims.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (c is null) return Results.NotFound(new { id });

    var violations = new List<object>();
    void Deny(string code, string desc, object? ctx = null) => violations.Add(new { code, desc, ctx });

    if (string.IsNullOrWhiteSpace(c.Km)) Deny("InvalidKM", "Số Km của BCBH trống!");

    // Phụ tùng CHÍNH của hồ sơ (PTC) — nguồn lọc đúng loại này, không phải mọi dòng phụ tùng.
    var ptcCodes = await db.WarrantyClaimPartItems
        .Where(x => x.OrgId == t.OrgId && x.ClaimId == id && x.RowPartType == "PTC")
        .Select(x => x.PartCode).Distinct().ToListAsync();

    // RO gần nhất (theo NGÀY GIAO XE) của cùng VIN có chứa một trong các PTC đó.
    // KHÔNG lọc đại lý — chủ ý của nguồn. Bỏ RO hiện tại và các RO đã từ chối.
    var roQ =
        from ro in db.RepairOrders
        join pi in db.RoPartItems on ro.Id equals pi.RoId
        where ro.OrgId == t.OrgId && pi.OrgId == t.OrgId
              && ro.Vin == c.Vin && ptcCodes.Contains(pi.PartCode)
              && ro.ActualDeliveryDate != null && ro.Status != "Rejected"
              && (c.ROID == null || ro.RONo != c.ROID)
        orderby ro.ActualDeliveryDate descending
        select new { ro.RONo, ro.Km, ro.ActualDeliveryDate };
    var other = ptcCodes.Count == 0 ? null : await roQ.FirstOrDefaultAsync();

    var isPartWarranty = c.ROWTypeCode == "PT" && c.ROWTypeDtlCode == "S";
    var rule = isPartWarranty ? "PT/S — bảo hành PHỤ TÙNG (bản 1)" : "XM|SB + W — bảo hành thường (bản 2)";

    if (other is null)
    {
        Deny("InvalidPTC", "Phụ tùng chính của BCBH không được sửa chữa gần đây!");
    }
    else
    {
        var replacedAt = other.ActualDeliveryDate!.Value;
        var submittedAt = c.CreatedAt;
        var within6Months = replacedAt.AddMonths(6) > submittedAt;
        decimal.TryParse(c.Km, out var kmNow);
        decimal.TryParse(other.Km, out var kmThen);
        var kmDiff = kmNow - kmThen;
        var ctx = new { otherRONo = other.RONo, otherKm = other.Km, replacedAt, kmDiff };

        if (string.IsNullOrWhiteSpace(other.Km))
            Deny("InvalidOtherKM", "Số KM của báo giá có phụ tùng chính gần nhất trống!", ctx);

        if (isPartWarranty)
        {
            // BẢN 1 — hết hạn thì từ chối.
            if (!within6Months)
                Deny("InvalidCreatedDate_OtherROActualDeliveryDate",
                     "Phụ tùng chính đã được thay thế hơn 6 tháng trước!", ctx);
            if (kmDiff > 10000m)
                Deny("InvalidKM", "Xe đã chạy được hơn 10,000 KM từ khi Phụ tùng chính đã được thay thế!", ctx);
        }
        else
        {
            // BẢN 2 — CÒN trong hạn của lần thay trước thì từ chối. Điều kiện là phép VÀ.
            if (!string.IsNullOrWhiteSpace(other.Km) && kmThen > kmNow)
                Deny("InvalidOtherKM", "Số KM của báo giá có phụ tùng chính gần nhất lớn hơn số KM của BCBH!", ctx);

            if (kmDiff < 10000m && within6Months)
            {
                // Nguồn còn một nhánh KM ngay sau đây nhưng KHÔNG BAO GIỜ tới được (xem chú thích trên).
                Deny("InvalidCreatedDate_OtherROActualDeliveryDate",
                     "Phụ tùng chính đã được thay thế trong 6 tháng gần đây!", ctx);
            }
        }
    }

    return Results.Ok(new
    {
        claimId = id, c.ClaimNo, c.ROWTypeCode, c.ROWTypeDtlCode,
        ruleApplied = rule,
        canApprove = violations.Count == 0,
        violations,
        ptcPartCodes = ptcCodes,
        ruleClassified = c.ROWTypeCode != null && c.ROWTypeDtlCode != null,
        ruleNote = "Hai luật NGƯỢC CHIỀU: PT/S từ chối khi ĐÃ QUÁ 6 tháng; XM|SB+W từ chối khi CÒN TRONG 6 tháng.",
        deadBranchNote = "Bản 2 của nguồn có nhánh lỗi KM không bao giờ chạy tới (if lồng luôn đúng) — "
            + "người dùng chỉ nhận được lý do 6 tháng.",
        dealerScopeNote = "Tìm RO gần nhất theo VIN trên toàn hệ, KHÔNG lọc đại lý — chủ ý của nguồn.",
    });
}).RequireAuthorization();

app.MapGet("/api/warrantyclaims/{id:long}/detail", async (long id, AppDbContext db, ITenantContext t) =>
{
    var c = await db.ServiceWarrantyClaims.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (c is null) return Results.NotFound(new { id });

    // Lệnh sửa chữa — nguồn INNER JOIN theo `td.ROID = ro.ROID`; MiniHTC chưa có ROID trên mọi bản ghi cũ
    //   nên tra theo ROID trước, thiếu thì theo số lệnh (khai rõ, không im lặng).
    var ro = c.ROID is not null
        ? await db.RepairOrders.FirstOrDefaultAsync(r => r.OrgId == t.OrgId && r.Id.ToString() == c.ROID)
        : null;
    ro ??= c.RONo is not null
        ? await db.RepairOrders.FirstOrDefaultAsync(r => r.OrgId == t.OrgId && r.RONo == c.RONo)
        : null;

    // Xe: ghép CHỈ theo CarID (xem quyết định nghiệp vụ 2022-05-23 ở trên).
    var car = c.CarID is not null
        ? await db.ServiceCars.FirstOrDefaultAsync(v => v.OrgId == t.OrgId && v.FrameNo == c.CarID)
        : null;
    var cus = c.CusID is not null
        ? await db.ServiceCustomers.FirstOrDefaultAsync(u => u.OrgId == t.OrgId && u.CusCode == c.CusID)
        : null;

    return Results.Ok(new
    {
        c.Id, c.ClaimNo, c.ROWNo, c.DealerCode, c.RONo, c.ROID, c.CusID, c.CarID,
        c.Creator, c.Assistant, c.CreatedBy, c.ApprovedBy, c.ApprovedDate,
        c.Km, c.CheckInDate, c.FinishedDate, c.CusRequest, c.CarStatus, c.StartDate,
        c.NaturalCode, c.CauseCode, c.ErrorCodeCD, c.ErrorCodePN, c.PartIDError, c.FlagReadySend,
        c.ROWTID, c.WarrantyType, c.WarrantySerCode, c.Amount, c.Description, c.HtcNote,
        c.Status,
        warrantyStatusText = warrantyClaimStatusNames.TryGetValue(c.Status, out var sn) ? sn : null,
        c.HMCApiStatus, c.SyncHMCDateTime, c.ClmRcptNo, c.HMCApiQtyA, c.ClmNoSrl,

        // --- thông tin XE lấy TỪ LỆNH SỬA CHỮA (đúng bản LIVE), KHÔNG từ master xe ---
        frameNo = ro?.Vin,
        plateNo = ro?.LicensePlate,
        batteryNo = ro?.BatteryNo,
        serialNo = ro?.SerialNo,
        // nguồn convert sang chuỗi yyyy-MM-dd; cột hết hạn để nguyên datetime
        warrantyRegistrationDate = ro?.WarrantyRegistrationDate?.ToString("yyyy-MM-dd"),
        warrantyExpiresDate = ro?.WarrantyExpiresDate,
        roCreator = ro?.Creator,

        // 🔴 #322 BẢN CHỤP TRÊN CHÍNH PHIẾU — ghi bởi `_Update_V2` nhưng hàm Get LIVE KHÔNG đọc.
        //   Trả kèm để lộ nghịch lý: nếu lệch với khối lấy từ LỆNH ở trên thì dữ liệu hai nơi đã rời nhau.
        claimSnapshot = new
        {
            c.CusName, c.CusAddress, c.CusTel, c.ModelID, c.BatteryNo, c.SerialNo,
            c.WarrantyRegistrationDate, c.WarrantyExpiresDate, c.WarrantyKM, c.Note,
        },
        snapshotDiffersFromRo = (c.BatteryNo ?? "") != (ro?.BatteryNo ?? "")
                             || (c.SerialNo ?? "") != (ro?.SerialNo ?? ""),

        // --- cột DUY NHẤT còn lấy từ master xe ---
        cusConfirmedWarrantyDate = car?.WarrantyDate,
        ownerName = cus?.CusName,

        roResolvedBy = c.ROID is not null ? "ROID" : (c.RONo is not null ? "RONo (xấp xỉ)" : null),
        note = "Thông tin xe lấy từ LỆNH SỬA CHỮA theo bản LIVE _New20230417; bản _New20230220 (đọc từ phiếu/master) đã CHẾT.",
    });
}).RequireAuthorization();

// ===== 🔴 #466 `Ser_ROWarrantyReportGetByROID` — TRA ĐỀ NGHỊ BẢO HÀNH THEO LỆNH =====
// TRACE 4 TẦNG: `FrmQuotation` → `SerROWarrantyReportSerivce.Ser_ROWarrantyReportGetByROID` (`:160`)
//   → WS `Ser_ROWarrantyReport_Get` (tên KHÁC tên hàm client) → biz **`…_Get_New20230417`**
//   (`BizCarSv.WarrantyReport.cs:13388`; bản kho: `…_Get_WH_New20230417`).
// ⚠️ Tầng service **đóng cứng 6 ô điều kiện thành `""`** và chỉ truyền ba thứ: `"=" + strROWID`,
//   `"=" + strROID`, `"=" + SystemGlobal.strDealerCode` (đại lý ĐANG đăng nhập, không cho chọn),
//   cộng `strIsGetDetail`. ⇒ Lối vào này **luôn bị giới hạn trong đại lý của người dùng**.
//
// 🔴🔴 **HAI MÀN CÙNG DỮ LIỆU NHƯNG NỐI XE KHÁC NHAU** — mâu thuẫn thật giữa hai nguồn:
//   · #460 `Ser_RO_GetWarranty_V2_New20230417`: `inner join ser_car on ro.CarID=car.CarID`
//     **`and ro.cusid = car.cusid`** (ĐANG CHẠY) ⇒ xe sang tên ⇒ **mất dòng**.
//   · #466 `Ser_ROWarrantyReport_Get_New20230417`: cùng phép nối nhưng vế thứ hai **ĐÃ BỊ COMMENT**,
//     kèm lý do ghi thẳng trong nguồn: `--and td.cusID=car.CusID // 2022-05-23. Confirm vs Ms.Đông`
//     `KH ko bắt buộc phải giống nhau` ⇒ ở đây xe sang tên **VẪN ra dòng**.
//   ⇒ Cùng một câu hỏi nghiệp vụ, hai màn trả **hai kết quả khác nhau**. Người ta đã sửa MỘT chỗ
//     (2022-05-23) mà quên chỗ kia. Port giữ đúng từng bên và **nêu tên mâu thuẫn** để nghiệp vụ chốt.
//     Cờ `carOwnerJoinInconsistentAcrossScreens`.
// 🔴 Bảng lọc đầu tiên `left join Ser_MST_ROWarrantyType` nhưng WHERE có `zzzz…ROWTypeCodeConditionList`
//   **đặt trên bảng LEFT** ⇒ LEFT **chết KHI VÀ CHỈ KHI** người gọi truyền bộ lọc đó (luật #414).
//   Lối `…GetByROID` truyền `""` ⇒ LEFT còn sống; lối `Ser_ROWarrantyReportHTC_Get` truyền mã ⇒ LEFT chết.
//   📌 "LEFT chết" **không phải thuộc tính của câu SQL**, mà của **từng người gọi**. Cờ `leftJoinDiesWhenRowTypeFiltered`.
// ⚠️ Bảng kết quả thứ hai còn **ba `inner join`** (Ser_RO · Ser_Customer · ser_car) ⇒ vẫn mất dòng nếu
//   thiếu khách hoặc thiếu xe. Đếm và trả `droppedByRequiredMaster`.
// ⚠️ Cùng bảng dịch 6 mã trạng thái, **không có ELSE** ⇒ mã lạ ra **null** (đã có ở endpoint này).
// ===== 🔴 #470 NHÁNH KHO `Ser_ROWarrantyReport_Get_WH` LỌC **SAI CỘT** so với bản chính =====
// DIFF hai nhánh (`_audit/diffwh.js`, 77 vs 50 dòng SQL) — khác biệt cốt lõi nằm ở **cột được lọc**:
//   · bản chính `_New20230417`: `BuildClause("and", "**ro**.FrameNo", …)` · `"**ro**.PlateNo"`
//     ⇒ lọc theo **ẢNH CHỤP trên lệnh sửa chữa** (đúng tinh thần đợt sửa 2023-04-17, xem #460).
//   · bản kho `_WH`:            `BuildClause("and", "**car**.FrameNo", …)` · `"**car**.PlateNo"`
//     ⇒ lọc theo **DANH MỤC XE HIỆN TẠI**.
//   ⇒ Xe **đổi biển số** sau khi sửa: tra ở màn chính phải gõ biển **lúc sửa**, tra ở màn kho phải gõ biển
//     **hiện tại** — cùng một câu hỏi, hai đáp án. Đây đúng là loại lỗi "**LỌC SAI CỘT**" mà §12 không bắt.
// 🔴 Bản kho còn **THIẾU HẲN**: bảng lọc trung gian `#Ser_ROWarrantyReportFilter` · hai bộ lọc
//   `ROWTypeCode`/`ROWTID` (nên **không lọc được theo loại đề nghị bảo hành**) · `left join Ser_MST_Part`
//   (nên **không có tên phụ tùng lỗi**) · `order by rt.ROWRTransactionID` · ba `left join` dịch vụ/phụ tùng/
//   `Btl_Bulletin`. ⇒ Khớp đúng hình dạng "nhánh kho tụt hậu" mà #468 đo được trên toàn cây.
// ⇒ Port cho tham số `scope` chọn **cột lọc**, mặc định `main` (ảnh chụp). Không tự hợp nhất hai bên.
app.MapGet("/api/warrantyclaims", async (AppDbContext db, ITenantContext t, string? status, string? plate,
    string? vin, string? dealer, string? roId, string? rowId, string? isGetDetail, string? scope) =>
{
    var useMasterCar = string.Equals(scope?.Trim(), "wh", StringComparison.OrdinalIgnoreCase);
    var q = db.ServiceWarrantyClaims.Where(x => x.OrgId == t.OrgId);
    // #466: hai bộ lọc chính của lối vào theo lệnh sửa chữa (nguồn so BẰNG, không LIKE).
    if (!string.IsNullOrWhiteSpace(roId)) q = q.Where(x => x.ROID == roId!.Trim());
    if (!string.IsNullOrWhiteSpace(rowId)) q = q.Where(x => x.ROWNo == rowId!.Trim());
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(x => x.Status == status);
    // #470: nhánh kho lọc trên DANH MỤC XE, nhánh chính lọc trên ẢNH CHỤP của lệnh.
    if (useMasterCar)
    {
        if (!string.IsNullOrWhiteSpace(plate))
        {
            var carIdsByPlate = await db.ServiceCars.Where(c => c.OrgId == t.OrgId
                && c.PlateNo != null && c.PlateNo.Contains(plate!) && c.CarID != null)
                .Select(c => c.CarID!).ToListAsync();
            q = q.Where(x => x.CarID != null && carIdsByPlate.Contains(x.CarID));
        }
        if (!string.IsNullOrWhiteSpace(vin))
        {
            var carIdsByVin = await db.ServiceCars.Where(c => c.OrgId == t.OrgId
                && c.FrameNo.Contains(vin!) && c.CarID != null)
                .Select(c => c.CarID!).ToListAsync();
            q = q.Where(x => x.CarID != null && carIdsByVin.Contains(x.CarID));
        }
    }
    else
    {
        if (!string.IsNullOrWhiteSpace(plate)) q = q.Where(x => x.PlateNo != null && x.PlateNo.Contains(plate!));
        if (!string.IsNullOrWhiteSpace(vin)) q = q.Where(x => x.Vin != null && x.Vin.Contains(vin!));
    }
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(x => x.DealerCode == dealer);
    var items = await q.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.Id, x.ClaimNo, x.DealerCode, x.RONo, x.Vin, x.PlateNo, x.WarrantyType, x.PartCode, x.Description, x.Amount, x.Status, x.HMCApiStatus, x.SyncHMCDateTime, x.ClmRcptNo, x.HMCApiQtyA, x.ClmNoSrl, x.HtcNote, x.WarrantySerCode, x.ApprovedDate,
        // #302 §12: cột mới có mặt ở CẢ GET lẫn POST
        x.ROWNo, x.ROID, x.CusID, x.CarID, x.Creator, x.Assistant, x.Km, x.CheckInDate, x.FinishedDate,
        // #369 §12: hai ma phan loai quyet dinh AP LUAT DUYET NAO
        x.ROWTypeCode, x.ROWTypeDtlCode,
        // #322 §12: bản chụp khách + xe (ghi bởi _Update_V2)
        x.CusName, x.CusAddress, x.CusTel, x.ModelID, x.BatteryNo, x.SerialNo,
        x.WarrantyRegistrationDate, x.WarrantyExpiresDate, x.WarrantyKM, x.Note,
        x.CusRequest, x.CarStatus, x.NaturalCode, x.CauseCode, x.StartDate, x.ROWTID,
        x.ErrorCodeCD, x.ErrorCodePN, x.FlagReadySend, x.PartIDError, x.ApprovedBy, x.CreatedBy
    }).ToListAsync();
    var withLabel = items.Select(i => new
    {
        i.Id, i.ClaimNo, i.DealerCode, i.RONo, i.Vin, i.PlateNo, i.WarrantyType, i.PartCode,
        i.Description, i.Amount, i.Status,
        warrantyStatusText = warrantyClaimStatusNames.TryGetValue(i.Status, out var wn) ? wn : null,
        i.HMCApiStatus, i.SyncHMCDateTime, i.ClmRcptNo, i.HMCApiQtyA, i.ClmNoSrl, i.HtcNote,
        i.WarrantySerCode, i.ApprovedDate,
        i.ROWNo, i.ROID, i.CusID, i.CarID, i.Creator, i.Assistant, i.Km, i.CheckInDate, i.FinishedDate,
        i.CusRequest, i.CarStatus, i.NaturalCode, i.CauseCode, i.StartDate, i.ROWTID,
        i.ErrorCodeCD, i.ErrorCodePN, i.FlagReadySend, i.PartIDError, i.ApprovedBy, i.CreatedBy,
    }).ToList();
    // #466: ba bảng bắt buộc của nguồn (Ser_RO · Ser_Customer · ser_car) — đếm dòng bị nuốt.
    var roNos = await db.RepairOrders.Where(x => x.OrgId == t.OrgId).Select(x => x.RONo).ToListAsync();
    var cusCodes = await db.ServiceCustomers.Where(x => x.OrgId == t.OrgId).Select(x => x.CusCode).ToListAsync();
    var carIds = await db.ServiceCars.Where(x => x.OrgId == t.OrgId && x.CarID != null)
        .Select(x => x.CarID!).ToListAsync();
    var droppedByRequiredMaster = items.Count(i =>
        (i.RONo != null && !roNos.Contains(i.RONo))
        || (i.CusID != null && !cusCodes.Contains(i.CusID))
        || (i.CarID != null && !carIds.Contains(i.CarID)));

    return Results.Ok(new { count = items.Count, totalAmount = items.Sum(i => i.Amount),
        // ===== #466 =====
        droppedByRequiredMaster,
        isGetDetail = isGetDetail,
        dealerScopeForcedInSource = true,
        leftJoinDiesWhenRowTypeFiltered = true,
        // ===== #470 =====
        scope = useMasterCar ? "wh" : "main",
        filterColumnDiffersByScope = true,
        filterColumnNote = "scope=main lọc PlateNo/Vin ẢNH CHỤP trên lệnh (ro.*); scope=wh lọc theo DANH "
            + "MỤC XE hiện tại (car.*) — đúng nguồn Ser_ROWarrantyReport_Get_WH. Xe đổi biển số thì hai "
            + "phạm vi cho kết quả khác nhau.",
        whBranchMissing = new[] { "loc ROWTypeCode", "loc ROWTID", "ten phu tung loi (Ser_MST_Part)",
            "order by ROWRTransactionID", "left join dich vu/phu tung/Btl_Bulletin" },
        carOwnerJoinInconsistentAcrossScreens = true,
        carOwnerJoinNote = "Ser_ROWarrantyReport_Get_New20230417 ĐÃ BỎ vế `td.cusID = car.CusID` "
            + "(comment 2022-05-23: khách không bắt buộc phải giống nhau), nhưng Ser_RO_GetWarranty_V2"
            + "_New20230417 (#460) VẪN GIỮ vế đó ⇒ hai màn cho kết quả khác nhau khi xe đã sang tên.",
        pending = items.Count(i => i.Status == "Pending"), sent = items.Count(i => i.Status == "Sent"),
        accepted = items.Count(i => i.Status == "Accepted"), rejected = items.Count(i => i.Status == "Rejected"),
        confirmed = items.Count(i => i.Status == "Confirmed"), reverted = items.Count(i => i.Status == "Reverted"),
        items = withLabel });
}).RequireAuthorization();

// Đại lý tạo đề nghị bảo hành (theo RO). Amount >= 0; cần VIN hoặc biển số.
app.MapPost("/api/warrantyclaims", async (WarrantyClaimDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.Vin) && string.IsNullOrWhiteSpace(dto.PlateNo))
        return Results.BadRequest(new { error = "Cần số khung (VIN) hoặc biển số." });
    if (dto.Amount < 0) return Results.BadRequest(new { error = "Số tiền bảo hành không được âm." });
    var no = "WC" + DateTime.Now.ToString("yyMMddHHmmss");
    var c = new ServiceWarrantyClaim { OrgId = t.OrgId, ClaimNo = no, DealerCode = dto.DealerCode, RONo = dto.RONo,
        ROWTypeCode = dto.ROWTypeCode, ROWTypeDtlCode = dto.ROWTypeDtlCode,   // #369 §12
        Vin = dto.Vin, PlateNo = dto.PlateNo, WarrantyType = dto.WarrantyType, PartCode = dto.PartCode, Description = dto.Description,
        Amount = dto.Amount, Status = "Pending", WarrantySerCode = dto.WarrantySerCode,
        // #302 §12 POST: 20 cột thật của `Ser_ROWarrantyReport` phải GÁN được, không chỉ ĐỌC được.
        //   `ROWNo` rỗng thì lấy chính `ClaimNo` — nguồn sinh số phiếu riêng, MiniHTC dùng một số.
        //   `Creator`/`CreatedBy`: nguồn có CẢ HAI cột và ghi cùng người lúc tạo.
        ROWNo = string.IsNullOrWhiteSpace(dto.ROWNo) ? no : dto.ROWNo,
        ROID = dto.ROID, CusID = dto.CusID, CarID = dto.CarID,
        Creator = dto.Creator, CreatedBy = dto.CreatedBy ?? dto.Creator, Assistant = dto.Assistant,
        Km = dto.Km, CheckInDate = dto.CheckInDate, FinishedDate = dto.FinishedDate,
        CusRequest = dto.CusRequest, CarStatus = dto.CarStatus,
        NaturalCode = dto.NaturalCode, CauseCode = dto.CauseCode, StartDate = dto.StartDate,
        ROWTID = dto.ROWTID, ErrorCodeCD = dto.ErrorCodeCD, ErrorCodePN = dto.ErrorCodePN,
        FlagReadySend = dto.FlagReadySend, PartIDError = dto.PartIDError,
        // #322 §12: gán bản chụp khách + xe.
        CusName = dto.CusName, CusAddress = dto.CusAddress, CusTel = dto.CusTel, ModelID = dto.ModelID,
        BatteryNo = dto.BatteryNo, SerialNo = dto.SerialNo,
        WarrantyRegistrationDate = dto.WarrantyRegistrationDate,
        WarrantyExpiresDate = dto.WarrantyExpiresDate,
        WarrantyKM = dto.WarrantyKM, Note = dto.Note };
    db.ServiceWarrantyClaims.Add(c); await db.SaveChangesAsync();
    // #268: nguồn ghi nhật ký NGAY KHI TẠO (2 chỗ gọi với Ser_WarrantyReport_Status.Pending,
    //   WarrantyReport.cs:2792 và :3493) ⇒ đề nghị nào cũng có dòng đầu tiên "PEND".
    db.ServiceWarrantyClaimTransactions.Add(new ServiceWarrantyClaimTransaction
    {
        OrgId = t.OrgId, ClaimId = c.Id, Creator = dto.Creator, CurrentStatus = c.Status,
        Note = dto.Description, CreatedBy = dto.Creator, LogLUDateTime = DateTime.Now, LogLUBy = dto.Creator,
    });
    await db.SaveChangesAsync();
    return Results.Ok(new { c.Id, c.ClaimNo, c.ROWNo, c.Status,
        warrantyStatusText = warrantyClaimStatusNames.TryGetValue(c.Status, out var cn) ? cn : null });
}).RequireAuthorization();

// 🔴 TRỤC TRẠNG THÁI THỨ HAI của đề nghị bảo hành: đồng bộ sang API hãng HMC (TConst.HMCApiStatus).
// ĐỘC LẬP với luồng duyệt nội bộ (/action) — port cũ thiếu hẳn trục này.
var hmcApiStatusNames = new Dictionary<string, string>
{
    ["P"] = "Chờ gửi HMC",
    ["A"] = "Gửi thành công",
    ["R"] = "Gửi lỗi",
};

app.MapGet("/api/warrantyclaims/hmcapistatuses", () => Results.Ok(new
{
    statuses = hmcApiStatusNames.Select(kv => new { code = kv.Key, name = kv.Value }),
    note = "Trục ĐỘC LẬP với Status duyệt nội bộ; nguồn set 'P' ngay khi tạo đề nghị."
})).RequireAuthorization();

/// <summary>
/// Đổi số lần gửi lại thành chữ cái theo nguồn (`CUtils.SoSangChuCai`): 1→A, 2→B, …
/// Dùng cho số serial claim khi đẩy lại sang HMC.
///
/// 🔴 #270 VÁ LỖI PARITY. Nguồn thật (`TERP.Utils/Utils.cs:337` — hàm này **CHỈ CÓ TRÊN MÁY 150**,
/// laptop không có nên lượt port trước phải suy đoán):
/// <code>if (so &lt; 1 || so &gt; 26) return ""; return ((char)(so + 96)).ToString();</code>
/// ⇒ **quá 26 thì trả CHUỖI RỖNG**, KHÔNG cuộn vòng về "A". Bản port cũ dùng `% 26` nên lần gửi thứ 27
/// lại ra "A", **trùng số serial với lần thứ 2** — hai claim khác nhau cùng một `clmNoSrl` ở phía HMC.
/// (Nguồn trả chữ THƯỜNG, chỗ gọi mới `.ToUpper()`; port trả sẵn chữ hoa — cùng kết quả.)
/// </summary>
static string ResendSuffixLetter(int resendCount)
{
    if (resendCount < 1 || resendCount > 26) return "";
    return ((char)('A' + resendCount - 1)).ToString();
}

// Ghi kết quả đồng bộ HMC (bộ đẩy API gọi lại sau khi có phản hồi của hãng).
// TWIN: bản LIVE trên máy 150 là `Ser_ROWarrantyReport_SendHMCX_20260227` — bản laptop KHÔNG có hàm này.
// 🔴 JOB QUÉT ứng viên đẩy HMC — port từ bản biz CHỈ CÓ TRÊN MÁY 150 (WarrantyReport.cs:23477-23505).
// Bản laptop lọc `WarrantyStatus = 'ACCE'` (Accepted) và KHÔNG lọc hãng bảo hành; bản 150 đổi thành
// trạng thái Confirmed + CHỈ hãng HMC/HTMV. Port cũ không có job này ⇒ không có cách lấy danh sách cần đẩy.
app.MapGet("/api/warrantyclaims/hmc-pending", async (AppDbContext db, ITenantContext t, string? dealer) =>
{
    // Cửa sổ thời gian của nguồn: 3 ngày gần nhất, LÙI THÊM 5 GIỜ.
    // Lý do ghi ngay trong nguồn: "tránh job chạy lâu chạy vào sáng sớm hôm sau ==> bỏ sót BCBH".
    var fromDate = DateTime.Now.AddDays(-3).AddHours(-5).Date;

    var qy = db.ServiceWarrantyClaims.Where(x => x.OrgId == t.OrgId
        // đại lý test của idocNet — nguồn loại trừ thẳng trong câu SQL
        && x.DealerCode != "VN101"
        // chưa đẩy (P) hoặc chưa có trạng thái đồng bộ
        && (x.HMCApiStatus == "P" || x.HMCApiStatus == "")
        // trạng thái duyệt: bản 150 đổi từ Accepted sang Confirmed
        && x.Status == "Confirmed"
        // chỉ hãng HMC/HTMV — điều kiện MỚI của bản 150
        && (x.WarrantySerCode == "HMC" || x.WarrantySerCode == "HTMV")
        && x.ApprovedDate != null && x.ApprovedDate >= fromDate);
    if (!string.IsNullOrWhiteSpace(dealer)) qy = qy.Where(x => x.DealerCode == dealer);

    var items = await qy.OrderBy(x => x.Id).Select(x => new
    {
        x.Id, x.ClaimNo, x.DealerCode, x.RONo, x.Vin, x.PlateNo, x.WarrantySerCode,
        x.Status, x.HMCApiStatus, x.HMCApiQtyA, x.ClmNoSrl, x.ApprovedDate,
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, fromDate = fromDate.ToString("yyyy-MM-dd"), items });
}).RequireAuthorization();

app.MapPost("/api/warrantyclaims/{id}/hmcsync", async (
    long id, WarrantyHmcSyncDto dto, AppDbContext db, ITenantContext t) =>
{
    var c = await db.ServiceWarrantyClaims.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (c is null) return Results.NotFound(new { id });
    var target = (dto.ToStatus ?? "").Trim().ToUpperInvariant();
    if (!hmcApiStatusNames.ContainsKey(target))
        return Results.BadRequest(new { error = $"Trạng thái hợp lệ: {string.Join(", ", hmcApiStatusNames.Keys)}" });

    // 🔴 Guard MỚI của bản _20260227: chỉ đẩy HMC khi đề nghị đang ở trạng thái duyệt "Confirmed"
    // (`CheckExistROWarrantyReport(..., Ser_WarrantyReport_Status.Confirmed, ...)`).
    if (c.Status != "Confirmed")
        return Results.BadRequest(new { error = $"Chỉ đẩy HMC khi đề nghị ở trạng thái Confirmed (đang: {c.Status})." });

    // Guard: đã gửi THÀNH CÔNG ("A") thì KHÔNG gửi lại.
    // ⚠️ Ở nguồn, ĐIỀU KIỆN CODE và COMMENT/tham số lỗi MÂU THUẪN nhau:
    //    comment + `HMCApiStatusListToCheck` ghi hợp lệ = "Pending,Fail" (chỉ cho gửi khi P hoặc R),
    //    nhưng biểu thức lại là `if (status != Success) throw`.
    //    Port theo COMMENT + danh sách hợp lệ vì đó mới khớp nghiệp vụ "đã gửi thành công thì thôi".
    //    ĐÃ FLAG trong sổ theo dõi để người xác nhận — không tự quyết là bug của nguồn.
    if (c.HMCApiStatus == "A")
        return Results.BadRequest(new { error = "Đề nghị đã đồng bộ thành công sang HMC, không gửi lại." });

    c.HMCApiStatus = target;
    c.SyncHMCDateTime = DateTime.Now;
    if (!string.IsNullOrWhiteSpace(dto.ClmRcptNo)) c.ClmRcptNo = dto.ClmRcptNo.Trim();

    if (target == "A")
    {
        // Chỉ lần gửi THÀNH CÔNG mới tăng đếm (nguồn: `HMCApiQtyA = iHMCApiQtyACur`).
        var previousSuccess = c.HMCApiQtyA;   // số lần đã gửi thành công TRƯỚC lần này
        c.HMCApiQtyA = previousSuccess + 1;
        // Từ lần đẩy THỨ 2 trở đi: đổi "-" trong số serial claim thành chữ cái theo số lần đã gửi.
        // Lần 1 giữ nguyên; lần 2 = A; lần 3 = B…
        var serial = (dto.ClmNoSrl ?? c.ClmNoSrl ?? "").Trim();
        if (serial.Length > 0)
            c.ClmNoSrl = previousSuccess > 0 ? serial.Replace("-", ResendSuffixLetter(previousSuccess)) : serial;
    }

    c.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        c.Id, c.HMCApiStatus, statusName = hmcApiStatusNames[target],
        c.SyncHMCDateTime, c.ClmRcptNo, c.HMCApiQtyA, c.ClmNoSrl
    });
}).RequireAuthorization();

// Chuyển trạng thái theo máy trạng thái duyệt bảo hành (submit/review/approve/reject/revert).
// ===== 🔴 DÒNG PHỤ TÙNG của đề nghị bảo hành (Ser_ROWarrantyReportPartItems — 1-n, port cũ THIẾU HẲN) =====
// Nguồn: BizCarSv.WarrantyReport.cs:960-1290 (bản máy 150 canonical). Port cũ chỉ có 1 cột PartCode vô hướng.
var rowPartTypeNames = new Dictionary<string, string>
{
    ["PTC"] = "Phụ tùng chính",
    ["PTTT"] = "Phụ tùng thay thế",
    ["VTP"] = "Vật tư phụ",
};

// #394: trả bảng nhãn trạng thái theo MÀN. Mặc định `biz`; `?screen=approve` cho hộp thoại duyệt.
app.MapGet("/api/warrantyclaims/statusnames", (string? screen) =>
{
    var key = string.IsNullOrWhiteSpace(screen) ? "biz" : screen!.Trim().ToLowerInvariant();
    if (!warrantyClaimStatusNamesByScreen.TryGetValue(key, out var map))
        return Results.BadRequest(new { error = "screen phải là biz | approve.", screen = key });
    return Results.Ok(new
    {
        screen = key,
        names = map.Select(kv => new { code = kv.Key, name = kv.Value }),
        screens = warrantyClaimStatusNamesByScreen.Keys,
        note = "Cùng SÁU trạng thái nhưng nguồn có TÁM hằng nhãn: Rejected và Reverted mỗi cái hai cách gọi "
            + "(bản UI của màn duyệt vs bản nghiệp vụ). Giữ cả hai, tách theo màn.",
        divergentCodes = new[] { "Rejected", "Reverted" },
    });
}).RequireAuthorization();

app.MapGet("/api/warrantyclaims/rowparttypes", () => Results.Ok(new
{
    types = rowPartTypeNames.Select(kv => new { code = kv.Key, name = kv.Value }),
    note = "Bắt buộc nhập cho mỗi dòng PT; mỗi đề nghị chỉ được ĐÚNG 1 dòng PTC.",
    partOrderTypes = new[] { new { code = "TST", name = "Mua qua đơn đặt TST" }, new { code = "OTHER", name = "Nguồn khác" } },
})).RequireAuthorization();

app.MapGet("/api/warrantyclaims/{id}/parts", async (long id, AppDbContext db, ITenantContext t) =>
{
    var items = await db.WarrantyClaimPartItems.Where(x => x.OrgId == t.OrgId && x.ClaimId == id)
        .OrderBy(x => x.Id).Select(x => new
        {
            x.Id, x.ClaimId, x.PartCode, x.PartName, x.RowPartType, x.PartOrderType, x.PartOrderNo,
            x.Quantity, x.Price, x.Factor, x.Vat, x.InsurancePrice, x.ExpenseType, x.WarrantyStatus,
            x.FlagMainPart, x.Note, x.CreatedAt, x.UpdatedAt,
            rowPartTypeName = rowPartTypeNames.ContainsKey(x.RowPartType) ? rowPartTypeNames[x.RowPartType] : x.RowPartType,
            amount = x.Quantity * x.Price * x.Factor,
        }).ToListAsync();
    return Results.Ok(new { count = items.Count, totalAmount = items.Sum(i => i.amount), items });
}).RequireAuthorization();

// Thêm 1 dòng phụ tùng vào đề nghị bảo hành — port ĐỦ chuỗi guard của nguồn.
app.MapPost("/api/warrantyclaims/{id}/parts", async (
    long id, WarrantyClaimPartItemDto dto, AppDbContext db, ITenantContext t) =>
{
    var c = await db.ServiceWarrantyClaims.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (c is null) return Results.NotFound(new { error = "Không tìm thấy đề nghị bảo hành." });

    var partCode = (dto.PartCode ?? "").Trim();
    if (partCode.Length == 0) return Results.BadRequest(new { error = "Chưa nhập mã phụ tùng." });

    // Guard 1 (nguồn): loại phụ tùng KHÔNG được trống và phải thuộc PTC/PTTT/VTP.
    var rowPartType = (dto.RowPartType ?? "").Trim().ToUpperInvariant();
    if (rowPartType.Length == 0)
        return Results.BadRequest(new { error = $"PT {partCode} loại phụ tùng không được trống!" });
    if (!rowPartTypeNames.ContainsKey(rowPartType))
        return Results.BadRequest(new { error = $"Loại phụ tùng không hợp lệ (chỉ PTC/PTTT/VTP), nhận: {rowPartType}." });

    // Guard 2 (nguồn, biến bCheckPTC): mỗi đề nghị chỉ được ĐÚNG 1 phụ tùng chính.
    // ⚠️ Nguồn CÓ đoạn bắt buộc phải có PTC nhưng đã COMMENT (dòng ~1285) ⇒ KHÔNG port thành ràng buộc.
    if (rowPartType == "PTC")
    {
        var hasPtc = await db.WarrantyClaimPartItems
            .AnyAsync(x => x.OrgId == t.OrgId && x.ClaimId == id && x.RowPartType == "PTC");
        if (hasPtc) return Results.BadRequest(new { error = "Báo cáo bảo hành chỉ có 1 phụ tùng chính!" });
    }

    // Guard 3 (nguồn): nguồn gốc phụ tùng bắt buộc và chỉ nhận TST/OTHER.
    var partOrderType = (dto.PartOrderType ?? "").Trim().ToUpperInvariant();
    if (partOrderType.Length == 0)
        return Results.BadRequest(new { error = "Chưa có nguồn gốc phụ tùng!" });
    if (partOrderType != "TST" && partOrderType != "OTHER")
        return Results.BadRequest(new { error = "Nguồn gốc phụ tùng không hợp lệ!" });

    var partOrderNo = (dto.PartOrderNo ?? "").Trim();
    if (partOrderType == "TST")
    {
        // Guard 4 (nguồn): TST thì số đơn hàng bắt buộc.
        if (partOrderNo.Length == 0) return Results.BadRequest(new { error = "Chưa nhập số đơn hàng!" });

        // Guard 5 (nguồn): đơn hàng phải TỒN TẠI và đã được duyệt/hoàn thành, có đúng dòng phụ tùng này.
        var order = await db.OrderParts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.OrderPartNo == partOrderNo);
        // 🔴 #237 GUARD CHẾT CÂM (do #234 đổi từ vựng): guard này so với "Approved"/"Finished" trong khi
        //    #234 đã chuyển `OrderPartStatus` sang mã 1 ký tự "A"/"F" ⇒ điều kiện LUÔN ĐÚNG ⇒ **mọi số đơn
        //    hàng TST đều bị báo "không hợp lệ"**. Grep của #234 chỉ tìm `== "Finished"` nên trượt dạng `!=`.
        if (order is null || (order.OrderPartStatus != "A" && order.OrderPartStatus != "F"))
            return Results.BadRequest(new { error = "Số đơn hàng không hợp lệ!" });
        var line = await db.OrderPartLines
            .FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.OrderPartId == order.Id && x.PartCode == partCode);
        if (line is null) return Results.BadRequest(new { error = "Số đơn hàng không hợp lệ!" });

        // Guard 6 (nguồn): tổng SL trên MỌI đề nghị bảo hành (trừ đề nghị bị từ chối) phải <= SL duyệt của đơn.
        var usedQty = await db.WarrantyClaimPartItems
            .Where(x => x.OrgId == t.OrgId && x.ClaimId != id && x.PartOrderType == "TST"
                        && x.PartOrderNo == partOrderNo && x.PartCode == partCode)
            .Join(db.ServiceWarrantyClaims.Where(w => w.OrgId == t.OrgId && w.Status != "Rejected"),
                  x => x.ClaimId, w => w.Id, (x, w) => x.Quantity)
            .SumAsync();
        if (line.OrderQty < usedQty + dto.Quantity)
            return Results.BadRequest(new { error = $"Số lượng phụ tùng BCBH phải <= số lượng duyệt của đơn hàng (duyệt {line.OrderQty}, đã dùng {usedQty})." });

        // Guard 7 (nguồn): đơn giá BCBH phải BẰNG đơn giá của đơn hàng.
        if (line.Price != dto.Price)
            return Results.BadRequest(new { error = $"Đơn giá BCBH và đơn giá của đơn hàng phải bằng nhau (đơn hàng {line.Price})." });
    }

    if (dto.Quantity <= 0) return Results.BadRequest(new { error = "Số lượng phải lớn hơn 0." });
    if (dto.Price < 0) return Results.BadRequest(new { error = "Đơn giá không được âm." });

    var row = new WarrantyClaimPartItem
    {
        OrgId = t.OrgId, ClaimId = id, PartCode = partCode, PartName = dto.PartName,
        RowPartType = rowPartType, PartOrderType = partOrderType,
        PartOrderNo = partOrderNo.Length == 0 ? null : partOrderNo,
        Quantity = dto.Quantity, Price = dto.Price, Factor = dto.Factor <= 0 ? 1 : dto.Factor,
        Vat = dto.Vat, InsurancePrice = dto.InsurancePrice, ExpenseType = dto.ExpenseType,
        WarrantyStatus = dto.WarrantyStatus, FlagMainPart = rowPartType == "PTC" ? "1" : dto.FlagMainPart,
        Note = dto.Note,
    };
    db.WarrantyClaimPartItems.Add(row);
    await db.SaveChangesAsync();
    return Results.Ok(new { row.Id, row.ClaimId, row.PartCode, row.RowPartType, amount = row.Quantity * row.Price * row.Factor });
}).RequireAuthorization();

app.MapDelete("/api/warrantyclaims/{id}/parts/{lineId}", async (
    long id, long lineId, AppDbContext db, ITenantContext t) =>
{
    var row = await db.WarrantyClaimPartItems
        .FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ClaimId == id && x.Id == lineId);
    if (row is null) return Results.NotFound(new { error = "Không tìm thấy dòng phụ tùng." });
    db.WarrantyClaimPartItems.Remove(row);
    await db.SaveChangesAsync();
    return Results.Ok(new { deleted = lineId });
}).RequireAuthorization();

// ===== 🔴 #395 DUYỆT BCBH PHÍA HTC LÀ MỘT **LỜI GỌI LIÊN HỆ THỐNG**, không phải đổi cột =====
// TRACE 4 tầng (khó vì **hai lần sai chính tả**):
//   `FrmWarrantyReportHTCApproved.cs:928` → lớp `SerROWarrantyReportSerivce` (**'Serivce'**, nên grep
//   `Service\.` **bỏ sót** cả màn) → WS `Ser_ROWarrantyReport_HTCApproved` (`asmx:19416`)
//   → biz **`Ser_ROWarrantyReport_HTCApproved_ForHTC`** (`WarrantyReport.cs:10528`).
//   Có **BỐN** twin: `_New20230112` · bản trần · **`_ForHTC` (LIVE)** · `_ForAuto`.
//   ⚠️ Form cha `FrmWarrantyReportHTCSearch` **chỉ ĐỌC**; `UpdateRowStatus` chỉ làm mới lưới.
//
// 🔴 Bản LIVE **KHÔNG tự ghi trạng thái**. Nó đi ba bước rồi **đẩy quyết định sang hệ ĐẠI LÝ**:
//   1. `CheckExistROWarrantyReport(_dbMain, …)` — đề nghị phải tồn tại (đọc trên **DB Main**).
//   2. `DealerCode` trên đề nghị **không được rỗng** ⇒ `Ser_ROWarrantyReport_Dealer_DealerCode_NotFound`.
//   3. Tra **master mạng lưới** `CmCt_Mst_Network` theo `NetworkID = DealerCode`
//      ⇒ không có thì `Ser_ROWarrantyReport_NetworkID_NotFound`;
//      lấy tiếp **địa chỉ WS của đại lý**, thiếu thì `Ser_ROWarrantyReport_WSUrlAddr_NotFound`.
//   4. Gọi `ws.Ser_ROWarrantyReport_HTCApproved_ForDealer(...)` — **web service của chính đại lý đó**;
//      lỗi thì ném `Call_Ser_ROWarrantyReport_HTCApproved_ForDealer` và **KHÔNG duyệt**.
//   ⇒ Đại lý chưa khai trong mạng lưới, hoặc thiếu địa chỉ WS, thì **duyệt bị CHẶN** — không phải
//     'duyệt xong rồi đồng bộ sau'. Đây là món **nợ tầng HTTP** đã ghi trong hàng đợi.
// 📌 MiniHTC chưa có tầng gọi WS đại lý ⇒ giữ nguyên ba guard, và trả cờ `dealerPushPending`
//   thay vì lặng lẽ coi như đã đẩy.
// ===== 🔴 #397 DUYỆT HÀNG LOẠT (`…_HTCApproved_ForAuto`, `:10797`) — GOM THEO ĐẠI LÝ =====
// Nhánh tự động của cùng cụm #395/#396. Khác bản thủ công ở **chữ ký**: thay 11 tham số lẻ
// + 2 DataSet chi tiết bằng **MỘT DataSet lô hồ sơ** (`ds_Ser_ROWarrantyReport`).
//
// 🔴 **HAI VÒNG LẶP TÁCH BIỆT**, và đó là luật:
//   · Vòng 1 — **kiểm TOÀN BỘ** dòng: `ROWID` hợp lệ (`…ForAuto_InvalidROWID`) và có `DealerCode`
//     (`…ForAuto_DealerCode_NotFound`).
//   · Vòng 2 — mới lưu. ⇒ Một dòng hỏng là **cả lô không ghi gì**, không phải 'ghi được dòng nào hay dòng đó'.
// 🔴 **MỘT LỜI GỌI WS CHO MỖI ĐẠI LÝ, KHÔNG PHẢI MỖI HỒ SƠ**: vòng 2 giữ `listDealer`; gặp đại lý
//   đã xử lý thì `continue`, gặp đại lý mới thì `Select("DealerCode = '…'")` **gom hết hồ sơ của đại lý
//   đó** rồi đẩy sang WS của họ một lần.
// ⚠️ **BẤT ĐỐI XỨNG khi lỗi**: trùng đại lý thì `continue` (bỏ qua êm), nhưng thiếu bản ghi mạng lưới
//   hoặc thiếu `WSUrlAddr` thì **`throw`** ⇒ **huỷ cả lô ngay giữa chừng**, kể cả các đại lý đã đẩy xong.
// ⚠️ Bộ lọc gom theo đại lý dựng bằng `string.Format("DealerCode = '{0}'")` — mã đại lý chứa dấu nháy
//   sẽ làm hỏng biểu thức lọc.
// 📌 MiniHTC chưa có tầng gọi WS ⇒ gom nhóm + guard đầy đủ, trả `dealerBatches` để thấy rõ số lời gọi
//   mà nguồn sẽ thực hiện.
app.MapPost("/api/warrantyclaims/approve-auto", async (WarrantyClaimAutoDto dto, AppDbContext db, ITenantContext t) =>
{
    var rows = dto.Claims ?? new();
    if (rows.Count == 0)
        return Results.BadRequest(new { error = "Ser_ROWarrantyReport_HTCApproved_ForAutoTableNotBlank",
            message = "Bảng hồ sơ đầu vào rỗng." });

    // --- VÒNG 1: kiểm TOÀN BỘ trước khi ghi bất cứ gì.
    var claims = new List<ServiceWarrantyClaim>();
    foreach (var r in rows)
    {
        var c = await db.ServiceWarrantyClaims.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == r.ClaimId);
        if (c is null)
            return Results.BadRequest(new { error = "Ser_ROWarrantyReport_HTCApproved_ForAuto_InvalidROWID",
                message = "Không tìm thấy đề nghị.", claimId = r.ClaimId });
        if (string.IsNullOrWhiteSpace(c.DealerCode))
            return Results.BadRequest(new { error = "Ser_ROWarrantyReport_HTCApproved_ForAuto_DealerCode_NotFound",
                message = "Đề nghị không có mã đại lý.", claimId = r.ClaimId });
        claims.Add(c);
    }

    // --- VÒNG 2: GOM THEO ĐẠI LÝ, mỗi đại lý MỘT lời gọi.
    var batches = new List<object>();
    // 🔴 #398 ĐÍNH CHÍNH #397: nhánh LÔ **không nhận ngày duyệt từ người gọi**.
    //   Đầu nhận `…_HTCApproved_ForDealerAuto` (`:11433`) gán thẳng
    //     `string objApprovedDate = dtimeSys.ToString("yyyy-MM-dd")`
    //   ⇒ **ngày HỆ THỐNG, và CHỈ NGÀY — bỏ giờ** (cùng lệ cắt giờ ở #391).
    //   ⇒ Vì luôn là hôm nay nên nhánh lô **không cần** guard 'ngày duyệt < ngày tạo' mà nhánh thủ công
    //     có (#396) — **thiếu guard ở đây là NHẤT QUÁN, không phải sót**.
    //   #397 của tôi nhận `dto.ApprovedDate` là **sai 1:1**; nay bỏ, giữ trường trong DTO cho tương thích.
    var apprAt = DateTime.Today;
    foreach (var g in claims.GroupBy(c => c.DealerCode!))
    {
        var dealer = await db.Dealers.FirstOrDefaultAsync(d => d.OrgId == t.OrgId && d.DealerCode == g.Key);
        if (dealer is null)
            return Results.BadRequest(new { error = "Ser_ROWarrantyReport_HTCApproved_ForAuto_NetworkID_NotFound",
                message = "Đại lý chưa khai trong master mạng lưới — nguồn HUỶ CẢ LÔ tại đây.",
                dealerCode = g.Key, batchesAlreadyPushed = batches.Count });
        if (string.IsNullOrWhiteSpace(dealer.WsUrlAddr))
            return Results.BadRequest(new { error = "Ser_ROWarrantyReport_HTCApproved_ForAuto_WSUrlAddr_NotFound",
                message = "Đại lý chưa có địa chỉ web service — nguồn HUỶ CẢ LÔ tại đây.",
                dealerCode = g.Key, batchesAlreadyPushed = batches.Count });

        foreach (var c in g)
        {
            c.Status = "Accepted";
            c.ApprovedDate = apprAt;
            if (!string.IsNullOrWhiteSpace(dto.Note)) c.HtcNote = dto.Note;
            c.UpdatedAt = DateTime.Now;
        }
        batches.Add(new { dealerCode = g.Key, wsUrl = dealer.WsUrlAddr, claims = g.Select(x => x.Id).ToList() });
    }
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        claimCount = claims.Count,
        dealerBatches = batches.Count,
        batches,
        approvedDate = apprAt,
        approvedDateFromServer = true,
        approvedDateNote = "Nhánh LÔ đóng dấu NGÀY HỆ THỐNG (bỏ giờ) và BỎ QUA ngày do client gửi — đúng nguồn; "
            + "vì thế nhánh này không có guard 'ngày duyệt < ngày tạo' như nhánh thủ công.",
        receiverParityNote = "Đầu nhận lô (…_ForDealerAuto) làm y hệt đầu nhận đơn (…_ForDealer): ghi 3 bảng "
            + "× 3 CSDL và cập nhật Btl_Bulletin_VIN; khác biệt DUY NHẤT là nguồn của ApprovedDate.",
        twoPassNote = "Nguồn kiểm TOÀN BỘ dòng ở vòng 1 rồi mới ghi ở vòng 2 ⇒ một dòng hỏng là cả lô không ghi gì.",
        oneCallPerDealerNote = "MỘT lời gọi WS cho MỖI ĐẠI LÝ, không phải mỗi hồ sơ — nguồn gom hồ sơ theo DealerCode.",
        asymmetryNote = "Trùng đại lý thì bỏ qua êm, nhưng thiếu mạng lưới/WSUrlAddr thì THROW ⇒ huỷ cả lô "
            + "giữa chừng, kể cả các đại lý đã đẩy xong.",
        filterInjectionNote = "Nguồn gom bằng string.Format(\"DealerCode = '{0}'\") — mã đại lý có dấu nháy sẽ hỏng bộ lọc.",
        dealerPushPending = true,
    });
}).RequireAuthorization();

app.MapPost("/api/warrantyclaims/{id}/action", async (long id, WarrantyClaimActionDto dto, AppDbContext db, ITenantContext t) =>
{
    var c = await db.ServiceWarrantyClaims.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (c is null) return Results.NotFound(new { id });
    var act = (dto.Action ?? "").Trim().ToLowerInvariant();
    // (action, các trạng thái nguồn hợp lệ, trạng thái đích)
    (string[] from, string to) rule = act switch
    {
        "submit"  => (new[] { "Pending", "Reverted" }, "Sent"),
        "review"  => (new[] { "Sent" }, "Confirmed"),
        "approve" => (new[] { "Confirmed" }, "Accepted"),
        "reject"  => (new[] { "Sent", "Confirmed" }, "Rejected"),
        "revert"  => (new[] { "Sent", "Confirmed" }, "Reverted"),
        _ => (Array.Empty<string>(), "")
    };
    if (rule.to == "") return Results.BadRequest(new { error = "Hành động không hợp lệ." });
    if (!rule.from.Contains(c.Status)) return Results.BadRequest(new { error = $"Không thể '{act}' khi đang ở trạng thái {c.Status}." });
    if ((act == "reject" || act == "revert") && string.IsNullOrWhiteSpace(dto.Note))
        return Results.BadRequest(new { error = "Từ chối/hoàn trả phải ghi lý do." });
    // --- #395 CHUỖI GUARD của bản LIVE, chỉ áp cho hành động phía HTC (duyệt / từ chối / hoàn trả).
    var htcSide = act is "approve" or "reject" or "revert";
    Dealer? dealerRow = null;
    if (htcSide)
    {
        if (string.IsNullOrWhiteSpace(c.DealerCode))
            return Results.BadRequest(new { error = "Ser_ROWarrantyReport_Dealer_DealerCode_NotFound",
                message = "Đề nghị không có mã đại lý — nguồn chặn duyệt." });

        dealerRow = await db.Dealers.FirstOrDefaultAsync(d => d.OrgId == t.OrgId && d.DealerCode == c.DealerCode);
        if (dealerRow is null)
            return Results.BadRequest(new { error = "Ser_ROWarrantyReport_NetworkID_NotFound",
                message = "Đại lý chưa khai trong master mạng lưới (CmCt_Mst_Network) — nguồn chặn duyệt.",
                c.DealerCode });

        if (string.IsNullOrWhiteSpace(dealerRow.WsUrlAddr))
            return Results.BadRequest(new { error = "Ser_ROWarrantyReport_WSUrlAddr_NotFound",
                message = "Đại lý chưa có địa chỉ web service — nguồn chặn duyệt, KHÔNG phải đồng bộ sau.",
                c.DealerCode });
    }

    // ===== 🔴 #396 ĐẦU NHẬN của lời gọi liên hệ thống (`…_HTCApproved_ForDealer`, `:11090`) =====
    //   Chú thích của chính nguồn ngay tên hàm: *"dùng tạm sau phải nâng cấp lại"*.
    //   Hàm này mới là nơi GHI, và nó làm **bốn** việc chứ không chỉ đổi trạng thái đầu:
    //     1. Guard `CreatedDate > ApprovedDate` ⇒ `Ser_ROWarrantyReport_HTCApproved_InvalidApproved`
    //        (ngày duyệt **không được TRƯỚC** ngày tạo đề nghị).
    //     2. Ghi 10 cột lên `Ser_ROWarrantyReport` — **Main + WH + Dealer** (Dealer có điều kiện).
    //     3. **LAN trạng thái + mốc duyệt xuống DÒNG CÔNG và DÒNG PHỤ TÙNG**
    //        (`…ServiceItems` / `…PartItems`, mỗi bảng 4 cột: `WarrantyStatus` `BulletinID`
    //        `ApprovedDate` `ApprovedBy`) — cũng trên cả ba CSDL.
    //     4. 🔴 **TÁC DỤNG PHỤ SANG MIỀN KHÁC**: nếu duyệt = `Accepted` **và** dòng công có
    //        `BulletinID` thì cập nhật `Btl_Bulletin_VIN` sang `Blt_Bulletin_Status.F`
    //        ('Đã thực hiện'; `P` = chưa thực hiện — khớp mặc định `isnull(Status,'P')` ở #377).
    //        ⇒ Duyệt bảo hành **đóng luôn thông báo kỹ thuật** cho xe đó.
    //   ⚠️ Trong khối bulletin, nguồn có câu `left join ser_car car on car.carid = ro.roid` —
    //     ghép **mã xe với mã LỆNH**. Vô hại ở đây vì không cột nào của `car` được dùng trong
    //     bảng tạm đó, nhưng là cái bẫy nằm sẵn nếu ai thêm cột.
    // 📌 Guard 1 và bước 3, 4 nay đã port; bước 2 (ba CSDL) MiniHTC không tái hiện được.
    if (htcSide && dto.ApprovedDate is not null && dto.ApprovedDate < c.CreatedAt)
        return Results.BadRequest(new { error = "Ser_ROWarrantyReport_HTCApproved_InvalidApproved",
            message = "Ngày duyệt không được TRƯỚC ngày tạo đề nghị.",
            createdAt = c.CreatedAt, approvedDate = dto.ApprovedDate });

    c.Status = rule.to;
    // Mốc duyệt dùng cho job đẩy HMC (nguồn lọc ApprovedDate trên đề nghị đang ở "CONF").
    if (rule.to == "Confirmed") c.ApprovedDate = DateTime.Now;
    if (!string.IsNullOrWhiteSpace(dto.Note)) c.HtcNote = dto.Note;
    // #395: nguồn ĐẨY quyết định sang WS của đại lý ngay trong lời gọi này. MiniHTC chưa có tầng đó.
    var dealerPushPending = htcSide;

    // --- #396 LAN trạng thái + mốc duyệt xuống DÒNG CÔNG và DÒNG PHỤ TÙNG.
    var apprAt = dto.ApprovedDate ?? DateTime.Now;
    var svcItems = await db.WarrantyClaimServiceItems.Where(x => x.OrgId == t.OrgId && x.ClaimId == c.Id).ToListAsync();
    var prtItems = await db.WarrantyClaimPartItems.Where(x => x.OrgId == t.OrgId && x.ClaimId == c.Id).ToListAsync();
    if (htcSide)
    {
        foreach (var i in svcItems) { i.WarrantyStatus = rule.to; i.ApprovedDate = apprAt; i.ApprovedBy = dto.ApprovedBy; }
        foreach (var i in prtItems) { i.WarrantyStatus = rule.to; i.ApprovedDate = apprAt; i.ApprovedBy = dto.ApprovedBy; }
    }

    // --- #396 TÁC DỤNG PHỤ: duyệt CHẤP THUẬN + dòng công có BulletinID ⇒ đóng thông báo kỹ thuật.
    var bulletinsClosed = new List<string>();
    if (rule.to == "Accepted" && c.Vin is not null)
    {
        var bltIds = svcItems.Where(i => !string.IsNullOrWhiteSpace(i.BulletinID))
            .Select(i => i.BulletinID!).Distinct().ToList();
        if (bltIds.Count > 0)
        {
            var links = await db.BulletinVins
                .Where(x => x.OrgId == t.OrgId && x.VinNo == c.Vin && bltIds.Contains(x.BulletinNo))
                .ToListAsync();
            foreach (var lk in links) { lk.Status = "F"; bulletinsClosed.Add(lk.BulletinNo); }
        }
    }
    c.UpdatedAt = DateTime.Now;

    // 🔴 #268: MỌI bước chuyển đều ghi một dòng nhật ký — nguồn gọi
    //   `ProcessSaveSerROWarrantyReportTransaction` ở **10 chỗ**, phủ hết submit/review/approve/reject/revert.
    //   `CurrentStatus` là trạng thái ĐÍCH (nguồn truyền vào chính hằng trạng thái mới).
    db.ServiceWarrantyClaimTransactions.Add(new ServiceWarrantyClaimTransaction
    {
        OrgId = t.OrgId, ClaimId = c.Id, Creator = dto.Creator, CurrentStatus = c.Status,
        Note = dto.Note, CreatedBy = dto.Creator, LogLUDateTime = DateTime.Now, LogLUBy = dto.Creator,
    });
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        c.Id, c.Status,
        // #395: nguon DAY quyet dinh sang WS cua dai ly ngay trong loi goi nay.
        dealerPushPending,
        // #396
        cascadedServiceItems = htcSide ? svcItems.Count : 0,
        cascadedPartItems = htcSide ? prtItems.Count : 0,
        bulletinsClosed,
        cascadeNote = "Nguồn lan WarrantyStatus + ApprovedDate/By xuống DÒNG CÔNG và DÒNG PHỤ TÙNG, "
            + "trên cả ba CSDL (Main + WH + Dealer).",
        bulletinSideEffectNote = "Duyệt CHẤP THUẬN + dòng công có BulletinID ⇒ Btl_Bulletin_VIN chuyển sang "
            + "F (\"Đã thực hiện\"): duyệt bảo hành ĐÓNG LUÔN thông báo kỹ thuật cho xe đó.",
        dealerWsUrl = dealerRow?.WsUrlAddr,
        dealerPushNote = dealerPushPending
            ? "Nguon goi ..._ForDealer sang WS cua dai ly ngay tai buoc nay; loi thi KHONG duyet. "
              + "MiniHTC chua co tang goi WS => trang thai da doi nhung CHUA day."
            : null,
        guardsNote = "Duyet phia HTC bi chan neu: thieu DealerCode, dai ly chua khai trong master mang luoi, "
            + "hoac dai ly chua co dia chi WS. Ba guard lay tu ban LIVE _ForHTC.",
    });
}).RequireAuthorization();

// #268: đọc nhật ký chuyển trạng thái của một đề nghị (cũ nhất → mới nhất, như nguồn `order by`
//   `rt.ROWRTransactionID` ở WarrantyReport.cs:13552).
// 📌 NỢ: nguồn ghi dòng này vào **BA** DB — `_dbMain`, `_dbWH`, và `_dbDealer` khi `!bIsWSMain`
//   (WarrantyReport.cs:1735/1780/1795). MiniHTC một DB nên chỉ ghi một lần.
app.MapGet("/api/warrantyclaims/{id}/transactions", async (long id, AppDbContext db, ITenantContext t) =>
{
    var c = await db.ServiceWarrantyClaims.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (c is null) return Results.NotFound(new { id });
    var items = await db.ServiceWarrantyClaimTransactions
        .Where(x => x.OrgId == t.OrgId && x.ClaimId == id)
        .OrderBy(x => x.Id)
        .Select(x => new { x.Id, x.Creator, x.CurrentStatus, x.Note, x.CreatedBy,
            createdDate = x.CreatedDate.ToString("yyyy-MM-dd HH:mm:ss"), x.LogLUBy })
        .ToListAsync();
    return Results.Ok(new { claimId = id, c.ClaimNo, currentStatus = c.Status, count = items.Count, items });
}).RequireAuthorization();

// ===== Gói dịch vụ (ServicePackage — port 1:1 FrmServicePackageCreate/Search, TCMotor/Services) =====
// ===== 🔴 #550 VÁ TRA CỨU GÓI DỊCH VỤ THEO `SerServicePackageGet` — **KHÁC MÀN, KHÁC LỌC** =====
// Nguồn: `BizCarSv.ServicePackage.cs:1329 SerServicePackageGet`. **Endpoint**: `GET /api/servicepackages` (vá).
//
// 📐 **DIFF `SerServicePackageGet` ↔ `SerServicePackageGetSearchCreateRO`** (#546) — hai hàm gần **giống hệt**,
//   khác đúng **ba** điểm, và cả ba đều nói lên **hai màn khác nhau**:
//   1) 🔴 Bản này lọc `Creator` và `IsPublicFlag` **THẲNG trong mệnh đề chính**;
//      bản kia **comment cả hai** ở đó rồi áp lại trong **hai nhánh `Union`** (công khai ∪ riêng của mình).
//      ⇒ Màn **quản lý gói** (đây) xem theo đúng bộ lọc người dùng chọn; màn **tạo lệnh sửa chữa** (#546)
//        luôn hợp hai tập. **Không** dùng chung một endpoint.
//   2) 🔴 Bản này **có thêm** bộ lọc `TakingTime` (thời gian thực hiện gói) — bản kia **không có**.
//   3) ⚠️ Bản kia có thêm `IsPrivateFlag` và **không** có `TakingTime`; mã lỗi mặc định cũng khác
//      (`SerServicePackageGet` vs `Ser_ServicePackage_GetRO` — **tên hằng lỗi không theo tên hàm**).
//   ⇒ Đây là **cặp sinh đôi** đúng nghĩa: khác biệt thật nằm ở **danh sách mệnh đề lọc**, không ở WHERE
//     tổng thể — đúng cảnh báo của luật #414.
// ⚠️ Tám bộ lọc của nguồn đều qua `BuildClause` (bẫy #410) và **không có `order by`** ở câu cuối.
// ⚠️ Hai cờ `strIsGetService`/`strIsGetPart` quyết định có ghép hai khối bảng con hay không —
//   MiniHTC luôn trả **số đếm** dòng con (rẻ hơn) và có endpoint `/detail` riêng (#546) cho chi tiết.
app.MapGet("/api/servicepackages", async (AppDbContext db, ITenantContext t, string? q, string? active,
    string? dealerCode, string? packageNo, string? packageName, string? takingTime,
    string? creator, DateTime? createdDate, string? isPublicFlag) =>
{
    var query = db.ServicePackages.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(q)) query = query.Where(x => x.PackageNo.Contains(q!) || (x.PackageName != null && x.PackageName.Contains(q!)));
    if (active == "1" || active == "0") query = query.Where(x => x.FlagActive == active);
    // #550 sáu bộ lọc còn thiếu của nguồn (lọc THẲNG, không qua Union).
    if (!string.IsNullOrWhiteSpace(dealerCode)) query = query.Where(x => x.DealerCode == dealerCode!.Trim());
    if (!string.IsNullOrWhiteSpace(packageNo)) query = query.Where(x => x.PackageNo == packageNo!.Trim().ToUpperInvariant());
    if (!string.IsNullOrWhiteSpace(packageName)) query = query.Where(x => x.PackageName != null && x.PackageName!.Contains(packageName!.Trim()));
    if (!string.IsNullOrWhiteSpace(takingTime)) query = query.Where(x => x.TakingTime == takingTime!.Trim());
    if (!string.IsNullOrWhiteSpace(creator)) query = query.Where(x => x.Creator == creator!.Trim());
    if (createdDate is not null) query = query.Where(x => x.CreatedDate != null && x.CreatedDate!.Value.Date == createdDate.Value.Date);
    if (!string.IsNullOrWhiteSpace(isPublicFlag)) query = query.Where(x => x.IsPublicFlag == isPublicFlag!.Trim());

    var items = await query.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.Id, x.PackageNo, x.PackageName, x.DealerCode, x.TakingTime, x.Creator, x.CreatedDate,
        x.IsPublicFlag, x.IsUserBasePrice, x.Description,
        x.ServiceTotal, x.PartTotal, x.GrandTotal, x.FlagActive,
        services = db.ServicePackageServices.Count(s => s.OrgId == t.OrgId && s.ServicePackageId == x.Id),
        parts = db.ServicePackageParts.Count(p => p.OrgId == t.OrgId && p.ServicePackageId == x.Id)
    }).ToListAsync();
    return Results.Ok(new
    {
        count = items.Count, items,
        filtersAppliedDirectlyNotViaUnion = true,
        contrastWithCreateRoScreen = "#546 comment Creator + IsPublicFlag roi ap lai o hai nhanh Union",
        takingTimeFilterOnlyExistsHere = true,
        errorConstantDiffersFromFunctionName = "Ser_ServicePackage_GetRO (ham kia) vs SerServicePackageGet",
        sourceHasNoOrderBy = true,
    });
}).RequireAuthorization();

// Tạo/cập nhật gói theo PackageNo: thay toàn bộ dòng CV + PT, tính tổng (Price×Factor mỗi dòng).
// ===== 🔴 #547 VÁ GUARD TẠO GÓI DỊCH VỤ THEO `SerServicePackageCreate` =====
// Nguồn: `BizCarSv.ServicePackage.cs:179 SerServicePackageCreate` (đọc nguyên văn `#region //Check`
//   và `#region // Check Input Detail` — luật #403). Bản port cũ thiếu **bốn** phép kiểm.
//
// 🔴 **1) BẢNG DỊCH VỤ KHÔNG ĐƯỢC RỖNG**: `if (dt_Ser_ServicePackageServiceItems_Input.Rows.Count == 0)`
//   ⇒ ném `SerServicePackageCreate_ServiceTableNotBlank`. Bản port cũ cho phép *"công **HOẶC** phụ tùng"*
//   ⇒ tạo được gói **chỉ có phụ tùng**, thứ nguồn **cấm**. Nay chặn đúng nguồn.
// 🔴 **2) MỖI DÒNG CÔNG PHẢI CÓ ĐỦ BA TRƯỜNG**, mỗi trường một mã lỗi riêng:
//   `SerID` rỗng → `…_ServiceNotInList` · `ExpenseType` rỗng → `…_Invalid_ExpenseType`
//   · `ROType` rỗng → `…_Invalid_ROType`. **§12**: hai cột `ExpenseType`/`ROType` trước nay **không có**
//   trên `ServicePackageService` ⇒ thêm entity + Seeder + DTO + GET/POST.
// 🔴 **3) GUARD CHÉO GIỮA HAI CỘT** (đây mới là luật nghiệp vụ thật):
//   `if (ROType == Ser_ROType_New.BDD)` thì `ExpenseType` **chỉ được** `Ser_ROType.RORepair` hoặc
//   `Ser_ROType.ROLocal`, ngược lại ném `…_Invalid_ExpenseType`.
//   ⚠️ **HẰNG ≠ GIÁ TRỊ, và hai lớp hằng tên gần giống nhau nhưng KHÁC HẲN NGHĨA** (mở `Const.Main.cs:308`):
//     `Ser_ROType` = **đối tượng thanh toán** (`RORepair="ROREPAIR" · ROInsurance="ROINSURANCE"`
//     `· ROWarranty="ROWARRANTY" · ROLocal="**LOCAL**" · ROGeneral="GENERAL"` — chú ý `ROLocal` có giá trị
//     `"LOCAL"` **không có tiền tố RO**);
//     `Ser_ROType_**New**` = **loại công việc** (`BDD · SCC · SCD · SCS · PDI · SPK`).
//     ⇒ Đọc lướt sẽ tưởng cùng một bảng mã. Chép **giá trị**, không chép tên lớp.
// 🔴 **4) `CheckExistServicePackageNo`**: nguồn **CHẶN trùng mã** khi tạo mới; bản port cũ **upsert theo mã**
//   ⇒ gọi lại cùng mã là **ghi đè im lặng** gói cũ. Nay tách: trùng mã ⇒ báo lỗi, muốn sửa thì gọi
//   `/api/servicepackages/{id}/detail` + đường sửa riêng (bản `Update` của nguồn có `ServicePackageID`).
app.MapPost("/api/servicepackages", async (ServicePackageDto dto, AppDbContext db, ITenantContext t) =>
{
    // Giá trị hằng — chép từ Const.Main.cs, KHÔNG chép tên lớp.
    const string kROTypeBDD = "BDD";                 // Ser_ROType_New.BDD (loại công việc)
    string[] kExpenseAllowedForBDD = { "ROREPAIR", "LOCAL" };   // Ser_ROType.RORepair / .ROLocal

    var no = (dto.PackageNo ?? "").Trim();
    if (no == "") return Results.BadRequest(new { error = "Thiếu mã gói dịch vụ." });
    var svcs = dto.Services ?? new(); var parts = dto.Parts ?? new();
    // #547-1: nguồn BẮT BUỘC có dòng dịch vụ (không chấp nhận gói chỉ có phụ tùng).
    if (svcs.Count == 0)
        return Results.BadRequest(new { error = "SerServicePackageCreate_ServiceTableNotBlank" });
    // #547-2/3: ba trường bắt buộc + guard chéo BDD.
    foreach (var s in svcs)
    {
        if (string.IsNullOrWhiteSpace(s.SerCode))
            return Results.BadRequest(new { error = "SerServicePackageCreate_ServiceNotInList" });
        if (string.IsNullOrWhiteSpace(s.ExpenseType))
            return Results.BadRequest(new { error = "SerServicePackageCreate_Invalid_ExpenseType", s.SerCode });
        if (string.IsNullOrWhiteSpace(s.ROType))
            return Results.BadRequest(new { error = "SerServicePackageCreate_Invalid_ROType", s.SerCode });
        if (string.Equals(s.ROType!.Trim(), kROTypeBDD, StringComparison.OrdinalIgnoreCase)
            && !kExpenseAllowedForBDD.Contains(s.ExpenseType!.Trim().ToUpperInvariant()))
            return Results.BadRequest(new
            {
                error = "SerServicePackageCreate_Invalid_ExpenseType",
                ROType = s.ROType, ExpenseType = s.ExpenseType,
                allowedForBDD = kExpenseAllowedForBDD,
            });
    }
    decimal svcTotal = 0, partTotal = 0;
    var svcRows = new List<ServicePackageService>();
    foreach (var s in svcs)
    {
        if (string.IsNullOrWhiteSpace(s.SerCode)) return Results.BadRequest(new { error = "Có dòng công thiếu mã." });
        var f = s.Factor <= 0 ? 1 : s.Factor; var amt = Math.Round(s.Price * f, 2);
        svcTotal += amt;
        // #552 §12: rỗng ⇒ KHÔNG ghi (khuôn `if (!IsEmpty)` của ProcessSaveServicePackageServiceItem)
        //   — khác #548 nơi rỗng ⇒ DBNull (XOÁ). Hai khuôn ngược nhau trong CÙNG một hàm Update.
        svcRows.Add(new ServicePackageService { OrgId = t.OrgId, SerCode = s.SerCode.Trim(), SerName = s.SerName,
            ExpenseType = s.ExpenseType, ROType = s.ROType, Price = s.Price, Factor = f, Amount = amt,
            ActManHour = s.ActManHour, VAT = s.VAT, Note = s.Note });
    }
    var partRows = new List<ServicePackagePart>();
    var seenP = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
    foreach (var p in parts)
    {
        if (string.IsNullOrWhiteSpace(p.PartCode)) return Results.BadRequest(new { error = "Có dòng PT thiếu mã." });
        if (!seenP.Add(p.PartCode.Trim())) return Results.BadRequest(new { error = "Trùng mã PT trong gói: " + p.PartCode });
        var f = p.Factor <= 0 ? 1 : p.Factor; var amt = Math.Round(p.Price * f, 2);
        partTotal += amt;
        partRows.Add(new ServicePackagePart { OrgId = t.OrgId, PartCode = p.PartCode.Trim(), PartName = p.PartName,
            Price = p.Price, Factor = f, Amount = amt,
            Quantity = p.Quantity, VAT = p.VAT, Note = p.Note, ExpenseType = p.ExpenseType });
    }
    var h = await db.ServicePackages.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PackageNo == no);
    // #547-4: CheckExistServicePackageNo — nguồn CHẶN trùng mã khi TẠO (không upsert im lặng).
    if (h is not null)
        return Results.BadRequest(new
        {
            error = "CheckExistServicePackageNo: mã gói đã tồn tại.",
            packageNo = no, existingId = h.Id,
            sourceBlocksDuplicateOnCreate = true,
        });
    h = new ServicePackage { OrgId = t.OrgId, PackageNo = no }; db.ServicePackages.Add(h);
    h.PackageName = dto.PackageName; h.ServiceTotal = svcTotal; h.PartTotal = partTotal; h.GrandTotal = svcTotal + partTotal; h.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    db.ServicePackageServices.RemoveRange(db.ServicePackageServices.Where(x => x.OrgId == t.OrgId && x.ServicePackageId == h.Id));
    db.ServicePackageParts.RemoveRange(db.ServicePackageParts.Where(x => x.OrgId == t.OrgId && x.ServicePackageId == h.Id));
    foreach (var s in svcRows) { s.ServicePackageId = h.Id; db.ServicePackageServices.Add(s); }
    foreach (var p in partRows) { p.ServicePackageId = h.Id; db.ServicePackageParts.Add(p); }
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        h.Id, h.PackageNo, h.ServiceTotal, h.PartTotal, h.GrandTotal,
        guardsAddedFromSource = new[] { "ServiceTableNotBlank", "ServiceNotInList",
            "Invalid_ExpenseType", "Invalid_ROType", "BDD => ExpenseType in (ROREPAIR, LOCAL)",
            "CheckExistServicePackageNo" },
        twoConstantClassesLookAlike = "Ser_ROType (doi tuong thanh toan) vs Ser_ROType_New (loai cong viec)",
        roLocalValueHasNoRoPrefix = "Ser_ROType.ROLocal = \"LOCAL\"",
    });
}).RequireAuthorization();

// ===== #549 XOÁ GÓI DỊCH VỤ — VÀ MỘT **ĐỐI CHỨNG LÀNH** VỀ THAM SỐ HOÁ =====
// Nguồn: `BizCarSv.ServicePackage.cs:1165 SerServicePackageDelete`.
// Endpoint: `POST /api/servicepackages/{id}/delete` (trước nay MiniHTC chỉ có `toggle`).
//
// ⚪ **ĐỐI CHỨNG LÀNH — CÂU `DELETE` **CÓ** THAM SỐ HOÁ**:
//     `delete from Ser_ServicePackage where ServicePackageID = @ServicePackageID`
//     `_dbMain.ExecQuery(strSqlDelete, "@ServicePackageID", strServicePackageID)`
//   ⇒ **Ngược hẳn** #536 / #538 / #540 (dựng mệnh đề bằng `BuildClauseConditionList` rồi `ExecNonQuery`
//     **không tham số**). Cùng một repo, cùng một loại thao tác, **hai kiểu viết** — nên "nguồn hay bake"
//     **không phải quy luật**; phải đọc từng hàm. Ghi lại để lượt sau khỏi vơ đũa cả nắm.
// 🔴 **XOÁ CON TRƯỚC, CHA SAU**: `ProcessServicePackageServiceItemDelete` →
//   `ProcessServicePackagePartItemDelete` → mới `delete Ser_ServicePackage` ⇒ đúng thứ tự khoá ngoại.
//   Port giữ nguyên thứ tự đó.
// 🔴 **KHÔNG có guard tham chiếu**: nguồn **không** kiểm gói có đang được lệnh sửa chữa / lịch hẹn nào dùng —
//   khác #540 (mã lỗi có guard) và giống #541 (loại gia hạn không có). ⇒ Xoá gói đang dùng thì dữ liệu
//   tham chiếu **thành mồ côi**. Port **giữ đúng nguồn** (không tự thêm) nhưng **đếm và trả** số tham chiếu
//   tìm thấy, để người gọi tự quyết — nêu cờ `sourceHasNoReferenceGuard`.
// ⚠️ `Convert.ToInt32(strServicePackageID)` **không guard rỗng** (họ #526/#528/#535).
// ⚠️ Xoá ở **ba** DB (`_dbMain` · `_dbWH` · `_dbDealer` nếu `bNeedTransaction_Dealer`) — nợ kiến trúc đã ghi.
app.MapPost("/api/servicepackages/{id:long}/delete", async (long id, AppDbContext db, ITenantContext t) =>
{
    // CheckExistServicePackage(ID)
    var h = await db.ServicePackages.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (h is null) return Results.NotFound(new { error = "CheckExistServicePackage: không tìm thấy gói.", id });

    // Nguồn KHÔNG kiểm tham chiếu; ở đây chỉ ĐẾM và báo lại, không tự chặn (giữ đúng hành vi nguồn).
    var svcCount = await db.ServicePackageServices.CountAsync(x => x.OrgId == t.OrgId && x.ServicePackageId == id);
    var partCount = await db.ServicePackageParts.CountAsync(x => x.OrgId == t.OrgId && x.ServicePackageId == id);

    // Xoá CON trước, CHA sau — đúng thứ tự của nguồn.
    db.ServicePackageServices.RemoveRange(
        db.ServicePackageServices.Where(x => x.OrgId == t.OrgId && x.ServicePackageId == id));
    db.ServicePackageParts.RemoveRange(
        db.ServicePackageParts.Where(x => x.OrgId == t.OrgId && x.ServicePackageId == id));
    await db.SaveChangesAsync();
    db.ServicePackages.Remove(h);
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        deletedId = id, packageNo = h.PackageNo,
        deletedServiceLines = svcCount, deletedPartLines = partCount,
        deleteOrderChildThenParent = true,
        sourceDeleteIsParameterised = "delete ... where ServicePackageID = @ServicePackageID",
        contrastWithBakedDeletes = "#536 / #538 / #540 dung BuildClauseConditionList + ExecNonQuery khong tham so",
        sourceHasNoReferenceGuard = true,
        sourceConvertToInt32HasNoEmptyGuard = true,
        deletesThreeDatabases = "Main + WH + Dealer",
    });
}).RequireAuthorization();

// ===== 🔴 #548 SỬA GÓI DỊCH VỤ — `SerServicePackageUpdate`, VÀ MỘT LỜI GỌI GUARD **LẶP THỪA** =====
// Nguồn: `BizCarSv.ServicePackage.cs:546 SerServicePackageUpdate`. Endpoint: `POST /api/servicepackages/{id}/update`.
// **§12**: thêm 7 cột `DealerCode · TakingTime · Description · Creator · CreatedDate · IsPublicFlag · IsUserBasePrice`.
//
// 📐 **DIFF `Create` ↔ `Update`** (luật #404) — khác ở **guard**, không ở phần ghi:
//   · `Create`: `CheckExistServicePackageNo` (chặn trùng mã).
//   · `Update`: `CheckExistServicePackage(ID)` · `CheckServicePackageFieldEmpty(No, DealerCode, Name)`
//     · `CheckExistServicePackage(ID)` **LẦN HAI** · `CheckExistServicePackageNoModify(No, DealerCode, ID)`.
// 🔴 **`CheckExistServicePackage` ĐƯỢC GỌI HAI LẦN, CÙNG THAM SỐ, CÁCH NHAU MỘT LỜI GỌI** —
//   lần thứ hai **thừa hoàn toàn** (cùng họ `SetDataRowStateOfAllRows` gọi hai lần ở #528).
//   Vô hại về kết quả, nhưng là **một truy vấn DB thừa mỗi lần sửa gói**.
// 🔴 **Chống trùng khi SỬA dùng hàm KHÁC**: `…NoModify(No, DealerCode, **ID**)` — có thêm `ID` để
//   **loại trừ chính bản ghi đang sửa**; nếu port dùng nhầm hàm của `Create` thì **không sửa được**
//   chính gói đó (tự báo trùng với chính mình). ⚠️ Khoá chống trùng là **cặp** `(No, DealerCode)`,
//   không phải riêng `No` — nghĩa là **hai đại lý được dùng chung một mã gói**.
// 🔴 **Rỗng ⇒ `DBNull`** cho **năm** cột (`TakingTime · Description · Creator · CreatedDate · IsPublicFlag`
//   · `IsUserBasePrice`): ở đây gửi rỗng là **XOÁ** — ngược hẳn #528 (rỗng = giữ nguyên).
//   Ba cột bắt buộc (`No · DealerCode · Name`) được `CheckServicePackageFieldEmpty` chặn từ trước.
// ⚠️ `ServicePackageNo` được `.ToUpper()` trước khi ghi (chuẩn hoá **chỉ ở nhánh sửa**).
app.MapPost("/api/servicepackages/{id:long}/update", async (long id, ServicePackageUpdateDto dto,
    AppDbContext db, ITenantContext t) =>
{
    // CheckExistServicePackage(ID) — nguồn gọi HAI lần; ở đây một lần là đủ (nêu cờ).
    var h = await db.ServicePackages.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (h is null) return Results.NotFound(new { error = "CheckExistServicePackage: không tìm thấy gói.", id });

    // CheckServicePackageFieldEmpty(No, DealerCode, Name) — ba trường BẮT BUỘC.
    var no = (dto.PackageNo ?? "").Trim();
    var dealer = (dto.DealerCode ?? "").Trim();
    var name = (dto.PackageName ?? "").Trim();
    if (no.Length == 0 || dealer.Length == 0 || name.Length == 0)
        return Results.BadRequest(new
        {
            error = "CheckServicePackageFieldEmpty: thiếu ServicePackageNo / DealerCode / ServicePackageName.",
            packageNo = no, dealerCode = dealer, packageName = name,
        });

    // CheckExistServicePackageNoModify(No, DealerCode, ID) — trùng theo CẶP (No, DealerCode), TRỪ chính mình.
    var dup = await db.ServicePackages.AnyAsync(x => x.OrgId == t.OrgId && x.Id != id
        && x.PackageNo == no.ToUpperInvariant() && x.DealerCode == dealer);
    if (dup)
        return Results.BadRequest(new
        {
            error = "CheckExistServicePackageNoModify: mã gói đã tồn tại ở đại lý này.",
            packageNo = no, dealerCode = dealer,
            uniqueKeyIsPair = "(ServicePackageNo, DealerCode)",
        });

    h.PackageNo = no.ToUpperInvariant();          // nguồn .ToUpper() CHỈ ở nhánh sửa
    h.DealerCode = dealer;
    h.PackageName = name;
    // Rỗng ⇒ null (khuôn DBNull của nguồn: gửi rỗng XOÁ).
    h.TakingTime = string.IsNullOrWhiteSpace(dto.TakingTime) ? null : dto.TakingTime;
    h.Description = string.IsNullOrWhiteSpace(dto.Description) ? null : dto.Description;
    h.Creator = string.IsNullOrWhiteSpace(dto.Creator) ? null : dto.Creator;
    h.CreatedDate = dto.CreatedDate;
    h.IsPublicFlag = string.IsNullOrWhiteSpace(dto.IsPublicFlag) ? null : dto.IsPublicFlag;
    h.IsUserBasePrice = string.IsNullOrWhiteSpace(dto.IsUserBasePrice) ? null : dto.IsUserBasePrice;
    h.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        h.Id, h.PackageNo, h.DealerCode, h.PackageName, h.TakingTime, h.Description,
        h.Creator, h.CreatedDate, h.IsPublicFlag, h.IsUserBasePrice,
        duplicateGuardExcludesSelf = "CheckExistServicePackageNoModify(No, DealerCode, ID)",
        uniqueKeyIsPair = "(ServicePackageNo, DealerCode) — hai dai ly duoc trung ma goi",
        emptyMeansClear = "5 cot: TakingTime/Description/Creator/CreatedDate/IsPublicFlag/IsUserBasePrice",
        duplicateGuardCallInSource = "CheckExistServicePackage(ID) goi HAI lan cung tham so — lan hai thua",
        packageNoUpperCasedOnUpdateOnly = true,
    });
}).RequireAuthorization();

// ===== 🔴 #546 VÁ CHI TIẾT GÓI DỊCH VỤ THEO `SerServicePackageGetSearchCreateRO` =====
// Nguồn: `BizCarSv.ServicePackage.cs:1582 SerServicePackageGetSearchCreateRO` (kênh ClientService).
// Bản port cũ trả gói + hai bảng con **giá cố định trên dòng**; nguồn còn kèm **giá hiệu lực** và **tồn kho**.
//
// 🔴 **GIÁ PHỤ TÙNG LẤY THEO NGÀY HIỆU LỰC** (đúng luật #412 — danh mục CÓ hiệu lực và CÓ dùng):
//     `left join (SELECT PartPriceID, PartId, Price, DateEffect,`
//     `   RANK() OVER(PARTITION BY PartId ORDER BY DateEffect DESC) AS rn`
//     ` FROM Ser_Inv_Partprice WHERE DateEffect <= <hôm nay> and IsActive = '1') tmpprice WHERE rn = 1`
//   ⇒ Giá **mới nhất còn hiệu lực tính đến hôm nay**, chỉ lấy dòng `IsActive = '1'`.
//   🔴 **DÙNG `RANK()` CHỨ KHÔNG PHẢI `ROW_NUMBER()`**: hai bảng giá **cùng `DateEffect`** cho cùng mã
//     ⇒ **cả hai đều có `rn = 1`** ⇒ `left join` **NHÂN ĐÔI dòng phụ tùng** của gói, và tổng tiền
//     hiển thị bị đếm lặp. Port lấy **một** dòng (mới nhất, rồi tới Id lớn nhất) + đếm `priceTies`
//     để nêu đúng chỗ nguồn sẽ nhân dòng.
//   ⚠️ Mốc so là **CHUỖI**: `Replace(CONVERT(VARCHAR, Getdate(), 111), '/', '-')` ⇒ `yyyy-mm-dd`.
// 🔴 **`InventoryQuantity` Ở ĐÂY CHỈ LÀ TỒN KHO**: `(isnull(sb.TotalInStock, 0))` — **không** cộng
//   "hàng đang về" như màn hẹn (#544). Xác nhận lần thứ hai rằng **hai công thức là chủ đích**,
//   không hợp nhất (đã ghi ở `/api/serviceparts/{code}/inventory`).
// ⚠️ Bảng con nối `INNER JOIN Ser_Mst_Part` ⇒ phụ tùng **đã xoá khỏi danh mục** thì **rơi khỏi gói**
//   (luật #410) — khác các bảng con của lịch hẹn (#544) vốn `left join`.
// ⚠️ Ở câu lọc gói: hai mệnh đề bị **comment trong bảng lọc đầu** rồi áp lại ở **hai nhánh `Union`** —
//   nhánh 1 lọc `IsPublicFlag`, nhánh 2 lọc `Creator` + `IsPrivateFlag` ⇒ *gói công khai* **hợp** *gói riêng
//   của người tạo*. `Union` (không `ALL`) nên gói vừa công khai vừa của mình **chỉ ra một lần**.
// ⚠️ `case sp.IsUserBasePrice when 1 then N'Giá chung' when 0 then N'Giá theo gói dịch vụ'
//   else N'Giá theo gói dịch vụ' end` — **nhánh `else` trùng nhánh `0`** ⇒ NULL cũng hiện *"Giá theo gói"*.
app.MapGet("/api/servicepackages/{id}/detail", async (long id, AppDbContext db, ITenantContext t) =>
{
    var h = await db.ServicePackages.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (h is null) return Results.NotFound(new { id });
    // ===== 🔴 #551 KHỐI DỊCH VỤ CỦA GÓI — **HAI BỘ GIÁ SONG SONG** =====
    // Nguồn: `zzzzClauseSelect_ServicePackageServiceItems` trong `SerServicePackageGetSearchCreateRO`
    //   (`BizCarSv.ServicePackage.cs:1582`). Bản port cũ chỉ trả **một** bộ giá.
    // 🔴 Nguồn trả **hai bộ**: `Isnull(sps.Price,0) Price` · `sps.Factor * Isnull(sps.Price,0) Amount`
    //   (**giá CHỐT trên gói**) và `s.Price NewPrice` · `s.VAT NewVAT` ·
    //   `sps.Factor * Isnull(s.Price,0) NewAmount` (**giá HIỆN HÀNH trong danh mục**).
    //   ⇒ Màn tạo lệnh sửa chữa cho người dùng thấy **chênh lệch giá** giữa lúc lập gói và hôm nay.
    //     Thiếu nó thì báo giá theo gói cũ mà **không ai biết giá đã đổi**.
    // 🔴 **Ba cột HẰNG SỐ CỨNG** để khớp hình dạng bảng khi tạo RO:
    //   `WarrantyStatus = ''` · `InsurancePrice = 0.0` · `'' CamID` — **không** đọc từ đâu cả.
    // 🔴 `--, sps.ExpenseType` **BỊ COMMENT** ⇒ dù #547 **bắt buộc** nhập `ExpenseType` khi tạo gói,
    //   khối này **không trả nó ra** ⇒ tạo lệnh sửa chữa từ gói thì **đối tượng thanh toán bị mất**,
    //   người dùng phải chọn lại. **Mâu thuẫn nội bộ của nguồn** — port **vẫn trả** (có cờ) vì dữ liệu đã có.
    // ⚠️ `sps.*` rồi mới tới `Isnull(sps.Price,0) Price` ⇒ DataTable có **hai cột `Price`** (cột sau thành
    //   `Price1`). ⚠️ `INNER JOIN ser_mst_service` ⇒ dịch vụ **đã xoá khỏi danh mục rơi khỏi gói**
    //   (giống phần phụ tùng ở #546).
    var svcRows = await db.ServicePackageServices.Where(x => x.OrgId == t.OrgId && x.ServicePackageId == id)
        .ToListAsync();
    var svcCodes = svcRows.Select(x => x.SerCode).ToList();
    var svcMaster = await db.ServiceItemMsts.Where(m => m.OrgId == t.OrgId && svcCodes.Contains(m.SerCode))
        .Select(m => new { m.SerCode, m.SerName, m.Price, m.Vat, m.StdManHour, m.FlagWarranty }).ToListAsync();
    var svcs = svcRows.Select(x =>
    {
        var m = svcMaster.FirstOrDefault(v => v.SerCode == x.SerCode);
        return new
        {
            x.SerCode, x.SerName, x.ExpenseType, x.ROType,   // #547 §12
            x.Price, x.Factor, x.Amount,                      // giá CHỐT trên gói
            x.ActManHour, x.VAT, x.Note,                      // #552 §12
            NewPrice = m?.Price, NewVAT = m?.Vat,             // giá HIỆN HÀNH trong danh mục
            NewAmount = m is null ? (decimal?)null : x.Factor * m.Price,
            StdManHour = m?.StdManHour,
            m?.FlagWarranty,
            // Ba cột hằng số cứng của nguồn — giữ để khớp hình dạng khi tạo RO.
            WarrantyStatus = "",
            InsurancePrice = 0.0m,
            CamID = "",
            priceChanged = m is not null && m.Price != x.Price,
        };
    }).ToList();
    var partRows = await db.ServicePackageParts.Where(x => x.OrgId == t.OrgId && x.ServicePackageId == id)
        .ToListAsync();
    var codes = partRows.Select(x => x.PartCode).ToList();

    // Giá hiệu lực: mới nhất tính đến HÔM NAY, chỉ dòng IsActive = "1".
    var today = DateTime.Now.Date;
    var prices = await db.PartPrices
        .Where(p => p.OrgId == t.OrgId && codes.Contains(p.PartCode)
            && p.EffectiveDate <= today && p.IsActive == "1")
        .Select(p => new { p.Id, p.PartCode, p.Price, p.PriceVAT, p.EffectiveDate }).ToListAsync();
    // Nguồn dùng RANK() ⇒ hoà mốc hiệu lực thì NHÂN DÒNG; ở đây đếm số mã bị hoà.
    var priceTies = prices.GroupBy(p => p.PartCode)
        .Count(g => g.Count(x => x.EffectiveDate == g.Max(y => y.EffectiveDate)) > 1);

    var stock = await db.PartStocks.Where(s => s.OrgId == t.OrgId && codes.Contains(s.PartCode))
        .GroupBy(s => s.PartCode).Select(g => new { PartCode = g.Key, OnHand = g.Sum(x => x.OnHand) })
        .ToListAsync();

    var parts = partRows.Select(x =>
    {
        var eff = prices.Where(p => p.PartCode == x.PartCode)
            .OrderByDescending(p => p.EffectiveDate).ThenByDescending(p => p.Id).FirstOrDefault();
        return new
        {
            x.PartCode, x.PartName,
            x.Quantity, x.VAT, x.Note, x.ExpenseType,       // #552 §12
            x.Price,                                        // giá chốt trên dòng gói
            effectivePrice = eff?.Price,                    // giá theo bảng giá còn hiệu lực
            effectivePriceVAT = eff?.PriceVAT,
            effectiveDate = eff?.EffectiveDate,
            x.Factor, x.Amount,
            // Công thức của MÀN GÓI DỊCH VỤ: CHỈ tồn kho (khác #544).
            InventoryQuantity = stock.FirstOrDefault(v => v.PartCode == x.PartCode)?.OnHand ?? 0m,
        };
    }).ToList();

    return Results.Ok(new
    {
        h.PackageNo, h.PackageName, h.ServiceTotal, h.PartTotal, h.GrandTotal,
        services = svcs, parts,
        inventoryFormulaOfThisScreen = "isnull(TotalInStock,0) — KHONG cong hang dang ve",
        // ===== #551 =====
        twoPriceSetsForServices = "Price/Amount (chot tren goi) vs NewPrice/NewVAT/NewAmount (danh muc hien hanh)",
        servicesWithChangedPrice = svcs.Count(x => x.priceChanged),
        hardcodedColumnsInSource = new[] { "WarrantyStatus=''", "InsurancePrice=0.0", "'' CamID" },
        expenseTypeCommentedOutInSource = "--, sps.ExpenseType — bat buoc nhap khi tao goi (#547) nhung KHONG tra ra",
        duplicatePriceColumnInSource = "sps.* roi Isnull(sps.Price,0) Price => DataTable co Price va Price1",
        serviceMasterJoinIsInner = "dich vu da xoa khoi danh muc ROI khoi goi",
        // ===== #552 =====
        // 🔴 `ProcessSaveServicePackage*Item` ghi thêm các cột mà bản port cũ KHÔNG có:
        //   dòng công: `ActManHour` (giờ công THỰC TẾ — khác `StdManHour` định mức ở danh mục) · `VAT` · `Note`;
        //   dòng phụ tùng: **`Quantity`** · `VAT` · `Note` · `ExpenseType`.
        //   ⚠️ Thiếu `Quantity` là **mất thông tin nghiệp vụ**: gói có HAI lọc dầu và gói có MỘT
        //     trước nay không phân biệt được (chỉ có `Factor`).
        // ⚪ **Kiểm tra âm tính**: `Update` gọi `ProcessServicePackage*ItemDelete` **trước** rồi mới
        //   `ProcessSave…` ⇒ **xoá-rồi-chèn**, không nhân đôi hạng mục. MiniHTC cũng `RemoveRange` rồi `Add`
        //   ⇒ **khớp**, không phải sửa.
        // ⚠️ Trong `ProcessSave…`, mỗi cột bọc `if (!StringUtils.IsEmpty(...))` ⇒ **rỗng = KHÔNG ghi**
        //   (giữ null), **ngược** với phần header của cùng hàm `Update` nơi rỗng ⇒ `DBNull` (XOÁ) — #548.
        //   Hai khuôn đối lập nằm trong **cùng một lời gọi nghiệp vụ**.
        // ===== 🔴 #553 CƠ CHẾ ĐỒNG BỘ BA DB: **CHÉP KHOÁ CHÍNH**, KHÔNG PHẢI SINH LẠI =====
        // Đọc `ProcessSaveServicePackagePartItem` (`BizCarSv.ServicePackage.cs:1031`) tới tận câu ghi:
        //   1) `_dbMain.SaveData("Ser_ServicePackagePartItems", dt_PartItem)` — Main sinh `ItemID` (PK tự tăng);
        //   2) đọc **ngược lại** từ Main: `select * from Ser_ServicePackagePartItems where ServicePackageID = @…`;
        //   3) với **từng dòng**, chạy `insert into Ser_ServicePackagePartItems (**ItemID**, …) values (@ItemID, …)`
        //      trên `_dbWH`, rồi trên `_dbDealer` nếu `!bIsWSMain`.
        // ⇒ **Khoá chính được CHÉP nguyên, không sinh lại** ⇒ ba DB **bắt buộc cùng `ItemID`**.
        //   Đây là ràng buộc kiến trúc mà nợ `_dbWH`/`_dbDealer` phải tôn trọng: nếu bản port sau này
        //   sinh khoá riêng ở từng DB thì **mọi phép đối chiếu chéo DB sẽ vỡ** (và câu `insert` này sẽ
        //   đụng PK khi chạy lại).
        // ⚪ **KIỂM TRA ÂM TÍNH (đã đọc tận nơi)**: `ProcessServicePackagePartItemDelete` xoá ở **cả ba**
        //   `_dbMain` · `_dbWH` · `_dbDealer` ⇒ chu trình *xoá-3-nơi rồi chèn-3-nơi* **không** đụng PK.
        //   Nếu Delete chỉ xoá Main thì lần sửa thứ hai đã nổ khoá trùng ở WH — nó **không** xảy ra.
        // ⚠️ `LogLUDateTime`/`LogLUBy` được **đọc từ bản Main vừa ghi**, nhưng `ProcessSave…` **không gán**
        //   hai cột đó ⇒ chép sang WH/Dealer là chép **NULL**. Cột nhật ký của hạng mục gói **luôn rỗng**.
        // ⚠️ Mỗi dòng tốn **hai** round-trip phụ (WH + Dealer) ⇒ gói 30 phụ tùng = 60 lượt gọi DB thêm.
        threeDbSyncCopiesPrimaryKey = "insert ... (ItemID, ...) values (@ItemID, ...) tren _dbWH va _dbDealer",
        deleteCoversAllThreeDbVerified = true,
        logColumnsAreNullBecauseSaveDoesNotSetThem = new[] { "LogLUDateTime", "LogLUBy" },
        extraRoundTripsPerItem = 2,
        itemColumnsAdded = new[] { "ActManHour", "VAT", "Note", "Quantity", "ExpenseType" },
        deleteThenInsertVerified = true,
        emptyMeansSkipOnItemsButClearOnHeader = true,
        contrastWithAppointmentScreen = "#544 cong ca TotalInShipment",
        effectivePriceRule = "RANK() OVER(PARTITION BY PartId ORDER BY DateEffect DESC) = 1, DateEffect <= hom nay, IsActive = '1'",
        rankInsteadOfRowNumberDuplicatesRows = true,
        priceTies,
        sourceInnerJoinsPartMaster = "phu tung da xoa khoi danh muc thi ROI khoi goi",
        packageFilterUsesUnionOfPublicAndOwn = "nhanh 1: IsPublicFlag; nhanh 2: Creator + IsPrivateFlag",
