app.MapPost("/api/redeemrequests", async (RedeemRequestDto dto, AppDbContext db, ITenantContext t, HttpContext http) =>
{
    var lines = dto.Lines ?? new List<RedeemRequestLineDto>();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Đề nghị chưa có dòng VIN." });
    if (lines.Any(l => string.IsNullOrWhiteSpace((l.VIN ?? "").Trim()))) return Results.BadRequest(new { error = "Có dòng chưa nhập số VIN." });
    var dup = lines.GroupBy(l => (l.VIN ?? "").Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dup != null) return Results.BadRequest(new { error = $"VIN '{dup.Key}' bị trùng trong đề nghị." });
    if (lines.Any(l => (l.RedeemType ?? "DIRECT").Trim().ToUpperInvariant() is not ("DIRECT" or "GUARANTEE"))) return Results.BadRequest(new { error = "Loại thu hồi phải là DIRECT hoặc GUARANTEE." });
    var who = http.User.Identity?.Name ?? http.User.FindFirst("email")?.Value ?? "system";
    var h = new RedeemRequest
    {
        OrgId = t.OrgId,
        ReqRedeemNo = string.IsNullOrWhiteSpace((dto.ReqRedeemNo ?? "").Trim()) ? "RD" + DateTime.Now.ToString("yyMMddHHmmss") : dto.ReqRedeemNo!.Trim(),
        CreatedDate = dto.CreatedDate ?? DateTime.Now,
        DealerCode = dto.DealerCode, Note = dto.Note, VinCount = lines.Count,
        // 🔴 #140 SỬA BUG CÂM: chỗ này trước ghi Status = "Created", trong khi endpoint duyệt
        //    (POST /api/redeemrequests/{id}/{action}) đòi Status == "P" ⇒ đề nghị vừa tạo
        //    KHÔNG BAO GIỜ duyệt được. Mã nguồn dùng "P" (`TConst.Stage.Pending`).
        Status = "P", CreatedBy = who, CreatedAt = DateTime.Now,
        Remark = dto.Remark, LogLUDateTime = DateTime.Now, LogLUBy = who
    };
    db.RedeemRequests.Add(h);
    await db.SaveChangesAsync();
    foreach (var l in lines)
        db.RedeemRequestLines.Add(new RedeemRequestLine { OrgId = t.OrgId, RequestId = h.Id, VIN = (l.VIN ?? "").Trim(), CarId = l.CarId, RedeemType = (l.RedeemType ?? "DIRECT").Trim().ToUpperInvariant(),
            // #140 parity RD_ReqRedeemDtl.
            DMReqDate = l.DMReqDate ?? h.CreatedDate, DealerCode = l.DealerCode ?? dto.DealerCode,
            DRListCode = l.DRListCode, MortageBankCode = l.MortageBankCode, ReqRMNo = l.ReqRMNo,
            Remark = l.Remark, DMReqDtlStatus = "P", LogLUDateTime = DateTime.Now, LogLUBy = who });
    await db.SaveChangesAsync();
    return Results.Ok(new { h.Id, h.ReqRedeemNo, h.VinCount, h.Status });
}).RequireAuthorization();

app.MapPost("/api/redeemrequests/{id}/{action}", async (long id, string action, AppDbContext db, ITenantContext t) =>
{
    var h = await db.RedeemRequests.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (h is null) return Results.NotFound(new { id });
    var target = action.ToLowerInvariant() switch { "approve" => "A", "reject" => "R", _ => "" };
    if (target == "") return Results.BadRequest(new { error = "Hành động không hợp lệ (approve/reject)." });
    if (h.Status != "P") return Results.BadRequest(new { error = $"Đề nghị đang '{h.Status}', chỉ xử lý khi 'P' (chờ duyệt)." });
    // ⚠️ Duyệt cả đề nghị là lối tắt của bản port. Nguồn duyệt TỪNG DÒNG rồi mới suy ra header
    // — xem POST /api/reqredeems/{no}/approve-vin. Ở đây đồng bộ luôn trạng thái mọi dòng cho nhất quán.
    h.Status = target;
    h.ApprovedDate = DateTime.Now;
    var allLines = await db.RedeemRequestLines.Where(x => x.OrgId == t.OrgId && x.RequestId == h.Id).ToListAsync();
    var stampAt = DateTime.Now;
    foreach (var ln in allLines) { ln.DMReqDtlStatus = target; ln.ApprovedDate = stampAt; }

    // ===== 🔴 #352 DUYỆT GIẢI CHẤP PHẢI ĐÓNG LUÔN DÒNG THẾ CHẤP =====
    // Nguồn `RD_ReqRedeemDtl_Approve_New20230306` (`BizHTC.GiaiChap.cs:2810`, md5 giống hệt 2 máy)
    //   cập nhật `RM_ReqMortgageDtl` bằng **một cụm 5 trường** trong cùng thao tác duyệt:
    //     `t.ReqDMNo = f.ReqDMNo` · `t.RMDtlStatus = f.RMDtlStatus`
    //     `t.FinishDate = f.**ApprovedDate**` · `t.FinishBy = f.**ApprovedBy**` · LogLU*
    // 🔴 ÁNH XẠ ĐỔI TÊN QUA BẢNG: mốc `ApprovedDate`/`ApprovedBy` của phiếu **giải chấp** trở thành
    //   `FinishDate`/`FinishBy` của dòng **thế chấp** — "duyệt giải chấp" chính là "kết thúc thế chấp".
    //   Cùng tên trường mà khác nghĩa hai bên; chép thẳng tên sang là sai.
    // 🔴 `ReqDMNo` trên dòng thế chấp là **CON TRỎ** sang phiếu giải chấp (#140 đã ghi: tạo thì để
    //   trống, chỉ điền khi có đề nghị giải chấp). Thiếu nó thì **không lần ngược được** xe này
    //   được giải chấp bằng phiếu nào — cùng mô-típ cặp Old/Curr ở #348.
    // ⚠️ CHỈ làm ở nhánh DUYỆT: nguồn đặt cụm này trong hàm `_Approve`, từ chối thì không đụng.
    var mortgageClosed = 0;
    if (target == "A")
    {
        var vins = allLines.Select(x => x.VIN).Where(v => v != null).ToList();
        var rmLines = await db.ReqMortgageCars
            .Where(x => x.OrgId == t.OrgId && x.VIN != null && vins.Contains(x.VIN)).ToListAsync();
        foreach (var rm in rmLines)
        {
            rm.ReqDMNo = h.ReqRedeemNo;      // con trỏ sang phiếu giải chấp
            rm.RMDtlStatus = target;
            rm.FinishDate = stampAt;         // = ApprovedDate của phiếu giải chấp
            rm.FinishBy = h.ApprovedBy;      // = ApprovedBy của phiếu giải chấp
            rm.LogLUDateTime = stampAt; rm.LogLUBy = h.ApprovedBy;
            mortgageClosed++;
        }
    }
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        h.Id, h.Status,
        // #352: số dòng THẾ CHẤP được đóng theo — phải khớp số VIN của phiếu giải chấp.
        mortgageClosed,
        mortgageNote = target == "A" && mortgageClosed == 0
            ? "Không tìm thấy dòng thế chấp nào khớp VIN — kiểm tra lại: giải chấp lẽ ra phải đóng một dòng thế chấp."
            : null,
    });
}).RequireAuthorization();

// ===== Khóa đào tạo NVBH + tham gia (TrainingCourse/TrainingParticipant — port 1:1 FrmMst_TrainingCreate/Mng + FrmMst_TrainingDtlCreate/Mng, 2010.HTC/Admin) =====
app.MapGet("/api/trainingcourses", async (AppDbContext db, ITenantContext t, string? q, bool? all) =>
{
    var qry = db.TrainingCourses.Where(x => x.OrgId == t.OrgId);
    if (all != true) qry = qry.Where(x => x.FlagActive == "1");
    if (!string.IsNullOrWhiteSpace(q)) qry = qry.Where(x => x.TrainingUserCode.Contains(q!) || x.TrainingName!.Contains(q!) || x.TrainerName!.Contains(q!));
    var items = await qry.OrderBy(x => x.TrainingUserCode).Take(500).Select(x => new { x.Id, x.TrainingUserCode, x.TrainingName, x.Department, x.DealerCode, x.TrainerCode, x.TrainerName, x.Description, x.FlagActive }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/trainingcourses", async (TrainingCourseDto dto, AppDbContext db, ITenantContext t) =>
{
    var code = (dto.TrainingUserCode ?? "").Trim();
    if (string.IsNullOrWhiteSpace(code)) return Results.BadRequest(new { error = "Chưa nhập mã khóa đào tạo." });
    if (string.IsNullOrWhiteSpace((dto.TrainingName ?? "").Trim())) return Results.BadRequest(new { error = "Chưa nhập tên khóa đào tạo." });
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Chưa chọn đại lý." });
    if (string.IsNullOrWhiteSpace(dto.TrainerCode)) return Results.BadRequest(new { error = "Chưa chọn loại giảng viên." });
    // Guard: giảng viên nội bộ bắt buộc nhập tên (FrmMst_TrainingCreate line 73-79)
    if (dto.TrainerCode.Trim() == "NOIBO" && string.IsNullOrWhiteSpace(dto.TrainerName))
        return Results.BadRequest(new { error = "Giảng viên nội bộ: bắt buộc nhập tên giảng viên." });
    var row = await db.TrainingCourses.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.TrainingUserCode == code);
    if (row is null) { row = new TrainingCourse { OrgId = t.OrgId, TrainingUserCode = code }; db.TrainingCourses.Add(row); }
    row.TrainingName = dto.TrainingName; row.Department = dto.Department; row.DealerCode = dto.DealerCode; row.TrainerCode = dto.TrainerCode; row.TrainerName = dto.TrainerName; row.Description = dto.Description; row.UpdatedAt = DateTime.Now;
    if (!string.IsNullOrWhiteSpace(dto.FlagActive)) row.FlagActive = dto.FlagActive!;
    await db.SaveChangesAsync();
    return Results.Ok(new { row.Id, row.TrainingUserCode, row.TrainingName, row.FlagActive });
}).RequireAuthorization();

