}).RequireAuthorization();

// ===== 🔴 #245 TRA PHỤ TÙNG TST THEO NHIỀU MÃ — `TST_Mst_Part_Get01` (BizCarSv.Service.cs:18409) =====
// Màn: `Views/TST/FrmTSTPart_Search.cs` (744 dòng, DMSCarSv/TST). BƯỚC 3B: md5 `5e5d6f20` — KHỚP 2 máy.
//
// 🔴 Ô `txtPartCodeMulti` cho nhập **NHIỀU MÃ, mỗi mã một DÒNG**; form `Split("\r\n")` rồi **nối lại bằng
//    `", "`** thành một chuỗi gửi đi (:311-327). Nếu API lỗi, nguồn báo đúng câu:
//    "Mã phụ tùng ngăn cách nhau bởi dấu phẩy!" (:18500).
//    ⇒ endpoint nhận `codes` và **tách theo cả dấu phẩy LẪN xuống dòng**, giữ đúng cách người dùng nhập.
// ⚠️ Nguồn gọi **API Bravo** (GetToken → CallBravo) chứ không query DB; MiniHTC tra bảng `TstParts` đã đồng
//    bộ sẵn (#212 `/api/tstparts/sync-all`) — nợ lớp gọi Bravo trực tiếp vẫn còn.
app.MapGet("/api/tstparts", async (AppDbContext db, ITenantContext t, string? q, string? group, bool? all,
    string? codes) =>
{
    var qry = db.TstParts.Where(x => x.OrgId == t.OrgId);
    if (all != true) qry = qry.Where(x => x.FlagActive == "1");
    if (!string.IsNullOrWhiteSpace(group)) qry = qry.Where(x => x.PartGroup == group);
    if (!string.IsNullOrWhiteSpace(q)) qry = qry.Where(x => x.TSTPartCode.Contains(q!) || x.VieName!.Contains(q!) || x.VieNameHTC!.Contains(q!));
    if (!string.IsNullOrWhiteSpace(codes))
    {
        // tách theo dấu phẩy, xuống dòng, chấm phẩy — người dùng dán từ Excel hay gõ tay đều nhận
        var list = codes.Split(new[] { ',', '\n', '\r', ';' }, StringSplitOptions.RemoveEmptyEntries)
                        .Select(x => x.Trim().ToUpperInvariant())
                        .Where(x => x.Length > 0).Distinct().ToList();
        if (list.Count == 0)
            return Results.BadRequest(new { error = "Mã phụ tùng ngăn cách nhau bởi dấu phẩy!" });
        qry = qry.Where(x => list.Contains(x.TSTPartCode));
    }
    var items = await qry.OrderBy(x => x.TSTPartCode).Take(500).Select(x => new
    {
        x.Id, x.TSTPartCode, x.VieNameHTC, x.VieName, x.EngName, x.Unit, x.VAT, x.TSTPrice,
        x.PartGroup, x.PartType, x.FlagActive, x.LUDTime,
        // #245: 16 cột bổ sung (§12 — có ở cả GET lẫn POST)
        // ===== 🔴 #262 CỘT DB THẬT (`TblTSTMSTPart`) vs CỘT CỦA DATATABLE API (#245) =====
        // Nhóm dưới đây là **cột DB** theo lớp hằng `TblTSTMSTPart` (DbDefine.cs:695-721, md5 `d373e758`).
        x.TSTPriceBefore, x.TSTCost, x.DateEffect, x.TSTUnit,
        x.GroupCode, x.GroupName, x.TypeCode, x.TypeName,
        x.TSTWarrantyPrice, x.TSTUrgentPrice, x.UpdateBy, x.UpdateDateTime, x.LUBy,
        // Nhóm dưới là cột của **DataTable trả về từ Bravo** (#245) — giữ để không mất dữ liệu API.
        x.MinOrderQuantity,
        x.TSTPriceList, x.TSTPriceUrgent, x.TSTPriceWarranty, x.TaxRate,
        x.DongAnhStockStatus, x.CaiMepStockStatus, x.HoChiMinhStockStatus,
        x.TSTPartCodeNew, x.TSTPartCodeOld, x.Remark, x.ModelList,
        x.Length, x.Width, x.Height,
    }).ToListAsync();   // #212 §12 + #245
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/tstparts", async (TstPartDto dto, AppDbContext db, ITenantContext t) =>
{
    var code = (dto.TSTPartCode ?? "").Trim();
    if (string.IsNullOrWhiteSpace(code)) return Results.BadRequest(new { error = "Chưa nhập mã phụ tùng TST." });
    // #249: `FrmTST_Mst_Exchange_Unit.cs` kiểm `regex.IsMatch(strTSTPartCode)` / `(tstPartCode)`
    if (HasSpecialChar(code))
        return Results.BadRequest(new { error = "Mã vật tư không được phép chứa các ký tự đặc biệt", code });
    if (dto.TSTPrice < 0 || dto.VAT < 0) return Results.BadRequest(new { error = "Giá/VAT không được âm." });
    var row = await db.TstParts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.TSTPartCode == code);
    if (row is null) { row = new TstPart { OrgId = t.OrgId, TSTPartCode = code }; db.TstParts.Add(row); }
    row.VieNameHTC = dto.VieNameHTC; row.VieName = dto.VieName; row.EngName = dto.EngName; row.Unit = dto.Unit; row.VAT = dto.VAT; row.TSTPrice = dto.TSTPrice; row.PartGroup = dto.PartGroup; row.PartType = dto.PartType; row.UpdatedAt = DateTime.Now;
    // #245: 16 cột bổ sung — chỉ ghi đè khi client CÓ truyền, để lệnh đồng bộ (#212) không xoá mất
    //   dữ liệu do màn nhập tay điền.
    // #262: 13 cột DB thật — chỉ ghi đè khi client CÓ truyền (giống nhóm #245).
    if (dto.TSTPriceBefore is not null) row.TSTPriceBefore = dto.TSTPriceBefore;
    if (dto.TSTCost is not null) row.TSTCost = dto.TSTCost;
    if (dto.DateEffect is not null) row.DateEffect = dto.DateEffect;
    if (dto.TSTUnit is not null) row.TSTUnit = dto.TSTUnit;
    if (dto.GroupCode is not null) row.GroupCode = dto.GroupCode;
    if (dto.GroupName is not null) row.GroupName = dto.GroupName;
    if (dto.TypeCode is not null) row.TypeCode = dto.TypeCode;
    if (dto.TypeName is not null) row.TypeName = dto.TypeName;
    if (dto.TSTWarrantyPrice is not null) row.TSTWarrantyPrice = dto.TSTWarrantyPrice;
    if (dto.TSTUrgentPrice is not null) row.TSTUrgentPrice = dto.TSTUrgentPrice;
    if (dto.UpdateBy is not null) row.UpdateBy = dto.UpdateBy;
    if (dto.UpdateDateTime is not null) row.UpdateDateTime = dto.UpdateDateTime;
    if (dto.LUBy is not null) row.LUBy = dto.LUBy;
    if (dto.MinOrderQuantity is not null) row.MinOrderQuantity = dto.MinOrderQuantity;
    if (dto.TSTPriceList is not null) row.TSTPriceList = dto.TSTPriceList;
    if (dto.TSTPriceUrgent is not null) row.TSTPriceUrgent = dto.TSTPriceUrgent;
    if (dto.TSTPriceWarranty is not null) row.TSTPriceWarranty = dto.TSTPriceWarranty;
    if (dto.TaxRate is not null) row.TaxRate = dto.TaxRate;
    if (dto.DongAnhStockStatus is not null) row.DongAnhStockStatus = dto.DongAnhStockStatus;
    if (dto.CaiMepStockStatus is not null) row.CaiMepStockStatus = dto.CaiMepStockStatus;
    if (dto.HoChiMinhStockStatus is not null) row.HoChiMinhStockStatus = dto.HoChiMinhStockStatus;
    if (dto.TSTPartCodeNew is not null) row.TSTPartCodeNew = dto.TSTPartCodeNew;
    if (dto.TSTPartCodeOld is not null) row.TSTPartCodeOld = dto.TSTPartCodeOld;
    if (dto.Remark is not null) row.Remark = dto.Remark;
    if (dto.ModelList is not null) row.ModelList = dto.ModelList;
    if (dto.Length is not null) row.Length = dto.Length;
    if (dto.Width is not null) row.Width = dto.Width;
    if (dto.Height is not null) row.Height = dto.Height;
    if (!string.IsNullOrWhiteSpace(dto.FlagActive)) row.FlagActive = dto.FlagActive!;
    await db.SaveChangesAsync();
    return Results.Ok(new { row.Id, row.TSTPartCode, row.TSTPrice, row.FlagActive });
}).RequireAuthorization();

// ===== 🔴 #212 ĐỒNG BỘ TOÀN BỘ PHỤ TÙNG TỪ HỆ TST/BRAVO — `TST_SavePartAll` =====
// Nguồn: DMSCarSv `V20.2023.Release.V2/TERP.BizCarSv/BizCarSv.Bravo.cs:79` (469 dòng).
// BƯỚC 3B: md5 CẢ FILE `44509215` (469 dòng) KHỚP 2 máy (laptop `.Release.V2` ≡ máy 150 `.Release`).
// Màn gốc: `TERP.HTCServiceClient/Views/Bravo/FrmBravo.cs` (95 dòng) — ba nút:
//   `btnCancel` · `btnGetAll` (gọi `TST_GetAllPart` lấy dữ liệu từ hệ TST) · `BtnUpdateTSTPart` (ghi xuống DB).
//   ⚠️ Nút thứ ba viết HOA đầu (`Btn...`) nên grep `"private void btn"` bỏ sót — đã ghi thành luật.
//
// 🔴 HAI ĐIỂM CỐT TỬ của nguồn:
//  1. **Guard TOÀN LÔ trước, xoá sau**: duyệt hết mọi dòng, dòng nào `TSTPartCode` rỗng thì ném
//     `TST_SavePartAll_InvalidTSTPartCode` — kiểm XONG mới tới bước xoá. Một dòng hỏng ⇒ **huỷ cả lô**,
//     bảng cũ còn nguyên.
//  2. **REPLACE-ALL, KHÔNG phải upsert**: nguồn `delete t from TST_Mst_Part` (xoá SẠCH bảng) rồi insert lại
//     toàn bộ. ⇒ mã nào không có trong lô mới sẽ **BIẾN MẤT**. Đây là chủ ý của nguồn, không phải thiếu sót.
//
// Nguồn chỉ ghi **3 cột**: `TSTPartCode` · `TSTPrice` · `LUDTime` (các cột tên/đơn vị/nhóm KHÔNG được ghi
//   ở lệnh này — chúng do màn `FrmTST_Mst_Part` nhập tay, tức `POST /api/tstparts`). Ghi song song `_dbWH` (nợ).
// ⚠️ Form gốc còn chặn bằng **key cứng** (`strKeyFix` nhập tay trên form) — đó là bảo vệ ở tầng client,
//   KHÔNG port thành tham số API; API đã có `RequireAuthorization()`.
app.MapPost("/api/tstparts/sync-all", async (List<TstPartSyncDto> rows, AppDbContext db, ITenantContext t) =>
{
    rows ??= new List<TstPartSyncDto>();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Lô đồng bộ rỗng." });

    // (1) guard TOÀN LÔ — kiểm hết trước khi chạm dữ liệu.
    for (var i = 0; i < rows.Count; i++)
        if (string.IsNullOrWhiteSpace(rows[i].TSTPartCode))
            return Results.BadRequest(new { error = "Mã phụ tùng TST không được rỗng — huỷ toàn bộ lô.", rowIndex = i });

    // (2) REPLACE-ALL: xoá sạch rồi ghi lại, đúng như nguồn.
    var old = await db.TstParts.Where(x => x.OrgId == t.OrgId).ToListAsync();
    db.TstParts.RemoveRange(old);

    var now = DateTime.Now;
    foreach (var r in rows)
        db.TstParts.Add(new TstPart
        {
            OrgId = t.OrgId,
            TSTPartCode = r.TSTPartCode!.Trim(),
            TSTPrice = r.TSTPrice,
            LUDTime = now
        });

    await db.SaveChangesAsync();
    return Results.Ok(new { deleted = old.Count, inserted = rows.Count, luDTime = now,
        note = "REPLACE-ALL đúng nguồn: mã không có trong lô mới sẽ biến mất." });
}).RequireAuthorization();

