app.MapGet("/api/serservicetypes", async (AppDbContext db, ITenantContext t, string? q, bool? all) =>
{
    var qry = db.SerServiceTypes.Where(x => x.OrgId == t.OrgId);
    if (all != true) qry = qry.Where(x => x.FlagActive == "1");
