// Cập nhật hàng loạt (khớp btnApply_Click/DealerSalesDealUpdateAttachFileMulti gốc) — chỉ dòng có FileNameNew mới upsert.
app.MapPost("/api/dealerdealattaches", async (DealerDealAttachBatchDto dto, AppDbContext db, ITenantContext t) =>
{
    var rows = (dto.Rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.DealNo) && !string.IsNullOrWhiteSpace(r.FileNameNew)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Không có dữ liệu được thay đổi" });
    int added = 0, updated = 0;
    foreach (var r in rows)
    {
        var no = r.DealNo!.Trim();
        var row = await db.DealerDealAttaches.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealNo == no);
        if (row is null) { row = new DealerDealAttach { OrgId = t.OrgId, DealNo = no }; db.DealerDealAttaches.Add(row); added++; } else updated++;
        row.FileName = r.FileNameNew!.Trim(); row.FilePath = r.FilePathNew; row.UpdatedAt = DateTime.Now;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { added, updated });
}).RequireAuthorization();

// ===== Đề nghị đăng ký xe lái thử (CarTestCar — port 1:1 FrmNewRegister_TestCar, 2010.HTC/Sales) =====
app.MapGet("/api/cartestcars", async (AppDbContext db, ITenantContext t, string? dealer, string? q) =>
{
    var qry = db.CarTestCars.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) qry = qry.Where(x => x.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(q)) qry = qry.Where(x => x.TestCarCode.Contains(q!));
    var items = await qry.OrderByDescending(x => x.Id).Take(500).Select(x => new
    { x.TestCarCode, x.DealerCode, x.Remark, x.CreatedAt, x.TestCarStatus, x.ApprovedAt, x.ApprovedBy, x.RejectReason,
      lines = db.CarTestCarDtls.Count(l => l.OrgId == t.OrgId && l.TestCarId == x.Id) }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapGet("/api/cartestcars/{no}", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim();
    var h = await db.CarTestCars.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.TestCarCode == no);
    if (h is null) return Results.NotFound(new { no });
    var lines = await db.CarTestCarDtls.Where(l => l.OrgId == t.OrgId && l.TestCarId == h.Id)
        .Select(l => new { l.CarId, l.VIN, l.ModelCode, l.SpecCode, l.SpecDescription, l.SoDonHang, l.ColorCode, l.ColorName, l.EffDateStart, l.EffDateEnd, l.UnitPriceActual,
            l.TestCarStatusDtl }).ToListAsync();
    return Results.Ok(new { h.TestCarCode, h.DealerCode, h.Remark, h.CreatedAt, h.TestCarStatus, h.ApprovedAt, h.ApprovedBy, h.RejectReason, lines });
}).RequireAuthorization();

// Lưu đề nghị (khớp Car_TestCar_Save gốc: TestCarCode tự sinh nếu trống; đã tồn tại → thay toàn bộ dòng VIN, khớp hành vi "sửa đề nghị")
app.MapPost("/api/cartestcars", async (CarTestCarDto dto, AppDbContext db, ITenantContext t) =>
{
    var lines = dto.Lines ?? new List<CarTestCarLineDto>();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Lưới dữ liệu trống!" });

    var no = string.IsNullOrWhiteSpace(dto.TestCarCode) ? "TC" + DateTime.Now.ToString("yyMMddHHmmss") : dto.TestCarCode.Trim();
    var h = await db.CarTestCars.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.TestCarCode == no);
    if (h is null) { h = new CarTestCar { OrgId = t.OrgId, TestCarCode = no }; db.CarTestCars.Add(h); await db.SaveChangesAsync(); }
    else { db.CarTestCarDtls.RemoveRange(db.CarTestCarDtls.Where(l => l.OrgId == t.OrgId && l.TestCarId == h.Id)); }
    h.DealerCode = dto.DealerCode; h.Remark = dto.Remark;

    // 🔴 LUẬT CHỐNG ĐĂNG KÝ TRÙNG XE (nguồn: mycheck_Car_TestCar_CarId, BizHTC.Car.cs:4942-5008):
    // một CarId KHÔNG được nằm ở >1 đề nghị có trạng thái DÒNG thuộc ('P','A').
    var carIds = lines.Select(x => (x.CarId ?? "").Trim()).Where(x => x.Length > 0).ToList();
    if (carIds.Count > 0)
    {
        var clash = await db.CarTestCarDtls
            .Where(x => x.OrgId == t.OrgId && x.TestCarId != h.Id
                        && carIds.Contains(x.CarId)
                        && (x.TestCarStatusDtl == "P" || x.TestCarStatusDtl == "A"))
            .Select(x => x.CarId).FirstOrDefaultAsync();
        if (clash != null)
            return Results.BadRequest(new { error = $"Xe {clash} đã nằm trong một đề nghị xe lái thử khác đang chờ duyệt hoặc đã duyệt." });
    }

    foreach (var l in lines)
        db.CarTestCarDtls.Add(new CarTestCarDtl
        {
            OrgId = t.OrgId, TestCarId = h.Id, CarId = l.CarId ?? "", VIN = (l.Vin ?? "").Trim().ToUpperInvariant(), ModelCode = l.ModelCode,
            SpecCode = l.SpecCode, SpecDescription = l.SpecDescription, SoDonHang = l.SoDonHang, ColorCode = l.ColorCode, ColorName = l.ColorName,
            EffDateStart = l.EffDateStart, EffDateEnd = l.EffDateEnd, UnitPriceActual = l.UnitPriceActual,
            TestCarStatusDtl = "P",
        });
    await db.SaveChangesAsync();
    return Results.Ok(new { h.TestCarCode, lines = lines.Count });
}).RequireAuthorization();

// 🔴 DUYỆT / TỪ CHỐI đề nghị xe lái thử — port cũ (bộ CarTestCar) KHÔNG có vòng đời duyệt nào.
app.MapPost("/api/cartestcars/{no}/action", async (
    string no, string action, AppDbContext db, ITenantContext t,
    System.Security.Claims.ClaimsPrincipal user, string? reason) =>
{
    no = no.Trim();
    var act = (action ?? "").Trim().ToLowerInvariant();
    if (act != "approve" && act != "reject") return Results.BadRequest(new { error = "action = approve|reject" });
    var h = await db.CarTestCars.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.TestCarCode == no);
    if (h is null) return Results.NotFound(new { no });
    if (h.TestCarStatus != "P")
        return Results.BadRequest(new { error = $"Đề nghị đang '{h.TestCarStatus}', chỉ xử lý khi 'P'." });
    if (act == "reject" && string.IsNullOrWhiteSpace(reason))
        return Results.BadRequest(new { error = "Từ chối phải ghi lý do." });

    var target = act == "approve" ? "A" : "R";
    h.TestCarStatus = target;
    h.ApprovedAt = DateTime.Now; h.ApprovedBy = user.Identity?.Name ?? "system";
    if (act == "reject") h.RejectReason = reason!.Trim();
    foreach (var l in await db.CarTestCarDtls.Where(x => x.OrgId == t.OrgId && x.TestCarId == h.Id).ToListAsync())
        l.TestCarStatusDtl = target;
    await db.SaveChangesAsync();
    // 🔴 #190: guard HẬU-GHI của nguồn (`mycheck_Car_TestCar_CarId`) — gọi ở CẢ NĂM hàm của cụm.
    var badUniq = await CheckTestCarCarIdUniqueAsync(db, t, h.Id);
    if (badUniq is not null) return badUniq;
    return Results.Ok(new { h.TestCarCode, status = h.TestCarStatus, h.ApprovedAt, h.RejectReason });
}).RequireAuthorization();

// ===== #190 Xe chạy thử: `Car_TestCar_Finished` + `Car_TestCarDtl_Cancel`/`_Reject` + GUARD HẬU-GHI =====
// Nguồn: `TERP.BizHTC/BizHTC.Car.cs` (csproj) — `_SaveX`(5710) · `_ApproveX`(6384) · `_FinishedX`(6762)
//   · `Dtl_CancelX`(7215) · `Dtl_RejectX`(7677); helper `mycheck_Car_TestCar_CarId`(4947).
// BƯỚC 3B: md5 CẢ FILE `961695a5` KHỚP 2 máy. Đã liệt kê ranh giới hàm trước khi đọc.
// 🔴 TWIN: cụm `Car_TestCar_*` **CHỈ có ở WS 64-bit**; WS 32-bit **không có hàm nào**.
//
// 🔴 Cách tìm ra: biến luật `C0-ducentesimusseptuagesimus` (#189, guard hậu-ghi) thành phép quét —
//    `grep "Port check\|PostCheck"` toàn biz. Khối *"Port check: 1 CarId chỉ thuộc 1 đề nghị đăng ký
//    lái thử trạng thái chi tiết P/A"* xuất hiện ở **CẢ NĂM** hàm của cụm này.
//
// 🔴 GUARD HẬU-GHI (`mycheck_Car_TestCar_CarId`, 4947): sau khi lưu, nguồn gom các `CarId` của phiếu
//    rồi đếm trên **toàn bảng** `Car_TestCarDtl` những dòng `TestCarStatusDtl in ('P','A')`;
//    `CountCarId > 1` ⇒ ném `mycheck_Car_TestCar_CarId_InvalidCarId`.
//    ⇒ Một xe chỉ được nằm trong ĐÚNG MỘT đề nghị còn sống. Port cũ **chỉ ghi luật này trong ghi chú
//    `/statuses`** mà KHÔNG endpoint nào thực thi.
static async Task<IResult?> CheckTestCarCarIdUniqueAsync(AppDbContext db, ITenantContext t, long testCarId)
{
    var carIds = await db.CarTestCarDtls
        .Where(x => x.OrgId == t.OrgId && x.TestCarId == testCarId)
        .Select(x => x.CarId).ToListAsync();
    if (carIds.Count == 0) return null;
    var dup = await db.CarTestCarDtls
        .Where(x => x.OrgId == t.OrgId && carIds.Contains(x.CarId)
                 && (x.TestCarStatusDtl == "P" || x.TestCarStatusDtl == "A"))
        .GroupBy(x => x.CarId)
        .Where(g => g.Count() > 1)
        .Select(g => g.Key).FirstOrDefaultAsync();
    return dup is null ? null
        : Results.BadRequest(new { error = $"Xe {dup} đang nằm trong nhiều hơn một đề nghị chạy thử còn hiệu lực (P/A).", carId = dup });
}

// 🔴 `Car_TestCar_Finished` (6762): guard header `TestCarStatus = Approved ("A")` → `"F"`,
//    ghi `FinishedDate`/`FinishedBy`. Nguồn còn kiểm xe tồn tại + còn hoạt động trước khi kết thúc.
app.MapPost("/api/cartestcars/{no}/finish", async (string no, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim();
    var h = await db.CarTestCars.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.TestCarCode == no);
    if (h is null) return Results.NotFound(new { no });
    if (h.TestCarStatus != "A")
        return Results.BadRequest(new { error = $"Đề nghị đang '{h.TestCarStatus}' — chỉ kết thúc khi đã duyệt (A)." });
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    h.TestCarStatus = "F"; h.FinishedDate = now; h.FinishedBy = who;
    foreach (var l in await db.CarTestCarDtls.Where(x => x.OrgId == t.OrgId && x.TestCarId == h.Id).ToListAsync())
        l.TestCarStatusDtl = "F";
    await db.SaveChangesAsync();
    var bad = await CheckTestCarCarIdUniqueAsync(db, t, h.Id);
    if (bad is not null) return bad;
    return Results.Ok(new { h.TestCarCode, status = h.TestCarStatus, h.FinishedDate, h.FinishedBy });
}).RequireAuthorization();

// 🔴 `Car_TestCarDtl_Cancel` (7215) / `_Reject` (7677) — thao tác theo **DÒNG**, không phải header.
//    Guard trạng thái dòng **NGƯỢC NHAU**:
//      · `_Cancel` đòi `TestCarStatusDtl = Finished ("F")` — huỷ dòng ĐÃ kết thúc;
//      · `_Reject` đòi `TestCarStatusDtl = Approved ("A")` — từ chối dòng ĐÃ duyệt.
//    Cả hai còn kiểm xe tồn tại + `FlagTestCar` (cờ "xe đang là xe chạy thử"): `_Cancel` chặn khi cờ
//    đang Inactive, `_Reject` chặn khi cờ đang Active — cũng ngược nhau.
app.MapPost("/api/cartestcars/{no}/lines/{carId}/{action}", async (string no, string carId, string action,
    AppDbContext db, ITenantContext t) =>
{
    if (action is not ("cancel" or "reject")) return Results.BadRequest(new { error = "action = cancel|reject" });
    no = no.Trim(); carId = carId.Trim();
    var h = await db.CarTestCars.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.TestCarCode == no);
    if (h is null) return Results.NotFound(new { no });
    var l = await db.CarTestCarDtls.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.TestCarId == h.Id && x.CarId == carId);
    if (l is null) return Results.NotFound(new { no, carId });

    var want = action == "cancel" ? "F" : "A";
    if (l.TestCarStatusDtl != want)
        return Results.BadRequest(new { error = $"Dòng xe {carId} đang '{l.TestCarStatusDtl}' — {(action == "cancel" ? "chỉ huỷ dòng ĐÃ kết thúc (F)" : "chỉ từ chối dòng ĐÃ duyệt (A)")}." });

    l.TestCarStatusDtl = action == "cancel" ? "C" : "R";
    await db.SaveChangesAsync();
    var bad = await CheckTestCarCarIdUniqueAsync(db, t, h.Id);
    if (bad is not null) return bad;
    return Results.Ok(new { h.TestCarCode, l.CarId, statusDtl = l.TestCarStatusDtl });
}).RequireAuthorization();

app.MapGet("/api/cartestcars/statuses", () => Results.Ok(new
{
    statuses = new[] {
        new { code = "P", name = "Chờ duyệt" },
        new { code = "A", name = "Đã duyệt" },
        new { code = "R", name = "Từ chối" } },
    note = "Một xe (CarId) chỉ được nằm trong ĐÚNG MỘT đề nghị đang ở 'P' hoặc 'A' — #190 đã THỰC THI bằng guard hậu-ghi, trước đó chỉ là ghi chú.",
    statusesDtl = new[] { "P", "A", "F", "C", "R" },
})).RequireAuthorization();

// Xóa đề nghị (khớp Car_TestCar_Save với flagIsDelete=1 gốc)
app.MapDelete("/api/cartestcars/{no}", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim();
    var h = await db.CarTestCars.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.TestCarCode == no);
    if (h is null) return Results.NotFound(new { no });
    db.CarTestCarDtls.RemoveRange(db.CarTestCarDtls.Where(l => l.OrgId == t.OrgId && l.TestCarId == h.Id));
    db.CarTestCars.Remove(h);
    await db.SaveChangesAsync();
    return Results.Ok(new { deleted = no });
}).RequireAuthorization();

// ===== Đơn hàng gốc DMS40 (Dms40SoRoot — port 1:1 FrmUpgradeMngOrderDealer/FrmUpgradeOrderApprove/FrmUpgradeOrderApprovePlan, 2010.HTC/Sales/Upgrade) =====
// ĐƠN GIẢN HOÁ: bỏ nhánh "duyệt đặc biệt PA→F"/mirror WH/join Model-Spec-Color master — quá sâu để trace 1:1 trong 1 fire.
app.MapGet("/api/dms40/soroots", async (AppDbContext db, ITenantContext t, string? dealer, string? status, string? q) =>
{
    var qry = db.Dms40SoRoots.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) qry = qry.Where(x => x.DealerCode == dealer.Trim().ToUpperInvariant());
    if (!string.IsNullOrWhiteSpace(status)) qry = qry.Where(x => x.Status == status);
    if (!string.IsNullOrWhiteSpace(q)) qry = qry.Where(x => x.SORCode.Contains(q!));
    var items = await qry.OrderByDescending(x => x.Id).Take(500).Select(x => new
    { x.SORCode, x.SOType, x.DealerCode, x.SPCode, x.OrderMonth, x.Status, x.CreatedAt, x.ApprDTime,
      x.FinishDTime, x.FinishBy, x.GeneratedSoCode,
      lines = db.Dms40SoRootDetails.Count(l => l.OrgId == t.OrgId && l.SoRootId == x.Id) }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapGet("/api/dms40/soroots/{no}", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.Dms40SoRoots.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SORCode == no);
    if (h is null) return Results.NotFound(new { no });
    var lines = await db.Dms40SoRootDetails.Where(l => l.OrgId == t.OrgId && l.SoRootId == h.Id)
        .Select(l => new { l.ModelCode, l.SpecCode, l.ColorCode, l.UnitPriceInit, l.RequestedQuantity, l.Approved1Quantity, l.Approved2Quantity, l.CancelQuantityTotal, l.Remark,
            l.RequestedDate, l.Approved1Date, l.Approved2Date, l.SORStatusDtl }).ToListAsync();
    return Results.Ok(new { h.SORCode, h.SOType, h.DealerCode, h.SPCode, h.OrderMonth, h.ProductionMonth, h.ExpectedMonth, h.Status, h.CreatedAt, h.ApprDTime,
        h.FinishDTime, h.FinishBy, h.GeneratedSoCode, lines });
}).RequireAuthorization();

// Tạo đơn hàng gốc (khớp DMS40_Ord_SalesOrderRoot_Save flagIsDelete=0 gốc)
app.MapPost("/api/dms40/soroots", async (Dms40SoRootDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Cần mã đại lý." });
    // WinForm line 810: OrderMonth bắt buộc
    if (dto.OrderMonth is null) return Results.BadRequest(new { error = "Chưa chọn tháng đơn hàng." });
    var lines = dto.Lines ?? new List<Dms40SoRootLineDto>();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Không có dữ liệu model." });

    var no = string.IsNullOrWhiteSpace(dto.SORCode) ? "SOR" + DateTime.Now.ToString("yyMMddHHmmss") : dto.SORCode.Trim().ToUpperInvariant();
    if (await db.Dms40SoRoots.AnyAsync(x => x.OrgId == t.OrgId && x.SORCode == no))
        return Results.BadRequest(new { error = $"Số {no} đã tồn tại!" });
    var h = new Dms40SoRoot { OrgId = t.OrgId, SORCode = no, SOType = dto.SOType, DealerCode = dto.DealerCode.Trim().ToUpperInvariant(), SPCode = dto.SPCode, OrderMonth = dto.OrderMonth, Status = "P" };
    db.Dms40SoRoots.Add(h); await db.SaveChangesAsync();
    foreach (var l in lines)
        db.Dms40SoRootDetails.Add(new Dms40SoRootDetail { OrgId = t.OrgId, SoRootId = h.Id, ModelCode = l.ModelCode, SpecCode = l.SpecCode, ColorCode = l.ColorCode, UnitPriceInit = l.UnitPriceInit, RequestedQuantity = l.RequestedQuantity, Remark = l.Remark,
            RequestedDate = l.RequestedDate, SORStatusDtl = "P" });
    await db.SaveChangesAsync();
    return Results.Ok(new { h.SORCode, h.Status, lines = lines.Count });
}).RequireAuthorization();

// Duyệt số lượng theo dòng (khớp btnApprove_Click/DMS40_Ord_SalesOrderRoot_Approve gốc: P→A) — Approved1Quantity theo ModelCode+SpecCode+ColorCode.
app.MapPost("/api/dms40/soroots/{no}/approve", async (string no, Dms40SoRootApproveDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.Dms40SoRoots.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SORCode == no);
    if (h is null) return Results.NotFound(new { no });
    if (h.Status != "P") return Results.BadRequest(new { error = "Chỉ có thể duyệt khi trạng thái là P (chờ duyệt)." });
    var rows = dto.Lines ?? new List<Dms40SoRootApproveLineDto>();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Không có dữ liệu được duyệt." });
    var lines = await db.Dms40SoRootDetails.Where(l => l.OrgId == t.OrgId && l.SoRootId == h.Id).ToListAsync();
    int updated = 0;
    foreach (var r in rows)
    {
        var l = lines.FirstOrDefault(x => x.ModelCode == r.ModelCode && x.SpecCode == r.SpecCode && x.ColorCode == r.ColorCode);
        if (l is null) continue;
        if (r.Approved1Quantity > l.RequestedQuantity) return Results.BadRequest(new { error = $"Model {r.ModelCode}: số lượng duyệt vượt số lượng yêu cầu." });
        l.Approved1Quantity = r.Approved1Quantity;
        // #163: nguồn ghi NGÀY duyệt cấp 1 theo TỪNG DÒNG — bước hoàn tất đọc lại cột này
        // để map sang `ApprovedDate` của dòng đơn bán, và để sao sang `Approved2Date`.
        l.Approved1Date = r.Approved1Date ?? DateTime.Now;
        l.SORStatusDtl = "A";
        updated++;
    }
    h.Status = "A"; h.ApprDTime = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { h.SORCode, h.Status, updated });
}).RequireAuthorization();

// ===== #163 hoàn tất đơn hàng gốc DMS40 — `DMS40_Ord_SalesOrderRoot_Finish_New20210521` =====
// Nguồn: `TERP.BizHTC/DataWH/BizHTC.Order.cs:1478` (csproj 315), thân thật ở `..._FinishX_New20210521`.
// 🔴 TWIN: WS **64-bit** gọi `_New20210521`; WS **32-bit** vẫn gọi `_New20181119` (Biz.HTC.WH.cs:76779) ⇒ LIVE là bản 2021.
// BƯỚC 3B: hàm bắt đầu **cùng dòng 1478 ở CẢ HAI máy**, vùng 2551 dòng md5 `22c18bb1` KHỚP.
//
// 🔴 Port cũ chỉ làm HAI việc (đổi `Status = "F"` + `Approved2Quantity = Approved1Quantity`) — mất hẳn phần
//    NẶNG NHẤT của nghiệp vụ: hoàn tất đơn gốc là **TỰ SINH RA MỘT ĐƠN BÁN (`Ord_SalesOrder`) đã duyệt sẵn**.
app.MapPost("/api/dms40/soroots/{no}/finish", async (string no, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;

    var h = await db.Dms40SoRoots.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SORCode == no);
    if (h is null) return Results.NotFound(new { no });
    // `DMS40_Ord_SalesOrderRoot_CheckDB(..., strStatusListToCheck: SORStatus.Approved)`
    if (h.Status != "A") return Results.BadRequest(new { error = "Chỉ có thể hoàn tất khi trạng thái là A (đã duyệt)." });

    // `myCommon_CheckDealer(..., FlagExist: Active, FlagActiveList: Active)` — đại lý phải TỒN TẠI và còn HOẠT ĐỘNG.
    var dlr = await db.Dealers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealerCode == h.DealerCode);
    if (dlr is null) return Results.BadRequest(new { error = $"Đại lý {h.DealerCode} không tồn tại." });
    if (dlr.FlagActive != "1") return Results.BadRequest(new { error = $"Đại lý {h.DealerCode} đang ngừng hoạt động." });

    // 🔴 SINH MÃ ĐƠN BÁN THEO CHÍNH SÁCH BÁN — quy tắc HẬU TỐ của nguồn, và là một GUARD CHẶN:
    //    CSC → giữ nguyên mã đơn gốc; KCK/CCK/DLM/NG → mã gốc + "." + mã chính sách;
    //    chính sách khác (kể cả `CKTT` có trong bảng hằng) → LỖI `NotAllowSPCode`, KHÔNG cho hoàn tất.
    var sp = (h.SPCode ?? "").Trim().ToUpperInvariant();
    string soCode;
    if (sp == "CSC") soCode = h.SORCode;
    else if (sp is "KCK" or "CCK" or "DLM" or "NG") soCode = h.SORCode + "." + sp;
    else return Results.BadRequest(new { error = $"Chính sách bán \"{sp}\" không được phép hoàn tất đơn hàng gốc (chỉ CSC/KCK/CCK/DLM/NG).", sorCode = h.SORCode, spCode = sp });

    var lines = await db.Dms40SoRootDetails.Where(l => l.OrgId == t.OrgId && l.SoRootId == h.Id).ToListAsync();

    // ---- Sinh đơn bán: nguồn chạy chuỗi OrderSOCreateX → OrderSOApprove1X → OrderSOApprove2X ----
    //      ⇒ đơn bán ra đời ở trạng thái **A2 (đã duyệt cấp 2)** ngay, không qua tay người duyệt.
    //      Chỉ lấy dòng có `Approved1Quantity > 0` (điều kiện `where t.Approved1Quantity > 0` trong SQL nguồn).
    string? generated = null;
    var srcLines = lines.Where(l => l.Approved1Quantity > 0).ToList();
    if (srcLines.Count > 0)
    {
        if (await db.SalesOrders.AnyAsync(x => x.OrgId == t.OrgId && x.SoCode == soCode))
            return Results.BadRequest(new { error = $"Đơn bán {soCode} đã tồn tại — đơn hàng gốc này có thể đã được hoàn tất.", soCode });

        var so = new SalesOrder
        {
            OrgId = t.OrgId,
            SoCode = soCode,
            // Nguồn bê nguyên `SOType` và `DealerCode` của đơn gốc sang đơn bán.
            OrderType = string.IsNullOrWhiteSpace(h.SOType) ? "Plan" : h.SOType!,
            DealerCode = h.DealerCode,
            SPCode = sp,
            // Chuỗi Create→Approve1→Approve2 chạy liền ⇒ trạng thái cuối là "A2".
            Status = "A2",
            CreatedAt = now, Approved1At = now, Approved2At = now, ApprovedBy1 = who
        };
        db.SalesOrders.Add(so);
        await db.SaveChangesAsync();

        foreach (var l in srcLines)
            db.SalesOrderLines.Add(new SalesOrderLine
            {
                OrgId = t.OrgId, SalesOrderId = so.Id,
                ModelCode = l.ModelCode ?? "", SpecCode = l.SpecCode, ColorCode = l.ColorCode,
                RequestedQuantity = (int)l.RequestedQuantity, RequestedDate = l.RequestedDate,
                UnitPrice = l.UnitPriceInit, UnitPriceInit = l.UnitPriceInit,
                // `t.Approved1Quantity AS ApprovedQuantity` · `t.Approved1Date AS ApprovedDate` trong SQL nguồn.
                ApprovedQuantity = (int)l.Approved1Quantity, ApprovedDate = l.Approved1Date,
                MapVINRanking = 5.0m,     // Approve1 của nguồn gán CỨNG 5.0
                Remark = l.Remark
            });
        generated = soCode;
    }

    // ---- SaveDB: cập nhật header và TỪNG DÒNG của đơn gốc ----
    h.Status = "F"; h.FinishDTime = now; h.FinishBy = who; h.GeneratedSoCode = generated;
    foreach (var l in lines)
    {
        l.Approved2Quantity = l.Approved1Quantity;
        // Nguồn sao chép `Approved2Date = Approved1Date` (không nhập tay) và ghi trạng thái RIÊNG của dòng.
        l.Approved2Date = l.Approved1Date;
        l.SORStatusDtl = "F";
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { h.SORCode, h.Status, h.FinishDTime, h.FinishBy, generatedSoCode = generated, soLines = srcLines.Count });
}).RequireAuthorization();

// ===== 🔴 #208 HUỶ ĐƠN GỐC — `DMS40_Ord_SalesOrderRoot_Cancel1` (78681) / `Cancel2` (79242) =====
// Nguồn: `DataWH/Biz.HTC.WH.cs` (csproj <Compile> 272). TWIN FILE: hai hàm này CÒN ở
//   `DataWH/Biz.HTC.WH.Rel.20230823.cs` (74835/75396) — file đó KHÔNG có trong csproj ⇒ **FILE CHẾT** (xác định ở #200).
//
// 🔴 BƯỚC 3B — bài học đo đúng: md5 theo SỐ DÒNG cố định (78681-79800) cho kết quả LỆCH giữa 2 máy
//   (`2325b86e` vs `07dfeaa7`), nhưng diff cho thấy chỉ là **lệch offset 5 dòng** — bản 150 có thêm 5 dòng
//   ở TRƯỚC vùng này. Căn lại theo **MỐC HÀM** (150 tại 78686): md5 = `2325b86e` **KHỚP**. Nội dung y hệt.
//
// Hai lệnh, hai guard khác nhau — port cũ gộp thành một điều kiện `P or A` (đúng về TẬP HỢP, nên giữ),
//   nhưng bỏ sót phần GHI:
//     `Cancel1`: guard `SORStatus = SORStatus.Pending` ("P")   → `SORStatus = "C"`
//     `Cancel2`: guard `SORStatus = SORStatus.Approved` ("A")  → `SORStatus = "C"`
//   Cả hai đều ghi `CancelDTime` · `CancelBy` · `LogLUDateTime` · `LogLUBy`,
//   và 🔴 **CASCADE** `DMS40_Ord_SalesOrderRootDetail.SORStatusDtl = "C"` + `LogLU*` trên MỌI dòng chi tiết.
app.MapPost("/api/dms40/soroots/{no}/cancel", async (string no, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.Dms40SoRoots.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SORCode == no);
    if (h is null) return Results.NotFound(new { no });
    // Giữ điều kiện gộp: `Cancel1` nhận "P", `Cancel2` nhận "A" — hợp lại đúng bằng tập {P, A}.
    if (h.Status is not ("P" or "A")) return Results.BadRequest(new { error = "Chỉ có thể hủy khi trạng thái là P hoặc A." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    var branch = h.Status == "P" ? "Cancel1" : "Cancel2";   // ghi lại nhánh nguồn tương ứng
    h.Status = "C";
    h.CancelDTime = now; h.CancelBy = who;
    h.LogLUDateTime = now; h.LogLUBy = who;

    var dtls = await db.Dms40SoRootDetails.Where(x => x.OrgId == t.OrgId && x.SoRootId == h.Id).ToListAsync();
    foreach (var d in dtls) { d.SORStatusDtl = "C"; d.LogLUDateTime = now; d.LogLUBy = who; }

    await db.SaveChangesAsync();
    return Results.Ok(new { h.SORCode, h.Status, h.CancelDTime, h.CancelBy, branch, cancelledDetailRows = dtls.Count });
}).RequireAuthorization();

