        x.Id, x.VIN, x.InvoiceNoFactory, x.InvoiceFactoryDate, x.BillNo, x.CQNo, x.CONo, x.MortageBankCode, x.MortageStartDate, x.MortageEndDate, x.RedeemDate, x.UpdatedBy, x.UpdatedAt
    }).ToListAsync();
