app.MapGet("/api/carinvoicespecs", async (AppDbContext db, ITenantContext t, string? q, bool? all) =>
{
    var qry = db.CarInvoiceSpecs.Where(x => x.OrgId == t.OrgId);
    if (all != true) qry = qry.Where(x => x.FlagActive == "1");
