    h.MsReadStatus = "Y"; h.ReadAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { h.MsDlvNo, h.MsReadStatus, h.ReadAt });
}).RequireAuthorization();

