    {
        x.Id, x.DRNo, x.DealerCode, requestDate = x.RequestDate.HasValue ? x.RequestDate.Value.ToString("yyyy-MM-dd") : "", x.Status, x.Note,
        cars = db.DeliveryRequestDetails.Count(l => l.OrgId == t.OrgId && l.DeliveryRequestId == x.Id)
    }).ToListAsync();
