// ===== Quản lý giá vốn phụ tùng (PartCostSnapshot — port 1:1 FrmPartCostManagement/FrmCaluCost/FrmReportHistoryCost, TCMotor) =====
// Giá vốn bình quân gia quyền THEO KỲ — đúng công thức nguồn (biz Ser_PartCost_Calculate):
//   AverageCost = (TGD + TGN) / (SLD + SLN)
//     SLD/TGD = lượng & giá trị TỒN ĐẦU KỲ (phiếu nhập TRƯỚC FromDate)
//     SLN/TGN = lượng & giá trị NHẬP TRONG KỲ; TGN ĐÃ GỒM THUẾ:
//               sum(Price*Qty + VAT*0.01*Price*Qty)
// Bỏ trống FromDate ⇒ nguồn mặc định 1990-01-01 (tính từ đầu, coi như không có tồn đầu kỳ).
app.MapPost("/api/partcosts/calculate", async (
    PartCostCalculateDto? dto, AppDbContext db, ITenantContext t) =>
{
    var fromDate = dto?.FromDate ?? new DateTime(1990, 1, 1);
    var toDate = dto?.ToDate ?? DateTime.Today;
    if (toDate < fromDate) return Results.BadRequest(new { error = "Ngày cuối kỳ phải >= ngày đầu kỳ." });
    // Nguồn chốt mốc cuối kỳ tới HẾT NGÀY: CalculateDateTime = ToDate + " 23:59:59".
    var toDateEndOfDay = toDate.Date.AddDays(1).AddTicks(-1);

    var confirmedStockInIds = db.ServiceStockIns
        .Where(o => o.OrgId == t.OrgId && o.Status == "Confirmed")
        .Select(o => o.Id);

    var stockInLines = await (
        from line in db.ServiceStockInLines.Where(l => l.OrgId == t.OrgId && confirmedStockInIds.Contains(l.ServiceStockInId))
        join header in db.ServiceStockIns.Where(o => o.OrgId == t.OrgId) on line.ServiceStockInId equals header.Id
        select new { line.PartCode, line.PartName, line.Quantity, line.Price, line.Vat, header.StockInDate }).ToListAsync();

    // Giá trị một dòng nhập ĐÃ GỒM THUẾ — đúng biểu thức TGN của nguồn.
    static decimal StockInLineValue(decimal quantity, decimal price, decimal vat)
        => quantity * price + vat * 0.01m * price * quantity;

    var openingLines = stockInLines.Where(l => l.StockInDate.HasValue && l.StockInDate < fromDate).ToList();
    var inPeriodLines = stockInLines.Where(l => l.StockInDate.HasValue && l.StockInDate >= fromDate && l.StockInDate <= toDateEndOfDay).ToList();

    var partCodes = openingLines.Select(l => l.PartCode).Concat(inPeriodLines.Select(l => l.PartCode)).Distinct().ToList();
    if (partCodes.Count == 0) return Results.Ok(new { calculated = 0, message = "Chưa có phiếu nhập đã duyệt để tính giá vốn." });

    // Nguồn chỉ tính phụ tùng đang hiệu lực (p.IsActive = '1').
    var activeParts = await db.ServiceParts.Where(p => p.OrgId == t.OrgId && p.FlagActive == "1").ToListAsync();
    var partByCode = activeParts.ToDictionary(p => p.PartCode, p => p);

    var now = DateTime.Now;
    int calculated = 0, updated = 0;
    foreach (var partCode in partCodes)
    {
        if (!partByCode.TryGetValue(partCode, out var part)) continue;

        var opening = openingLines.Where(l => l.PartCode == partCode).ToList();
        var inPeriod = inPeriodLines.Where(l => l.PartCode == partCode).ToList();

        var openingQty = opening.Sum(l => l.Quantity);
        var openingValue = opening.Sum(l => StockInLineValue(l.Quantity, l.Price, l.Vat));
        var inQty = inPeriod.Sum(l => l.Quantity);
        var inValue = inPeriod.Sum(l => StockInLineValue(l.Quantity, l.Price, l.Vat));

        var totalQty = openingQty + inQty;
        var totalValue = openingValue + inValue;
        // Nguồn lọc `(op.SLD != 0 or si.SLN != 0)` — vừa bỏ dòng vô nghĩa, vừa CHẶN CHIA 0.
        if (totalQty == 0) continue;

        var averageCost = Math.Round(totalValue / totalQty, 2);
        db.PartCostSnapshots.Add(new PartCostSnapshot
        {
            OrgId = t.OrgId, PartCode = partCode,
            PartName = inPeriod.FirstOrDefault()?.PartName ?? opening.FirstOrDefault()?.PartName,
            AverageCost = averageCost,
            OpeningQty = openingQty, OpeningValue = openingValue,
            InQty = inQty, InValue = inValue,
            TotalQty = totalQty, TotalValue = totalValue,
            FromDate = fromDate, ToDate = toDate, Method = "Average", CalculatedAt = now
        });
        part.Cost = averageCost;
        updated++; calculated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { calculated, partsUpdated = updated, fromDate, toDate });
}).RequireAuthorization();

// Giá vốn hiện tại theo mã PT (snapshot mới nhất mỗi mã).
app.MapGet("/api/partcosts", async (AppDbContext db, ITenantContext t) =>
{
    var snaps = await db.PartCostSnapshots.Where(x => x.OrgId == t.OrgId).ToListAsync();
    var rows = snaps.GroupBy(x => x.PartCode).Select(g => g.OrderByDescending(x => x.Id).First())
        .Select(x => new { x.PartCode, x.PartName, x.AverageCost, x.OpeningQty, x.OpeningValue, x.InQty, x.InValue, x.TotalQty, x.TotalValue, x.FromDate, x.ToDate, calculatedAt = x.CalculatedAt.ToString("yyyy-MM-dd HH:mm") })
        .OrderBy(x => x.PartCode).ToList();
    return Results.Ok(new { count = rows.Count, rows });
}).RequireAuthorization();

// Lịch sử tính giá vốn 1 mã PT (các lần tính theo thời gian).
app.MapGet("/api/report/cost-history", async (AppDbContext db, ITenantContext t, string partCode) =>
{
    var code = (partCode ?? "").Trim();
    if (code == "") return Results.BadRequest(new { error = "Cần mã phụ tùng." });
    var rows = await db.PartCostSnapshots.Where(x => x.OrgId == t.OrgId && x.PartCode == code).OrderByDescending(x => x.Id)
        .Select(x => new { x.AverageCost, x.OpeningQty, x.OpeningValue, x.InQty, x.InValue, x.TotalQty, x.TotalValue, x.FromDate, x.ToDate, x.Method, calculatedAt = x.CalculatedAt.ToString("yyyy-MM-dd HH:mm") }).ToListAsync();
    return Results.Ok(new { partCode = code, count = rows.Count, rows });
}).RequireAuthorization();

// ===== Đặt hàng tồn kho tối ưu (report tái-dùng ServiceStockOut — port 1:1 FrmQLDathangtonkhotoiuu, TCMotor) =====
// Nhu cầu bình quân tháng (MAD) = trung bình SL xuất 6 tháng gần nhất; phân nhóm ABC theo tỉ trọng nhu cầu; đề xuất đặt hàng.
app.MapGet("/api/report/optimal-reorder", async (AppDbContext db, ITenantContext t, decimal? leadFactor) =>
{
    var factor = leadFactor is > 0 and <= 12 ? leadFactor.Value : 1.5m; // hệ số thời gian giao + an toàn
    var now = DateTime.Now;
    var startMonth = new DateTime(now.Year, now.Month, 1).AddMonths(-5); // đầu tháng của 6 tháng gần nhất (gồm tháng này)
    var confirmedIds = db.ServiceStockOuts.Where(o => o.OrgId == t.OrgId && o.Status == "Confirmed" && o.StockOutDate.HasValue && o.StockOutDate >= startMonth)
        .Select(o => new { o.Id, o.StockOutDate });
    var lines = await (from l in db.ServiceStockOutLines.Where(x => x.OrgId == t.OrgId)
                       join o in confirmedIds on l.ServiceStockOutId equals o.Id
                       select new { l.PartCode, l.Quantity, date = o.StockOutDate!.Value }).ToListAsync();
    var parts = await db.ServiceParts.Where(p => p.OrgId == t.OrgId).Select(p => new { p.PartCode, p.PartName, p.Quantity, p.MinQuantity }).ToListAsync();
    var pMap = parts.ToDictionary(p => p.PartCode, p => p);
    // Gom theo mã PT + 6 rổ tháng (index 0 = 5 tháng trước ... 5 = tháng này).
    int MonthIdx(DateTime d) => (d.Year - startMonth.Year) * 12 + (d.Month - startMonth.Month);
    var byPart = lines.GroupBy(l => l.PartCode).Select(g =>
    {
        var buckets = new decimal[6];
        foreach (var l in g) { var i = MonthIdx(l.date); if (i >= 0 && i < 6) buckets[i] += l.Quantity; }
        var total = buckets.Sum();
        var mad = Math.Round(total / 6m, 2);
        var months = g.Where(x => x.Quantity > 0).Select(x => new DateTime(x.date.Year, x.date.Month, 1)).Distinct().Count();
        pMap.TryGetValue(g.Key, out var p);
        var cur = p?.Quantity ?? 0m;
        var target = Math.Ceiling(mad * factor);
        var suggest = Math.Max(0, target - cur);
        return new { partCode = g.Key, partName = p?.PartName, buckets, total6mo = total, mad, freq = months, current = cur, target, suggestOrder = suggest };
    }).OrderByDescending(x => x.total6mo).ToList();
    // Phân nhóm ABC theo tỉ trọng lũy kế nhu cầu.
    var grand = byPart.Sum(x => x.total6mo);
    decimal cum = 0;
    var rows = byPart.Select(x =>
    {
        cum += x.total6mo;
        var share = grand > 0 ? cum / grand : 0;
        var icc = share <= 0.7m ? "A" : share <= 0.9m ? "B" : "C";
        return new { x.partCode, x.partName, x.buckets, x.total6mo, x.mad, x.freq, x.current, x.target, x.suggestOrder, icc };
    }).ToList();
    return Results.Ok(new { count = rows.Count, needOrder = rows.Count(r => r.suggestOrder > 0), totalSuggest = rows.Sum(r => r.suggestOrder), leadFactor = factor, rows });
}).RequireAuthorization();

// ===== File đính kèm đề nghị bảo hành (WarrantyAttachment — port 1:1 FrmROAttachment, TCMotor) =====
app.MapGet("/api/warrantyclaims/{id}/attachments", async (long id, AppDbContext db, ITenantContext t) =>
{
    var c = await db.ServiceWarrantyClaims.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (c is null) return Results.NotFound(new { id });
    var files = await db.WarrantyAttachments.Where(a => a.OrgId == t.OrgId && a.ServiceWarrantyClaimId == id).OrderBy(a => a.Id)
        .Select(a => new { a.Id, a.FileName, a.FileNote, createdAt = a.CreatedAt.ToString("yyyy-MM-dd HH:mm") }).ToListAsync();
    return Results.Ok(new { c.ClaimNo, count = files.Count, files });
}).RequireAuthorization();

app.MapPost("/api/warrantyclaims/{id}/attachments", async (long id, WarrantyAttachmentDto dto, AppDbContext db, ITenantContext t) =>
{
    var c = await db.ServiceWarrantyClaims.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (c is null) return Results.NotFound(new { id });
    var fn = (dto.FileName ?? "").Trim();
    if (fn == "") return Results.BadRequest(new { error = "Cần tên file đính kèm." });
    var a = new WarrantyAttachment { OrgId = t.OrgId, ServiceWarrantyClaimId = id, FileName = fn, FileNote = dto.FileNote };
    db.WarrantyAttachments.Add(a); await db.SaveChangesAsync();
    return Results.Ok(new { a.Id, a.FileName });
}).RequireAuthorization();

app.MapDelete("/api/warrantyclaims/{id}/attachments/{attId}", async (long id, long attId, AppDbContext db, ITenantContext t) =>
{
    var a = await db.WarrantyAttachments.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ServiceWarrantyClaimId == id && x.Id == attId);
    if (a is null) return Results.NotFound(new { attId });
    db.WarrantyAttachments.Remove(a); await db.SaveChangesAsync();
    return Results.Ok(new { deleted = attId });
}).RequireAuthorization();

// ===== 🔴 #303 BÁO CÁO CHẤP THUẬN BẢO HÀNH — viết lại theo bản LIVE =====
// TRACE TWIN: `SerWarrantyAcceptRpt` có **MƯỜI** biến thể trong 2 file. WS gọi đúng bốn:
//   `_New20230417` (`WarrantyReport.cs:14575`) · `_GetAll` (:14083) · `_GetAll_WH` (:14329) ·
//   `_WH_New20230417` (`WH.cs:20271`). Sáu bản còn lại CHẾT — trong đó `SerWarrantyAcceptRpt_WH`
//   (`WH.cs:19248`) chính là chỗ sweep #302 chỉ tới. Lại một lần nữa: sweep chỉ VỊ TRÍ, không chỉ THẨM QUYỀN.
//
// ⚠️ Báo cáo cũ ở đây là **hàng tự chế** (gộp theo đại lý, lấy `claim.Amount`). Nguồn KHÔNG làm vậy:
//   nó dựng từng DÒNG công + DÒNG phụ tùng rồi mới ra tiền. Nay port đúng.
//
// 🔴 CÔNG THỨC TIỀN (khác nhau giữa hai loại dòng — **`Quantity` CHỈ nhân cho phụ tùng**):
//   `ServicePrice = Factor*Price + Factor*Price*VAT*0.01`
//   `PartPrice    = Factor*Price*Quantity + Factor*Price*Quantity*VAT*0.01`
//   (VAT là **phần trăm**, nhân 0.01 — không phải hệ số 0..1.)
//
// 🔴 FULL OUTER JOIN công ⟗ phụ tùng theo ROWID: đề nghị **chỉ có công** hoặc **chỉ có phụ tùng** vẫn phải
//   ra báo cáo. Dùng inner join là mất hẳn hai nhóm đó. Bên thiếu ⇒ tiền = 0 (`ISNULL(...,0)`).
//
// 🔴 CHỈ LẤY **MỘT DÒNG ĐẠI DIỆN** mỗi đề nghị: `top 1 itemid where ROWSerType = 'CVC'` (công chính) và
//   `top 1 itemid where ROWPartType = 'PTC'` (phụ tùng chính) — nhưng **TIỀN thì cộng TOÀN BỘ** các dòng.
//   Hai việc khác nhau: tên/mã hiển thị lấy dòng chính, số tiền lấy tổng.
//
// ⚠️ Lọc trạng thái đặt ở **ĐẦU ĐỀ NGHỊ** (`rwr.WarrantyStatus = 'ACCE'`). Ở mức DÒNG, nguồn đã
//   **comment mất** `--AND rwrs.WarrantyStatus = 'ACCE'` ⇒ đề nghị đã chấp thuận thì **MỌI dòng đều tính**,
//   kể cả dòng có trạng thái riêng khác. Giữ đúng (đây là dòng ACTIVE, luật B).
//
// ⚠️ Lọc ngày duyệt của nguồn là `convert(char(10), rwr.ApprovedDate, 120)` ⇒ **so CHUỖI yyyy-MM-dd**,
//   không phải khoảng datetime. ⚠️ Lọc `VAT` là MỘT tham số áp cho **CẢ HAI** bảng dòng (`rwrs.VAT` và `rwrp.VAT`).
// ===== 🔴 #406 GAP: lọc ngày duyệt của nguồn là **KHOẢNG**, không phải một ngày =====
// TRACE (đọc thân từng tầng, lệ #400/#405): form `FrmWarrantyReportAcceptRpt`
//   → `SerROWarrantyReportSerivce.SerWarrantyAcceptRpt(dealer, dateFrom, dateTo, VAT)`
//   → WS `SerWarrantyAcceptRpt` → biz `SerWarrantyAcceptRpt_New20230417` (`WarrantyReport.cs:14575`).
//
// 🔴 **TOÁN TỬ LỌC NẰM Ở TẦNG SERVICE** (lệ #401) — biz chỉ nhận một CHUỖI điều kiện:
//   `Util.GenDateRangeCondition(from, to)` (`Util.cs:180`) sinh ra **bốn dạng** tuỳ ô nào trống:
//     cả hai trống → `""` (KHÔNG lọc) · chỉ có `to` → `"<=to"` · chỉ có `from` → `">=from"`
//     · đủ hai → `">=from|<=to"`   (dấu `|` = AND hai vế, theo cú pháp `SqlUtils.BuildClause`).
//   Biz áp chuỗi đó lên `convert(char(10), rwr.ApprovedDate, 120)` ⇒ **so sánh CHUỖI**, không phải datetime.
//   May là `yyyy-MM-dd` xếp thứ tự từ điển trùng thứ tự thời gian nên khoảng vẫn đúng — và form
//   định dạng bằng `Nonsense.DATE_DB_FORMAT = "yyyy-MM-dd"` (`Constants.cs:120`), **khớp** `char(10)` kiểu 120.
//   ⚠️ Nếu ai đó đổi `DATE_DB_FORMAT` sang `dd/MM/yyyy` thì bộ lọc **vẫn chạy, vẫn ra kết quả, chỉ là sai** —
//     so chuỗi không bao giờ báo lỗi kiểu. Đây là lý do port giữ nguyên so-chuỗi thay vì "sửa" thành so ngày.
//
// 🔴 Bản port trước (#303) chỉ có `approvedDate` **một ngày, so bằng** ⇒ không diễn đạt được thao tác
//   thật của form (ô *Ngày duyệt từ* `deMonth` + ô `dateTo`). Nay thêm `from`/`to` đúng 4 dạng trên;
//   `approvedDate` giữ lại như lối tắt "from = to = ngày đó".
//
// 📌 **ĐỐI CHIẾU BẢN `_WH`** (lệ #376/#378 — hậu tố `_WH` KHÔNG mặc nhiên chỉ là đổi CSDL):
//   diff thân hai hàm LIVE `SerWarrantyAcceptRpt_New20230417` (`WarrantyReport.cs:14575-14938`) vs
//   `SerWarrantyAcceptRpt_WH_New20230417` (`WH.cs:20271-20632`) = **45 dòng lệch, KHÔNG dòng nào lệch nghiệp vụ**:
//   `_dbDealer`→`_dbWH`, `Mst_Dealer` bỏ tiền tố `[@strDBName_CommonCenter]`, khác hoa/thường và khoảng trắng,
//   và **một** `--//[mylock]` bị bỏ trên bảng tạm `#tblFinished`. ⇒ Ở hàm NÀY `_WH` đúng là bản đổi CSDL
//   thuần tuý — khác hẳn `…_OnlyOneROWID_WH` ở #378 (chỗ đó đổi hẳn điều kiện chọn dòng).
//   MiniHTC một CSDL ⇒ **không cần tham số `scope`** cho báo cáo này; ghi lại kết luận để lần sau khỏi dò.
app.MapGet("/api/report/warranty-accept", async (AppDbContext db, ITenantContext t,
    string? dealer, string? approvedDate, string? from, string? to, decimal? vat, string? month) =>
{
    var q = db.ServiceWarrantyClaims.Where(x => x.OrgId == t.OrgId && x.Status == "Accepted");
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(x => x.DealerCode == dealer!.Trim().ToUpperInvariant());
    // `month` giữ lại cho client cũ — KHÔNG có trong nguồn, đánh dấu rõ là phần mở rộng.
    if (!string.IsNullOrWhiteSpace(month) && DateTime.TryParse(month + "-01", out var m0))
    {
        var m1 = m0.AddMonths(1);
        q = q.Where(x => x.UpdatedAt >= m0 && x.UpdatedAt < m1);
    }

    var claims = await q.ToListAsync();
    // Lọc ngày duyệt: nguồn so CHUỖI `convert(char(10), ApprovedDate, 120)` = "yyyy-MM-dd",
    //   KHÔNG phải khoảng datetime ⇒ lọc sau khi nạp, đúng ngữ nghĩa chuỗi.
    // #406 Bốn dạng của `GenDateRangeCondition`, so **CHUỖI** `yyyy-MM-dd` đúng như nguồn.
    // `approvedDate` (bản #303) = lối tắt "from = to = ngày đó".
    var dFrom = (from ?? approvedDate ?? "").Trim();
    var dTo = (to ?? approvedDate ?? "").Trim();
    if (dFrom.Length > 0) claims = claims
        .Where(x => string.CompareOrdinal(x.ApprovedDate == null ? "" : x.ApprovedDate.Value.ToString("yyyy-MM-dd"), dFrom) >= 0).ToList();
    if (dTo.Length > 0) claims = claims
        .Where(x => string.CompareOrdinal(x.ApprovedDate == null ? "" : x.ApprovedDate.Value.ToString("yyyy-MM-dd"), dTo) <= 0).ToList();
    var ids = claims.Select(c => c.Id).ToList();

    var svcQ = db.WarrantyClaimServiceItems.Where(i => i.OrgId == t.OrgId && ids.Contains(i.ClaimId));
    var partQ = db.WarrantyClaimPartItems.Where(i => i.OrgId == t.OrgId && ids.Contains(i.ClaimId));
    if (vat.HasValue) { svcQ = svcQ.Where(i => i.VAT == vat.Value); partQ = partQ.Where(i => i.Vat == vat.Value); }
    var svcItems = await svcQ.ToListAsync();
    var partItems = await partQ.ToListAsync();

    var svcByClaim = svcItems.GroupBy(i => i.ClaimId).ToDictionary(g => g.Key, g => g.ToList());
    var partByClaim = partItems.GroupBy(i => i.ClaimId).ToDictionary(g => g.Key, g => g.ToList());

    // Chữ hoa đầu, phần còn lại chữ thường — đúng nguồn:
    //   upper(substring(X,1,1)) + lower(substring(X,2,len(X)))
    static string? TitleOne(string? v)
        => string.IsNullOrWhiteSpace(v) ? v : char.ToUpperInvariant(v![0]) + v.Substring(1).ToLowerInvariant();

    var rows = new List<WarrantyAcceptRptRow>();
    // FULL OUTER JOIN: duyệt hợp của hai tập khoá đề nghị có dòng, cộng cả đề nghị không có dòng nào
    //   (nguồn dùng RIGHT JOIN #tbl_RO_Customer nên đề nghị trống vẫn còn mặt).
    foreach (var c in claims)
    {
        var svs = svcByClaim.TryGetValue(c.Id, out var s1) ? s1 : new List<WarrantyClaimServiceItem>();
        var pts = partByClaim.TryGetValue(c.Id, out var p1) ? p1 : new List<WarrantyClaimPartItem>();
        if (svs.Count == 0 && pts.Count == 0 && vat.HasValue) continue;   // lọc VAT loại sạch hai bên

        decimal servicePrice = svs.Sum(i => i.Factor * i.Price + i.Factor * i.Price * i.VAT * 0.01m);
        decimal partPrice = pts.Sum(i => i.Factor * i.Price * i.Quantity
                                        + i.Factor * i.Price * i.Quantity * i.Vat * 0.01m);

        // dòng ĐẠI DIỆN: công chính CVC, phụ tùng chính PTC (top 1 theo Id — nguồn dùng top 1 itemid)
        var mainSvc = svs.Where(i => i.ROWSerType == "CVC").OrderBy(i => i.Id).FirstOrDefault();
        var mainPart = pts.Where(i => i.RowPartType == "PTC").OrderBy(i => i.Id).FirstOrDefault();

        // ItemCode: mã PHỤ TÙNG thắng, mã dịch vụ là dự phòng (Isnull(svp.PartCode, svs.sercode))
        var itemCode = mainPart?.PartCode ?? mainSvc?.SerCode;
        var itemName = TitleOne(mainPart?.PartName ?? mainSvc?.SerName);

        rows.Add(new WarrantyAcceptRptRow(
            c.Id, c.ROWNo, c.RONo, c.Vin, c.DealerCode, c.ApprovedDate,
            itemCode, itemName,
            mainPart?.PartCode, mainPart?.PartName, mainPart?.Quantity,
            mainSvc?.SerCode, mainSvc?.SerName, mainSvc?.StdManHour,
            servicePrice, partPrice, servicePrice + partPrice,
            // ItemIndex của nguồn: "1" = phụ tùng, "2" = công — dùng để sắp xếp lưới.
            mainPart is not null ? "1" : "2",
            svs.Count, pts.Count));
    }
    // Đúng nguồn: ORDER BY RONo, ItemIndex.
    rows = rows.OrderBy(r => r.RONo).ThenBy(r => r.ItemIndex).ToList();

    return Results.Ok(new
    {
        count = rows.Count,
        grandServicePrice = rows.Sum(r => r.ServicePrice),
        grandPartPrice = rows.Sum(r => r.PartPrice),
        note = "Tiền = TỔNG mọi dòng; mã/tên lấy DÒNG CHÍNH (CVC/PTC). Lọc ACCE đặt ở đầu đề nghị, "
             + "KHÔNG lọc ở mức dòng (nguồn đã comment mất điều kiện đó).",
        rows,
    });
}).RequireAuthorization();

// ===== 🔴 #406 KẾT XUẤT EXCEL BÁO CÁO CHẤP THUẬN BẢO HÀNH — **MỌI ĐẠI LÝ** =====
// Nguồn: `FrmWarrantyReportAcceptRpt.btnExportExcel_Click` →
//   `SerWarrantyAcceptRptAllDealer(from, to, bFlagWH)` (`SerROWarrantyReportSerivce.cs:1393`).
// ⚠️ Hàm này **KHÔNG có biz riêng**: nó gọi đúng WS `SerWarrantyAcceptRpt` như nút xem báo cáo,
//   chỉ khác **hai tham số**: `strDealerCodeConditionList = ""` (⇒ **mọi đại lý**) và VAT = `""` (⇒ không lọc VAT).
//   Tức "báo cáo toàn hệ thống" ở đây chỉ là *bỏ trống ô đại lý* — không phải một truy vấn khác.
//
// 🔴 SỐ LIỆU **KHÔNG GIỐNG** lưới trên màn, dù cùng nguồn — form nhào lại trước khi ghi file:
//   1. `TOTALAMOUNT = Math.Round(partPrice + servicePrice, MidpointRounding.AwayFromZero)`
//      ⇒ **làm tròn về SỐ NGUYÊN**, nửa lẻ làm tròn RA XA số 0. Chú thích nguồn nói thẳng lý do:
//        *"làm tròn dữ liệu cột total để khớp dữ liệu các column và TotalAmount.Summary"*.
//      ⚠️ Cộng-rồi-làm-tròn ⇒ **tổng cột Excel ≠ tổng tiền thật** khi có phần lẻ; đây là chủ đích của nguồn.
//   2. `CusRequest` bỏ `-` `'` và **xuống dòng**; `CarStatus` bỏ `-` `'` và **TOÀN BỘ khoảng trắng**
//      ⇒ *"Xe không nổ máy"* thành *"Xekhôngnổmáy"* trong file Excel. Đọc rất khó nhưng là hành vi thật.
//   3. Cả hai cột **cắt còn 255 ký tự** sau khi dọn.
//   4. Bỏ hẳn hai cột `ROWID` và `ROWNo`, rồi `SetOrdinal` ép **thứ tự cột cố định**.
// ⚠️ `BulletinNoHMC` có trong lưới nhưng dòng `SetOrdinal` của nó **đã bị comment** ⇒ **không** ra file (luật B).
// 📌 (#502b CẬP NHẬT) `WARRANTYSTATUSTEXT` đã trả; nay chỉ còn `HTCROWNo` ⇒ trả `null` và báo `columnsNotModelled`,
//   thay vì bịa giá trị cho đủ cột.
// ===== 🔴 #407 CÙNG BÁO CÁO, **HAI HÌNH DẠNG KẾT QUẢ KHÁC HẲN NHAU** =====
// TRACE (đọc thân WS TRƯỚC, lệ #405): form `FrmWarrantyReportAcceptRpt.PrintDtl` →
//   `SerWarrantyAcceptRpt_GetAll(dealer, from, to, VAT)` → WS `SerWarrantyAcceptRpt_GetAll`
//   (`WSCarSv.asmx.cs:19912`) → biz `SerWarrantyAcceptRpt_GetAll` (`WarrantyReport.cs:14083`).
//   ⚠️ Ở đây WS gọi bản **KHÔNG hậu tố** — khác hẳn nút xem báo cáo (#406) gọi `_New20230417`.
//     Cùng một màn, hai nút, hai quy ước đặt tên. Chỉ đọc thân WS mới biết.
//
// 🔴 `_GetAll` **KHÔNG phải** `SerWarrantyAcceptRpt` + "lấy tất cả đại lý". Nó là **báo cáo MỨC DÒNG**:
//   · Bản #406 gộp mỗi đề nghị thành **một dòng** (`#tbl_rowr_tmp` full outer join + `sum`),
//     lấy mã/tên của dòng chính rồi cộng tiền.
//   · Bản `_GetAll` **bỏ hẳn khối gộp đó** ⇒ trả **từng dòng công và từng dòng phụ tùng**, mỗi dòng
//     một mã, một mức VAT, một số tiền riêng.
//   ⇒ Hai báo cáo cùng bộ lọc cho ra **số dòng khác nhau**; đừng dùng cái này kiểm tra cái kia.
//
// 🔴 **INNER JOIN, không phải RIGHT JOIN** (khác #406): `_GetAll` nối `#tbl_RO_Customer` với bảng dòng bằng
//   `inner join` ⇒ **đề nghị đã duyệt nhưng KHÔNG có dòng nào sẽ BIẾN MẤT** khỏi báo cáo chi tiết,
//   trong khi vẫn **hiện** ở báo cáo tổng (bản #406 dùng `RIGHT JOIN #tbl_RO_Customer` giữ chúng lại).
//   Đây là lý do thật khiến tổng hai màn lệch nhau — không phải lỗi cộng tiền.
//
// 🔴 **`rankType` — thứ tự ưu tiên trong một RO**, chỉ có ở bản này:
//   công: `CVC`→`1` · `CVPSN`→`2` · còn lại→`3`;  phụ tùng: `PTC`→`1` · `PTTT`→`2` · `VTP`→`3` · còn lại→`4`.
//   Sắp xếp cuối: `order by RONo asc, ItemIndex DESC, rankType asc` — `ItemIndex` **giảm dần** nên
//   `2` (Công) đứng TRƯỚC `1` (Phụ tùng). Đọc lướt rất dễ đảo ngược chỗ này.
//
// ⚠️ `PartPrice` của dòng công (và `ServicePrice` của dòng phụ tùng) là `''` — **chuỗi rỗng, KHÔNG phải NULL**.
//   Nên `isnull(t.PartPrice, 0.0)` ở dòng tổng **không bao giờ kích hoạt**; số 0 có được là nhờ SQL Server
//   ép ngầm `''` → 0 khi hợp kiểu UNION. Guard chống NULL ở đây là **guard chết**.
// ⚠️ `order by RONo, ItemIndex` đặt trong câu `SELECT … INTO #tbl_part_tmp` — ORDER BY trên SELECT INTO
//   **không bảo đảm thứ tự gì cả**; thứ tự thật do câu SELECT cuối quyết định. Dòng thừa.
// ⚠️ `--AND rwrs.WarrantyStatus = 'ACCE'` bị comment ở **cả hai** nhánh (giống #303): lọc ACCE chỉ đặt ở
//   **đầu đề nghị**, mọi dòng con đều được tính. Giữ 1:1 (luật B).
// ⚠️ WS đặt `strFunctionName = "SerWarrantyAcceptRpt"` (KHÔNG có `_GetAll`) ⇒ **nhật ký và phân quyền của
//   nút này ghi dưới tên nút kia**. Tra log theo tên hàm sẽ lẫn hai nút vào nhau.
// 📌 Bản `_GetAll_WH` (`WarrantyReport.cs:14329` — nằm cùng file, KHÔNG ở `WH.cs`): diff 24 dòng,
//   **không dòng nào lệch nghiệp vụ** (`_dbDealer`→`_dbWH`, `Mst_Dealer` bỏ tiền tố). Không cần `scope`.
// ===== 🔴 #409 Ô CHỌN ĐẠI LÝ LỌC THEO **NGÀY TẠO**, CÒN BÁO CÁO LỌC THEO **NGÀY DUYỆT** =====
// TRACE (thân WS trước, lệ #405): `FrmWarrantyReportAcceptRpt.Init()` →
//   `Ser_ROWarrantyReportHTCDealer_Get(deMonth.ToString("yyyy-MM"), bFlagWH)` (`…Serivce.cs:1528`)
//   → WS `Ser_ROWarrantyReportHTCDealer_Get` (`WSCarSv.asmx.cs:20198`)
//   → biz `Ser_ROWarrantyReportHTCDealer_Get` (`WarrantyReport.cs:18448`).
//
// 🔴 **BẤT ĐỐI XỨNG THẬT SỰ CỦA MÀN NÀY**: ô *Ngày duyệt từ* (`deMonth`) vừa nạp danh sách đại lý,
//   vừa là mốc lọc báo cáo — nhưng **hai bên lọc trên HAI CỘT KHÁC NHAU**:
//     · Nạp combo : `convert(char(7), td.**CreatedDate**, 120) = 'yyyy-MM'`
//     · Báo cáo   : `convert(char(10), rwr.**ApprovedDate**, 120)` trong khoảng (#406)
//   ⇒ Đề nghị **tạo tháng trước, duyệt tháng này**: đại lý đó **KHÔNG có trong danh sách chọn**,
//     dù báo cáo của nó có dữ liệu. Người dùng không tìm thấy đại lý và kết luận "tháng này không có".
//   ⇒ Ngược lại, đại lý **tạo tháng này nhưng chưa duyệt xong** vẫn hiện trong combo rồi cho ra
//     báo cáo **rỗng**. Cả hai chiều đều im lặng.
//   📌 Giữ 1:1 (lọc theo ngày TẠO) và trả kèm `dealersByApprovedDate` + `mismatch` để nhìn thấy lệch.
//
// ⚠️ **NGOẠI LỆ của lệ #401**: lần này toán tử **KHÔNG** nằm ở tầng service — form truyền chuỗi
//   `yyyy-MM` **trần**, và chính **BIZ** ghép dấu bằng: `BuildClause(…, "=" + strMonthConditionList, …)`.
//   ⇒ Vị trí toán tử **không có quy luật cố định**; phải đọc cả hai tầng, đừng suy từ hàm khác.
// ⚠️ Dùng `with(nolock)` **viết thẳng**, không phải dấu `--//[mylock]` ⇒ chấp nhận đọc bẩn.
// ⚠️ Tên hàm WH là `_GetWH` (**không** phải `_Get_WH`) — lại một quy ước đặt tên nữa trong cùng file.
//   Diff hai thân: chỉ đổi CSDL, **không lệch nghiệp vụ** ⇒ không cần `scope`.
app.MapGet("/api/report/warranty-accept/dealers", async (AppDbContext db, ITenantContext t,
    string? month) =>
{
    // `WarrantyStatus in ('ACCE')` — chỉ đề nghị ĐÃ CHẤP THUẬN.
    var accepted = await db.ServiceWarrantyClaims
        .Where(x => x.OrgId == t.OrgId && x.Status == "Accepted")
        .Select(x => new { x.DealerCode, x.CreatedAt, x.ApprovedDate })
        .ToListAsync();

    var m = (month ?? "").Trim();
    // So CHUỖI `yyyy-MM` — đúng `convert(char(7), …, 120)` của nguồn.
    var byCreated = accepted
        .Where(x => m.Length == 0 || x.CreatedAt.ToString("yyyy-MM") == m)
        .Select(x => x.DealerCode).Where(d => !string.IsNullOrWhiteSpace(d))
        .Distinct().ToList();
    // Chỉ để ĐỐI CHIẾU — không phải hành vi nguồn.
    var byApproved = accepted
        .Where(x => m.Length == 0
            || (x.ApprovedDate != null && x.ApprovedDate.Value.ToString("yyyy-MM") == m))
        .Select(x => x.DealerCode).Where(d => !string.IsNullOrWhiteSpace(d))
        .Distinct().ToList();

    var names = await db.Dealers.Where(d => d.OrgId == t.OrgId)
        .Select(d => new { d.DealerCode, d.DealerName }).ToListAsync();
    var nameOf = names.GroupBy(d => d.DealerCode).ToDictionary(g => g.Key, g => g.First().DealerName);

    // `inner join Mst_Dealer` ⇒ mã không có trong danh mục đại lý thì BỊ LOẠI, không hiện lên combo.
    var rows = byCreated.Where(d => nameOf.ContainsKey(d!))
        .Select(d => new { dealerCode = d, dealerName = nameOf[d!] })
        .OrderBy(x => x.dealerCode).ToList();
    var notInMaster = byCreated.Where(d => !nameOf.ContainsKey(d!)).OrderBy(x => x).ToList();

    var missingFromCombo = byApproved.Except(byCreated).OrderBy(x => x).ToList();
    var comboButNoReport = byCreated.Except(byApproved).OrderBy(x => x).ToList();

    return Results.Ok(new
    {
        month = m, count = rows.Count, rows,
        filterColumnNote = "Danh sách này lọc theo NGÀY TẠO (CreatedDate), trong khi báo cáo lọc theo "
            + "NGÀY DUYỆT (ApprovedDate) — hai cột khác nhau trên cùng một ô nhập.",
        dealersByApprovedDate = byApproved.OrderBy(x => x),
        missingFromCombo,
        missingFromComboNote = missingFromCombo.Count > 0
            ? "Các đại lý này CÓ đề nghị được duyệt trong tháng nhưng KHÔNG hiện trong ô chọn "
              + "(đề nghị tạo từ tháng trước) ⇒ người dùng không chọn được, tưởng là không có dữ liệu."
            : null,
        comboButNoReport,
        comboButNoReportNote = comboButNoReport.Count > 0
            ? "Các đại lý này HIỆN trong ô chọn nhưng báo cáo sẽ RỖNG (tạo trong tháng, chưa duyệt xong)."
            : null,
        notInMaster,
        notInMasterNote = notInMaster.Count > 0
            ? "Có đề nghị mang mã đại lý KHÔNG nằm trong danh mục Mst_Dealer; inner join của nguồn loại "
              + "chúng khỏi ô chọn ⇒ dữ liệu đó không ai xem được từ màn này."
            : null,
        operatorLocationNote = "Toán tử '=' do BIZ ghép (BuildClause(…, \"=\" + month, …)), KHÔNG do tầng "
            + "service — ngược với các hàm khác cùng màn. Vị trí toán tử không có quy luật cố định.",
        nolockNote = "Nguồn dùng with(nolock) viết thẳng (không phải dấu --//[mylock]) ⇒ chấp nhận đọc bẩn.",
    });
}).RequireAuthorization();

app.MapGet("/api/report/warranty-accept/lines", async (AppDbContext db, ITenantContext t,
    string? dealer, string? from, string? to, decimal? vat) =>
{
    var q = db.ServiceWarrantyClaims.Where(x => x.OrgId == t.OrgId && x.Status == "Accepted");
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(x => x.DealerCode == dealer!.Trim().ToUpperInvariant());
    var claims = await q.ToListAsync();

    // Lọc ngày duyệt: KHOẢNG, so CHUỖI `yyyy-MM-dd` — cùng luật #406.
    string DK(DateTime? d) => d == null ? "" : d.Value.ToString("yyyy-MM-dd");
    var dFrom = (from ?? "").Trim(); var dTo = (to ?? "").Trim();
    if (dFrom.Length > 0) claims = claims.Where(x => string.CompareOrdinal(DK(x.ApprovedDate), dFrom) >= 0).ToList();
    if (dTo.Length > 0) claims = claims.Where(x => string.CompareOrdinal(DK(x.ApprovedDate), dTo) <= 0).ToList();

    var byId = claims.ToDictionary(c => c.Id);
    var ids = claims.Select(c => c.Id).ToList();
    var svcQ = db.WarrantyClaimServiceItems.Where(i => i.OrgId == t.OrgId && ids.Contains(i.ClaimId));
    var partQ = db.WarrantyClaimPartItems.Where(i => i.OrgId == t.OrgId && ids.Contains(i.ClaimId));
    if (vat.HasValue) { svcQ = svcQ.Where(i => i.VAT == vat.Value); partQ = partQ.Where(i => i.Vat == vat.Value); }
    var svcItems = await svcQ.ToListAsync();
    var partItems = await partQ.ToListAsync();

    var rows = new List<WarrantyAcceptLineRow>();
    // --- Nhánh CÔNG: ItemIndex = "2", PartPrice = 0 (nguồn để '' rồi bị ép về 0).
    foreach (var i in svcItems)
    {
        if (!byId.TryGetValue(i.ClaimId, out var c)) continue;
        var price = i.Factor * i.Price + i.Factor * i.Price * i.VAT * 0.01m;
        var rank = i.ROWSerType == "CVC" ? "1" : i.ROWSerType == "CVPSN" ? "2" : "3";
        rows.Add(new WarrantyAcceptLineRow(c.RONo, c.Vin, "Công", i.VAT,
            i.SerCode, i.SerName, price, 0m, price, "2", rank));
    }
    // --- Nhánh PHỤ TÙNG: ItemIndex = "1", ServicePrice = 0. Quantity CHỈ nhân ở nhánh này.
    foreach (var i in partItems)
    {
        if (!byId.TryGetValue(i.ClaimId, out var c)) continue;
        var price = i.Factor * i.Price * i.Quantity + i.Factor * i.Price * i.Quantity * i.Vat * 0.01m;
        var rank = i.RowPartType == "PTC" ? "1" : i.RowPartType == "PTTT" ? "2"
                 : i.RowPartType == "VTP" ? "3" : "4";
        rows.Add(new WarrantyAcceptLineRow(c.RONo, c.Vin, "Phụ tùng", i.Vat,
            i.PartCode, i.PartName, 0m, price, price, "1", rank));
    }

    // 🔴 ItemIndex sắp GIẢM DẦN ⇒ Công ("2") đứng TRƯỚC Phụ tùng ("1").
    rows = rows.OrderBy(r => r.RONo).ThenByDescending(r => r.ItemIndex).ThenBy(r => r.RankType).ToList();

    // INNER JOIN của nguồn ⇒ đề nghị không có dòng nào bị LOẠI. Đếm ra để thấy chênh với báo cáo tổng.
    var claimsWithLines = rows.Select(r => r.RONo).Distinct().Count();
    var claimsDropped = claims.Count - claims.Count(c => svcItems.Any(i => i.ClaimId == c.Id)
                                                      || partItems.Any(i => i.ClaimId == c.Id));

    return Results.Ok(new
    {
        count = rows.Count,
        acceptedClaims = claims.Count, claimsWithLines, claimsDropped,
        grandServicePrice = rows.Sum(r => r.ServicePrice),
        grandPartPrice = rows.Sum(r => r.PartPrice),
        shapeNote = "Đây là báo cáo MỨC DÒNG (mỗi dòng công / mỗi dòng phụ tùng một bản ghi), KHÁC "
            + "/api/report/warranty-accept vốn gộp mỗi đề nghị thành MỘT dòng. Số dòng hai bên khác nhau "
            + "là đúng, không phải lỗi.",
        droppedNote = claimsDropped > 0
            ? $"{claimsDropped} đề nghị đã duyệt KHÔNG có dòng nào nên bị INNER JOIN loại khỏi báo cáo chi "
              + "tiết, nhưng VẪN hiện ở báo cáo tổng (bên đó dùng RIGHT JOIN). Đây là nguồn lệch tổng thật sự."
            : null,
        sortNote = "Sắp xếp: RONo tăng, ItemIndex GIẢM (Công trước Phụ tùng), rankType tăng "
            + "(công CVC<CVPSN<khác; phụ tùng PTC<PTTT<VTP<khác).",
        deadGuardNote = "Nguồn dùng isnull(PartPrice, 0.0) nhưng giá trị là CHUỖI RỖNG chứ không phải NULL "
            + "⇒ guard đó không bao giờ kích hoạt; số 0 do SQL ép ngầm '' → 0 khi hợp kiểu UNION.",
        logNameNote = "WS đặt strFunctionName = \"SerWarrantyAcceptRpt\" (thiếu _GetAll) ⇒ nhật ký/phân "
            + "quyền của nút chi tiết ghi lẫn với nút xem báo cáo.",
        rows,
    });
}).RequireAuthorization();

// ===== 🔴 #408 KẾT XUẤT CHI TIẾT — **HAI KIỂU LÀM TRÒN KHÁC NHAU trong CÙNG một dòng** =====
// Nguồn: `FrmWarrantyReportAcceptRpt.btnExportExcelDtl_Click` (`:703`) →
//   `SerWarrantyAcceptRptDtlAllDealer(from, to, bFlagWH)` (`SerROWarrantyReportSerivce.cs:1442`).
// ⚠️ Hàm service này gọi đúng WS `SerWarrantyAcceptRpt_GetAll` của #407, chỉ bỏ trống đại lý và VAT
//   ⇒ **không có truy vấn mới**. Toàn bộ giá trị của lượt này nằm ở phần form NHÀO LẠI dữ liệu.
//
// 🔴 **Ba số tiền trên một dòng, làm tròn theo BA cách — nên chúng KHÔNG cộng khớp nhau**:
//   1. `ServicePrice` và `PartPrice` bị **ghi đè** bằng `Convert.ToInt32(...)` ⇒ làm tròn **NGÂN HÀNG**
//      (ties-to-even): `0.5`→`0`, `1.5`→`2`, `2.5`→`2`.
//   2. `TOTALAMOUNT` tính từ **giá trị GỐC chưa làm tròn** (biến `partPrice`/`servicePrice` mà `TryParse`
//      lấy ra **TRƯỚC** khi ghi đè), rồi `Math.Round(..., AwayFromZero)` ⇒ làm tròn **RA XA SỐ 0**.
//   ⇒ Ví dụ công `0.5` + phụ tùng `0.5`: hai cột hiển thị `0` và `0`, cột tổng hiển thị `1`.
//     Người đọc file thấy **0 + 0 = 1**. Không có lỗi nào được báo — đây là hành vi thật của nguồn.
//   3. Cột `TOTALPRICE` **do SQL tính** (tổng chính xác, không làm tròn) thì bị **XOÁ khỏi file**
//      cùng với `RANKTYPE` ⇒ con số đúng duy nhất bị bỏ đi, giữ lại con số đã bị nhào.
//
// ⚠️ `Convert.ToInt32` **NÉM OverflowException** khi vượt `2_147_483_647`. Với tiền VNĐ đây không phải
//   giả thuyết xa vời: một dòng > 2,1 tỷ là **sập cả thao tác kết xuất**, không phải sai một ô.
//   📌 **CỐ Ý LỆCH NGUỒN**: MiniHTC KHÔNG ném — kẹp giá trị và đếm vào `int32OverflowRows`,
//     vì một API sập vì dữ liệu thì không nói cho ai biết điều gì; con số đếm thì có.
// ⚠️ Dòng công có `PartPrice` rỗng ⇒ `double.TryParse("")` **thất bại** ⇒ nhánh ghi đè **không chạy**,
//   và biến cục bộ giữ nguyên `0`. Vô tình đúng, nhưng đúng do `TryParse` hỏng chứ không do guard nào.
app.MapGet("/api/report/warranty-accept/lines/export", async (AppDbContext db, ITenantContext t,
    string? from, string? to) =>
{
    // Đại lý + VAT để TRỐNG = mọi đại lý, mọi mức VAT (đúng nguồn).
    var claims = await db.ServiceWarrantyClaims
        .Where(x => x.OrgId == t.OrgId && x.Status == "Accepted").ToListAsync();
    string DK(DateTime? d) => d == null ? "" : d.Value.ToString("yyyy-MM-dd");
    var dFrom = (from ?? "").Trim(); var dTo = (to ?? "").Trim();
    if (dFrom.Length > 0) claims = claims.Where(x => string.CompareOrdinal(DK(x.ApprovedDate), dFrom) >= 0).ToList();
    if (dTo.Length > 0) claims = claims.Where(x => string.CompareOrdinal(DK(x.ApprovedDate), dTo) <= 0).ToList();

    var byId = claims.ToDictionary(c => c.Id);
    var ids = claims.Select(c => c.Id).ToList();
    var svcItems = await db.WarrantyClaimServiceItems
        .Where(i => i.OrgId == t.OrgId && ids.Contains(i.ClaimId)).ToListAsync();
    var partItems = await db.WarrantyClaimPartItems
        .Where(i => i.OrgId == t.OrgId && ids.Contains(i.ClaimId)).ToListAsync();

    // INNER JOIN của #407 vẫn áp: đề nghị không có dòng nào thì không xuất hiện.
    var raw = new List<(string? RONo, string? FrameNo, string ItemType, decimal VAT,
        string? ItemCode, string? ItemName, decimal Service, decimal Part, string ItemIndex, string Rank)>();
    foreach (var i in svcItems)
    {
        if (!byId.TryGetValue(i.ClaimId, out var c)) continue;
        var p = i.Factor * i.Price + i.Factor * i.Price * i.VAT * 0.01m;
        raw.Add((c.RONo, c.Vin, "Công", i.VAT, i.SerCode, i.SerName, p, 0m, "2",
            i.ROWSerType == "CVC" ? "1" : i.ROWSerType == "CVPSN" ? "2" : "3"));
    }
    foreach (var i in partItems)
    {
        if (!byId.TryGetValue(i.ClaimId, out var c)) continue;
        var p = i.Factor * i.Price * i.Quantity + i.Factor * i.Price * i.Quantity * i.Vat * 0.01m;
        raw.Add((c.RONo, c.Vin, "Phụ tùng", i.Vat, i.PartCode, i.PartName, 0m, p, "1",
            i.RowPartType == "PTC" ? "1" : i.RowPartType == "PTTT" ? "2"
                : i.RowPartType == "VTP" ? "3" : "4"));
    }
    raw = raw.OrderBy(r => r.RONo).ThenByDescending(r => r.ItemIndex).ThenBy(r => r.Rank).ToList();

    // Convert.ToInt32 trên decimal = làm tròn NGÂN HÀNG (ties-to-even) — giống hệt nguồn.
    int overflow = 0;
    long ToInt32Like(decimal v)
    {
        var r = Math.Round(v, 0, MidpointRounding.ToEven);
        if (r > int.MaxValue || r < int.MinValue) { overflow++; return r > 0 ? int.MaxValue : int.MinValue; }
        return (long)r;
    }

    var rows = new List<object>();
    decimal sumColumns = 0m, sumTotalAmount = 0m, sumExact = 0m;
    foreach (var r in raw)
    {
        // 🔴 Cột: ToEven. Tổng: AwayFromZero TRÊN GIÁ TRỊ GỐC. Hai kiểu làm tròn, một dòng.
        var svcCol = ToInt32Like(r.Service);
        var partCol = ToInt32Like(r.Part);
        var totalAmount = Math.Round(r.Service + r.Part, 0, MidpointRounding.AwayFromZero);
        sumColumns += svcCol + partCol; sumTotalAmount += totalAmount; sumExact += r.Service + r.Part;
        rows.Add(new
        {
            RONo = r.RONo, FrameNo = r.FrameNo, ItemType = r.ItemType, VAT = r.VAT,
            ItemCode = r.ItemCode, ItemName = r.ItemName,
            SERVICEPRICE = svcCol,      // đã Convert.ToInt32 (ToEven)
            PARTPRICE = partCol,        // đã Convert.ToInt32 (ToEven)
            TOTALAMOUNT = totalAmount,  // Math.Round(gốc, AwayFromZero)
            // TOTALPRICE và RANKTYPE bị nguồn XOÁ khỏi file ⇒ không trả.
        });
    }

    var columnsDisagree = sumColumns != sumTotalAmount;
    return Results.Ok(new
    {
        count = rows.Count,
        fileNameHint = "BaoCaoChapThuanBaoHanhChiTiet_" + DateTime.Now.ToString("yyyy_MM_dd") + ".xls",
        sumColumns, sumTotalAmount, sumExact, columnsDisagree,
        roundingNote = "SERVICEPRICE/PARTPRICE làm tròn NGÂN HÀNG (Convert.ToInt32, ties-to-even); "
            + "TOTALAMOUNT làm tròn RA XA 0 trên GIÁ TRỊ GỐC chưa làm tròn. Hai kiểu khác nhau ⇒ trong file "
            + "SERVICEPRICE + PARTPRICE có thể KHÁC TOTALAMOUNT ngay trên cùng một dòng (0 + 0 = 1).",
        droppedColumnsNote = "Nguồn XOÁ hai cột TOTALPRICE (tổng CHÍNH XÁC do SQL tính) và RANKTYPE khỏi "
            + "file ⇒ con số đúng duy nhất bị bỏ đi. sumExact ở đây chính là tổng TOTALPRICE đó.",
        int32OverflowRows = overflow,
        int32OverflowNote = overflow > 0
            ? $"{overflow} dòng vượt Int32: nguồn sẽ NÉM OverflowException và SẬP cả thao tác kết xuất. "
              + "MiniHTC CỐ Ý lệch — kẹp giá trị và đếm ra đây thay vì ném."
            : "Nguồn dùng Convert.ToInt32 ⇒ một dòng > 2.147.483.647 VNĐ sẽ làm SẬP cả thao tác kết xuất.",
        sameQueryNote = "Dùng chung WS SerWarrantyAcceptRpt_GetAll với /lines (#407), chỉ bỏ trống đại lý "
            + "và VAT — không có truy vấn mới.",
        rows,
    });
}).RequireAuthorization();

app.MapGet("/api/report/warranty-accept/export", async (AppDbContext db, ITenantContext t,
    string? from, string? to) =>
{
    // Đại lý để TRỐNG = mọi đại lý (đúng `strDealerCodeConditionList = ""` của nguồn).
    var claims = await db.ServiceWarrantyClaims
        .Where(x => x.OrgId == t.OrgId && x.Status == "Accepted").ToListAsync();
    var dFrom = (from ?? "").Trim(); var dTo = (to ?? "").Trim();
    string DK(DateTime? d) => d == null ? "" : d.Value.ToString("yyyy-MM-dd");
    if (dFrom.Length > 0) claims = claims.Where(x => string.CompareOrdinal(DK(x.ApprovedDate), dFrom) >= 0).ToList();
    if (dTo.Length > 0) claims = claims.Where(x => string.CompareOrdinal(DK(x.ApprovedDate), dTo) <= 0).ToList();

    var ids = claims.Select(c => c.Id).ToList();
    var svcItems = await db.WarrantyClaimServiceItems
        .Where(i => i.OrgId == t.OrgId && ids.Contains(i.ClaimId)).ToListAsync();
    var partItems = await db.WarrantyClaimPartItems
        .Where(i => i.OrgId == t.OrgId && ids.Contains(i.ClaimId)).ToListAsync();
    var svcByClaim = svcItems.GroupBy(i => i.ClaimId).ToDictionary(g => g.Key, g => g.ToList());
    var partByClaim = partItems.GroupBy(i => i.ClaimId).ToDictionary(g => g.Key, g => g.ToList());

    var dealerNames = await db.Dealers.Where(d => d.OrgId == t.OrgId)
        .Select(d => new { d.DealerCode, d.DealerName }).ToListAsync();
    var dealerName = dealerNames.GroupBy(d => d.DealerCode)
        .ToDictionary(g => g.Key, g => g.First().DealerName);
    // Phụ tùng LỖI: nguồn join `Ser_MST_Part` theo `PartIDError` để lấy mã + tên.
    var errIds = claims.Select(c => c.PartIDError).Where(x => !string.IsNullOrWhiteSpace(x)).Distinct().ToList();
    var errParts = await db.ServiceParts.Where(p => p.OrgId == t.OrgId && errIds.Contains(p.PartID))
        .Select(p => new { p.PartID, p.PartCode, p.PartName }).ToListAsync();
    var errByPartId = errParts.Where(p => p.PartID != null).GroupBy(p => p.PartID!)
        .ToDictionary(g => g.Key, g => g.First());

    // Dọn văn bản đúng nguồn — CarStatus bị bỏ CẢ khoảng trắng, CusRequest thì không.
    static string? Clean(string? v, bool stripSpace)
    {
        if (v == null) return null;
        var s = v.Replace("-", "").Replace("'", "").Replace("\n", "");
        if (stripSpace) s = s.Replace(" ", "");
        s = s.Trim();
        return s.Length > 255 ? s.Substring(0, 255) : s;
    }
    static string? TitleOne(string? v)
        => string.IsNullOrWhiteSpace(v) ? v : char.ToUpperInvariant(v![0]) + v.Substring(1).ToLowerInvariant();

    var rows = new List<object>();
    decimal roundedTotalSum = 0m, exactTotalSum = 0m;
    foreach (var c in claims)
    {
        var svs = svcByClaim.TryGetValue(c.Id, out var s1) ? s1 : new List<WarrantyClaimServiceItem>();
        var pts = partByClaim.TryGetValue(c.Id, out var p1) ? p1 : new List<WarrantyClaimPartItem>();
        decimal servicePrice = svs.Sum(i => i.Factor * i.Price + i.Factor * i.Price * i.VAT * 0.01m);
        decimal partPrice = pts.Sum(i => i.Factor * i.Price * i.Quantity
                                        + i.Factor * i.Price * i.Quantity * i.Vat * 0.01m);
        // 🔴 Làm tròn về SỐ NGUYÊN, nửa lẻ ra xa 0 — đúng `Math.Round(x, MidpointRounding.AwayFromZero)`.
        decimal exact = servicePrice + partPrice;
        decimal totalAmount = Math.Round(exact, 0, MidpointRounding.AwayFromZero);
        roundedTotalSum += totalAmount; exactTotalSum += exact;

        var mainSvc = svs.Where(i => i.ROWSerType == "CVC").OrderBy(i => i.Id).FirstOrDefault();
        var mainPart = pts.Where(i => i.RowPartType == "PTC").OrderBy(i => i.Id).FirstOrDefault();
        errByPartId.TryGetValue(c.PartIDError ?? "", out var ep);

        // Thứ tự khai báo dưới đây = đúng thứ tự `SetOrdinal` của nguồn (ROWID/ROWNo đã bị bỏ).
        rows.Add(new
        {
            DealerCode = c.DealerCode,
            DealerName = c.DealerCode != null && dealerName.TryGetValue(c.DealerCode, out var dn) ? dn : null,
            RONo = c.RONo,
            HTCROWNo = (string?)null,          // chưa mô hình hoá trong MiniHTC
            FrameNo = c.Vin,
            PlateNo = c.PlateNo,
            WarrantyRegistrationDate = c.WarrantyRegistrationDate,
            Km = c.Km,
            PartCodeError = ep?.PartCode,
            PartNameError = ep?.PartName,
            ITEMCODE = mainPart?.PartCode ?? mainSvc?.SerCode,
            ITEMNAME = TitleOne(mainPart?.PartName ?? mainSvc?.SerName),
            PartCode = mainPart?.PartCode,
            VieName = mainPart?.PartName,
            Quantity = mainPart?.Quantity,
            SerCode = mainSvc?.SerCode,
            SerName = mainSvc?.SerName,
            StdManHour = mainSvc?.StdManHour,
            ErrorCodePN = c.ErrorCodePN,
            ErrorCodeCD = c.ErrorCodeCD,
            CarStatus = Clean(c.CarStatus, true),    // 🔴 bỏ CẢ khoảng trắng
            SERVICEPRICE = servicePrice,
            PARTPRICE = partPrice,
            TOTALAMOUNT = totalAmount,
            // ===== #502 TRẢ NỬA NỢ: nhãn trạng thái bảo hành ĐÃ có bảng mã (6 mã, không ELSE) =====
            // Bảng mã lấy đúng CASE của nguồn (SENT/PEND/CONF/ACCE/REJ/REVERT) — đã dùng ở #460/#466.
            WARRANTYSTATUSTEXT = c.Status switch
            {
                "SENT" => "Chờ xem xét",
                "PEND" => "Chưa gửi",
                "CONF" => "Chờ duyệt",
                "ACCE" => "Chấp thuận B.H",
                "REJ" => "Không duyệt",
                "REVERT" => "HTC Hoàn trả",
                _ => (string?)null,   // nguồn KHÔNG có ELSE ⇒ mã lạ ra null
            },
            CusRequest = Clean(c.CusRequest, false),
            StartDate = c.StartDate,
            FinishedDate = c.FinishedDate,
            CreatedDate = c.CreatedAt,
        });
    }

    return Results.Ok(new
    {
        count = rows.Count,
        fileNameHint = "BaoCaoChapThuanBaoHanh_" + DateTime.Now.ToString("yyyy_MM_dd") + ".xls",
        roundedTotalSum, exactTotalSum,
        roundingNote = "TOTALAMOUNT làm tròn về SỐ NGUYÊN (AwayFromZero) TỪNG DÒNG rồi mới cộng ⇒ "
            + "roundedTotalSum có thể LỆCH exactTotalSum. Đây là chủ đích của nguồn (khớp TotalAmount.Summary).",
        textCleanNote = "CusRequest bỏ - ' và xuống dòng; CarStatus bỏ - ' VÀ TOÀN BỘ khoảng trắng; "
            + "cả hai cắt còn 255 ký tự — đúng nguồn.",
        // #502: WARRANTYSTATUSTEXT đã trả (dùng bảng mã 6 giá trị của nguồn).
        //   HTCROWNo vẫn nợ: nguồn lấy từ hàm vô hướng SQL 
        //   — không tái tạo được nếu chưa biết thân hàm đó, nên KHÔNG bịa.
        // #502b NỬA NỢ ĐÃ TRẢ: `WARRANTYSTATUSTEXT` nay dựng từ bảng mã 6 giá trị của nguồn
        //   (`SENT`/`PEND`/`CONF`/`ACCE`/`REJ`/`REVERT`, **không có ELSE**) — cùng bảng đã dùng ở #460/#466.
        //   Nợ này trôi lâu chỉ vì ghi chú cũ gộp **hai** cột vào một cờ; tách ra thì một nửa **trả được ngay**.
        //   📌 Lệ: cờ nợ nên đặt **cho từng cột**, đừng gộp — gộp thì phần trả được cũng bị chôn theo.
        // 🔴 `HTCROWNo` **VẪN NỢ**: nguồn lấy từ hàm vô hướng SQL `dbo.ROWarrantyGetHTCWRID(ROWID)`;
        //   chưa đọc được thân hàm đó nên **không bịa** cách sinh mã.
        columnsNotModelled = new[] { "HTCROWNo" },
        warrantyStatusTextPaid = true,
        droppedByCommentNote = "BulletinNoHMC có trên lưới nhưng dòng SetOrdinal của nó đã bị COMMENT "
            + "trong nguồn ⇒ KHÔNG ra file (port dòng active, luật B).",
        allDealerNote = "Nút kết xuất gọi SerWarrantyAcceptRptAllDealer = CÙNG WS với nút xem báo cáo, "
            + "chỉ bỏ trống điều kiện đại lý và VAT.",
        rows,
    });
}).RequireAuthorization();

// #303 Dòng CÔNG của một đề nghị bảo hành.
// ===== 🔴 #308 LẦN SỬA GẦN NHẤT TRƯỚC ĐÓ của CÙNG XE + CÙNG PHỤ TÙNG (bảo hành LẶP) =====
// Nguồn: `Ser_ROWarrantyReportHTC_Get_OnlyOneROWID` (`WarrantyReport.cs:17800`), khối
//   `select top 1 … into #tblSer_ROActualDeliveryDate`. Xuất hiện **6 chỗ** trong hai file
//   (`WarrantyReport.cs` ×4 · `WH.cs` ×2) — cùng một luật, dùng ở nhiều màn bảo hành.
//
// 🆕 Tìm ra nhờ **sweep `top 1` lệch trục** (`_audit/sweep_top1_orderby_mismatch.js`, sinh từ bài học
//   `C0-quingentesimustricesimusseptimus` ở #307). Ở ĐÂY lệch trục là **CHỦ ĐÍCH**, không phải lỗi:
//   `select sr.ROID … order by sr.ActualDeliveryDate desc` = "lấy LỆNH của lần GIAO XE gần nhất".
//   (Khác hẳn `StockInDateLastest` của #307 — chỗ đó order/select thật sự lệch ý nghĩa.)
//
// 🔴 BỐN điều kiện, bỏ cái nào cũng sai:
//   1. `t.ROID > sr.ROID` — chú thích nguồn: *"Chỉ lấy những báo giá trước đó"*.
//      ⚠️ Nguồn dùng **thứ tự KHOÁ TĂNG DẦN thay cho thứ tự thời gian** (ROID nhỏ hơn = cũ hơn),
//        KHÔNG so ngày. Port bằng `Id` để giữ đúng ngữ nghĩa đó.
//   2. `inner join Ser_ROPartItems on sr.ROID = srpart.ROID AND t.PartID = srpart.PartID`
//      ⇒ chỉ tính lần sửa **có dùng ĐÚNG phụ tùng đang xét** — đây là cốt lõi của "bảo hành lặp".
//   3. `sr.ActualDeliveryDate is not null` — phải **đã giao xe** mới tính là một lần sửa hoàn tất.
//   4. `sr.Status not in ('REJ')` — **BLACKLIST đúng MỘT mã** (lệnh huỷ), không phải whitelist
//      danh sách trạng thái hợp lệ. Mã lạ/NULL **vẫn được tính**.
//
// ⚠️ Ghép xe theo **FrameNo** (số khung) rồi mới sang `CarID` — không ghép thẳng `CarID`.
// ⚠️ `ActualDeliveryDate` nguồn `convert(varchar, …, 23)` ⇒ trả **CHUỖI `yyyy-MM-dd`**.
// ⚠️ Trả kèm `Km` — cùng với ngày giao, đây là hai số để tính "lặp sau bao lâu / bao nhiêu km".
// ===== 🔴 #378 ĐỐI CHIẾU BẢN `_WH` của guard 'lần sửa trước đó' — LỆCH NGHIỆP VỤ, KHÔNG PHẢI ĐỔI CSDL =====
// Nguồn có bốn hàm cùng họ: `Ser_ROWarrantyReportHTC_Get_OnlyOneROWID(_New20230417)` (`WarrantyReport.cs`)
// và `…_WH(_New20230417)` (`WH.cs:33266/33646`). Diff bỏ khoảng trắng giữa hai bản **LIVE**:
//
// 🔴 **ĐIỀU KIỆN CHỌN LẦN SỬA KHÁC HẲN NHAU**:
//     bản Main: `and t.ROID > sr.ROID`  `-- Chỉ lấy những báo giá trước đó`
//     bản `_WH` : `and t.ROID <> sr.ROID`   (**không** có chú thích)
//   ⇒ Bản Main chỉ xét các lệnh **TRƯỚC ĐÓ**; bản `_WH` xét **MỌI lệnh khác, kể cả lệnh SAU**.
//     Vì sau đó còn `order by ActualDeliveryDate desc` nên bản `_WH` có thể trả về một lần sửa
//     **XẢY RA SAU** đề nghị bảo hành và gọi đó là 'lần thay gần nhất trước đó' — sai nghiệp vụ,
//     và làm hai màn (HTC vs kho) cho ra **kết quả khác nhau trên cùng một hồ sơ**.
// ⚠️ Danh mục loại BCBH: bản Main join qua `[@strDBName_CommonCenter]`, bản `_WH` join bảng cục bộ;
//   một chỗ trong bản `_WH` còn đổi `--//[mylock]` thành `with(nolock)` ⇒ **gợi ý khoá khác nhau**.
//   (Cùng lệ #376: hậu tố `_WH` không chỉ là đổi CSDL.)
// 📌 MiniHTC một CSDL: `scope` tái hiện **khác biệt điều kiện**, mặc định `main` (bản đúng nghiệp vụ).
app.MapGet("/api/warrantyclaims/{id:long}/previous-repair", async (long id, AppDbContext db, ITenantContext t, string? scope) =>
{
    var c = await db.ServiceWarrantyClaims.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (c is null) return Results.NotFound(new { claimId = id });

    // Lệnh sửa chữa của chính đề nghị này (mốc để so "trước đó").
    var curRo = c.ROID is not null
        ? await db.RepairOrders.FirstOrDefaultAsync(r => r.OrgId == t.OrgId && r.Id.ToString() == c.ROID)
        : null;
    curRo ??= c.RONo is not null
        ? await db.RepairOrders.FirstOrDefaultAsync(r => r.OrgId == t.OrgId && r.RONo == c.RONo)
        : null;
    if (curRo is null) return Results.Ok(new { claimId = id, found = false, reason = "Chưa xác định được lệnh sửa chữa của đề nghị." });

    var vin = curRo.Vin ?? c.Vin;
    if (string.IsNullOrWhiteSpace(vin))
        return Results.Ok(new { claimId = id, found = false, reason = "Đề nghị/lệnh không có số khung." });

    // Phụ tùng của đề nghị — chỉ xét lần sửa nào có dùng ĐÚNG một trong các mã này.
    var partCodes = await db.WarrantyClaimPartItems
        .Where(p => p.OrgId == t.OrgId && p.ClaimId == c.Id)
        .Select(p => p.PartCode).Distinct().ToListAsync();
    if (partCodes.Count == 0)
        return Results.Ok(new { claimId = id, found = false, reason = "Đề nghị chưa có dòng phụ tùng." });

    // Các lệnh TRƯỚC ĐÓ của cùng xe: theo THỨ TỰ KHOÁ (Id < Id hiện tại), đúng như nguồn.
    // #378: bản _WH dùng `<>` thay vì `>` ⇒ nhận CẢ lệnh sau. Mặc định giữ bản Main.
    var whScope = (scope ?? "main").Trim().ToLowerInvariant() == "wh";
    var priorRoIds = await db.RepairOrders
        .Where(r => r.OrgId == t.OrgId && r.Vin == vin
                    && (whScope ? r.Id != curRo.Id : r.Id < curRo.Id)
                    && r.ActualDeliveryDate != null
                    && r.Status != "Rejected")            // blacklist đúng MỘT mã, đúng nguồn
        .Select(r => r.Id).ToListAsync();
    if (priorRoIds.Count == 0)
        return Results.Ok(new { claimId = id, found = false, reason = "Xe chưa có lần sửa nào trước đó đã giao." });

    // Lọc tiếp: lệnh đó phải có dùng đúng phụ tùng đang xét.
    var matchedRoIds = await db.RoPartItems
        .Where(pi => pi.OrgId == t.OrgId && priorRoIds.Contains(pi.RoId) && partCodes.Contains(pi.PartCode))
        .Select(pi => pi.RoId).Distinct().ToListAsync();
    if (matchedRoIds.Count == 0)
        return Results.Ok(new { claimId = id, found = false, reason = "Chưa từng thay đúng phụ tùng này ở lần sửa trước." });

    // top 1 theo NGÀY GIAO XE giảm dần (lệch trục có chủ đích — xem chú thích đầu khối).
    var prev = await db.RepairOrders
        .Where(r => r.OrgId == t.OrgId && matchedRoIds.Contains(r.Id))
        .OrderByDescending(r => r.ActualDeliveryDate)
        .FirstOrDefaultAsync();
    if (prev is null) return Results.Ok(new { claimId = id, found = false });

    return Results.Ok(new
    {
        claimId = id, found = true,
        // #378: bản _WH của nguồn dùng `<>` nên có thể trả về một lần sửa XẢY RA SAU.
        scope = whScope ? "wh" : "main",
        scopeNote = whScope
            ? "Bản _WH dùng `t.ROID <> sr.ROID` ⇒ nhận CẢ lệnh SAU đề nghị; kết quả có thể KHÔNG phải lần sửa trước đó."
            : "Bản Main dùng `t.ROID > sr.ROID` — chỉ xét lệnh TRƯỚC ĐÓ (đúng nghiệp vụ).",
        laterRepairReturned = whScope && prev.Id > curRo.Id,
        roId = prev.Id, prev.RONo, prev.Km,
        actualDeliveryDate = prev.ActualDeliveryDate?.ToString("yyyy-MM-dd"),   // convert(varchar,…,23)
        daysSincePrevious = prev.ActualDeliveryDate.HasValue
            ? (int?)(DateTime.Now.Date - prev.ActualDeliveryDate.Value.Date).TotalDays : null,
        partCodes,
        note = "Lần sửa TRƯỚC ĐÓ (theo thứ tự khoá, đúng nguồn) của cùng xe và có dùng đúng phụ tùng đang xét; "
             + "đã giao xe và không phải lệnh huỷ. Dùng để xét bảo hành LẶP.",
    });
}).RequireAuthorization();

app.MapGet("/api/warrantyclaims/{id:long}/serviceitems", async (long id, AppDbContext db, ITenantContext t) =>
{
    var items = await db.WarrantyClaimServiceItems.Where(i => i.OrgId == t.OrgId && i.ClaimId == id)
        .OrderBy(i => i.Id).ToListAsync();
    return Results.Ok(new { claimId = id, count = items.Count, items = items.Select(i => new
    {
        itemId = i.Id, i.SerID, i.SerCode, i.SerName, i.ROWSerType, i.Factor, i.Price, i.VAT,
        i.StdManHour, i.WarrantyStatus, i.Note, i.BulletinID, i.CreatedDate, i.CreatedBy,
        servicePrice = i.Factor * i.Price + i.Factor * i.Price * i.VAT * 0.01m,
    }) });
}).RequireAuthorization();

app.MapPost("/api/warrantyclaims/{id:long}/serviceitems", async (long id, WarrantyClaimServiceItemDto dto,
    AppDbContext db, ITenantContext t) =>
{
    var c = await db.ServiceWarrantyClaims.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (c is null) return Results.NotFound(new { claimId = id });
    var type = string.IsNullOrWhiteSpace(dto.ROWSerType) ? null : dto.ROWSerType!.Trim().ToUpperInvariant();
    if (type is not null && type != "CVC" && type != "CVPSN")
        return Results.BadRequest(new { error = "Loại công việc không hợp lệ (chỉ CVC hoặc CVPSN)." });
    // Nguồn: mỗi đề nghị chỉ ĐÚNG MỘT dòng công chính — cùng luật với phụ tùng chính "PTC".
    if (type == "CVC" && await db.WarrantyClaimServiceItems.AnyAsync(i => i.OrgId == t.OrgId && i.ClaimId == id && i.ROWSerType == "CVC"))
        return Results.BadRequest(new { error = "Báo cáo bảo hành chỉ có 1 công việc chính!" });

    var r = new WarrantyClaimServiceItem
    {
        OrgId = t.OrgId, ClaimId = id,
        SerID = dto.SerID, SerCode = dto.SerCode, SerName = dto.SerName, ROWSerType = type,
        Factor = dto.Factor, Price = dto.Price, VAT = dto.VAT, StdManHour = dto.StdManHour,
        WarrantyStatus = dto.WarrantyStatus, Note = dto.Note,
        // ⚠️ Nguồn coi chuỗi "0" như RỖNG cho BulletinID (WarrantyReport.cs:246) — bỏ qua, không ghi.
        BulletinID = string.IsNullOrWhiteSpace(dto.BulletinID) || dto.BulletinID == "0" ? null : dto.BulletinID,
        CreatedBy = dto.CreatedBy, LogLUDateTime = DateTime.Now, LogLUBy = dto.CreatedBy,
    };
    db.WarrantyClaimServiceItems.Add(r); await db.SaveChangesAsync();
    return Results.Ok(new { itemId = r.Id, claimId = id, r.ROWSerType,
        servicePrice = r.Factor * r.Price + r.Factor * r.Price * r.VAT * 0.01m });
}).RequireAuthorization();

// Báo cáo NHẬP KHO CHI TIẾT — port 1:1 khối SQL báo cáo nhập của BizCarSv.Inventory.Report.
// Nguồn trả RIÊNG hai cột tiền: Total (trước thuế) và VATAmount (phần thuế), kèm vị trí THỰC nhập.
app.MapGet("/api/report/stockin-detail", async (
    AppDbContext db, ITenantContext t, DateTime? from, DateTime? to, string? dealer, string? supplier) =>
{
    // Nguồn lọc: sti.status = 3 (đã duyệt) + khoảng StockInDate + DealerCode + SupplierID.
    var headers = db.ServiceStockIns.Where(o => o.OrgId == t.OrgId && o.Status == "Confirmed");
    if (from.HasValue) headers = headers.Where(o => o.StockInDate >= from);
    if (to.HasValue) headers = headers.Where(o => o.StockInDate <= to);
    if (!string.IsNullOrWhiteSpace(dealer)) headers = headers.Where(o => o.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(supplier)) headers = headers.Where(o => o.SupplierCode == supplier);

    var rows = await (from line in db.ServiceStockInLines.Where(l => l.OrgId == t.OrgId)
                      join header in headers on line.ServiceStockInId equals header.Id
                      orderby header.StockInDate, header.StockInNo
                      select new
                      {
                          line.PartCode, line.PartName,
                          date = header.StockInDate, header.StockInNo,
                          header.SupplierCode, header.DealerCode,
                          line.Quantity, line.Price,
                          total = line.TotalBeforeVat,
                          line.Vat, vatAmount = line.VatAmount,
                          location = line.ActualLocationCode
                      }).Take(2000).ToListAsync();

    return Results.Ok(new
    {
        count = rows.Count,
        totalBeforeVat = rows.Sum(r => r.total),
        totalVat = rows.Sum(r => r.vatAmount),
        grandTotal = rows.Sum(r => r.total + r.vatAmount),
        rows
    });
}).RequireAuthorization();

// ===== Báo cáo nhập-xuất-tồn + thẻ kho (report tái-dùng ServiceStockIn/Out — port 1:1 FrmReportInOutStock + FrmReportCardStock, TCMotor) =====
// Nhập-xuất-tồn theo mã PT: tổng nhập (phiếu Confirmed), tổng xuất (phiếu Confirmed), tồn hiện tại (ServicePart.Quantity).
app.MapGet("/api/report/stock-inout", async (AppDbContext db, ITenantContext t, DateTime? fromDate, DateTime? toDate) =>
{
    var ins = db.ServiceStockIns.Where(o => o.OrgId == t.OrgId && o.Status == "Confirmed");
    var outs = db.ServiceStockOuts.Where(o => o.OrgId == t.OrgId && o.Status == "Confirmed");
    if (fromDate.HasValue) { ins = ins.Where(o => o.StockInDate.HasValue && o.StockInDate.Value.Date >= fromDate.Value.Date); outs = outs.Where(o => o.StockOutDate.HasValue && o.StockOutDate.Value.Date >= fromDate.Value.Date); }
    if (toDate.HasValue) { ins = ins.Where(o => o.StockInDate.HasValue && o.StockInDate.Value.Date <= toDate.Value.Date); outs = outs.Where(o => o.StockOutDate.HasValue && o.StockOutDate.Value.Date <= toDate.Value.Date); }
    var inIds = ins.Select(o => o.Id); var outIds = outs.Select(o => o.Id);
    var inByPart = await db.ServiceStockInLines.Where(l => l.OrgId == t.OrgId && inIds.Contains(l.ServiceStockInId))
        .GroupBy(l => l.PartCode).Select(g => new { partCode = g.Key, qty = g.Sum(x => x.Quantity) }).ToListAsync();
    var outByPart = await db.ServiceStockOutLines.Where(l => l.OrgId == t.OrgId && outIds.Contains(l.ServiceStockOutId))
        .GroupBy(l => l.PartCode).Select(g => new { partCode = g.Key, qty = g.Sum(x => x.Quantity) }).ToListAsync();
    var parts = await db.ServiceParts.Where(p => p.OrgId == t.OrgId).Select(p => new { p.PartCode, p.PartName, p.Unit, p.Quantity }).ToListAsync();
    var inMap = inByPart.ToDictionary(x => x.partCode, x => x.qty);
    var outMap = outByPart.ToDictionary(x => x.partCode, x => x.qty);
    var codes = parts.Select(p => p.PartCode).Union(inMap.Keys).Union(outMap.Keys).Distinct();
    var pMap = parts.ToDictionary(p => p.PartCode, p => p);
    var rows = codes.Select(c => {
        pMap.TryGetValue(c, out var p);
        var tin = inMap.TryGetValue(c, out var vi) ? vi : 0m;
        var tout = outMap.TryGetValue(c, out var vo) ? vo : 0m;
        return new { partCode = c, partName = p?.PartName, unit = p?.Unit, totalIn = tin, totalOut = tout, current = p?.Quantity ?? 0m };
    }).Where(r => r.totalIn != 0 || r.totalOut != 0).OrderBy(r => r.partCode).ToList();
    return Results.Ok(new { count = rows.Count, sumIn = rows.Sum(r => r.totalIn), sumOut = rows.Sum(r => r.totalOut), rows });
}).RequireAuthorization();

// Thẻ kho 1 mã PT: sổ nhập/xuất theo thời gian + tồn lũy kế (chỉ phiếu Confirmed).
app.MapGet("/api/report/stock-card", async (AppDbContext db, ITenantContext t, string partCode) =>
{
    var code = (partCode ?? "").Trim();
    if (code == "") return Results.BadRequest(new { error = "Cần mã phụ tùng." });
    var inMoves = await (from l in db.ServiceStockInLines.Where(x => x.OrgId == t.OrgId && x.PartCode == code)
                         join h in db.ServiceStockIns.Where(x => x.OrgId == t.OrgId && x.Status == "Confirmed") on l.ServiceStockInId equals h.Id
                         select new { docNo = h.StockInNo, date = h.StockInDate, inQty = l.Quantity, outQty = 0m }).ToListAsync();
    var outMoves = await (from l in db.ServiceStockOutLines.Where(x => x.OrgId == t.OrgId && x.PartCode == code)
                          join h in db.ServiceStockOuts.Where(x => x.OrgId == t.OrgId && x.Status == "Confirmed") on l.ServiceStockOutId equals h.Id
                          select new { docNo = h.StockOutNo, date = h.StockOutDate, inQty = 0m, outQty = l.Quantity }).ToListAsync();
    var moves = inMoves.Concat(outMoves).OrderBy(m => m.date ?? DateTime.MaxValue).ThenBy(m => m.docNo).ToList();
    decimal bal = 0; var ledger = moves.Select(m => { bal += m.inQty - m.outQty; return new { m.docNo, date = m.date.HasValue ? m.date.Value.ToString("yyyy-MM-dd") : "", m.inQty, m.outQty, balance = bal }; }).ToList();
    return Results.Ok(new { partCode = code, totalIn = moves.Sum(m => m.inQty), totalOut = moves.Sum(m => m.outQty), closing = bal, ledger });
}).RequireAuthorization();

// ===== Báo cáo phụ tùng (report tái-dùng ServicePart + ServiceStockOut — port 1:1 FrmReportPartMinQuantity/TopProfit/TopRotate, TCMotor) =====
// Phụ tùng dưới định mức tồn (Quantity < MinQuantity) — cần đặt hàng bổ sung.
app.MapGet("/api/report/part-minquantity", async (AppDbContext db, ITenantContext t) =>
{
    var rows = await db.ServiceParts.Where(x => x.OrgId == t.OrgId && x.FlagActive == "1" && x.Quantity < x.MinQuantity)
        .OrderBy(x => x.Quantity - x.MinQuantity)
        .Select(x => new { x.PartCode, x.PartName, x.Unit, x.Quantity, x.MinQuantity, shortage = x.MinQuantity - x.Quantity, x.Location, x.PartGroupCode }).ToListAsync();
    return Results.Ok(new { count = rows.Count, totalShortage = rows.Sum(r => r.shortage), rows });
}).RequireAuthorization();

// Top phụ tùng lãi cao: lợi nhuận đơn vị = giá bán - giá vốn, và % lãi trên giá vốn.
app.MapGet("/api/report/part-topprofit", async (AppDbContext db, ITenantContext t, int? top) =>
{
    var n = top is > 0 and <= 200 ? top.Value : 20;
    var rows = await db.ServiceParts.Where(x => x.OrgId == t.OrgId && x.FlagActive == "1" && x.Price > 0)
        .Select(x => new { x.PartCode, x.PartName, x.Price, x.Cost, unitProfit = x.Price - x.Cost,
            marginPct = x.Cost > 0 ? Math.Round((x.Price - x.Cost) / x.Cost * 100, 1) : (decimal?)null })
        .OrderByDescending(x => x.unitProfit).Take(n).ToListAsync();
    return Results.Ok(new { count = rows.Count, rows });
}).RequireAuthorization();

// Top phụ tùng luân chuyển: tổng số lượng đã xuất kho (chỉ phiếu đã duyệt) theo mã PT.
app.MapGet("/api/report/part-toprotate", async (AppDbContext db, ITenantContext t, int? top) =>
{
    var n = top is > 0 and <= 200 ? top.Value : 20;
    var confirmedIds = db.ServiceStockOuts.Where(o => o.OrgId == t.OrgId && o.Status == "Confirmed").Select(o => o.Id);
    var rows = await db.ServiceStockOutLines.Where(l => l.OrgId == t.OrgId && confirmedIds.Contains(l.ServiceStockOutId))
        .GroupBy(l => new { l.PartCode, l.PartName })
        .Select(g => new { g.Key.PartCode, g.Key.PartName, totalOut = g.Sum(x => x.Quantity), timesOut = g.Count() })
        .OrderByDescending(x => x.totalOut).Take(n).ToListAsync();
    return Results.Ok(new { count = rows.Count, totalOut = rows.Sum(r => r.totalOut), rows });
}).RequireAuthorization();

// Top phụ tùng doanh thu: doanh thu = SL xuất (phiếu Confirmed) × giá bán hiện tại của PT, lọc khoảng ngày xuất.
app.MapGet("/api/report/part-toprevenue", async (AppDbContext db, ITenantContext t, DateTime? fromDate, DateTime? toDate, int? top) =>
{
    var n = top is > 0 and <= 200 ? top.Value : 20;
    var outs = db.ServiceStockOuts.Where(o => o.OrgId == t.OrgId && o.Status == "Confirmed");
    if (fromDate.HasValue) outs = outs.Where(o => o.StockOutDate.HasValue && o.StockOutDate.Value.Date >= fromDate.Value.Date);
    if (toDate.HasValue) outs = outs.Where(o => o.StockOutDate.HasValue && o.StockOutDate.Value.Date <= toDate.Value.Date);
    var outIds = outs.Select(o => o.Id);
    var qtyByPart = await db.ServiceStockOutLines.Where(l => l.OrgId == t.OrgId && outIds.Contains(l.ServiceStockOutId))
        .GroupBy(l => l.PartCode).Select(g => new { partCode = g.Key, qty = g.Sum(x => x.Quantity) }).ToListAsync();
    var parts = await db.ServiceParts.Where(p => p.OrgId == t.OrgId).Select(p => new { p.PartCode, p.PartName, p.Unit, p.Price }).ToListAsync();
    var priceMap = parts.ToDictionary(p => p.PartCode, p => p);
    var rows = qtyByPart.Select(q => {
        priceMap.TryGetValue(q.partCode, out var p);
        var price = p?.Price ?? 0m;
        return new { q.partCode, partName = p?.PartName, unit = p?.Unit, qtyOut = q.qty, price, revenue = q.qty * price };
    }).OrderByDescending(x => x.revenue).Take(n).ToList();
    return Results.Ok(new { count = rows.Count, totalRevenue = rows.Sum(r => r.revenue), rows });
}).RequireAuthorization();

// Biến động giá phụ tùng: từ các phiếu nhập kho — số lần giá khác nhau, giá thấp nhất/cao nhất theo mã PT.
app.MapGet("/api/report/part-variationprice", async (AppDbContext db, ITenantContext t) =>
{
    var lines = await db.ServiceStockInLines.Where(l => l.OrgId == t.OrgId)
        .Select(l => new { l.PartCode, l.PartName, l.Price }).ToListAsync();
    var rows = lines.GroupBy(l => l.PartCode).Select(g => new
    {
        partCode = g.Key, partName = g.Select(x => x.PartName).FirstOrDefault(x => x != null),
        countPrice = g.Select(x => x.Price).Distinct().Count(), minPrice = g.Min(x => x.Price), maxPrice = g.Max(x => x.Price),
        variation = g.Max(x => x.Price) - g.Min(x => x.Price)
    }).Where(r => r.countPrice > 1).OrderByDescending(r => r.variation).ToList();
    return Results.Ok(new { count = rows.Count, rows });
}).RequireAuthorization();

// ===== Lịch hẹn dịch vụ + bảng khoang/bay (ServiceAppointment — port 1:1 FrmAppList + FrmShowCavityStatus, TCMotor) =====
// ===== 🔴 #474 BỘ LỌC THẬT CỦA MÀN DANH SÁCH LỊCH HẸN — `Ser_App_GetStatusList01_New20201230` =====
// #285 mới port **bảng nhãn trạng thái**; bản thân **bộ lọc** thì endpoint này còn thiếu 4/6.
// Nguồn (`ZTemp.cs:26252`) dùng **BA bộ dựng mệnh đề khác quy ước nhau trong CÙNG một truy vấn**:
//   · `BuildClauseConditionSingle("and","car.PlateNo","like","@strPlateNoParttern",…)` — **tự cấp toán tử**,
//     giá trị bind NGUYÊN VĂN ⇒ người gọi phải tự thêm `%`.
//   · `BuildClause("and","cus.CusName", …)` · `"ro.AppDateTimeFrom"` · `"ro.Creator"` — **ĐÒI toán tử ở đầu
//     chuỗi**; thiếu toán tử là **bỏ im lặng** (luật #410).
//   · `BuildClauseConditionList("and","ro.AppTypeCode", strAppTypeCodeList, "|")` — **KHÔNG đọc toán tử**,
//     mọi token thành giá trị IN. Truyền `"= TYPE1"` vào đây thì `"="` bị coi là **một mã loại**.
//   ⇒ Cùng một màn, ba tham số ba luật. Port mô hình hoá theo NGHĨA (contains / equals / IN) và ghi rõ.
//
// 🔴 **BỘ LỌC "LÁT CẮT THỜI ĐIỂM" `strDateTimeline`** — chỉ bản Main có:
//     `and (ro.AppDateTimeFrom <= X and ro.AppDateTime >= X)`
//   tức "lịch hẹn **đang mở tại thời điểm X**" (X nằm trong khoảng từ–đến), KHÔNG phải "hẹn trong ngày X".
//   Bản `_WH_New20201230` **không có** mệnh đề này (46 → 37 dòng SQL) ⇒ màn kho **không lọc được theo lát
//   cắt thời điểm**, trả nhiều dòng hơn. Cờ `timelineFilterMissingInWhBranch`.
// ⚠️ **BAKE-PARAM MIX**: riêng mệnh đề này nối chuỗi có nháy (`"… <= '" + strDateTimeline + "'"`) trong khi
//   các mệnh đề anh em đều dùng tham số ⇒ trộn hai lối trong một câu (lệ đã ghi ở sổ). Port dùng tham số thật.
// ⚪ KIỂM TRA ÂM TÍNH (#403): mệnh đề này **CÓ** guard `if (!StringUtils.IsEmpty(strDateTimeline))` ⇒
//   bỏ trống thì **không lọc**, KHÔNG rơi vào bẫy `<= ''` trả 0 dòng. Ghi lại để lượt sau khỏi soi lại.
// ⚪ `inner join` (Main) vs `join` (WH) sang `Ser_Customer`/`Ser_Car`/`Ser_MST_TradeMark` — **cùng nghĩa**,
//   không phải khác biệt. (Nhưng vẫn là 3 INNER ⇒ thiếu khách/xe/hãng là **mất dòng lúc ĐỌC**.)
// ===== 🔴 #542 VÁ TRA CỨU LỊCH HẸN THEO BẢN MÁY TÍNH BẢNG `Ser_App_GetX_New20220926` =====
// Nguồn: `BizCarSv.Tab.cs:2329 Ser_App_GetForTab_New20210108` — **vỏ bọc**, thân thật là
//   `Ser_App_GetX_New20220926` (`:4114`). Bản port cũ (#474) mới phủ 4 bộ lọc, còn thiếu **ba** thứ:
//
// 🔴 **1) KHOẢNG THỜI GIAN GIAO NHAU — BỐN VẾ `OR`, không phải một mốc**:
//   Nguồn dựng khi có **cả** `DateTimelineFrom` lẫn `DateTimelineTo`:
//     `and (( AppDateTime BETWEEN từ..đến )`
//     ` or ( AppDateTimeFrom BETWEEN từ..đến )`
//     ` or ( AppDateTimeFrom >= từ and AppDateTime <= đến )`
//     ` or ( AppDateTimeFrom <= từ and AppDateTime >= đến ))`
//   ⇒ Bốn kiểu **chồng lấn** giữa lịch hẹn và khoảng hỏi (bắt đầu trong, kết thúc trong, nằm trong,
//     bao trùm). Bản port cũ chỉ có `timeline` **một mốc** ⇒ **bỏ sót** lịch hẹn bao trùm/giao một phần.
// 🔴 **2) NỐI CHUỖI THẲNG GIÁ TRỊ CLIENT**: bốn vế trên ghép bằng `"... >= '" + strDateTimelineFrom + "'"`
//   — **không tham số hoá** ⇒ bề mặt **tiêm SQL ở bộ lọc ĐỌC** (họ #536/#538 vốn ở câu XOÁ).
// 🔴 **3) PHÂN TRANG + TỔNG SỐ**: nguồn có `#tbl_Ser_App_Filter_Draft` với `identity()` rồi lọc
//   `MyIdxSeq` theo `@nFilterRecordStart/@nFilterRecordEnd`, và trả riêng `select Count(0) MyCount`.
//   Bản port cũ cắt cứng `Take(500)`, **không** trả tổng ⇒ client không biết còn bao nhiêu.
//   ⚠️ Nhưng `identity()` lại gán trên `select distinct … **không có `order by`**` (y hệt #533)
//     ⇒ **trang không ổn định**. Port sắp tường minh trước khi cắt + cờ `sourceHasNoOrderBy`.
// 🔴 **4) HAI `inner join` LÀM RƠI DÒNG**: `inner join ser_Customer on sera.CusID = cus.CusID` và
//   `inner join ser_car on sera.carid = car.carid and sera.cusid = car.cusid` ⇒ lịch hẹn **chưa gắn
//   khách/xe** (khách vãng lai đặt hẹn) **biến mất khỏi danh sách** — luật #410. MiniHTC lưu lịch hẹn
//   phẳng nên **không** rơi; nêu cờ `sourceInnerJoinsDropUnlinkedAppointments` để biết vì sao số lệch.
// ⚪ `left join sys_user su on Creator = UserCode and DealerCode = DealerCode` — **không cột nào của `su`**
//   được select, **không** điều kiện WHERE nào trên `su` ⇒ LEFT **còn sống nhưng THỪA** (họ #414
//   "khai báo rồi không dùng"): chỉ tốn một phép nối cross-DB mỗi lần tra.
app.MapGet("/api/appointments", async (AppDbContext db, ITenantContext t, string? plate, string? status,
    DateTime? date, string? cusName, string? creator, string? appTypeCodes,
    DateTime? appDateTimeFrom, DateTime? timeline, string? scope,
    DateTime? timelineFrom, DateTime? timelineTo, int? recordStart, int? recordCount) =>
{
    var isWh = string.Equals(scope?.Trim(), "wh", StringComparison.OrdinalIgnoreCase);
    var q = db.ServiceAppointments.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(plate)) q = q.Where(x => x.PlateNo != null && x.PlateNo.Contains(plate!));
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(x => x.Status == status);
    if (date.HasValue) { var d0 = date.Value.Date; var d1 = d0.AddDays(1); q = q.Where(x => x.AppFrom >= d0 && x.AppFrom < d1); }
    // #474: bốn bộ lọc còn thiếu của nguồn.
    if (!string.IsNullOrWhiteSpace(cusName)) q = q.Where(x => x.CusName != null && x.CusName.Contains(cusName!.Trim()));
    if (!string.IsNullOrWhiteSpace(creator)) q = q.Where(x => x.Creator == creator!.Trim());
    if (appDateTimeFrom.HasValue) q = q.Where(x => x.AppFrom >= appDateTimeFrom);
    if (!string.IsNullOrWhiteSpace(appTypeCodes))
    {
        // BuildClauseConditionList: tách theo "|", MỌI token là giá trị IN (không có toán tử).
        var codes = appTypeCodes!.Split((char)124, StringSplitOptions.RemoveEmptyEntries)
            .Select(x => x.Trim()).Where(x => x.Length > 0).ToList();
        if (codes.Count > 0) q = q.Where(x => x.AppTypeCode != null && codes.Contains(x.AppTypeCode));
    }
    // Lát cắt thời điểm — CHỈ bản Main có; bản kho bỏ qua.
    var timelineApplied = false;
    if (timeline.HasValue && !isWh)
    {
        q = q.Where(x => x.AppFrom <= timeline && x.AppTo >= timeline);
        timelineApplied = true;
    }
    // #542 Khoảng GIAO NHAU bốn vế — đúng nguồn (chỉ áp khi có ĐỦ hai đầu, như nguồn).
    var timelineRangeApplied = false;
    if (timelineFrom.HasValue && timelineTo.HasValue)
    {
        var f = timelineFrom.Value; var e = timelineTo.Value;
        q = q.Where(x => (x.AppTo >= f && x.AppTo <= e)
            || (x.AppFrom >= f && x.AppFrom <= e)
            || (x.AppFrom >= f && x.AppTo <= e)
            || (x.AppFrom <= f && x.AppTo >= e));
        timelineRangeApplied = true;
    }

    // #542 Tổng số TRƯỚC khi cắt trang — nguồn trả riêng bảng MySummary (Count(0) MyCount).
    var myCount = await q.CountAsync();
    var start = Math.Max(0, recordStart ?? 0);
    var take = recordCount is > 0 ? recordCount!.Value : 500;
    var items = await q.OrderBy(x => x.AppFrom).ThenBy(x => x.Id).Skip(start).Take(take).Select(x => new
    {
        x.Id, x.AppNo, x.CavityName, x.PlateNo, x.CusName, x.Mobile, x.ModelName, x.AppType,
        x.CarID,          // #319 §12: phải có ở CẢ GET lẫn POST
        // #323 §12: 4 cột ngày/giờ THÔ + 2 mã gốc — trả kèm để đối chiếu với AppFrom/AppTo đã gộp.
        x.AppDateTime, x.AppTime, x.AppDateTimeFrom, x.AppTimeFrom, x.AppTypeCode, x.CVDVCode,
        appFrom = x.AppFrom.ToString("yyyy-MM-dd HH:mm"), appTo = x.AppTo.ToString("yyyy-MM-dd HH:mm"), x.Status, x.Note, x.EngineerNo, x.QuoteNo, x.CusRequest,
        // #270 §12: cot bo sung co mat o CA GET lan POST
        x.DealerCode, x.CusID, x.Vin, x.HCCPushStatus, x.HCCPushDateTime,
        x.HCCFinishStatus, x.HCCFinishDateTime,   // #351 §12: ve DONG phai nhin thay duoc nhu ve MO
        // #282 §12
        x.Creator, x.CusAddress, x.CusTel, x.InsNo, x.CavityID, x.Source,
        x.FirstContactDateTime, x.LastContactDateTime,
        serviceItems = db.AppointmentServiceItems.Count(i => i.OrgId == t.OrgId && i.AppNo == x.AppNo),
        partItems = db.AppointmentPartItems.Count(i => i.OrgId == t.OrgId && i.AppNo == x.AppNo)
    }).ToListAsync();
    return Results.Ok(new
    {
        count = items.Count, items,
        // ===== #542 =====
        myCount, recordStart = start, recordCount = take,
        timelineRangeApplied,
        timelineRangeIsFourWayOverlap = "AppDateTime trong / AppDateTimeFrom trong / nam trong / bao trum",
        timelineValuesConcatenatedInSource = "'\" + strDateTimelineFrom + \"' — khong tham so hoa",
        sourceHasNoOrderBy = "identity() tren select distinct khong order by => trang khong on dinh",
        sourceInnerJoinsDropUnlinkedAppointments = "inner join ser_Customer + ser_car",
        deadLeftJoinInSource = "left join sys_user su — khong select cot nao, khong dieu kien nao",
        // ===== #474 =====
        scope = isWh ? "wh" : "main",
        timelineApplied,
        timelineFilterMissingInWhBranch = true,
        appTypeCodesIsInListNotOperator = true,
        bakeParamMixInSource = true,
        timelineHasEmptyGuard = true,
    });
}).RequireAuthorization();

// Đặt lịch hẹn. Guard: giờ kết thúc > bắt đầu; không trùng khoang cùng lúc (bay không được đặt chồng giờ).
// ===== 🔴 #331 ĐẶT LỊCH TỪ ỨNG DỤNG DI ĐỘNG (TVO) — `HTCMobileTVO_Ser_App_Create_New20210423` =====
// (`BizCarSv.TVO.cs:1808`). TRACE TWIN: WS `:37191` gọi bản `_New20210423` ⇒ bản trần (`:1120`) CHẾT.
// BƯỚC 3B: md5 file TVO **giống hệt** giữa laptop (`V20.2023.Release.V2`) và máy 150 (`V20.2023.Release`).
//
// Đây KHÔNG phải bản sao của `POST /api/appointments`: kênh này là **khách tự đặt**, chưa chắc đã có
// hồ sơ ⇒ nguồn **tự sinh khách + xe** rồi mới tạo lịch. Ba khác biệt cốt lõi so với kênh nội bộ:
//
// 🔴 (1) DANH TÍNH KHÁCH TRA THEO **BIỂN SỐ**, không theo tên/điện thoại:
//       `from Ser_Car t inner join Ser_Customer f on t.CusID = f.CusID`
//       `where t.PlateNo = @strPlateNo and f.DealerCode = @strDealerCode and t.IsActive = '1'`
//     ⇒ Biển số đã có tại đại lý đó ⇒ **dùng lại khách + xe cũ**, và tên/di động/địa chỉ vừa gửi lên
//       bị **BỎ QUA HOÀN TOÀN** (nguồn không cập nhật gì lên hồ sơ cũ). Người đặt hộ, người mua lại xe,
//       hay gõ nhầm biển đều rơi vào hồ sơ của chủ cũ. Giữ 1:1 vì đây là luật danh tính của kênh,
//       nhưng trả `customerMatchedByPlate` để chỗ đối chiếu nhìn thấy khi nào hồ sơ cũ được tái dùng.
//
// 🔴 (2) **KHÔNG có guard chồng giờ**. Kênh nội bộ (#325) chặn trùng khoang bằng `MyCheck_DateTime_Cavity`
//     với đủ **3 nhánh** (gồm nhánh bao trùm); kênh di động này **không gọi hàm nào tương tự** —
//     ⇒ khách tự đặt **đè lên lịch đã có** được. Không tự thêm guard (lệ #299: không tự chế luật),
//       trả cờ `overlapNotChecked` để lệch với kênh nội bộ là lệch **nhìn thấy được**.
//
// 🔴 (3) `AppDateTime` ghi **THÔ**, không cắt ngày như kênh nội bộ:
//     TVO: `dt_Ser_App.Rows[0]["AppDateTime"] = strAppDateTime;` (nguyên chuỗi client gửi)
//     nội bộ (#323): `… = Convert.ToDateTime(str).ToString("yyyy-MM-dd");` (**cắt còn ngày**)
//     ⇒ **cùng một cột, hai kênh ghi hai định dạng khác nhau** — đúng kiểu lệch mà sweep #320 truy.
//       Port giữ nguyên thô, trả `appDateTimeRawNote`.
//
// ⚠️ `Source` **đóng cứng** `"HYUNDAIME"` trong nguồn (có chú thích "Fix cứng") ⇒ không cho client đặt.
// ⚠️ `AppStatus = "1"` ghi thẳng chữ số — cùng từ vựng thô của #319, không phải nhãn hiển thị.
// ⚠️ `CreatedDate` dạng `"yyyy-MM-dd HH:mm"` ⇒ **cắt GIÂY** (khác #330 giữ giây).
//
// 📌 `alColumnEffective` trong nguồn được tạo RỖNG rồi truyền thẳng vào `SaveData` — biến chết,
//   không lọc cột nào. Không port.
// 📌 NỢ ĐÃ KHAI (giữ nguyên nợ chung của fleet, không phát sinh mới ở lượt này):
//   nguồn ghi **ba** CSDL `_dbMain` + `_dbWH` + `_dbDealer` trong một giao dịch; MiniHTC một CSDL.
//   Nguồn còn gọi HTTP `NotifyNewAppointment` sang HCC **bên trong giao dịch đang mở** (giữ khoá
//   suốt lời gọi mạng) — tầng HTTP HCC vẫn là nợ; ở đây chỉ trả `pendingAppCount` mà HCC cần.
// ===== 🔴 #372 API MOBILE: KHÁCH ĐẾN HẠN BẢO DƯỠNG (`HTCMobileTVO_GetServiceReminders`) =====
// Nguồn: `BizCarSv.TVO.cs:426-620` — chuỗi 4 bảng tạm `_Draft_01` → `_Draft_02` → `_Draft` → `_Filter`.
// Chú thích của chính nguồn: *"API này trả về danh sách KH đến hạn bảo dưỡng và làm dịch vụ"*.
//
// 🔴 **THAM SỐ NGÀY KHÔNG PHẢI KHOẢNG**: nguồn gán `strFromDate` và `strToDate` **cùng bằng**
//   `StandardizeDate(strDate)` ⇒ luôn chỉ lọc **ĐÚNG MỘT NGÀY**. Tên biến `From`/`To` gợi ý một
//   khoảng, nhưng không có tham số thứ hai nào để truyền. Đừng "sửa cho tiện" thành khoảng ngày.
// 🔴 **PHÂN TRANG KHÔNG PHÂN ĐƯỢC**: `nFilterRecordStart` đóng cứng `0`, `nFilterRecordEnd = start + count - 1`
//   ⇒ API **luôn trả về `count` bản ghi ĐẦU TIÊN**, không có đường nào lấy trang 2. Ứng dụng mobile
//   chỉ "xem thêm" được bằng cách tăng `count`. Giữ 1:1 và báo cờ.
// 🔴 **TRỤC CHỌN BẢN ĐẠI DIỆN LÀ LẦN SỬA CUỐI**, không phải lần tạo:
//   `select top 1 ro.ROID … order by ro.LogLUDateTime desc`
//   ⇒ Một lệnh cũ chỉ cần **bị sửa vặt** (đổi ghi chú, cập nhật hành chính) là **nhảy lên làm đại diện**
//     cho khách đó. Khác hẳn `Tab.cs:8487` (#310) vốn chọn theo `CreatedDate` — cùng mẫu "top 1 lấy
//     bản đại diện" nhưng **hai trục khác nhau** trong cùng một hệ.
// ⚠️ Gộp theo `CusID` lấy `max(ReminderMaintanceDate)` — nhưng bước trước đã lọc về đúng một ngày,
//   nên phép `max` này chỉ còn tác dụng khi cột có phần GIỜ. Giữ nguyên, không rút gọn.
// ⚠️ **KHÔNG lọc đại lý** ở bất kỳ bước nào ⇒ API trả khách của TOÀN hệ. Chạy trên DB Main.
// 📌 Đối chiếu 3 cây: laptop `.V2` = 150 `.Release` (md5 `7860ef59`); `V20` khác md5 cả file nhưng
//   **vùng hàm 426-560 giống hệt** (`c5ea1781`) ⇒ hàm chưa từng đổi.
// ===== 🔴🔴 #562 SỬA #372: **PORT NHẦM BẢN CHẾT** — bản LIVE là `_20210603`, và nó ĐỔI HÌNH DẠNG KẾT QUẢ =====
// TRACE WS (luật "đọc thân WS trước"): `HTCWSCarSvTab/WSCarSvTab.asmx.cs:4747` gọi
//   `_biz.HTCMobileTVO_GetServiceReminders_**20210603**` ⇒ **bản có hậu tố ngày mới là bản SỐNG**.
//   Bản trần `:426` (mà #372 đã port) chỉ còn được gọi từ `WSCarSvTab.asmx.**20210412**.cs` — **file WS cũ**.
// ⚠️ **Bẫy đánh lừa**: bản `_20210603` đặt `strFunctionName = "HTCMobileTVO_GetServiceReminders"` —
//   **không có hậu tố** ⇒ log, mã lỗi, tên SQL debug đều ghi tên bản trần. Ai truy theo **log** sẽ
//   kết luận bản trần đang chạy. Chỉ **thân WS** mới nói đúng.
//
// 📐 DIFF hai bản (luật #414) — khác biệt thật nằm ở **CÁCH CHỌN BẢN ĐẠI DIỆN**, tức **HÌNH DẠNG KẾT QUẢ**:
//   · Bản **chết**: gom theo `CusID` → `max(ReminderMaintanceDate)` → `top 1 … order by LogLUDateTime desc`
//     ⇒ **một KHÁCH một dòng**, trục chọn = **lần sửa cuối**.
//   · Bản **sống**: gom theo `(sc.PlateNo, ro.DealerCode)` → `Max(ro.ROID)`
//     ⇒ **một XE tại một ĐẠI LÝ một dòng**; khách có ba xe ra **ba dòng**; trục chọn = **ROID lớn nhất**.
//   ⇒ Đây đúng là câu §12 không bắt được: *"một bản ghi là một CHỨNG TỪ hay một DÒNG?"* — đổi bản là
//     đổi **số dòng** mà mobile nhận, không phải đổi vài cột.
//
// 🔴 **BỘ LỌC NGẦM Ở BẢN SỐNG — `#tblSer_RO_Max` KHÔNG GIỚI HẠN THEO KỲ**:
//     `from #tbl_PlateNo_DealerCode t inner join Ser_RO ro on ro.DealerCode = t.DealerCode`
//     `inner join Ser_Car sc on ro.CarID = sc.CarID and t.PlateNo = sc.PlateNo`
//   Bảng `Ser_RO` ở đây nối theo **biển + đại lý**, **không** nối lại với `#tbl_Ser_RO_Draft_01` ⇒ quét
//   **TOÀN BỘ lịch sử** lệnh của xe đó, rồi lấy `Max(ROID)`. Sau đó `#tbl_Ser_RO_Draft_02` nối
//   `t.ROID = f.ROID` với Draft_01 ⇒ **xe nào có lệnh mới hơn nằm NGOÀI ngày lọc thì bị loại sạch**.
//   ⇒ Thành ra một luật nghiệp vụ ngầm: *"chỉ nhắc khi lần vào xưởng gần nhất chính là lần đang xét"*.
//   Dòng đáng lẽ giới hạn kỳ **bị comment ngay tại đó**: `--and ro.ReminderMaintanceDate >= @strFromDate`.
// 🔴 `Max(ro.ROID)` = **giả định ROID tăng dần theo thời gian** — phụ thuộc ngầm vào cách sinh khoá,
//   khác hẳn bản chết vốn sắp theo `LogLUDateTime`. Hai bản có thể chọn **hai lệnh khác nhau** cho cùng một xe.
// ⚠️ Bản sống kết bằng `RollbackSafety` (đọc thuần); bản chết gọi `CommitSafety` dù **không ghi gì**.
// 📌 Giữ tham số `variant`: mặc định `live` (bản đang chạy). `legacy` chạy lại logic #372 để **đối chiếu**
//   — cùng một ngày, hai bản trả **số dòng khác nhau**, và endpoint nói rõ chênh bao nhiêu.
app.MapGet("/api/tvo/service-reminders", async (AppDbContext db, ITenantContext t, DateTime? date, int? count,
    string? variant) =>
{
    var day = (date ?? DateTime.Today).Date;
    var take = count is > 0 ? count!.Value : 50;
    var isLegacy = string.Equals((variant ?? "live").Trim(), "legacy", StringComparison.OrdinalIgnoreCase);

    // _Draft_01: lệnh có ngày hẹn bảo dưỡng RƠI ĐÚNG NGÀY ĐÓ (from = to, không phải khoảng).
    var next = day.AddDays(1);
    var pool = await db.RepairOrders
        .Where(r => r.OrgId == t.OrgId
                    && r.ReminderMaintanceDate >= day && r.ReminderMaintanceDate < next
                    && r.CusID != null)
        .Select(r => new { r.Id, roid = r.Id, r.RONo, r.CusID, r.CarID, r.Vin, r.DealerCode,
                           r.LicensePlate,   // #562 bản sống gom theo (BIỂN SỐ, ĐẠI LÝ)
                           r.ReminderMaintanceDate, r.LogLUDateTime })
        .ToListAsync();

    // _Draft_02 + _Draft: mỗi khách lấy mốc hẹn LỚN NHẤT, rồi trong đó chọn lệnh SỬA GẦN NHẤT.
    var legacyPicked = pool
        .GroupBy(r => r.CusID!)
        .Select(g =>
        {
            var maxDate = g.Max(x => x.ReminderMaintanceDate);
            var sameDate = g.Where(x => x.ReminderMaintanceDate == maxDate).ToList();
            // TRỤC = LogLUDateTime (lần sửa cuối), KHÔNG phải ngày tạo — đúng bản CHẾT :426.
            var rep = sameDate.OrderByDescending(x => x.LogLUDateTime).First();
            return new { rep, candidates = sameDate.Count };
        })
        .ToList();

    // ===== #562 BẢN SỐNG `_20210603` — gom theo (BIỂN SỐ, ĐẠI LÝ), đại diện = ROID lớn nhất =====
    // #tblSer_RO_Max: quét TOÀN BỘ lịch sử lệnh của (biển, đại lý) — KHÔNG giới hạn ngày (đúng nguồn).
    var pairs = pool.Select(r => new { plate = r.LicensePlate, dealer = r.DealerCode ?? "" })
        .Distinct().ToList();
    var plates = pairs.Select(p => p.plate).Distinct().ToList();
    var allRo = await db.RepairOrders
        .Where(r => r.OrgId == t.OrgId && plates.Contains(r.LicensePlate))
        .Select(r => new { r.Id, r.LicensePlate, r.DealerCode })
        .ToListAsync();
    var maxRoIds = allRo
        .Where(r => pairs.Any(p => p.plate == r.LicensePlate && p.dealer == (r.DealerCode ?? "")))
        .GroupBy(r => new { r.LicensePlate, dealer = r.DealerCode ?? "" })
        .Select(g => g.Max(x => x.Id))
        .ToHashSet();
    // Draft_02: chỉ giữ lệnh vừa thuộc kỳ, VỪA là lệnh mới nhất của xe đó tại đại lý đó.
    var livePicked = pool.Where(r => maxRoIds.Contains(r.Id))
        .OrderBy(r => r.Id)
        .Select(r => new { rep = r, candidates = 1 })
        .ToList();
    // Số xe bị luật ngầm loại: có mặt trong kỳ nhưng đã có lệnh mới hơn ngoài kỳ.
    var droppedByNewerRoOutsidePeriod = pool.Count(r => !maxRoIds.Contains(r.Id));

    var picked = isLegacy ? legacyPicked : livePicked;

    // _Filter: MyIdxSeq trong [0 .. count-1] — start LUÔN bằng 0 nên không có trang 2.
    var totalBeforePaging = picked.Count;
    var legacyRowCount = legacyPicked.Count;   // #562 để đo chênh lệch hình dạng kết quả
    var page = picked.Take(take).ToList();

    var cusIds = page.Select(x => x.rep.CusID!).Distinct().ToList();
    var vins = page.Select(x => x.rep.Vin).Where(x => x != null).Select(x => x!).Distinct().ToList();
    var cus = await db.ServiceCustomers.Where(c => c.OrgId == t.OrgId && cusIds.Contains(c.CusCode)).ToListAsync();
    var cars = await db.ServiceCars.Where(c => c.OrgId == t.OrgId && vins.Contains(c.FrameNo)).ToListAsync();
    var modelCodes = cars.Select(c => c.ModelCode).Where(x => x != null).Select(x => x!).Distinct().ToList();
    var models = await db.ServiceModels.Where(m => m.OrgId == t.OrgId && modelCodes.Contains(m.ModelCode)).ToListAsync();

    var items = page.Select(x =>
    {
        var r = x.rep;
        var c = cus.FirstOrDefault(z => z.CusCode == r.CusID);
        var car = r.Vin == null ? null : cars.FirstOrDefault(z => z.FrameNo == r.Vin);
        var mdl = car?.ModelCode == null ? null : models.FirstOrDefault(z => z.ModelCode == car.ModelCode);
        return new
        {
            r.roid, r.RONo,
            customerCode = r.CusID, customerName = c?.CusName,
            customerMobile = c?.Mobile, customerIDCardNo = c?.IDCardNo,
            r.CarID, plateNo = car?.PlateNo, vin = car?.FrameNo,
            tradeMarkCode = car?.TradeMark,
            modelCode = mdl?.ModelCode, modelName = mdl?.ModelName,
            r.ReminderMaintanceDate, r.DealerCode,
            // Có nhiều lệnh cùng mốc hẹn ⇒ bản hiển thị phụ thuộc LẦN SỬA CUỐI.
            candidateCount = x.candidates,
        };
    }).ToList();

    return Results.Ok(new
    {
        date = day, count = items.Count, items,
        totalBeforePaging,
        // ===== #562 =====
        variant = isLegacy ? "legacy" : "live",
        liveBizIsDateSuffixed = "WSCarSvTab.asmx.cs goi HTCMobileTVO_GetServiceReminders_20210603; ban tran :426 chi con o file WS cu .20210412",
        liveBizLogsUnsuffixedName = "strFunctionName = HTCMobileTVO_GetServiceReminders => truy theo LOG se ket luan sai ban nao dang chay",
        resultShapeChangedBetweenVariants = "chet: mot KHACH mot dong (gom CusID); song: mot XE tai mot DAI LY mot dong (gom PlateNo+DealerCode)",
        legacyRowCount,
        liveRowCount = livePicked.Count,
        representativeAxis = isLegacy ? "LogLUDateTime desc (lan sua cuoi)" : "Max(ROID) — gia dinh ROID tang dan theo thoi gian",
        droppedByNewerRoOutsidePeriod,
        hiddenRuleOnlyRemindWhenLatestVisit = "#tblSer_RO_Max quet TOAN BO lich su (khong gioi han ky); dong gioi han bi comment: --and ro.ReminderMaintanceDate >= @strFromDate",
        truncated = totalBeforePaging > items.Count,
        pagingStartAlwaysZero = true,
        pagingNote = "Nguồn đóng cứng vị trí bắt đầu = 0 ⇒ chỉ lấy được `count` bản ghi ĐẦU; không có trang 2.",
        singleDayNotRange = true,
        dateNote = "Nguồn đặt from = to = cùng một ngày; tên biến From/To gây hiểu nhầm là khoảng.",
        legacyRepresentativeAxis = "LogLUDateTime (lần SỬA cuối) — trục của bản CHẾT :426",
        axisNote = "Lệnh cũ bị sửa vặt sẽ nhảy lên làm đại diện. Khác Tab.cs:8487 (#310) vốn chọn theo CreatedDate.",
        ambiguousCustomers = page.Count(x => x.candidates > 1),
        noDealerFilter = true,
        carJoinedByVin = true,
        carJoinNote = "Nguồn ghép xe theo CarID; MiniHTC ghép theo VIN vì ServiceCar không có cột CarID.",
    });
}).RequireAuthorization();

app.MapPost("/api/tvo/appointments", async (TvoAppCreateDto dto, AppDbContext db, ITenantContext t) =>
{
    // Thứ tự và tập trường bắt buộc lấy đúng theo nguồn. ModelCode và CVDVCode **không** bắt buộc
    //   (hai guard đó bị comment trong nguồn) ⇒ không tự thêm.
    var req = new (string k, string? v)[]
    {
        ("CustomerName", dto.CustomerName), ("CustomerMobile", dto.CustomerMobile),
        ("CustomerAddress", dto.CustomerAddress), ("PlateNo", dto.PlateNo),
        ("TradeMarkCode", dto.TradeMarkCode), ("AppDateTime", dto.AppDateTime),
        ("AppTime", dto.AppTime), ("CusRequest", dto.CusRequest), ("DealerCode", dto.DealerCode),
    };
    foreach (var (k, v) in req)
        if (string.IsNullOrWhiteSpace(v)) return Results.BadRequest(new { error = "Thiếu tham số bắt buộc: " + k });

    var dealer = dto.DealerCode!.Trim().ToUpperInvariant();
    var plate = dto.PlateNo!.Trim().ToUpperInvariant();

    // Nguồn gọi CheckExistDealerCode / CheckExistTradeMarkCode / CheckExistEngineerCode(nếu có CVDV).
    if (!await db.Dealers.AnyAsync(d => d.OrgId == t.OrgId && d.DealerCode == dealer))
        return Results.BadRequest(new { error = "Đại lý không tồn tại: " + dealer });

    var cvdv = (dto.CVDVCode ?? "").Trim();

    // ---- (1) tra khách + xe THEO BIỂN SỐ (xe còn hiệu lực) ----
    var car = await db.ServiceCars.FirstOrDefaultAsync(c => c.OrgId == t.OrgId
        && c.PlateNo == plate && c.DealerCode == dealer && c.FlagActive == "1");
    var matchedByPlate = car is not null;

    var now = DateTime.Now;
    string? cusId = car?.CusID;
    string? carId = car?.CarID;
    string? cusCreated = null, carCreated = null;

    if (!matchedByPlate)
    {
        // Nguồn tạo khách với **hầu hết cột = DBNull** — chỉ giữ tên / di động / địa chỉ.
        //   `IsContact = true` và `IsActive = true` là hai giá trị đóng cứng.
        cusId = "TVO" + now.ToString("yyMMddHHmmssfff");
        db.ServiceCustomers.Add(new ServiceCustomer
        {
            // MiniHTC định danh khách dịch vụ bằng `CusCode` (không có cột `CusID` như nguồn);
            //   `ServiceCar.CusID` trỏ về đúng giá trị này nên quan hệ hai bảng giữ nguyên.
            OrgId = t.OrgId, CusCode = cusId, DealerCode = dealer,
            CusName = dto.CustomerName!.Trim(), Mobile = dto.CustomerMobile!.Trim(),
            Address = dto.CustomerAddress!.Trim(),
            // 🔴 LỆCH CÓ CHỦ ĐÍCH: nguồn **nhận** `strCustomerIDCardNo`, đưa vào mảng ghi log, rồi
            //   **KHÔNG GHI VÀO ĐÂU CẢ** — số CMND/CCCD khách nhập trên app **rơi mất im lặng**.
            //   Không có chú thích nào giải thích ⇒ là sót, không phải luật (lệ #272/#275).
            //   MiniHTC đã sẵn cột `IDCardNo` ⇒ **ghi lại**, và trả cờ `idCardNoStoredWebOnly`.
            IDCardNo = string.IsNullOrWhiteSpace(dto.CustomerIDCardNo) ? null : dto.CustomerIDCardNo!.Trim(),
            // Nguồn ghi `true` (cột bit); MiniHTC dùng từ vựng cờ "1"/"0" ⇒ "1".
            IsContact = "1", FlagActive = "1",
        });
        cusCreated = cusId;

        carId = "TVOC" + now.ToString("yyMMddHHmmssfff");
        db.ServiceCars.Add(new ServiceCar
        {
            OrgId = t.OrgId, CarID = carId, CusID = cusId, DealerCode = dealer, PlateNo = plate,
            TradeMark = dto.TradeMarkCode!.Trim(), ModelCode = string.IsNullOrWhiteSpace(dto.ModelCode) ? null : dto.ModelCode!.Trim(),
            CusName = dto.CustomerName!.Trim(), CusMobile = dto.CustomerMobile!.Trim(),
            FlagActive = "1",
        });
        carCreated = carId;
    }
    else
    {
        // ---- (2) hậu kiểm của nguồn: xe này có đang thuộc về khách KHÁC không ----
        //   `where t.CarID = @strCarID and f.CusID <> @strCusID` ⇒ ném lỗi `…_ReCheck_InvalidCusID`.
        //   ⚠️ Nguồn chạy hậu kiểm **SAU KHI đã ghi** lịch hẹn vào cả ba CSDL; an toàn chỉ nhờ giao dịch
        //     bọc ngoài rollback. Port kiểm **TRƯỚC KHI ghi** — cùng kết quả, không dựa vào rollback.
        if (!string.IsNullOrWhiteSpace(carId) && !string.IsNullOrWhiteSpace(cusId)
            && await db.ServiceCars.AnyAsync(c => c.OrgId == t.OrgId && c.CarID == carId && c.CusID != cusId))
            return Results.BadRequest(new { error = "Xe đang thuộc về khách hàng khác — không tạo được lịch hẹn.", carId });
    }

    // ---- (3) tạo lịch hẹn ----
    var appNo = "APP" + now.ToString("yyMMddHHmmss");
    // AppFrom/AppTo là cột bắt buộc của MiniHTC; nguồn không có cặp này (chỉ ngày + giờ THÔ)
    //   ⇒ dựng lại từ AppDateTime + AppTime để hai bên không rời nhau, giống cách #323 làm ngược lại.
    var appFrom = DateTime.TryParse((dto.AppDateTime + " " + dto.AppTime).Trim(), out var pf) ? pf
        : DateTime.TryParse(dto.AppDateTime, out var pd) ? pd : now;
    var a = new ServiceAppointment
    {
        OrgId = t.OrgId, AppNo = appNo, DealerCode = dealer, PlateNo = plate,
        CusID = cusId, CarID = carId,
        CusName = dto.CustomerName!.Trim(), Mobile = dto.CustomerMobile!.Trim(),
        CusAddress = dto.CustomerAddress!.Trim(),
        CusRequest = dto.CusRequest!.Trim(),
        Creator = dto.PartnerUserCode,
        Status = "1",                       // AppStatus ghi thẳng chữ số, đúng nguồn
        Source = "HYUNDAIME",               // ĐÓNG CỨNG trong nguồn — client không đặt được
        // ⚠️ THÔ, **không** cắt ngày — khác kênh nội bộ (#323). Xem chú thích (3) ở đầu khối.
        AppDateTime = dto.AppDateTime!.Trim(), AppDateTimeFrom = dto.AppDateTime!.Trim(),
        AppTime = dto.AppTime!.Trim(), AppTimeFrom = dto.AppTime!.Trim(),
        CVDVCode = cvdv == "" ? null : cvdv,
        AppFrom = appFrom, AppTo = appFrom,
        // Nguồn: `CreatedDate = DateTime.Now.ToString("yyyy-MM-dd HH:mm")` ⇒ CẮT GIÂY.
        CreatedAt = new DateTime(now.Year, now.Month, now.Day, now.Hour, now.Minute, 0),
    };
    db.ServiceAppointments.Add(a);
    await db.SaveChangesAsync();

    // Nguồn đếm số lịch `AppStatus = '1'` của đại lý rồi gửi sang HCC (`itemcount`).
    var pendingAppCount = await db.ServiceAppointments.CountAsync(x => x.OrgId == t.OrgId
        && x.DealerCode == dealer && x.Status == "1");

    return Results.Ok(new
    {
        a.Id, appNo, dealerCode = dealer, plateNo = plate, cusId, carId,
        appStatus = "1", source = "HYUNDAIME",
        // Danh tính tra theo BIỂN SỐ: true = dùng lại hồ sơ cũ, tên/di động/địa chỉ gửi lên bị bỏ qua.
        customerMatchedByPlate = matchedByPlate,
        customerCreated = cusCreated, carCreated = carCreated,
        pendingAppCount,
        overlapNotChecked = true,
        overlapNote = "Kênh di động KHÔNG kiểm chồng giờ (kênh nội bộ #325 có kiểm) — đúng nguồn.",
        appDateTimeRawNote = "AppDateTime lưu THÔ theo chuỗi client gửi; kênh nội bộ cắt còn \"yyyy-MM-dd\".",
        idCardNoStoredWebOnly = !string.IsNullOrWhiteSpace(dto.CustomerIDCardNo),
        idCardNoNote = string.IsNullOrWhiteSpace(dto.CustomerIDCardNo) ? null
            : "Nguồn NHẬN CustomerIDCardNo rồi bỏ rơi (không ghi vào đâu); web có ghi ⇒ dữ liệu web ĐẦY HƠN.",
    });
}).RequireAuthorization();

app.MapPost("/api/appointments", async (AppointmentDto dto, AppDbContext db, ITenantContext t) =>
{
    if (dto.AppTo <= dto.AppFrom) return Results.BadRequest(new { error = "Giờ kết thúc phải sau giờ bắt đầu." });
    var cavity = (dto.CavityName ?? "").Trim();
    if (cavity != "")
    {
        // Kiểm tra khoang có tồn tại trong danh mục Cavity (nếu đã khai báo).
        var hasCavityMaster = await db.Cavities.AnyAsync(c => c.OrgId == t.OrgId);
        if (hasCavityMaster && !await db.Cavities.AnyAsync(c => c.OrgId == t.OrgId && c.CavityName == cavity))
            return Results.BadRequest(new { error = "Khoang/bay không có trong danh mục: " + cavity });
        // ===== 🔴 #325 CHỐNG CHỒNG GIỜ CÙNG KHOANG — đối chiếu `MyCheck_DateTime_Cavity` (`ZTemp.cs:23125`) =====
        // TRACE TWIN: bản `…_Cavityxxx` (`:23078`) CHẾT; bản LIVE nhận thêm tham số `dbAction`.
        //
        // 🔴 SỬA 1 — KHOÁ SAI CỘT: nguồn lọc `t.CavityID = @strCavityID` (**khoá**), port cũ lọc theo
        //   `CavityName` (**tên hiển thị**) ⇒ hai lịch hẹn cùng khoang nhưng ghi tên khác chính tả
        //   (“Bay 1” vs “BAY 1”) **KHÔNG bị coi là trùng** ⇒ đặt chồng lọt lưới.
        //   Nay khoá theo `CavityID`; chỉ khi thiếu `CavityID` mới lùi về tên (dữ liệu cũ), và ghi rõ.
        //
        // ⚠️ SO SÁNH HAI GUARD CHỒNG GIỜ TRONG CÙNG HỆ — mức đầy đủ KHÁC NHAU:
        //   • **Lịch hẹn** (đây): nguồn có **BA** nhánh — hai nhánh mốc + nhánh
        //     `(cũ.From >= mới.From AND cũ.To <= mới.To)` ⇒ bắt được cả ca **khoảng mới BAO TRÙM khoảng cũ**
        //     ⇒ **ĐẦY ĐỦ**.
        //   • **Phân công công việc** (#309): chỉ **HAI** nhánh mốc ⇒ **BỎ SÓT** ca bao trùm.
        //   ⇒ Cùng khái niệm "khoang bận", một chỗ đã vá, một chỗ chưa. Xác nhận lỗ hổng ghi ở #309 là
        //     **bất nhất có thật của nguồn**, không phải thiết kế chung.
        //   Vị từ của MiniHTC (`x.AppFrom < dto.AppTo && dto.AppFrom < x.AppTo`) **tương đương** ba nhánh
        //   của nguồn ⇒ giữ nguyên, đúng bản LIVE.
        //
        // ⚠️ Nguồn loại `AppStatus != '4'` (Hủy) — **blacklist đúng MỘT mã**, mã lạ/NULL **vẫn tính là bận**.
        var cavityId = (dto.CavityID ?? "").Trim();
        var overlap = cavityId.Length > 0
            ? await db.ServiceAppointments.AnyAsync(x => x.OrgId == t.OrgId && x.CavityID == cavityId
                  && x.Status != "Cancelled" && x.AppFrom < dto.AppTo && dto.AppFrom < x.AppTo)
            // lùi về TÊN chỉ khi chưa có CavityID (dữ liệu cũ) — kém chính xác, đã khai báo.
            : await db.ServiceAppointments.AnyAsync(x => x.OrgId == t.OrgId && x.CavityName == cavity
                  && x.Status != "Cancelled" && x.AppFrom < dto.AppTo && dto.AppFrom < x.AppTo);
        if (overlap) return Results.BadRequest(new
        {
            error = "Khoang " + (cavityId.Length > 0 ? cavityId : cavity) + " đã có lịch trùng khung giờ.",
            matchedBy = cavityId.Length > 0 ? "CavityID (đúng nguồn)" : "CavityName (dữ liệu cũ, kém chính xác)",
        });
    }
    var engineerNo = (dto.EngineerNo ?? "").Trim().ToUpperInvariant();
    if (engineerNo != "" && !await db.ServiceEngineers.AnyAsync(e => e.OrgId == t.OrgId && e.EngineerNo == engineerNo))
        return Results.BadRequest(new { error = "CVDV không tồn tại: " + engineerNo });
    // TWIN đã trace: WS gọi `Ser_App_Create_New20201230` (BizCarSv.ZTemp.cs) — KHÔNG phải `Ser_App_Create` trần.
    // Bản LIVE NÉM LỖI khi dòng dịch vụ/phụ tùng thiếu mã (bản cũ chỉ ghi DBNull) ⇒ port theo bản LIVE.
    var serviceItems = dto.ServiceItems ?? new();
    foreach (var line in serviceItems)
        if (string.IsNullOrWhiteSpace(line.SerCode))
            return Results.BadRequest(new { error = "Dịch vụ không có trong danh mục!" });
    var partItems = dto.PartItems ?? new();
    foreach (var line in partItems)
        if (string.IsNullOrWhiteSpace(line.PartCode))
            return Results.BadRequest(new { error = "Phụ tùng không có trong kho!" });

    var no = "APP" + DateTime.Now.ToString("yyMMddHHmmss");
    // 🔴 #270 KÊNH TẠO quyết định có đẩy HCC hay không: nguồn chỉ gắn `HCC_Appointment_AddOSX` vào
    //   `Ser_App_Create_ForTab` (kênh máy tính bảng), KHÔNG gắn vào nhánh tạo thường.
    //   ⇒ `Channel == "TAB"` mới đặt cờ chờ đẩy; mặc định để `null` = không thuộc diện đẩy.
    var isTab = string.Equals((dto.Channel ?? "").Trim(), "TAB", StringComparison.OrdinalIgnoreCase);
    var a = new ServiceAppointment { OrgId = t.OrgId, AppNo = no, CavityName = cavity == "" ? null : cavity, PlateNo = dto.PlateNo,
        CusName = dto.CusName, Mobile = dto.Mobile, ModelName = dto.ModelName, AppType = dto.AppType, AppFrom = dto.AppFrom, AppTo = dto.AppTo, Note = dto.Note,
        // 🔴 #319 TRẠNG THÁI do NGƯỜI GỌI truyền: nguồn ghi `AppStatus` **chỉ khi tham số khác rỗng**
        //   (`if (!StringUtils.IsEmpty(strAppStatus))`) ⇒ kênh máy tính bảng tự quyết trạng thái ban đầu.
        //   Port cũ **ép cứng** "Booked" ⇒ mất khả năng đó. Nay: rỗng thì mới mặc định "Booked".
        Status = string.IsNullOrWhiteSpace(dto.AppStatus) ? "Booked" : dto.AppStatus!.Trim(),
        EngineerNo = engineerNo == "" ? null : engineerNo, QuoteNo = dto.QuoteNo, CusRequest = dto.CusRequest,
        DealerCode = dto.DealerCode?.Trim().ToUpperInvariant(), CusID = dto.CusID, Vin = dto.Vin?.Trim().ToUpperInvariant(),
        // #282 §12: 8 cột thật của `TblSerAppRO`. `Source` là cột NGUỒN; `Channel` (#270, port tự đặt)
        //   được ghi vào chính cột đó khi client không gửi `Source` riêng.
        Creator = dto.Creator, CusAddress = dto.CusAddress, CusTel = dto.CusTel, InsNo = dto.InsNo,
        CavityID = dto.CavityID,
        // ===== 🔴 #319 SO HAI MÁY: bản 150 của `Ser_App_Create_ForTab` ghi **5 cột** mà bản laptop KHÔNG =====
        //   `AppStatus` · `AppDateTime` · `CarID` · `InsNo` · `Note` (file `BizCarSv.Tab.cs` lệch **+18 dòng**;
        //   khoanh được đúng chỗ chèn bằng **độ dịch dòng từng hàm** — quy trình 3 tầng của #318).
        //   MiniHTC đã có 4/5 (`AppFrom`≈AppDateTime · `Status` · `InsNo` · `Note`); **thiếu `CarID`** ⇒ bổ sung.
        CarID = dto.CarID,
        // ===== 🔴 #323 bốn cột NGÀY/GIỜ THÔ + hai mã của nguồn =====
        // Nguồn ghi mỗi cột dưới một guard RIÊNG ⇒ cho phép có ngày mà không giờ (và ngược lại).
        //   Rỗng thì **KHÔNG ghi** (giữ nguyên) — khác nhóm "rỗng = xoá" ở #321, phải đọc từng hàm.
        // Không có giá trị truyền lên ⇒ dựng lại từ `AppFrom`/`AppTo` để dữ liệu hai bên không rời nhau.
        AppDateTime = string.IsNullOrWhiteSpace(dto.AppDateTime) ? dto.AppTo.ToString("yyyy-MM-dd") : dto.AppDateTime!.Trim(),
        AppTime = string.IsNullOrWhiteSpace(dto.AppTime) ? dto.AppTo.ToString("HH:mm") : dto.AppTime!.Trim(),
        AppDateTimeFrom = string.IsNullOrWhiteSpace(dto.AppDateTimeFrom) ? dto.AppFrom.ToString("yyyy-MM-dd") : dto.AppDateTimeFrom!.Trim(),
        AppTimeFrom = string.IsNullOrWhiteSpace(dto.AppTimeFrom) ? dto.AppFrom.ToString("HH:mm") : dto.AppTimeFrom!.Trim(),
        AppTypeCode = string.IsNullOrWhiteSpace(dto.AppTypeCode) ? dto.AppType : dto.AppTypeCode!.Trim(),
        CVDVCode = string.IsNullOrWhiteSpace(dto.CVDVCode) ? engineerNo : dto.CVDVCode!.Trim(),   // nguồn .Trim()
        Source = string.IsNullOrWhiteSpace(dto.Source) ? (string.IsNullOrWhiteSpace(dto.Channel) ? null : dto.Channel!.Trim().ToUpperInvariant()) : dto.Source!.Trim().ToUpperInvariant(),
        HCCPushStatus = isTab ? "P" : null };
    db.ServiceAppointments.Add(a);

    foreach (var line in serviceItems)
        db.AppointmentServiceItems.Add(new AppointmentServiceItem
        {
            OrgId = t.OrgId, AppNo = no,
            SerCode = line.SerCode!.Trim().ToUpperInvariant(), SerName = line.SerName,
            StdManHour = line.StdManHour, Note = line.Note
        });
    foreach (var line in partItems)
        db.AppointmentPartItems.Add(new AppointmentPartItem
        {
            OrgId = t.OrgId, AppNo = no,
            PartCode = line.PartCode!.Trim().ToUpperInvariant(), PartName = line.PartName, EngName = line.EngName,
            Unit = line.Unit, Quantity = line.Quantity, Note = line.Note
        });
    await db.SaveChangesAsync();
    return Results.Ok(new { a.Id, a.AppNo, a.Status, a.HCCPushStatus, serviceItems = serviceItems.Count, partItems = partItems.Count });
}).RequireAuthorization();

// Nội dung đặt trước của lịch hẹn: danh sách dịch vụ + phụ tùng khách yêu cầu.
// 🔴 #270 PAYLOAD ĐẨY LỊCH HẸN SANG HCC — dựng đúng 24 trường của nguồn
//   (`HCCIntergration/BizCarSv.HCC.cs:71-107`, câu `----- HCC_Appointment:`).
// ⚠️ `AppointmentSourceCode` là **hằng chuỗi `'DMS'`** ngay trong câu SQL, không phải cột nào cả.
// ⚠️ `AppointmentDTimeUTC` = `CONCAT(sa.AppDateTimeFrom, ' ', sa.AppTimeFrom)` — nguồn tách NGÀY và GIỜ
//   thành hai cột rồi mới ghép; MiniHTC lưu một `DateTime` nên định dạng lại cho khớp.
// ⚠️ Nguồn chặn trước: `AppId` rỗng ⇒ ném `HCC_Appointment_AddOSX_InvalidAppId`.
// 📌 NỢ: lời gọi HTTP thật (`HCCService.Login` → đẩy `RQ_HCC_Appointment`) chưa port; endpoint này dựng
//   payload + trục trạng thái, phần còn lại là tầng vận chuyển.
// 🔴 #282 GHI MỐC LIÊN HỆ KHÁCH của lịch hẹn (`FirstContactDateTime` / `LastContactDateTime`).
// Nguồn giữ **HAI** mốc chứ không phải một: lần liên hệ ĐẦU TIÊN không bao giờ bị ghi đè, lần GẦN NHẤT
//   cập nhật mỗi lần gọi ⇒ đo được "bao lâu mới liên hệ được khách lần đầu" và "liên hệ gần nhất khi nào".
//   Gộp một cột là mất hẳn chỉ tiêu thứ nhất.
app.MapPost("/api/appointments/{no}/contact", async (string no, AppDbContext db, ITenantContext t) =>
{
    var a = await db.ServiceAppointments.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.AppNo == no.Trim());
    if (a is null) return Results.NotFound(new { no });
    var now = DateTime.Now;
    var isFirst = a.FirstContactDateTime is null;
    if (isFirst) a.FirstContactDateTime = now;   // chỉ ghi MỘT lần, không đè
    a.LastContactDateTime = now;
    await db.SaveChangesAsync();
    return Results.Ok(new { a.AppNo, firstContact = a.FirstContactDateTime, lastContact = a.LastContactDateTime, isFirstContact = isFirst });
}).RequireAuthorization();

app.MapGet("/api/appointments/{no}/hcc-payload", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim();
    if (no == "") return Results.BadRequest(new { error = "Thiếu số lịch hẹn." });
    var a = await db.ServiceAppointments.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.AppNo == no);
    if (a is null) return Results.NotFound(new { no });

    var d = a.DealerCode == null ? null : await db.Dealers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DealerCode == a.DealerCode);
    var cus = a.CusID == null ? null : await db.ServiceCustomers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CusCode == a.CusID);
    var car = a.Vin == null ? null : await db.ServiceCars.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.FrameNo == a.Vin);

    return Results.Ok(new
    {
        OrgID = d?.OrgHCCID, NetworkID = d?.NetworkHCCID, DealerCode = a.DealerCode,
        AppointmentCode = a.AppNo, AppointmentType = a.AppType,
        AppointmentDTimeUTC = a.AppFrom.ToString("yyyy-MM-dd HH:mm:ss"),
        UserCodeOwner = a.EngineerNo,
        AppointmentSourceCode = "DMS",
        CustomerCode = cus?.CusCode ?? a.CusID, CustomerName = cus?.CusName ?? a.CusName,
        CustomerPhone = cus?.Mobile ?? a.Mobile, CustomerEmail = cus?.Email, CustomerAddress = cus?.Address,
        ProvinceCode = cus?.ProvinceCode, DistrictCode = cus?.DistrictCode,
        ContactName = cus?.ContName, ContactPhone = cus?.ContMobile,
        ContactEmail = cus?.ContEmail, ContactAddress = cus?.ContAddress,
        // 🔴 #317 SỬA: nguồn lấy CẢ HAI **TỪ XE**, KHÔNG có dự phòng sang lịch hẹn:
        //   `car.PlateNo PlateNo` · `car.FrameNo VIN` (LEFT JOIN ⇒ xe không tra được thì để **NULL**).
        //   Port cũ thêm `?? a.PlateNo` và dùng thẳng `a.Vin` ⇒ **tự nghĩ ra dự phòng** (lớp lỗi
        //   `C0-quingentesimusquartusdecimus`). Nếu biển số trên lịch hẹn khác hồ sơ xe, HCC nhận số
        //   KHÁC với thứ nguồn gửi — mà không có gì báo.
        PlateNo = car?.PlateNo, TradeMarkCode = car?.TradeMark,
        // `smm.ModelCode` — nguồn join `Ser_MST_Model` qua `car.ModelID`; MiniHTC lưu sẵn mã model trên xe.
        ModelCode = car?.ModelCode, VIN = car?.FrameNo,
        AppointmentRequest = a.CusRequest,
        // Giữ giá trị của lịch hẹn ở trường RIÊNG để đối chiếu, KHÔNG trộn vào payload.
        plateNoOnAppointment = a.PlateNo, vinOnAppointment = a.Vin,
        carResolved = car is not null,
        pushStatus = a.HCCPushStatus,
    });
}).RequireAuthorization();

// ===== 🔴 #351 GHI KẾT QUẢ ĐẨY **LỆNH ĐÓNG** LỊCH HẸN SANG HCC =====
// Cụm `HCC*` trên lịch hẹn là **cơ chế của riêng MiniHTC** (nguồn không có cột nào tên `HCC…` trên
//   `Ser_App` — nguồn gọi thẳng web service). Vì tầng HTTP HCC vẫn là nợ, MiniHTC mô hình hoá bằng
//   một HÀNG ĐỢI hai vế: **MỞ** khi tạo lịch (#270) và **ĐÓNG** khi xe tới tiếp nhận (#271).
// 🔴 Vế MỞ có đủ bộ ba `HCCPushStatus` / `HCCPushDateTime` / `HCCPushNote` và endpoint ghi kết quả;
//   vế ĐÓNG mới chỉ đặt `HCCFinishStatus = "P"` lúc tiếp nhận rồi **bỏ lửng** — không có đường ghi
//   kết quả, `HCCFinishDateTime` nằm chết ⇒ **không biết lệnh đóng đã đẩy được hay chưa**.
//   Đây là cụm bị port dở, cùng mô-típ #348 (cụm phiên bản hợp đồng).
app.MapPost("/api/appointments/{no}/hccfinish", async (string no, AppointmentHccPushDto dto, AppDbContext db, ITenantContext t) =>
{
    var a = await db.ServiceAppointments.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.AppNo == no.Trim());
    if (a is null) return Results.NotFound(new { no });
    var to = (dto.ToStatus ?? "").Trim().ToUpperInvariant();
    if (to != "A" && to != "R") return Results.BadRequest(new { error = "ToStatus chỉ nhận A (thành công) hoặc R (lỗi)." });
    // Chỉ lịch hẹn ĐÃ được tiếp nhận mới có lệnh đóng để đẩy (nơi đặt "P").
    if (a.HCCFinishStatus is null)
        return Results.BadRequest(new { error = "Lịch hẹn chưa tiếp nhận nên không có lệnh đóng để đẩy HCC." });
    a.HCCFinishStatus = to; a.HCCFinishDateTime = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { a.AppNo, a.HCCFinishStatus, a.HCCFinishDateTime });
}).RequireAuthorization();

// #270 Ghi kết quả đẩy HCC (bộ đẩy gọi lại) — cùng lệ với `/api/warrantyclaims/{id}/hmcsync`.
app.MapPost("/api/appointments/{no}/hccpush", async (string no, AppointmentHccPushDto dto, AppDbContext db, ITenantContext t) =>
{
    var a = await db.ServiceAppointments.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.AppNo == no.Trim());
    if (a is null) return Results.NotFound(new { no });
    var to = (dto.ToStatus ?? "").Trim().ToUpperInvariant();
    if (to != "A" && to != "R") return Results.BadRequest(new { error = "ToStatus chỉ nhận A (thành công) hoặc R (lỗi)." });
    if (a.HCCPushStatus is null) return Results.BadRequest(new { error = "Lịch hẹn này không thuộc diện đẩy HCC (chỉ kênh TAB)." });
    a.HCCPushStatus = to; a.HCCPushDateTime = DateTime.Now; a.HCCPushNote = dto.Note;
    await db.SaveChangesAsync();
    return Results.Ok(new { a.AppNo, a.HCCPushStatus, a.HCCPushDateTime });
}).RequireAuthorization();

// ===== 🔴 #544 VÁ HAI BẢNG CON CỦA LỊCH HẸN THEO `Ser_App_GetX_New20220926` =====
// Nguồn: hai macro `zzB_Select_Ser_AppServiceItems_zzE` / `zzB_Select_Ser_AppPartItems_zzE`
//   (`BizCarSv.Tab.cs:4114` trong thân `Ser_App_GetX_New20220926`, xem #542).
//
// 🔴 **THIẾU HẲN `InventoryQuantity` — CỘT QUYẾT ĐỊNH CỦA MÀN HẸN**:
//     `(isnull(sb.TotalInStock, 0) + isnull(sb.TotalInShipment, 0)) InventoryQuantity`
//     `left join vwSer_inv_stockbalancebypart sb on rp.partid = sb.partid`
//   ⇒ Người nhận hẹn nhìn ngay được **phụ tùng có sẵn hay không** trước khi hứa ngày trả xe.
//   Bản port cũ **không trả gì** ⇒ mất hẳn cơ sở quyết định. Nay bù, dùng đúng **công thức của màn hẹn**
//   (tồn + hàng đang về), **không** dùng công thức của màn đặt hàng (chỉ tồn) — hai công thức là **chủ đích**
//   khác nhau, đã phân tích ở `/api/serviceparts/{code}/inventory`.
//   ⚠️ MiniHTC **chưa mô hình hoá "hàng đang về"** (nợ #423) ⇒ trả `inShipment = null` + cờ, **không bịa 0**.
// 🔴 **TÊN/ĐVT LẤY TỪ DANH MỤC, KHÔNG PHẢI TỪ DÒNG**: nguồn `left join Ser_Mst_Part mp on mp.PartID = rp.PartID`
//   rồi lấy `mp.PartCode · mp.EngName · mp.VieName · mp.Unit`; dòng chi tiết chỉ giữ `Quantity`/`Note`.
//   MiniHTC lưu **bản chụp** tên/ĐVT trên dòng ⇒ **hình dạng khác**: nếu danh mục đổi tên, nguồn hiện tên MỚI
//   còn MiniHTC giữ tên CŨ. Trả **cả hai** (tên trên dòng + tên tra danh mục) + cờ `nameFromMasterInSource`.
//   ⚪ LEFT ở đây **còn sống** (không điều kiện WHERE nào trên `mp`/`sb`) ⇒ phụ tùng đã xoá khỏi danh mục
//     vẫn ra dòng, chỉ trống tên — kiểm tra âm tính.
// ⚠️ `rp.Quantity` được trả **HAI LẦN**: `Quantity` và alias `Need` — hai cột **trùng giá trị**
//   (họ `Qty`/`QtyRO` ở #507). Giữ cả hai để khớp hình dạng.
// ⚠️ Dịch vụ: `left join Ser_Mst_Service ms on ms.SerID = rs.SerID` ⇒ `SerCode/SerName/StdManHour` **từ danh mục**,
//   còn `rs.Note` và `rs.ItemID` từ dòng. ⚠️ Hai bảng con dùng `inner join` vào bảng chi tiết nên lịch hẹn
//   **không có hạng mục** đơn giản là **không có dòng nào** ở bảng đó (không phải lỗi).
app.MapGet("/api/appointments/{no}/items", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var a = await db.ServiceAppointments.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.AppNo == no);
    if (a is null) return Results.NotFound(new { no });

    var svcRows = await db.AppointmentServiceItems.Where(x => x.OrgId == t.OrgId && x.AppNo == no).ToListAsync();
    var svcCodes = svcRows.Select(x => x.SerCode).Where(x => x != null).Select(x => x!).ToList();
    var svcMaster = await db.ServiceItemMsts.Where(m => m.OrgId == t.OrgId && svcCodes.Contains(m.SerCode))
        .Select(m => new { m.SerCode, m.SerName, m.StdManHour }).ToListAsync();
    var services = svcRows.Select(x =>
    {
        var m = svcMaster.FirstOrDefault(v => v.SerCode == x.SerCode);
        return new
        {
            x.Id, x.SerCode,
            x.SerName,                                   // bản chụp trên dòng
            serNameFromMaster = m?.SerName,              // nguồn lấy cột này
            x.StdManHour,
            stdManHourFromMaster = m?.StdManHour,
            x.Note,
        };
    }).ToList();

    var partRows = await db.AppointmentPartItems.Where(x => x.OrgId == t.OrgId && x.AppNo == no).ToListAsync();
    var partCodes = partRows.Select(x => x.PartCode).Where(x => x != null).Select(x => x!).ToList();
    var partMaster = await db.ServiceParts.Where(m => m.OrgId == t.OrgId && partCodes.Contains(m.PartCode))
        .Select(m => new { m.PartCode, m.PartName, m.Unit }).ToListAsync();
    // Công thức của MÀN HẸN: tồn + hàng đang về. "Hàng đang về" chưa có nguồn đúng (#423) ⇒ null.
    var stock = await db.PartStocks.Where(s => s.OrgId == t.OrgId && partCodes.Contains(s.PartCode))
        .GroupBy(s => s.PartCode).Select(g => new { PartCode = g.Key, OnHand = g.Sum(x => x.OnHand) })
        .ToListAsync();

    var parts = partRows.Select(x =>
    {
        var m = partMaster.FirstOrDefault(v => v.PartCode == x.PartCode);
        var st = stock.FirstOrDefault(v => v.PartCode == x.PartCode);
        return new
        {
            x.Id, x.PartCode,
            x.PartName, x.EngName, x.Unit,               // bản chụp trên dòng
            partNameFromMaster = m?.PartName,            // nguồn lấy cột này (mp.VieName)
            unitFromMaster = m?.Unit,
            x.Quantity,
            Need = x.Quantity,                           // alias TRÙNG giá trị, đúng nguồn
            x.Note,
            inStock = st?.OnHand ?? 0m,
            inShipment = (decimal?)null,                 // #423: chưa có nguồn đúng, KHÔNG bịa 0
            InventoryQuantity = (decimal?)null,          // = inStock + inShipment ⇒ chưa tính được
        };
    }).ToList();

    return Results.Ok(new
    {
        a.AppNo, a.PlateNo, a.CusName, a.CusRequest, a.AppFrom, a.AppTo, a.Status,
        services, parts,
        // Tổng giờ công định mức — cơ sở ước tính thời gian giữ khoang cho lịch hẹn.
        totalStdManHour = services.Sum(s => s.StdManHour ?? 0),
        inventoryFormulaOfThisScreen = "isnull(TotalInStock,0) + isnull(TotalInShipment,0)",
        inShipmentNotModelled = "#423 — chua co nguon dung, tra null thay vi 0",
        nameFromMasterInSource = "mp.VieName / mp.Unit / ms.SerName — MiniHTC luu ban chup tren dong",
        quantityReturnedTwiceInSource = "Quantity va alias Need",
        masterJoinsAreLeftAndAlive = true,
    });
}).RequireAuthorization();

// 🔴 Trạng thái lịch hẹn theo ĐÚNG nguồn (TConst.Ser_App) — port cũ thiếu bước XÁC NHẬN.
// Nguồn: CREA (mới tạo) → CONF (xác nhận) → ACCE (tiếp nhận, xe đã tới xưởng) · REJ (huỷ).
// "Confirmed" là bước gọi khách xác nhận TRƯỚC khi tới — thiếu nó thì không phân biệt được
// lịch mới đặt với lịch khách đã xác nhận sẽ đến (cơ sở để xưởng giữ khoang).
// ===== 🔴 #285 ĐÍNH CHÍNH MÃ TRẠNG THÁI LỊCH HẸN: là SỐ "1".."4", KHÔNG phải CREA/CONF/ACCE/REJ =====
// Lượt trước lấy mã từ lớp hằng `TConst.Ser_App` (`Create="CREA"` · `Confirm="CONF"` · `Accept="ACCE"` ·
//   `Reject="REJ"`). Kiểm lại bằng BA nguồn bằng chứng thì lớp hằng đó **SAI/CHẾT**:
//   1. **GHI**: `dt_Ser_App.Rows[0]["AppStatus"] = "1";` — ghi thẳng CHỮ SỐ
//      (`BizCarSv.TVO.cs:1697` và `:2410`).
//   2. **ĐỌC/LỌC**: `"AppStatus", "=", "1"` trong tham số truy vấn (`BizCarSv.Tab.cs:5131`, `TVO.cs:2509`).
//   3. **HIỂN THỊ**: `case ro.AppStatus when '1' then N'Mới tạo' when '2' then N'Xác nhận'`
//      `when '3' then N'Tiếp nhận' when '4' then N'Hủy' end as StatusName`
//      (`BizCarSv.Appointment.cs:1497-1502`, hàm `Ser_App_GetStatusList` — lặp lại ở 4 chỗ).
//   4. Grep TOÀN CÂY (đã loại file chết): `TConst.Ser_App.Create/Confirm/Accept/Reject` **KHÔNG được dùng
//      ở BẤT KỲ ĐÂU** ⇒ lớp hằng CHẾT, chỉ còn là tài liệu sai.
// ⇒ Giữ tên trạng thái nội bộ của port, nhưng **mã nguồn ánh xạ về CHỮ SỐ**, và bổ sung **NHÃN hiển thị**.
var appointmentStatusSourceCodes = new Dictionary<string, string>
{
    ["Booked"] = "1",          // Mới tạo
    ["Confirmed"] = "2",       // Xác nhận
    ["Arrived"] = "3",         // Tiếp nhận (xe đã tới)
    ["Cancelled"] = "4",       // Hủy
    // ===== 🔴 #444 MÃ '5' KHÔNG CHỈ LÀ NHÃN — nó là TRẠNG THÁI GHI ĐƯỢC =====
    // #289 đã tìm ra nhãn `'5' = "Đã liên hệ & Chưa xác nhận"`, nhưng **bộ máy trạng thái** ở đây vẫn
    //   dừng ở 1..4 ⇒ MiniHTC **không có đường nào ĐẶT** trạng thái đó.
    // Nay đã thấy nơi GHI: `FrmQuotationApp.btnDaLHChuaXN_Click` (`:2765`) gọi thẳng
    //   `DB.Ser_AppUpdateStatus(strAppID, **stDaLHVaChuaXN**)` với `private const string stDaLHVaChuaXN = "5"`
    //   (`:39`). ⇒ Mã `5` được **ghi vào CSDL** từ một nút có thật trên màn báo giá lịch hẹn.
    ["ContactedUnconfirmed"] = "5",   // Đã liên hệ & Chưa xác nhận
    // "Done" KHÔNG có trong nguồn (CASE chỉ có 1..4) — port cũ tự thêm. Giữ cho dữ liệu cũ, đánh dấu rõ.
    ["Done"] = "(port-only)",
};

// Nhãn hiển thị nguyên văn nguồn. Nguồn **KHÔNG có nhánh ELSE** ⇒ mã lạ cho ra NULL, không phải chuỗi rỗng.
// ===== 🔴 #289 BỔ SUNG mã trạng thái lịch hẹn thứ NĂM + bảng nhãn theo MÀN + từ vựng ĐỐI TÁC =====
// 🆕 Tìm ra bằng sweep `_audit/sweep_label_divergence.js` (gom mọi khối `CASE … then N'…'` rồi nhóm theo
//   CỘT được switch): trên `TERP.BizCarSv` có **118 khối nhãn / 12 cột**, trong đó **4 cột PHÂN KỲ**.
//   Cột `AppStatus` có **BA** bộ nhãn khác nhau — #285 mới port một bộ.
//
// ✅ TRACE TWIN: **CẢ HAI** hàm đều LIVE, là hai `[WebMethod]` riêng:
//   • `Ser_App_GetStatusList` (`Appointment.cs:1418`)            → 4 mã (1..4)
//   • `Ser_App_GetStatusList01_New20201230` (`ZTemp.cs:26252`)   → **5 mã**, thêm
//     `when '5' then N'Đã liên hệ & Chưa xác nhận'`
//   ⇒ mã `'5'` là **có thật**, chỉ màn cũ không hiện. Bảng 4 mã của #285 là **THIẾU**.
//
// 🔴 Bộ thứ BA là **TỪ VỰNG ĐỐI TÁC**, không phải nhãn cho người dùng:
//   `BizCarSv.PushToHyundaiMe.cs:315` → `when '2' then N'confirm' when '4' then N'reject'`
//   — tiếng ANH, và **chỉ ánh xạ 2 trong 5 mã**; ba mã còn lại cho NULL ⇒ hệ Hyundai Me **không nhận**
//   lịch hẹn ở trạng thái mới tạo / tiếp nhận / đã-liên-hệ. Đây là **hợp đồng dữ liệu ra ngoài**, phải
//   giữ tách khỏi bảng nhãn hiển thị.
var appointmentStatusDisplayNamesByScreen = new Dictionary<string, Dictionary<string, string>>
{
    // Màn danh sách lịch hẹn cũ (Ser_App_GetStatusList) — 4 mã.
    ["applist"] = new()
    {
        ["1"] = "Mới tạo", ["2"] = "Xác nhận", ["3"] = "Tiếp nhận", ["4"] = "Hủy",
    },
    // Màn danh sách lịch hẹn bản 20201230 (Ser_App_GetStatusList01_New20201230) — 5 mã.
    ["applist01"] = new()
    {
        ["1"] = "Mới tạo", ["2"] = "Xác nhận", ["3"] = "Tiếp nhận", ["4"] = "Hủy",
        ["5"] = "Đã liên hệ & Chưa xác nhận",
    },
};

// Giữ tên cũ cho chỗ đã dùng: bảng ĐẦY ĐỦ nhất (5 mã) — vì đây là bảng dùng để TRA, không phải để hiển thị
// theo một màn cụ thể.
var appointmentStatusDisplayNames = appointmentStatusDisplayNamesByScreen["applist01"];

// 🔴 Từ vựng ĐẨY SANG HYUNDAI ME (`PushToHyundaiMe.cs:315`) — CHỈ 2/5 mã có giá trị.
var appointmentStatusHyundaiMe = new Dictionary<string, string>
{
    ["2"] = "confirm", ["4"] = "reject",
};

// ===== 🔴 #444 BẢNG CHUYỂN TIẾP CŨ SAI HAI CHỖ — đọc từ **nút nào được BẬT sau mỗi thao tác** =====
// Nguồn không khai bảng chuyển tiếp; nó nằm trong các dòng `btnX.Enabled = …` ngay sau khi đổi trạng thái
// (`FrmQuotationApp.cs:2536/2578/2765`). Đọc đúng ba khối đó:
//   · Sau **Xác nhận** (→2): `btnConfirm.Enabled = false` ⇒ không xác nhận lại.
//   · Sau **Huỷ** (→4): `btnConfirm=true · btnSave=true · btnCancel=false · btnDelete=true`
//     `· btnCreateRO=false · btnDaLHChuaXN=true`
//     ⇒ 🔴 **HUỶ KHÔNG PHẢI TRẠNG THÁI CUỐI**: huỷ xong vẫn **xác nhận lại được**, vẫn **sửa và lưu được**,
//       vẫn chuyển sang "đã liên hệ" được. Bảng cũ ghi `["Cancelled"] = rỗng` ⇒ **chặn oan** một luồng
//       nghiệp vụ có thật (khách huỷ rồi gọi lại đặt tiếp).
//   · Sau **Đã liên hệ & chưa xác nhận** (→5): `btnConfirm=true · btnDelete=true · btnCancel=true`
//     `· btnCreateRO=true · btnDaLHChuaXN=false` ⇒ từ 5 đi được sang 2, 4 và tạo lệnh sửa (3).
//
// ⚠️ Đây đúng lệ đã ghi trước đây: **`Visible = true` ≠ nút sống** — phải truy `Enabled` theo trạng thái.
//   Ở màn này bảng chuyển tiếp **chỉ tồn tại dưới dạng các dòng gán `Enabled`**, không ở đâu khác.
var appointmentTransitions = new Dictionary<string, string[]>
{
    ["Booked"] = new[] { "Confirmed", "Arrived", "Cancelled", "ContactedUnconfirmed" },
    ["Confirmed"] = new[] { "Arrived", "Cancelled" },
    ["Arrived"] = new[] { "Done", "Cancelled" },
    ["Done"] = Array.Empty<string>(),
    // 🔴 Huỷ KHÔNG phải trạng thái cuối — xem khối ghi chú ngay trên.
    ["Cancelled"] = new[] { "Confirmed", "ContactedUnconfirmed" },
    ["ContactedUnconfirmed"] = new[] { "Confirmed", "Arrived", "Cancelled" },
};

app.MapGet("/api/appointments/statuses", () => Results.Ok(new
{
    statuses = appointmentStatusSourceCodes.Select(kv => new
    {
        status = kv.Key, sourceCode = kv.Value,
        // #285: nhãn hiển thị nguyên văn nguồn; mã "(port-only)" không có nhãn.
        displayName = appointmentStatusDisplayNames.TryGetValue(kv.Value, out var dn) ? dn : null,
        // #289: giá trị gửi sang hệ Hyundai Me — NULL nghĩa là trạng thái đó KHÔNG được đẩy.
        hyundaiMe = appointmentStatusHyundaiMe.TryGetValue(kv.Value, out var hm) ? hm : null,
    }),
    // #289: bảng nhãn THEO MÀN (applist = 4 mã · applist01 = 5 mã, thêm "Đã liên hệ & Chưa xác nhận").
    byScreen = appointmentStatusDisplayNamesByScreen.Select(s => new
    {
        screen = s.Key, names = s.Value.Select(kv => new { code = kv.Key, name = kv.Value }),
    }),
    transitions = appointmentTransitions.Select(kv => new { from = kv.Key, to = kv.Value }),
    statusFiveWritableNote = "#444: mã '5' (Đã liên hệ & Chưa xác nhận) KHÔNG chỉ là nhãn — "
        + "FrmQuotationApp.btnDaLHChuaXN_Click gọi Ser_AppUpdateStatus(appId, \"5\") ⇒ ghi thẳng vào CSDL. "
        + "Bộ máy trạng thái của bản port cũ dừng ở 1..4 nên KHÔNG có đường nào đặt được trạng thái này.",
    // ===== ✅ #445 QUÉT TRỌN BIZ (áp luật #441) — đếm được mức độ của lỗi, không còn ước lượng =====
    // Duyệt **mọi** khối `case ro.AppStatus` / `case tpro.AppStatus` trong `TERP.BizCarSv`, bỏ dòng comment,
    // rồi kiểm 10 dòng kế xem có `when '5'` không:
    //     **19 khối ACTIVE · chỉ 6 khối có mã '5' · 13 khối THIẾU** (thêm 2 khối đã bị comment).
    //   Danh sách thiếu: `Appointment.cs` 1497/1527/1692/1726 (**cả bốn** — chính là màn danh sách lịch hẹn)
    //   · `PushToHyundaiMe.cs:315` · `TVO.cs` 959/1029 · `WH.cs` 3228/3262 · `ZTemp.cs` 26125/26159/26553/26587.
    // ⇒ Trạng thái `5` **ghi được** từ nút trên màn báo giá lịch hẹn, nhưng **13/19 đường hiển thị không**
    //   **dịch nổi nó** — và vì các `CASE` đó **không có `ELSE`**, kết quả là **ô trạng thái TRỐNG**,
    //   không phải chữ "Không xác định". Người dùng thấy một dòng lịch hẹn **không có trạng thái**.
    // 📌 Chỉ 6/19 khối biết mã `5` ⇒ đây không phải "một màn quên", mà là **tính năng thêm sau mà chỉ
    //   vá vào vài chỗ hiển thị**. MiniHTC có nhãn cho cả 5 mã ở **mọi** đường đọc.
    statusFiveDisplaySweep = new { caseBlocksActive = 19, withCode5 = 6, missingCode5 = 13, commentedOut = 2 },
    statusFiveDisplaySweepNote = "Quét toàn TERP.BizCarSv: 19 khối CASE AppStatus đang chạy, chỉ 6 khối có "
        + "when '5', 13 khối THIẾU (gồm CẢ BỐN khối ở Appointment.cs — màn danh sách lịch hẹn). Các CASE "
        + "đó không có ELSE ⇒ ô trạng thái TRỐNG, không phải 'Không xác định'.",
    statusFiveDisplaysBlankNote = "🔴 LỖI NGUỒN: CASE hiển thị ở Ser_App…(BizCarSv.Appointment.cs:1497) chỉ "
        + "có when '1'..'4' và KHÔNG có ELSE ⇒ lịch hẹn ở trạng thái '5' hiện StatusName = NULL, tức Ô "
        + "TRẠNG THÁI TRỐNG trên lưới. Chính màn đặt được trạng thái đó lại không hiển thị được nó.",
