app.MapPost("/api/appointments/{id}/status", async (long id, AppointmentStatusDto dto, AppDbContext db, ITenantContext t) =>
{
    var a = await db.ServiceAppointments.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (a is null) return Results.NotFound(new { id });
    var s = (dto.Status ?? "").Trim();
    if (!appointmentStatusSourceCodes.ContainsKey(s))
        return Results.BadRequest(new { error = $"Trạng thái hợp lệ: {string.Join(", ", appointmentStatusSourceCodes.Keys)}" });
    // Chỉ cho đi theo bảng chuyển tiếp — port cũ cho nhảy tự do giữa mọi trạng thái.
    if (!appointmentTransitions.TryGetValue(a.Status, out var allowedNext) || !allowedNext.Contains(s))
        return Results.BadRequest(new { error = $"Không thể chuyển từ '{a.Status}' sang '{s}'. Cho phép: {string.Join(", ", allowedNext ?? Array.Empty<string>())}" });
    a.Status = s; await db.SaveChangesAsync();
    return Results.Ok(new { a.Id, a.Status, sourceCode = appointmentStatusSourceCodes[s] });
}).RequireAuthorization();

// ===== 🔴 #431 BẢNG KHOANG THEO NGÀY — bổ sung bốn luật hiển thị của `FrmShowCavityStatus` =====
// Nguồn: `Views/Appointment/FrmShowCavityStatus.cs` (262 dòng) — vẽ biểu đồ Gantt từ
//   `Ser_AppROGet(…)` + `Ser_CavityGet("","","","","","1","")` (tham số thứ 6 = **chỉ khoang đang dùng**).
// Bản port trước chỉ liệt kê lịch hẹn theo khoang; bốn luật sau **nằm ở phần VẼ**, dễ bị bỏ khi port API:
//
// 🔴 1. **KHUNG GIỜ CỐ ĐỊNH 06:00 → 19:00** của ngày đang xem:
//      `ganttChart.FromDate = new DateTime(y, m, d, **6**, 0, 0)` · `ToDate = … **19**, 0, 0`
//    ⇒ Lịch hẹn **ngoài khung này vẫn tồn tại nhưng KHÔNG hiện trên biểu đồ**. Người điều phối nhìn
//      bảng thấy khoang trống, thực tế đã có hẹn lúc 5h30 hoặc 20h. Đây là **ẩn dữ liệu khi VẼ**,
//      không phải bộ lọc dữ liệu — nên không ai thấy nó trong câu truy vấn.
// 🔴 2. **MÀU THEO LOẠI HẸN** (`AppTypeCode`) — chính là thứ làm bảng này có ích:
//      `BDDK` → cam nhạt (248,203,173) · `SCC` → xám (201,201,201) · `SCDS` → xanh (0,176,240)
//      · `SCK` → vàng (255,255,0) · **còn lại** → xanh lá.
// 🔴 3. **`AppStatus == "2"` (đã xác nhận) ⇒ ĐÁNH DẤU SAO** trên thanh. Bản port cũ dùng tiêu chí
//    khác hẳn (`Status != "Cancelled"`) ⇒ mất phân biệt "đã xác nhận" với "mới đặt".
//    (Mã trạng thái là **CHỮ SỐ 1..4** — xem ghi chú #285 ngay phía trên.)
// 🔴 4. Dòng có `AppDateTimeFrom` hoặc `AppDateTime` **rỗng** bị `continue` — **bỏ qua LẶNG LẼ**,
//    không đếm, không cảnh báo. Nay trả `skippedNoTime`.
//
// 📌 **KẾT QUẢ ÂM TÍNH đáng ghi**: form này parse ngày bằng
//   `DateTime.ParseExact(x, "yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture)` — **đúng cách**,
//   ngược hẳn với `DateTime.Now.ToString()` phụ thuộc văn hoá ở #421. Cùng một cây nguồn, hai lối làm.
// ⚠️ Lịch hẹn **chưa gán khoang** (`CavityID` rỗng) không bao giờ lên bảng — cả nguồn lẫn bản port.
// ===== 🔴 #446 CUỘC HẸN NÀY ĐÃ CÓ BÁO GIÁ CHƯA (`Ser_RO_Get_ByAppId`) =====
// TRACE: `FrmQuotationApp.btnCreateRO_Click` (`:2612`) → `AppointmentService.Ser_RO_Get_ByAppId`
//   (`:508`) → biz (`BizCarSv.Appointment.cs:2086`). Kết quả quyết định nhãn nút:
//   có báo giá ⇒ **"Xem báo giá"**, chưa có ⇒ **"Tạo báo giá"**.
//
// 🔴 **CHỌN BÁO GIÁ BẰNG BIẾN, KHÔNG SẮP XẾP**:
//     `declare @ROID int`
//     `select @ROID = ro0.ROID from ser_RO ro0 where exists ( … )`
//   Không `TOP`, không `ORDER BY` ⇒ nếu **một cuộc hẹn có nhiều lệnh sửa**, `@ROID` nhận **một cái BẤT KỲ**
//   (cái cuối cùng máy quét trúng). Cùng họ với lỗi `TOP` thiếu `ORDER BY` ở #415, nhưng ở đây nó quyết định
//   **người dùng được mở báo giá NÀO**. 📌 MiniHTC sắp theo `Id` và trả `candidateCount` để thấy khi có nhiều.
//
// 🔴 **NHÁNH "KHÔNG CÓ" TRẢ VỀ BẢNG SAI LƯỢC ĐỒ**: `else BEGIN select 1 where (1 = 0) END`
//   ⇒ một bảng **rỗng nhưng chỉ có một cột vô danh**, rồi biz vẫn **đặt tên nó là `Ser_RO`**.
//   Client nhận một bảng tên đúng, **lược đồ sai**. Và vì có guard `if (dsGetData.Tables.Count > 1)`,
//   hai bảng `Ser_Service`/`Ser_Part` **không tồn tại** trong trường hợp này ⇒ `ds.Tables["Ser_Part"]`
//   trả **null**, được gán thẳng vào `frm.dtSerAppParts` — null lan âm thầm sang màn báo giá.
//
// 🔴 **NGUỒN DÒNG ĐỔI THEO NHÁNH**: trong `btnCreateRO_Click`, khi đã có báo giá và `bRoFirst == false`,
//   nguồn **ghi đè** `frm.dtSerAppParts`/`Services` bằng các bảng lấy từ **LỆNH SỬA**, thay cho bảng lấy từ
//   **CUỘC HẸN** gán ngay phía trên. ⇒ Cùng một màn, dòng công/phụ tùng hiển thị có thể đến từ **hai nguồn
//   khác nhau** tuỳ đã có báo giá hay chưa. Đọc lướt sẽ tưởng luôn lấy từ cuộc hẹn.
//
// ⚠️ Chuỗi fallback tên/địa chỉ người liên hệ, đáng chú ý vì **địa chỉ đi theo cái TÊN**:
//   `isnull(ro.CusName, isnull(cus.ContName, cus.CusName)) CusName` và
//   `case when ro.CusName is not null then ro.**CusAddress** when cus.ContName is not null then cus.**ContAddress**`
//   `     else cus.Address end` — điều kiện xét **cột TÊN** để chọn **cột ĐỊA CHỈ**.
app.MapGet("/api/appointments/{appNo}/quotation", async (string appNo, AppDbContext db, ITenantContext t) =>
{
    var app = await db.ServiceAppointments
        .FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.AppNo == appNo);
    if (app is null) return Results.NotFound(new { appNo });

    var candidates = await db.RepairOrders
        .Where(r => r.OrgId == t.OrgId && r.AppId == appNo)
        .OrderBy(r => r.Id).ToListAsync();

    if (candidates.Count == 0)
        return Results.Ok(new
        {
            appNo, hasQuotation = false, buttonLabel = "Tạo báo giá",
            candidateCount = 0,
            emptyShapeNote = "Nguồn trả `select 1 where (1=0)` cho trường hợp này ⇒ một bảng RỖNG chỉ có "
                + "MỘT CỘT VÔ DANH nhưng vẫn được đặt tên Ser_RO (lược đồ sai), và hai bảng Ser_Service/"
                + "Ser_Part KHÔNG tồn tại ⇒ ds.Tables[\"Ser_Part\"] trả null, lan âm thầm sang màn báo giá.",
        });

    var ro = candidates[0];
    return Results.Ok(new
    {
        appNo, hasQuotation = true, buttonLabel = "Xem báo giá",
        candidateCount = candidates.Count,
        ro.Id, ro.RONo, ro.Status, ro.CusRequest, ro.CarStatus, ro.Assistant, ro.Km,
        ro.CusID, ro.CarID, ro.DealerCode,
        // ===== ✅ #447 QUÉT TRỌN BIZ (luật #441): mẫu "chọn một dòng vào biến" dùng **33 lần, 0 lần có
        //        tiêu chí chọn** =====
        // Duyệt mọi `select @X = …` trong SQL nguồn, bỏ các `@@Identity`/`SCOPE_IDENTITY()` (đó là lấy khoá
        // vừa sinh, không phải chọn dòng):
        //     **33 chỗ · 0 chỗ có `ORDER BY` hoặc `TOP` · 22/33 lọc bằng mệnh đề ĐỘNG (`zzzzClauseWhere…`)**.
        // ⚠️ **Không kết luận cả 33 đều sai**: khi `WHERE` khoá vào một cột duy nhất (số RO, số phiếu) thì
        //   "lấy dòng bất kỳ" vẫn ra đúng. Điều đo được là: **tính đúng đắn phụ thuộc HOÀN TOÀN vào việc
        //   mệnh đề lọc có duy nhất hay không — và không chỗ nào tự bảo đảm điều đó.**
        //   22 chỗ lọc bằng mệnh đề **dựng động lúc chạy** ⇒ tính duy nhất **không thể biết khi đọc code**.
        // 📌 Ở #446 thì mệnh đề là `ro.AppId` — **không** phải khoá duy nhất (một cuộc hẹn có thể có nhiều
        //   lệnh sửa) ⇒ đây là chỗ mẫu này **thật sự nguy hiểm**, và là lý do endpoint trả `candidateCount`.
        scalarPickSweep = new { sites = 33, withOrderByOrTop = 0, filteredByDynamicClause = 22 },
        scalarPickSweepNote = "Quét toàn TERP.BizCarSv: mẫu `select @X = …` (bỏ @@Identity/SCOPE_IDENTITY) "
            + "dùng 33 lần, KHÔNG lần nào kèm ORDER BY hay TOP; 22/33 lọc bằng mệnh đề dựng ĐỘNG lúc chạy. "
            + "Không phải cả 33 đều sai — nhưng tính đúng đắn phụ thuộc hoàn toàn vào việc mệnh đề lọc có "
            + "duy nhất hay không, và không chỗ nào tự bảo đảm điều đó.",
        arbitraryPickNote = candidates.Count > 1
            ? $"Cuộc hẹn này có {candidates.Count} lệnh sửa. NGUỒN chọn bằng `select @ROID = ro0.ROID … "
              + "where exists(…)` KHÔNG có TOP/ORDER BY ⇒ lấy một cái BẤT KỲ; người dùng có thể được mở "
              + "báo giá khác nhau giữa hai lần bấm. MiniHTC sắp theo Id cho ổn định."
            : null,
        lineSourceSwitchNote = "Trong nguồn, khi ĐÃ có báo giá và bRoFirst = false, các bảng dòng công/phụ "
            + "tùng bị GHI ĐÈ bằng dữ liệu lấy từ LỆNH SỬA thay cho dữ liệu lấy từ CUỘC HẸN gán ngay phía "
            + "trên ⇒ cùng một màn, dòng hiển thị đến từ hai nguồn khác nhau tuỳ đã có báo giá hay chưa.",
        contactFallbackNote = "Tên người liên hệ: isnull(ro.CusName, isnull(cus.ContName, cus.CusName)). "
            + "Địa chỉ chọn theo ĐIỀU KIỆN TRÊN CỘT TÊN (when ro.CusName is not null then ro.CusAddress …) "
            + "⇒ địa chỉ đi theo nguồn của cái TÊN, không tự xét cột địa chỉ.",
    });
}).RequireAuthorization();

app.MapGet("/api/appointments/cavity-board", async (AppDbContext db, ITenantContext t,
    DateTime? date, int? fromHour, int? toHour) =>
{
    var d0 = (date ?? DateTime.Today).Date; var d1 = d0.AddDays(1);
    // Khung giờ vẽ của nguồn: 6h → 19h. Cho phép nới bằng tham số, mặc định giữ đúng nguồn.
    var h0 = fromHour ?? 6; var h1 = toHour ?? 19;
    var winFrom = d0.AddHours(h0); var winTo = d0.AddHours(h1);

    var cavities = await db.Cavities.Where(c => c.OrgId == t.OrgId && c.FlagActive == "1")
        .OrderBy(c => c.CavityName).Select(c => new { c.CavityName, c.CavityNo }).ToListAsync();   // Cavity dung CavityNo

    var raw = await db.ServiceAppointments.Where(x => x.OrgId == t.OrgId && x.CavityName != null
            && x.Status != "Cancelled" && x.AppFrom >= d0 && x.AppFrom < d1)
        .OrderBy(x => x.AppFrom).ToListAsync();

    // Nguồn: dòng thiếu giờ bắt đầu/kết thúc bị `continue` — bỏ qua lặng lẽ. Nay ĐẾM ra.
    var skippedNoTime = raw.Count(x => x.AppFrom == default || x.AppTo == default);
    var valid = raw.Where(x => x.AppFrom != default && x.AppTo != default).ToList();

    static string ColorOf(string? code) => code switch
    {
        "BDDK" => "#F8CBAD",   // 248,203,173
        "SCC" => "#C9C9C9",    // 201,201,201
        "SCDS" => "#00B0F0",   // 0,176,240
        "SCK" => "#FFFF00",    // 255,255,0
        _ => "#008000",        // Color.Green
    };

    var shaped = valid.Select(x => new
    {
        x.CavityName, x.AppNo, x.PlateNo, x.CusName, x.ModelName, x.Status,
        appTypeCode = x.AppTypeCode,
        color = ColorOf(x.AppTypeCode),
        // AppStatus "2" = ĐÃ XÁC NHẬN ⇒ nguồn vẽ dấu sao trên thanh.
        markStar = x.Status == "2" || string.Equals(x.Status, "Confirmed", StringComparison.OrdinalIgnoreCase),
        appFrom = x.AppFrom.ToString("HH:mm"), appTo = x.AppTo.ToString("HH:mm"),
        // Nằm ngoài khung vẽ 6h-19h ⇒ nguồn KHÔNG hiển thị.
        outsideChartWindow = x.AppFrom < winFrom || x.AppTo > winTo,
    }).ToList();

    var outsideCount = shaped.Count(a => a.outsideChartWindow);
    var board = cavities.Select(cv => new
    {
        cavityName = cv.CavityName, cavityNo = cv.CavityNo,
        appointments = shaped.Where(a => a.CavityName == cv.CavityName).ToList(),
    }).ToList();

    return Results.Ok(new
    {
        date = d0.ToString("yyyy-MM-dd"),
        chartWindow = new { from = winFrom.ToString("HH:mm"), to = winTo.ToString("HH:mm") },
        totalCavity = cavities.Count, totalApp = shaped.Count,
        outsideChartWindowCount = outsideCount,
        outsideChartWindowNote = outsideCount > 0
            ? "Có lịch hẹn nằm NGOÀI khung vẽ 06:00-19:00 của nguồn ⇒ trên WinForm chúng KHÔNG hiện, "
              + "khoang trông như đang trống. Đây là ẩn dữ liệu lúc VẼ, không phải bộ lọc truy vấn."
            : null,
        skippedNoTime,
        skippedNoTimeNote = skippedNoTime > 0
            ? "Nguồn `continue` bỏ qua dòng thiếu giờ bắt đầu/kết thúc — lặng lẽ, không đếm, không cảnh báo."
            : null,
        colorLegend = new
        {
            BDDK = "#F8CBAD", SCC = "#C9C9C9", SCDS = "#00B0F0", SCK = "#FFFF00", other = "#008000",
        },
        markStarNote = "Nguồn đánh dấu SAO khi AppStatus = \"2\" (đã xác nhận). Bản port trước chỉ lọc "
            + "Status != Cancelled ⇒ mất phân biệt 'đã xác nhận' với 'mới đặt'.",
        parseExactNote = "KẾT QUẢ ÂM TÍNH: form này parse ngày bằng ParseExact(..., InvariantCulture) — "
            + "ĐÚNG cách, ngược hẳn DateTime.Now.ToString() phụ thuộc văn hoá ở #421. Cùng cây nguồn, hai lối làm.",
        unassignedNote = "Lịch hẹn CHƯA gán khoang không bao giờ lên bảng — cả nguồn lẫn bản port.",
        board,
    });
}).RequireAuthorization();

// ===== Công nợ bảo hiểm + thu tiền (InsDebit — port 1:1 FrmInsDebitSearch/FrmInsPaymentCreate, TCMotor) =====
app.MapGet("/api/insdebits", async (AppDbContext db, ITenantContext t, string? q, string? status) =>
{
    var query = db.InsDebits.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(q)) query = query.Where(x => x.DebitNo.Contains(q!) || (x.InsName != null && x.InsName.Contains(q!)) || (x.InsNo != null && x.InsNo.Contains(q!)) || (x.RONo != null && x.RONo.Contains(q!)));
    if (!string.IsNullOrWhiteSpace(status)) query = query.Where(x => x.Status == status);
    var items = await query.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.DebitNo, x.InsNo, x.InsName, x.RONo, x.DebitAmount, x.PaidAmount, balance = x.DebitAmount - x.PaidAmount, x.Status, x.Note,
        debitDate = x.DebitDate.HasValue ? x.DebitDate.Value.ToString("yyyy-MM-dd") : ""
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, totalDebit = items.Sum(i => i.DebitAmount), totalPaid = items.Sum(i => i.PaidAmount), totalBalance = items.Sum(i => i.balance), items });
}).RequireAuthorization();

// Tạo công nợ bảo hiểm (hãng BH nợ tiền bồi thường theo RO). DebitAmount > 0.
app.MapPost("/api/insdebits", async (InsDebitDto dto, AppDbContext db, ITenantContext t) =>
{
    if (dto.DebitAmount <= 0) return Results.BadRequest(new { error = "Số tiền công nợ phải lớn hơn 0." });
    var no = "ID" + DateTime.Now.ToString("yyMMddHHmmss");
    var r = new InsDebit { OrgId = t.OrgId, DebitNo = no, InsNo = dto.InsNo, InsName = dto.InsName, RONo = dto.RONo, DebitAmount = dto.DebitAmount, PaidAmount = 0, DebitDate = dto.DebitDate ?? DateTime.Now, Note = dto.Note, Status = "Open" };
    db.InsDebits.Add(r); await db.SaveChangesAsync();
    return Results.Ok(new { r.DebitNo });
}).RequireAuthorization();

app.MapGet("/api/insdebits/{no}/payments", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.InsDebits.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DebitNo == no);
    if (h is null) return Results.NotFound(new { no });
    var pays = await db.InsDebitPayments.Where(p => p.OrgId == t.OrgId && p.InsDebitId == h.Id).OrderBy(p => p.Id)
        .Select(p => new { p.PaymentAmount, p.Note, p.PaymentNo, p.DealerCode, p.PayPersonName, p.PayPersonIDCardNo, payDate = p.PayDate.HasValue ? p.PayDate.Value.ToString("yyyy-MM-dd") : "" }).ToListAsync();
    return Results.Ok(new { h.DebitNo, h.DebitAmount, h.PaidAmount, balance = h.DebitAmount - h.PaidAmount, h.Status, count = pays.Count, payments = pays });
}).RequireAuthorization();

// Thu tiền công nợ bảo hiểm (không vượt số dư; đủ tiền -> Paid).
app.MapPost("/api/insdebits/{no}/payments", async (string no, InsDebitPaymentDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.InsDebits.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DebitNo == no);
    if (h is null) return Results.NotFound(new { no });
    if (dto.PaymentAmount <= 0) return Results.BadRequest(new { error = "Số tiền thu phải lớn hơn 0." });
    // Guard của nguồn (checkPaymentFieldEmpty): đại lý + người nộp + CMND/CCCD + ngày thu đều BẮT BUỘC.
    // ⚠️ CusID KHÔNG bắt buộc — nguồn đã COMMENT dòng truyền strCusID vào hàm check (luật "port dòng active").
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Chưa nhập mã đại lý." });
    if (string.IsNullOrWhiteSpace(dto.PayPersonName)) return Results.BadRequest(new { error = "Chưa nhập tên người nộp tiền." });
    if (string.IsNullOrWhiteSpace(dto.PayPersonIDCardNo)) return Results.BadRequest(new { error = "Chưa nhập số CMND/CCCD người nộp tiền." });
    if (dto.PayDate is null) return Results.BadRequest(new { error = "Chưa nhập ngày thu tiền." });
    var balance = h.DebitAmount - h.PaidAmount;
    if (dto.PaymentAmount > balance) return Results.BadRequest(new { error = $"Số tiền thu vượt số dư công nợ ({balance})." });
    db.InsDebitPayments.Add(new InsDebitPayment { OrgId = t.OrgId, InsDebitId = h.Id, PaymentAmount = dto.PaymentAmount, PayDate = dto.PayDate ?? DateTime.Now, Note = dto.Note,
        PaymentNo = "PM" + DateTime.Now.ToString("yyMMddHHmmss"), DealerCode = dto.DealerCode, PayPersonName = dto.PayPersonName, PayPersonIDCardNo = dto.PayPersonIDCardNo });
    h.PaidAmount += dto.PaymentAmount;
    if (h.PaidAmount >= h.DebitAmount) h.Status = "Paid";
    await db.SaveChangesAsync();
    return Results.Ok(new { h.DebitNo, paidAmount = h.PaidAmount, balance = h.DebitAmount - h.PaidAmount, status = h.Status });
}).RequireAuthorization();

// ===== Công nợ nhà cung cấp phụ tùng + thu tiền (SupplierDebit — port 1:1 FrmSuplierDebitCreate/FrmSupplierDebitSearch/FrmSupplierPaymentCreate, TCMotor DMSCarSv/Debit) =====
app.MapGet("/api/supplierdebits", async (AppDbContext db, ITenantContext t, string? supplier, string? status) =>
{
    var query = db.SupplierDebits.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(supplier)) query = query.Where(x => x.SupplierCode == supplier);
    if (!string.IsNullOrWhiteSpace(status)) query = query.Where(x => x.Status == status);
    var items = await query.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.Id, x.SupplierCode, x.StockInNo, x.DebitAmount, x.PaidAmount, balance = x.DebitAmount - x.PaidAmount, x.Status, x.Note,
        debitDate = x.DebitDate.HasValue ? x.DebitDate.Value.ToString("yyyy-MM-dd") : ""
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, totalDebit = items.Sum(i => i.DebitAmount), totalPaid = items.Sum(i => i.PaidAmount), totalBalance = items.Sum(i => i.balance), items });
}).RequireAuthorization();

// Tạo/cộng dồn nợ NCC theo (SupplierCode, StockInNo) — khớp Check_HaveDebit_01 WinForm gốc.
app.MapPost("/api/supplierdebits", async (SupplierDebitDto dto, AppDbContext db, ITenantContext t) =>
{
    var supplier = (dto.SupplierCode ?? "").Trim();
    if (string.IsNullOrWhiteSpace(supplier)) return Results.BadRequest(new { error = "Chưa chọn nhà cung cấp." });
    if (dto.DebitAmount <= 0) return Results.BadRequest(new { error = "Số tiền nợ phải lớn hơn 0." });
    if (dto.DebitDate is null) return Results.BadRequest(new { error = "Chưa nhập ngày trả nợ." });
    var stockIn = (dto.StockInNo ?? "").Trim();
    // audit 2026-09-03: CheckDebitAmount() gốc chặn số tiền nợ > dDefaultDebitAmount (số tiền phải trả = tổng phiếu nhập) — port trước thiếu guard này.
    if (!string.IsNullOrWhiteSpace(stockIn))
    {
        var stockInTotal = await db.ServiceStockIns.Where(x => x.OrgId == t.OrgId && x.StockInNo == stockIn).Select(x => (decimal?)x.TotalAmount).FirstOrDefaultAsync();
        if (stockInTotal is not null)
        {
            var already = await db.SupplierDebits.Where(x => x.OrgId == t.OrgId && x.SupplierCode == supplier && x.StockInNo == stockIn).Select(x => x.DebitAmount).FirstOrDefaultAsync();
            if (already + dto.DebitAmount > stockInTotal.Value)
                return Results.BadRequest(new { error = $"Số tiền nợ vượt quá số tiền phải trả ({stockInTotal.Value})." });
        }
    }
    var row = await db.SupplierDebits.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SupplierCode == supplier && x.StockInNo == stockIn);
    var isNew = row is null;
    if (isNew) { row = new SupplierDebit { OrgId = t.OrgId, SupplierCode = supplier, StockInNo = stockIn, Status = "Open" }; db.SupplierDebits.Add(row); }
    row!.DebitAmount += dto.DebitAmount; row.DebitDate = dto.DebitDate; row.Note = dto.Note;
    await db.SaveChangesAsync();
    return Results.Ok(new { row.Id, row.SupplierCode, row.StockInNo, row.DebitAmount, isNew });
}).RequireAuthorization();

app.MapDelete("/api/supplierdebits/{id:long}", async (long id, AppDbContext db, ITenantContext t) =>
{
    var row = await db.SupplierDebits.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (row is null) return Results.NotFound(new { id });
    db.SupplierDebits.Remove(row);
    await db.SaveChangesAsync();
    return Results.Ok(new { deleted = id });
}).RequireAuthorization();

app.MapGet("/api/supplierdebits/{id:long}/payments", async (long id, AppDbContext db, ITenantContext t) =>
{
    var h = await db.SupplierDebits.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
