    var pays = await db.SupplierDebitPayments.Where(p => p.OrgId == t.OrgId && p.SupplierDebitId == h.Id).OrderBy(p => p.Id)
        .Select(p => new { p.PaymentAmount, p.Note, p.PaymentNo, p.DealerCode, p.PayPersonName, p.PayPersonIDCardNo, payDate = p.PayDate.HasValue ? p.PayDate.Value.ToString("yyyy-MM-dd") : "" }).ToListAsync();
    return Results.Ok(new { h.Id, h.DebitAmount, h.PaidAmount, balance = h.DebitAmount - h.PaidAmount, h.Status, count = pays.Count, payments = pays });
}).RequireAuthorization();

// Thanh toán nợ NCC (không vượt số dư; đủ tiền -> Paid).
app.MapPost("/api/supplierdebits/{id:long}/payments", async (long id, SupplierDebitPaymentDto dto, AppDbContext db, ITenantContext t) =>
{
    var h = await db.SupplierDebits.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (h is null) return Results.NotFound(new { id });
    if (dto.PaymentAmount <= 0) return Results.BadRequest(new { error = "Số tiền trả phải lớn hơn 0." });
    // Guard của nguồn (checkPaymentFieldEmpty): đại lý + người nộp + CMND/CCCD + ngày thu đều BẮT BUỘC.
    // ⚠️ CusID KHÔNG bắt buộc — nguồn đã COMMENT dòng truyền strCusID vào hàm check (luật "port dòng active").
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Chưa nhập mã đại lý." });
    if (string.IsNullOrWhiteSpace(dto.PayPersonName)) return Results.BadRequest(new { error = "Chưa nhập tên người nộp tiền." });
    if (string.IsNullOrWhiteSpace(dto.PayPersonIDCardNo)) return Results.BadRequest(new { error = "Chưa nhập số CMND/CCCD người nộp tiền." });
    if (dto.PayDate is null) return Results.BadRequest(new { error = "Chưa nhập ngày thu tiền." });
    var balance = h.DebitAmount - h.PaidAmount;
    if (dto.PaymentAmount > balance) return Results.BadRequest(new { error = $"Số tiền trả vượt số dư công nợ ({balance})." });
    db.SupplierDebitPayments.Add(new SupplierDebitPayment { OrgId = t.OrgId, SupplierDebitId = h.Id, PaymentAmount = dto.PaymentAmount, PayDate = dto.PayDate ?? DateTime.Now, Note = dto.Note,
        PaymentNo = "PM" + DateTime.Now.ToString("yyMMddHHmmss"), DealerCode = dto.DealerCode, PayPersonName = dto.PayPersonName, PayPersonIDCardNo = dto.PayPersonIDCardNo });
    h.PaidAmount += dto.PaymentAmount;
    if (h.PaidAmount >= h.DebitAmount) h.Status = "Paid";
    await db.SaveChangesAsync();
    return Results.Ok(new { h.Id, paidAmount = h.PaidAmount, balance = h.DebitAmount - h.PaidAmount, status = h.Status });
}).RequireAuthorization();

// ===== 🔴 PHÂN BỔ 1 PHIẾU THU sang NHIỀU CÔNG NỢ (luật của nguồn mà port cũ làm mất) =====
// Nguồn BizCarSv.Debit.cs:2976-3007: 1 phiếu thu (Ser_Payment) sinh NHIỀU dòng Ser_PaymentDetail,
// trả lần lượt các công nợ CHƯA HẾT DƯ cho tới khi hết tiền. Port cũ gắn CHẶT 1 lần thu = 1 công nợ
// ⇒ thu 1 lần cho nhiều RO phải tự tay bổ ra từng dòng, và số phiếu thu không nối được các dòng đó với nhau.
// Ba chủ thể (khách hàng / bảo hiểm / nhà cung cấp) dùng CHUNG luật này — nguồn chỉ khác cột khoá.
app.MapPost("/api/debits/allocate-payment", async (
    string subject, SerPaymentAllocateDto dto, AppDbContext db, ITenantContext t) =>
{
    subject = (subject ?? "").Trim().ToLowerInvariant();
    if (subject != "cus" && subject != "ins" && subject != "supplier")
        return Results.BadRequest(new { error = "subject phải là cus | ins | supplier." });

    // Guard của nguồn (checkPaymentFieldEmpty).
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Chưa nhập mã đại lý." });
    if (dto.PaymentAmount <= 0) return Results.BadRequest(new { error = "Số tiền thu phải lớn hơn 0." });
    if (string.IsNullOrWhiteSpace(dto.PayPersonName)) return Results.BadRequest(new { error = "Chưa nhập tên người nộp tiền." });
    if (string.IsNullOrWhiteSpace(dto.PayPersonIDCardNo)) return Results.BadRequest(new { error = "Chưa nhập số CMND/CCCD người nộp tiền." });
    if (dto.PayDate is null) return Results.BadRequest(new { error = "Chưa nhập ngày thu tiền." });
    if (string.IsNullOrWhiteSpace(dto.SubjectKey))
        return Results.BadRequest(new { error = "Chưa chọn chủ thể công nợ (mã KH / số HĐ bảo hiểm / mã NCC)." });

    var payNo = "PM" + DateTime.Now.ToString("yyMMddHHmmss");
    var payDate = dto.PayDate;
    var remaining = dto.PaymentAmount;
    var allocated = new List<object>();

    // ⚠️ LỆCH CÓ CHỦ ĐÍCH so với nguồn: nguồn so sánh "dư nợ > tiền còn lại" nên khi BẰNG NHAU sẽ đi nhánh
    // else rồi vòng sau sinh thêm 1 dòng phân bổ SỐ TIỀN 0. Ở đây dừng ngay khi hết tiền.
    // Tiền dư (nếu trả quá tổng nợ) KHÔNG bị chặn — giống nguồn — mà trả về ở "unallocated".
    if (subject == "cus")
    {
        var debts = await db.CusDebits.Where(x => x.OrgId == t.OrgId && x.CusId == dto.SubjectKey
                        && x.DebitAmount > x.PaidAmount).OrderBy(x => x.Id).ToListAsync();
        foreach (var h in debts)
        {
            if (remaining <= 0) break;
            var left = h.DebitAmount - h.PaidAmount;
            var take = left > remaining ? remaining : left;
            db.CusDebitPayments.Add(new CusDebitPayment { OrgId = t.OrgId, CusDebitId = h.Id, PaymentAmount = take,
                PayDate = payDate, Note = dto.Note, PaymentNo = payNo, DealerCode = dto.DealerCode,
                PayPersonName = dto.PayPersonName, PayPersonIDCardNo = dto.PayPersonIDCardNo });
            h.PaidAmount += take;
            if (h.PaidAmount >= h.DebitAmount) h.Status = "Paid";
            remaining -= take;
            allocated.Add(new { debitNo = h.DebitNo, amount = take, status = h.Status });
        }
    }
    else if (subject == "ins")
    {
        var debts = await db.InsDebits.Where(x => x.OrgId == t.OrgId && x.InsNo == dto.SubjectKey
                        && x.DebitAmount > x.PaidAmount).OrderBy(x => x.Id).ToListAsync();
        foreach (var h in debts)
        {
            if (remaining <= 0) break;
            var left = h.DebitAmount - h.PaidAmount;
            var take = left > remaining ? remaining : left;
            db.InsDebitPayments.Add(new InsDebitPayment { OrgId = t.OrgId, InsDebitId = h.Id, PaymentAmount = take,
                PayDate = payDate, Note = dto.Note, PaymentNo = payNo, DealerCode = dto.DealerCode,
                PayPersonName = dto.PayPersonName, PayPersonIDCardNo = dto.PayPersonIDCardNo });
            h.PaidAmount += take;
            if (h.PaidAmount >= h.DebitAmount) h.Status = "Paid";
            remaining -= take;
            allocated.Add(new { debitNo = h.DebitNo, amount = take, status = h.Status });
        }
    }
    else
    {
        var debts = await db.SupplierDebits.Where(x => x.OrgId == t.OrgId && x.SupplierCode == dto.SubjectKey
                        && x.DebitAmount > x.PaidAmount).OrderBy(x => x.Id).ToListAsync();
        foreach (var h in debts)
        {
            if (remaining <= 0) break;
            var left = h.DebitAmount - h.PaidAmount;
            var take = left > remaining ? remaining : left;
            db.SupplierDebitPayments.Add(new SupplierDebitPayment { OrgId = t.OrgId, SupplierDebitId = h.Id, PaymentAmount = take,
                PayDate = payDate, Note = dto.Note, PaymentNo = payNo, DealerCode = dto.DealerCode,
                PayPersonName = dto.PayPersonName, PayPersonIDCardNo = dto.PayPersonIDCardNo });
            h.PaidAmount += take;
            if (h.PaidAmount >= h.DebitAmount) h.Status = "Paid";
            remaining -= take;
            allocated.Add(new { debitNo = h.StockInNo ?? "", amount = take, status = h.Status });
        }
    }

    if (allocated.Count == 0)
        return Results.BadRequest(new { error = "Chủ thể này không còn công nợ nào chưa trả hết." });

    await db.SaveChangesAsync();
    return Results.Ok(new { paymentNo = payNo, subject, subjectKey = dto.SubjectKey,
        paymentAmount = dto.PaymentAmount, allocatedAmount = dto.PaymentAmount - remaining,
        unallocated = remaining, count = allocated.Count, allocated });
}).RequireAuthorization();

// Tra 1 phiếu thu theo SỐ PHIẾU — gom các dòng phân bổ của cùng lần nộp (cả 3 chủ thể).
app.MapGet("/api/debits/payments/{paymentNo}", async (string paymentNo, AppDbContext db, ITenantContext t) =>
{
    var no = paymentNo.Trim();
    var cus = await db.CusDebitPayments.Where(x => x.OrgId == t.OrgId && x.PaymentNo == no)
        .Select(x => new { subject = "cus", x.PaymentAmount, x.DealerCode, x.PayPersonName, x.PayPersonIDCardNo, x.Note,
            payDate = x.PayDate.HasValue ? x.PayDate.Value.ToString("yyyy-MM-dd") : "" }).ToListAsync();
    var ins = await db.InsDebitPayments.Where(x => x.OrgId == t.OrgId && x.PaymentNo == no)
        .Select(x => new { subject = "ins", x.PaymentAmount, x.DealerCode, x.PayPersonName, x.PayPersonIDCardNo, x.Note,
            payDate = x.PayDate.HasValue ? x.PayDate.Value.ToString("yyyy-MM-dd") : "" }).ToListAsync();
    var sup = await db.SupplierDebitPayments.Where(x => x.OrgId == t.OrgId && x.PaymentNo == no)
        .Select(x => new { subject = "supplier", x.PaymentAmount, x.DealerCode, x.PayPersonName, x.PayPersonIDCardNo, x.Note,
            payDate = x.PayDate.HasValue ? x.PayDate.Value.ToString("yyyy-MM-dd") : "" }).ToListAsync();
    var all = cus.Concat(ins).Concat(sup).ToList();
    if (all.Count == 0) return Results.NotFound(new { paymentNo = no });
    return Results.Ok(new { paymentNo = no, count = all.Count, totalAmount = all.Sum(x => x.PaymentAmount), lines = all });
}).RequireAuthorization();

// ===== Báo cáo công nợ (report tái-dùng CusDebit + InsDebit — port 1:1 FrmReportTotalCusDebit/InsDebit/ReceivableDebit + FrmReportSerPaymentGet, TCMotor) =====
// Tổng công nợ phải thu: gộp dư nợ khách hàng + hãng bảo hiểm (mỗi bên 1 nhóm), có tổng cộng.
app.MapGet("/api/report/receivable-debt", async (AppDbContext db, ITenantContext t, string? debtorType) =>
{
    var cus = await db.CusDebits.Where(x => x.OrgId == t.OrgId && x.DebitAmount > x.PaidAmount)
        .GroupBy(x => new { x.CusId, x.CusName })
        .Select(g => new { debtorType = "Customer", code = g.Key.CusId, name = g.Key.CusName, debit = g.Sum(x => x.DebitAmount), paid = g.Sum(x => x.PaidAmount), balance = g.Sum(x => x.DebitAmount - x.PaidAmount) }).ToListAsync();
    var ins = await db.InsDebits.Where(x => x.OrgId == t.OrgId && x.DebitAmount > x.PaidAmount)
        .GroupBy(x => new { x.InsNo, x.InsName })
        .Select(g => new { debtorType = "Insurance", code = g.Key.InsNo, name = g.Key.InsName, debit = g.Sum(x => x.DebitAmount), paid = g.Sum(x => x.PaidAmount), balance = g.Sum(x => x.DebitAmount - x.PaidAmount) }).ToListAsync();
    var all = cus.Concat(ins).ToList();
    if (!string.IsNullOrWhiteSpace(debtorType)) all = all.Where(r => r.debtorType == debtorType).ToList();
    all = all.OrderByDescending(r => r.balance).ToList();
    return Results.Ok(new { totalCustomer = cus.Sum(r => r.balance), totalInsurance = ins.Sum(r => r.balance), grandTotal = all.Sum(r => r.balance), rows = all });
}).RequireAuthorization();

// ===== 🔴 #215 TÌM KIẾM CÔNG NỢ (3 loại) — `SerCusDebitSearch` =====
// Màn gốc: `Views/Debit/FrmCusDebitSearch.cs` (258 dòng, DMSCarSv) — hai nút `btnSearch` · `btnExit`.
// Nguồn: `TERP.BizCarSv/BizCarSv.Debit.cs:1632`; WS LIVE (`WSCarSv.asmx.cs:18250`) gọi đúng hàm này.
// BƯỚC 3B: md5 CẢ FILE `9119d491` (3784 dòng) KHỚP 2 máy.
//
// 🔴 PHÁT HIỆN GIẢI THÍCH #213/#214: nguồn lọc **`d.DebitType = @DebitType` VÀ `r.PaymentType = @DebitType`**
//    — tức mã loại nợ và mã loại phiếu thu DÙNG CHUNG một bộ hằng `TConst.SerDebitType` (Const.Main.cs:372):
//      **1 = khách hàng · 2 = bảo hiểm · 3 = nhà cung cấp**.
//    ⇒ `PaymentType='1'` ở #213 và `'2'` ở #214 không phải hai quy ước rời rạc mà là CÙNG một bảng mã.
//    Nguồn có hẳn ba nhánh SQL theo `DebitType` (1632: khách hàng · 1876: bảo hiểm · 1930: nhà cung cấp).
//
// 🔴 Bộ lọc của nguồn dựng bằng `SqlUtils.BuildClause` với chuỗi điều kiện đã ghép sẵn ở tầng service:
//    tên/hãng BH/NCC nhận dạng `"like %giá trị%"` ⇒ **so khớp CHỨA, không phân biệt hoa thường**.
//    Riêng `strIsDebit`: nếu = `Flag.Active` ("1") thì thành `"> 0"`, ngược lại **chuỗi rỗng ⇒ BỎ HẲN điều kiện**
//    (không phải lọc `= 0`). Nghĩa là: bật cờ ⇒ chỉ hiện dòng CÒN nợ; tắt cờ ⇒ hiện TẤT CẢ.
// ===== 🔴 #559 VÁ `/api/debits/search` — TRẢ HAI NỢ CÓ TÊN + GHI NHẬN LỖI `FULL JOIN` =====
// Nguồn: `BizCarSv.Debit.cs:1632 SerCusDebitSearch` (đã port ở cụm #213/#214/#215).
// Hai bộ lọc từng ghi *"chưa nối, KHÔNG bịa"* nay **trả được**, vì hai cột cần thiết đã có:
//   · `dealerCode` — cột `CusDebit.DealerCode` vừa thêm ở **#557 §12**;
//   · `plateNo` — nối qua `RONo` sang `RepairOrders.LicensePlate` (nguồn nối `c.PlateNo` trên bảng khách).
//   ⚠️ Riêng `groupName` (`sg.GroupName`) **vẫn là nợ**: MiniHTC chưa có bảng nhóm khách hàng.
//
// 🔴🔴 **PHÁT HIỆN Ở NGUỒN — `FULL JOIN` CHỈ NỐI THEO `CusID`, ĐIỀU KIỆN ĐÚNG BỊ COMMENT**:
//     `zzzzClauseJoin_Debit` ← `"ON d1.CusID = r1.CusID"`
//     `--ON d1.CusID = r1.CusID and d1.InsNo = r1.InsNo and d1.SupplierID = r1.SupplierID`
//   ⇒ Với nợ **bảo hiểm**/**nhà cung cấp** (khoá thật là `InsNo`/`SupplierID`, còn `CusID` **NULL**),
//     phép nối so `NULL = NULL` — trong SQL là **KHÔNG khớp** ⇒ `FULL JOIN` **tách đôi** mỗi đối tượng
//     thành **một dòng chỉ có nợ** và **một dòng chỉ có thu**; số dư **không bao giờ trừ được cho nhau**.
//   ⇒ Luật *"port dòng ACTIVE"* dùng **ngược**: ở đây dòng **comment mới là dòng đúng**, dòng đang chạy
//     là dòng **thiếu**. MiniHTC gộp theo **khoá đúng của từng loại** nên **không** dính — nêu cờ để đo.
// 🔴 **Chỉ `DealerCode` được bọc toán tử; các bộ lọc khác thì không** — bằng chứng trực tiếp cho bẫy #410:
//     `BuildClause("and", "c.DealerCode", **"=" + strDealerCodeConditionList**, …)`
//     `BuildClause("and", "c.CusID", strCusIDConditionList, …)`   ← **không** toán tử ⇒ **bỏ im lặng**
//     `BuildClause("and", "c.PlateNo", strPlateNoConditionList, …)` ← **không** toán tử
//   ⚠️ Một lời gọi còn viết `"and "` (**thừa dấu cách**) — vô hại, nhưng là dấu vết chép tay.
// ⚠️ Ba tham số bị **bake**: `d.DealerCode = '@DealerCode'` · `d.DebitType = '@DebitType'` ·
//   `r.PaymentType = '@DebitType'`. ⚪ Kiểm tra âm tính: hai bảng mã **trùng giá trị**
//   (`SerDebitType 1/2/3` ↔ `SerPaymentType 1/2/3`) nên dùng chung **hiện đúng** — nhưng là phụ thuộc ngầm.
app.MapGet("/api/debits/search", async (AppDbContext db, ITenantContext t,
    string? debitType, string? name, string? plateNo, string? insName, string? supplierName, string? isDebit,
    string? dealerCode) =>
{
    var dt = (debitType ?? "1").Trim();
    if (dt is not ("1" or "2" or "3"))
        return Results.BadRequest(new { error = "Loại công nợ chỉ nhận 1 (khách hàng) | 2 (bảo hiểm) | 3 (nhà cung cấp)." });
    var onlyDebt = (isDebit ?? "").Trim() == "1";   // nguồn: Flag.Active ⇒ "> 0"; ngược lại bỏ hẳn điều kiện

    var rows = new List<object>();
    if (dt == "1")
    {
        var q1 = db.CusDebits.Where(x => x.OrgId == t.OrgId);
        if (!string.IsNullOrWhiteSpace(name)) q1 = q1.Where(x => x.CusName != null && x.CusName.ToLower().Contains(name!.Trim().ToLower()));
        // #559 dealerCode — bộ lọc DUY NHẤT được nguồn bọc toán tử "=".
        if (!string.IsNullOrWhiteSpace(dealerCode)) q1 = q1.Where(x => x.DealerCode == dealerCode!.Trim());
        // #559 plateNo — nguồn lọc c.PlateNo; MiniHTC nối qua RONo sang lệnh sửa chữa.
        if (!string.IsNullOrWhiteSpace(plateNo))
        {
            var pl = plateNo!.Trim().ToLower();
            var roNos = await db.RepairOrders.Where(r => r.OrgId == t.OrgId && r.LicensePlate.ToLower().Contains(pl))
                .Select(r => r.RONo).ToListAsync();
            q1 = q1.Where(x => x.RONo != null && roNos.Contains(x.RONo!));
        }
        var list = await q1.GroupBy(x => new { x.CusId, x.CusName })
            .Select(g => new { g.Key.CusId, g.Key.CusName, Debit = g.Sum(x => x.DebitAmount), Paid = g.Sum(x => x.PaidAmount) })
            .ToListAsync();
        rows.AddRange(list.Select(x => new { code = x.CusId, itemName = x.CusName, debitType = dt,
                                            debitAmount = x.Debit, paymentAmount = x.Paid, remain = x.Debit - x.Paid })
                          .Where(r => !onlyDebt || r.remain > 0).Cast<object>());
    }
    else if (dt == "2")
    {
        var q2 = db.InsDebits.Where(x => x.OrgId == t.OrgId);
        if (!string.IsNullOrWhiteSpace(insName)) q2 = q2.Where(x => x.InsName != null && x.InsName.ToLower().Contains(insName!.Trim().ToLower()));
        var list = await q2.GroupBy(x => new { x.InsNo, x.InsName })
            .Select(g => new { g.Key.InsNo, g.Key.InsName, Debit = g.Sum(x => x.DebitAmount), Paid = g.Sum(x => x.PaidAmount) })
            .ToListAsync();
        rows.AddRange(list.Select(x => new { code = x.InsNo, itemName = x.InsName, debitType = dt,
                                            debitAmount = x.Debit, paymentAmount = x.Paid, remain = x.Debit - x.Paid })
                          .Where(r => !onlyDebt || r.remain > 0).Cast<object>());
    }
    else
    {
        var q3 = db.SupplierDebits.Where(x => x.OrgId == t.OrgId);
        // Entity MiniHTC chỉ có SupplierCode (không lưu tên NCC) ⇒ lọc theo MÃ; tên do bảng NCC riêng giữ.
        if (!string.IsNullOrWhiteSpace(supplierName)) q3 = q3.Where(x => x.SupplierCode.ToLower().Contains(supplierName!.Trim().ToLower()));
        var list = await q3.GroupBy(x => new { x.SupplierCode })
            .Select(g => new { g.Key.SupplierCode, Debit = g.Sum(x => x.DebitAmount), Paid = g.Sum(x => x.PaidAmount) })
            .ToListAsync();
        rows.AddRange(list.Select(x => new { code = x.SupplierCode, itemName = (string?)null, debitType = dt,
                                            debitAmount = x.Debit, paymentAmount = x.Paid, remain = x.Debit - x.Paid })
                          .Where(r => !onlyDebt || r.remain > 0).Cast<object>());
    }

    return Results.Ok(new { debitType = dt, onlyDebt, count = rows.Count, rows,
        note = "DebitType dùng chung bảng mã với PaymentType (TConst.SerDebitType: 1 KH · 2 BH · 3 NCC).",
        // ===== #559 =====
        dealerCodeFilterApplied = !string.IsNullOrWhiteSpace(dealerCode),
        plateNoFilterApplied = !string.IsNullOrWhiteSpace(plateNo) && dt == "1",
        plateNoResolvedVia = "CusDebit.RONo -> RepairOrder.LicensePlate",
        sourceFullJoinOnCusIdOnly = "ON d1.CusID = r1.CusID — dieu kien day du (InsNo/SupplierID) BI COMMENT",
        sourceWouldSplitRowsForType2And3 = dt != "1",
        onlyDealerCodeGetsOperatorPrefix = true,
        stillOwed = "Bo loc nhom khach (sg.GroupName) — MiniHTC chua co bang nhom khach hang." });
}).RequireAuthorization();

// ===== 🔴 #214 CÔNG NỢ BẢO HIỂM theo KỲ — `Ser_InvReportInsuranceDebitRpt_New20210618` =====
// Màn gốc: `Views/Debit/FrmReportTotalInsDebit.cs` (303 dòng, DMSCarSv) — 4 nút Search/Print/Export/Thoát.
// Nguồn: `TERP.BizCarSv/BizCarSv.Service.Report.cs:2392`. md5 CẢ FILE `b7ecca4c` KHỚP 2 máy.
//
// 🔴 TWIN + FILE CHẾT (bắt được nhờ trace, không theo tên):
//   · Biz có HAI hàm cùng tên: `Ser_InvReportInsuranceDebitRpt` (2184) và `..._New20210618` (2392).
//   · Thư mục WS có BA file: `WSCarSv.asmx.20210208.cs` · `WSCarSv.asmx.20210412.cs` · `WSCarSv.asmx.cs`;
//     csproj chỉ `<Compile Include="WSCarSv.asmx.cs">` ⇒ hai file có ngày trong tên là **FILE CHẾT**.
//   · Hai file chết gọi bản 2184; **bản LIVE (13080) gọi `_New20210618`** ⇒ port theo 2392.
//
// Báo cáo theo KỲ (FromDate..ToDate), mỗi hãng bảo hiểm 4 chỉ tiêu:
//   `TGD` dư đầu kỳ  = (nợ phát sinh TRƯỚC FromDate) − (thu TRƯỚC FromDate)
//   `PST` phát sinh tăng = nợ trong kỳ          `PSG` phát sinh giảm = thu trong kỳ
//   `TGC` dư cuối kỳ = TGD + PST − PSG
// 🔴 Thu của nhánh BẢO HIỂM lọc `PaymentType = '2'` — khác nhánh KHÁCH HÀNG dùng `'1'` (xem #213).
//    Hai mã này là hai loại phiếu thu khác nhau, KHÔNG được dùng lẫn.
// 🔴 Guard cuối của nguồn: `where (deb.InsNo is not null or dk.InsNo is not null)` — hãng nào **không có
//    phát sinh trong kỳ VÀ không có dư đầu kỳ** thì KHÔNG lên báo cáo (khác với lọc `số dư != 0` ở #213).
app.MapGet("/api/report/insurance-debit", async (AppDbContext db, ITenantContext t, DateTime? fromDate, DateTime? toDate) =>
{
    var from = (fromDate ?? DateTime.Today.AddMonths(-1)).Date;
    var to = (toDate ?? DateTime.Today).Date;
    if (from > to) return Results.BadRequest(new { error = "Từ ngày phải nhỏ hơn hoặc bằng đến ngày." });

    var debits = await db.InsDebits.Where(x => x.OrgId == t.OrgId).ToListAsync();
    var pays = await (from p in db.InsDebitPayments.Where(x => x.OrgId == t.OrgId)
                      join h in db.InsDebits.Where(x => x.OrgId == t.OrgId) on p.InsDebitId equals h.Id
                      select new { h.InsNo, h.InsName, p.PaymentAmount, p.PayDate }).ToListAsync();

    var keys = debits.Select(d => new { d.InsNo, d.InsName })
        .Concat(pays.Select(p => new { p.InsNo, p.InsName }))
        .Distinct().ToList();

    var rows = new List<object>();
    decimal sTGD = 0, sPST = 0, sPSG = 0, sTGC = 0;
    foreach (var k in keys)
    {
        // dư ĐẦU KỲ: mọi phát sinh TRƯỚC FromDate (nguồn: substring(...) < @FromDate).
        var debBefore = debits.Where(d => d.InsNo == k.InsNo && d.DebitDate.HasValue && d.DebitDate.Value.Date < from).Sum(d => d.DebitAmount);
        var payBefore = pays.Where(p => p.InsNo == k.InsNo && p.PayDate.HasValue && p.PayDate.Value.Date < from).Sum(p => p.PaymentAmount);
        var tgd = debBefore - payBefore;

        // trong kỳ
        var pst = debits.Where(d => d.InsNo == k.InsNo && d.DebitDate.HasValue && d.DebitDate.Value.Date >= from && d.DebitDate.Value.Date <= to).Sum(d => d.DebitAmount);
        var psg = pays.Where(p => p.InsNo == k.InsNo && p.PayDate.HasValue && p.PayDate.Value.Date >= from && p.PayDate.Value.Date <= to).Sum(p => p.PaymentAmount);

        // guard của nguồn: không có phát sinh trong kỳ VÀ không có dư đầu kỳ thì bỏ hẳn dòng.
        var hasInPeriod = pst != 0 || psg != 0;
        if (!hasInPeriod && tgd == 0) continue;

        var tgc = tgd + pst - psg;
        sTGD += tgd; sPST += pst; sPSG += psg; sTGC += tgc;
        rows.Add(new { insNo = k.InsNo, insName = k.InsName, tgd, pst, psg, tgc });
    }

    return Results.Ok(new
    {
        fromDate = from, toDate = to,
        totalTGD = sTGD, totalPST = sPST, totalPSG = sPSG, totalTGC = sTGC,
        count = rows.Count, rows,
        note = "PSG chỉ gồm phiếu thu loại bảo hiểm (nguồn lọc PaymentType='2'); nhánh khách hàng dùng '1'."
    });
}).RequireAuthorization();

