        deadLeftJoinNote = "left join ser_mst_part rồi đưa p.IsActive và p.DealerCode vào WHERE ⇒ LEFT "
            + "join chết (lệ #414, lần thứ tư trong cụm kho).",
        onHandSource = usedInstances ? "PartInstances (nhập − xuất tới mốc)" : "ServicePart.Quantity (dự phòng)",
        onHandSourceNote = usedInstances ? null
            : "Chưa có dữ liệu PartInstances nên SLC lấy tạm từ ServicePart.Quantity — KHÔNG phải cách "
              + "nguồn tính (nguồn dựng từ nhập/xuất theo mốc). Báo cờ thay vì lặng lẽ đổi nguồn số liệu.",
        rows,
    });
}).RequireAuthorization();

app.MapGet("/api/report/part-variation-price", async (AppDbContext db, ITenantContext t,
    DateTime? fromDate, DateTime? toDate, int? top) =>
{
    var f = (fromDate ?? DateTime.Today.AddMonths(-1)).Date;
    var to = (toDate ?? DateTime.Today).Date;

    var inIds = (await db.PartStockIns.Where(s => s.OrgId == t.OrgId && s.Status == "3"
            && s.StockInDate >= f && s.StockInDate <= to)
        .Select(s => s.Id).ToListAsync()).ToHashSet();
    var lines = await db.PartStockInLines
        .Where(l => l.OrgId == t.OrgId && inIds.Contains(l.StockInId)).ToListAsync();
    var partMaster = (await db.ServiceParts.Where(p => p.OrgId == t.OrgId)
        .Select(p => new { p.PartCode, p.PartName, p.Unit }).ToListAsync())
        .GroupBy(p => p.PartCode).ToDictionary(g => g.Key, g => g.First());

    var droppedNotInMaster = 0; var rowsWithoutPrice = 0;
    var rows = new List<dynamic>();
    foreach (var g in lines.GroupBy(l => l.PartCode))
    {
        // Nối TRONG với danh mục: không có thì MẤT DÒNG.
        if (!partMaster.TryGetValue(g.Key, out var pm)) { droppedNotInMaster++; continue; }

        // 🔴 DISTINCT của nguồn ⇒ tập MỨC GIÁ duy nhất, không phải số lần nhập.
        var prices = g.Select(l => l.Price).Distinct().ToList();   // Price khong nullable trong entity nay
        if (prices.Count == 0) rowsWithoutPrice++;
        rows.Add(new
        {
            partCode = g.Key, partName = pm.PartName, unit = pm.Unit,
            minPrice = prices.Count == 0 ? (decimal?)null : prices.Min(),
            maxPrice = prices.Count == 0 ? (decimal?)null : prices.Max(),
            distinctPriceCount = prices.Count,          // = CountPrice của nguồn
            stockInLineCount = g.Count(),               // số dòng nhập THẬT — nguồn không có
            priceSpread = prices.Count == 0 ? (decimal?)null : prices.Max() - prices.Min(),
        });
    }

    var ordered = rows.OrderByDescending(r => (int)r.distinctPriceCount).ToList();
    var n = top ?? 0;
    var outRows = n > 0 ? ordered.Take(n).ToList() : ordered;

    return Results.Ok(new
    {
        count = outRows.Count, fromDate = f, toDate = to, top = n > 0 ? n : (int?)null,
        countPriceMeaningNote = "CountPrice của nguồn ĐẾM SỐ MỨC GIÁ KHÁC NHAU, KHÔNG phải số lần nhập "
            + "(bảng tạm dựng bằng select DISTINCT gồm cả cột price). Nhập 50 lần cùng một giá ⇒ CountPrice = 1. "
            + "MiniHTC đặt tên rõ: distinctPriceCount, và trả thêm stockInLineCount là số dòng nhập thật.",
        minMaxNote = "MinPrice/MaxPrice cũng tính trên tập giá DUY NHẤT, không theo trọng số lần nhập.",
        rowsWithoutPrice,
        nullPriceNote = rowsWithoutPrice > 0
            ? "count(price) của SQL bỏ qua NULL ⇒ phụ tùng mà mọi dòng nhập đều thiếu giá vẫn có mặt "
              + "với CountPrice = 0 và Min/Max = NULL — hiện trong báo cáo nhưng vô nghĩa."
            : null,
        droppedNotInMaster,
        droppedNotInMasterNote = "join Ser_mst_part là nối TRONG ⇒ phụ tùng không có trong danh mục biến "
            + "mất; nhất quán với #416/#417 — cả cụm báo cáo kho đều loại nhóm này.",
        orderByOkNote = "CÓ order by countPrice desc trong chính câu lấy TOP ⇒ không dính lỗi #415. "
            + "Bốn báo cáo cùng họ đã kiểm: #415 hỏng, #416/#417/#419 lành.",
        redundantColumnNote = "st.Status nằm trong danh sách DISTINCT nhưng WHERE đã ghim Status = '3' "
            + "⇒ cột hằng, thừa.",
        endDateExclusive = true,
        scopeNote = "Chỉ xét GIÁ NHẬP (Ser_Inv_StockInDetail.price), không liên quan giá bán.",
        rows = outRows,
    });
}).RequireAuthorization();

app.MapGet("/api/report/part-top-rotate", async (AppDbContext db, ITenantContext t,
    DateTime? fromDate, DateTime? toDate, int? top, string? dealer) =>
{
    var f = (fromDate ?? DateTime.Today.AddMonths(-1)).Date;
    var to = (toDate ?? DateTime.Today).Date;

    var inst = await db.PartInstances.Where(x => x.OrgId == t.OrgId
            && (dealer == null || x.DealerCode == dealer)).ToListAsync();
    var stockIns = (await db.PartStockIns.Where(s => s.OrgId == t.OrgId && s.Status == "3")
        .Select(s => s.Id).ToListAsync()).ToHashSet();
    var stockOuts = (await db.PartStockOuts.Where(s => s.OrgId == t.OrgId && s.Status == "3")
        .Select(s => s.Id).ToListAsync()).ToHashSet();
    var partMaster = (await db.ServiceParts.Where(p => p.OrgId == t.OrgId)
        .Select(p => new { p.PartCode, p.PartName, p.Unit }).ToListAsync())
        .GroupBy(p => p.PartCode).ToDictionary(g => g.Key, g => g.First());

    // --- #tbl_partin: DISTINCT trên bộ cột gồm cả Quantity ⇒ gộp dòng trùng (nguồn đếm thiếu).
    var inKeys = inst.Where(x => x.StockInId != null && stockIns.Contains(x.StockInId!.Value)
            && x.DateIn != null && x.DateIn >= f && x.DateIn <= to)
        .Select(x => new { x.PartCode, x.StockInId, x.Quantity, x.DateIn })
        .Distinct().ToList();
    var outKeys = inst.Where(x => x.StockOutId != null && stockOuts.Contains(x.StockOutId!.Value)
            && x.DateOut != null && x.DateOut >= f && x.DateOut <= to)
        .Select(x => new { x.PartCode, x.StockOutId, x.Quantity, x.DateOut })
        .Distinct().ToList();

    var inAgg = inKeys.GroupBy(x => x.PartCode).ToDictionary(g => g.Key,
        g => new { Qty = g.Sum(x => x.Quantity), Times = g.Count() });
    var outAgg = outKeys.GroupBy(x => x.PartCode).ToDictionary(g => g.Key,
        g => new { Qty = g.Sum(x => x.Quantity), Times = g.Count() });

    // 🔴 Nối TRONG: chỉ giữ phụ tùng CÓ CẢ nhập LẪN xuất trong kỳ.
    var both = inAgg.Keys.Intersect(outAgg.Keys).ToList();
    var inOnly = inAgg.Keys.Except(outAgg.Keys).OrderBy(x => x).ToList();
    var outOnly = outAgg.Keys.Except(inAgg.Keys).OrderBy(x => x).ToList();

    var droppedNotInMaster = 0;
    var rows = new List<dynamic>();
    foreach (var code in both)
    {
        if (!partMaster.TryGetValue(code, out var pm)) { droppedNotInMaster++; continue; }
        rows.Add(new
        {
            partCode = code, partName = pm.PartName, unit = pm.Unit,
            inQuantity = inAgg[code].Qty, outQuantity = outAgg[code].Qty,
            soLanNhap = inAgg[code].Times, soLanXuat = outAgg[code].Times,
        });
    }

    // Giữ NGUYÊN hướng sắp của nguồn, kể cả chỗ nghi ngờ.
    var ordered = rows
        .OrderByDescending(r => (decimal)r.outQuantity)
        .ThenBy(r => (decimal)r.inQuantity)
        .ThenBy(r => (int)r.soLanXuat)
        .ThenByDescending(r => (int)r.soLanNhap)
        .ToList();
    var n = top ?? 0;
    var outRows = n > 0 ? ordered.Take(n).ToList() : ordered;

    return Results.Ok(new
    {
        count = outRows.Count, fromDate = f, toDate = to, top = n > 0 ? n : (int?)null,
        sortSpec = "outQuantity desc, inQuantity ASC, soLanXuat ASC, soLanNhap desc (nguyên văn nguồn)",
        sortDirectionSuspect = true,
        sortNote = "Chú thích đầu hàm ghi thứ tự ưu tiên 1..4 nhưng câu ORDER BY đảo chiều xen kẽ; "
            + "riêng soLanXuat ASC xếp phụ tùng có ÍT lần xuất lên TRÊN — ngược nghĩa 'luân chuyển nhanh'. "
            + "Giữ nguyên 1:1, KHÔNG tự sửa; cần người nắm nghiệp vụ chốt hướng đúng.",
        innerJoinDropped = new { inOnlyCount = inOnly.Count, outOnlyCount = outOnly.Count },
        inOnly, outOnly,
        innerJoinNote = "Nguồn nối TRONG #IN với #OUT ⇒ phụ tùng CHỈ NHẬP mà chưa xuất lần nào trong kỳ "
            + "biến mất hoàn toàn — đúng nhóm hàng Ứ ĐỌNG, thứ đáng nhìn thấy nhất. Hàng bán từ tồn kỳ "
            + "trước (kỳ này không nhập) cũng biến mất. Hai danh sách trên là phần bị loại.",
        distinctUndercountNote = "Nguồn select DISTINCT trên chín cột (gồm cả Quantity) RỒI mới sum/count "
            + "⇒ hai dòng chi tiết cùng phiếu, cùng phụ tùng, CÙNG số lượng bị gộp làm một ⇒ tổng số lượng "
            + "và số lần đều ĐẾM THIẾU. MiniHTC tái hiện đúng để số khớp WinForm.",
        droppedNotInMaster,
        deadLeftJoinNote = "left join ser_mst_part rồi đưa p.dealercode vào WHERE ⇒ LEFT join chết (lệ #414). "
            + "and p.PartId is not null đặt sau nối TRONG là điều kiện THỪA.",
        statusLiteralNote = "sti.Status = '3' viết dạng CHUỖI ở đây, nhưng #415 cùng ý nghĩa lại viết = 3 dạng SỐ.",
        endDateExclusive = true,
        endDateNote = "Mốc <= toDate trên cột ngày ⇒ mất trọn ngày cuối nếu cột có phần giờ (lệ #415).",
        rows = outRows,
    });
}).RequireAuthorization();

app.MapGet("/api/report/part-top-profit", async (AppDbContext db, ITenantContext t,
    DateTime? fromDate, DateTime? toDate, int? top, string? dealer, string? costingMethod) =>
{
    var f = (fromDate ?? DateTime.Today.AddMonths(-1)).Date;
    var to = (toDate ?? DateTime.Today).Date;
    var mcc = (costingMethod ?? "FIFO").Trim().ToUpperInvariant();

    var inst = await db.PartInstances.Where(x => x.OrgId == t.OrgId
            && (dealer == null || x.DealerCode == dealer)
            && x.Status != "4" && x.Status != "5"          // danh sách ĐEN, không phải trắng
            && x.StockOutNo != null                        // `like '%%'` loại NULL ⇒ chỉ lô ĐÃ XUẤT
            && x.DateOut != null && x.DateOut >= f && x.DateOut <= to
            && x.DateIn != null && x.DateIn <= to)
        .ToListAsync();

    var inLines = (await db.PartStockInLines.Where(l => l.OrgId == t.OrgId).ToListAsync())
        .GroupBy(l => l.StockInId + "|" + l.PartCode).ToDictionary(g => g.Key, g => g.First());
    var outLines = (await db.PartStockOutLines.Where(l => l.OrgId == t.OrgId).ToListAsync())
        .GroupBy(l => l.StockOutId + "|" + l.PartCode).ToDictionary(g => g.Key, g => g.First());
    var partMaster = (await db.ServiceParts.Where(p => p.OrgId == t.OrgId)
        .Select(p => new { p.PartCode, p.PartName, p.Unit }).ToListAsync())
        .GroupBy(p => p.PartCode).ToDictionary(g => g.Key, g => g.First());

    var droppedNotInMaster = 0;
    var rows = new List<dynamic>();
    foreach (var g in inst.GroupBy(x => x.PartCode))
    {
        // LEFT join chết: nguồn đưa p.Dealercode vào WHERE ⇒ không có trong danh mục là MẤT DÒNG.
        if (!partMaster.TryGetValue(g.Key, out var pm)) { droppedNotInMaster++; continue; }

        decimal cost = 0m, sale = 0m;
        foreach (var x in g)
        {
            inLines.TryGetValue(x.StockInId + "|" + x.PartCode, out var il);
            outLines.TryGetValue(x.StockOutId + "|" + x.PartCode, out var ol);
            var inPrice = il?.Price ?? x.SIPrice ?? 0m;      // isnull(sidd.Price, isnull(pf.SIPrice,0))
            var inVat = il?.VAT ?? 0m;
            var outPrice = ol?.Price ?? x.SOPrice ?? 0m;
            var outVat = ol?.Vat ?? 0m;
            cost += inPrice * x.Quantity + inVat * 0.01m * inPrice * x.Quantity;
            sale += outPrice * x.Quantity + outVat * 0.01m * outPrice * x.Quantity;
        }

        rows.Add(new
        {
            partCode = g.Key, partName = pm.PartName, unit = pm.Unit,
            tongGiaNhap = cost, tongGiaBan = sale, profit = sale - cost,
            // Con số mà NGUỒN sẽ ra nếu đại lý không dùng FIFO: giá vốn coi như 0.
            profitIfSourceBehaviour = mcc == "FIFO" ? sale - cost : sale,
            instanceCount = g.Count(),
        });
    }

    // Nguồn CÓ order by Profit desc, partcode — giữ đúng.
    var ordered = rows.OrderByDescending(r => (decimal)r.profit).ThenBy(r => (string)r.partCode).ToList();
    var n = top ?? 0;
    var outRows = n > 0 ? ordered.Take(n).ToList() : ordered;

    return Results.Ok(new
    {
        count = outRows.Count, fromDate = f, toDate = to, top = n > 0 ? n : (int?)null,
        costingMethod = mcc,
        zeroCostFallback = mcc != "FIFO",
        zeroCostNote = mcc != "FIFO"
            ? "NGUỒN sẽ trả TongGiaNhap = 0 vì tham số MCC của đại lý không phải FIFO (nhánh bình quân "
              + "gia quyền đã bị COMMENT) ⇒ toàn bộ doanh thu bị báo là lợi nhuận. MiniHTC VẪN tính giá "
              + "vốn thật (cột profit); xem profitIfSourceBehaviour để biết con số nguồn sẽ ra."
            : "MCC = FIFO ⇒ nguồn và MiniHTC tính giống nhau.",
        // ===== #418 ĐỐI CHIẾU TWIN `_WH` — lần này GIỐNG HỆT, và đó cũng là một kết quả =====
        // Diff `Ser_InvReportPartTopProfit` (`Inventory.Report.cs:6729-6901`, 164 dòng sau khi bỏ
        //   khoảng trắng) với `Ser_InvReportPartTopProfit_WH` (`WH.cs:7581-7750`, 162 dòng):
        //   khác biệt còn lại **chỉ là hai dòng đánh dấu `#region`**, ngoài phần định tuyến CSDL.
        // 📌 Kiểm bằng ĐẾM CHUỖI (lệ #413 — đừng đọc lướt), năm mốc đều 1=1 ở cả hai bản:
        //   `Else '0'` · `paramcode='MCC'` · `like '%%'` · `GetAverageCost` · `order by Profit desc`.
        //   ⇒ **Lỗi giá vốn = 0 khi không FIFO có ở CẢ HAI bản** — không phải chỉ bản Main.
        //     Chuyển sang màn kho cũng không thoát; sửa thì phải sửa cả hai.
        // 📊 Thống kê twin `_WH` tới #418: giống hệt ở #406, #407, #409, #418 · lệch thật ở #378, #413.
        //   4/6 giống — nhưng 2 lần lệch đều là lệch NGHIỆP VỤ nặng, nên vẫn phải diff từng hàm.
        whTwinIdentical = true,
        whTwinNote = "Ser_InvReportPartTopProfit_WH (WH.cs:7581) diff với bản Main chỉ còn hai dòng "
            + "#region ngoài phần định tuyến CSDL. Đếm chuỗi: Else '0' / paramcode='MCC' / like '%%' / "
            + "GetAverageCost / order by Profit desc đều 1=1 hai bên ⇒ LỖI GIÁ VỐN = 0 CÓ Ở CẢ HAI BẢN, "
            + "sửa thì phải sửa cả hai. Không cần tham số scope cho báo cáo này.",
        orderByNote = "Hàm này CÓ order by Profit desc, partcode trong chính câu lấy TOP ⇒ KHÔNG dính "
            + "lỗi thiếu ORDER BY của #415. Hai báo cáo sinh đôi về hình thức, chỉ một cái hỏng.",
        soldOnlyNote = "Nguồn lọc StockOutNo like '%%' — trông như không lọc, nhưng like LOẠI NULL "
            + "⇒ thực chất chỉ lấy lô ĐÃ XUẤT.",
        droppedNotInMaster,
        droppedNotInMasterNote = droppedNotInMaster > 0
            ? "Phụ tùng không có trong danh mục bị loại: nguồn left join ser_mst_part rồi đưa "
              + "p.Dealercode vào WHERE ⇒ LEFT join chết (lệ #414)."
            : null,
        statusBlacklistNote = "Status not in ('4','5') là danh sách ĐEN — mã lạ hoặc NULL VẪN được tính.",
        dateNote = "Ba mốc cùng lúc: DateOut trong khoảng, VÀ DateIn <= toDate (lô nhập sau kỳ bị loại).",
        priceFallbackNote = "Giá lấy dòng chi tiết phiếu trước, không có mới lấy giá lưu ở lô "
            + "(isnull(sidd.Price, isnull(pf.SIPrice,0))) — hai nguồn giá cho cùng một lô.",
        rows = outRows,
    });
}).RequireAuthorization();

app.MapGet("/api/report/part-top-revenue", async (AppDbContext db, ITenantContext t,
    DateTime? fromDate, DateTime? toDate, int? top, string? warehouse) =>
{
    var f = (fromDate ?? DateTime.Today.AddMonths(-1)).Date;
    var to = (toDate ?? DateTime.Today).Date;   // ⚠️ nguồn coi là 00:00:00 của ngày này

    var outs = await db.PartStockOuts.Where(s => s.OrgId == t.OrgId && s.Status == "3"
            && (warehouse == null || s.WarehouseCode == warehouse))
        .Select(s => new { s.Id, s.StockOutDate }).ToListAsync();
    // Đúng nguồn: mốc trên so với 00:00 của ngày kết thúc ⇒ loại phiếu trong ngày cuối sau 0 giờ.
    var okIds = outs.Where(s => s.StockOutDate >= f && s.StockOutDate <= to)
        .Select(s => s.Id).ToHashSet();
    var excludedOnEndDate = outs.Count(s => s.StockOutDate.Date == to && s.StockOutDate > to);

    var lines = await db.PartStockOutLines
        .Where(l => l.OrgId == t.OrgId && okIds.Contains(l.StockOutId)).ToListAsync();

    var partNames = (await db.ServiceParts.Where(p => p.OrgId == t.OrgId)
        .Select(p => new { p.PartCode, p.PartName, p.Unit }).ToListAsync())
        .GroupBy(p => p.PartCode).ToDictionary(g => g.Key, g => g.First());

    // Amount = giá*SL + giá*SL*VAT/100 (VAT là PHẦN TRĂM). AmountNoVat của nguồn là cột CHẾT.
    var grouped = lines.GroupBy(l => l.PartCode).Select(g => new
    {
        partCode = g.Key,
        partName = partNames.TryGetValue(g.Key, out var pn) ? pn.PartName : null,
        unit = partNames.TryGetValue(g.Key, out var pu) ? pu.Unit : null,
        amountFinal = g.Sum(l => (l.Price ?? 0) * l.Quantity
                               + (l.Price ?? 0) * l.Quantity * (l.Vat ?? 0) / 100m),
        lineCount = g.Count(),
    }).Where(x => x.amountFinal > 0).ToList();

    var notInMaster = grouped.Where(x => x.partName == null).Select(x => x.partCode).ToList();

    // 📌 CỐ Ý LỆCH: sắp giảm dần rồi mới cắt N. Nguồn KHÔNG sắp ⇒ trả N dòng bất kỳ.
    var n = top ?? 0;
    var ordered = grouped.OrderByDescending(x => x.amountFinal).ToList();
    var rows = n > 0 ? ordered.Take(n).ToList() : ordered;   // ô trống ⇒ nguồn trả TOÀN BỘ

    return Results.Ok(new
    {
        count = rows.Count, fromDate = f, toDate = to, top = n > 0 ? n : (int?)null,
        grandTotal = rows.Sum(x => x.amountFinal),
        sourceHasNoOrderBy = true,
        orderByNote = "Câu lấy TOP của nguồn KHÔNG có ORDER BY (hai ORDER BY phía trước nằm trên "
            + "SELECT INTO nên vô nghĩa) ⇒ WinForm trả N dòng BẤT KỲ, không phải N dòng doanh thu cao "
            + "nhất. MiniHTC CỐ Ý sắp giảm dần rồi mới cắt — số hai bên có thể KHÁC nhau.",
        emptyTopReturnsAllNote = "Ô Top để trống ⇒ nguồn sinh \"select  * from …\" ⇒ trả TOÀN BỘ, "
            + "không giới hạn. MiniHTC giữ đúng: không truyền top thì trả hết.",
        sqlInjectionNote = "Nguồn ghép \"Top \" + nội dung ô nhập rồi Replace thẳng vào SQL — không kiểm "
            + "số, không tham số hoá.",
        endDateExclusive = true,
        endDateNote = "Nguồn so StockOutTime <= 'yyyy-MM-dd' (ngầm 00:00:00) ⇒ phiếu xuất trong NGÀY "
            + "CUỐI sau 0 giờ bị loại — lệch một ngày, im lặng.",
        excludedOnEndDate,
        statusNote = "Lọc sto.Status = 3 — trạng thái bằng SỐ, khác các bảng dùng mã chữ cùng hệ.",
        deadColumnNote = "Nguồn tính AmountNoVat ở bảng tạm rồi không bao giờ dùng.",
        notInMaster,
        notInMasterNote = notInMaster.Count > 0
            ? "Mã phụ tùng không có trong danh mục: nguồn left join rồi group by cột của danh mục ⇒ các mã "
              + "này bị GOM CHUNG vào một nhóm NULL (không mất dòng, nhưng trộn nhiều mã làm một)."
            : null,
        zeroExcludedNote = "where AmountFinal > 0 ⇒ phụ tùng doanh thu 0 hoặc ÂM (trả hàng) không xuất hiện.",
        rows,
    });
}).RequireAuthorization();

app.MapGet("/api/report/customer-to-htc", async (AppDbContext db, ITenantContext t,
    DateTime? fromDate, DateTime? toDate, string? tradeMark, string? dealer) =>
{
    var f = (fromDate ?? DateTime.Today.AddMonths(-1)).Date;
    var to = (toDate ?? DateTime.Today).Date;

    var cars = await db.ServiceCars.Where(c => c.OrgId == t.OrgId
            && (dealer == null || c.DealerCode == dealer)).ToListAsync();
    var ros = await db.RepairOrders.Where(r => r.OrgId == t.OrgId).ToListAsync();
    var customers = await db.ServiceCustomers.Where(c => c.OrgId == t.OrgId).ToListAsync();
    var models = await db.ServiceModels.Where(m => m.OrgId == t.OrgId).ToListAsync();
    var marks = await db.ServiceTradeMarks.Where(m => m.OrgId == t.OrgId).ToListAsync();

    var cusBy = customers.GroupBy(c => c.CusCode).ToDictionary(g => g.Key, g => g.First());
    var mdlBy = models.GroupBy(m => m.ModelCode).ToDictionary(g => g.Key, g => g.First());
    var markBy = marks.GroupBy(m => m.TradeMarkCode).ToDictionary(g => g.Key, g => g.First());

    // Bộ lọc hãng: LIKE HAI ĐẦU, không so bằng (tầng service dựng "like %x%").
    var tmLike = (tradeMark ?? "").Trim();
    var rows = new List<object>();
    int droppedNoRO = 0, droppedNoTradeMark = 0, droppedByStatus = 0;

    foreach (var car in cars)
    {
        // LEFT JOIN ser_ro — nhưng WHERE bên dưới sẽ huỷ tính chất LEFT.
        var carROs = ros.Where(r => r.CarID != null && r.CarID == car.CarID
                                 && r.DealerCode == car.DealerCode).ToList();
        if (carROs.Count == 0) { droppedNoRO++; continue; }   // ro.ROID is not null

        foreach (var ro in carROs)
        {
            if (ro.Status != "PAID" && ro.Status != "FNS") { droppedByStatus++; continue; }
            if (ro.CheckInDate == null) { droppedByStatus++; continue; }
            var d = ro.CheckInDate.Value.Date;
            if (d < f || d > to) continue;                     // datediff(day,…) >= 0 hai chiều

            if (tmLike.Length > 0 &&
                !(car.TradeMark ?? "").Contains(tmLike, StringComparison.OrdinalIgnoreCase)) continue;

            // 🔴 Nối TRONG với danh mục hãng: không có trong danh mục ⇒ MẤT DÒNG.
            if (car.TradeMark == null || !markBy.TryGetValue(car.TradeMark, out var mark))
            { droppedNoTradeMark++; continue; }

            cusBy.TryGetValue(car.CusID ?? "", out var cus);
            mdlBy.TryGetValue(car.ModelCode ?? "", out var mdl);

            rows.Add(new
            {
                CusName = cus?.CusName,
                Address = cus?.Address,
                Phone = cus?.Tel ?? cus?.Mobile,        // isnull(tel, mobile)
                CarID = car.CarID,
                PlateNo = car.PlateNo,
                FrameNo = car.FrameNo,
                // Cột này CHỈ có ở nhánh "có lọc hãng" của nguồn — xem shapeNote.
                TradeMarkName = tmLike.Length > 0 ? mark.TradeMarkName : null,
                TradeMarkNameModel = mark.TradeMarkName + " - " + (mdl?.ModelName ?? ""),
                RONo = "LS-" + ro.RONo,                 // tiền tố cứng của nguồn
                CheckInDate = ro.CheckInDate,
                CusRequest = ro.CusRequest,
                CusAddress = ro.CusAddress,
            });
        }
    }
    rows = rows.OrderBy(r => (string?)r.GetType().GetProperty("CusName")!.GetValue(r)).ToList();

    return Results.Ok(new
    {
        count = rows.Count, fromDate = f, toDate = to,
        tradeMarkFilter = tmLike.Length > 0 ? "like %" + tmLike + "%" : null,
        shapeNote = "Nguồn có HAI nhánh SQL gần như giống hệt; khác biệt DUY NHẤT là nhánh CÓ lọc hãng "
            + "chọn thêm cột TradeMarkName. Điều kiện rẽ nhánh KHÔNG đổi bộ lọc (mệnh đề lọc nằm ở cả hai "
            + "nhánh) ⇒ hình dạng kết quả đổi theo việc người dùng có tick ô hãng hay không.",
        droppedNoRO, droppedByStatus, droppedNoTradeMark,
        deadLeftJoinNote = "Ba `left join` của nguồn thực chất là INNER: các bảng danh mục nối theo "
            + "ro.DealerCode (NULL khi xe chưa có lệnh sửa), ser_mst_TradeMark nối TRONG, và WHERE còn "
            + "co ro.ROID is not null + ro.Status thuoc PAID/FNS. Xe chua tung vao xuong KHONG bao gio "
            + "xuất hiện, dù đọc SQL thì tưởng có.",
        droppedNoTradeMarkNote = droppedNoTradeMark > 0
            ? "Xe mang mã hãng KHÔNG có trong danh mục ser_mst_TradeMark bị loại hẳn (nối TRONG)."
            : null,
        nameNote = "Hàm tên Ser_Count_Customer_ToHTC nhưng KHÔNG đếm gì — trả danh sách chi tiết.",
        dateRangeNote = "Mốc ngày so theo NGÀY, bao gồm cả hai đầu (datediff(day,…) >= 0 hai chiều).",
        bakedParamNote = "Nguồn nhúng thẳng @DealerCode/@FromDate/@ToDate vào chuỗi SQL "
            + "(StringUtils.Replace), không dùng tham số — cùng bề mặt tiêm SQL như #413.",
        columnNameMapNote = "MiniHTC: ServiceCar.TradeMark (nguồn TradeMarkCode), ModelCode (nguồn "
            + "ModelID), ServiceCustomer.CusCode (nguồn CusID) — ánh xạ theo ý nghĩa.",
        rows,
    });
}).RequireAuthorization();

app.MapGet("/api/report/receivable-debit", async (AppDbContext db, ITenantContext t, DateTime? toDate,
    string? scope) =>
{
    var cut = (toDate ?? DateTime.Today).Date;

    // (1) nợ + thu theo KHÁCH HÀNG
    var cusDebits = await db.CusDebits.Where(x => x.OrgId == t.OrgId)
        .Where(x => x.DebitDate == null || x.DebitDate.Value.Date <= cut)
        .GroupBy(x => new { x.CusId, x.CusName })
        .Select(g => new { g.Key.CusId, g.Key.CusName, Debit = g.Sum(x => x.DebitAmount), Paid = g.Sum(x => x.PaidAmount) })
        .ToListAsync();

    // (2) nợ + thu theo HÃNG BẢO HIỂM
    var insDebits = await db.InsDebits.Where(x => x.OrgId == t.OrgId)
        .Where(x => x.DebitDate == null || x.DebitDate.Value.Date <= cut)
        .GroupBy(x => new { x.InsNo, x.InsName })
        .Select(g => new { g.Key.InsNo, g.Key.InsName, Debit = g.Sum(x => x.DebitAmount), Paid = g.Sum(x => x.PaidAmount) })
        .ToListAsync();

    var insRows = insDebits
        .Select(x => new { itemCode = x.InsNo, itemName = x.InsName, remark = "Bảo hiểm nợ", debitAmount = x.Debit - x.Paid })
        .Where(r => r.debitAmount != 0).ToList();
    var cusRows = cusDebits
        .Select(x => new { itemCode = x.CusId, itemName = x.CusName, remark = "Khách hàng nợ", debitAmount = x.Debit - x.Paid })
        .Where(r => r.debitAmount != 0).ToList();

    // union all giữa hai nhánh — đúng nguồn (không khử trùng).
    var rows = insRows.Concat(cusRows).OrderByDescending(r => r.debitAmount).ToList();

    return Results.Ok(new
    {
        toDate = cut,
        totalInsurance = insRows.Sum(r => r.debitAmount),
        totalCustomer = cusRows.Sum(r => r.debitAmount),
        grandTotal = rows.Sum(r => r.debitAmount),
        count = rows.Count,
        rows,
        legacyRows = (object?)null,
        // #413 nhánh thứ ba chỉ có ở bản Main; bản _WH thiếu hẳn.
        scope = string.Equals(scope, "wh", StringComparison.OrdinalIgnoreCase) ? "wh" : "main",
        legacyBranchInSource = !string.Equals(scope, "wh", StringComparison.OrdinalIgnoreCase),
        whDivergenceNote = "Bản _WH của nguồn (WH.cs:10764) THIẾU HẲN nhánh union "
            + "BaoCoCongNoKhachHang_20170101 mà bản Main (Service.Report.cs:2605) có ⇒ cùng đại lý, cùng "
            + "mốc ngày, hai màn cho HAI TỔNG NỢ khác nhau, không cảnh báo gì.",
        legacyTableFrozenNote = "Tên bảng đóng băng theo ngày (_20170101): một bảng chốt 2017 nằm cứng "
            + "trong báo cáo đang chạy.",
        bakedDealerCodeNote = "Nguồn nhúng thẳng mã đại lý vào chuỗi SQL (StringUtils.Replace), không "
            + "dùng tham số — bề mặt tiêm SQL và là kiểu trộn nháy/tham số đã từng gây guard chết câm.",
        note = "Nguồn còn union bảng chốt lịch sử BaoCoCongNoKhachHang_20170101 (DB CommonCenter) — MiniHTC chưa có bảng này, KHÔNG bịa dữ liệu."
    });
}).RequireAuthorization();

// Báo cáo tổng công nợ khách hàng: đầu kỳ 0, phát sinh tăng = tổng nợ, phát sinh giảm = tổng thu, cuối kỳ = dư nợ.
app.MapGet("/api/report/cusdebit-total", async (AppDbContext db, ITenantContext t) =>
{
    var rows = await db.CusDebits.Where(x => x.OrgId == t.OrgId)
        .GroupBy(x => new { x.CusId, x.CusName })
        .Select(g => new { code = g.Key.CusId, name = g.Key.CusName, increase = g.Sum(x => x.DebitAmount), decrease = g.Sum(x => x.PaidAmount), closing = g.Sum(x => x.DebitAmount - x.PaidAmount), count = g.Count() })
        .OrderByDescending(r => r.closing).ToListAsync();
    return Results.Ok(new { totalIncrease = rows.Sum(r => r.increase), totalDecrease = rows.Sum(r => r.decrease), totalClosing = rows.Sum(r => r.closing), rows });
}).RequireAuthorization();

// Báo cáo lịch sử thu tiền dịch vụ: gộp thu tiền khách hàng + bảo hiểm theo ngày.
app.MapGet("/api/report/service-payments", async (AppDbContext db, ITenantContext t, DateTime? fromDate, DateTime? toDate) =>
{
    var cusPay = await (from p in db.CusDebitPayments.Where(x => x.OrgId == t.OrgId)
                        join h in db.CusDebits.Where(x => x.OrgId == t.OrgId) on p.CusDebitId equals h.Id
                        select new { p.PaymentAmount, p.PayDate, debitNo = h.DebitNo, payer = h.CusName, payerType = "Customer", p.Note }).ToListAsync();
    var insPay = await (from p in db.InsDebitPayments.Where(x => x.OrgId == t.OrgId)
                        join h in db.InsDebits.Where(x => x.OrgId == t.OrgId) on p.InsDebitId equals h.Id
                        select new { p.PaymentAmount, p.PayDate, debitNo = h.DebitNo, payer = h.InsName, payerType = "Insurance", p.Note }).ToListAsync();
    var all = cusPay.Concat(insPay);
    if (fromDate.HasValue) all = all.Where(x => x.PayDate.HasValue && x.PayDate.Value.Date >= fromDate.Value.Date);
    if (toDate.HasValue) all = all.Where(x => x.PayDate.HasValue && x.PayDate.Value.Date <= toDate.Value.Date);
    var rows = all.OrderByDescending(x => x.PayDate).Select(x => new { x.debitNo, x.payer, x.payerType, x.PaymentAmount, payDate = x.PayDate.HasValue ? x.PayDate.Value.ToString("yyyy-MM-dd") : "", x.Note }).ToList();
    return Results.Ok(new { count = rows.Count, total = rows.Sum(r => r.PaymentAmount), rows });
}).RequireAuthorization();

// ===== 🔴 #272 XẾP HÀNG ĐẨY NO-SHOW SANG HCC =====
// Nguồn: phần "Call HCC" của `HCC_NoShow_CreateOSX` (`BizCarSv.HCC.cs:704-763`, **chỉ có trên máy 150**).
//
// 🔴 TÀI KHOẢN ĐĂNG NHẬP HCC LÀ TÀI KHOẢN NỀN, KHÔNG PHẢI NGƯỜI DÙNG:
//   `HCCService.Login(url, GwUserCode, GwPassword, tid, **_strOS_HCC_BG_WAUserCode**, **…BG_WAUserPassword**)`
//   — khác hẳn `CommonSignIn2026NC` (truyền chính mật khẩu người đăng nhập). Job chạy không có người dùng
//   nào ngồi đó, nên phải dùng tài khoản riêng; đăng nhập hỏng ⇒ ném `..._HCCLoginFail`.
//
// 🔴 `AppAgent = "BizSkodaService"` — chuỗi CỐ ĐỊNH, và nó ghi **Skoda** trong hệ TCMotor/Hyundai.
//   Dấu vết copy từ bản dựng của hãng khác. Giữ nguyên văn khi đối soát log phía HCC, đừng "sửa cho đúng".
//   Cùng khối: `UtcOffset = "7"`, `Authorization = "Bearer " + AccessToken`.
//
// ☠️ KẾT QUẢ ĐẨY KHÔNG ĐƯỢC KIỂM: cả khối kiểm `objCMyMsgResult` và lệnh `throw` đều **bị comment**
//   ⇒ HCC trả lỗi thì job vẫn coi như xong, **hỏng âm thầm**. (Lệnh throw bị comment đó còn dùng NHẦM hằng
//   lỗi của hàm khác: `HCC_Appointment_AddOSX_InvalidOutSite` nằm trong `HCC_NoShow_CreateOSX`.)
//   ⇒ Port **KHÔNG bắt chước chỗ hỏng âm thầm**: có trục trạng thái "R" + ghi chú lỗi. Sai lệch CỐ Ý.
//
// 🔴 Nguồn đẩy **THEO TỪNG ĐẠI LÝ** (vòng lặp `dt_Mst_Dealer`) ⇒ nhật ký cũng một dòng / một đại lý.
app.MapPost("/api/hcc/noshow/queue", async (AppDbContext db, ITenantContext t, string? dealer, int? months) =>
{
    var m = months ?? 6;
    if (m != 6 && m != 12)
        return Results.BadRequest(new { error = "months chỉ nhận 6 hoặc 12 (nguồn chỉ định nghĩa hai mốc)." });

    var now = DateTime.Now;
    var noShowType = m == 6 ? "6Month" : "12Month";
    var fromDate = now.AddMonths(m == 6 ? -12 : -24).Date;
    var toDate = now.AddMonths(m == 6 ? -6 : -12).Date.AddDays(1).AddSeconds(-1);

    var dealers = db.Dealers.Where(d => d.OrgId == t.OrgId && d.OrgHCCID != null);
    if (!string.IsNullOrWhiteSpace(dealer)) dealers = dealers.Where(d => d.DealerCode == dealer!.Trim().ToUpperInvariant());
    var dealerList = await dealers.ToListAsync();

    var created = new List<HccNoShowPush>();
    foreach (var d in dealerList)
    {
        var count = await (from car in db.ServiceCars
                           join cus in db.ServiceCustomers on car.CusID equals cus.CusCode
                           where car.OrgId == t.OrgId && cus.OrgId == t.OrgId
                                 && car.CurrentServiceDate > fromDate && car.CurrentServiceDate <= toDate
                                 && cus.DealerCode == d.DealerCode && cus.FlagActive == "1"
                           select car.Id).CountAsync();

        // Danh sách rỗng ⇒ nguồn KHÔNG gọi HCC (guard `strOrgID` vẫn null). Không tạo dòng nhật ký.
        if (count == 0) continue;

        var row = new HccNoShowPush
        {
            OrgId = t.OrgId, NoShowType = noShowType, DealerCode = d.DealerCode,
            WindowFrom = fromDate, WindowTo = toDate, CandidateCount = count, PushStatus = "P",
        };
        db.HccNoShowPushes.Add(row); created.Add(row);
    }
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        noShowType,
        from = fromDate.ToString("yyyy-MM-dd HH:mm:ss"), to = toDate.ToString("yyyy-MM-dd HH:mm:ss"),
        dealersScanned = dealerList.Count, queued = created.Count,
        skippedEmpty = dealerList.Count - created.Count,
        items = created.Select(x => new { x.Id, x.DealerCode, x.CandidateCount, x.PushStatus }),
    });
}).RequireAuthorization();

// #272 Đọc nhật ký đẩy NoShow.
app.MapGet("/api/hcc/noshow/pushes", async (AppDbContext db, ITenantContext t, string? dealer, string? status) =>
{
    var qy = db.HccNoShowPushes.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) qy = qy.Where(x => x.DealerCode == dealer!.Trim().ToUpperInvariant());
    if (!string.IsNullOrWhiteSpace(status)) qy = qy.Where(x => x.PushStatus == status);
    var items = await qy.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.Id, x.NoShowType, x.DealerCode, x.CandidateCount, x.PushStatus, x.PushNote,
        windowFrom = x.WindowFrom.ToString("yyyy-MM-dd HH:mm:ss"),
        windowTo = x.WindowTo.ToString("yyyy-MM-dd HH:mm:ss"),
        pushDateTime = x.PushDateTime.HasValue ? x.PushDateTime.Value.ToString("yyyy-MM-dd HH:mm:ss") : null,
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// #272 Ghi kết quả đẩy (bộ đẩy gọi lại). Nguồn BỎ QUA kết quả (khối kiểm bị comment) — port ghi lại.
app.MapPost("/api/hcc/noshow/pushes/{id}/result", async (long id, HccNoShowResultDto dto, AppDbContext db, ITenantContext t) =>
{
    var row = await db.HccNoShowPushes.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (row is null) return Results.NotFound(new { id });
    var to = (dto.ToStatus ?? "").Trim().ToUpperInvariant();
    if (to != "A" && to != "R") return Results.BadRequest(new { error = "ToStatus chỉ nhận A (thành công) hoặc R (lỗi)." });
    if (to == "R" && string.IsNullOrWhiteSpace(dto.Note))
        return Results.BadRequest(new { error = "Đẩy lỗi phải ghi lý do (nguồn nuốt lỗi, port thì không)." });
    row.PushStatus = to; row.PushDateTime = DateTime.Now; row.PushNote = dto.Note;
    await db.SaveChangesAsync();
    return Results.Ok(new { row.Id, row.PushStatus, row.PushDateTime, row.PushNote });
}).RequireAuthorization();

// ===== 🔴 #290 CẤU HÌNH GỬI EMAIL TỰ ĐỘNG — `Email_ConfigSendAuto` =====
// Nguồn: `BizCarSv.SendMail.cs:1124 Email_ConfigSendAuto_Create`. Năm `[WebMethod]` sống
//   (Create · Update · Delete · Get · Cancel — `WSCarSv.asmx.cs:21500-21827`).
// 🆕 Tìm ra từ hàng đợi #289 (cột `typeemail` có 2 bộ nhãn ⇒ có màn chưa port).
//
// 🔴 HAI BỘ NHÃN cho cùng cột `TypeEmail` (luật nhãn-theo-màn #286):
//   • Màn CẤU HÌNH (`SendMail.cs:1301`): 7 mã `1..7`, mã `3` = **"Mừng sinh nhật"**.
//   • Màn LỊCH SỬ GỬI (`SendMail.cs:4635`): thêm mã **`0` với nhãn RỖNG** (`then N''`), và mã `3` đổi
//     thành **"Chúc mừng SN"** (viết tắt cho vừa cột lưới).
//   ⚠️ Nhãn RỖNG **KHÁC** NULL: mã `0` **có** nhánh, trả về chuỗi rỗng — nghĩa là "chưa phân loại",
//     một giá trị hợp lệ. Bỏ nhánh này thì mã `0` rơi vào NULL và lẫn với mã lạ.
var emailTypeNamesByScreen = new Dictionary<string, Dictionary<string, string>>
{
    // Màn CẤU HÌNH gửi tự động.
    ["config"] = new()
    {
        ["1"] = "Thông báo chiến dịch", ["2"] = "Nhắc bảo dưỡng", ["3"] = "Mừng sinh nhật",
        ["4"] = "Hẹn khách hàng", ["5"] = "Khuyến mại", ["6"] = "Thông báo sửa xong", ["7"] = "Khác",
    },
    // Màn LỊCH SỬ GỬI — có thêm mã 0 (nhãn RỖNG) và viết tắt mã 3.
    ["history"] = new()
    {
        ["0"] = "", ["1"] = "Thông báo chiến dịch", ["2"] = "Nhắc bảo dưỡng", ["3"] = "Chúc mừng SN",
        ["4"] = "Hẹn khách hàng", ["5"] = "Khuyến mại", ["6"] = "Thông báo sửa xong", ["7"] = "Khác",
    },
};

// SENDMODE — quyết định ý nghĩa của AutoDate / AutoDay.
var emailSendModeNames = new Dictionary<string, string>
{
    ["1"] = "Gửi một lần", ["2"] = "Gửi hàng ngày", ["3"] = "Gửi hàng tuần",
};

// ===== 🔴 #433 CẤU HÌNH MÁY CHỦ THƯ (`Email_Config`) — **KHÁC** `Email_ConfigSendAuto` của #290 =====
// Nguồn: `Views/SendEmail/FrmEmail_ConfigCreate.cs` (238 dòng) → `EmailSendEmailService`
//   `Email_Config_Get / _Create / _Update`.
// ⚠️ Hai bảng tên gần giống nhau: `Email_ConfigSendAuto` (#290) là **lịch gửi tự động**;
//   `Email_Config` là **thông số SMTP**. Grep theo "Email_Config" trúng cả hai — dễ tưởng đã port.
//
// 🔴 **ĐỌC CÓ LỌC ĐẠI LÝ, GHI THÌ KHÔNG**:
//     `db.Email_Config_Get(**SystemGlobal.strDealerCode**, strID_config, …)  //20121010 huongkt`
//     `db.Email_Config_Create(**""**, strPort, strTimeOut, …)`   ← tham số đầu để **RỖNG**
//   Chú thích `20121010` cho thấy phạm vi theo đại lý được thêm vào **đường ĐỌC** mà **quên đường GHI**.
//   ⇒ Cấu hình vừa tạo **không mang mã đại lý** nên chính màn đó **đọc lại không thấy**; người dùng bấm
//     Tạo thành công rồi mở lại thấy trống, và bấm Tạo tiếp ⇒ **sinh ra nhiều bản ghi mồ côi**.
//   📌 MiniHTC **CỐ Ý LỆCH**: ghi kèm `dealerCode` để đọc-ghi cùng phạm vi, và trả cờ `dealerScopeFixed`.
//
// 🔴 **MẬT KHẨU SMTP LƯU NGUYÊN VĂN**: form lấy `txtmailServerPassword.Text.Trim()` rồi truyền thẳng
//   xuống, không băm, không mã hoá. Ô nhập chỉ đổi `PasswordChar` **sau khi lưu xong** — tức lúc gõ vẫn
//   hiện rõ. Đây là dữ liệu nhạy cảm, ghi vào log để bên nghiệp vụ quyết cách xử lý.
//
// ⚠️ `EnableSSL` lưu chuỗi `"True"`/`"False"` (từ `Convert.ToString(chk.Checked)`), **không** theo quy ước
//   cờ `"1"`/`"0"` của hệ; lúc đọc lại nguồn so `== "False"` ⇒ **mọi giá trị khác "False" đều thành bật**.
// ⚠️ Guard của form (`ValidateInput`) bắt buộc **năm** ô: địa chỉ máy chủ · TimeOut · Port · Mật khẩu · User.
//   ⚠️ **KHÔNG** kiểm Port/TimeOut có phải số hay không ⇒ nhập chữ vẫn lưu được.
// ⚠️ Nhánh tạo và nhánh sửa **hỏi xác nhận bằng hai thông điệp khác nhau** rồi mới gọi; sau khi tạo,
//   form tự chuyển sang chế độ sửa (`b_isUpdate = true`) và giữ `IdConfig` vừa nhận.
app.MapGet("/api/emailserverconfigs", async (AppDbContext db, ITenantContext t, string? dealer) =>
{
    var qy = db.EmailServerConfigs.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) qy = qy.Where(x => x.DealerCode == dealer!.Trim());
    var items = await qy.OrderBy(x => x.Id).Select(x => new
    {
        x.IdConfig, x.DealerCode, x.MailServerAddress, x.MailServerUser,
        x.Port, x.TimeOut, x.EnableSSL,
        // Không trả mật khẩu ra danh sách; chỉ báo đã đặt hay chưa.
        hasPassword = !string.IsNullOrEmpty(x.MailServerPassword),
    }).ToListAsync();
    return Results.Ok(new
    {
        count = items.Count, items,
        passwordNote = "Nguồn lưu mật khẩu SMTP NGUYÊN VĂN. Endpoint này KHÔNG trả mật khẩu ra danh sách "
            + "(chỉ báo hasPassword) — cố ý khác nguồn, vì trả ra là phát tán thêm.",
    });
}).RequireAuthorization();

app.MapPost("/api/emailserverconfigs", async (EmailServerConfigDto dto, AppDbContext db, ITenantContext t) =>
{
    // Guard của form: NĂM ô bắt buộc, đúng thứ tự báo lỗi của nguồn.
    if (string.IsNullOrWhiteSpace(dto.MailServerAddress))
        return Results.BadRequest(new { error = "Chưa nhập Địa chỉ mail server" });
    if (string.IsNullOrWhiteSpace(dto.TimeOut))
        return Results.BadRequest(new { error = "Chưa nhập TimeOut" });
    if (string.IsNullOrWhiteSpace(dto.Port))
        return Results.BadRequest(new { error = "Chưa nhập Port" });
    if (string.IsNullOrWhiteSpace(dto.MailServerPassword))
        return Results.BadRequest(new { error = "Chưa nhập Mật khẩu" });
    if (string.IsNullOrWhiteSpace(dto.MailServerUser))
        return Results.BadRequest(new { error = "Chưa nhập User" });

    // Nguồn KHÔNG kiểm Port/TimeOut là số — giữ 1:1, chỉ BÁO CỜ.
    var portNotNumeric = !int.TryParse(dto.Port!.Trim(), out _);
    var timeOutNotNumeric = !int.TryParse(dto.TimeOut!.Trim(), out _);

    var id = "EC" + DateTime.Now.ToString("yyMMddHHmmss");
    var r = new EmailServerConfig
    {
        OrgId = t.OrgId, IdConfig = id,
        // 🔴 CỐ Ý LỆCH: nguồn truyền chuỗi rỗng ở đây nên bản ghi không đọc lại được.
        DealerCode = dto.DealerCode?.Trim(),
        MailServerAddress = dto.MailServerAddress!.Trim(),
        MailServerUser = dto.MailServerUser!.Trim(),
        MailServerPassword = dto.MailServerPassword!.Trim(),
        Port = dto.Port!.Trim(), TimeOut = dto.TimeOut!.Trim(),
        // Nguồn lưu chuỗi "True"/"False", không phải "1"/"0".
        EnableSSL = (dto.EnableSSL ?? false) ? "True" : "False",
    };
    db.EmailServerConfigs.Add(r);
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        r.IdConfig, r.DealerCode, message = "Đã thêm mới thành công",
        dealerScopeFixed = true,
        dealerScopeNote = "Nguồn gọi Email_Config_Create(\"\", …) — bỏ TRỐNG mã đại lý, trong khi "
            + "Email_Config_Get lại LỌC theo mã đại lý (thêm 2012) ⇒ bản ghi vừa tạo không đọc lại được, "
            + "bấm Tạo nhiều lần sinh ra bản ghi mồ côi. MiniHTC ghi kèm dealerCode để đọc-ghi cùng phạm vi.",
        portNotNumeric, timeOutNotNumeric,
        numericNote = (portNotNumeric || timeOutNotNumeric)
            ? "Port hoặc TimeOut KHÔNG phải số. Nguồn không kiểm nên vẫn lưu — giữ 1:1, chỉ báo cờ."
            : null,
        enableSslNote = "Lưu chuỗi \"True\"/\"False\" theo nguồn (không phải \"1\"/\"0\"); nguồn đọc lại "
            + "chỉ so == \"False\" ⇒ mọi giá trị khác đều hiểu là BẬT.",
        passwordPlainNote = "Nguồn lưu mật khẩu SMTP NGUYÊN VĂN, không băm không mã hoá — ghi lại để "
            + "bên nghiệp vụ quyết cách xử lý.",
    });
}).RequireAuthorization();

app.MapPut("/api/emailserverconfigs/{idConfig}", async (string idConfig, EmailServerConfigDto dto,
    AppDbContext db, ITenantContext t) =>
{
    var r = await db.EmailServerConfigs.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.IdConfig == idConfig);
    if (r is null) return Results.NotFound(new { idConfig });
    // Nguồn dùng CHUNG hàm ValidateInput cho cả tạo lẫn sửa ⇒ năm ô vẫn bắt buộc.
    if (string.IsNullOrWhiteSpace(dto.MailServerAddress) || string.IsNullOrWhiteSpace(dto.TimeOut)
        || string.IsNullOrWhiteSpace(dto.Port) || string.IsNullOrWhiteSpace(dto.MailServerPassword)
        || string.IsNullOrWhiteSpace(dto.MailServerUser))
        return Results.BadRequest(new { error = "Thiếu một trong năm trường bắt buộc (địa chỉ, TimeOut, Port, mật khẩu, user)." });

    r.MailServerAddress = dto.MailServerAddress!.Trim();
    r.MailServerUser = dto.MailServerUser!.Trim();
    r.MailServerPassword = dto.MailServerPassword!.Trim();
    r.Port = dto.Port!.Trim(); r.TimeOut = dto.TimeOut!.Trim();
    r.EnableSSL = (dto.EnableSSL ?? false) ? "True" : "False";
    if (!string.IsNullOrWhiteSpace(dto.DealerCode)) r.DealerCode = dto.DealerCode!.Trim();
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        r.IdConfig, r.DealerCode,
        sharedValidateNote = "Nguồn dùng CHUNG ValidateInput cho tạo và sửa (khác lệ #404 nơi hai thao "
            + "tác có guard khác nhau) — ở màn này hai bên GIỐNG nhau, đã kiểm.",
    });
}).RequireAuthorization();

app.MapGet("/api/emailconfigsendauto/vocab", (string? screen) =>
{
    var key = string.IsNullOrWhiteSpace(screen) ? "config" : screen!.Trim().ToLowerInvariant();
    if (!emailTypeNamesByScreen.TryGetValue(key, out var map))
        return Results.BadRequest(new { error = "screen phải là config | history.", screen = key });
    return Results.Ok(new
    {
        screen = key,
        typeEmail = map.Select(kv => new { code = kv.Key, name = kv.Value }),
        sendMode = emailSendModeNames.Select(kv => new { code = kv.Key, name = kv.Value }),
        isActive = new[] { new { code = "0", name = "Không kích hoạt" }, new { code = "1", name = "Kích hoạt" } },
        note = "Màn history có thêm mã 0 với nhãn RỖNG (\"chưa phân loại\") và viết tắt mã 3 = \"Chúc mừng SN\".",
    });
}).RequireAuthorization();

// ===== 🔴 #437 DANH SÁCH CẤU HÌNH GỬI TỰ ĐỘNG — **NẠP thì lọc đại lý, TÌM thì không** =====
// Nguồn: `Views/SendEmail/FrmAutoSendConfigList.cs` (396 dòng) → `Email_ConfigSendAuto_Get`.
// Hai lời gọi trong **cùng một form**, khác nhau đúng **tham số đầu tiên**:
//   · Lúc NẠP lưới:  `db.Email_ConfigSendAuto_Get(**SystemGlobal.strDealerCode**, "", "", "", …)`
//   · Lúc bấm TÌM:   `db.Email_ConfigSendAuto_Get(**""**, "", "", "", <ngày>, "", <chế độ gửi>, …)`
// ⇒ Mở màn thấy **đúng cấu hình của đại lý mình**; bấm Tìm một cái là **thấy cấu hình của MỌI đại lý**.
//   Không có thông báo nào; người dùng tưởng bộ lọc vừa nới ngày/chế độ, thực ra nó **nới cả phạm vi đại lý**.
//   Đây là rò phạm vi ngay **trong một màn**, khác #433 (rò giữa đường ĐỌC và đường GHI).
// 📌 MiniHTC **giữ tham số `dealer` cho mọi lần gọi** và trả cờ `dealerScopeLostOnSearchInSource` để
//   người dùng biết số liệu WinForm có thể rộng hơn.
//
// ⚠️ Hàm nhận **mười hai** tham số, form truyền **rỗng mười cái**; bản gọi cũ (bảy tham số) còn nằm
//   ngay trên dưới dạng comment ⇒ chữ ký đã đổi ít nhất một lần mà nơi gọi chỉ độn thêm `""`.
app.MapGet("/api/emailconfigsendauto", async (AppDbContext db, ITenantContext t,
    string? dealer, string? typeEmail, string? isActive, string? sendMode, DateTime? autoDate) =>
{
    var qy = db.EmailConfigSendAutos.Where(x => x.OrgId == t.OrgId);
    // #437 hai bộ lọc mà màn TÌM của nguồn có nhưng bản port cũ thiếu.
    if (!string.IsNullOrWhiteSpace(sendMode)) qy = qy.Where(x => x.SendMode == sendMode!.Trim());
    if (autoDate.HasValue) qy = qy.Where(x => x.ConfigDate != null && x.ConfigDate!.Value.Date == autoDate.Value.Date);
    if (!string.IsNullOrWhiteSpace(dealer)) qy = qy.Where(x => x.DealerCode == dealer!.Trim().ToUpperInvariant());
    if (!string.IsNullOrWhiteSpace(typeEmail)) qy = qy.Where(x => x.TypeEmail == typeEmail);
    if (!string.IsNullOrWhiteSpace(isActive)) qy = qy.Where(x => x.IsActive == isActive);
    var rows = await qy.OrderByDescending(x => x.Id).Take(500).ToListAsync();
    var cfg = emailTypeNamesByScreen["config"];
    var items = rows.Select(x => new
    {
        x.Id, x.DealerCode, x.AutoTime, x.StartDate, x.EndDate, x.Description,
        x.SendMode,
        sendModeName = x.SendMode is not null && emailSendModeNames.TryGetValue(x.SendMode, out var sm) ? sm : null,
        x.IsActive, x.TypeEmail,
        // #437 cờ cảnh báo rò phạm vi đại lý ở màn nguồn.
        dealerScopeLostOnSearchInSource = true,
        typeEmailName = x.TypeEmail is not null && cfg.TryGetValue(x.TypeEmail, out var te) ? te : null,
        x.ConfigDate, x.AutoDate, x.AutoDay,
    }).ToList();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/emailconfigsendauto", async (EmailConfigSendAutoDto dto, AppDbContext db, ITenantContext t) =>
{
    var mode = (dto.SendMode ?? "").Trim();
    if (mode.Length > 0 && !emailSendModeNames.ContainsKey(mode))
        return Results.BadRequest(new { error = "SendMode phải là 1 (một lần) | 2 (hàng ngày) | 3 (hàng tuần)." });
    var type = (dto.TypeEmail ?? "").Trim();
    if (type.Length > 0 && !emailTypeNamesByScreen["history"].ContainsKey(type))
        return Results.BadRequest(new { error = "TypeEmail phải nằm trong 0..7 (0 = chưa phân loại)." });

    var row = new EmailConfigSendAuto
    {
        OrgId = t.OrgId, DealerCode = dto.DealerCode?.Trim().ToUpperInvariant(),
        AutoTime = dto.AutoTime, StartDate = dto.StartDate, EndDate = dto.EndDate,
        Description = dto.Description, SendMode = mode.Length == 0 ? null : mode,
        IsActive = string.IsNullOrWhiteSpace(dto.IsActive) ? "1" : dto.IsActive!.Trim(),
        TypeEmail = type.Length == 0 ? null : type,
        ConfigDate = dto.ConfigDate ?? DateTime.Now,
        AutoDate = dto.AutoDate, AutoDay = dto.AutoDay,
    };
    db.EmailConfigSendAutos.Add(row); await db.SaveChangesAsync();
    return Results.Ok(new { row.Id, row.SendMode, row.TypeEmail, row.IsActive });
}).RequireAuthorization();

// Nguồn có `Email_ConfigSendAuto_Cancel` RIÊNG, tách khỏi `_Delete` ⇒ huỷ = **tắt cờ**, không xoá bản ghi.
app.MapPost("/api/emailconfigsendauto/{id:long}/cancel", async (long id, AppDbContext db, ITenantContext t) =>
{
    var row = await db.EmailConfigSendAutos.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (row is null) return Results.NotFound(new { id });
    row.IsActive = "0";
    await db.SaveChangesAsync();
    return Results.Ok(new { row.Id, row.IsActive, note = "Nguồn tách Cancel khỏi Delete ⇒ huỷ là TẮT CỜ, không xoá." });
}).RequireAuthorization();

// ===== 🔴 #287 ĐƠN ĐẶT PHỤ TÙNG GỬI NHÀ CUNG CẤP — `Ser_Part_Order` =====
// ⚠️ **KHÁC HẲN** `Ser_Order_Part` (đơn TST, đã port thành `OrderPart` ở #234): hai bảng tên **đảo chữ**
//   của nhau, khác bộ mã trạng thái, khác nghiệp vụ. BƯỚC 2 xác nhận MiniHTC chưa có bảng này.
//
// ✅ TRACE TWIN — bốn bản `Ser_Part_OrderGet*`: `_old` (:1608) · bản trần (:1886) · **`_StatusList01` (:2169)**
//   · `_StatusList` (:2466). WS `WSCarSv.asmx.cs:23686` gọi **`_StatusList`** ⇒ ba bản kia CHẾT.
//   ⚠️ Bẫy: `_StatusList01` **trông mới hơn** (có hậu tố `01`) và có bộ mã CHỮ đầy đủ
//   (`CREA/CONF/REJ/FINS/CANC`) — nhưng **KHÔNG được gọi**. Port theo nó là port bộ mã không tồn tại.
//
// 🔴 BỘ MÃ TRỘN SỐ + CHỮ trong CÙNG MỘT CỘT (`PartOrder.cs:2614-2623`, bản LIVE):
//     `'1'` → "Mới tạo" · **`'CONF'`** → "Xác nhận" · `'2'` → "Hàng đang về" · `'3'` → "Hoàn thành"
//   Chỉ **một** mã chữ xen giữa ba mã số ⇒ dấu vết một đợt đổi sang mã chữ **làm DỞ DANG**.
//   ⚠️ Nguồn **KHÔNG có nhánh ELSE** ⇒ mã lạ cho **NULL**, không phải chuỗi rỗng. Giữ nguyên.
//
// 🔴 TRẠNG THÁI GIAO HÀNG là **TÍNH RA**, không lưu cột — bản `_old` (:1712) và `_StatusList01` (:2294):
//     `SumDeliveryQuantity <= 0 hoặc NULL`   → "Mới tạo"
//     `SumDeliveryQuantity <  SumQuantity`   → "Hàng đang về"
//     `SumDeliveryQuantity >= SumQuantity`   → "Hoàn thành"
//   ⚠️ Đúng ba nhãn này về sau được **materialize** thành mã `'1'/'2'/'3'` của cột `Status` ở bản LIVE.
//   ⇒ endpoint trả CẢ HAI: `status` (cột) và `deliveryStatus` (tính lại từ SL) để đối soát lệch.
var supplierPartOrderStatusNames = new Dictionary<string, string>
{
    ["1"] = "Mới tạo", ["CONF"] = "Xác nhận", ["2"] = "Hàng đang về", ["3"] = "Hoàn thành",
};

app.MapGet("/api/supplierpartorders/statuses", () => Results.Ok(new
{
    statuses = supplierPartOrderStatusNames.Select(kv => new { code = kv.Key, name = kv.Value }),
    note = "Bộ mã TRỘN số + chữ trong cùng một cột (chỉ CONF là mã chữ). Mã ngoài bốn giá trị ⇒ nhãn NULL (nguồn không có ELSE).",
})).RequireAuthorization();

app.MapGet("/api/supplierpartorders", async (AppDbContext db, ITenantContext t,
    string? status, string? dealer, string? supplier, string? orderNo, string? includeDeleted) =>
{
    // 🔴 #298 XOÁ MỀM: hàm LIVE `Ser_Part_OrderGet` lọc `si.IsActive = '1'` ở BA chỗ. Port cũ trả cả đơn
    //   đã xoá. `includeDeleted=1` để soi dữ liệu, mặc định theo nguồn.
    var qy = db.SupplierPartOrders.Where(x => x.OrgId == t.OrgId);
    if (includeDeleted != "1") qy = qy.Where(x => x.FlagActive == "1");
    if (!string.IsNullOrWhiteSpace(status)) qy = qy.Where(x => x.Status == status);
    if (!string.IsNullOrWhiteSpace(dealer)) qy = qy.Where(x => x.DealerCode == dealer!.Trim().ToUpperInvariant());
    if (!string.IsNullOrWhiteSpace(supplier)) qy = qy.Where(x => x.SupplierID == supplier);
    if (!string.IsNullOrWhiteSpace(orderNo)) qy = qy.Where(x => x.OrderNo.Contains(orderNo!) || (x.OrderNoUser != null && x.OrderNoUser.Contains(orderNo!)));

    var heads = await qy.OrderByDescending(x => x.Id).Take(500).ToListAsync();
    var ids = heads.Select(h => h.Id).ToList();
    var lines = await db.SupplierPartOrderLines.Where(l => l.OrgId == t.OrgId && ids.Contains(l.SupplierPartOrderId)).ToListAsync();
    var byOrder = lines.GroupBy(l => l.SupplierPartOrderId).ToDictionary(g => g.Key, g => g.ToList());

    var items = heads.Select(h =>
    {
        var ls = byOrder.TryGetValue(h.Id, out var v) ? v : new List<SupplierPartOrderLine>();
        decimal sumQty = ls.Sum(l => l.Quantity);
        decimal sumDlv = ls.Sum(l => l.DeliveryQuantity);
        // 🔴 #298 TIỀN THẬT của nguồn (`#tbl_Amount`, PartOrder.cs:2018-2037) — tính từ `Cost` và `VAT`,
        //   **KHÔNG** từ cột `Price`/`Amount` mà port cũ tự đặt ra, và **KHÔNG trừ `Discount`**:
        //     BeforeTax = Cost × Quantity   ·   AfterTax = Cost × Quantity × (100 + VAT) / 100
        decimal beforeTax = ls.Sum(l => (l.Cost ?? 0m) * l.Quantity);
        decimal afterTax = ls.Sum(l => (l.Cost ?? 0m) * l.Quantity * (100m + (l.VAT ?? 0m)) / 100m);
        // Đúng thứ tự nhánh của nguồn: <=0 hoặc rỗng trước, rồi < , rồi >=.
        var deliveryStatus = sumDlv <= 0 ? "Mới tạo" : (sumDlv < sumQty ? "Hàng đang về" : "Hoàn thành");
        return new
        {
            h.OrderNo, h.OrderNoUser, h.CreateDate, h.DealerCode, h.SupplierID,
            h.Status,
            statusName = h.Status is not null && supplierPartOrderStatusNames.TryGetValue(h.Status, out var sn) ? sn : null,
            h.SendDate, h.ReceivePartDate, h.UserCreate, h.UserApproved, h.ApprovedDate,
            h.TypeOrder, h.HTCConfirm, h.PartialShipment, h.TypeTransport, h.VIN, h.ConfirmNo, h.CusCharges,
            h.FlagActive,
            lineCount = ls.Count, sumQuantity = sumQty, sumDeliveryQuantity = sumDlv,
            beforeTax, afterTax, amount = afterTax,
            deliveryStatus,
            // #298 PendingDeliveryQty là cột TÍNH, không lưu — kẹp sàn 0 đúng nguồn.
            pendingDeliveryQty = ls.Sum(l => Math.Max(0m, l.Quantity - l.DeliveryQuantity)),
        };
    }).ToList();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// #298 XOÁ MỀM đơn đặt phụ tùng NCC — nguồn không xoá vật lý, chỉ hạ `IsActive`.
app.MapDelete("/api/supplierpartorders/{no}", async (string no, AppDbContext db, ITenantContext t) =>
{
    var code = no.Trim();
    var h = await db.SupplierPartOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.OrderNo == code);
    if (h is null) return Results.NotFound(new { orderNo = code });
    h.FlagActive = "0";
    await db.SaveChangesAsync();
    return Results.Ok(new { h.OrderNo, deleted = true, note = "Xoá mềm (IsActive=0) — bản ghi vẫn còn trong DB." });
}).RequireAuthorization();

// #298 Đọc DÒNG của một đơn, kèm hai cột TÍNH của nguồn (BeforeTax/AfterTax/PendingDeliveryQty).
app.MapGet("/api/supplierpartorders/{no}/lines", async (string no, AppDbContext db, ITenantContext t) =>
{
    var code = no.Trim();
    var h = await db.SupplierPartOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.OrderNo == code);
    if (h is null) return Results.NotFound(new { orderNo = code });
    var ls = await db.SupplierPartOrderLines.Where(l => l.OrgId == t.OrgId && l.SupplierPartOrderId == h.Id).ToListAsync();
    var items = ls.Select(l => new
    {
        l.PartCode, l.PartName, l.PartID, l.Quantity, l.DeliveryQuantity,
        l.Cost, l.VAT, l.Discount, l.Factor, l.Model, l.HTCConfirm, l.LastDateDelivery,
        l.MIP, l.OO, l.BO, l.OH, l.SOQ, l.ICC, l.Note,
        beforeTax = (l.Cost ?? 0m) * l.Quantity,
        afterTax = (l.Cost ?? 0m) * l.Quantity * (100m + (l.VAT ?? 0m)) / 100m,
        pendingDeliveryQty = Math.Max(0m, l.Quantity - l.DeliveryQuantity),
    }).ToList();
    return Results.Ok(new { h.OrderNo, h.Status, h.FlagActive, count = items.Count, items });
}).RequireAuthorization();

// ⚠️ #298 KHÁC BIỆT CÓ CHỦ ĐÍCH so với nguồn, khai báo rõ để không ai tưởng port sót:
//  (1) Nguồn `Ser_Part_OrderGet` dùng **INNER JOIN Sys_user ON si.LogLUBy = suser.UserCode AND dealercode**
//      ⇒ đơn nào có `LogLUBy` rỗng, hoặc người sửa cuối đã bị xoá/đổi đại lý, **BIẾN MẤT khỏi danh sách**.
//      Cùng lý do với `INNER JOIN Ser_MST_Supplier`. Tác giả **không giải thích** chủ đích ⇒ theo lệ đã
//      chốt ở #272/#275, KHÔNG bắt chước mất-dữ-liệu-câm; ở đây vẫn trả đơn.
//      (Chú ý: bản `_StatusList` đã **comment mất** đúng join Sys_user đó ⇒ hai hàm LIVE cùng màn cho ra
//       số dòng khác nhau — thêm một bằng chứng join này là tai nạn, không phải luật.)
//  (2) Bộ lọc ngày: `Ser_Part_OrderGet` lọc theo **CreateDate**, còn `_StatusList` lọc theo **SendDate**
//      với CÙNG tham số `@FromDate/@ToDate`. Endpoint này chưa mở lọc ngày; khi mở phải chọn CỘT rõ ràng.
app.MapPost("/api/supplierpartorders", async (SupplierPartOrderDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.SupplierID)) return Results.BadRequest(new { error = "Chưa chọn nhà cung cấp." });
    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.PartCode)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Đơn phải có ít nhất 1 dòng phụ tùng." });

    var no = string.IsNullOrWhiteSpace(dto.OrderNo) ? "PO" + DateTime.Now.ToString("yyMMddHHmmss") : dto.OrderNo!.Trim();
    var h = new SupplierPartOrder
    {
        OrgId = t.OrgId, OrderNo = no, OrderNoUser = dto.OrderNoUser,
        CreateDate = dto.CreateDate ?? DateTime.Now,
        DealerCode = dto.DealerCode?.Trim().ToUpperInvariant(),
        // Nguồn nhận Status từ tham số; mặc định "1" (Mới tạo) đúng bảng mã LIVE.
        Status = string.IsNullOrWhiteSpace(dto.Status) ? "1" : dto.Status!.Trim(),
        ReceivePartDate = dto.ReceivePartDate, SendDate = dto.SendDate,
        SupplierID = dto.SupplierID, UserCreate = dto.UserCreate, UserApproved = dto.UserApproved,
        ApprovedDate = dto.ApprovedDate, TypeOrder = dto.TypeOrder, HTCConfirm = dto.HTCConfirm,
        PartialShipment = dto.PartialShipment, TypeTransport = dto.TypeTransport,
        VIN = dto.VIN?.Trim().ToUpperInvariant(), ConfirmNo = dto.ConfirmNo, CusCharges = dto.CusCharges,
    };
    db.SupplierPartOrders.Add(h); await db.SaveChangesAsync();

    foreach (var l in lines)
        db.SupplierPartOrderLines.Add(new SupplierPartOrderLine
        {
            OrgId = t.OrgId, SupplierPartOrderId = h.Id,
            PartCode = l.PartCode.Trim().ToUpperInvariant(), PartName = l.PartName,
            Quantity = l.Quantity, DeliveryQuantity = l.DeliveryQuantity,
            Price = l.Price, Amount = l.Amount, Note = l.Note,
            // #298 §12: khối cột THẬT của `Ser_Part_OrderDetail` (nguồn chỉ ghi khi tham số KHÁC RỖNG
            //   — ở đây `null` vào cột `null` nên tương đương).
            PartID = l.PartID, Factor = l.Factor, Cost = l.Cost, VAT = l.VAT, Discount = l.Discount,
            Model = l.Model, HTCConfirm = l.HTCConfirm, LastDateDelivery = l.LastDateDelivery,
            MIP = l.MIP, OO = l.OO, BO = l.BO, OH = l.OH, SOQ = l.SOQ, ICC = l.ICC,
            LogLUDateTime = DateTime.Now, LogLUBy = dto.UserCreate,
        });
    await db.SaveChangesAsync();
    return Results.Ok(new { h.OrderNo, h.Status, lines = lines.Count });
}).RequireAuthorization();

// ===== 🔴 #269 HCC NO-SHOW — khách QUÁ HẠN chưa quay lại xưởng =====
// Nguồn: `TERP.BizCarSv/HCCIntergration/BizCarSv.HCC.cs:381 HCC_NoShow_CreateOS` + hàm con `…OSX`,
//   chạy bởi job `Refs/Jobs/DMS.Service.Job.OSHCC` (`DMSServices_OSHCC.HCCNoShowCreateOS`).
// ⚠️ **CẢ CỤM NÀY CHỈ CÓ TRÊN MÁY 150** — grep `HCC_NoShow_CreateOS` trên laptop ra **0 dòng**, và cả
//   project job `DMS.Service.Job.OSHCC` (30 file) cũng chỉ có ở 150. Không đối chiếu 2 máy thì không
//   bao giờ thấy tính năng này. (Đo toàn cây ở #269: laptop ⊂ 150, 0 file riêng của laptop.)
//
// ===== 🔴 HAI CỬA SỔ THỜI GIAN KHÔNG GIAO NHAU =====
//   `months = 6`  ⇒ NoShowType "6Month"  · lần vào xưởng gần nhất trong **[nay−12 tháng, nay−6 tháng]**
//   `months = 12` ⇒ NoShowType "12Month" · lần vào xưởng gần nhất trong **[nay−24 tháng, nay−12 tháng]**
//   Job gọi đúng hai lần: `HCCNoShowCreateOS(6)` rồi `(12)`. Hai cửa sổ **rời nhau** nên một xe chỉ rơi
//   vào một nhóm — không nhân đôi.
// ⚠️ Cận dưới **HỞ** (`>`), cận trên **ĐÓNG** (`<=`) — giữ đúng, đừng "làm cho đối xứng".
// ⚠️ Nguồn **KHÔNG có nhánh else**: truyền số khác 6/12 thì cả ba biến (`NoShowType`, from, to) ở lại
//   `null` ⇒ câu SQL lọc bằng NULL, trả rỗng, **không báo lỗi**. Port CHẶN THẲNG thay vì im lặng —
//   đây là sai lệch CỐ Ý, ghi rõ để không bị coi là port sai.
//
// ⚠️ Lọc `IsActive` là của **KHÁCH HÀNG** (`cus.IsActive`), KHÔNG phải của xe — dễ đọc nhầm alias.
// ⚠️ `OrgHCCID is not null` xuất hiện ở **hai** câu (chọn đại lý, rồi ghép dữ liệu) — cổng chặn kép.
//
// 📌 NỢ (không bịa): (1) lời gọi HTTP sang HCC (`HCCService.Login` rồi đẩy `RQ_HCC_NoShow`) chưa port —
//   endpoint này mới dựng đúng DANH SÁCH ứng viên, là phần nghiệp vụ; (2) job gốc lặp qua mọi mạng lưới
//   trong `CmCt_Mst_Network` và **bỏ qua `NetworkID == "HTC"`** (tổng công ty tự nó không có khách) —
//   MiniHTC một tenant nên tham số `dealer` thay cho vòng lặp đó.
app.MapGet("/api/hcc/noshow", async (AppDbContext db, ITenantContext t, string? dealer, int? months) =>
{
    var m = months ?? 6;
    if (m != 6 && m != 12)
        return Results.BadRequest(new { error = "months chỉ nhận 6 hoặc 12 (nguồn chỉ định nghĩa hai mốc)." });

    var now = DateTime.Now;
    var noShowType = m == 6 ? "6Month" : "12Month";
    // ⚠️ KHONG dat ten bien la `from`/`to`: `from` la tu khoa ngu canh cua LINQ query syntax,
    //    `car.CurrentServiceDate > from` bi phan tich thanh menh de query (CS1525).
    var fromDate = now.AddMonths(m == 6 ? -12 : -24).Date;                          // 00:00:00
    var toDate = now.AddMonths(m == 6 ? -6 : -12).Date.AddDays(1).AddSeconds(-1);    // 23:59:59

    // Đại lý phải đã đăng ký HCC (OrgHCCID is not null).
    var dealers = db.Dealers.Where(d => d.OrgId == t.OrgId && d.OrgHCCID != null);
    if (!string.IsNullOrWhiteSpace(dealer)) dealers = dealers.Where(d => d.DealerCode == dealer!.Trim().ToUpperInvariant());
    var dealerList = await dealers.ToListAsync();
    if (dealerList.Count == 0)
        return Results.Ok(new { noShowType, from = fromDate, to = toDate, count = 0, items = Array.Empty<object>(), note = "Không đại lý nào có OrgHCCID." });
    var codes = dealerList.Select(d => d.DealerCode).ToList();

    var rows = await (from car in db.ServiceCars
                      join cus in db.ServiceCustomers on car.CusID equals cus.CusCode
                      where car.OrgId == t.OrgId && cus.OrgId == t.OrgId
                            && car.CurrentServiceDate > fromDate && car.CurrentServiceDate <= toDate
                            && cus.DealerCode != null && codes.Contains(cus.DealerCode)
                            && cus.FlagActive == "1"
                      select new { car, cus }).ToListAsync();

    // ===== 🔴 #454 TRẢ NỢ #269: hai cột **SAI HÌNH DẠNG** mà §12 không bắt được =====
    // (a) `ModelName` trước đây để cứng `null`. Nguồn có `left join Ser_MST_Model smm on car.ModelID =`
    //     `smm.ModelID` rồi trả `smm.ModelName` ⇒ đây là **cột thiếu hẳn**, không phải cột rỗng.
    //     ⚠️ Lệch khoá **cố ý**: nguồn nối bằng `ModelID`, MiniHTC không có cột đó nên nối bằng `ModelCode`.
    //     Vẫn là LEFT (xe chưa gán model vẫn phải ra) — nối INNER sẽ **nuốt dòng** ở tầng ĐỌC.
    // (b) `Km` trả số thập phân, trong khi nguồn `CONVERT(nvarchar(50), t.Km)` và model JSON
    //     `UtilHCC.HCC_NoShow.Km` là **string**. Toàn bộ 19 cột của bản tin HCC đều là chuỗi —
    //     gửi số sẽ lệch kiểu ở phía nhận. Đưa về chuỗi cho đúng hợp đồng.
    var modelNames = await db.ServiceModels.Where(x => x.OrgId == t.OrgId)
        .Select(x => new { x.ModelCode, x.ModelName }).ToListAsync();
    var modelByCode = modelNames.Where(x => x.ModelCode != null)
        .GroupBy(x => x.ModelCode).ToDictionary(g => g.Key, g => g.First().ModelName);
    var byCode = dealerList.ToDictionary(d => d.DealerCode);
    var items = rows.Select(r => new
    {
        NoShowType = noShowType,
        OrgID = r.cus.DealerCode != null && byCode.ContainsKey(r.cus.DealerCode) ? byCode[r.cus.DealerCode].OrgHCCID : null,
        NetworkID = r.cus.DealerCode != null && byCode.ContainsKey(r.cus.DealerCode) ? byCode[r.cus.DealerCode].NetworkHCCID : null,
        DealerCode = r.cus.DealerCode,
        CustomerCode = r.cus.CusCode, CustomerName = r.cus.CusName,
        CustomerAddress = r.cus.Address, CustomerEmail = r.cus.Email, CustomerPhone = r.cus.Mobile,
        ContactName = r.cus.ContName, ContactAddress = r.cus.ContAddress,
        ContactEmail = r.cus.ContEmail, ContactPhone = r.cus.ContMobile,
        PlateNo = r.car.PlateNo, ModelCode = r.car.ModelCode,
        ModelName = r.car.ModelCode != null && modelByCode.ContainsKey(r.car.ModelCode)
            ? modelByCode[r.car.ModelCode] : null,
        VIN = r.car.FrameNo,
        DeliveryDTimeUTC = r.car.CurrentServiceDate.HasValue ? r.car.CurrentServiceDate.Value.ToString("yyyy-MM-dd HH:mm:ss") : null,
        Km = r.car.CurrentKm.ToString(System.Globalization.CultureInfo.InvariantCulture),
    }).ToList();

    return Results.Ok(new
    {
        noShowType,
        from = fromDate.ToString("yyyy-MM-dd HH:mm:ss"),
        to = toDate.ToString("yyyy-MM-dd HH:mm:ss"),
        count = items.Count, items,

        // ===== 🔴 #454 BA PHÁT HIỆN VỀ NGUỒN (đọc trên máy 150, laptop không có) =====
        // 🔴 (1) **HÀM BAO TRẢ VỀ RỖNG MÃI MÃI**: `HCC_NoShow_CreateOS` khai `DataSet dsGetData = null;`,
        //     gọi `HCC_NoShow_CreateOSX(...)` — hàm này `private **void**`, **không** nhận `ref dsGetData` —
        //     rồi `MoveDataTable(ref mdsFinal, ref dsGetData)` với `dsGetData` vẫn là `null`.
        //     ⇒ WebMethod luôn trả **rỗng**; việc đẩy sang HCC chỉ là *tác dụng phụ*. Người gọi không có
        //     cách nào biết đã đẩy bao nhiêu bản ghi. Port **không bắt chước**: trả `count` + `items` thật,
        //     và gắn cờ dưới đây để chỗ lệch là **cố ý, có tên**.
        // 🔴 (2) **KIỂM TRA KẾT QUẢ HCC BỊ COMMENT**: cả khối `if (!StringEqual(objCMyMsgResult._strErrCode,`
        //     `TConst.Flag.No)) throw …` nằm trong `//` ⇒ HCC báo lỗi thì hệ vẫn **commit và coi là thành công**.
        //     (Theo LƯU Ý "port dòng ACTIVE, không port dòng COMMENT": bản chạy = KHÔNG kiểm.)
        // ⚪ (3) KIỂM TRA ÂM TÍNH — **không phải lỗi**: `strOrgID`/`strNetworkID` gán trong vòng lặp chi tiết
        //     rồi dùng **sau** vòng lặp (chỉ còn giá trị dòng CUỐI). Vô hại vì vòng ngoài đã cố định một đại lý
        //     nên mọi dòng cùng `OrgHCCID`. Ghi lại để lượt sau khỏi điều tra lại chỗ này.
        //     Nhưng hệ quả thật: 0 dòng ⇒ `strOrgID` ở lại `null` ⇒ **bỏ qua toàn bộ lời gọi HCC im lặng**.
        // ⚪ (4) `left join Mst_Dealer` ở câu thứ hai đi kèm `where md.OrgHCCID is not null` ⇒ **LEFT chết**,
        //     thực chất là INNER. Port dùng danh sách đại lý đã lọc sẵn nên tương đương.
        sourceReturnsEmptyAlways = true,
        sourceSkipsHccErrorCheck = true,
        modelNameJoinedByCodeNotId = true,
    });
}).RequireAuthorization();

// ===== Chia sẻ phụ tùng giữa đại lý (SharePart — port 1:1 FrmSharePart/ShareDealer, TCMotor) =====
// ===== 🔴 #420 ĐỌC PHIẾU CHIA SẺ (`SpSharePartGet`) — **một tham số đại lý, HAI mệnh đề lọc** =====
// TRACE: `FrmSharePartPublic` → `MstPartService.SpSharePartGet` (`MstPartService.cs:1299`)
//   → WS `SpSharePartGet` (`WSCarSv.asmx.cs:20335`) → biz `SpSharePartGet` (`BizCarSv.PartOrder.cs:5554`).
// (Bản ghi/tạo đã port ở #267; đây là bổ sung phía ĐỌC.)
//
// 🔴 **`strDealerCodeConditionList` được dùng LÀM HAI mệnh đề khác nghĩa nhau**:
//     `BuildClause("and", "**ssp**.DealerCode", strDealerCodeConditionList, …)`  ← đại lý ĐĂNG phiếu
//     `BuildClause("and", "**smp**.DealerCode", strDealerCodeConditionList, …)`  ← đại lý sở hữu bản ghi
//                                                                                 DANH MỤC phụ tùng
//   Cả hai cùng vào `WHERE` của truy vấn đầu ⇒ lọc "đại lý X" đòi **CẢ phiếu LẪN dòng danh mục phụ tùng**
//   phải thuộc X. Nếu danh mục phụ tùng do đơn vị khác quản lý thì truy vấn trả **RỖNG** — và rỗng ở đây
//   trông y hệt "đại lý này không chia sẻ gì". Một tham số, hai ý nghĩa, không ai khai báo.
//
// 🔴 **`0.0 SOPrice`** — cột giá bán trong phần chi tiết là **số 0 VIẾT CỨNG trong SQL**, không phải dữ liệu.
//   Lưới hiển thị một cột "giá" mà **luôn bằng 0** ở mọi dòng, mọi đại lý, mọi thời điểm.
// 🔴 `LEFT JOIN vwSer_inv_stockbalancebypart sb ON p.partid = sb.partid` — **THIẾU điều kiện đại lý**,
//   trong khi MỌI phép nối khác trong cùng câu đều có. Nếu khung nhìn này không tự giới hạn theo đại lý
//   thì `InStockQuantity` đang lấy tồn kho **không phân biệt đại lý**. Không đọc được định nghĩa khung
//   nhìn từ cây nguồn ⇒ ghi là **BẤT ĐỐI XỨNG CẦN XÁC MINH**, không kết luận.
//
// ⚠️ Chi tiết lọc `WHERE sspd.QuantityShare > 0` ⇒ dòng chia sẻ **số lượng 0 không hiện**. Nhưng #267 đã
//   xác định gửi 0 nghĩa là *"thôi chia sẻ"* ⇒ ghi 0 rồi thì **không đọc lại được**, chỉ biết qua việc nó biến mất.
// ⚠️ Nối `Ser_Mst_Part` theo **cả `PartID` LẪN `DealerCode`** (`sspd.DealerCode = p.DealerCode`) ⇒ cùng cái
//   bẫy chéo đại lý như trên. ⚠️ `INNER JOIN Mst_Dealer` hai lần ⇒ đại lý vắng danh mục là **mất phiếu** (lệ #410).
// ⚠️ Tầng service dựng `like %x%` cho **mã** và **tên** phụ tùng (lệ #401); còn `SharePartID`/`PartID`
//   truyền **trần** ⇒ `BuildClause` **bỏ im lặng** nếu người gọi không tự thêm toán tử (lệ #410).
// ⚠️ Service có `if (strDealerCodeConditionList == "=") strDealerCodeConditionList = "";` — chuẩn hoá
//   trường hợp mã đại lý rỗng; và ngay dưới là `strDealerCodeConditionList = strDealerCodeConditionList;`
//   — **tự gán chính nó, một dòng CHẾT** nằm trong thân `if` không làm gì cả.
// ⚠️ Tên tham số nguồn viết SAI CHÍNH TẢ `strPartIDCondit**o**nList` (thiếu `i`) và sai nhất quán qua **cả ba**
//   tầng ⇒ grep theo tên đúng chính tả sẽ TRƯỢT. Giữ nguyên văn khi tra cứu.
// 📌 Nguồn đọc trên **DB Main** (chú thích *"lấy trên main. vì là nghiệp vụ chia sẻ"*), không phải DB đại lý.
app.MapGet("/api/shareparts", async (AppDbContext db, ITenantContext t, string? dealer, string? part,
    string? status, string? shareNo, string? partCode, string? partName, string? createdBy,
    DateTime? createdDate, bool? includeZeroShare, string? dealerScope) =>
{
    var query = db.ShareParts.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) query = query.Where(x => x.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(part)) query = query.Where(x => x.PartCode.Contains(part!.ToUpper()) || (x.PartName != null && x.PartName.Contains(part!)));
    if (!string.IsNullOrWhiteSpace(status)) query = query.Where(x => x.Status == status);
    // #420 các bộ lọc của SpSharePartGet mà bản #267 chưa có:
    if (!string.IsNullOrWhiteSpace(shareNo)) query = query.Where(x => x.ShareNo == shareNo);
    // mã và tên phụ tùng: nguồn dựng `like %x%` ở TẦNG SERVICE ⇒ chứa, không phải bằng.
    if (!string.IsNullOrWhiteSpace(partCode)) query = query.Where(x => x.PartCode.Contains(partCode!));
    if (!string.IsNullOrWhiteSpace(partName)) query = query.Where(x => x.PartName != null && x.PartName.Contains(partName!));
    if (!string.IsNullOrWhiteSpace(createdBy)) query = query.Where(x => x.CreatedBy == createdBy);
    if (createdDate.HasValue) query = query.Where(x => x.CreatedAt.Date == createdDate.Value.Date);
    // 🔴 Nguồn lọc QuantityShare > 0 ở phần chi tiết — mặc định giữ đúng vậy.
    var keepZero = includeZeroShare ?? false;
    if (!keepZero) query = query.Where(x => x.QuantityShare > 0);

    var items = await query.OrderByDescending(x => x.Id).Take(500)
        // #267 §12: cột bổ sung có mặt ở CẢ GET lẫn POST
        .Select(x => new { x.ShareNo, x.DealerCode, x.PartCode, x.PartName, x.Unit, x.InStock, x.MinQuantity,
            x.QuantityShare, x.QuantityShareRequested, x.FlagLatest, x.Remark, x.Note, x.Status,
            x.CreatedBy, x.LogLUBy, createdAt = x.CreatedAt.ToString("yyyy-MM-dd"),
            // #420 Cột SOPrice của nguồn là số 0 VIẾT CỨNG trong SQL — trả đúng vậy, kèm ghi chú.
            soPrice = 0.0m }).ToListAsync();

    var zeroShareHidden = keepZero ? 0
        : await db.ShareParts.CountAsync(x => x.OrgId == t.OrgId && x.QuantityShare <= 0
            && (string.IsNullOrWhiteSpace(dealer) || x.DealerCode == dealer));

    return Results.Ok(new
    {
        count = items.Count,
        dealerFilterAppliedTwiceNote = "Nguồn dùng CÙNG tham số đại lý cho HAI mệnh đề khác nghĩa: "
            + "ssp.DealerCode (đại lý ĐĂNG phiếu) và smp.DealerCode (đại lý sở hữu bản ghi DANH MỤC phụ "
            + "tùng). Lọc 'đại lý X' đòi CẢ HAI thuộc X ⇒ nếu danh mục do đơn vị khác quản lý thì trả "
            + "RỖNG, trông y hệt 'đại lý này không chia sẻ gì'. MiniHTC chỉ lọc theo đại lý ĐĂNG.",
        soPriceNote = "Cột SOPrice là 0.0 viết cứng trong SQL nguồn — lưới hiển thị một cột giá LUÔN "
            + "bằng 0 ở mọi dòng. Không phải dữ liệu.",
        stockBalanceJoinNote = "LEFT JOIN vwSer_inv_stockbalancebypart CHỈ nối theo partid, THIẾU điều "
            + "kiện đại lý trong khi mọi join khác cùng câu đều có ⇒ InStockQuantity có thể không phân "
            + "biệt đại lý. BẤT ĐỐI XỨNG CẦN XÁC MINH (không đọc được định nghĩa khung nhìn từ cây nguồn).",
        zeroShareHidden,
        zeroShareNote = "Nguồn lọc sspd.QuantityShare > 0 ⇒ dòng số lượng 0 KHÔNG hiện. Mà theo #267, "
            + "gửi 0 nghĩa là 'thôi chia sẻ' ⇒ ghi 0 rồi thì không đọc lại được, chỉ biết qua việc nó "
            + "biến mất. Truyền includeZeroShare=true để xem cả các dòng đó.",
        misspelledParamNote = "Tham số nguồn viết sai chính tả strPartIDConditonList (thiếu i) và sai "
            + "NHẤT QUÁN qua cả ba tầng ⇒ grep theo tên đúng chính tả sẽ TRƯỢT.",
        dbNote = "Nguồn đọc trên DB Main (chú thích: lấy trên main, vì là nghiệp vụ chia sẻ).",
        items,
    });
}).RequireAuthorization();

// 🔴 #267 ĐĂNG CHIA SẺ PHỤ TÙNG — port 1:1 `SP_SharePartCreate` + `FrmSharePart.btnShare_Click`.
//
// ===== LUẬT TRẦN CHIA SẺ (thứ port cũ THIẾU HẲN) =====
//   `SoLuongDcChiaSe     = InStock − MinQuantity`      (tồn hiện có TRỪ tồn tối thiểu)
//   `SoLuongChiaSeThucTe = CASE`
//       `WHEN yêu-cầu >= trần AND trần    >= 0 THEN trần`
//       `WHEN yêu-cầu <  trần AND yêu-cầu >= 0 THEN yêu-cầu`
//       `ELSE 0`
//   ⇒ đại lý **không được chia sẻ phần tồn tối thiểu**; tồn đã dưới mức tối thiểu (trần âm) ⇒ chia sẻ = 0.
//   Nguồn KHÔNG tin số client gửi: sau khi `InsertHuge` nó còn `UPDATE … SET QuantityShare =`
//   `SoLuongChiaSeThucTe` đè lên. Port làm đúng vậy: **kẹp ở server**, giữ số gốc ở `QuantityShareRequested`.
//
// ⚠️ Form CÒN chặn trước ở client (`FrmSharePart.cs:243`): `if (checksl <= slt - slttt || checksl == 0)`
//    ngược lại báo **"Số lượng chia sẻ vượt quá quy định!"** — giữ NGUYÊN VĂN câu này. Lưu ý `== 0` được
//    cho qua: gửi 0 nghĩa là **thôi chia sẻ** phụ tùng đó, KHÔNG phải lỗi.
//    ⇒ bỏ hai guard cũ `QuantityShare <= 0` và `QuantityShare > InStock`: cả hai đều SAI so với nguồn
//      (nguồn cho 0, và trần là `InStock − MinQuantity` chứ không phải `InStock`).
//
// ===== LUẬT "BẢN MỚI THAY BẢN CŨ" =====
//   Nguồn xoá mọi bản ghi cũ CÙNG ĐẠI LÝ khác `SharePartID` vừa tạo (`delete t from SP_SharePart t inner`
//   `join #tbl_..._Filter f` …), và ghi `FlagLatest = Flag.Active` cho bản mới ⇒ **mỗi đại lý chỉ có MỘT
//   đợt chia sẻ đang hiệu lực**. Vì vậy POST nhận CẢ DANH SÁCH (`Lines`) trong một lần — gửi từng phụ tùng
//   một sẽ xoá mất phụ tùng gửi trước, đúng như nguồn.
//
// ☠️ BẪY CODE CHẾT ĐÃ TRÁNH: region "Save on DB old" dựng chuỗi `strSql_SaveOnDB_01` chứa
//   `DELETE FROM SP_SharePart_Detail;` / `DELETE FROM SP_SharePart;` **KHÔNG CÓ WHERE** (xoá sạch bảng).
//   Chuỗi đó **dựng xong rồi vứt — không hàm Exec* nào nhận nó**. Bản CHẠY là `strSql_SaveOnDB`, đã
//   thêm `where SharePartID <> @… and DealerCode = @…`. Port theo block chết = viết API xoá sạch bảng.
//   (Hai block còn khác nhau ở CASE: bản chạy thêm `AND trần >= 0` / `and yêu-cầu >= 0`.)
//
// 📌 NỢ: nguồn `ExecNonQuery` **hai lần** — `_dbMain` rồi `_dbWH` (ghi kép Main/WH). MiniHTC một DB.
app.MapPost("/api/shareparts", async (SharePartDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.DealerCode)) return Results.BadRequest(new { error = "Chưa chọn đại lý." });

    // Một dòng phẳng (tương thích ngược) HOẶC cả danh sách — nguồn luôn gửi cả bảng chi tiết.
    var lines = dto.Lines is { Count: > 0 }
        ? dto.Lines
        : new List<SharePartLineDto> { new(dto.PartCode, dto.PartName, dto.Unit, dto.InStock, dto.QuantityShare, dto.MinQuantity, dto.Remark) };
    if (lines.Any(l => string.IsNullOrWhiteSpace(l.PartCode))) return Results.BadRequest(new { error = "Chưa chọn phụ tùng." });

    // Trùng phụ tùng trong một đợt: nguồn ném SP_SharePart_Create_DuplicateKeyDetail (khoá "|PartID|").
    var dupe = lines.GroupBy(l => l.PartCode.Trim().ToUpperInvariant()).FirstOrDefault(g => g.Count() > 1);
    if (dupe is not null) return Results.BadRequest(new { error = "Phụ tùng bị lặp trong danh sách chia sẻ: " + dupe.Key });

    var dealer = dto.DealerCode.Trim().ToUpperInvariant();
    var no = "SP" + DateTime.Now.ToString("yyMMddHHmmss");
    var now = DateTime.Now;
    var rows = new List<SharePart>();

    foreach (var l in lines)
    {
        var code = l.PartCode.Trim().ToUpperInvariant();
        // Tồn / tồn tối thiểu lấy từ DANH MỤC PHỤ TÙNG khi có — nguồn tính SLC từ Ser_Inv_PartInstance
        //   và MinQuantity từ Ser_Mst_Part, KHÔNG lấy số client gửi. Không có trong danh mục thì mới dùng
        //   số client gửi (MiniHTC chưa port tầng partInstance — đã ghi nợ).
        var mp = await db.ServiceParts.FirstOrDefaultAsync(p => p.OrgId == t.OrgId && p.PartCode == code);
        var inStock = mp?.Quantity ?? l.InStock;
        var minQty = mp?.MinQuantity ?? l.MinQuantity;
        var room = inStock - minQty;              // SoLuongDcChiaSe
        var req = l.QuantityShare;

        // Chặn phía client của nguồn — giữ nguyên văn câu thông báo.
        if (!(req <= room || req == 0))
            return Results.BadRequest(new { error = "Số lượng chia sẻ vượt quá quy định!", partCode = code });

        // Kẹp phía server (CASE của nguồn) — vẫn chạy dù guard trên đã qua, đúng như nguồn làm hai lớp.
        var actual = (req >= room && room >= 0) ? room
                   : (req < room && req >= 0) ? req
                   : 0m;

        rows.Add(new SharePart
        {
            OrgId = t.OrgId, ShareNo = no, DealerCode = dealer, PartCode = code,
            PartName = l.PartName ?? mp?.PartName, Unit = l.Unit ?? mp?.Unit,
            InStock = inStock, MinQuantity = minQty,
            QuantityShareRequested = req, QuantityShare = actual,
            Remark = l.Remark, Note = dto.Note, Status = "Open", FlagLatest = "1",
            CreatedBy = dto.CreatedBy, LogLUDateTime = now, LogLUBy = dto.CreatedBy,
        });
    }

    // Bản mới THAY bản cũ: nguồn XOÁ hẳn các bản ghi cũ của chính đại lý đó (không phải chỉ hạ cờ).
    var old = await db.ShareParts.Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer && x.ShareNo != no).ToListAsync();
    if (old.Count > 0) db.ShareParts.RemoveRange(old);

    db.ShareParts.AddRange(rows);
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        shareNo = no, replaced = old.Count,
        items = rows.Select(x => new { x.PartCode, requested = x.QuantityShareRequested, shared = x.QuantityShare, room = x.InStock - x.MinQuantity }),
    });
}).RequireAuthorization();

// Đóng tin chia sẻ (Open -> Closed).
app.MapPost("/api/shareparts/{no}/close", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var x = await db.ShareParts.FirstOrDefaultAsync(v => v.OrgId == t.OrgId && v.ShareNo == no);
    if (x is null) return Results.NotFound(new { no });
    if (x.Status == "Closed") return Results.BadRequest(new { error = "Tin chia sẻ đã đóng." });
    x.Status = "Closed"; await db.SaveChangesAsync();
    return Results.Ok(new { x.ShareNo, status = x.Status });
}).RequireAuthorization();

// ===== Thông báo kỹ thuật (Bulletin — port 1:1 FrmBulletinHTCCreate/Modify/Search, TCMotor) =====
app.MapGet("/api/bulletins", async (AppDbContext db, ITenantContext t, string? q, string? part, string? active) =>
{
    var query = db.Bulletins.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(q)) query = query.Where(x => x.BulletinNo.Contains(q!) || (x.Remark != null && x.Remark.Contains(q!)));
    if (!string.IsNullOrWhiteSpace(part)) query = query.Where(x => x.PartCode == part);
    if (!string.IsNullOrWhiteSpace(active)) query = query.Where(x => x.FlagActive == active);
    var items = await query.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.BulletinNo, x.BulletinNoHMC, x.Remark, x.PartCode, x.PartName, x.SerCode, x.SerName, x.FileNameAttachment, x.FileAttachment, x.FlagActive, x.CreateDate, x.UserCreate,   // #377 §12
        vins = db.BulletinVins.Count(v => v.OrgId == t.OrgId && v.BulletinNo == x.BulletinNo),
        dateExpired = x.DateExpired.HasValue ? x.DateExpired.Value.ToString("yyyy-MM-dd") : ""
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Upsert theo số thông báo (số trống = auto-gen).
// TWIN đã trace: WS gọi `Blt_BulletinCreate_20210224` / `Blt_BulletinUpdate_20210224`
// (KHÔNG phải Blt_BulletinCreate / Blt_BulletinUpdate trần — có tới 4 phiên bản trong biz).
app.MapPost("/api/bulletins", async (BulletinDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.Remark)) return Results.BadRequest(new { error = "Chưa nhập nội dung thông báo." });
    // Biz chặn thiếu số bản tin hãng (Blt_Bulletin_InvalidBulletinNoHMC) — form không có luật này.
    if (string.IsNullOrWhiteSpace(dto.BulletinNoHMC)) return Results.BadRequest(new { error = "Chưa nhập số bản tin HMC!" });
    // #250: `FrmBulletinHTCCreate.cs` và `FrmBulletinHTCModify.cs` đều kiểm `regex.IsMatch(txtBulletinNo.Text)`.
    //   ⚠️ Ô bị kiểm là `BulletinNo` (số bản tin của TA), KHÔNG phải `BulletinNoHMC` (số của hãng).
    if (HasSpecialChar((dto.BulletinNo ?? "").Trim()))
        return Results.BadRequest(new { error = "Số bản tin không được phép chứa các ký tự đặc biệt" });

    var vinLines = dto.Vins ?? new();
    foreach (var line in vinLines)
    {
        // Nguồn gọi CheckVINEmpty cho từng dòng trước khi ghi.
        if (string.IsNullOrWhiteSpace(line.VinNo)) return Results.BadRequest(new { error = "Số khung không được để trống!" });
    }
    var duplicatedVin = vinLines
        .GroupBy(v => v.VinNo!.Trim().ToUpperInvariant())
        .FirstOrDefault(g => g.Count() > 1);
    if (duplicatedVin is not null)
        return Results.BadRequest(new { error = $"Số khung '{duplicatedVin.Key}' bị trùng trong danh sách!" });

    var no = string.IsNullOrWhiteSpace(dto.BulletinNo) ? "BLT" + DateTime.Now.ToString("yyMMddHHmmss") : dto.BulletinNo.Trim().ToUpperInvariant();
    var row = await db.Bulletins.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.BulletinNo == no);
    var updated = row is not null;
    if (row is null) { row = new Bulletin { OrgId = t.OrgId, BulletinNo = no }; db.Bulletins.Add(row); }

    row.BulletinNoHMC = dto.BulletinNoHMC!.Trim();
    row.Remark = dto.Remark;
    row.PartCode = dto.PartCode; row.PartName = dto.PartName;
    row.SerCode = dto.SerCode; row.SerName = dto.SerName;
    row.DateExpired = dto.DateExpired;
    row.FileNameAttachment = dto.FileNameAttachment;
    row.FileAttachment = dto.FileAttachment;   // #377 §12
    row.CreateDate = dto.CreateDate; row.UserCreate = dto.UserCreate;
    row.FlagActive = "1";
    await db.SaveChangesAsync();

    // Hai bảng chi tiết: chỉ thay khi client CÓ gửi lên (không gửi = giữ nguyên).
    if (dto.Details is not null)
    {
        db.BulletinDtls.RemoveRange(db.BulletinDtls.Where(d => d.OrgId == t.OrgId && d.BulletinNo == no));
        foreach (var line in dto.Details)
            db.BulletinDtls.Add(new BulletinDtl
            {
                OrgId = t.OrgId, BulletinNo = no,
                SerCode = line.SerCode, SerName = line.SerName,
                PartCode = line.PartCode, PartName = line.PartName
            });
    }
    if (dto.Vins is not null)
    {
        db.BulletinVins.RemoveRange(db.BulletinVins.Where(v => v.OrgId == t.OrgId && v.BulletinNo == no));
        foreach (var line in vinLines)
            db.BulletinVins.Add(new BulletinVin
            {
                OrgId = t.OrgId, BulletinNo = no,
                VinNo = line.VinNo!.Trim().ToUpperInvariant(),
                DealerCode = line.DealerCode,
                // Không truyền trạng thái thì mặc định "P" đúng như `isnull(bv.Status,'P')` của nguồn.
                Status = string.IsNullOrWhiteSpace(line.Status) ? "P" : line.Status!.Trim().ToUpperInvariant()
            });
    }
    await db.SaveChangesAsync();

    return Results.Ok(new { row.BulletinNo, row.BulletinNoHMC, details = dto.Details?.Count ?? 0, vins = vinLines.Count, updated });
}).RequireAuthorization();

// Chi tiết một bản tin: dịch vụ/phụ tùng liên quan + danh sách VIN áp dụng kèm trạng thái từng xe.
// ===== 🔴 #377 THÔNG BÁO KỸ THUẬT ÁP CHO MỘT XE (`Blt_Bulletin_Get_byVin_ForTab`, `Bulletin.cs:4145`) =====
// Màn Tab tra thông báo kỹ thuật theo **VIN**: lọc trên bảng nối `Btl_Bulletin_VIN` rồi lấy thông báo.
//
// 🔴 **MÃ TEST LỌT LÊN BẢN CHẠY THẬT** — cột `FileAttachment` được lấy bằng:
//   `(select top 1 t.FileAttachment from Btl_Bulletin t where t.BulletinNo = 'TEST201911')`
//   Truy vấn con này **KHÔNG tương quan với dòng nào cả**: mọi thông báo trả về đều nhận tệp đính kèm
//   của **một bản ghi TEST**. Nếu bản ghi đó không tồn tại thì cột luôn NULL.
//   📌 Có mặt ở **cả ba cây nguồn** (laptop `.V2`, 150 `.Release`, và cả `V20` cũ) ⇒ tồn tại nhiều năm,
//     không phải sơ suất mới. MiniHTC **không tái hiện**: trả đúng tệp của từng thông báo và bật cờ.
// 🔴 **CỘT LẶP TRONG DANH SÁCH SELECT**: `bb.CreateDate` xuất hiện **HAI LẦN** trong cùng câu select
//   (kèm `bb.UserCreate` / `bb.CreatedBy` là hai cột người tạo khác nhau) ⇒ ADO trả về `CreateDate` và
//   `CreateDate1`. Ai map theo chỉ số cột sẽ lệch.
// ⚠️ **TRỘN BAKE + PARAM trên CÙNG một token** (lệ `[BAKE-PARAM-MIX]`): `@strIsActive` vừa được
//   `BuildClauseConditionSingle` đăng ký làm **tham số**, vừa bị `StringUtils.Replace` **thay thẳng bằng
//   giá trị thô, KHÔNG bọc nháy**. Replace chạy trước nên tham số thành vô dụng, và giá trị được ghép
//   trực tiếp vào SQL. Port dùng tham số thật.
// ⚠️ `Status` của dòng VIN: `isnull(bv.Status, 'P')` ⇒ trống hiểu là **P** (chờ xử lý).
// ⚠️ Bộ lọc VIN/đại lý/trạng thái đều là **DANH SÁCH ngăn cách `|`** (`BuildClauseConditionList`).
// ===== 🔴 #379 HẠN THANH TOÁN CỌC = NGÀY LÀM VIỆC **T+N**, KHÔNG PHẢI CỘNG NGÀY THƯỜNG =====
// Nguồn: `BizHTC.Order.cs:1773` + `BizHTC.MasterData.cs:2276` gọi
//   `myUtils_GetParamsRaw(TConst.HTCParamCode.Calendar_DepositDuty_DayT)` lấy N, rồi dùng
//   `mySql_GetClauseSelect_Mst_Calendar_GetForDayT()` (`BizHTC.Common.cs:959`) để tra lịch:
//     1. lọc `Mst_Calendar` `CalendarType = 'WorkingDay'` **và** `StatusValue = 0`, `Date >= hôm nay`,
//        đánh số tuần tự bằng `identity(bigint, 0, 1)` ⇒ **chỉ ngày LÀM VIỆC mới có số thứ tự**;
//     2. tự nối `t.MyIdxSeq + @nDayT = t1.MyIdxSeq` ⇒ ngày làm việc **thứ N kể từ** ngày đang xét;
//     3. `update osod set DepositDutyEndDate = mcDayT.DateDayT ... on osod.ApprovedDate = mcDayT.Date`.
//   ⇒ Cộng N **ngày lịch** là SAI: N ở đây đếm **ngày làm việc**, nhảy qua mọi ngày nghỉ.
//
// 🔴 `StatusValue = 0` **nghĩa là NGÀY LÀM VIỆC** (chú thích nguồn `-- Only WorkingDay`) — trực giác
//   dễ hiểu ngược thành 'trạng thái rỗng/chưa set'. Khác 0 = ngày nghỉ.
// 🔴 **BẢNG LỊCH LỌC TỪ HÔM NAY**, không phải từ `ApprovedDate`: `and mcal.Date >= @strMCALDate_From`
//   với `@strMCALDate_From = DateTime.Now`. ⇒ Đơn có `ApprovedDate` **trong QUÁ KHỨ** không khớp dòng
//   nào, `left join` trả NULL và câu `update` **ghi NULL đè lên hạn cọc đang có** — lưu lại một đơn cũ
//   là **xoá trắng hạn thanh toán cọc** của nó mà không báo gì.
// 🔴 `myUtils_GetParamsRaw` (`Common.cs:648`) đọc `Mst_Param` bằng `top 1` không `order by` rồi trả
//   `Rows[0][0]` **không kiểm `Rows.Count`** ⇒ thiếu bản ghi tham số thì **NÉM LỖI CHỈ SỐ**, không phải
//   trả rỗng; lỗi hiện ra rất xa nơi thực sự sai (thiếu cấu hình).
// ⚠️ Câu `update` đặt `with (nolock)` **trên chính bảng bị GHI** (`Ord_SalesOrderDetail`).
// ===== 🔴 #380 TỒN KHO PHỤ TÙNG LÀ SỐ **TÍNH**, KHÔNG PHẢI SỐ **LƯU** =====
// 🆕 Tìm ra bằng sweep #313 `_audit/sweep_stored_vs_derived.js` chạy trên **CẢ HAI** cây nguồn
//   (TCMotor CarSv + 2010.HTC BizHTC) — sweep tự cảnh báo phải quét mọi cây, vì cột của hệ không
//   được truyền vào sẽ trông như 'dẫn xuất' một cách giả tạo.
//
// Kiểm chứng tay: trong toàn bộ file SỐNG của nguồn, `InventoryQuantity` **KHÔNG có một chỗ ghi nào**
// (0 hit cho `[\"InventoryQuantity\"]` / `alColumnEffective`); nó luôn là **alias tính lúc đọc**.
//
// 🔴 **HAI CÔNG THỨC KHÁC NHAU cho cùng một tên cột**:
//   · `Appointment.cs:1323` · `Appointment.cs:2299` · `Service.RO.cs:362`
//       `(isnull(sb.TotalInStock,0) + isnull(sb.TotalInShipment,0))` = **tồn kho + hàng đang về**
//   · `PartOrder.cs:4415`
//       `(isnull(sb.TotalInStock,0))` = **CHỈ tồn kho**
//   ⇒ Màn đặt hàng nhìn thấy con số **nhỏ hơn** màn hẹn/lệnh sửa chữa trên cùng một mã phụ tùng.
//     Đây là chủ đích (đặt hàng không được tính hàng chưa về), nên **không hợp nhất hai công thức**.
// ⚠️ MiniHTC chưa mô hình hoá 'hàng đang về' ⇒ trả `inShipment = null` và bật cờ, thay vì bịa số 0.
app.MapGet("/api/serviceparts/{code}/inventory", async (string code, AppDbContext db, ITenantContext t,
    string? formula) =>
{
    code = (code ?? "").Trim().ToUpperInvariant();
    var part = await db.ServiceParts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PartCode == code);
    if (part is null) return Results.NotFound(new { code });

    var inStock = await db.PartStocks.Where(s => s.OrgId == t.OrgId && s.PartCode == code)
        .SumAsync(s => (decimal?)s.OnHand) ?? 0m;

    // "order" = công thức của PartOrder.cs (CHỈ tồn kho); mặc định = công thức của Appointment/Service.RO.
    var orderShape = (formula ?? "").Trim().ToLowerInvariant() == "order";

    return Results.Ok(new
    {
        code, inStock,
        inShipment = (decimal?)null,
        inventoryQuantity = inStock,   // + inShipment khi có mô hình hàng đang về
        formula = orderShape ? "PartOrder: CHỈ tồn kho" : "Appointment/Service.RO: tồn kho + hàng đang về",
        inShipmentNotModelled = !orderShape,
        twoFormulaNote = "Nguồn dùng HAI công thức cho cùng tên cột: màn đặt hàng KHÔNG cộng hàng đang về, "
            + "màn hẹn/lệnh sửa chữa CÓ cộng. Không hợp nhất — khác biệt là chủ đích.",
        storedValueIgnored = part.InventoryQuantity,
        storedValueNote = "Cột InventoryQuantity trên master là DI SẢN: nguồn không bao giờ ghi nó. "
            + "Từ #380 endpoint tạo/sửa phụ tùng KHÔNG nhận giá trị này từ client nữa.",
    });
}).RequireAuthorization();

app.MapGet("/api/calendar/workday-offset", async (AppDbContext db, ITenantContext t,
    DateTime? date, int? days, DateTime? from) =>
{
    var baseDate = (date ?? DateTime.Today).Date;
    var n = days ?? 0;
    // Đúng nguồn: mốc lọc lịch là HÔM NAY, không phải ngày đang xét.
    var fromDate = (from ?? DateTime.Today).Date;

    // Chỉ NGÀY LÀM VIỆC mới được đánh số: CalendarType = WorkingDay và StatusValue = 0.
    var workdays = await db.MstCalendars
        .Where(c => c.OrgId == t.OrgId && c.CalendarType == "WorkingDay" && c.StatusValue == "0"
                    && c.Date >= fromDate)
        .OrderBy(c => c.Date).Select(c => c.Date).ToListAsync();

    var idx = workdays.FindIndex(d => d.Date == baseDate);
    if (idx < 0)
        return Results.Ok(new
        {
            date = baseDate, days = n, found = false,
            resultDate = (DateTime?)null,
            reason = "Ngày đang xét KHÔNG nằm trong dải lịch làm việc lọc từ mốc `from`.",
            pastDateWipesValue = baseDate < fromDate,
            wipeNote = baseDate < fromDate
                ? "Nguồn lọc lịch từ HÔM NAY: ngày duyệt trong QUÁ KHỨ không khớp dòng nào, `left join` ra NULL "
                  + "và câu `update` GHI NULL ĐÈ lên hạn cọc đang có."
                : null,
            calendarFrom = fromDate, workdayCount = workdays.Count,
        });

    var targetIdx = idx + n;
    DateTime? result = targetIdx >= 0 && targetIdx < workdays.Count ? workdays[targetIdx] : null;

    return Results.Ok(new
    {
        date = baseDate, days = n, found = true,
        resultDate = result,
        calendarExhausted = result is null,
        exhaustedNote = result is null
            ? "Lịch làm việc chưa kéo dài đủ N ngày ⇒ nguồn trả NULL (không báo lỗi)."
            : null,
        calendarDaysSpanned = result is null ? (int?)null : (int)(result.Value - baseDate).TotalDays,
        workdayIndex = idx, workdayCount = workdays.Count, calendarFrom = fromDate,
        semanticsNote = "N đếm theo NGÀY LÀM VIỆC (nhảy qua ngày nghỉ), không phải cộng ngày lịch.",
        statusValueNote = "StatusValue = 0 nghĩa là NGÀY LÀM VIỆC; khác 0 là ngày nghỉ (dễ hiểu ngược).",
    });
}).RequireAuthorization();

// Tham số hệ thống đọc thô (`myUtils_GetParamsRaw`) — nguồn CRASH khi thiếu bản ghi.
app.MapGet("/api/params/{code}", async (string code, AppDbContext db, ITenantContext t) =>
{
    code = (code ?? "").Trim();
    var rows = await db.Masters
        .Where(m => m.OrgId == t.OrgId && m.Category == "Mst_Param" && m.Code == code)
        .Select(m => m.Name).ToListAsync();

    return Results.Ok(new
    {
        code, found = rows.Count > 0,
        value = rows.FirstOrDefault(),          // nguồn: top 1 KHÔNG order by
        matchCount = rows.Count,
        ambiguous = rows.Count > 1,
        sourceCrashesWhenMissing = rows.Count == 0,
        crashNote = rows.Count == 0
            ? "Nguồn đọc Rows[0][0] mà KHÔNG kiểm Rows.Count ⇒ thiếu tham số là NÉM LỖI CHỈ SỐ, "
              + "không phải trả rỗng. MiniHTC trả found = false thay vì ném."
            : null,
    });
}).RequireAuthorization();

// ===== 🔴 #428 TRA BẢN TIN KỸ THUẬT (`Blt_BulletinSearch`) — ô **GHI CHÚ** không bao giờ ra kết quả =====
// TRACE: `FrmBulletinHTCSearch` → `BltBulletin.Blt_BulletinSearch` (`BltBulletin.cs:801`)
//   → WS `Blt_Bulletin_Get` → biz **`Blt_Bulletin_Get_20210224`** (`BizCarSv.Bulletin.cs:2523`).
//   ⚠️ Có **11 hàm cùng họ `Blt_Bulletin_Get*`** trong một file; WS chỉ gọi bản `_20210224`.
//
// 🔴 **LỖI THẬT — HAI QUY ƯỚC DỰNG MỆNH ĐỀ TRỘN TRONG CÙNG MỘT HÀM** (cùng gốc với #427):
//   Biz dùng `BuildClause` cho `BulletinID` · `BulletinNo` · `CreateDate` · `UserCreate` · `VinNo`
//     ⇒ chuỗi truyền vào **PHẢI kèm toán tử** (`"like%abc%"`, `">=2026-01-01"`).
//   nhưng dùng `BuildClauseConditionSingle("and", "si.Remark", **"like"**, @p, giá trị)` cho `Remark`
//     ⇒ hàm này **tự cấp toán tử** và đưa giá trị vào tham số **NGUYÊN VĂN** (đọc thân: nó chỉ
//       `string.Format("{0} ({1} {2} {3})")` rồi `AddRange(paramName, paramValue)`, **không cắt gì cả**).
//   Mà tầng service lại dựng `strRemarkConditionList = "like" + "%abc%"` cho **cả hai** loại như nhau.
//   ⇒ Với Remark, câu SQL thành `si.Remark like @p` với `@p = "like%abc%"`
//     ⇒ **tìm những ghi chú bắt đầu bằng đúng chữ "like"**. Người dùng gõ gì cũng ra **rỗng**.
//     Không lỗi, không cảnh báo — ô tìm kiếm chỉ đơn giản là không bao giờ khớp.
//   📌 MiniHTC lọc Remark bằng **chứa (contains)** đúng ý định của màn, và trả cờ `remarkFilterBrokenInSource`.
//
// 📌 **KẾT QUẢ ÂM TÍNH đã kiểm** (đừng "phát hiện" lại): service nối `"like"` + `"%x%"` **KHÔNG có dấu cách**
//   (`"like%x%"`) cho BulletinNo/Vin/Remark, chỉ `UserCreate` có dấu cách (`"like "`). Với `BuildClause` thì
//   **không sao**: nó nhận diện tiền tố bằng `StartsWith("LIKE")` rồi cắt đúng `Substring(4)` ⇒ ba ô kia chạy đúng.
//   Chỉ `Remark` hỏng, vì nó đi vào hàm KHÁC.
//
// 🔴 **THAM SỐ CHẾT**: service khai `strIsActive` nhưng khi gọi WS lại truyền cứng `Constants.Flag.Active`
//   (= `"1"`) ⇒ **không bao giờ tra được bản tin đã ngừng hiệu lực**. Đây là ca **thứ tư** cùng kiểu
//   (#410 mã đại lý bị thay bằng phiên đăng nhập · #420 tự gán chính nó · #423 tên nói sai khái niệm).
// ⚠️ Khoảng ngày dựng thành `">=from|<=to"` (giống #406) và áp lên `si.CreateDate`.
// ⚠️ `BuildClause` gọi `.ToUpper()` lên **cả giá trị tham số** ⇒ dữ liệu lưu chữ thường có thể không khớp.
// ===== 🔴 #429 BÁO CÁO CHIẾN DỊCH THEO ĐẠI LÝ (`Ser_CampaignDealerRpt`) =====
// TRACE: `FrmCamExportRpt` (722 dòng) → `Ser_CampaignDealerRpt` / `_WH` tuỳ ô "toàn bộ lịch sử"
//   → WS (`WSCarSv.asmx.cs:13161`) → biz (`BizCarSv.Service.Report.cs:3323`).
//
// 🔴 **MỘT THAM SỐ ĐẠI LÝ, HAI BẢNG Ở HAI CSDL** (cùng kiểu #420, nhưng nặng hơn):
//   `zzzzClauseWhereDealerCodeConditionList` được nhét vào **CẢ HAI**:
//     · `#tbl_cam`  ← `from [@strDBName_CommonCenter].[dbo].Ser_Campaign` (**CSDL TRUNG TÂM**)
//     · `#tbl_ro`   ← `from ser_ro` (CSDL đại lý)
//   ⇒ Lọc "đại lý X" đòi **chiến dịch cũng phải mang mã đại lý X**. Nếu chiến dịch được khai ở trung
//     tâm dưới một mã khác (hoặc để trống), tập `#tbl_cam` **rỗng** ⇒ mọi phép nối sau đó rỗng theo
//     ⇒ **báo cáo trắng**, trông y hệt "đại lý này không tham gia chiến dịch nào".
//
// 📌 **KẾT QUẢ ÂM TÍNH — đã kiểm, KHÔNG phải bug** (ghi để lượt sau khỏi dò lại):
//   Khối gộp tầng 1 (`#tbl_ser_ROPartItems`) có `group by` chứa **chính các cột đang được `sum`**
//     (`Factor`, `Price`, `Quantity`, `VAT`) — nhìn rất giống lỗi gộp sai. **Nhưng** ngay sau đó có
//     tầng 2 (`#tbl_ser_ROPartItems_PartAmount`) gộp lại theo `ROID + CamID` ⇒ tổng cuối **đúng**.
//     Hai tầng gộp bù nhau; đọc một tầng rồi kết luận là sai.
//   ⚠️ Có một khối `#tmpAmount` dùng `full outer join` **đã bị comment trọn vẹn** — bản ACTIVE là
//     hai khối gộp riêng rồi nối sau. Port theo dòng active.
//
// ⚠️ Tiền **công** tính `Factor × Price` (**không** nhân số lượng), tiền **phụ tùng** tính
//   `Factor × Price × Quantity` — bất đối xứng CÓ CHỦ Ý, giống hệt lệ #303.
// ⚠️ VAT là **phần trăm** (`× VAT × 0.01`), không phải hệ số 0..1.
// ⚠️ `#tbl_ro` chỉ lấy lệnh `Status = 'FNS'` (đã hoàn tất) và nối `ser_customer`/`ser_car` bằng
//   **nối TRONG** kèm `DealerCode` ở cả hai vế ⇒ xe/khách lệch đại lý là **mất dòng**.
app.MapGet("/api/report/campaign-dealer", async (AppDbContext db, ITenantContext t,
    string? camNo, string? dealer, DateTime? fromDate, DateTime? toDate) =>
{
    // #tbl_cam — nguồn lọc chiến dịch bằng CÙNG mã đại lý dùng cho lệnh sửa.
    var camQ = db.Campaigns.Where(c => c.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(camNo)) camQ = camQ.Where(c => c.CamNo == camNo!.Trim());
    var cams = await camQ.ToListAsync();
    var camIds = cams.Select(c => c.CamNo).ToHashSet();   // Campaign: khoa nghiep vu la CamNo (khong co cot CamID)

    // #tbl_ro — chỉ lệnh đã hoàn tất.
    var roQ = db.RepairOrders.Where(r => r.OrgId == t.OrgId && r.Status == "FNS");
    if (!string.IsNullOrWhiteSpace(dealer)) roQ = roQ.Where(r => r.DealerCode == dealer!.Trim());
    if (fromDate.HasValue) roQ = roQ.Where(r => r.CheckInDate >= fromDate.Value.Date);
    if (toDate.HasValue) roQ = roQ.Where(r => r.CheckInDate <= toDate.Value.Date);
    var ros = await roQ.ToListAsync();
    var roIds = ros.Select(r => r.Id).ToHashSet();

    var partItems = (await db.RoPartItems.Where(i => i.OrgId == t.OrgId && roIds.Contains(i.RoId))
        .ToListAsync()).Where(i => i.CamID != null && camIds.Contains(i.CamID!)).ToList();
    var svcItems = (await db.RoServiceItems.Where(i => i.OrgId == t.OrgId && roIds.Contains(i.RoId))
        .ToListAsync()).Where(i => i.CamID != null && camIds.Contains(i.CamID!)).ToList();

    // Tiền: phụ tùng CÓ nhân số lượng, công KHÔNG. VAT là phần trăm.
    var partAmt = partItems.GroupBy(i => (i.RoId, i.CamID!))
        .ToDictionary(g => g.Key, g => g.Sum(i =>
            i.Factor * i.NeedQty * i.UnitPrice
          + i.Factor * i.NeedQty * i.UnitPrice * i.Vat * 0.01m));
    var svcAmt = svcItems.GroupBy(i => (i.RoId, i.CamID!))
        .ToDictionary(g => g.Key, g => g.Sum(i =>
            i.Factor * i.Price + i.Factor * i.Price * i.Vat * 0.01m));

    var keys = partAmt.Keys.Union(svcAmt.Keys).ToList();
    var roById = ros.ToDictionary(r => r.Id);
    var camByCode = cams.GroupBy(c => c.CamNo)
        .ToDictionary(g => g.Key, g => g.First());

    var rows = keys.Select(k =>
    {
        var ro = roById[k.Item1];
        camByCode.TryGetValue(k.Item2, out var cam);
        var pa = partAmt.TryGetValue(k, out var p) ? p : 0m;
        var sa = svcAmt.TryGetValue(k, out var s) ? s : 0m;
        return new
        {
            roId = ro.Id, roNo = ro.RONo, dealerCode = ro.DealerCode,
            checkInDate = ro.CheckInDate, km = ro.Km, cusRequest = ro.CusRequest,
            camId = k.Item2, camNo = cam?.CamNo, camName = cam?.CamName,
            partAmount = pa, serviceAmount = sa, sumAmount = pa + sa,
        };
    }).OrderBy(x => x.roNo).ToList();

    return Results.Ok(new
    {
        count = rows.Count,
        campaignCount = cams.Count, finishedRoCount = ros.Count,
        grandPartAmount = rows.Sum(r => r.partAmount),
        grandServiceAmount = rows.Sum(r => r.serviceAmount),
        dealerFilterOnCampaignNote = "Nguồn nhét CÙNG mệnh đề mã đại lý vào CẢ HAI bảng: Ser_Campaign ở "
            + "CSDL TRUNG TÂM và ser_ro ở CSDL đại lý. Nếu chiến dịch khai ở trung tâm dưới mã khác (hoặc "
            + "để trống) thì #tbl_cam rỗng ⇒ BÁO CÁO TRẮNG, trông y hệt 'đại lý không tham gia chiến dịch'. "
            + "MiniHTC chỉ lọc đại lý trên LỆNH SỬA.",
        // ===== #430 ĐỐI CHIẾU TWIN `Ser_CampaignDealerRpt_WH` (`WH.cs:8791-9164`) =====
        // Đếm chuỗi 8 mốc: `Status='FNS'` 1=1 · `zzzzClauseWhereDealerCodeConditionList` **5=5** ·
        //   `full outer join` 1=1 (comment cả hai bên) · `ropAmount` 4=4 · `rsiAmount` 4=4 · `group by` 5=5.
        // ⇒ **KHÔNG lệch nghiệp vụ.** Hai khác biệt duy nhất:
        //   ① `strDBName_CommonCenter` 3 ở Main, **0** ở `_WH` — bản kho đọc `Ser_Campaign` **cục bộ**
        //     thay vì CSDL trung tâm (đúng bản chất hậu tố `_WH`).
        //   ② Bản Main có **bảy** câu `drop table` dọn bảng tạm; bản `_WH` **bỏ hết**. Không đổi kết quả
        //     (bảng `#temp` tự huỷ khi phiên kết nối được đặt lại) nhưng là khác biệt về vệ sinh tài nguyên.
        // ⚠️ Bài học đo lường: lần bound đầu tôi cắt hàm Main bằng mốc `public DataSet` nên **lấn sang**
        //   hai hàm `private void CheckExistRptKPI*` phía sau ⇒ diff nhiễu. Mốc kết thúc phải gồm **cả**
        //   `private void` / `private DataSet`, không chỉ `public DataSet`.
        // 📊 Thống kê twin `_WH` tới #430: **giống nghiệp vụ 6** (#406/#407/#409/#418/#426/#430) ·
        //   **lệch thật 3** (#378/#413/#422) ⇒ 3/9.
        whTwinNote = "Ser_CampaignDealerRpt_WH: đếm chuỗi 8 mốc đều bằng nhau ⇒ KHÔNG lệch nghiệp vụ. "
            + "Khác biệt: bản kho đọc Ser_Campaign CỤC BỘ (không qua CSDL trung tâm) và bỏ hết bảy câu "
            + "drop table dọn bảng tạm.",
        twoStageAggregateNote = "KIỂM RỒI, KHÔNG phải bug: tầng gộp 1 có group by chứa chính các cột đang "
            + "sum (Factor/Price/Quantity/VAT) — nhìn như gộp sai — nhưng tầng gộp 2 gộp lại theo ROID+CamID "
            + "nên tổng cuối đúng. Hai tầng bù nhau.",
        deadBlockNote = "Khối #tmpAmount dùng full outer join đã bị COMMENT trọn vẹn; bản active là hai "
            + "khối gộp riêng rồi nối sau. Port theo dòng active.",
        amountFormulaNote = "Tiền CÔNG = Factor × Price (KHÔNG nhân số lượng); tiền PHỤ TÙNG = Factor × "
            + "Price × Quantity. VAT là PHẦN TRĂM (× 0.01). Bất đối xứng có chủ ý, giống lệ #303.",
        innerJoinNote = "Nguồn nối ser_customer/ser_car bằng nối TRONG kèm DealerCode ở cả hai vế ⇒ xe "
            + "hoặc khách lệch đại lý là MẤT DÒNG.",
        rows,
    });
}).RequireAuthorization();

app.MapGet("/api/bulletins/search", async (AppDbContext db, ITenantContext t,
    string? bulletinId, string? bulletinNo, DateTime? createDateFrom, DateTime? createDateTo,
    string? remark, string? userCreate, string? vin, bool? includeInactive, bool? getDetail) =>
{
    var qy = db.Bulletins.Where(b => b.OrgId == t.OrgId);

    // Nguồn ghim cứng Flag.Active — tham số strIsActive của service KHÔNG được dùng.
    var wantInactive = includeInactive ?? false;
    if (!wantInactive) qy = qy.Where(b => b.FlagActive == "1");

    if (!string.IsNullOrWhiteSpace(bulletinId))
        qy = qy.Where(b => b.Id.ToString() == bulletinId!.Trim());
    if (!string.IsNullOrWhiteSpace(bulletinNo))
        qy = qy.Where(b => b.BulletinNo.Contains(bulletinNo!.Trim()));
    if (createDateFrom.HasValue) qy = qy.Where(b => b.CreateDate >= createDateFrom.Value.Date);
    if (createDateTo.HasValue) qy = qy.Where(b => b.CreateDate <= createDateTo.Value.Date);

    var items = await qy.ToListAsync();

    // 🔴 Remark: nguồn HỎNG (tìm chuỗi "like…"). MiniHTC làm đúng ý định = CHỨA.
    var remarkQ = (remark ?? "").Trim();
    if (remarkQ.Length > 0)
        items = items.Where(b => (b.Remark ?? "").Contains(remarkQ, StringComparison.OrdinalIgnoreCase)).ToList();

    var userQ = (userCreate ?? "").Trim();
    if (userQ.Length > 0)
        items = items.Where(b => (b.UserCreate ?? "").Contains(userQ, StringComparison.OrdinalIgnoreCase)).ToList();

    // VIN nằm ở bảng chi tiết (Blt_Bulletin_VIN) — nguồn lọc si d.VinNo like %x%.
    var vinQ = (vin ?? "").Trim();
    List<string>? vinBulletinIds = null;
    if (vinQ.Length > 0)
    {
        vinBulletinIds = await db.BulletinVins
            .Where(v => v.OrgId == t.OrgId && v.VinNo.Contains(vinQ))
            .Select(v => v.BulletinNo).Distinct().ToListAsync();
        items = items.Where(b => vinBulletinIds.Contains(b.BulletinNo)).ToList();
    }

    var rows = items.OrderByDescending(b => b.CreateDate).Select(b => new
    {
        b.Id, b.BulletinNo, b.BulletinNoHMC, b.Remark, b.PartCode, b.PartName,
        b.SerCode, b.SerName, b.DateExpired, b.FlagActive, b.CreateDate, b.UserCreate,
        b.FileNameAttachment,
    }).ToList();

    return Results.Ok(new
    {
        count = rows.Count,
        remarkFilterBrokenInSource = true,
        remarkNote = "Trong NGUỒN, ô Ghi chú KHÔNG BAO GIỜ ra kết quả: tầng service dựng chuỗi "
            + "\"like%abc%\" (kèm toán tử) rồi đưa vào BuildClauseConditionSingle — hàm này TỰ cấp toán tử "
            + "và bind giá trị NGUYÊN VĂN ⇒ SQL thành `si.Remark like 'like%abc%'`, chỉ khớp ghi chú bắt "
            + "đầu bằng đúng chữ 'like'. MiniHTC lọc theo CHỨA, đúng ý định của màn.",
        verifiedNotABugNote = "Ba ô BulletinNo/Vin/UserCreate cũng nối \"like\" liền \"%x%\" không dấu "
            + "cách, NHƯNG chúng đi qua BuildClause — hàm này cắt theo ĐỘ DÀI toán tử nên vẫn đúng. "
            + "Chỉ Remark hỏng vì đi qua hàm khác.",
        isActiveParamDead = true,
        isActiveNote = "Service khai tham số strIsActive nhưng khi gọi WS truyền cứng Flag.Active ('1') "
            + "⇒ nguồn KHÔNG BAO GIỜ tra được bản tin đã ngừng hiệu lực. MiniHTC mở bằng includeInactive.",
        liveTwinNote = "Có 11 hàm cùng họ Blt_Bulletin_Get* trong một file; WS chỉ gọi bản _20210224.",
        upperCaseNote = "BuildClause gọi .ToUpper() lên cả GIÁ TRỊ tham số ⇒ dữ liệu lưu chữ thường có "
            + "thể không khớp trong nguồn.",
        rows,
    });
}).RequireAuthorization();

// ===== 🔴 #461 TRẢ NỢ `by-vin`: bản LIVE là `_New20221114`, KHÔNG phải `_New20210618` =====
// TRACE 4 TẦNG: `FrmQuotation` → `BltBulletin.Blt_BulletinGetByVin` (`:910`) →
//   WS **`Blt_Bulletin_Get_byVin`** (trên `_commonCenterService`, KHÁC tên hàm ở client)
//   → biz **`Blt_Bulletin_Get_byVin_New20221114`** (`BizCarSv.Bulletin.cs:3796`).
//   Cụm có **4 bản**; WS chỉ gọi bản 2022-11-14 ⇒ ba bản kia chết.
// 🔴 DIFF hai nhánh dài (luật #414) — 2022-11-14 so với 2021-06-18 thêm ĐÚNG hai thứ:
//   (1) tham số lọc **`strDateExpiredConditionList`** → `BuildClause("and", "b.DateExpired", …)`;
//   (2) cột **`bb.BulletinNoHMC`** vào HAI bảng kết quả. WHERE còn lại y hệt.
//   ⇒ Port cũ thiếu **bộ lọc hạn hiệu lực**; bổ sung `expiredFrom`/`expiredTo` ở đây.
//
// 🔴 TẦNG SERVICE **THAY** tham số của người gọi: hàm nhận `strIsActive` nhưng khi gọi WS lại truyền
//   `Constants.Flag.Active` (= "1") **đóng cứng** ⇒ tham số `strIsActive` của client **không bao giờ tới
//   được biz**. Người gọi tưởng tra được thông báo đã ngừng, thực tế **luôn chỉ ra bản đang hiệu lực**.
//   Giữ tham số `active` của MiniHTC (hữu dụng hơn) nhưng nêu cờ `sourceForcesActiveOnly`.
// ⚪ KIỂM TRA ÂM TÍNH (đừng kết luận vội): service ghép chuỗi `Append("like"); Append("%x%")` ⇒ ra
//   `"like%x%"` **KHÔNG có dấu cách**. Đọc `BuildClause` (`DataUtils.cs:1074`): nó `Trim().ToUpper()` rồi
//   `StartsWith("LIKE")` ⇒ **vẫn nhận đúng toán tử**, điều kiện KHÔNG chết. (`strUserCreate` thì có dấu
//   cách — hai lối viết khác nhau, cùng kết quả.) Ghi lại để lượt sau khỏi báo nhầm "bộ lọc chết".
// ⚠️ Khoảng ngày tạo ghép bằng dấu `|`: `">= từ"` và `"<= đến"` — hai điều kiện trong MỘT chuỗi.
// ⚠️ Tham số vị trí thứ 4 khi gọi WS luôn là `""` (một ô điều kiện bỏ trống cố định).
app.MapGet("/api/bulletins/by-vin", async (AppDbContext db, ITenantContext t,
    string? vins, string? dealers, string? status, string? active,
    string? bulletinNo, string? remark, string? userCreate,
    DateTime? createFrom, DateTime? createTo,
    DateTime? expiredFrom, DateTime? expiredTo) =>
{
    List<string> Split(string? s) => (s ?? "").Split('|', StringSplitOptions.RemoveEmptyEntries)
        .Select(x => x.Trim().ToUpperInvariant()).Where(x => x.Length > 0).ToList();

    var vinList = Split(vins);
    var dealerList = Split(dealers);
    var statusList = Split(status);

    var linkQ = db.BulletinVins.Where(x => x.OrgId == t.OrgId);
    if (vinList.Count > 0) linkQ = linkQ.Where(x => x.VinNo != null && vinList.Contains(x.VinNo));
    if (dealerList.Count > 0) linkQ = linkQ.Where(x => x.DealerCode != null && dealerList.Contains(x.DealerCode));
    var links = await linkQ.ToListAsync();

    // Trống hiểu là "P" — đúng nguồn (isnull(bv.Status, 'P')). Lọc trạng thái áp SAU khi đã bù mặc định.
    var linkRows = links.Select(x => new
    {
        x.BulletinNo, x.VinNo, x.DealerCode,
        Status = string.IsNullOrWhiteSpace(x.Status) ? "P" : x.Status!,
    }).ToList();
    if (statusList.Count > 0) linkRows = linkRows.Where(x => statusList.Contains(x.Status.ToUpperInvariant())).ToList();

    var nos = linkRows.Select(x => x.BulletinNo).Distinct().ToList();
    var bq = db.Bulletins.Where(b => b.OrgId == t.OrgId && nos.Contains(b.BulletinNo));
    if (!string.IsNullOrWhiteSpace(active)) bq = bq.Where(b => b.FlagActive == active!.Trim());
    // #461: ba bộ lọc LIKE của tầng service (BulletinNo · Remark · UserCreate) + khoảng ngày tạo.
    if (!string.IsNullOrWhiteSpace(bulletinNo))
        bq = bq.Where(b => b.BulletinNo.Contains(bulletinNo!.Trim()));
    if (!string.IsNullOrWhiteSpace(remark))
        bq = bq.Where(b => b.Remark != null && b.Remark.Contains(remark!.Trim()));
    if (!string.IsNullOrWhiteSpace(userCreate))
        bq = bq.Where(b => b.UserCreate != null && b.UserCreate.Contains(userCreate!.Trim()));
    if (createFrom.HasValue) bq = bq.Where(b => b.CreateDate >= createFrom);
    if (createTo.HasValue) bq = bq.Where(b => b.CreateDate <= createTo);
    // #461 CỘT MỚI CỦA BẢN 2022-11-14: lọc theo hạn hiệu lực `b.DateExpired`.
    if (expiredFrom.HasValue) bq = bq.Where(b => b.DateExpired >= expiredFrom);
    if (expiredTo.HasValue) bq = bq.Where(b => b.DateExpired <= expiredTo);

    var bulletins = await bq.Select(b => new
    {
        b.BulletinNo, b.BulletinNoHMC, b.Remark, b.CreateDate, b.UserCreate,
        b.FileNameAttachment,
        // KHÔNG lấy theo số thông báo đóng cứng như nguồn — lấy đúng tệp của chính dòng này.
        b.FileAttachment,
        b.FlagActive, b.DateExpired,
    }).ToListAsync();

    return Results.Ok(new
    {
        count = bulletins.Count, bulletins,
        vinLinks = linkRows,
        vinFilter = vinList, dealerFilter = dealerList, statusFilter = statusList,
        hardcodedTestBulletinInSource = "TEST201911",
        divergenceNote = "Nguồn lấy FileAttachment bằng truy vấn con đóng cứng BulletinNo = 'TEST201911' "
            + "(không tương quan dòng nào) ⇒ mọi thông báo nhận tệp của một bản ghi TEST. MiniHTC trả đúng "
            + "tệp của từng thông báo — CỐ Ý khác nguồn, cần nghiệp vụ xác nhận.",
        duplicateColumnNote = "Nguồn select `bb.CreateDate` HAI LẦN ⇒ ADO trả CreateDate và CreateDate1; "
            + "map theo chỉ số cột sẽ lệch.",
        bakeParamMixNote = "Nguồn trộn bake + param trên cùng token @strIsActive (Replace thay giá trị thô, "
            + "không bọc nháy). Port dùng tham số thật.",
        statusDefaultNote = "Status của dòng VIN trống ⇒ hiểu là 'P' (chờ xử lý), đúng nguồn.",
        // ===== #461 =====
        sourceForcesActiveOnly = true,
        liveBizNote = "WS gọi Blt_Bulletin_Get_byVin_New20221114 (Bulletin.cs:3796); ba bản còn lại của "
            + "cụm 4 bản là code chết. Bản 2022-11-14 thêm bộ lọc DateExpired và cột BulletinNoHMC.",
        likeWithoutSpaceIsHarmless = true,
    });
}).RequireAuthorization();

app.MapGet("/api/bulletins/{no}/details", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var row = await db.Bulletins.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.BulletinNo == no);
    if (row is null) return Results.NotFound(new { no });
    var details = await db.BulletinDtls.Where(d => d.OrgId == t.OrgId && d.BulletinNo == no)
        .Select(d => new { d.SerCode, d.SerName, d.PartCode, d.PartName }).ToListAsync();
    var vins = await db.BulletinVins.Where(v => v.OrgId == t.OrgId && v.BulletinNo == no)
        .Select(v => new { v.VinNo, v.DealerCode, v.Status }).ToListAsync();
    return Results.Ok(new
    {
        row.BulletinNo, row.BulletinNoHMC, row.Remark, row.CreateDate, row.UserCreate,
        row.DateExpired, row.FileNameAttachment, row.FlagActive,
        details, vins,
        pendingVins = vins.Count(v => v.Status == "P")
    });
}).RequireAuthorization();

// Đại lý cập nhật trạng thái xử lý của MỘT xe trên bản tin (FrmBulletinDealerSearch).
app.MapPost("/api/bulletins/{no}/vins/{vin}/status", async (
    string no, string vin, BulletinVinStatusDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    vin = vin.Trim().ToUpperInvariant();
    var row = await db.BulletinVins.FirstOrDefaultAsync(v => v.OrgId == t.OrgId && v.BulletinNo == no && v.VinNo == vin);
    if (row is null) return Results.NotFound(new { no, vin });
    var status = (dto.Status ?? "").Trim().ToUpperInvariant();
    if (string.IsNullOrWhiteSpace(status)) return Results.BadRequest(new { error = "Chưa chọn trạng thái." });
    row.Status = status;
    await db.SaveChangesAsync();
    return Results.Ok(new { row.BulletinNo, row.VinNo, row.Status });
}).RequireAuthorization();

app.MapPost("/api/bulletins/{no}/toggle", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var x = await db.Bulletins.FirstOrDefaultAsync(v => v.OrgId == t.OrgId && v.BulletinNo == no);
    if (x is null) return Results.NotFound(new { no });
    x.FlagActive = x.FlagActive == "1" ? "0" : "1";
    await db.SaveChangesAsync();
    return Results.Ok(new { x.BulletinNo, flagActive = x.FlagActive });
}).RequireAuthorization();

// ===== Báo giá phụ tùng dịch vụ (PartQuote header-detail — port 1:1 FrmPartQuotation/Search, TCMotor) =====
app.MapGet("/api/partquotes", async (AppDbContext db, ITenantContext t, string? q, string? status) =>
{
    var query = db.PartQuotes.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(q)) query = query.Where(x => x.QuoteNo.Contains(q!) || (x.CusName != null && x.CusName.Contains(q!)));
    if (!string.IsNullOrWhiteSpace(status)) query = query.Where(x => x.Status == status);
    var items = await query.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.QuoteNo, x.CusId, x.CusName, x.Mobile, x.ReceiveName, x.PaymentMethod, x.TotalAmount, x.Status,
        createdAt = x.CreatedAt.ToString("yyyy-MM-dd"),
        x.SumAmountNoFactor,
        lines = db.PartQuoteLines.Count(l => l.OrgId == t.OrgId && l.PartQuoteId == x.Id)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Tạo báo giá (header + dòng phụ tùng; tính Amount=Qty*Price*(1+VAT/100) + tổng).
app.MapPost("/api/partquotes", async (PartQuoteDto dto, AppDbContext db, ITenantContext t) =>
{
    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.PartCode)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Chưa có dòng phụ tùng." });
    if (lines.Any(l => l.Quantity <= 0)) return Results.BadRequest(new { error = "Số lượng phải lớn hơn 0." });
    var no = "PQ" + DateTime.Now.ToString("yyMMddHHmmss");
    var h = new PartQuote { OrgId = t.OrgId, QuoteNo = no, CusId = dto.CusId, CusName = dto.CusName, Mobile = dto.Mobile, ReceiveName = dto.ReceiveName, PaymentMethod = dto.PaymentMethod, Remark = dto.Remark, Status = "Draft" };
    db.PartQuotes.Add(h); await db.SaveChangesAsync();
    decimal total = 0m, sumAmountNoFactor = 0m;
    foreach (var l in lines)
    {
        // Hệ số giảm giá: nguồn đọc `isnull(sst.Factor, 1)` ⇒ không nhập thì coi như 1 (không giảm).
        var factor = l.Factor ?? 1m;
        // Công thức nguyên văn nguồn (Issue 813) — hệ số nhân vào CẢ phần gốc LẪN phần thuế:
        //   Amount = Qty*Price*Factor + Qty*Price*0.01*VAT*Factor
        var amountBeforeVat = l.Quantity * l.UnitPrice * factor;
        var amount = amountBeforeVat + l.Quantity * l.UnitPrice * (l.Vat / 100m) * factor;
        total += amount;
        // 🔴 Cột SumAmount của nguồn tính KHÔNG có Factor:
        //   sum(Qty*Price + Qty*Price*0.01*VAT)
        // Nguồn bất đối xứng giữa dòng và tổng — giữ nguyên cả hai, không tự sửa cho khớp.
        sumAmountNoFactor += l.Quantity * l.UnitPrice * (1 + l.Vat / 100m);
        db.PartQuoteLines.Add(new PartQuoteLine
        {
            OrgId = t.OrgId, PartQuoteId = h.Id,
            PartCode = l.PartCode.Trim().ToUpperInvariant(), PartName = l.PartName, Unit = l.Unit,
            Quantity = l.Quantity, UnitPrice = l.UnitPrice, Vat = l.Vat,
            Factor = factor, PartPriceId = l.PartPriceId, Note = l.Note,
            AmountBeforeVat = amountBeforeVat, Amount = amount
        });
    }
    h.TotalAmount = total;
    h.SumAmountNoFactor = sumAmountNoFactor;
    await db.SaveChangesAsync();
    return Results.Ok(new { h.QuoteNo, lines = lines.Count, totalAmount = total, sumAmountNoFactor });
}).RequireAuthorization();

app.MapGet("/api/partquotes/{no}/lines", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.PartQuotes.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.QuoteNo == no);
    if (h is null) return Results.NotFound(new { no });
    // ===== 🔴 #313 TIỀN DÒNG BÁO GIÁ: nguồn TÍNH LÚC ĐỌC, không lưu =====
    // 🆕 Tìm ra nhờ sweep `_audit/sweep_stored_vs_derived.js` (sinh từ sự cố #312) rồi **kiểm tay**:
    //   `Amount`/`AmountBeforeVAT` chỉ xuất hiện làm alias trong `Inventory.Quote.cs:2070-2071` và
    //   **không có chỗ nào GHI** (đã grep `Rows[0][…]` / `strFN` / `alColumnEffective` — rỗng).
    // Công thức nguồn (Issue 813 — hệ số nhân vào CẢ phần gốc LẪN phần thuế):
    //   `Amount          = Qty*Price*Factor + Qty*Price*0.01*VAT*Factor`
    //   `AmountBeforeVAT = Qty*Price*Factor`
    // ⚠️ MiniHTC tính lúc GHI rồi lưu. **Không** phải lỗ hổng như #312 (DTO không nhận hai cột này),
    //   nhưng vẫn LỆCH PHA được nếu về sau có đường sửa Qty/Price/Factor/Vat mà quên tính lại.
    //   ⇒ Đọc thì TÍNH LẠI như nguồn; trả kèm giá trị LƯU + cờ `amountStale` để phát hiện lệch.
    var rows = await db.PartQuoteLines.Where(l => l.OrgId == t.OrgId && l.PartQuoteId == h.Id).ToListAsync();
    var lines = rows.Select(l =>
    {
        var beforeVat = l.Quantity * l.UnitPrice * l.Factor;
        var amount = beforeVat + l.Quantity * l.UnitPrice * 0.01m * l.Vat * l.Factor;
        return new
        {
            l.PartCode, l.PartName, l.Unit, l.Quantity, l.UnitPrice, l.Vat, l.Factor, l.PartPriceId, l.Note,
            amountBeforeVat = beforeVat, amount,
            // giá trị đang LƯU — để đối chiếu, không dùng để hiển thị
            amountBeforeVatStored = l.AmountBeforeVat, amountStored = l.Amount,
            amountStale = l.Amount != amount || l.AmountBeforeVat != beforeVat,
        };
    }).ToList();
    return Results.Ok(new { h.QuoteNo, h.CusName, h.Status, h.TotalAmount, h.SumAmountNoFactor,
        count = lines.Count,
        // Tổng TÍNH LẠI từ dòng — nếu khác `TotalAmount` đang lưu thì dữ liệu đã lệch pha.
        totalAmountRecomputed = lines.Sum(x => x.amount),
        anyStale = lines.Any(x => x.amountStale),
        note = "Tiền dòng TÍNH LẠI theo nguồn (Issue 813: hệ số nhân cả phần gốc lẫn phần thuế). "
             + "amountStale = true nghĩa là giá trị đang lưu đã lệch so với Qty/Price/Factor/Vat hiện tại.",
        lines });
}).RequireAuthorization();

// Chuyển trạng thái báo giá: Draft->Sent->Approved (hoặc cancel).
// 🔴 Bộ trạng thái báo giá phụ tùng theo ĐÚNG nguồn (TConst.Ser_Inv_Quote_Status).
// Port cũ TỰ CHẾ một luồng gửi/duyệt (Draft→Sent→Approved→Cancelled) — nguồn KHÔNG có khái niệm đó.
// Nguồn theo dõi báo giá bám theo VÒNG ĐỜI PHIẾU XUẤT sinh ra từ nó:
var partQuoteStatusSourceCodes = new Dictionary<string, string>
{
    ["Created"] = "1",        // Mới tạo
    ["Rejected"] = "2",       // Báo giá huỷ
    ["SOOCreated"] = "3",     // Đã tạo phiếu xuất (lệnh xuất kho)
    ["SOIssued"] = "4",       // Đã xuất
    ["SOAdjusted"] = "5",     // Đã điều chỉnh phiếu xuất
    ["SORejected"] = "6",     // Đã huỷ phiếu xuất
};

// Ánh xạ giá trị port CŨ → trạng thái nguồn, để dữ liệu đã tạo vẫn đọc được.
var partQuoteLegacyStatusMap = new Dictionary<string, string>
{
    ["Draft"] = "Created",
    ["Sent"] = "Created",       // nguồn không có bước "đã gửi" riêng
    ["Approved"] = "SOOCreated",
    ["Cancelled"] = "Rejected",
};

app.MapGet("/api/partquotes/statuses", () => Results.Ok(new
{
    statuses = partQuoteStatusSourceCodes.Select(kv => new { status = kv.Key, sourceCode = kv.Value }),
    legacyMap = partQuoteLegacyStatusMap.Select(kv => new { legacy = kv.Key, status = kv.Value }),
    note = "Nguồn theo dõi báo giá bám vòng đời phiếu xuất; KHÔNG có bước gửi/duyệt như port cũ."
})).RequireAuthorization();

app.MapPost("/api/partquotes/{no}/{action}", async (string no, string action, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.PartQuotes.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.QuoteNo == no);
    if (h is null) return Results.NotFound(new { no });

    // Quy trạng thái cũ về trạng thái nguồn trước khi xét chuyển tiếp.
    var current = partQuoteLegacyStatusMap.TryGetValue(h.Status, out var mapped) ? mapped : h.Status;

    // 🔴 Guard của biz (Ser_Inv_Quote_Delete): báo giá ĐÃ XUẤT (SOIssued) thì KHÔNG được xoá/huỷ —
    // chỉ 4 trạng thái Created/Rejected/SOOCreated mới cho gỡ phiếu xuất đi kèm.
    string[] cancellableStatuses = { "Created", "SOOCreated" };

    string next = action switch
    {
        "createsoo" => current == "Created" ? "SOOCreated" : "",
        "issue" => current == "SOOCreated" ? "SOIssued" : "",
        "adjustso" => current == "SOIssued" ? "SOAdjusted" : "",
        "rejectso" => current is "SOIssued" or "SOAdjusted" ? "SORejected" : "",
        "cancel" => cancellableStatuses.Contains(current) ? "Rejected" : "",
        _ => "?"
    };
    if (next == "?") return Results.BadRequest(new { error = "action = createsoo|issue|adjustso|rejectso|cancel" });
    if (next == "")
    {
        if (action == "cancel" && current == "SOIssued")
            return Results.BadRequest(new { error = "Báo giá đã xuất hàng, không huỷ được (dùng rejectso để huỷ phiếu xuất)." });
        return Results.BadRequest(new { error = $"Không thể {action} khi đang ở trạng thái {current}." });
    }

    h.Status = next; await db.SaveChangesAsync();
    return Results.Ok(new { h.QuoteNo, status = h.Status, sourceCode = partQuoteStatusSourceCodes[next] });
}).RequireAuthorization();

// ===== Hợp đồng bảo hiểm dịch vụ (InsContract — port 1:1 FrmInsuranceContractCreate/Search, TCMotor) =====
app.MapGet("/api/inscontracts", async (AppDbContext db, ITenantContext t, string? q, string? ins, string? active) =>
{
    var query = db.InsContracts.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(q)) query = query.Where(x => x.InContractNo.Contains(q!) || (x.InsName != null && x.InsName.Contains(q!)));
    if (!string.IsNullOrWhiteSpace(ins)) query = query.Where(x => x.InsNo == ins);
    if (!string.IsNullOrWhiteSpace(active)) query = query.Where(x => x.FlagActive == active);
    var items = await query.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.InContractNo, x.InContractCode, x.InsNo, x.InsName, x.PaymentLimit, x.TypePayment, x.FlagActive,
        startDate = x.StartDate.HasValue ? x.StartDate.Value.ToString("yyyy-MM-dd") : "",
        finishDate = x.FinishDate.HasValue ? x.FinishDate.Value.ToString("yyyy-MM-dd") : ""
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Tạo/cập nhật HĐ bảo hiểm (số HĐ trống = auto-gen). Guard ngày hết hạn >= ngày hiệu lực.
app.MapPost("/api/inscontracts", async (InsContractDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.InsNo)) return Results.BadRequest(new { error = "Chưa chọn nhà bảo hiểm." });
    if (dto.PaymentLimit < 0) return Results.BadRequest(new { error = "Hạn mức chi trả không hợp lệ." });
    if (dto.StartDate.HasValue && dto.FinishDate.HasValue && dto.FinishDate < dto.StartDate)
        return Results.BadRequest(new { error = "Ngày hết hạn phải sau ngày hiệu lực." });
    var no = string.IsNullOrWhiteSpace(dto.InContractNo) ? "IC" + DateTime.Now.ToString("yyMMddHHmmss") : dto.InContractNo.Trim().ToUpperInvariant();
    var ex = await db.InsContracts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.InContractNo == no);
    if (ex is not null)
    {
        ex.InContractCode = dto.InContractCode; ex.InsNo = dto.InsNo; ex.InsName = dto.InsName; ex.StartDate = dto.StartDate; ex.FinishDate = dto.FinishDate; ex.PaymentLimit = dto.PaymentLimit; ex.TypePayment = dto.TypePayment; ex.FlagActive = "1";
        await db.SaveChangesAsync();
        return Results.Ok(new { ex.InContractNo, updated = true });
    }
    var r = new InsContract { OrgId = t.OrgId, InContractNo = no, InContractCode = dto.InContractCode, InsNo = dto.InsNo, InsName = dto.InsName, StartDate = dto.StartDate, FinishDate = dto.FinishDate, PaymentLimit = dto.PaymentLimit, TypePayment = dto.TypePayment, FlagActive = "1" };
    db.InsContracts.Add(r); await db.SaveChangesAsync();
    return Results.Ok(new { r.InContractNo, updated = false });
}).RequireAuthorization();

app.MapPost("/api/inscontracts/{no}/toggle", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var x = await db.InsContracts.FirstOrDefaultAsync(v => v.OrgId == t.OrgId && v.InContractNo == no);
