        ex.CusTypeName = dto.CusTypeName; ex.CusFactor = dto.CusFactor; ex.CusPersonType = person; ex.FlagActive = "1";
        await db.SaveChangesAsync();
        return Results.Ok(new { ex.CusTypeCode, updated = true });
    }
