{
    var qry = db.InsuranceAttachmentTypes.Where(x => x.OrgId == t.OrgId);
    if (all != true) qry = qry.Where(x => x.Status == "1");
    var items = await qry.OrderBy(x => x.Code).Take(500).Select(x => new { x.Code, x.Name, x.Note, x.Status }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/insuranceattachmenttypes", async (InsuranceAttachmentTypeDto dto, AppDbContext db, ITenantContext t) =>
{
    var code = (dto.Code ?? "").Trim();
    if (string.IsNullOrWhiteSpace(code)) return Results.BadRequest(new { error = "Chưa nhập mã tài liệu." });
    var row = await db.InsuranceAttachmentTypes.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Code == code);
    if (row is null) { row = new InsuranceAttachmentType { OrgId = t.OrgId, Code = code }; db.InsuranceAttachmentTypes.Add(row); }
    row.Name = dto.Name; row.Note = dto.Note; row.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { row.Code, row.Name });
}).RequireAuthorization();

// Trả toàn bộ danh mục kèm cờ đã-có cho 1 RO (khớp checklist tích-chọn trong FrmInsuranceAttachmentAdd).
app.MapGet("/api/insuranceattachments/{roNo}", async (string roNo, AppDbContext db, ITenantContext t) =>
{
    roNo = roNo.Trim().ToUpperInvariant();
    var types = await db.InsuranceAttachmentTypes.Where(x => x.OrgId == t.OrgId && x.Status == "1").OrderBy(x => x.Code).ToListAsync();
    var have = (await db.InsuranceAttachments.Where(x => x.OrgId == t.OrgId && x.RONo == roNo).Select(x => x.AttachmentCode).ToListAsync()).ToHashSet();
    var items = types.Select(x => new { x.Code, x.Name, x.Note, ischecked = have.Contains(x.Code) });
    return Results.Ok(new { roNo, items });
}).RequireAuthorization();

// Lưu bộ tài liệu đã tích chọn cho 1 RO — thay toàn bộ set (khớp btnSave gốc: lưu lại cả danh sách check).
app.MapPost("/api/insuranceattachments/{roNo}", async (string roNo, InsuranceAttachmentSaveDto dto, AppDbContext db, ITenantContext t) =>
{
    roNo = roNo.Trim().ToUpperInvariant();
    var codes = (dto.Codes ?? new List<string>()).Select(x => x.Trim()).Where(x => x.Length > 0).Distinct().ToList();
    if (codes.Count == 0) return Results.BadRequest(new { error = "Chưa tích chọn tài liệu nào." });
    var old = db.InsuranceAttachments.Where(x => x.OrgId == t.OrgId && x.RONo == roNo);
    db.InsuranceAttachments.RemoveRange(old);
    foreach (var c in codes) db.InsuranceAttachments.Add(new InsuranceAttachment { OrgId = t.OrgId, RONo = roNo, AttachmentCode = c });
    await db.SaveChangesAsync();
    return Results.Ok(new { roNo, count = codes.Count });
}).RequireAuthorization();

// ===== Chiến dịch marketing HTC gửi đại lý (CampaignMarketing — port 1:1 FrmSer_CampaignMarketing/Mng, TCMotor DMSCarSv/Ser_CampaignMarketing) =====
app.MapGet("/api/campaignmarketings", async (AppDbContext db, ITenantContext t, string? q) =>
{
    var qry = db.CampaignMarketings.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(q)) qry = qry.Where(x => x.CamNo.Contains(q!) || x.CamName.Contains(q!));
    var items = await qry.OrderByDescending(x => x.Id).Take(500).Select(x => new
    { x.CamNo, x.CamName, x.CamDesc, x.EffDateStart, x.EffDateEnd, x.ConditionDealer, parts = db.CampaignMarketingParts.Count(p => p.OrgId == t.OrgId && p.CampaignId == x.Id) }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// ===== 🔴 #482 NHÁNH KHO TRẢ THÊM MỘT BẢNG KẾT QUẢ — `Ser_CampaignMarketingFullVIN` =====
// DIFF `Ser_CampaignMarketing_Get` (Main, 55 dòng SQL) vs `…_Get_WH` (63) — **chi o main = 0**, và
//   toàn bộ phần dôi là MỘT khối truy vấn phụ mà bản Main không có:
//     `select t.MyIdxSeq, scmfv.* from #tbl_Ser_CampaignMarketing_Filter t`
//     `inner join Ser_CampaignMarketingFullVIN scmfv on t.CamMarketingNo = scmfv.CamMarketingNo`
//     `order by t.MyIdxSeq asc`
//   ⇒ Khác biệt là **HÌNH DẠNG KẾT QUẢ** (số bảng trả về), không phải bộ lọc — đúng loại mà §12 không bắt.
// ⚠️ Khối này nằm trong `#region // bGet_Ser_CampaignMarketingFullVIN:` — tên vùng gợi ý từng có cờ bật/tắt,
//   nhưng **không còn `if` nào**: biến khởi tạo `"-- Nothing."` rồi bị gán đè **vô điều kiện**.
//   Port theo dòng ACTIVE ⇒ nhánh kho **luôn** trả bảng này.
// ⚠️ Nguồn nối theo **SỐ chiến dịch** (`CamMarketingNo`), không theo khoá nội bộ ⇒ entity giữ `CamNo`.
// 📌 Trả nợ một phần của #392/#393: trong năm bảng con (VIN · PlateNo · Dealer · FullVIN · Part),
//   nay đã mô hình hoá **Part** (cũ) + **FullVIN** (lượt này); còn **ba** bảng ⇒ cờ `childTablesNotModelled`
//   vẫn giữ cho ba cái còn lại.
app.MapGet("/api/campaignmarketings/{no}", async (string no, AppDbContext db, ITenantContext t,
    string? scope) =>
{
    no = no.Trim().ToUpperInvariant();
    var c = await db.CampaignMarketings.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CamNo == no);
    if (c is null) return Results.NotFound(new { no });
    var parts = await db.CampaignMarketingParts.Where(p => p.OrgId == t.OrgId && p.CampaignId == c.Id).Select(p => new { p.PartCode, p.PercentDiscount }).ToListAsync();
    // Chỉ nhánh KHO mới kèm danh sách VIN đầy đủ (đúng nguồn).
    var isWh = string.Equals(scope?.Trim(), "wh", StringComparison.OrdinalIgnoreCase);
    var fullVins = isWh
        ? await db.CampaignMarketingFullVins.Where(v => v.OrgId == t.OrgId && v.CamNo == c.CamNo)
            .OrderBy(v => v.MyIdxSeq)
            .Select(v => new { v.VinNo, v.CamMarketingFullVinStatus, v.MyIdxSeq }).ToListAsync()
        : null;
    return Results.Ok(new
    {
        c.CamNo, c.CamName, c.CamDesc, c.EffDateStart, c.EffDateEnd, c.WarrantyDateStart,
        c.WarrantyDateEnd, c.ConditionVin, c.ConditionPlateNo, c.ConditionDealer, parts,
        scope = isWh ? "wh" : "main",
        fullVins,
        fullVinOnlyInWhBranch = true,
        fullVinAlwaysIncludedInWh = true,
        // #483: ba bảng con còn lại đã mô hình hoá ⇒ trả luôn, không còn nợ.
        vins = await db.CampaignMarketingVins.Where(v => v.OrgId == t.OrgId && v.CamNo == c.CamNo)
            .OrderBy(v => v.VIN).Select(v => new { v.VIN, v.CamMarketingVinStatus }).ToListAsync(),
        plateNos = await db.CampaignMarketingPlateNos.Where(v => v.OrgId == t.OrgId && v.CamNo == c.CamNo)
            .OrderBy(v => v.StartPlateNo).Select(v => new { v.StartPlateNo, v.CamMarketingPlateNoStatus }).ToListAsync(),
        dealers = await db.CampaignMarketingDealers.Where(v => v.OrgId == t.OrgId && v.CamNo == c.CamNo)
            .OrderBy(v => v.DealerCode).Select(v => new { v.DealerCode, v.CamMarketingDealerStatus }).ToListAsync(),
        childTablesNotModelled = Array.Empty<string>(),
        plateNoIsListNotRange = true,
        childRowsHaveNoAuditColumns = true,
        dualWriteInSource = true,
    });
}).RequireAuthorization();

// #483 §12: ghi ba bảng con còn lại. Cùng lệ "XOÁ SẠCH rồi ghi lại" của #393.
// ⚠️ Trạng thái khởi tạo = "P" (hằng CamMarketingStatus.Pending) — bảng mã chỉ có P/A, không có mã từ chối.
app.MapPost("/api/campaignmarketings/{no}/scope", async (string no, CampaignScopeDto dto,
    AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var c = await db.CampaignMarketings.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CamNo == no);
    if (c is null) return Results.NotFound(new { no });
    static List<string> Norm(List<string>? xs) => (xs ?? new List<string>())
        .Select(x => (x ?? "").Trim().ToUpperInvariant()).Where(x => x.Length > 0).Distinct().ToList();
    var vins = Norm(dto.Vins); var plates = Norm(dto.StartPlateNos); var dealers = Norm(dto.DealerCodes);
    if (vins.Count == 0 && plates.Count == 0 && dealers.Count == 0)
        return Results.BadRequest(new { error = "Cần ít nhất một trong: Vins, StartPlateNos, DealerCodes." });

    var status = string.IsNullOrWhiteSpace(dto.Status) ? "P" : dto.Status!.Trim().ToUpperInvariant();
    if (status != "P" && status != "A")
        return Results.BadRequest(new { error = "Trạng thái chỉ nhận P (chờ duyệt) hoặc A (đã duyệt)." });

    var removed = 0;
    if (vins.Count > 0)
    {
        var old = await db.CampaignMarketingVins.Where(v => v.OrgId == t.OrgId && v.CamNo == no).ToListAsync();
        removed += old.Count; db.CampaignMarketingVins.RemoveRange(old);
        foreach (var v in vins) db.CampaignMarketingVins.Add(new CampaignMarketingVin
            { OrgId = t.OrgId, CamNo = no, VIN = v, CamMarketingVinStatus = status });
    }
    if (plates.Count > 0)
    {
        var old = await db.CampaignMarketingPlateNos.Where(v => v.OrgId == t.OrgId && v.CamNo == no).ToListAsync();
        removed += old.Count; db.CampaignMarketingPlateNos.RemoveRange(old);
        foreach (var v in plates) db.CampaignMarketingPlateNos.Add(new CampaignMarketingPlateNo
            { OrgId = t.OrgId, CamNo = no, StartPlateNo = v, CamMarketingPlateNoStatus = status });
    }
    if (dealers.Count > 0)
    {
        var old = await db.CampaignMarketingDealers.Where(v => v.OrgId == t.OrgId && v.CamNo == no).ToListAsync();
        removed += old.Count; db.CampaignMarketingDealers.RemoveRange(old);
        foreach (var v in dealers) db.CampaignMarketingDealers.Add(new CampaignMarketingDealer
            { OrgId = t.OrgId, CamNo = no, DealerCode = v, CamMarketingDealerStatus = status });
    }
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        camNo = no, status,
        vinCount = vins.Count, plateNoCount = plates.Count, dealerCount = dealers.Count,
        replacedRows = removed,
        replaceNotMergeSemantics = true,   // đúng lệ #393: gửi thiếu là MẤT phần còn lại
    });
}).RequireAuthorization();

// #482 §12: ghi danh sách VIN đầy đủ của chiến dịch (bảng con thứ năm).
app.MapPost("/api/campaignmarketings/{no}/fullvins", async (string no, CampaignFullVinDto dto,
    AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var c = await db.CampaignMarketings.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CamNo == no);
    if (c is null) return Results.NotFound(new { no });
    var vins = (dto.VinNos ?? new List<string>()).Select(x => (x ?? "").Trim().ToUpperInvariant())
        .Where(x => x.Length > 0).Distinct().ToList();
    if (vins.Count == 0) return Results.BadRequest(new { error = "Cần ít nhất một VIN." });
    // Nguồn SỬA = XOÁ SẠCH rồi ghi lại (#393) — giữ đúng lệ đó cho bảng con này.
    var old = await db.CampaignMarketingFullVins.Where(v => v.OrgId == t.OrgId && v.CamNo == no).ToListAsync();
    db.CampaignMarketingFullVins.RemoveRange(old);
    var seq = 0;
    foreach (var v in vins)
        db.CampaignMarketingFullVins.Add(new CampaignMarketingFullVin
        {
            OrgId = t.OrgId, CamNo = no, VinNo = v, MyIdxSeq = ++seq,
            CamMarketingFullVinStatus = dto.Status ?? "P",
        });
    await db.SaveChangesAsync();
    return Results.Ok(new { camNo = no, count = vins.Count, replacedRows = old.Count });
}).RequireAuthorization();

// Khớp checkForm() + btnApply_Click gốc: guard tên/nội dung/ngày bắt buộc, PercentDiscount 0-100, PartCode không trùng trong 1 lần tạo.
// ===== 🔴 #392 DUYỆT CHIẾN DỊCH MARKETING (`FrmSer_CampaignMarketingDetail`) =====
// TRACE TWIN 4 tầng: `FrmSer_CampaignMarketingDetail.cs:1001` → `Ser_CampaignMarketingService.cs:425`
//   → WS `Ser_CampaignMarketing_Approve` → biz **`Ser_CampaignMarketing_Approve_20220926`**
//   (`CampaignMarketing/BizCarSv.CampaignMarketing.cs:7163`, chú thích tác giả `//ToanNH`).
//   ⚠️ Có **BA** hàm cùng tên gốc trong **HAI thư mục trùng tên file**
//     (`BizCarSv.CampaignMarketing/` và `CampaignMarketing/`) — WS chỉ gọi bản `_20220926`.
//
// 🔴 **DUYỆT LAN TRẠNG THÁI XUỐNG SÁU BẢNG** trong một câu lệnh:
//     `CamMarketingStatus` (chiến dịch) · `CamMarketingVINStatus` · `CamMarketingPlateNoStatus`
//     · `CamMarketingDealerStatus` · `CamMarketingFullVINStatus` · `CamMarketingPartStatus`
//   ⇒ Duyệt **không chỉ đổi một cột ở đầu**; bỏ sót bảng con nào là bảng đó vĩnh viễn kẹt ở `P`.
// 🔴 Guard: `Ser_CampaignMarketing_CheckDB(…, CamMarketingStatus.Pending, …)` ⇒ **chỉ duyệt được
//   khi đang ở `P`**; đã `A` thì không duyệt lại.
// ⚠️ Bảng mã chỉ có **HAI** giá trị: `P` = chờ duyệt · `A` = đã duyệt. Không có mã từ chối.
// ⚠️ Tầng service truyền `Remark` = **null khi rỗng** (không phải chuỗi rỗng) — giữ đúng phân biệt.
// 📌 MiniHTC hiện chỉ có bảng con `CampaignMarketingPart`; bốn bảng VIN/PlateNo/Dealer/FullVIN chưa
//   mô hình hoá ⇒ trả cờ `childTablesNotModelled` thay vì lặng lẽ bỏ qua.
// ===== 🔴 #393 SỬA + XOÁ chiến dịch marketing (cùng màn `FrmSer_CampaignMarketingDetail`) =====
// TRACE TWIN: WS `Ser_CampaignMarketing_Update` → biz **`…_Update_20220626`** (`:5385`);
//             WS `Ser_CampaignMarketing_Delete` → biz **`…_Delete_20220926`** (`:6571`).
//   Ba thao tác của màn này dùng **ba twin có NGÀY KHÁC NHAU** (Update 2022-06-26,
//   Delete và Approve 2022-09-26) ⇒ chúng được sửa ở những đợt khác nhau, đừng giả định đồng bộ.
//
// 🔴 **CẢ HAI đều guard 'chỉ khi đang CHỜ DUYỆT (P)'** — cùng `Ser_CampaignMarketing_CheckDB(…, Pending)`
//   như Approve (#392). Chiến dịch đã duyệt thì **không sửa, không xoá được**.
// 🔴 **SỬA = XOÁ SẠCH DANH SÁCH CON RỒI GHI LẠI** (nguồn có **10** câu `delete t` trong hàm Update,
//   trên các bảng `VIN` · `PlateNo` · `FullVIN` · `Dealer` · `Part`) ⇒ **KHÔNG phải trộn từng dòng**.
//   Gửi lên danh sách thiếu là **mất phần còn lại**. Đây là điểm dễ port sai nhất của màn.
// 🔴 **XOÁ lan đúng SÁU bảng**, đối xứng với Approve (#392): bảng chính + `Dealer` + `FullVIN`
//   + `Part` + `PlateNo` + `VIN`.
// 📌 MiniHTC mới mô hình hoá bảng con `Part` ⇒ cả hai endpoint đều trả `childTablesNotModelled`.
app.MapPut("/api/campaignmarketings/{no}", async (string no, CampaignMarketingDto dto,
    AppDbContext db, ITenantContext t) =>
{
    no = (no ?? "").Trim().ToUpperInvariant();
    var c = await db.CampaignMarketings.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CamNo == no);
    if (c is null) return Results.NotFound(new { no });
    if (c.CamMarketingStatus != "P")
        return Results.BadRequest(new { error = "Chỉ sửa được chiến dịch đang CHỜ DUYỆT (P).",
            currentStatus = c.CamMarketingStatus });

    c.CamName = dto.CamName ?? c.CamName;
    c.CamDesc = dto.CamDesc;
    // EffDate* KHONG nullable tren entity => giu gia tri cu khi DTO khong gui.
    if (dto.EffDateStart is not null) c.EffDateStart = dto.EffDateStart.Value;
    if (dto.EffDateEnd is not null) c.EffDateEnd = dto.EffDateEnd.Value;
    c.WarrantyDateStart = dto.WarrantyDateStart; c.WarrantyDateEnd = dto.WarrantyDateEnd;
    c.ConditionVin = dto.ConditionVin; c.ConditionPlateNo = dto.ConditionPlateNo;
    c.ConditionDealer = dto.ConditionDealer;

    // 🔴 XOÁ SẠCH rồi ghi lại — đúng nguồn, KHÔNG trộn từng dòng.
    var oldParts = await db.CampaignMarketingParts.Where(x => x.OrgId == t.OrgId && x.CampaignId == c.Id).ToListAsync();
    db.CampaignMarketingParts.RemoveRange(oldParts);
    var newParts = dto.Parts ?? new();
    foreach (var p in newParts)
        db.CampaignMarketingParts.Add(new CampaignMarketingPart
        {
            OrgId = t.OrgId, CampaignId = c.Id,
            PartCode = p.PartCode, PercentDiscount = p.PercentDiscount,
            CamMarketingPartStatus = c.CamMarketingStatus,
        });
    // ===== 🔴 #501 NỐI NỐT BỐN BẢNG CON (đã mô hình hoá ở #482/#483) VÀO SỬA/XOÁ/DUYỆT =====
    // #482/#483 dựng xong bốn bảng con nhưng **ba endpoint ghi vẫn chưa đụng tới** — và tệ hơn, chúng
    //   vẫn **khai nợ `childTablesNotModelled`** cho đúng những bảng **đã có**. Nợ đã trả nhưng sổ chưa xoá
    //   ⇒ người đọc sau tưởng còn thiếu. Đây là lỗi **sổ sách lệch hiện trạng**, nguy hiểm ngang nợ thật.
    // Nguồn: hàm Update có **10 câu `delete t`** trên các bảng `VIN` · `PlateNo` · `FullVIN` · `Dealer` · `Part`
    //   ⇒ **XOÁ SẠCH rồi ghi lại**, không trộn từng dòng. Nay áp đúng lệ đó cho cả bốn bảng còn lại.
    var oldVins = await db.CampaignMarketingVins.Where(x => x.OrgId == t.OrgId && x.CamNo == c.CamNo).ToListAsync();
    var oldPlates = await db.CampaignMarketingPlateNos.Where(x => x.OrgId == t.OrgId && x.CamNo == c.CamNo).ToListAsync();
    var oldDealers = await db.CampaignMarketingDealers.Where(x => x.OrgId == t.OrgId && x.CamNo == c.CamNo).ToListAsync();
    var oldFullVins = await db.CampaignMarketingFullVins.Where(x => x.OrgId == t.OrgId && x.CamNo == c.CamNo).ToListAsync();
    db.CampaignMarketingVins.RemoveRange(oldVins);
    db.CampaignMarketingPlateNos.RemoveRange(oldPlates);
    db.CampaignMarketingDealers.RemoveRange(oldDealers);
    db.CampaignMarketingFullVins.RemoveRange(oldFullVins);
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        c.CamNo, status = c.CamMarketingStatus,
        partsRemoved = oldParts.Count, partsAdded = newParts.Count,
        // #501: bốn bảng con nay CÓ bị xoá sạch theo đúng lệ của nguồn.
        vinsRemoved = oldVins.Count, plateNosRemoved = oldPlates.Count,
        dealersRemoved = oldDealers.Count, fullVinsRemoved = oldFullVins.Count,
        replaceAllNote = "SỬA = XOÁ SẠCH danh sách con rồi ghi lại (nguồn có 10 câu `delete` trong hàm Update). "
            + "Gửi lên danh sách thiếu là MẤT phần còn lại — không phải trộn từng dòng.",
        pendingOnlyNote = "Chỉ sửa được khi đang CHỜ DUYỆT (P), giống guard của Approve.",
        // #501: nợ đã TRẢ — bốn bảng con đã mô hình hoá (#482/#483) và nay đã được nối vào lệnh sửa.
        childTablesNotModelled = Array.Empty<string>(),
        childRowsAreReplacedNotMerged = true,
        twinDateNote = "Update dùng twin _20220626, còn Delete/Approve dùng _20220926 — ba thao tác sửa ở ba đợt khác nhau.",
    });
}).RequireAuthorization();

// XOÁ: lan đúng SÁU bảng, và cũng chỉ khi đang CHỜ DUYỆT.
app.MapDelete("/api/campaignmarketings/{no}", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = (no ?? "").Trim().ToUpperInvariant();
    var c = await db.CampaignMarketings.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CamNo == no);
    if (c is null) return Results.NotFound(new { no });
    if (c.CamMarketingStatus != "P")
        return Results.BadRequest(new { error = "Chỉ xoá được chiến dịch đang CHỜ DUYỆT (P).",
            currentStatus = c.CamMarketingStatus });

    var parts = await db.CampaignMarketingParts.Where(x => x.OrgId == t.OrgId && x.CampaignId == c.Id).ToListAsync();
    // #501b XOA lan dung SAU bang nhu nguon (bang chinh + 5 bang con).
    var dVins = await db.CampaignMarketingVins.Where(x => x.OrgId == t.OrgId && x.CamNo == no).ToListAsync();
    var dPlates = await db.CampaignMarketingPlateNos.Where(x => x.OrgId == t.OrgId && x.CamNo == no).ToListAsync();
    var dDealers = await db.CampaignMarketingDealers.Where(x => x.OrgId == t.OrgId && x.CamNo == no).ToListAsync();
    var dFull = await db.CampaignMarketingFullVins.Where(x => x.OrgId == t.OrgId && x.CamNo == no).ToListAsync();
    db.CampaignMarketingVins.RemoveRange(dVins);
    db.CampaignMarketingPlateNos.RemoveRange(dPlates);
    db.CampaignMarketingDealers.RemoveRange(dDealers);
    db.CampaignMarketingFullVins.RemoveRange(dFull);
    db.CampaignMarketingParts.RemoveRange(parts);
    db.CampaignMarketings.Remove(c);
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        camNo = no, deleted = true, partsDeleted = parts.Count,
        vinsDeleted = dVins.Count, plateNosDeleted = dPlates.Count,
        dealersDeleted = dDealers.Count, fullVinsDeleted = dFull.Count,
        cascadeNote = "Nguồn xoá lan đúng SÁU bảng: chính + Dealer + FullVIN + Part + PlateNo + VIN "
            + "(đối xứng với Approve ở #392).",
        pendingOnlyNote = "Chỉ xoá được khi đang CHỜ DUYỆT (P).",
        // #501b: no da TRA — xoa lan du sau bang.
        childTablesNotModelled = Array.Empty<string>(),
    });
}).RequireAuthorization();

app.MapPost("/api/campaignmarketings/{no}/approve", async (string no, CampaignApproveDto? dto,
    AppDbContext db, ITenantContext t) =>
{
    no = (no ?? "").Trim().ToUpperInvariant();
    var c = await db.CampaignMarketings.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CamNo == no);
    if (c is null) return Results.NotFound(new { no });

    // Chỉ duyệt được khi đang CHỜ DUYỆT.
    if (c.CamMarketingStatus != "P")
        return Results.BadRequest(new { error = "Chỉ duyệt được chiến dịch đang ở trạng thái P (chờ duyệt).",
            currentStatus = c.CamMarketingStatus });

    var now = DateTime.Now;
    c.CamMarketingStatus = "A";
    c.ApprDTime = now;
    c.ApprBy = dto?.ApprBy;

    // LAN trạng thái xuống bảng con — #501: nay đủ NĂM bảng như nguồn, không còn thiếu bốn cái.
    var parts = await db.CampaignMarketingParts.Where(x => x.OrgId == t.OrgId && x.CampaignId == c.Id).ToListAsync();
    foreach (var p in parts) p.CamMarketingPartStatus = "A";
    var cvins = await db.CampaignMarketingVins.Where(x => x.OrgId == t.OrgId && x.CamNo == c.CamNo).ToListAsync();
    foreach (var v in cvins) v.CamMarketingVinStatus = "A";
    var cplates = await db.CampaignMarketingPlateNos.Where(x => x.OrgId == t.OrgId && x.CamNo == c.CamNo).ToListAsync();
    foreach (var v in cplates) v.CamMarketingPlateNoStatus = "A";
    var cdealers = await db.CampaignMarketingDealers.Where(x => x.OrgId == t.OrgId && x.CamNo == c.CamNo).ToListAsync();
    foreach (var v in cdealers) v.CamMarketingDealerStatus = "A";
    var cfull = await db.CampaignMarketingFullVins.Where(x => x.OrgId == t.OrgId && x.CamNo == c.CamNo).ToListAsync();
    foreach (var v in cfull) v.CamMarketingFullVinStatus = "A";
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        c.CamNo, status = c.CamMarketingStatus, c.ApprDTime, c.ApprBy,
        // Remark: null khi rỗng, đúng cách tầng service của nguồn truyền lên.
        remark = string.IsNullOrWhiteSpace(dto?.Remark) ? null : dto!.Remark,
        cascadedParts = parts.Count,
        // #501: lan đủ năm bảng con — nợ đã trả.
        cascadedVins = cvins.Count, cascadedPlateNos = cplates.Count,
        cascadedDealers = cdealers.Count, cascadedFullVins = cfull.Count,
        cascadeNote = "Duyệt LAN trạng thái xuống SÁU bảng con trong nguồn (VIN, PlateNo, Dealer, FullVIN, Part).",
        childTablesNotModelled = Array.Empty<string>(),
        statusVocabNote = "Chỉ có HAI mã: P = chờ duyệt, A = đã duyệt. Không có mã từ chối.",
    });
}).RequireAuthorization();

app.MapPost("/api/campaignmarketings", async (CampaignMarketingDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.CamName)) return Results.BadRequest(new { error = "Chưa nhập tên chiến dịch." });
    if (string.IsNullOrWhiteSpace(dto.CamDesc)) return Results.BadRequest(new { error = "Chưa nhập nội dung chiến dịch." });
    if (dto.EffDateStart is null) return Results.BadRequest(new { error = "Chưa nhập ngày chiến dịch từ." });
    if (dto.EffDateEnd is null) return Results.BadRequest(new { error = "Chưa nhập ngày chiến dịch đến." });
    var parts = dto.Parts ?? new List<CampaignMarketingPartDto>();
    var dupCodes = parts.Select(p => (p.PartCode ?? "").Trim().ToUpperInvariant()).Where(c => c.Length > 0)
        .GroupBy(c => c).Where(g => g.Count() > 1).Select(g => g.Key).ToList();
    if (dupCodes.Count > 0) return Results.BadRequest(new { error = $"Mã phụ tùng '{dupCodes[0]}' bị lặp trên lưới!" });
    foreach (var p in parts)
        if (p.PercentDiscount < 0 || p.PercentDiscount > 100) return Results.BadRequest(new { error = "Hệ số giảm(%) phải >= 0 và <= 100!" });

    var no = "CM" + DateTime.Now.ToString("yyMMddHHmmss");
    var c = new CampaignMarketing
    {
        OrgId = t.OrgId, CamNo = no, CamName = dto.CamName.Trim(), CamDesc = dto.CamDesc,
        EffDateStart = dto.EffDateStart.Value, EffDateEnd = dto.EffDateEnd.Value,
        WarrantyDateStart = dto.WarrantyDateStart, WarrantyDateEnd = dto.WarrantyDateEnd,
        ConditionVin = dto.ConditionVin, ConditionPlateNo = dto.ConditionPlateNo, ConditionDealer = dto.ConditionDealer
    };
    db.CampaignMarketings.Add(c); await db.SaveChangesAsync();
    foreach (var p in parts)
    {
        var code = (p.PartCode ?? "").Trim().ToUpperInvariant();
        if (code.Length == 0) continue;
        db.CampaignMarketingParts.Add(new CampaignMarketingPart { OrgId = t.OrgId, CampaignId = c.Id, PartCode = code, PercentDiscount = Math.Round(p.PercentDiscount, 2) });
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { c.CamNo, partsCount = parts.Count });
}).RequireAuthorization();

// ===== Phụ tùng nợ khách (PartBackorder — port 1:1 FrmNewSerPartOO/FrmMngSerPartOO, TCMotor DMSCarSv/Services) =====
app.MapGet("/api/partbackorders", async (AppDbContext db, ITenantContext t, string? plate, bool? open) =>
{
    var qry = db.PartBackorders.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(plate)) qry = qry.Where(x => x.PlateNo.Contains(plate.ToUpper()));
    if (open == true) qry = qry.Where(x => x.QtyReturned < x.QtyOwed);
    var items = await qry.OrderByDescending(x => x.Id).Take(500).Select(x => new
    { x.PlateNo, x.PartCode, x.PartName, x.CarType, x.DealerCode, x.StaffCode, x.QtyOwed, x.QtyReturned, remain = x.QtyOwed - x.QtyReturned, x.PromiseDate, x.OrderDate, x.ExpectedDate, x.Note }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// Khớp ValidateInput() của form + 3 luật CHỈ CÓ TRONG BIZ (Ser_Part_OO_Create / _Update).
// Khoá tra cứu (biển số, mã phụ tùng) ĐÃ ĐÚNG với nguồn: biz Update cũng tra theo (PartID, OOPlateNo).
app.MapPost("/api/partbackorders", async (PartBackorderDto dto, AppDbContext db, ITenantContext t) =>
{
    var plate = (dto.PlateNo ?? "").Trim().ToUpperInvariant();
    var code = (dto.PartCode ?? "").Trim().ToUpperInvariant();
    if (string.IsNullOrWhiteSpace(code) || string.IsNullOrWhiteSpace(dto.PartName)) return Results.BadRequest(new { error = "Chưa có phụ tùng" });
    if (string.IsNullOrWhiteSpace(plate)) return Results.BadRequest(new { error = "Phải nhập biển số" });
    // Biz chặn biển số ngoài khoảng 8–10 ký tự (Ser_Part_OO_Create_Invalid_BienSo) — form KHÔNG có luật này.
    if (plate.Length < 8 || plate.Length > 10) return Results.BadRequest(new { error = "Biển số phải từ 8 đến 10 ký tự!" });
    if (dto.QtyOwed <= 0) return Results.BadRequest(new { error = "Phải nhập số lượng nợ" });
    // Biz chặn số lượng trả vượt số lượng nợ ở CẢ nhánh tạo lẫn nhánh sửa.
    if (dto.QtyReturned < 0) return Results.BadRequest(new { error = "Số lượng trả không được âm!" });
    if (dto.QtyReturned > dto.QtyOwed) return Results.BadRequest(new { error = "Số lượng trả không được lớn hơn số lượng nợ!" });

    var row = await db.PartBackorders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PlateNo == plate && x.PartCode == code);
    var isNew = row is null;
    if (isNew) { row = new PartBackorder { OrgId = t.OrgId, PlateNo = plate, PartCode = code }; db.PartBackorders.Add(row); }
    row!.PartName = dto.PartName; row.CarType = dto.CarType; row.StaffCode = dto.StaffCode;
    row.DealerCode = dto.DealerCode;
    row.QtyOwed = dto.QtyOwed; row.QtyReturned = dto.QtyReturned;
    row.PromiseDate = dto.PromiseDate; row.OrderDate = dto.OrderDate; row.ExpectedDate = dto.ExpectedDate; row.Note = dto.Note;
    await db.SaveChangesAsync();
    return Results.Ok(new { row.PlateNo, row.PartCode, row.DealerCode, row.QtyOwed, row.QtyReturned, isNew });
}).RequireAuthorization();

// ===== Thanh toán phí AVN theo tháng (AvnPayment — port 1:1 FrmTaoThanhToanAVN, 2010.HTC Sales/Purchase) =====
app.MapGet("/api/avnpayments", async (AppDbContext db, ITenantContext t, string? q) =>
{
    var qry = db.AvnPayments.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(q)) qry = qry.Where(x => x.PmtNo.Contains(q!));
    var items = await qry.OrderByDescending(x => x.Id).Take(500).Select(x => new
    { x.PmtNo, x.PmtMonth, x.TotalAmount, lines = db.AvnPaymentLines.Count(l => l.OrgId == t.OrgId && l.AvnPaymentId == x.Id) }).ToListAsync();
