// Map VIN cho lô GPS chưa map (port 1:1 FrmSto_StoBalanceGPS btnApply_Click) — khớp theo (VIN, GpsNo).
app.MapPost("/api/gpsinstalls/map", async (List<GpsInstallMapDto> rows, AppDbContext db, ITenantContext t) =>
{
    var list = (rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.Vin) && !string.IsNullOrWhiteSpace(r.GpsNo)).ToList();
    if (list.Count == 0) return Results.BadRequest(new { error = "Lưới danh sách VIN - GPS trống!" });
    var mapNo = "GMV" + DateTime.Now.ToString("yyMMddHHmmss");
    var now = DateTime.Now;
    int mapped = 0; var notFound = new List<string>();
    foreach (var r in list)
    {
        var vin = r.Vin.Trim().ToUpperInvariant(); var gps = r.GpsNo.Trim().ToUpperInvariant();
        var x = await db.GpsInstalls.FirstOrDefaultAsync(g => g.OrgId == t.OrgId && g.Vin == vin && g.GpsNo == gps);
        if (x is null) { notFound.Add($"{vin}/{gps}"); continue; }
        x.MapStatus = "1"; x.GpsMapVINNo = mapNo; x.MappedAt = now;
        // 🔴 #B01: ở trạng thái ĐÃ MAP, nguồn giữ `VIN == VINReal` — bằng chứng là chính khối phục hồi map
        //    (`Biz.HTC.WH.cs:186590-186591` gán CẢ HAI = strVIN), và `DMSUnMapVINX` đọc `VINReal` để lấy VIN
        //    vừa gỡ (:185876). Port cũ không gán `VinReal` ⇒ gỡ map xong `VinUnMap` luôn NULL.
        x.VinReal = vin;
        x.VinUnMap = null;             // map lại ⇒ xoá vết "vừa gỡ khỏi VIN nào"
        // Nguồn ghi 1 dòng nhật ký loại GPSMAPVIN cho mỗi lượt map — `DMSUnMapVINX` tra đúng dòng này
        // (`Biz.HTC.WH.cs:185810-185818`: StorageCode + GPSDvNo + VIN=VINReal + RefType='GPSMAPVIN')
        // để so `MapDateTime` với `UnMapDateTime`. Port cũ không ghi ⇒ nhật ký map bị rỗng.
        db.GpsTransactions.Add(new GpsTransaction
        {
            OrgId = t.OrgId, Vin = vin, GpsDvNo = gps, GpsBoxNo = x.GpsBoxNo,
            StorageCode = x.StorageCode, VinReal = vin,
            MapDateTime = now,
            RefType = "GPSMAPVIN",       // TConst.RefTypeGPS.Sto_StoBalanceGPS_MapVIN
            RefCode00 = mapNo,
            FunctionName = "MYSTO_STOBALANCEGPS_MAPVINX",
            MapStatusAfter = "1", BlockStatus = x.BlockStatus, InStatus = x.InStatus,
            CreateDateTime = now,
        });
        mapped++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { gpsMapVINNo = mapNo, mapped, notFound = notFound.Distinct().Take(20) });
}).RequireAuthorization();

// Import danh sách (khớp btnImportExcel_Click gốc): guard VIN/GPS ID/ngày bắt buộc + trùng VIN+GPS ID trong lô.
app.MapPost("/api/gpsinstalls/import", async (List<GpsInstallDto> rows, AppDbContext db, ITenantContext t) =>
{
    var list = (rows ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.Vin) && !string.IsNullOrWhiteSpace(r.GpsNo)).ToList();
    if (list.Count == 0) return Results.BadRequest(new { error = "VIN không được trống!" });
    if (list.Any(r => r.DateActive is null)) return Results.BadRequest(new { error = "Ngày xuất kho không được trống!" });
    var dupe = list.GroupBy(r => (r.Vin.Trim().ToUpperInvariant(), r.GpsNo.Trim().ToUpperInvariant())).FirstOrDefault(g => g.Count() > 1);
    if (dupe != null) return Results.BadRequest(new { error = $"VIN: '{dupe.Key.Item1}' - GPS ID: '{dupe.Key.Item2}' bị lặp trong file excel!" });
    foreach (var r in list)
        db.GpsInstalls.Add(new GpsInstall { OrgId = t.OrgId, Vin = r.Vin.Trim().ToUpperInvariant(), GpsNo = r.GpsNo.Trim().ToUpperInvariant(), DateActive = r.DateActive!.Value,
            StorageCode = r.StorageCode, GpsBoxNo = r.GpsBoxNo, VinReal = r.VinReal, RefNoType = r.RefNoType, RefNoPk = r.RefNoPk,
            InStatus = string.IsNullOrWhiteSpace(r.InStatus) ? "1" : r.InStatus!.Trim(),
            BlockStatus = string.IsNullOrWhiteSpace(r.BlockStatus) ? "0" : r.BlockStatus!.Trim(),
            Remark = r.Remark });
    await db.SaveChangesAsync();
    return Results.Ok(new { imported = list.Count });
}).RequireAuthorization();

// ===== 🔴 GỠ MAP VIN TỰ ĐỘNG — port job `AutoUnMapVin` (2010.HTC Refs/Jobs/DMS.Sale.MapVin.Job) =====
// Luật: lấy các thiết bị đang map (MapStatus="1"), gọi API GPS theo LÔ 100 IMEI, thiết bị nào API trả về
// **Address RỖNG** thì coi là **đã bị tháo khỏi xe** ⇒ gỡ map. Mỗi lượt gỡ sinh 1 số lô (GPSUnMapVINNo).
// ⚠️ MiniHTC không gọi API GPS thật ⇒ nhận kết quả API qua payload; phần "gọi API" là XẤP XỈ CÓ CHỦ ĐÍCH.
const int GpsAutoUnmapPageSize = 100;   // nguồn chia lô đúng 100 IMEI mỗi lần gọi API

app.MapGet("/api/gpsinstalls/auto-unmap/candidates", async (
    AppDbContext db, ITenantContext t, string? storageCode) =>
{
    var code = string.IsNullOrWhiteSpace(storageCode) ? "STOGPS" : storageCode!.Trim();
    var list = await db.GpsInstalls
        .Where(x => x.OrgId == t.OrgId && x.MapStatus == "1")
        .OrderBy(x => x.Id).Select(x => x.GpsNo).ToListAsync();
    var pages = new List<object>();
    for (var i = 0; i < list.Count; i += GpsAutoUnmapPageSize)
        pages.Add(new { page = i / GpsAutoUnmapPageSize + 1, imeis = list.Skip(i).Take(GpsAutoUnmapPageSize) });
    return Results.Ok(new { storageCode = code, total = list.Count, pageSize = GpsAutoUnmapPageSize,
        pageCount = pages.Count, pages,
        note = "Gọi API GPS theo từng lô IMEI này, rồi POST kết quả sang /api/gpsinstalls/auto-unmap." });
}).RequireAuthorization();

app.MapPost("/api/gpsinstalls/auto-unmap", async (
    List<GpsOnlineResultDto> results, AppDbContext db, ITenantContext t, string? storageCode,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    if (results is null || results.Count == 0)
        return Results.BadRequest(new { error = "Chưa có kết quả API GPS để xét gỡ map." });
    var code = string.IsNullOrWhiteSpace(storageCode) ? "STOGPS" : storageCode!.Trim();

    var imeis = results.Where(r => !string.IsNullOrWhiteSpace(r.Imei))
        .Select(r => r.Imei!.Trim().ToUpperInvariant()).ToList();
    var rows = await db.GpsInstalls
        .Where(x => x.OrgId == t.OrgId && x.MapStatus == "1" && imeis.Contains(x.GpsNo)).ToListAsync();

    var unmapNo = "GUM" + DateTime.Now.ToString("yyMMddHHmmss");
    var now = DateTime.Now;
    var unmapped = new List<object>();
    var keptOnline = 0;
    var skippedBlocked = 0;      // thiết bị đang bị KHOÁ (BlockStatus != "0")
    var skippedInStorage = 0;    // thiết bị vẫn CÒN TRONG KHO (InStatus != "0")
    var actorUnmap = user.Identity?.Name ?? "system";

    foreach (var r in results)
    {
        var imei = (r.Imei ?? "").Trim().ToUpperInvariant();
        var row = rows.FirstOrDefault(x => x.GpsNo == imei);
        if (row is null) continue;

        // 🔴 Chính là luật của nguồn: Address RỖNG ⇒ thiết bị đã bị THÁO ⇒ gỡ map.
        if (!string.IsNullOrWhiteSpace(r.Address))
        {
            row.VinAddress = r.Address;   // còn online: chỉ cập nhật vị trí, KHÔNG gỡ
            keptOnline++;
            continue;
        }
        // 🔴 BỔ SUNG PARITY (#66, đọc phía SERVER `mySto_StoBalanceGPS_UnMapVINX` — BizHTC.ZTempGPS.cs:1670-1680):
        // nguồn kiểm **BA** điều kiện qua `Sto_StoBalanceGPS_CheckDB`, không chỉ MapStatus:
        //   BlockStatus = "0" (thiết bị KHÔNG bị khoá) · InStatus = "0" (thiết bị ĐÃ XUẤT kho) · MapStatus = "1".
        // Ở #50 tôi mới port điều kiện MapStatus (suy từ job phía client) ⇒ thiếu 2 guard.
        if (row.BlockStatus != "0") { skippedBlocked++; continue; }
        if (row.InStatus != "0") { skippedInStorage++; continue; }

        var vinBeforeUnmap = row.Vin;                 // chụp TRƯỚC: nguồn ghi đè cột VIN ngay bên dưới
        var vinRealBeforeUnmap = row.VinReal;
        unmapped.Add(new { row.GpsNo, vinWas = vinBeforeUnmap });
        row.MapStatus = "0";
        row.VinAddress = null;
        row.UnMapBy = actorUnmap;

        // 🔴 #B01 BỔ SUNG PARITY — khối gán của nguồn `mySto_StoBalanceGPS_DMSUnMapVINX_New20181119`
        //    (`Biz.HTC.WH.cs:185874-185884`) mà port #66 BỎ SÓT hoàn toàn:
        //      drScan["VIN"]        = drScan["GPSDvNo"];      ← cột VIN bị nhồi SỐ THIẾT BỊ khi gỡ
        //      drScan["VINReal"]    = null;
        //      drScan["VINUnMap"]   = <VINReal cũ trong DB>;  ← chỗ DUY NHẤT nhớ VIN vừa gỡ
        //      drScan["FlagRealSale"] = Veloca ? "1" : "0";
        //      drScan["GPSAddress"] = <địa chỉ Veloca trả về>;
        //      drScan["LogLUDateTime"/"LogLUBy"] = <thời điểm/người>;
        //    Thiếu `VINUnMap` ⇒ màn PHỤC HỒI MAP (`FrmUnmapRecover`) không có gì để phục hồi.
        row.VinUnMap = vinRealBeforeUnmap;
        row.Vin = row.GpsNo;
        row.VinReal = null;
        row.FlagRealSale = "0";        // MiniHTC không có trục ProjectCode ⇒ nhánh else của nguồn
        row.GpsAddress = null;         // nguồn lấy từ Veloca; MiniHTC không gọi Veloca ⇒ để NULL, KHÔNG suy
        row.LogLUDateTime = now;
        row.LogLUBy = actorUnmap;

        // 🔴 Nguồn GHI NHẬT KÝ giao dịch GPS cho mỗi lượt gỡ (Sto_StoTransactionGPS).
        // Luồng gỡ map tự động ở #50 KHÔNG ghi dòng nào ⇒ mất audit trail.
        db.GpsTransactions.Add(new GpsTransaction
        {
            OrgId = t.OrgId, Vin = vinBeforeUnmap, GpsDvNo = row.GpsNo, GpsBoxNo = row.GpsBoxNo,
            StorageCode = row.StorageCode ?? code, VinReal = vinRealBeforeUnmap,
            VINAddress = null,
            MapDateTime = row.MappedAt ?? now, UnMapDateTime = now, UnMapBy = actorUnmap,
            // 🔴 #B01 SỬA GIÁ TRỊ SAI: port cũ ghi TÊN HẰNG `"Sto_StoBalanceGPS_UNMapVIN"`, còn GIÁ TRỊ thật
            //    của `TConst.RefTypeGPS.Sto_StoBalanceGPS_UNMapVIN` là **"GPSUNMAPVIN"**
            //    (`TERP.Constants/Const.Main.StorageFG.1.cs:77`). Nguồn `RecoverMapX` lọc
            //    `t.RefType = 'GPSUNMAPVIN'` ⇒ để nguyên tên hằng thì KHÔNG BAO GIỜ tìm thấy dòng gỡ map.
            RefType = "GPSUNMAPVIN",                     // TConst.RefTypeGPS.Sto_StoBalanceGPS_UNMapVIN
            RefCode00 = unmapNo,                         // nguồn ghi SỐ LÔ gỡ map vào RefCode00
            FunctionName = "MYSTO_STOBALANCEGPS_UNMAPVINX",  // nguồn viết HOA tên hàm
            MapStatusAfter = "0", BlockStatus = row.BlockStatus, InStatus = row.InStatus,
            CreateDateTime = now, CreateBy = actorUnmap,
        });
        row.GpsUnMapVINNo = unmapNo;
        row.UnMappedAt = now;
        row.StorageCode ??= code;
    }

    if (unmapped.Count == 0)
        return Results.Ok(new { storageCode = code, unmapped = 0, keptOnline, skippedBlocked, skippedInStorage,
            note = "Không có thiết bị tháo!" });   // đúng thông điệp của nguồn

    await db.SaveChangesAsync();
    return Results.Ok(new { storageCode = code, gpsUnMapVINNo = unmapNo, unmapped = unmapped.Count, keptOnline,
        skippedBlocked, skippedInStorage, items = unmapped });
}).RequireAuthorization();

// ===== #B01 PHỤC HỒI MAP THIẾT BỊ GPS (port 1:1 FrmUnmapRecover — 2010.HTC TERP.HTCClient/Views/StoFGPS) =====
// Trace twin LIVE: FrmUnmapRecover.btnUnmapRecover_Click → Sto_StoBalanceGPSService.Sto_StoBalanceGPS_RecoverMap
//   → WSHTC.asmx.cs:52823 `Sto_StoBalanceGPS_RecoverMap` → **`_biz.Sto_StoBalanceGPS_RecoverMap_New20181119`**
//   (Biz.HTC.WH.cs:186659) → `mySto_StoBalanceGPS_RecoverMapX_New20181119` (:186479).
//   ⚠️ `mySto_StoBalanceGPS_RecoverMapX_New20180904` (BizHTC.ZTempGPS.cs:2978) là bản CHẾT — WS không gọi.
//   ⚠️ `Biz.HTC.WH.Rel.20230823.cs` KHÔNG có trong `TERP.BizHTC.csproj` ⇒ cũng chết.
// Nguồn hardcode kho `STOGPS` ngay trong form (`var storagecodeCur = "STOGPS";`).
app.MapPost("/api/gpsinstalls/{device}/recover-map", async (
    string device, AppDbContext db, ITenantContext t, string? storageCode,
    System.Security.Claims.ClaimsPrincipal user) =>
{
    // Guard form: "Số GPS ID trống!" (FrmUnmapRecover.cs:167)
    if (string.IsNullOrWhiteSpace(device)) return Results.BadRequest(new { error = "Số GPS ID trống!" });
    var dv = device.Trim().ToUpperInvariant();
    // Form hardcode "STOGPS"; cho phép override để test kho khác nhưng mặc định đúng nguồn.
    var code = string.IsNullOrWhiteSpace(storageCode) ? "STOGPS" : storageCode!.Trim().ToUpperInvariant();

    var g = await db.GpsInstalls.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.GpsNo == dv && x.StorageCode == code);
    // `Sto_StoBalanceGPS_CheckDB(..., strFlagExistToCheck = Flag.Yes)` — không có dòng ⇒ lỗi.
    // Thông điệp lấy đúng form (:161): "Thiết bị không được khai báo trên hệ thống!".
    if (g is null) return Results.BadRequest(new { error = "Thiết bị không được khai báo trên hệ thống!" });

    // `Sto_StoBalanceGPS_CheckDB(..., BlockStatus=Inactive, InStatus=Inactive, MapStatus=Inactive)`
    // — BA trục đều phải "0" (BizHTC.ZTempGPS.cs:25-125 + Biz.HTC.WH.cs:186499-186506).
    if (g.BlockStatus != "0") return Results.BadRequest(new { error = $"Thiết bị {dv} đang bị khoá (BlockStatus)." });
    if (g.InStatus != "0") return Results.BadRequest(new { error = $"Thiết bị {dv} vẫn còn trong kho (InStatus)." });
    // MapStatus = "1" ⇒ form báo "Thiết bị đang được map với VIN '<VIN>'" (FrmUnmapRecover.cs:152-157).
    if (g.MapStatus != "0")
        return Results.BadRequest(new { error = $"Thiết bị đang được map với VIN '{g.Vin}' trên hệ thống!" });
    // Form: VINUnMap rỗng ⇒ "Thiết bị chưa được map với bất kỳ VIN nào trên hệ thống!" (:142)
    if (string.IsNullOrWhiteSpace(g.VinUnMap))
        return Results.BadRequest(new { error = "Thiết bị chưa được map với bất kỳ VIN nào trên hệ thống!" });

    // Nguồn: lấy dòng nhật ký GỠ MAP mới nhất (RefType = 'GPSUNMAPVIN'); không có ⇒
    // `mySto_StoBalanceGPS_RecoverMapX_GPSNotUnMapVIN` (Biz.HTC.WH.cs:186537-186546).
    var txUnmap = await db.GpsTransactions
        .Where(x => x.OrgId == t.OrgId && x.GpsDvNo == dv && x.StorageCode == code && x.RefType == "GPSUNMAPVIN")
        .OrderByDescending(x => x.CreateDateTime).ThenByDescending(x => x.Id).FirstOrDefaultAsync();
    if (txUnmap is null)
        return Results.BadRequest(new { error = $"Thiết bị {dv} chưa có giao dịch gỡ map (GPSUNMAPVIN) để phục hồi." });

    // Nguồn: nếu SAU dòng gỡ map đó còn giao dịch khác (AutoId > AutoId của dòng gỡ) ⇒
    // `..._InvalidExistBizOrther` (:186563-186578) — thiết bị đã đi tiếp nghiệp vụ khác, cấm phục hồi.
    var txLater = await db.GpsTransactions
        .Where(x => x.OrgId == t.OrgId && x.GpsDvNo == dv && x.StorageCode == code && x.Id > txUnmap.Id)
        .OrderByDescending(x => x.CreateDateTime).FirstOrDefaultAsync();
    if (txLater is not null)
        return Results.BadRequest(new { error = $"Thiết bị {dv} đã phát sinh nghiệp vụ khác sau khi gỡ map (RefType={txLater.RefType}, RefCode00={txLater.RefCode00}).", gpsDvNo = dv, txLater.RefType, txLater.RefCode00 });

    var actor = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    var vin = g.VinUnMap!.Trim();

    // SaveDB Sto_StoBalanceGPS (Biz.HTC.WH.cs:186584-186598) — đúng 8 cột trong alColumnEffective.
    g.Vin = vin;
    g.VinReal = vin;
    g.VinUnMap = null;
    g.UnMappedAt = null;         // `UnMapDateTime` = null
    g.UnMapBy = null;
    g.MapStatus = "1";           // TConst.Flag.Active
    g.LogLUDateTime = now;
    g.LogLUBy = actor;

    // SaveDB Sto_StoTransactionGPS (:186601-186610): nguồn **XOÁ** dòng nhật ký gỡ map (`Rows[0].Delete()`).
    db.GpsTransactions.Remove(txUnmap);

    // Call Veloca `Veloca_ResetUnMap` (:186613-186652): lỗi NOTOK chỉ được GHI vào alParamsCoupleError,
    // lệnh `throw` bị COMMENT ⇒ nguồn KHÔNG chặn. MiniHTC không gọi Veloca ⇒ bỏ, không bịa kết quả.
    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        gpsDvNo = dv, storageCode = code, vin, mapStatus = g.MapStatus,
        message = $"Phục hồi map thiết bị với VIN ' {vin} ' thành công!"   // đúng thông điệp form (:135)
    });
}).RequireAuthorization();

// ===== #B02 BÁO CÁO THIẾT BỊ ĐÃ THÁO (UNMAP) NHƯNG CHƯA NHẬP KHO =====
// Port 1:1 `FrmRptThietBiUnMapChuaNhapKho` (2010.HTC TERP.HTCClient/Views/StoFGPS).
// Trace twin LIVE: btnSearch_Click → `ReportStoFGPSService.Rpt_GPSDvUnMapButNotInSto_ForGPS` (:166) —
//   hàm này rẽ theo cờ `checkWH` của form: `dataWH=false` → WS `..._ForGPS` (WSHTC.asmx.cs:53656)
//   → `_biz.Rpt_GPSDvUnMapButNotInSto_ForGPS_New20181017` (BizHTC.ZTempGPS.cs:8192, chạy `_dbMain`);
//   `dataWH=true` → WS `..._ForGPS_WH` (:73213) → `..._ForGPS_WH_New20181119` (Biz.HTC.WH.cs:156521, `_dbWH`).
//   `diff` hai hàm: **SQL GIỐNG HỆT**, chỉ khác `_dbMain` vs `_dbWH` ⇒ MiniHTC 1 DB nên cờ chỉ được ghi lại.
// 🔴 Báo cáo này ĐỌC ĐÚNG hai cột `VINUnMap` + `UnMapDateTime` mà #B01 vừa bổ sung — trước #B01 không thể port.
app.MapGet("/api/reports/gps-unmap-not-instock", async (
    AppDbContext db, ITenantContext t,
    string? gpsDvNo, DateTime? fromUnMapDate, DateTime? toUnMapDate, string? dataWH, string? buPattern) =>
{
    // Bộ lọc gốc trên `#tbl_Sto_StoBalanceGPS` (BizHTC.ZTempGPS.cs:8226-8232): ba điều kiện CỨNG.
    var q = db.GpsInstalls.Where(x => x.OrgId == t.OrgId
        && x.MapStatus == "0"            // đã tháo
        && x.UnMappedAt != null          // `ssbgps.UnMapDateTime is not null`
        && x.InStatus == "0");           // chưa nhập kho lại
    // `Util.GenLikeCondition2Percent` ⇒ LIKE '%…%' (form :113)
    if (!string.IsNullOrWhiteSpace(gpsDvNo)) { var k = gpsDvNo.Trim().ToUpperInvariant(); q = q.Where(x => x.GpsNo.Contains(k)); }
    // Form ép biên ngày: from + " 00:00:00", to + " 23:59:59" (:114-115)
    if (fromUnMapDate is not null) { var f = fromUnMapDate.Value.Date; q = q.Where(x => x.UnMappedAt >= f); }
    if (toUnMapDate is not null) { var e = toUnMapDate.Value.Date.AddDays(1).AddSeconds(-1); q = q.Where(x => x.UnMappedAt <= e); }

    // `inner join Sto_StoTransactionGPS ... RefType = 'GPSMAPVIN'` khớp theo StorageCode + GPSDvNo
    // (:8237-8250 + :8272-8273) — thiết bị KHÔNG có giao dịch map nào thì bị LOẠI (inner join).
    q = q.Where(x => db.GpsTransactions.Any(s => s.OrgId == t.OrgId && s.RefType == "GPSMAPVIN"
        && s.StorageCode == x.StorageCode && s.GpsDvNo == x.GpsNo));

    var rows = await q.OrderByDescending(x => x.UnMappedAt).Take(2000)
        .Select(x => new { x.GpsNo, x.StorageCode, x.UnMappedAt, x.UnMapBy, Vin = x.VinUnMap }).ToListAsync();

    // Chuỗi ra đại lý của nguồn: `Car_Car`(VIN=VINUnMap) → `Dls_DealDetail`(FlagCurrent='1')
    // → `DLS_Deal`(FlagInitDeal='0') → `Mst_Dealer` (+ `md.BUCode like @strBUPatternOfUser`).
    // ⚠️ MiniHTC KHÔNG có `Car_Car`/`Dls_DealDetail`/`DLS_Deal` ⇒ **XẤP XỈ CÓ NHÃN**: lấy
    //    `Car_VIN.DealerCode` (`CarVinMaster`). Đây KHÔNG phải cột nguồn — xem `dealerCodeSource` dưới.
    //    Nợ đã ghi log #B02; tuyệt đối không coi đây là parity đầy đủ.
    var vins = rows.Where(r => r.Vin != null).Select(r => r.Vin!).Distinct().ToList();
    var carMap = await db.CarVinMasters.Where(c => c.OrgId == t.OrgId && vins.Contains(c.VIN))
        .Select(c => new { c.VIN, c.DealerCode }).ToListAsync();
    var pattern = string.IsNullOrWhiteSpace(buPattern) ? null : buPattern.Trim().TrimEnd('%').ToUpperInvariant();
    var dealers = await db.Dealers.Where(d => d.OrgId == t.OrgId)
        .Select(d => new { d.DealerCode, d.BUCode }).ToListAsync();

    var items = new List<object>();
    var droppedNoCar = 0; var droppedNoDealer = 0;
    foreach (var r in rows)
    {
        var car = carMap.FirstOrDefault(c => c.VIN == r.Vin);
        if (car is null) { droppedNoCar++; continue; }                 // `inner join Car_Car`
        var dl = dealers.FirstOrDefault(d => d.DealerCode == car.DealerCode);
        if (dl is null) { droppedNoDealer++; continue; }               // `inner join Mst_Dealer`
        // `md.BUCode like @strBUPatternOfUser` — MiniHTC chưa có tầng ability ⇒ nhận pattern từ query.
        if (pattern is not null && !(dl.BUCode ?? "").ToUpperInvariant().StartsWith(pattern)) { droppedNoDealer++; continue; }
        items.Add(new
        {
            storageCode = r.StorageCode, gpsDvNo = r.GpsNo, vin = r.Vin,
            unMapDateTime = r.UnMappedAt, unMapBy = r.UnMapBy, mdDealerCode = dl.DealerCode
        });
    }

    return Results.Ok(new
    {
        count = items.Count, items,
        dataWH = dataWH == "1" || dataWH == "true",
        dataWHNote = "Nguồn có 2 hàm (Main/WH) nhưng SQL GIỐNG HỆT, chỉ khác DB đích; MiniHTC 1 DB ⇒ cờ không đổi kết quả.",
        dealerCodeSource = "XẤP XỈ: Car_VIN.DealerCode. Nguồn dùng Car_Car→Dls_DealDetail(FlagCurrent='1')→DLS_Deal(FlagInitDeal='0')→Mst_Dealer — 3 bảng này chưa có trong MiniHTC.",
        droppedNoCar, droppedNoDealer,
        note = items.Count == 0 ? "Lưới danh sách thiết bị trống!" : null   // đúng thông điệp form (:152)
    });
}).RequireAuthorization();

// Đồng bộ (khớp btnDongBoNggayXuatKho_Click gốc — mô phỏng gọi Veloca, luôn thành công trên fleet-demo).
app.MapPost("/api/gpsinstalls/sync", async (AppDbContext db, ITenantContext t) =>
{
    var pending = await db.GpsInstalls.Where(x => x.OrgId == t.OrgId && x.SyncStatus == "Pending").ToListAsync();
    if (pending.Count == 0) return Results.BadRequest(new { error = "Không có VIN - GPS ID - Ngày xuất kho cần đồng bộ!" });
    var now = DateTime.Now;
    foreach (var x in pending) { x.SyncStatus = "Synced"; x.SyncedAt = now; }
    await db.SaveChangesAsync();
    return Results.Ok(new { synced = pending.Count });
}).RequireAuthorization();

// ===== Thanh toán phí GPS theo tháng (GpsPayment — port 1:1 FrmTaoThanhToanGPS/FrmQuanLyThanhToanGPS, 2010.HTC Sales/Purchase) =====
app.MapGet("/api/gpspayments", async (AppDbContext db, ITenantContext t, string? q) =>
{
    var qry = db.GpsPayments.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(q)) qry = qry.Where(x => x.PmtNo.Contains(q!));
    var items = await qry.OrderByDescending(x => x.Id).Take(500).Select(x => new
    { x.PmtNo, x.PmtMonth, x.TotalWithoutVAT, x.AmountVAT, x.TotalAfterVAT, lines = db.GpsPaymentLines.Count(l => l.OrgId == t.OrgId && l.GpsPaymentId == x.Id) }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapGet("/api/gpspayments/{no}", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var h = await db.GpsPayments.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PmtNo == no);
    if (h is null) return Results.NotFound(new { no });
    var lines = await db.GpsPaymentLines.Where(l => l.OrgId == t.OrgId && l.GpsPaymentId == h.Id).Select(l => new
    { l.Vin, l.SpecCode, l.ModelCode, l.ModelName, l.GpsId, l.CostGPSStartDate, l.CostGPSEndDate, l.DeductDate, l.PriceGPS, l.PlanCostGPSDate, l.ActualCostGPSDate, l.AmountGPS }).ToListAsync();
    return Results.Ok(new { h.PmtNo, h.PmtMonth, h.TotalWithoutVAT, h.AmountVAT, h.TotalAfterVAT, lines });
}).RequireAuthorization();

// Khớp btnSave gốc: guard tháng thanh toán bắt buộc + ngày KT>=ngày BĐ; tự tính PlanCostGPSDate/ActualCostGPSDate/AmountGPS + VAT 10%.
app.MapPost("/api/gpspayments", async (GpsPaymentDto dto, AppDbContext db, ITenantContext t) =>
{
    if (dto.PmtMonth is null) return Results.BadRequest(new { error = "Chưa nhập tháng thanh toán" });
    var lines = dto.Lines ?? new List<GpsPaymentLineDto>();
    foreach (var l in lines)
        if (l.CostGPSEndDate < l.CostGPSStartDate) return Results.BadRequest(new { error = "Ngày kết thúc tính phí phải lớn hơn hoặc bằng ngày bắt đầu!" });
    foreach (var l in lines)
        if (l.DeductDate < 0) return Results.BadRequest(new { error = "Ngày khấu trừ phải lớn hơn hoặc bằng 0" });

    var no = "GPS" + DateTime.Now.ToString("yyMMddHHmmss");
    var h = new GpsPayment { OrgId = t.OrgId, PmtNo = no, PmtMonth = dto.PmtMonth.Value };
    db.GpsPayments.Add(h); await db.SaveChangesAsync();

    decimal total = 0;
    foreach (var l in lines)
    {
        var plan = (int)(l.CostGPSEndDate.Date - l.CostGPSStartDate.Date).TotalDays + 1;
        var actual = Math.Max(0, plan - l.DeductDate);
        var amount = l.PriceGPS * actual;
        total += amount;
        db.GpsPaymentLines.Add(new GpsPaymentLine
        {
            OrgId = t.OrgId, GpsPaymentId = h.Id, Vin = (l.Vin ?? "").Trim().ToUpperInvariant(), SpecCode = l.SpecCode, ModelCode = l.ModelCode, ModelName = l.ModelName,
            SpecDescription = l.SpecDescription, GpsId = l.GpsId, CostGPSStartDate = l.CostGPSStartDate, CostGPSEndDate = l.CostGPSEndDate, DeductDate = l.DeductDate,
            PriceGPS = l.PriceGPS, ContractGPS = l.ContractGPS, PlanCostGPSDate = plan, ActualCostGPSDate = actual, AmountGPS = amount
        });
    }
    h.TotalWithoutVAT = total; h.AmountVAT = Math.Round(total * 0.1m, 0); h.TotalAfterVAT = h.TotalWithoutVAT + h.AmountVAT;
    await db.SaveChangesAsync();
    return Results.Ok(new { h.PmtNo, h.TotalWithoutVAT, h.AmountVAT, h.TotalAfterVAT, lines = lines.Count });
}).RequireAuthorization();

// ===== Thanh toán phí lưu kho theo tháng (StoragePayment — port 1:1 FrmQuanLyThanhToanLuuKho/FrmSuaThanhToanLuuKho, 2010.HTC Sales/Purchase) =====
