      // #154 parity Pmt_TransportInsDetail.
      l.TotalPrice, l.FProvinceRemark, l.StandardRemark, l.TrasportInsDtlStatus,
      l.FStorageCode, l.FProvinceName, l.TStorageCode, l.InvStartDate, l.InvEndDate,
