            b.CreditContractNo, b.CreditContractDate, b.CreditAmount,
            b.FlagBankGrt, b.FlagBankPmt, b.FlagActive,
            b.Remark, b.LogLUDateTime, b.LogLUBy }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
