// Sửa số lượng theo dòng model/spec/màu (port 1:1 FrmMngRetailContractHistory btnFlagDone01_Click, Sales/RetailContract)
app.MapPost("/api/dlrcontracts/{no}/update-qty", async (string no, DlrContractQtyDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var c = await db.DlrContracts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlrContractNo == no);
    if (c is null) return Results.NotFound(new { no });
    var rows = (dto.Rows ?? new()).Where(r => r.UpdateQty > 0).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Không có Số lượng thay đổi" });
    int updated = 0;
    var lines = await db.DlrContractDetails.Where(l => l.OrgId == t.OrgId && l.ContractId == c.Id).ToListAsync();
    foreach (var r in rows)
    {
        var line = lines.FirstOrDefault(l => l.ModelCode == r.ModelCode && l.SpecCode == r.SpecCode && l.ColorCode == r.ColorCode);
        if (line is null) continue;
        line.Qty = r.UpdateQty;
        updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { c.DlrContractNo, updated });
}).RequireAuthorization();

// 🔴 XÁC NHẬN / HUỶ HỢP ĐỒNG BÁN LẺ — `Dlr_Contract_ApproveMulti` (BizHTC.Contract.cs:7215) và
// `Dlr_Contract_CancelMulti` (7566). **Cả hai đều làm THEO LÔ**: nhận bảng `Dlr_Contract` nhiều dòng,
// `foreach` theo `DlrContractNo`, guard **"P"** rồi ghi `ApproveDTime/By` hoặc `CancelDTime/By`.
// ⚠️ Port cũ chỉ có `cancel` từng HĐ với trạng thái tự đặt Active→Cancelled: thiếu bước **xác nhận "A"**,
// thiếu **theo lô**, và không lưu ai xác nhận/huỷ.
// TWIN: hai hàm này **chỉ có ở `TERP.WSHTC.64`** (37294/37359).
app.MapPost("/api/dlrcontracts/{action}-multi", async (string action, DlrContractBatchDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    if (action is not ("approve" or "cancel")) return Results.BadRequest(new { error = "action = approve | cancel" });
    var nos = (dto.ContractNos ?? new()).Where(x => !string.IsNullOrWhiteSpace(x)).Select(x => x.Trim().ToUpperInvariant()).Distinct().ToList();
    if (nos.Count == 0) return Results.BadRequest(new { error = "Chưa chọn hợp đồng nào." });
    var rows = await db.DlrContracts.Where(x => x.OrgId == t.OrgId && nos.Contains(x.DlrContractNo)).ToListAsync();
    var missing = nos.Except(rows.Select(x => x.DlrContractNo)).ToList();
    if (missing.Count > 0) return Results.BadRequest(new { error = $"Không tìm thấy hợp đồng: {string.Join(", ", missing)}" });
    // Cả hai hàm nguồn đều guard `strDlrCtrStatusListToCheck = DlrCtrStatus1.Pending` ⇒ CHỈ từ "P".
    var bad = rows.FirstOrDefault(x => x.Status != "P");
    if (bad is not null)
        return Results.BadRequest(new { error = $"HĐ {bad.DlrContractNo} đang ở trạng thái '{bad.Status}' — chỉ xử lý được HĐ mới tạo (P)." });

    var now = DateTime.Now;
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    foreach (var c in rows)
    {
        if (action == "approve") { c.Status = "A"; c.ApproveDTime = now; c.ApproveBy = who; }
        else { c.Status = "C"; c.CancelDTime = now; c.CancelBy = who; }
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { action, affected = rows.Count, status = rows[0].Status });
}).RequireAuthorization();

// ⚠️ #198 ĐÃ BỎ `/api/dlrcontracts/{no}/finish` — **nguồn KHÔNG có lệnh này**.
//    Grep toàn `TERP.BizHTC`: chỉ MỘT chỗ đặt `DlrCtrStatus = 'F'` (BizHTC.Contract.cs:3282), và nó nằm
//    bên trong `Dlr_ContractCancel_SaveX_New20230306` — tức "hoàn thành" là **hệ quả tự động** của việc
//    lưu phiếu huỷ xe khi hợp đồng không còn xe nào chưa xử lý, KHÔNG phải nút bấm.
//    Port cũ dựng một endpoint bấm tay với guard `Status == "A"` — guard đó không tồn tại ở nguồn.
//    Cùng cách xử lý với `/deliver` và `/reject` đã bỏ ở cụm lệnh giao xe (#175).
//    ⇒ Xem side-effect thật ở `POST /api/dlrcontractcancels/save`.

// Hỗ trợ sửa HĐ đại lý theo lô (port 1:1 FrmSupportDlr_Contract_UpdateBankCode/UpdateSalesType/UpdateSMCode, ERP.V15.2025/Support).
// field = bankCode|salesType|salesManCode.
app.MapPost("/api/dlrcontracts/{no}/patch", async (string no, DlrContractPatchDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var c = await db.DlrContracts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.DlrContractNo == no);
    if (c is null) return Results.NotFound(new { no });
    var field = (dto.Field ?? "").Trim();
    if (field is not ("bankCode" or "salesType" or "salesManCode")) return Results.BadRequest(new { error = "Field không hợp lệ (bankCode|salesType|salesManCode)." });
    if (string.IsNullOrWhiteSpace(dto.Value)) return Results.BadRequest(new { error = "Chưa nhập giá trị mới." });
    // 🔴 Nguồn (`Support_Dlr_Contract_Update{BankCode,SalesType,SMCode}`) ghi **BẢNG LỊCH SỬ RIÊNG**
    //    cho từng trường, lưu giá trị cũ + mới — port cũ sửa xong không để lại dấu vết nào.
    //    TWIN: cả ba hàm **chỉ có ở `TERP.WSHTC.64`** (99511 / 99577 / 99775).
    var newVal = dto.Value.Trim().ToUpperInvariant();
    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;
    string oldVal;
    switch (field)
    {
        case "bankCode":
            // ✅ GUARD ĐÃ PORT (nợ #94 đóng ở #116). Nguồn `Support_Dlr_Contract_UpdateBankCode`
            //    (`Biz.HTC.WH.cs:114720-114748`) kiểm INLINE: `BankCode = @strBankCode AND FlagActive = 1`
            //    — tức ngân hàng vừa phải tồn tại VỪA phải đang hoạt động.
            if (!await db.MstBanks.AnyAsync(x => x.OrgId == t.OrgId && x.BankCode == newVal && x.FlagActive == "1"))
                return Results.BadRequest(new { error = $"Ngân hàng {newVal} không tồn tại hoặc đã ngưng hoạt động." });
            oldVal = c.BankCode ?? ""; c.BankCode = newVal;
            db.DlrContractUpdBankCodeHiss.Add(new DlrContractUpdBankCodeHis { OrgId = t.OrgId, DlrContractNo = c.DlrContractNo, BankCodeOld = oldVal, BankCodeNew = newVal, UpdDTime = now, UpdBy = who });
            break;
        case "salesType":
            // ✅ GUARD ĐÃ PORT (nợ #94 đóng ở #116). Nguồn `Support_Dlr_Contract_UpdateSalesType`
            //    (`Biz.HTC.WH.cs:114415-114443`) kiểm INLINE và **CHỈ kiểm TỒN TẠI** —
            //    🔴 KHÔNG kiểm `FlagActive`, khác hẳn helper `Mst_DealerSalesType_CheckDB` (tra theo cặp
            //    SalesType + FlagActive). Port đúng bản INLINE mà hàm LIVE thực sự chạy, không theo helper.
            if (!await db.MstDealerSalesTypes.AnyAsync(x => x.OrgId == t.OrgId && x.SalesType == newVal))
                return Results.BadRequest(new { error = $"Kiểu bán lẻ {newVal} không tồn tại." });
            oldVal = c.SalesType; c.SalesType = newVal;
            db.DlrContractUpdSalesTypeHiss.Add(new DlrContractUpdSalesTypeHis { OrgId = t.OrgId, DlrContractNo = c.DlrContractNo, SalesTypeOld = oldVal, SalesTypeNew = newVal, UpdDTime = now, UpdBy = who });
            break;
        default:
            // 🔴 Guard nguồn ĐÃ port: NVBH mới phải tồn tại, đang hoạt động ("1") và đúng loại "TVBH".
            var sm = await db.SalesMen.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SalesManCode == newVal);
            if (sm is null) return Results.BadRequest(new { error = $"Không tìm thấy nhân viên bán hàng {newVal}." });
            if (sm.Status != "1") return Results.BadRequest(new { error = $"Nhân viên {newVal} không còn hoạt động (SMStatus != 1)." });
            if (!string.Equals(sm.SalesType, "TVBH", StringComparison.OrdinalIgnoreCase))
                return Results.BadRequest(new { error = $"Nhân viên {newVal} không phải loại TVBH (SMType = '{sm.SalesType}')." });
            oldVal = c.SalesManCode; c.SalesManCode = newVal;
            db.DlrContractUpdSMCodeHiss.Add(new DlrContractUpdSMCodeHis { OrgId = t.OrgId, DlrContractNo = c.DlrContractNo, SMCodeOld = oldVal, SMCodeNew = newVal, UpdDTime = now, UpdBy = who });
            break;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { c.DlrContractNo, field, oldValue = oldVal, newValue = newVal });
}).RequireAuthorization();

// ===== Khách hàng đại lý (DealerCustomer — port 1:1 FrmNewCustomer/FrmMngCustomer, DMSales.Foton/SalesDealer) =====
app.MapGet("/api/dealercustomers", async (AppDbContext db, ITenantContext t, string? q, string? dealer, string? type) =>
{
    var query = db.DealerCustomers.Where(c => c.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) query = query.Where(c => c.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(type)) query = query.Where(c => c.CusTypeCode == type);
    if (!string.IsNullOrWhiteSpace(q)) query = query.Where(c => c.FullName.Contains(q) || c.CustomerCode.Contains(q) || (c.PhoneNo != null && c.PhoneNo.Contains(q)));
    var items = await query.OrderByDescending(c => c.Id).Take(500).Select(c => new
    {
        // #124 §12: projection cũ THIẾU 10 cột đã có trong entity — bổ sung cho đủ.
        c.CustomerCode, c.FullName, c.FullNameEN, c.DealerCode, c.CusTypeCode, c.CusBaseCode,
        c.PhoneNo, c.Email, c.Address, c.ProvinceCode, c.DistrictCode, c.TaxCode,
        c.IDCardNo, c.IDCardType, c.Gender, c.DateOfBirth,
        c.RepresentName, c.Position, c.CusAccountBank, c.CreatedBy, c.CreatedAt
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

// ===== PHIẾU THANH TOÁN đại lý (Pmt_Payment + Pmt_PaymentDetail) =====
// Port 1:1 `PaymentPaymentCreate_New20191202` — 2010.HTC `BankIntergration/BizHTC.MBBank.cs:32`
// (ghi Pmt_Payment tại 460, Pmt_PaymentDetail tại 460-463).
// 🔴 BẪY TWIN + FILE CHẾT cùng lúc — phải trace mới ra:
//    · WS 32-bit gọi `_New20181119`, nhưng hàm đó nằm ở `DataWH/Delete.Biz.HTC.WH.My.cs` mà csproj
//      khai là `<None>` (dòng 325) ⇒ FILE CHẾT, không trong build.
//    · WS 64-bit gọi `_New20191202` ở `BizHTC.MBBank.cs` — csproj `<Compile>` (310) ⇒ LIVE.
//    · Còn bản `_New20190611` ở `Biz.HTC.WH.cs:45880` KHÔNG WS nào gọi (bản trung gian).
//    ⇒ Canonical = bản 20191202. Chọn nhầm bản trung gian sẽ THIẾU 2 cột PmtBakingStatus + BulkDetailId.
// 🔴 Khi tạo: PaymentStatus = "P"; ApprovedDate/By, PaymentEndDate, ConfirmDate/By,
//    AccountingRecordNo, BulkDetailId để NULL tường minh; PmtBakingStatus = "0" (chưa đẩy ngân hàng).
// ⚠️ Tên cột nguồn viết "PmtBakingStatus" — thiếu chữ n so với "Banking". Giữ nguyên theo nguồn.
app.MapGet("/api/pmtpayments", async (AppDbContext db, ITenantContext t, string? paymentNo, string? dealerCode, string? status) =>
{
    var qy = db.PmtPayments.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(paymentNo)) qy = qy.Where(x => x.PaymentNo == paymentNo);
    if (!string.IsNullOrWhiteSpace(dealerCode)) qy = qy.Where(x => x.DealerCode == dealerCode);
    if (!string.IsNullOrWhiteSpace(status)) qy = qy.Where(x => x.PaymentStatus == status);
    var items = await qy.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.PaymentNo, x.DealerCode, x.PaymentType, x.BankCodeSend, x.BankCodeReceive, x.BankPaymentNo,
        x.BankAccountSend, x.BankAccountReceive, x.AccountingRecordNo, x.TotalAmount, x.PaymentStatus,
        x.Funds, x.BankLending, x.PmtBakingStatus, x.BulkDetailId,
        x.CreatedDate, x.CreatedBy, x.ApprovedDate, x.ApprovedBy,
        x.PaymentEndDate, x.ConfirmDate, x.ConfirmBy,
        // #155 parity Pmt_Payment: 4 cột nguồn ghi mà port cũ thiếu.
        x.Remark, x.TransferType, x.LoanPeriod, x.InterestRate,
    }).ToListAsync();
    var nos = items.Select(i => i.PaymentNo).ToList();
    var details = await db.PmtPaymentDetails.Where(d => d.OrgId == t.OrgId && nos.Contains(d.PaymentNo))
        .Select(d => new { d.PaymentNo, d.CarId, d.GuaranteeNo, d.DlrCtrNo, d.Amount,
            d.LoanPeriod, d.InterestRate }).ToListAsync();   // #155 parity Pmt_PaymentDetail
    return Results.Ok(new { count = items.Count, items, details });
}).RequireAuthorization();

app.MapPost("/api/pmtpayments/create", async (PmtPaymentCreateDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    var no = (dto.PaymentNo ?? "").Trim();
    var dealer = (dto.DealerCode ?? "").Trim();
    if (no.Length < 1) return Results.BadRequest(new { error = "Số phiếu thanh toán rỗng." });
    if (dealer.Length < 1) return Results.BadRequest(new { error = "Chưa chọn đại lý." });
    if (await db.PmtPayments.AnyAsync(x => x.OrgId == t.OrgId && x.PaymentNo == no))
        return Results.BadRequest(new { error = $"Phiếu {no} đã tồn tại." });
    var rows = (dto.Details ?? new()).Where(r => !string.IsNullOrWhiteSpace(r.CarId)).ToList();
    if (rows.Count == 0) return Results.BadRequest(new { error = "Bảng chi tiết rỗng." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    db.PmtPayments.Add(new PmtPayment
    {
        OrgId = t.OrgId, PaymentNo = no, DealerCode = dealer,
        PaymentType = dto.PaymentType,
        BankCodeSend = dto.BankCodeSend, BankCodeReceive = dto.BankCodeReceive,
        BankPaymentNo = dto.BankPaymentNo,
        BankAccountSend = dto.BankAccountSend, BankAccountReceive = dto.BankAccountReceive,
        TotalAmount = dto.TotalAmount,
        PaymentStatus = "P",
        Funds = dto.Funds, BankLending = dto.BankLending,
        PmtBakingStatus = "0",           // TConst.Flag.No — chưa đẩy sang ngân hàng
        // 🔴 Nguồn để NULL tường minh lúc tạo, không sinh sẵn:
        AccountingRecordNo = null, BulkDetailId = null,
        ApprovedDate = null, ApprovedBy = null,
        PaymentEndDate = null, ConfirmDate = null, ConfirmBy = null,
        CreatedDate = DateTime.Now, CreatedBy = who,
        // #155 parity Pmt_Payment.
        Remark = dto.Remark, TransferType = dto.TransferType,
        LoanPeriod = dto.LoanPeriod, InterestRate = dto.InterestRate,
    });
    // 🔴 #155 luật nguồn (MBBank.cs:3490-3502): từ 20220325 kỳ hạn vay / lãi suất KHÔNG lấy từ dòng nữa
    //    (hai dòng gán ở bảng chi tiết đã bị COMMENT kèm ghi chú "lấy theo MST ko cho sửa ở Dtl nữa")
    //    mà RÓT XUỐNG từ bảng đầu, và phụ thuộc cờ Funds:
    //    Funds == "1" (TConst.Flag.Yes) ⇒ để NULL; ngược lại ⇒ lấy giá trị của phiếu.
    var isFunds = (dto.Funds ?? "").Trim() == "1";
    var loanPeriodLine = isFunds ? (decimal?)null : dto.LoanPeriod;
    var interestRateLine = isFunds ? (decimal?)null : dto.InterestRate;
    foreach (var r in rows)
        db.PmtPaymentDetails.Add(new PmtPaymentDetail
        {
            OrgId = t.OrgId, PaymentNo = no,   // khoá nối về đầu là SỐ phiếu, không phải Id
            CarId = r.CarId!.Trim(), GuaranteeNo = r.GuaranteeNo, DlrCtrNo = r.DlrCtrNo, Amount = r.Amount,
            LoanPeriod = loanPeriodLine, InterestRate = interestRateLine,   // #155: rót từ bảng đầu theo cờ Funds
        });
    await db.SaveChangesAsync();
    return Results.Ok(new { paymentNo = no, details = rows.Count, status = "P" });
}).RequireAuthorization();

// ===== 🔴 #280 CSI DASHBOARD — `Rpt_DMS_CSI_Dashboard` (`ERP.ICIC/ZTemp.cs:7107`) =====
// WS `WSCarSv_ICIC.cs:2591` gọi bản **KHÔNG hậu tố**; bản `_Old` (:6601) CHẾT. Hệ `ERP.ICIC` **chỉ có
//   trên LAPTOP** ⇒ laptop là canonical cho cụm này (#277).
//
// 🔴 10 CHỈ TIÊU / ĐẠI LÝ = 5 loại × 2 cách đếm (kể trùng biển số ↔ **bỏ trùng** `count(distinct PlateNo)`).
//   Nguồn ghi thẳng hai nhãn trong SQL: `----Không bỏ trùng biển số trong kỳ tìm kiếm` và
//   `----Bỏ trùng biển số trong kỳ tìm kiếm` ⇒ **cùng một tập dòng, hai cách đếm**, không phải hai bộ lọc.
//
// 🔴 TÊN CHỈ TIÊU ĐÁNH LỪA — `NoLocal`/`NoInsurance` KHÔNG phải "loại trừ":
//   `TotalRONoLocal`     = có ROINSURANCE **HOẶC** ROREPAIR **HOẶC** ROWARRANTY  ← là phép HỢP, không phải
//     "không có LOCAL". Một LSC vừa có LOCAL vừa có ROREPAIR **VẪN được đếm**.
//   `TotalRONoInsurance` = có LOCAL **HOẶC** ROREPAIR **HOẶC** ROWARRANTY
//   `TotalRORepair100`   = có ROREPAIR
//   `TotalROLocal100`    = có LOCAL **VÀ KHÔNG** có ROINSURANCE/ROREPAIR/ROWARRANTY  ← chỉ cái này mới là
//     điều kiện loại trừ thật; hậu tố **100** mới mang nghĩa "100% loại đó".
// ⚠️ Mã thứ 5 `GENERAL` (`TConst.Ser_ROType`) **không xuất hiện trong bất kỳ chỉ tiêu con nào** ⇒ LSC chỉ có
//   dòng GENERAL vẫn vào `TotalRO` nhưng KHÔNG vào 4 chỉ tiêu còn lại. Giữ đúng, đừng "bổ sung cho đủ".
//
// Bốn điều kiện lọc dùng chung với màn CSKH 72h (#278): loại lệnh SỬA LẠI · loại PDI (vế `is null` vẫn lấy) ·
//   danh sách đại lý bị loại · `IsROFinish` chỉ nhận "1"/"0".
app.MapGet("/api/report/csi-dashboard", async (AppDbContext db, ITenantContext t,
    string? dealer, string? isRoFinish, string? rejectDealers) =>
{
    if (!string.IsNullOrWhiteSpace(isRoFinish) && isRoFinish != "1" && isRoFinish != "0")
        return Results.BadRequest(new { error = "IsROFinish chỉ nhận 1 hoặc 0.", isRoFinish });

    var ros = db.RepairOrders.Where(r => r.OrgId == t.OrgId
        && (r.IsReRepair == null || r.IsReRepair == "0")
        && (r.ROType == null || r.ROType != "PDI"));
    if (!string.IsNullOrWhiteSpace(dealer)) ros = ros.Where(r => r.DealerCode == dealer!.Trim().ToUpperInvariant());
    var reject = (rejectDealers ?? "").Split(new[] { ',', '|' }, StringSplitOptions.RemoveEmptyEntries)
        .Select(s => s.Trim().ToUpperInvariant()).Where(s => s.Length > 0).ToList();
    if (reject.Count > 0) ros = ros.Where(r => r.DealerCode == null || !reject.Contains(r.DealerCode));
    var roList = await ros.Select(r => new { r.Id, r.RONo, r.DealerCode, r.LicensePlate }).ToListAsync();
    var roIds = roList.Select(r => r.Id).ToList();

    // Đối tượng thanh toán gom từ CẢ dòng công LẪN dòng phụ tùng của lệnh (nguồn dò trên bảng chi phí của RO).
    var svcTypes = await db.RoServiceItems.Where(x => x.OrgId == t.OrgId && roIds.Contains(x.RoId) && x.ExpenseType != null)
        .Select(x => new { x.RoId, x.ExpenseType }).ToListAsync();
    var partTypes = await db.RoPartItems.Where(x => x.OrgId == t.OrgId && roIds.Contains(x.RoId) && x.ExpenseType != null)
        .Select(x => new { x.RoId, x.ExpenseType }).ToListAsync();
    var byRo = svcTypes.Concat(partTypes)
        .GroupBy(x => x.RoId)
        .ToDictionary(g => g.Key,
            g => new HashSet<string>(g.Select(x => x.ExpenseType!.Trim().ToUpperInvariant())));

    bool Has(long roId, string code) => byRo.TryGetValue(roId, out var s) && s.Contains(code);

    var rows = roList.Select(r => new
    {
        r.DealerCode, r.LicensePlate,
        local = Has(r.Id, "LOCAL"), ins = Has(r.Id, "ROINSURANCE"),
        rep = Has(r.Id, "ROREPAIR"), war = Has(r.Id, "ROWARRANTY"),
    }).ToList();

    var report = rows.GroupBy(x => x.DealerCode ?? "").Select(g =>
    {
        var noLocal = g.Where(x => x.ins || x.rep || x.war).ToList();
        var noIns = g.Where(x => x.local || x.rep || x.war).ToList();
        var rep100 = g.Where(x => x.rep).ToList();
        var local100 = g.Where(x => x.local && !x.ins && !x.rep && !x.war).ToList();
        int Dup(IEnumerable<string?> p) => p.Where(v => !string.IsNullOrWhiteSpace(v)).Distinct().Count();
        return new
        {
            dealerCode = g.Key,
            // --- kể trùng biển số ---
            totalRO = g.Count(),
            totalRONoLocal = noLocal.Count,
            totalRONoInsurance = noIns.Count,
            totalRORepair100 = rep100.Count,
            totalROLocal100 = local100.Count,
            // --- bỏ trùng biển số ---
            totalRO_NoDup = Dup(g.Select(x => x.LicensePlate)),
            totalRONoLocal_NoDup = Dup(noLocal.Select(x => x.LicensePlate)),
            totalRONoInsurance_NoDup = Dup(noIns.Select(x => x.LicensePlate)),
            totalRORepair100_NoDup = Dup(rep100.Select(x => x.LicensePlate)),
            totalROLocal100_NoDup = Dup(local100.Select(x => x.LicensePlate)),
        };
    }).OrderBy(x => x.dealerCode).ToList();

    return Results.Ok(new
    {
        expenseTypes = new[] { "ROREPAIR", "ROINSURANCE", "ROWARRANTY", "LOCAL", "GENERAL" },
        note = "NoLocal/NoInsurance là phép HỢP của ba loại còn lại, KHÔNG phải loại trừ; chỉ *100 mới loại trừ. GENERAL không vào chỉ tiêu con nào.",
        count = report.Count, rows = report,
    });
}).RequireAuthorization();

// ===== 🔴 #279 BÁO CÁO SSI (Sales Satisfaction Index) — `RptSSI_ICIC_New2011119` =====
// Chuỗi gọi 3 tầng: WS iCIC `Sales_ReportSSI_New20180622` (`ERP.ICIC/BizSalesSv.DlsDeal.cs:4681`, hệ CHỈ
//   CÓ TRÊN LAPTOP) → proxy sang `WSHTC64.RptSSI_ICIC` → biz thật `BizHTC.DealerSales.cs:6504` (cây
//   `ERP.V15.DataWH.Release.2025`, file này KHỚP 2 máy — xem bảng đo toàn cây #273).
//
// ⚠️ TRACE TWIN — chú thích `// Used` ĐÁNH LỪA: cả `Sales_ReportSSI` lẫn `Sales_ReportSSI_New20180622`
//   đều được tác giả ghi `// Used`, nhưng WS chỉ gọi bản `_New20180622` ⇒ bản kia CHẾT. Chú thích của
//   người viết KHÔNG thay được việc trace lời gọi.
// ⚠️ Bản biz thật cũng có nhiều bản trong `TERP.BizHTC/Backup/` và `Delete.BizHTC.*` — sweep .csproj cho
//   thấy **106 file CHẾT** trong TERP.BizHTC (cả thư mục `Backup/` không được biên dịch).
//
// 🔴 CÔNG THỨC `Mytotal` = SỐ CÂU ĐÃ TRẢ LỜI, đếm trên **Survey1..Survey29**:
//   `case when (Survey{i} is null or Survey{i} = '' or Survey{i} = 0) then 0 else 1 end` rồi CỘNG lại.
//   ⇒ trả lời **"0" cũng bị coi là CHƯA trả lời** (nguồn so cột text với số 0 — ép kiểu ngầm).
//
// 🔴 BỘ LỌC `StatusAnswer` (`TConst.SurveyStage`) — và **hai nhánh CHỒNG NHAU**:
//   `ALLANSWERED` ⇒ `Mytotal >= 12` · `ANSWERED` ⇒ `Mytotal >= 0 and < 12` · `NOANSWER` ⇒ `Mytotal = 0`
//   ⚠️ `Mytotal = 0` **thoả CẢ `ANSWERED` LẪN `NOANSWER`** (vì `>= 0`). Giữ nguyên hành vi nguồn.
//   ⚠️ Tên hằng `ALLANSWERED` ĐÁNH LỪA: ngưỡng là **12**, không phải 29 — "trả lời hết" ở đây nghĩa là
//      **từ 12 câu trở lên**. Đọc tên hằng mà không tra ngưỡng là port sai.
//
// 🔴 HAI ĐIỀU KIỆN LỌC GIAO DỊCH:
//   `and dd.DealerCodeBuyer is null` — **KHÔNG tính giao dịch bán ngang** (đại lý bán cho đại lý), nguồn
//     ghi chú `-- Không tính giao dịch bán ngang 20170703`.
//   `and dd.FlagInitDeal = '0'` — loại giao dịch khởi tạo.
// ⚠️ Dòng `-- and dd.CtmCareFlag = '1'` **ĐÃ BỊ COMMENT** kèm ghi chú *"Báo cáo SSI: Hiện nay dữ liệu chỉ
//   hiển thị các kiểm chứng trạng thái A"* ⇒ **KHÔNG lọc theo cờ kiểm chứng**. Port theo dòng ĐANG CHẠY.
app.MapGet("/api/report/ssi", async (AppDbContext db, ITenantContext t,
    string? dealer, DateTime? deliveryFrom, DateTime? deliveryTo,
    DateTime? ctmCareFrom, DateTime? ctmCareTo, string? statusAnswer) =>
{
    var stage = (statusAnswer ?? "").Trim().ToUpperInvariant();
    if (stage.Length > 0 && stage is not ("ALLANSWERED" or "ANSWERED" or "NOANSWER"))
        return Results.BadRequest(new { error = "StatusAnswer phải là ALLANSWERED | ANSWERED | NOANSWER." });

    var deals = db.DealerDeals.Where(d => d.OrgId == t.OrgId
        // Không tính giao dịch BÁN NGANG (đại lý bán cho đại lý) — nguồn: 20170703.
        && (d.DealerCodeBuyer == null || d.DealerCodeBuyer == "")
        // Loại giao dịch khởi tạo.
        && (d.FlagInitDeal == null || d.FlagInitDeal == "0"));
    if (!string.IsNullOrWhiteSpace(dealer)) deals = deals.Where(d => d.DealerCode == dealer!.Trim().ToUpperInvariant());
    if (ctmCareFrom.HasValue) deals = deals.Where(d => d.CtmCareUpdDate != null && d.CtmCareUpdDate >= ctmCareFrom.Value);
    if (ctmCareTo.HasValue) deals = deals.Where(d => d.CtmCareUpdDate != null && d.CtmCareUpdDate <= ctmCareTo.Value);
    var dealList = await deals.ToListAsync();
    var dealIds = dealList.Select(d => d.Id).ToList();

    var lines = await db.DealerDealDetails
        .Where(x => x.OrgId == t.OrgId && dealIds.Contains(x.DealId)
                    && (deliveryFrom == null || (x.DeliveryDate != null && x.DeliveryDate >= deliveryFrom))
                    && (deliveryTo == null || (x.DeliveryDate != null && x.DeliveryDate <= deliveryTo)))
        .ToListAsync();

    var vins = lines.Select(l => l.CarId).Distinct().ToList();
    var surveys = await db.DlsVinSurveys.Where(s => s.OrgId == t.OrgId && vins.Contains(s.VIN)).ToListAsync();

    // Đúng công thức nguồn: rỗng/null/"0" ⇒ CHƯA trả lời.
    static int Answered(string? v) => string.IsNullOrWhiteSpace(v) || v.Trim() == "0" ? 0 : 1;
    int MyTotal(DlsVinSurvey s) =>
        Answered(s.Survey1) +        Answered(s.Survey2) +        Answered(s.Survey3) +        Answered(s.Survey4) +        Answered(s.Survey5) +        Answered(s.Survey6) +        Answered(s.Survey7) +        Answered(s.Survey8) +        Answered(s.Survey9) +        Answered(s.Survey10) +        Answered(s.Survey11) +        Answered(s.Survey12) +        Answered(s.Survey13) +        Answered(s.Survey14) +        Answered(s.Survey15) +        Answered(s.Survey16) +        Answered(s.Survey17) +        Answered(s.Survey18) +        Answered(s.Survey19) +        Answered(s.Survey20) +        Answered(s.Survey21) +        Answered(s.Survey22) +        Answered(s.Survey23) +        Answered(s.Survey24) +        Answered(s.Survey25) +        Answered(s.Survey26) +        Answered(s.Survey27) +        Answered(s.Survey28) +        Answered(s.Survey29);

    var totals = surveys.ToDictionary(s => s.VIN, s => MyTotal(s));
    var dealById = dealList.ToDictionary(d => d.Id);

    var rows = lines.Select(l =>
    {
        var d = dealById[l.DealId];
        var my = totals.TryGetValue(l.CarId, out var m) ? m : 0;
        return new
        {
            dealNo = d.DealNo, carId = l.CarId, plateNo = l.PlateNo,
            deliveryDate = l.DeliveryDate, cusInvoiceNo = l.CusInvoiceNo, cusInvoiceDate = l.CusInvoiceDate,
            dealerCode = d.DealerCode, ctmCareFlag = d.CtmCareFlag, ctmCareUpdDate = d.CtmCareUpdDate,
            ctmCareUpdBy = d.CtmCareUpdBy, ctmCareRemark = d.CtmCareRemark,
            myTotal = my,
        };
    })
    // Ba nhánh nguyên văn nguồn — KHÔNG sửa chỗ chồng nhau của ANSWERED/NOANSWER.
    .Where(r => stage.Length == 0
             || (stage == "ALLANSWERED" && r.myTotal >= 12)
             || (stage == "ANSWERED" && r.myTotal >= 0 && r.myTotal < 12)
             || (stage == "NOANSWER" && r.myTotal == 0))
    .OrderByDescending(r => r.deliveryDate).Take(500).ToList();

    return Results.Ok(new
    {
        statusAnswer = stage.Length == 0 ? null : stage,
        allAnsweredThreshold = 12,        // ngưỡng THẬT của nguồn (KHÔNG phải 29)
        surveyQuestionCount = 29,
        summary = new
        {
            total = rows.Count,
            allAnswered = rows.Count(r => r.myTotal >= 12),
            noAnswer = rows.Count(r => r.myTotal == 0),
        },
        count = rows.Count, rows,
    });
}).RequireAuthorization();

// ===== KHẢO SÁT bán lẻ: theo GIAO DỊCH (DLS_DealSurvey) và theo XE/VIN (DLS_VINSurvey) =====
// Port 1:1 `DealerSalesDealUpdate_Survey_New20190424` (BizHTC.DealerSales.cs:5225) và
// `DlsVINSurvey_Update_New20190424` (7214). TWIN: đã diff TOÀN BỘ danh sách hàm của cụm ở cả hai WS —
// **khớp hoàn toàn**, không có hàm nào lệch bit (khác cụm KH đại lý ở #124).
// 🔴 29 câu hỏi `Survey1`..`Survey29` là **cột RỜI**, không phải bảng con — giữ nguyên dạng để khớp
//    schema khi import dữ liệu thật từ SQL 228.
// 🔴 KHÁC BIỆT dual-write giữa HAI bảng anh em: `DLS_DealSurvey` ghi CẢ `_dbMain` lẫn `_dbWH`
//    (5225-5226), còn `DLS_VINSurvey` có dòng `_dbWH` **BỊ COMMENT** (7215, 7538) ⇒ chỉ ghi `_dbMain`.
//    Đừng suy hành vi từ bảng này sang bảng kia.
// 🔴 Cả hai là **UPSERT theo khoá** (DealNo / VIN): nguồn có nhánh tạo mới và nhánh cập nhật riêng
//    (5225 vs 5276; 7214 vs 7537).
app.MapGet("/api/dealsurveys", async (AppDbContext db, ITenantContext t, string? dealNo) =>
{
    var qy = db.DlsDealSurveys.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealNo)) qy = qy.Where(x => x.DealNo == dealNo);
    var items = await qy.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
