    {
        k.DeclarationNo, k.OpenDate, k.PortCode, k.Remark, k.TaxPaymentDate, k.CreatedAt,
        vins = db.CtTkhqVins.Count(v => v.OrgId == t.OrgId && v.CtTkhqId == k.Id)
    }).ToListAsync();
