        contacted = db.CampaignContacts.Count(x => x.OrgId == t.OrgId && x.CampaignId == c.Id && x.ContactStatus == "Contacted"),
        running = c.StartDate <= now && (c.FinishDate == null || c.FinishDate >= now)
