// Lưu khảo sát + chốt trạng thái liên hệ (3 nút của form gộp về 1 endpoint, phân biệt bằng Status).
app.MapPost("/api/customercares/{no}/survey", async (
    string no, CareSurveyDto dto, AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var care = await db.CustomerCares.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CareNo == no);
    if (care is null) return Results.NotFound(new { no });

    // Chỉ 3 kết quả mà form cho bấm; PEND là trạng thái khởi tạo, không phải kết quả khảo sát.
    var newStatus = (dto.Status ?? "").Trim().ToUpperInvariant();
    if (newStatus is not ("CINFB" or "CIFB" or "REJ"))
        return Results.BadRequest(new { error = "Status = CINFB (đã liên hệ, chưa phản hồi) | CIFB (đã liên hệ, đã phản hồi) | REJ (không liên hệ)" });

    // Form vô hiệu hoá đúng cái nút ứng với trạng thái hiện tại ⇒ không thể chốt lại y nguyên trạng thái cũ.
    if (string.Equals(care.Status, newStatus, StringComparison.OrdinalIgnoreCase))
        return Results.BadRequest(new { error = $"Phiếu đã ở trạng thái '{careSurveyStatusTexts[newStatus]}'." });

    // ===== 🔴 #225 GUARD NGÀY LIÊN HỆ — bất đối xứng theo nhánh =====
    // Nguồn: `Views/Customer/FrmCSCCustomerCare72h.cs` (455 dòng, DMSCarSv) — 5 nút:
    //   `btnThoat` · `btnContactedIFeedB` · `btnContactedINoFB` · `btnReject` · `btnMakeAppointment`.
    // 🔴 Hai handler ĐÃ LIÊN HỆ (`btnContactedIFeedB` 284, `btnContactedINoFB` 331) mở đầu bằng
    //   `if (GetDateEditStringValue(dedContactDate) == "") { … dedContactDate.Focus(); return; }`
    //   ⇒ **BẮT BUỘC** có ngày liên hệ mới cho lưu.
    //   Handler `btnReject` (377) **KHÔNG** có guard đó — từ chối liên hệ thì không cần ngày.
    //   ⇒ Guard áp cho CINFB/CIFB, KHÔNG áp cho REJ. Giữ đúng bất đối xứng này.
    // ⚠️ `btnMakeAppointment` chỉ MỞ form `FrmQuotationApp` (điều hướng), không gọi service ⇒ không phải
    //   một lệnh ghi, không port thành endpoint.
    if (newStatus is "CINFB" or "CIFB" && dto.ContactDate is null)
        return Results.BadRequest(new { error = "Phải nhập ngày liên hệ trước khi ghi nhận đã liên hệ.", field = "ContactDate" });

    // Bỏ trống được (form có thể chưa chọn), nhưng đã nhập thì phải thuộc danh sách đáp án của câu đó.
    foreach (var (questionKey, allowedAnswers) in careSurveyAnswerOptions)
    {
        var answer = questionKey switch
        {
            "YourCarProblem" => dto.YourCarProblem,
            "YourSatisfyQSv" => dto.YourSatisfyQSv,
            "FyourCSSH"      => dto.FyourCSSH,
            "YourRIWN"       => dto.YourRIWN,
            _                => dto.WFBasicNeeds,
        };
        if (!string.IsNullOrWhiteSpace(answer) && !allowedAnswers.Contains(answer.Trim()))
            return Results.BadRequest(new { error = $"Đáp án câu '{questionKey}' không hợp lệ. Cho phép: {string.Join(", ", allowedAnswers)}" });
    }

    var actor = user.Identity?.Name;
    var now = DateTime.Now;

    // Upsert theo CareNo — nguồn đọc "top 1 * where CusCareID" rồi insert hoặc update chính bản ghi đó.
    var survey = await db.CustomerCareSurveys.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CareNo == no);
    var isNewSurvey = survey is null;
    if (survey is null)
    {
        survey = new CustomerCareSurvey { OrgId = t.OrgId, CareNo = no, CreatedBy = actor, CreatedAt = now };
        db.CustomerCareSurveys.Add(survey);
    }
    survey.RONo = string.IsNullOrWhiteSpace(dto.RONo) ? care.RONo : dto.RONo.Trim();
    survey.FinishedDate = dto.FinishedDate;
    survey.ContactDate = dto.ContactDate;
    survey.YourCarProblem = dto.YourCarProblem?.Trim();
    survey.YourSatisfyQSv = dto.YourSatisfyQSv?.Trim();
    survey.FyourCSSH = dto.FyourCSSH?.Trim();
    survey.YourRIWN = dto.YourRIWN?.Trim();
    survey.WFBasicNeeds = dto.WFBasicNeeds?.Trim();
    // Nguồn ghi cùng một giá trị ô ghi chú vào cả Note lẫn YourHopeOfOur (câu 6 tự luận) — giữ nguyên hành vi.
    survey.Note = dto.Note;
    survey.YourHopeOfOur = dto.Note;
    // ===== #211 bộ câu hỏi trắc nghiệm + hồ sơ khảo sát (Ser_CustomerCare72h) =====
    survey.CusCareType = dto.CusCareType?.Trim() ?? care.CareType;
    survey.OrderID = no;                      // 🔴 nguồn gán OrderID = CusCareID, KHÔNG phải mã đơn hàng
    survey.Remark = dto.Remark;
    survey.SurveyGmail = dto.SurveyGmail?.Trim();
    survey.SurveyDateTime = now;              // nguồn đặt = thời điểm lưu
    survey.Survey1 = dto.Survey1;
    survey.Survey2 = dto.Survey2;
    survey.Survey3 = dto.Survey3;
    survey.Survey4 = dto.Survey4;
    survey.Survey5 = dto.Survey5;
    survey.Survey6 = dto.Survey6;
    survey.Survey7 = dto.Survey7;
    survey.Survey8 = dto.Survey8;
    survey.Survey9 = dto.Survey9;
    survey.Survey10 = dto.Survey10;
    survey.Survey11 = dto.Survey11;
    survey.Survey12 = dto.Survey12;
    survey.Survey13 = dto.Survey13;
    survey.Survey14 = dto.Survey14;
    survey.Survey15 = dto.Survey15;
    survey.Survey16 = dto.Survey16;
    survey.Survey17 = dto.Survey17;
    survey.Survey18 = dto.Survey18;
    survey.Survey19 = dto.Survey19;
    survey.Survey20 = dto.Survey20;
    survey.Survey21 = dto.Survey21;
    survey.Survey22 = dto.Survey22;
    survey.Survey23 = dto.Survey23;
    survey.Survey24 = dto.Survey24;
    survey.Survey25 = dto.Survey25;
    survey.Survey26 = dto.Survey26;
    survey.Survey27 = dto.Survey27;
    survey.Survey28 = dto.Survey28;
    if (!isNewSurvey) survey.UpdatedAt = now;

    // Đồng bộ trạng thái phiếu CSKH (nguồn: Ser_CustomerCareStatusUpdate).
    // Ngày liên hệ để trống thì XOÁ ngày trên phiếu, không giữ ngày cũ.
    care.Status = newStatus;
    care.ContactDate = dto.ContactDate;
    if (newStatus != "REJ") care.ContactedAt = now;

    await db.SaveChangesAsync();
    return Results.Ok(new
    {
        care.CareNo,
        status = care.Status,
        statusText = careSurveyStatusTexts[newStatus],
        surveyCreated = isNewSurvey
    });
}).RequireAuthorization();

// ===== Chăm sóc KH chương trình MACE hãng (CustomerCareMace — port 1:1 FrmCustomerCareMace/Update/ApointDate, TCMotor DMSCarSv/Customer) =====
app.MapGet("/api/customercaremaces", async (AppDbContext db, ITenantContext t, string? maceType, string? status, string? vin) =>
{
    var q = db.CustomerCareMaces.Where(c => c.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(maceType)) q = q.Where(c => c.MaceType == maceType);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(c => c.Status == status);
    if (!string.IsNullOrWhiteSpace(vin)) q = q.Where(c => c.Vin != null && c.Vin.Contains(vin.ToUpper()));
    var items = await q.OrderByDescending(c => c.Id).Take(500).Select(c => new
    { c.CareNo, c.MaceType, c.RONo, c.Vin, c.CusName, c.Status, c.ContactDate, c.ApointDate, c.MaceRecomentDate, c.Remark }).ToListAsync();
    return Results.Ok(new { count = items.Count, pending = items.Count(x => x.Status == "Pending"), items });
}).RequireAuthorization();

// Tạo bản ghi MACE (WinForm gốc chỉ search vì nguồn phát sinh từ hãng — thêm POST để nhập tay tương đương)
// ===== 🔴 #219 BÁO CÁO TỔNG HỢP CSKH (5 nhóm) — `Ser_CustomerCareRpt` =====
// Màn gốc: `Views/Customer/FrmCustomerCareReport.cs` (178 dòng, DMSCarSv) — 2 nút `btnSearch` · `btnThoat`.
// Nguồn: `TERP.BizCarSv/BizCarSv.Customer.cs:17534`. 3B: md5 CẢ FILE `44c7c87b` KHỚP 2 máy.
//
// Nguồn đếm 4 chỉ tiêu (`Total` · `Pending` · `IsContact` · `IsNotContact`) cho **5 nhóm** CSKH.
// 🔴 MỖI NHÓM DÙNG **BẢNG MÃ KHÁC NHAU** — đây là chỗ dễ port sai nhất, đã đối chiếu từng dòng SQL:
//     `#tblCustomerCareMace` (bảo dưỡng) : Pending=`'0'` · IsContact=`'1'` · IsNotContact=`'2'`
//     `#tblCustomerCareBth`  (sinh nhật) : Pending=`'0'` · IsContact=`'1'` · IsNotContact=`'2'`
//     `#tblCustomerCare72h`             : Pending=`'PEND'` · IsContact=`'CINFB' OR 'CIFB'` · IsNotContact=`'REJ'`
//     `#tblCustomerCare24h`             : (giống 72h)
//     `#tblCustomerCareCamp` (chiến dịch): 🔴 **Pending=`'2'` · IsContact=`'1'` · IsNotContact=`'3'`**
//        ⇒ nhóm chiến dịch **ĐẢO** so với Mace/Bth: mã `'2'` ở đây là "chưa liên hệ", không phải "không liên hệ".
//
// ⚠️ MiniHTC lưu 24h/72h trên CÙNG bảng `CustomerCares`, phân biệt bằng `CareType` (#220: mã nguồn `24h`/`72h`)
//    ⇒ tách hai nhóm bằng CareType, đúng ngữ nghĩa nguồn (nguồn tách bằng hai bảng tạm).
//
// ===== 🔴🔴 #492 ĐÍNH CHÍNH #219 — **MỌI NHÓM ĐỀU LỌC SAI CỘT NGÀY** =====
// #219 lọc cả năm nhóm bằng `ContactDate`. Đọc lại từng bảng tạm của nguồn thì **mỗi nhóm lọc một cột KHÁC**:
//   · Nhắc bảo dưỡng : `zzzzClauseWhere**MaceRecomentDate**ConditionList` (ngày HẸN bảo dưỡng)
//   · Sinh nhật      : `AND t.DateBth is not null` + `zzzzClauseWhere**DateBth**ConditionList`
//   · 72h            : mốc trên **`ro.ActualDeliveryDate`** (ngày GIAO XE), **không** phải ngày liên hệ
//   · 24h            : `zzzzClauseWhere**FinishedDate24**ConditionList`
//   · Chiến dịch     : `t.StartDate >= @FromDate` **và** `t.FinishedDate <= @ToDate` (hai cột khác nhau!)
//   ⇒ Lọc theo `ContactDate` làm **rơi mọi phiếu chưa liên hệ** (cột đó còn NULL) — tức chính nhóm `Pending`
//     mà báo cáo cần đếm. #219 có `x.ContactDate == null ||` nên không rơi hết, nhưng **khoảng thời gian**
//     vẫn sai hoàn toàn về ngữ nghĩa. Nay sửa từng nhóm về đúng cột.
//
// 🔴 **72h vs 24h KHÔNG chỉ khác bảng — khác cả ĐIỀU KIỆN NGHIỆP VỤ**:
//     72h: `AND ro.IsReRepair = "0"`   (lệnh **không** phải sửa lại)
//     24h: `AND ro.IsReRepair = "1"`   (lệnh **SỬA LẠI** — gọi lại sau 24 giờ)
//   #219 chỉ tách bằng `CareType` ⇒ **thiếu hẳn** vế này. Nay lọc thêm theo lệnh sửa chữa.
// 🔴 **CỬA SỔ 72h BỊ DỊCH, KHÔNG ĐỐI XỨNG**:
//     `DATEADD(day, 1, ro.ActualDeliveryDate) >= "@FromDate"`  ⇒ `ActualDeliveryDate >= From - 1 ngày`
//     `DATEADD(day, 3, ro.ActualDeliveryDate) <= "@ToDate"`    ⇒ `ActualDeliveryDate <= To - 3 ngày`
//   ⇒ Không phải "giao xe trong kỳ" mà là **"cửa sổ gọi 72h rơi trong kỳ"**. Lệch hai đầu khác nhau
//     (−1 và −3) nên **không thể rút gọn thành một khoảng quanh kỳ**. Giữ nguyên công thức.
app.MapGet("/api/report/customercare-summary", async (AppDbContext db, ITenantContext t,
    DateTime? fromDate, DateTime? toDate, string? dealerCode) =>
{
    var from = fromDate?.Date;
    var to = toDate?.Date;

    // --- nhóm 1+2: 24h / 72h trên bảng CustomerCares (mã PEND / CINFB|CIFB / REJ) ---
    // #492: mốc thời gian lấy từ LỆNH SỬA CHỮA, không phải ContactDate của phiếu.
    var allRos = await db.RepairOrders.Where(x => x.OrgId == t.OrgId).ToListAsync();
    var roByNoAll = allRos.GroupBy(x => x.RONo).ToDictionary(g => g.Key, g => g.First());
    var cares = await db.CustomerCares.Where(x => x.OrgId == t.OrgId).ToListAsync();

    // 72h: IsReRepair = "0", cửa sổ DỊCH (−1 / −3 ngày) trên ActualDeliveryDate.
    var cares72 = cares.Where(x => x.CareType == "72h").Where(x =>
    {
        if (x.RONo == null || !roByNoAll.TryGetValue(x.RONo, out var ro)) return false;
        if ((ro.IsReRepair ?? "") != "0") return false;
        var d = ro.ActualDeliveryDate?.Date; if (d is null) return false;
        if (from.HasValue && d.Value.AddDays(1) < from.Value) return false;
        if (to.HasValue && d.Value.AddDays(3) > to.Value) return false;
        return true;
    }).ToList();

    // 24h: IsReRepair = "1", mốc trên FinishedDate của lệnh.
    var cares24 = cares.Where(x => x.CareType == "24h").Where(x =>
    {
        if (x.RONo == null || !roByNoAll.TryGetValue(x.RONo, out var ro)) return false;
        if ((ro.IsReRepair ?? "") != "1") return false;
        var d = ro.FinishedDate?.Date; if (d is null) return false;
        if (from.HasValue && d.Value < from.Value) return false;
        if (to.HasValue && d.Value > to.Value) return false;
        return true;
    }).ToList();

    object CareGroup(string label, IEnumerable<CustomerCare> src)
    {
        var l = src.ToList();
        return new
        {
            group = label,
            total = l.Count,
            pending = l.Count(x => x.Status == "PEND"),
            isContact = l.Count(x => x.Status == "CINFB" || x.Status == "CIFB"),
            isNotContact = l.Count(x => x.Status == "REJ")
        };
    }

    var g24 = CareGroup("24h", cares24);
    var g72 = CareGroup("72h", cares72);

    // --- nhóm 3: nhắc bảo dưỡng (mã 0/1/2) ---
    var maces = await db.CustomerCareMaces.Where(x => x.OrgId == t.OrgId).ToListAsync();
    // #492: nguồn lọc MaceRecomentDate (ngày HẸN bảo dưỡng), KHÔNG phải ContactDate.
    if (!string.IsNullOrWhiteSpace(dealerCode)) maces = maces.Where(x => x.DealerCode == dealerCode).ToList();
    if (from.HasValue) maces = maces.Where(x => x.MaceRecomentDate != null && x.MaceRecomentDate.Value.Date >= from.Value).ToList();
    if (to.HasValue) maces = maces.Where(x => x.MaceRecomentDate != null && x.MaceRecomentDate.Value.Date <= to.Value).ToList();
    var gMace = new { group = "MACE", total = maces.Count,
        pending = maces.Count(x => x.Status == "0"),
        isContact = maces.Count(x => x.Status == "1"),
        isNotContact = maces.Count(x => x.Status == "2") };

    // --- nhóm 4: sinh nhật (mã 0/1/2) ---
    var bths = await db.CustomerCareBirthdays.Where(x => x.OrgId == t.OrgId).ToListAsync();
    if (!string.IsNullOrWhiteSpace(dealerCode)) bths = bths.Where(x => x.DealerCode == dealerCode).ToList();
    // #492: nguồn lọc DateBth và bắt buộc `DateBth is not null`, KHÔNG phải ContactDate.
    bths = bths.Where(x => x.DateBth != null).ToList();
    if (from.HasValue) bths = bths.Where(x => x.DateBth!.Value.Date >= from.Value).ToList();
    if (to.HasValue) bths = bths.Where(x => x.DateBth!.Value.Date <= to.Value).ToList();
    var gBth = new { group = "BIRTHDAY", total = bths.Count,
        pending = bths.Count(x => x.Status == "0"),
        isContact = bths.Count(x => x.Status == "1"),
        isNotContact = bths.Count(x => x.Status == "2") };

    // --- nhóm 5: chiến dịch — 🔴 bảng mã ĐẢO: 2 = chưa liên hệ, 1 = đã liên hệ, 3 = không liên hệ ---
    var camps = await db.CampaignContacts.Where(x => x.OrgId == t.OrgId).ToListAsync();
    var gCamp = new { group = "CAMPAIGN", total = camps.Count,
        pending = camps.Count(x => x.ContactStatus == "2"),
        isContact = camps.Count(x => x.ContactStatus == "1"),
        isNotContact = camps.Count(x => x.ContactStatus == "3") };

    var groups = new List<object> { g24, g72, gMace, gBth, gCamp };
    return Results.Ok(new { fromDate = from, toDate = to, groups,
        note = "Mỗi nhóm dùng bảng mã RIÊNG (24h/72h: PEND/CINFB|CIFB/REJ · Mace+Bth: 0/1/2 · Campaign: 2/1/3 — đảo).",
        // ===== #492 =====
        dateColumnPerGroup = new
        {
            care72h = "ro.ActualDeliveryDate (cua so DICH -1/-3 ngay)",
            care24h = "ro.FinishedDate",
            mace = "MaceRecomentDate",
            birthday = "DateBth (bat buoc not null)",
            campaign = "StartDate >= From VA FinishedDate <= To",
        },
        reRepairSplit = new { care72h = "IsReRepair = 0", care24h = "IsReRepair = 1" },
        supersedes = "#219 loc ca 5 nhom bang ContactDate — sai cot ngay o moi nhom",
        skipped = "Nguồn lọc thêm theo DealerCode cho mọi nhóm; MiniHTC chỉ có DealerCode trên nhóm sinh nhật, các nhóm khác chưa lưu ⇒ KHÔNG bịa." });
}).RequireAuthorization();

// ===== 🔴 #218 NHẮC BẢO DƯỠNG theo phiếu CSKH — `Ser_CustomerCareMaintance` =====
// Màn gốc: `Views/Customer/FrmCSCCustomerCareMaintance.cs` (238 dòng, DMSCarSv) —
//   bốn nút: `btnThoat` · `btnContactedIFeedB` · `btnContactedINoFB` · `btnReject`.
// Nguồn: `TERP.BizCarSv/BizCarSv.Customer.cs:16472`. 3B: md5 CẢ FILE `44c7c87b` KHỚP 2 máy.
//
// 🔴 BẪY ĐẶT TÊN NÚT — ba nút map sang ba mã theo HẰNG, KHÔNG theo tên nút:
//     `btnContactedIFeedB`  → `SerCareStatus.ContactedINeedFB` = **CINFB** (đã liên hệ, CHƯA phản hồi)
//     `btnContactedINoFB`   → `SerCareStatus.ContactedIFNoB`   = **CIFB**  (đã liên hệ, ĐÃ phản hồi)
//     `btnReject`           → `SerCareStatus.Reject`           = **REJ**
//   Tên nút và tên hằng NGƯỢC nhau về nghĩa (IFeedB ↔ INeedFB, INoFB ↔ IFNoB) ⇒ phải bám hằng.
//
// 🔴 MỘT THAO TÁC CHẠM HAI BẢNG:
//   1. `Ser_CustomerCareMaintance` — **upsert** theo `CusCareID`, ghi 3 cột `DateAppointment`/`ContactDate`/`Note`;
//   2. gọi `Ser_CustomerCareStatusUpdate` đặt `Status` (+ `ContactDate`) trên PHIẾU CHÍNH `Ser_CustomerCare`.
//   Bỏ bước 2 thì phiếu vẫn ở "PEND" dù đã ghi nhận liên hệ — lỗi âm thầm.
//
// ⚠️ Khác #217: `ContactDate` ở đây **chỉ ghi khi có giá trị** (`if (!IsEmpty(strConatctDate))`) — để trống thì
//   GIỮ NGUYÊN giá trị cũ, không set NULL. Giữ đúng khác biệt này.
app.MapPost("/api/customercares/{no}/maintance", async (string no, CareMaintanceDto dto,
    AppDbContext db, ITenantContext t, System.Security.Claims.ClaimsPrincipal user) =>
{
    no = no.Trim().ToUpperInvariant();
    var care = await db.CustomerCares.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CareNo == no);
    if (care is null) return Results.NotFound(new { no });

    var status = (dto.Status ?? "").Trim().ToUpperInvariant();
    if (status is not ("CINFB" or "CIFB" or "REJ"))
        return Results.BadRequest(new { error = "Trạng thái chỉ nhận CINFB (chưa phản hồi) | CIFB (đã phản hồi) | REJ (không liên hệ)." });

    var who = user.Identity?.Name ?? user.FindFirst("email")?.Value ?? "system";
    var now = DateTime.Now;

    // (1) upsert bảng nhắc bảo dưỡng
    var row = await db.CustomerCareMaintances.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CareNo == no);
    var isNew = row is null;
    if (row is null) { row = new CustomerCareMaintance { OrgId = t.OrgId, CareNo = no, CreatedAt = now }; db.CustomerCareMaintances.Add(row); }
    row.DateAppointment = dto.DateAppointment;
    if (dto.ContactDate.HasValue) row.ContactDate = dto.ContactDate;   // rỗng ⇒ GIỮ giá trị cũ (đúng nguồn)
    row.Note = dto.Note;
    if (!isNew) { row.UpdatedAt = now; row.UpdatedBy = who; }

    // (2) side-effect: cập nhật trạng thái trên PHIẾU CHÍNH
    care.Status = status;
    if (dto.ContactDate.HasValue) { care.ContactDate = dto.ContactDate; care.ContactedAt = now; }
    if (status == "CINFB") { care.IsCall = "1"; care.IsFeedback = "0"; }
    else if (status == "CIFB") { care.IsCall = "1"; care.IsFeedback = "1"; }

    await db.SaveChangesAsync();
    return Results.Ok(new { care.CareNo, status = care.Status, care.IsCall, care.IsFeedback,
                            row.DateAppointment, row.ContactDate, row.Note, created = isNew });
}).RequireAuthorization();

app.MapGet("/api/customercares/{no}/maintance", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var row = await db.CustomerCareMaintances.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CareNo == no);
    if (row is null) return Results.NotFound(new { no });
    return Results.Ok(new { row.CareNo, row.DateAppointment, row.ContactDate, row.Note,
                            row.CreatedAt, row.UpdatedAt, row.UpdatedBy });
}).RequireAuthorization();

// ===== 🔴 #216 LỊCH HẸN BẢO DƯỠNG đã chốt ngày — `Ser_CustomerCareMaceApointDate_Get` =====
// Màn gốc: `Views/Customer/FrmCustomerCareMaceApointDate.cs` (369 dòng, DMSCarSv) —
//   ba nút `btnSearch` · `btnExportExcel` · `btnThoat` (grep KHÔNG phân biệt hoa/thường, luật #212).
// Nguồn: `TERP.BizCarSv/BizCarSv.Customer.cs:13429`. 3B: md5 CẢ FILE `44c7c87b` KHỚP 2 máy (đo ở #210).
//
// 🔴 HAI GUARD CỨNG trong chính câu SQL của nguồn (không phải tham số lọc):
//     `and t.Status = '1'`            — CHỈ lấy dòng **đã liên hệ**
//     `and t.ApointDate is not null`  — và **đã chốt ngày hẹn**
//   ⇒ đây là màn "lịch hẹn đã chốt", KHÔNG phải danh sách nhắc bảo dưỡng nói chung
//     (danh sách chung là `/api/customercaremaces` đã có, lọc status tuỳ ý).
//
// Bảng mã `TConst.SerCareMaceStatus` (Const.Main.cs:365): **0 chưa liên hệ · 1 đã liên hệ · 2 không liên hệ**
//   — nguồn dịch sang chữ ngay trong SELECT (`StatusText`); port trả kèm để khỏi map lại ở client.
// Bộ lọc của form: tên khách + biển số + khoảng `ApointDate` (from/to). Nguồn dựng bằng `BuildClause`,
//   chuỗi rỗng ⇒ **bỏ hẳn điều kiện** (luật `C0-trecentesimusvicesimusquartus`).
app.MapGet("/api/customercaremaces/appointments", async (AppDbContext db, ITenantContext t,
    string? cusName, string? plateNo, DateTime? fromDate, DateTime? toDate) =>
{
    // hai guard cứng của nguồn — luôn áp, không cho client tắt
    var qy = db.CustomerCareMaces.Where(c => c.OrgId == t.OrgId && c.Status == "1" && c.ApointDate != null);

    if (!string.IsNullOrWhiteSpace(cusName))
        qy = qy.Where(c => c.CusName != null && c.CusName.ToLower().Contains(cusName!.Trim().ToLower()));
    if (!string.IsNullOrWhiteSpace(plateNo))
        qy = qy.Where(c => c.Vin != null && c.Vin.ToLower().Contains(plateNo!.Trim().ToLower()));
    if (fromDate.HasValue) qy = qy.Where(c => c.ApointDate!.Value.Date >= fromDate.Value.Date);
    if (toDate.HasValue) qy = qy.Where(c => c.ApointDate!.Value.Date <= toDate.Value.Date);

    var items = await qy.OrderBy(c => c.ApointDate).Take(500)
        .Select(c => new
        {
            c.CareNo, c.MaceType, c.RONo, c.Vin, c.CusName,
            c.Status,
            statusText = c.Status == "0" ? "Chưa liên hệ" : c.Status == "1" ? "Đã liên hệ" : c.Status == "2" ? "Không liên hệ" : c.Status,
            c.ContactDate, c.ApointDate, c.MaceRecomentDate, c.Remark
        }).ToListAsync();

    return Results.Ok(new { count = items.Count, items,
        note = "Luôn lọc Status='1' (đã liên hệ) và ApointDate != null — hai điều kiện nằm CỨNG trong SQL nguồn.",
        skipped = "Nguồn còn join Ser_Car (FrameNo) + ser_mst_model + ser_ro để hiện khung/model/lệnh sửa chữa — MiniHTC lưu Vin trên chính dòng, chưa nối các bảng đó, KHÔNG bịa." });
}).RequireAuthorization();

app.MapPost("/api/customercaremaces", async (CustomerCareMaceDto dto, AppDbContext db, ITenantContext t) =>
{
    var maceType = (dto.MaceType ?? "").Trim();
    if (string.IsNullOrWhiteSpace(maceType)) return Results.BadRequest(new { error = "Chưa nhập MaceType." });
    if (string.IsNullOrWhiteSpace(dto.Vin) && string.IsNullOrWhiteSpace(dto.CusName))
        return Results.BadRequest(new { error = "Cần VIN hoặc tên khách." });
    var no = "MC" + DateTime.Now.ToString("yyMMddHHmmss");
    var c = new CustomerCareMace
    {
        OrgId = t.OrgId, CareNo = no, MaceType = maceType, RONo = dto.RONo, Vin = dto.Vin?.Trim().ToUpperInvariant(),
        CusName = dto.CusName, MaceRecomentDate = dto.MaceRecomentDate, Status = "Pending"
    };
    db.CustomerCareMaces.Add(c); await db.SaveChangesAsync();
    return Results.Ok(new { c.CareNo, c.MaceType, status = c.Status });
}).RequireAuthorization();

// Cập nhật trạng thái liên hệ (khớp FrmCustomerCareMaceUpdate: Contacted bắt buộc có ContactDate).
app.MapPost("/api/customercaremaces/{no}/contact", async (string no, CareMaceContactDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var c = await db.CustomerCareMaces.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CareNo == no);
    if (c is null) return Results.NotFound(new { no });
    var status = (dto.Status ?? "").Trim();
    if (!_maceStatuses.Contains(status)) return Results.BadRequest(new { error = "Status = Pending|Contacted|NotContacted" });
    if (status == "Contacted" && dto.ContactDate is null)
        return Results.BadRequest(new { error = "Bạn chưa nhập Ngày liên hệ. Hãy nhập Ngày liên hệ để cập nhật tình trạng liên hệ." });
    c.Status = status; c.Remark = dto.Remark;
    c.ContactDate = status == "Contacted" ? dto.ContactDate : null;
    c.ApointDate = status == "Contacted" ? dto.ApointDate : null;
    await db.SaveChangesAsync();
    return Results.Ok(new { c.CareNo, status = c.Status });
}).RequireAuthorization();

// ===== 🔴 #281 TỔNG ĐÀI TRA KHÁCH + XE THEO SỐ ĐIỆN THOẠI — `Ser_CustomerCar_Get_ByPhone_New20180622` =====
// Nguồn: `ERP.ICIC/TERP.BizCarSv/BizCarSv.Customer.cs:930` (hệ **CHỈ CÓ TRÊN LAPTOP**).
// TRACE TWIN: ba bản — bản trần (:152) · `_Old` (:537) · `_New20180622` (:930). WS `WSCarSv_ICIC.cs:1314`
//   gọi **`_New20180622`** ⇒ hai bản kia CHẾT.
//
// 🔴 SỐ ĐIỆN THOẠI KHỚP TRÊN **HAI CỘT**, nối bằng `OR` — đây là điểm cốt lõi của màn tổng đài:
//     `and ( ((1=1) <đk trên t.Tel>) OR ((1=1) <đk trên t.Mobile>) )`
//   và mỗi vế dùng `BuildClauseConditionList(..., strPhoneList, "|")` ⇒ **NHẬN NHIỀU SỐ, ngăn bằng `|`**.
//   ⇒ endpoint `/api/customercars` sẵn có KHÔNG thay thế được: nó chỉ so MỘT cột `CusPhone` với MỘT chuỗi.
//
// 🔴 `car.DealerCode not in (@DealerCodeRejectList)` nằm ở **WHERE** trong khi `Ser_Car` là **LEFT JOIN**
//   ⇒ với khách **CHƯA CÓ XE**, `car.DealerCode` là NULL, mà `NULL not in (...)` cho ra **UNKNOWN** ⇒ dòng
//   bị LOẠI. Tức LEFT JOIN bị điều kiện WHERE biến thành **INNER JOIN**: **khách không có xe không bao giờ
//   ra kết quả**. Đây là hành vi THẬT của hệ đang chạy ⇒ port giữ nguyên (`requireCar` mặc định bật) và
//   mở tham số để đối soát; đổi thành LEFT JOIN thật sẽ làm tổng đài thấy thêm khách mà hệ cũ không thấy.
//
// Các guard còn lại: `t.IsActive = 1` · `t.CusID is not null` · `t.DealerCode not in (reject)` ·
//   `car.IsActive = 1` nằm **trên điều kiện JOIN** (không phải WHERE) · sắp xếp `order by t.CusName asc`.
// 📌 NỢ: nguồn còn gọi WS Sales lấy thêm khách bên bán hàng (`strSalesSessionId` + `GenInCondition`) rồi
//   ghép bảng `Sales_DealerCustomer` — MiniHTC chưa có tầng gọi WS ngoài.
app.MapGet("/api/servicecustomers/by-phone", async (AppDbContext db, ITenantContext t,
    string? phones, string? dealer, string? cusName, string? plateNo, string? frameNo,
    string? rejectDealers, bool? requireCar) =>
{
    // Danh sách số ngăn bằng "|" đúng như nguồn (nhận thêm "," cho tiện gọi từ web).
    var phoneList = (phones ?? "").Split(new[] { '|', ',' }, StringSplitOptions.RemoveEmptyEntries)
        .Select(s => s.Trim()).Where(s => s.Length > 0).ToList();

    var cus = db.ServiceCustomers.Where(c => c.OrgId == t.OrgId
        && c.FlagActive == "1"                    // t.IsActive = 1
        && c.CusCode != "");                      // t.CusID is not null
    if (!string.IsNullOrWhiteSpace(dealer)) cus = cus.Where(c => c.DealerCode == dealer!.Trim().ToUpperInvariant());
    if (!string.IsNullOrWhiteSpace(cusName)) cus = cus.Where(c => c.CusName.Contains(cusName!));

    var reject = (rejectDealers ?? "").Split(new[] { ',', '|' }, StringSplitOptions.RemoveEmptyEntries)
        .Select(s => s.Trim().ToUpperInvariant()).Where(s => s.Length > 0).ToList();
    if (reject.Count > 0) cus = cus.Where(c => c.DealerCode == null || !reject.Contains(c.DealerCode));

    var cusList = await cus.ToListAsync();

    // Tel HOẶC Mobile — khớp bất kỳ số nào trong danh sách.
    if (phoneList.Count > 0)
        cusList = cusList.Where(c => phoneList.Any(p =>
            (c.Tel != null && c.Tel.Contains(p)) || (c.Mobile != null && c.Mobile.Contains(p)))).ToList();

    var codes = cusList.Select(c => c.CusCode).ToList();
    var cars = await db.ServiceCars.Where(x => x.OrgId == t.OrgId && x.FlagActive == "1"
            && x.CusID != null && codes.Contains(x.CusID))
        .ToListAsync();
    if (!string.IsNullOrWhiteSpace(plateNo)) cars = cars.Where(x => x.PlateNo != null && x.PlateNo.Contains(plateNo!.ToUpperInvariant())).ToList();
    if (!string.IsNullOrWhiteSpace(frameNo)) cars = cars.Where(x => x.FrameNo.Contains(frameNo!.ToUpperInvariant())).ToList();
    if (reject.Count > 0) cars = cars.Where(x => x.DealerCode == null || !reject.Contains(x.DealerCode)).ToList();

    var carsByCus = cars.GroupBy(x => x.CusID!).ToDictionary(g => g.Key, g => g.ToList());

    // Mặc định GIỮ hành vi nguồn: khách không có xe thì KHÔNG ra (xem chú thích LEFT JOIN ở trên).
    var mustHaveCar = requireCar ?? true;

    var items = cusList
        .Where(c => !mustHaveCar || carsByCus.ContainsKey(c.CusCode))
        .OrderBy(c => c.CusName)                  // order by t.CusName asc
        .Take(500)
        .Select(c => new
        {
            c.CusCode, c.CusName, c.Tel, c.Mobile, c.Address, c.DealerCode,
            cars = carsByCus.TryGetValue(c.CusCode, out var cs)
                ? cs.Select(x => new { x.FrameNo, x.PlateNo, x.ModelCode, x.InsNo, x.DealerCode, x.CurrentKm, x.CurrentServiceDate }).ToList()
                : new(),
        }).ToList();

    return Results.Ok(new
    {
        phones = phoneList, requireCar = mustHaveCar, rejectedDealers = reject,
        note = "Nguồn khớp Tel HOẶC Mobile; khách chưa có xe bị loại do car.DealerCode not in (...) đặt ở WHERE trên LEFT JOIN.",
        count = items.Count, items,
    });
}).RequireAuthorization();

// ===== Xe của khách hàng (Ser_Car — port 1:1 FrmCustomerCar) =====
app.MapGet("/api/customercars", async (AppDbContext db, ITenantContext t, string? plate, string? vin, string? cus) =>
{
    var q = db.CustomerCars.Where(c => c.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(plate)) q = q.Where(c => c.PlateNo.Contains(plate.ToUpper()));
    if (!string.IsNullOrWhiteSpace(vin)) q = q.Where(c => c.Vin.Contains(vin.ToUpper()));
    if (!string.IsNullOrWhiteSpace(cus)) q = q.Where(c => (c.CusName != null && c.CusName.Contains(cus)) || (c.CusPhone != null && c.CusPhone.Contains(cus)));
    var items = await q.OrderBy(c => c.PlateNo).Take(500).Select(c => new
    { c.Vin, c.PlateNo, c.FrameNo, c.EngineNo, c.ModelCode, c.ColorCode, c.PlateColorCode, c.CusCode, c.CusName, c.CusPhone, c.SaleDate }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/customercars", async (CustomerCarDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.Vin) && string.IsNullOrWhiteSpace(dto.PlateNo))
        return Results.BadRequest(new { error = "Cần VIN hoặc biển số." });
    var vin = (dto.Vin ?? "").Trim().ToUpperInvariant();
    var plate = (dto.PlateNo ?? "").Trim().ToUpperInvariant();
    // upsert theo VIN nếu có, ngược lại theo biển số
    CustomerCar? c = null;
    if (vin.Length > 0) c = await db.CustomerCars.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Vin == vin);
    if (c is null && plate.Length > 0) c = await db.CustomerCars.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Vin == "" && x.PlateNo == plate);
    if (c is null) { c = new CustomerCar { OrgId = t.OrgId, Vin = vin, PlateNo = plate }; db.CustomerCars.Add(c); }
    else { if (vin.Length > 0) c.Vin = vin; if (plate.Length > 0) c.PlateNo = plate; }
    c.FrameNo = dto.FrameNo; c.EngineNo = dto.EngineNo; c.ModelCode = dto.ModelCode; c.ColorCode = dto.ColorCode; c.PlateColorCode = dto.PlateColorCode;
    c.CusCode = dto.CusCode; c.CusName = dto.CusName; c.CusPhone = dto.CusPhone; c.SaleDate = dto.SaleDate; c.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { c.Vin, c.PlateNo, c.CusName });
}).RequireAuthorization();

// ===== Giá bán phụ tùng theo ngày hiệu lực (Ser_Inv_PartPrice — port 1:1 FrmPartPriceCreate) =====
app.MapGet("/api/partprices", async (AppDbContext db, ITenantContext t, string? part, string? onDate) =>
{
    var q = db.PartPrices.Where(p => p.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(part)) q = q.Where(p => p.PartCode.Contains(part.ToUpper()));
    var items = await q.OrderBy(p => p.PartCode).ThenByDescending(p => p.EffectiveDate).Take(1000).Select(p => new
    { p.PartCode, p.PartName, p.Price, p.VAT, p.PriceVAT, p.EffectiveDate, p.Status, p.Remark, p.IsActive }).ToListAsync();   // #295 §12
    object? applicable = null;
    if (!string.IsNullOrWhiteSpace(part) && DateTime.TryParse(onDate, out var od))
        applicable = items.Where(x => x.PartCode == part.Trim().ToUpperInvariant() && x.EffectiveDate <= od)
            .OrderByDescending(x => x.EffectiveDate).FirstOrDefault();
    return Results.Ok(new { count = items.Count, applicable, items });
}).RequireAuthorization();

app.MapPost("/api/partprices", async (PartPriceDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.PartCode)) return Results.BadRequest(new { error = "Cần PartCode." });
    // 🔴 #256: `Views/Inventory/FrmPartPriceImport.cs:125` — guard **SỐNG** (khác `FrmImportPart` bị comment):
    //   `if (this.regex.IsMatch(strPartCode)) ShowWarningMsgBox(MSG_WARNING_KEYSPE_PARTCODE)`
    //   md5 `3874df4a` — KHỚP 2 máy.
    if (HasSpecialChar(dto.PartCode.Trim()))
        return Results.BadRequest(new { error = "Mã phụ tùng không được phép chứa các ký tự đặc biệt" });
    if (dto.EffectiveDate is null) return Results.BadRequest(new { error = "Cần EffectiveDate." });
    var code = dto.PartCode.Trim().ToUpperInvariant();
    var ed = dto.EffectiveDate.Value.Date;
    var p = await db.PartPrices.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.PartCode == code && x.EffectiveDate == ed);
    if (p is null) { p = new PartPrice { OrgId = t.OrgId, PartCode = code, EffectiveDate = ed }; db.PartPrices.Add(p); }
    p.PartName = dto.PartName; p.Price = dto.Price; p.VAT = dto.VAT; p.PriceVAT = Math.Round(dto.Price * (1 + dto.VAT / 100m), 2);
    p.Status = dto.Status ?? "1";
    // #295: hai cột RIÊNG của nguồn — `IsActive` mặc định "1" (bật), KHÔNG suy từ `Status`.
    p.Remark = dto.Remark;
    p.IsActive = string.IsNullOrWhiteSpace(dto.IsActive) ? "1" : dto.IsActive!.Trim();
    p.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { p.PartCode, p.Price, p.VAT, p.PriceVAT, p.EffectiveDate });
}).RequireAuthorization();

// ===== Phiếu xuất kho phụ tùng (Ser_Inv_StockOut — port 1:1 FrmStockOutCreate), TRỪ tồn PartStock =====
// ===== 🔴 #264 LOẠI XUẤT + NHÃN + khối VẬN CHUYỂN/ĐIỀU CHỈNH — `TblSerInvStockOut` =====
// DbDefine.cs:1257-1303 (md5 `d373e758` — KHỚP 2 máy), tìm qua sweep `sweep_tblconst_tail.js` (#261).
//
// 🔴 VOCABULARY LOẠI XUẤT — mã **NGƯỢC TRỰC GIÁC**, đọc kỹ kẻo gán nhầm:
//     `StockOutTypeServiceValue = "1"` ⇒ **Xuất dịch vụ**
//     `StockOutTypeNormalValue  = "2"` ⇒ **Xuất thường**
//   (số nhỏ hơn KHÔNG phải loại "thường" — cùng bẫy với `DeliveryFormCode.BAOHANH = "2"` ở #240.)
// 🔴 VOCABULARY TRẠNG THÁI (:1288-1298): "0" Mới (`StatusNewValue`, KHÔNG có Text) · "1" Mới tạo ·
//   "2" Tiến hành · "3" Kết thúc · "4" Đã điều chỉnh · "5" Đã hủy.
//   ⚠️ Mã "0" có Value nhưng **KHÔNG có Text** ⇒ nguồn không hiển thị nhãn cho nó.
// ⚠️ Nguồn lưu **CẢ NHÃN** trong DB: `StatusText` và `StockOutTypeText` — không chỉ mã.
var stockOutTypeNames = new Dictionary<string, string>
{
    ["1"] = "Xuất dịch vụ",   // StockOutTypeServiceValue/Text
    ["2"] = "Xuất thường",    // StockOutTypeNormalValue/Text
};

// ===== 🔴 #288 Trạng thái PHIẾU XUẤT nhìn từ MÀN BÁO GIÁ — nhãn KHÁC HẲN màn phiếu xuất =====
// Nguồn: `BizCarSv.Inventory.Quote.cs:1530-1534` (lặp lại ở `:1817`), đọc CÙNG cột
//   `Ser_Inv_StockOut.Status` nhưng gán nhãn khác — đúng luật "nhãn theo MÀN" đã rút ở #286.
//
// | mã | màn PHIẾU XUẤT (#264) | màn BÁO GIÁ (#288) |
// |----|----------------------|--------------------|
// | `NULL` | (không có nhãn)      | **"Mới tạo"** ← nghĩa: **CHƯA lập phiếu xuất nào** |
// | `1` | "Mới tạo"            | **"Đã tạo phiếu xuất"** |
// | `2` | "Tiến hành"          | **(không có nhãn ⇒ NULL)** |
// | `3` | "Kết thúc"           | "Đã xuất" |
// | `4` | "Đã điều chỉnh"      | "Đã điều chỉnh phiếu xuất" |
// | `5` | "Đã hủy"             | "Đã hủy phiếu xuất" |
//
// 🔴 HAI điểm dễ port sai:
//   1. Màn báo giá **diễn giải NULL thành một trạng thái nghiệp vụ** ("chưa lập phiếu xuất") — NULL ở đây
//      KHÔNG phải "thiếu dữ liệu". Bỏ nhánh `is null` là mất hẳn trạng thái đầu tiên của luồng.
//   2. Mã `2` **nhảy cóc**: màn báo giá không có nhánh cho nó ⇒ trả NULL. Đừng "điền cho đủ".
//   ⇒ Cùng một mã `1`: màn phiếu xuất đọc là "Mới tạo", màn báo giá đọc là "Đã tạo phiếu xuất" — hai câu
//     nói về hai chủ thể khác nhau (phiếu vs báo giá), không mâu thuẫn.
var stockOutStatusNamesByScreen = new Dictionary<string, Dictionary<string, string>>
{
    // Màn PHIẾU XUẤT (Ser_Inv_StockOut) — #264.
    ["stockout"] = new()
    {
        ["1"] = "Mới tạo", ["2"] = "Tiến hành", ["3"] = "Kết thúc",
        ["4"] = "Đã điều chỉnh", ["5"] = "Đã hủy",
    },
    // Màn BÁO GIÁ sửa chữa nhìn sang phiếu xuất — Inventory.Quote.cs.
    // Khoá "(null)" là quy ước của port cho nhánh `so.Status is null` của nguồn.
    ["quote"] = new()
    {
        ["(null)"] = "Mới tạo",
        ["1"] = "Đã tạo phiếu xuất",
        ["3"] = "Đã xuất",
        ["4"] = "Đã điều chỉnh phiếu xuất",
        ["5"] = "Đã hủy phiếu xuất",
    },
};

// Giữ tên cũ cho các chỗ đã dùng: mặc định là bảng của màn PHIẾU XUẤT.
var stockOutStatusNames = stockOutStatusNamesByScreen["stockout"];

// Tra nhãn theo màn — nguồn KHÔNG có nhánh ELSE ⇒ mã lạ trả NULL, không phải chuỗi rỗng.
string? StockOutStatusName(string screen, string? code)
{
    if (!stockOutStatusNamesByScreen.TryGetValue(screen, out var map)) return null;
    var key = string.IsNullOrWhiteSpace(code) ? "(null)" : code!.Trim();
    return map.TryGetValue(key, out var n) ? n : null;
}

app.MapGet("/api/stockouts/statusnames", (string? screen) =>
{
    var key = string.IsNullOrWhiteSpace(screen) ? "stockout" : screen!.Trim().ToLowerInvariant();
    if (!stockOutStatusNamesByScreen.TryGetValue(key, out var map))
        return Results.BadRequest(new { error = "screen phải là stockout | quote.", screen = key });
    return Results.Ok(new
    {
        screen = key,
        names = map.Select(kv => new { code = kv.Key, name = kv.Value }),
        screens = stockOutStatusNamesByScreen.Keys,
        note = "Cùng cột Ser_Inv_StockOut.Status, hai màn hai bảng nhãn. Màn quote diễn giải NULL = \"Mới tạo\" (chưa lập phiếu xuất) và KHÔNG có nhãn cho mã 2.",
    });
}).RequireAuthorization();

app.MapGet("/api/stockouts/vocab", () => Results.Ok(new
{
    stockOutTypes = stockOutTypeNames.Select(kv => new { code = kv.Key, name = kv.Value }),
    statuses = stockOutStatusNames.Select(kv => new { code = kv.Key, name = kv.Value }),
    note = "Mã loại xuất NGƯỢC trực giác: 1 = Xuất dịch vụ, 2 = Xuất thường. Mã trạng thái 0 có Value nhưng không có Text ở nguồn.",
})).RequireAuthorization();

app.MapGet("/api/stockouts", async (AppDbContext db, ITenantContext t, string? status, string? warehouse) =>
{
    var q = db.PartStockOuts.Where(s => s.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(s => s.Status == status);
    if (!string.IsNullOrWhiteSpace(warehouse)) q = q.Where(s => s.WarehouseCode == warehouse);
    var items = await q.OrderByDescending(s => s.Id).Take(500).Select(s => new
    {
        s.StockOutNo, s.StockOutDate, s.StockOutType, s.WarehouseCode, s.Reason, s.Status, s.PostedAt,
        // #264: cột bổ sung (§12)
        s.StockOutTypeText, s.StatusText, s.UserCode, s.CusID, s.DealerCode, s.Description,   // #292 §12
        s.TruckNo, s.DriverName, s.DriverID, s.DrivingLicense,
        s.AdjustmentBy, s.AdjustmentDate, s.AdjustmentNote, s.OldStockOutID, s.OldStockOutNo,
        s.LogLUDateTime, s.LogLUBy,
        lines = db.PartStockOutLines.Count(l => l.OrgId == t.OrgId && l.StockOutId == s.Id)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/stockouts", async (StockOutDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.WarehouseCode)) return Results.BadRequest(new { error = "Cần WarehouseCode." });
    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.PartCode) && l.Quantity > 0).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Cần ít nhất 1 dòng phụ tùng (PartCode + Quantity > 0)." });
    var no = "SO" + DateTime.Now.ToString("yyMMddHHmmss");
    var h = new PartStockOut
    {
        OrgId = t.OrgId, StockOutNo = no, StockOutDate = dto.StockOutDate ?? DateTime.Now,
        StockOutType = dto.StockOutType, WarehouseCode = dto.WarehouseCode.Trim().ToUpperInvariant(),
        Reason = dto.Reason, Status = "1",
        // #264: nhãn lưu kèm mã, đúng như nguồn (StatusText / StockOutTypeText).
        StatusText = stockOutStatusNames.TryGetValue("1", out var st1) ? st1 : null,
        StockOutTypeText = dto.StockOutType is not null && stockOutTypeNames.TryGetValue(dto.StockOutType, out var tn) ? tn : null,
        UserCode = dto.UserCode, CusID = dto.CusID, DealerCode = dto.DealerCode,
        TruckNo = dto.TruckNo, DriverName = dto.DriverName, DriverID = dto.DriverID,
        DrivingLicense = dto.DrivingLicense,
        LogLUDateTime = DateTime.Now, LogLUBy = dto.UserCode,
    };
    // 🔴 #304: nguồn đặt `FlagSyncVeloca = Flag.Inactive` **ngay khi tạo** (4 chỗ, cả DB đại lý lẫn DB kho)
    //   ⇒ phiếu mới luôn ở trạng thái "chưa đồng bộ Veloca". Mặc định entity đã là "0", ghi rõ cho khỏi lệch.
    h.FlagSyncVeloca = "0";
    // 🔴 #304 LUẬT GIỜ XUẤT KHO (`StockOut.cs:2207-2216`): `StockOutDateTime` = ngày xuất + **giờ hiện tại**
    //   NẾU ngày xuất là HÔM NAY; ngược lại là **00:00:00**. Phiếu lùi ngày không được mang giờ của lúc nhập.
    //   ⚠️ Luật này chỉ còn trong `SerStockOutUpdate_New20240115` — bản **CHẾT** (WS gọi bản trần).
    //     Port vào đây vì nó là quy tắc dữ liệu hợp lý và `StockOutDateTime` được dùng để tính giá vốn
    //     bình quân (`GetAverageCost(..., StockOutDateTime)`) lẫn để đẩy Veloca. **Khai rõ là mở rộng**,
    //     không phải trích từ đường chạy LIVE.
    h.StockOutDateTime = h.StockOutDate.Date == DateTime.Now.Date
        ? DateTime.Now
        : h.StockOutDate.Date;
    db.PartStockOuts.Add(h); await db.SaveChangesAsync();

    // 🔴 #294: nguồn `SerStockOutCreate` (`StockOut.cs:540`) gọi `SerStockOutOrderStockOutCreate` ⇒ khi phiếu
    //   xuất được tạo **TỪ MỘT LỆNH XUẤT**, ghi một dòng vào bảng nối. Quan hệ NHIỀU-NHIỀU: một lệnh có thể
    //   sinh nhiều phiếu (giao nhiều đợt). Nguồn lưu CẢ khoá lẫn SỐ của hai phía.
    if (!string.IsNullOrWhiteSpace(dto.StockOutOrderNo))
    {
        var soNo = dto.StockOutOrderNo!.Trim().ToUpperInvariant();
        var soo = await db.SerStockOutOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.OrderNo == soNo);
        if (soo is null) return Results.BadRequest(new { error = "Không tìm thấy lệnh xuất kho: " + soNo });
        db.SerStockOutOrderStockOuts.Add(new SerStockOutOrderStockOut
        {
            OrgId = t.OrgId,
            StockOutOrderId = soo.Id, StockOutOrderNo = soo.OrderNo,
            StockOutId = h.Id, StockOutNo = h.StockOutNo,
            LogLUDateTime = DateTime.Now, LogLUBy = dto.UserCode,
        });
        await db.SaveChangesAsync();
    }
    foreach (var l in lines)
        db.PartStockOutLines.Add(new PartStockOutLine { OrgId = t.OrgId, StockOutId = h.Id, PartCode = l.PartCode.Trim().ToUpperInvariant(), PartName = l.PartName, Location = l.Location, Quantity = l.Quantity, Price = l.Price, Vat = l.Vat, UnitCode = l.UnitCode, RoFactor = l.RoFactor, RoPrice = l.RoPrice });   // #368 §12
    await db.SaveChangesAsync();
    return Results.Ok(new { h.StockOutNo, h.WarehouseCode, lines = lines.Count, status = h.Status });
}).RequireAuthorization();

// #294 Tra các phiếu xuất đã sinh ra từ MỘT lệnh xuất (quan hệ NHIỀU-NHIỀU qua bảng nối).
app.MapGet("/api/stockoutorders/{id:long}/stockouts", async (long id, AppDbContext db, ITenantContext t) =>
{
    var h = await db.SerStockOutOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (h is null) return Results.NotFound(new { id });
    var items = await (from lk in db.SerStockOutOrderStockOuts
                       join so in db.PartStockOuts on lk.StockOutId equals so.Id
                       where lk.OrgId == t.OrgId && so.OrgId == t.OrgId && lk.StockOutOrderId == id
                       orderby lk.Id
                       select new
                       {
                           lk.StockOutNo, so.Status,
                           statusName = stockOutStatusNames.ContainsKey(so.Status) ? stockOutStatusNames[so.Status] : null,
                           so.StockOutDate, lk.LogLUDateTime, lk.LogLUBy,
                       }).ToListAsync();
    return Results.Ok(new { stockOutOrderId = id, orderNo = h.OrderNo, count = items.Count, items,
        blocksEdit = items.Any(x => x.Status == "1" || x.Status == "2" || x.Status == "3") });
}).RequireAuthorization();

// ===== 🔴 #304 ĐỒNG BỘ PHIẾU XUẤT SANG VELOCA (`OSVeloca_Ser_Inv_StockOut_*`) — chưa từng port =====
// Nguồn: `BizCarSv.Inventory.StockOut.cs`; WS có **7** WebMethod cho trục này (StockIn 3 + StockOut 4).
// TRACE TWIN: WS `:17685` gọi `..._GetByStockOutID_New20240606` ⇒ bản `_GetByStockOutID` (`:18670`) CHẾT.
//
// 🔴 LUẬT GIỜ UTC — **CHỈ áp cho trục Veloca/OS, KHÔNG áp cho HCC**:
//   Nguồn viết `CONVERT(varchar, DateAdd(hh, -7, X), 20) …UTC` ở **49 chỗ** (StockIn 4 · StockOut 4 ·
//   ZTemp 41) ⇒ mọi trường tên `*UTC` của trục này = **giờ địa phương TRỪ 7** (VN = UTC+7).
//   ⚠️ Ngược lại `HCCIntergration/BizCarSv.HCC.cs` **KHÔNG có lấy một** `DateAdd(hh,-7)` nào ⇒ payload HCC
//     gửi **giờ địa phương** dù tên trường cũng là `…DTimeUTC`. Hai trục, hai luật — **đừng áp đại trà**.
//     (Vì vậy `AppointmentDTimeUTC` và `DeliveryDTimeUTC` đã port ở các vòng trước là ĐÚNG, giữ nguyên.)
static string? VelocaUtc(DateTime? v) => v?.AddHours(-7).ToString("yyyy-MM-dd HH:mm:ss");

// 🔴 BẢN ĐỒ ĐẠI LÝ → KHO gõ CỨNG trong SQL nguồn, kèm chú thích của tác giả:
//   *"20240401. HuongTTT: Code này xử lý cho trường hợp PX không truyền vào Mã kho -> Sau khi NC cho PX
//     truyền vào mã kho thì rem đoạn này lại."*
//   ⇒ đây là **giải pháp TẠM có hạn dùng**, tác giả nói rõ sẽ bỏ. Bản đúng (đọc `Ser_Inv_Stock` /
//   `Ser_Mst_Location`) nằm ngay trên nhưng **đang bị comment**. Theo luật B port DÒNG ĐANG CHẠY,
//   đồng thời ghi lại ý định để vòng sau biết đường thay.
//   ⚠️ `else` gộp **mọi đại lý khác** về `PTDL` — blacklist, không phải whitelist.
var velocaDealerInv = new Dictionary<string, string>
{
    ["VN029"] = "PTDL",     // Đông Đô
    ["VN068"] = "PTDL",     // Đông Anh
    ["V3601"] = "KHOTONG",  // Lam Kinh
    ["VN012"] = "PTHD",     // Hải Phòng
    ["VN063"] = "PTDL",     // Ninh Bình
};
static string VelocaInvCode(Dictionary<string, string> m, string? dealer)
    => dealer is not null && m.TryGetValue(dealer, out var v) ? v : "PTDL";   // else của nguồn

// #304 Danh sách phiếu xuất theo trạng thái đồng bộ Veloca.
// ⚠️ `flagSync` rỗng = **LẤY CẢ HAI** (đúng nguồn: `'' = @strFlagSyncVeloca or siso.FlagSyncVeloca = @…`),
//   KHÔNG phải "không lọc gì" một cách tình cờ — đó là giá trị thứ ba có nghĩa.
app.MapGet("/api/stockouts/veloca-pending", async (AppDbContext db, ITenantContext t,
    string? flagSync, string? dealer) =>
{
    var qy = db.PartStockOuts.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrEmpty(flagSync)) qy = qy.Where(x => x.FlagSyncVeloca == flagSync);
    if (!string.IsNullOrWhiteSpace(dealer)) qy = qy.Where(x => x.DealerCode == dealer!.Trim().ToUpperInvariant());
    var rows = await qy.OrderByDescending(x => x.Id).Take(500).ToListAsync();
    return Results.Ok(new
    {
        count = rows.Count,
        note = "flagSync rỗng ⇒ lấy CẢ đã và chưa đồng bộ (giá trị thứ ba có nghĩa của nguồn).",
        items = rows.Select(x => new
        {
            x.Id, x.StockOutNo, x.DealerCode, x.WarehouseCode, x.Status,
            x.StockOutDate, x.StockOutDateTime, x.FlagSyncVeloca, x.SyncVelocaDTime,
            velocaInvCode = VelocaInvCode(velocaDealerInv, x.DealerCode),
        }),
    });
}).RequireAuthorization();

// #304 Payload đẩy MỘT phiếu xuất sang Veloca (`..._GetByStockOutID_New20240606`).
app.MapGet("/api/stockouts/{id:long}/veloca-payload", async (long id, AppDbContext db, ITenantContext t) =>
{
    var h = await db.PartStockOuts.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
