app.MapGet("/api/auth/app-login-eligibility", (string dealerCode, string userCode, string? versionApp) =>
{
    var d = (dealerCode ?? "").Trim();
    var u = (userCode ?? "").Trim();
    var isWa = string.Equals(versionApp, "WAVersion_App_idocNet2024", StringComparison.Ordinal);

    string? blockedBy = null, reason = null;
    if (!isWa)   // danh sách chặn CHỈ áp khi không đăng nhập từ WA
    {
        if (appLoginBlockedWithException.TryGetValue(d, out var allowed))
        {
            // ⚠️ nguồn so bằng `StringUtils.StringEqual`; riêng VS065 liệt kê cả hai dạng chữ.
            if (!allowed.Contains(u, StringComparer.Ordinal))
            { blockedBy = "exception-list"; reason = "Đại lý đã triển khai web — chỉ tài khoản ngoại lệ được dùng app."; }
        }
        else if (appLoginBlockedAll.Contains(d))
        { blockedBy = "blanket-list"; reason = "Đại lý đã triển khai web — app bị dừng cho toàn bộ tài khoản."; }
    }

    return Results.Ok(new
    {
        dealerCode = d, userCode = u,
        versionApp, isWaLogin = isWa,
        allowed = blockedBy is null,
        blockedBy, reason,
        // Cách XÁC THỰC tương ứng — hai đường khác hẳn nhau.
        authMode = isWa ? "HCC token (HCCService.Login, kiểm AccessToken)" : "so mật khẩu local với Sys_User.UserPassword",
        // Trạng thái đại lý có bị bắt buộc Active không.
        dealerActiveRequired = !appLoginDealerActiveExempt.Contains(d),
        note = "Nguồn ném mã lỗi CommonAppData_SysUserInvalidFlagActive (nghĩa gốc: user bị khoá) cho cả "
             + "trường hợp đại lý đã lên web ⇒ thông điệp lệch nghiệp vụ. Ở đây trả reason đúng lý do.",
    });
}).RequireAuthorization();

// ===== 🔴 #321 SỬA LỆNH SỬA CHỮA (`Ser_RO_Update_New20230220`) — nhánh TÁCH khỏi Create =====
// 🆕 Cụm này do sweep `sweep_twin_column_delta.js` (#320) chỉ ra: **8 bản**, chênh **23 cột**.
//   TRACE TWIN: WS `:10794` gọi `_New20230220` ⇒ 7 bản còn lại CHẾT.
//   So tập cột: Update ghi **57**, trong đó **7 cột KHÔNG có ở Create** — các trường phát sinh
//   TRONG QUÁ TRÌNH sửa chữa (vai trò kỹ thuật + mốc thời gian).
//
// 🔴 HAI LUẬT GHI KHÁC NHAU trong CÙNG một hàm — đây là điểm dễ port sai nhất:
//   (a) **VÔ ĐIỀU KIỆN** — `Assistant` · `Engineer` · `QA` · `Operator` · `QuanDoc` ·
//       `ScheduleDate` · `CheckInDate` · `PlanedDuration` · `CusRequest` · `CarStatus` …
//       ⇒ truyền rỗng là **XOÁ** giá trị đang có, KHÔNG phải "giữ nguyên".
//   (b) **CÓ GUARD RỖNG** — chỉ `StartDate` và `FinishedDate`:
//       `if (String.IsNullOrEmpty(strStartDate)) { } else { … }` ⇒ rỗng thì **giữ nguyên**.
//   ⚠️ Vì vậy KHÔNG được viết một vòng lặp "chỉ gán khi khác rỗng" cho tất cả — sẽ mất khả năng
//     **gỡ người phụ trách** (đặt lại rỗng) mà nguồn cho phép.
//
// ⚠️ `Convert.ToDateTime(strScheduleDate)` và `…(strCheckInDate)` **không có guard** ⇒ nguồn **ném
//   FormatException** khi tham số rỗng. Đây đúng lớp lỗi đã ghi trong hook (`Convert.To*` trên ô rỗng).
//   Port KHÔNG bắt chước crash: thiếu ngày ⇒ trả `400` có thông điệp, và ghi rõ chỗ lệch này.
// ⚠️ Nguồn lưu ngày dạng `"yyyy-MM-dd HH:mm"` ⇒ **cắt mất GIÂY**. Port cắt giây y hệt để đối chiếu khớp.
app.MapPut("/api/repairorders/{no}", async (string no, RepairOrderUpdateDto dto, AppDbContext db, ITenantContext t) =>
{
    var roNo = no.Trim().ToUpperInvariant();
    var r = await db.RepairOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == roNo);
    if (r is null) return Results.NotFound(new { no = roNo });

    // Nguồn Convert.ToDateTime KHÔNG guard ⇒ crash. Ở đây báo lỗi rõ thay vì crash (khai báo lệch).
    if (dto.ScheduleDate is null) return Results.BadRequest(new { error = "Thiếu ScheduleDate (nguồn ném FormatException khi rỗng)." });
    if (dto.CheckInDate is null) return Results.BadRequest(new { error = "Thiếu CheckInDate (nguồn ném FormatException khi rỗng)." });

    // Cắt GIÂY đúng như nguồn ("yyyy-MM-dd HH:mm").
    static DateTime ToMinute(DateTime v) => new DateTime(v.Year, v.Month, v.Day, v.Hour, v.Minute, 0);

    // (a) nhóm VÔ ĐIỀU KIỆN — rỗng = XOÁ.
    r.Assistant = dto.Assistant;
    r.Engineer = dto.Engineer;
    r.QA = dto.QA;
    r.Operator = dto.Operator;
    r.QuanDoc = dto.QuanDoc;
    r.ScheduleDate = ToMinute(dto.ScheduleDate!.Value);
    r.CheckInDate = ToMinute(dto.CheckInDate!.Value);
    r.PlanedDuration = dto.PlanedDuration;
    r.CusRequest = dto.CusRequest;
    r.CarStatus = dto.CarStatus;

    // (b) nhóm CÓ GUARD — rỗng = GIỮ NGUYÊN.
    if (dto.StartDate.HasValue) r.StartDate = ToMinute(dto.StartDate.Value);
    if (dto.FinishedDate.HasValue) r.FinishedDate = ToMinute(dto.FinishedDate.Value);

    r.ModifyBy = dto.ModifyBy; r.ModifyDate = DateTime.Now;
    r.LogLUBy = dto.ModifyBy; r.LogLUDateTime = DateTime.Now;
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        r.RONo, r.Assistant, r.Engineer, r.QA, r.Operator, r.QuanDoc,
        r.ScheduleDate, r.CheckInDate, r.StartDate, r.FinishedDate,
        r.PlanedDuration, r.CusRequest, r.CarStatus, r.ModifyBy, r.ModifyDate,
        note = "Năm vai trò kỹ thuật + ScheduleDate/CheckInDate ghi VÔ ĐIỀU KIỆN (rỗng = XOÁ); "
             + "StartDate/FinishedDate có guard (rỗng = GIỮ NGUYÊN). Ngày cắt tới PHÚT như nguồn.",
    });
}).RequireAuthorization();

app.MapGet("/api/repairorders/statusnames", (string? screen) =>
{
    var key = string.IsNullOrWhiteSpace(screen) ? "rosearch" : screen!.Trim().ToLowerInvariant();
    if (!roStatusDisplayNamesByScreen.TryGetValue(key, out var map))
        return Results.BadRequest(new { error = "screen phải là một trong: "
            + string.Join(" | ", roStatusDisplayNamesByScreen.Keys), screen = key });
    return Results.Ok(new
    {
        screen = key,
        names = map.Select(kv => new { code = kv.Key, name = kv.Value }),
        // #307: #306 có chú thích "trả kèm nhánh else" nhưng THỰC RA CHƯA trả — nay trả thật.
        //   Ba màn ba kết cục cho mã lạ: "Không xác định" · "" (chuỗi rỗng) · null (không có else).
        fallback = roStatusFallbackByScreen.TryGetValue(key, out var fb) ? fb : "Không xác định",
        screens = roStatusDisplayNamesByScreen.Keys,
        fallbackByScreen = roStatusFallbackByScreen.Select(kv => new { screen = kv.Key, elseValue = kv.Value }),
        note = "#286: nhãn hiển thị KHÁC NHAU theo màn (cùng mã W4P: rosearch=\"Hủy, Hẹn lại\" · tabhome=\"Đợi phụ tùng\" · stockout=\"Không dùng\"). "
             + "Khác nữa với bảng NHÓM TÌM KIẾM (/api/repairorders?stage=...) vốn gộp Paid vào Sửa xong.",
    });
}).RequireAuthorization();

// ===== 🔴 #283 TRA LỆNH SỬA CHỮA CHÉO ĐẠI LÝ (tổng đài iCIC) — `Ser_RO_GetStatusHistoryList_New20180622` =====
// Nguồn: `ERP.ICIC/TERP.BizCarSv/BizCarSv.Customer.cs:2869` (hệ **CHỈ CÓ TRÊN LAPTOP**).
// TRACE TWIN: ba bản — bản trần (:2362) · `_Old` (:2611) · `_New20180622` (:2869);
//   WS `WSCarSv_ICIC.cs:2399` gọi bản `_New20180622` ⇒ hai bản kia CHẾT.
// 🆕 SWEEP vỏ rỗng (sinh từ #282): WS iCIC có **51 `[WebMethod]` / 50 lời gọi `_biz.` sống / 1 bị comment**
//   ⇒ đúng MỘT endpoint vỏ rỗng là `Ser_App_Create_ForWeb`; 50 cái còn lại đều có ruột.
//
// ⚠️ TÊN HÀM ĐÁNH LỪA: "GetStatusHistoryList" **KHÔNG phải nhật ký đổi trạng thái của một lệnh** — nó là
//   **TÌM lệnh sửa chữa CHÉO ĐẠI LÝ** kèm trạng thái hiện tại. Nhật ký thật của LSC là chuyện khác.
//
// 🔴 LUẬT CHE DỮ LIỆU CHÉO ĐẠI LÝ (thứ dễ mất nhất khi port):
//     `CASE tpro.DealerCode WHEN '@strCallerDealerCode' THEN ('LS-'+RONo) ELSE '******' END NormalizedRONo`
//     `CASE tpro.DealerCode WHEN '@strCallerDealerCode' THEN tpro.Creator ELSE '******' END NormalizedCreator`
//   ⇒ đại lý gọi API **chỉ thấy số lệnh và người lập của CHÍNH MÌNH**; của đại lý khác bị che `******`.
//   Port bỏ qua luật này = **lộ số lệnh + người lập của mọi đại lý** cho bất kỳ ai gọi được API.
//   ⚠️ Dòng `RORONo = 'BG-' + RONo` thì **KHÔNG che** — tiền tố `BG-` (báo giá) hiện với mọi đại lý.
//
// ⚠️ HAI TIỀN TỐ khác nhau trên cùng một `RONo`: `BG-` (báo giá) và `LS-` (lệnh sửa chữa) — khớp đúng luật
//   bóc tiền tố đã port ở `/api/stockreqs`.
// ⚠️ `TOP 500` + `ORDER BY ro.CheckInDate DESC` đặt ở **truy vấn LỌC ĐẦU TIÊN**, trước mọi join ⇒ cắt theo
//   ngày tiếp nhận, không phải cắt sau khi ghép dữ liệu.
// #284: bản DMSCarSv của CÙNG màn này (`Ser_RO_GetStatusList02_New20230220`) có thêm bộ lọc
//   `strActualDeliveryDate` (ngày GIAO XE thực tế) và trả kèm `plateNoList` — bản iCIC không có.
//   Gộp vào đây thay vì dựng endpoint thứ hai: **cùng một màn, hai hệ gọi**.
app.MapGet("/api/repairorders/status-history", async (AppDbContext db, ITenantContext t,
    string? callerDealerCode, string? dealers, string? status, string? plateNo, string? frameNo,
    string? cusName, DateTime? checkInDate, DateTime? actualDeliveryDate) =>
{
    var caller = (callerDealerCode ?? "").Trim().ToUpperInvariant();

    var qy = db.RepairOrders.Where(r => r.OrgId == t.OrgId);
    var dealerList = (dealers ?? "").Split(new[] { ',', '|' }, StringSplitOptions.RemoveEmptyEntries)
        .Select(s => s.Trim().ToUpperInvariant()).Where(s => s.Length > 0).ToList();
    if (dealerList.Count > 0) qy = qy.Where(r => r.DealerCode != null && dealerList.Contains(r.DealerCode));
    if (!string.IsNullOrWhiteSpace(status)) qy = qy.Where(r => r.Status == status);
    if (!string.IsNullOrWhiteSpace(plateNo)) qy = qy.Where(r => r.LicensePlate.Contains(plateNo!.ToUpperInvariant()));
    if (!string.IsNullOrWhiteSpace(frameNo)) qy = qy.Where(r => r.Vin != null && r.Vin.Contains(frameNo!.ToUpperInvariant()));
    if (!string.IsNullOrWhiteSpace(cusName)) qy = qy.Where(r => r.CusName != null && r.CusName.Contains(cusName!));
    if (checkInDate.HasValue)
    {
        var d0 = checkInDate.Value.Date; var d1 = d0.AddDays(1);
        qy = qy.Where(r => r.CheckInDate != null && r.CheckInDate >= d0 && r.CheckInDate < d1);
    }

    if (actualDeliveryDate.HasValue)
    {
        var a0 = actualDeliveryDate.Value.Date; var a1 = a0.AddDays(1);
        qy = qy.Where(r => r.ActualDeliveryDate != null && r.ActualDeliveryDate >= a0 && r.ActualDeliveryDate < a1);
    }

    // TOP 500 + sắp theo ngày tiếp nhận GIẢM DẦN — đúng vị trí của nguồn: cắt TRƯỚC khi ghép dữ liệu.
    var rows = await qy.OrderByDescending(r => r.CheckInDate).Take(500).ToListAsync();

    // ===== 🔴 #301 BẢN CHỤP TRÊN LỆNH, MASTER CHỈ LÀ DỰ PHÒNG =====
    // Nguồn trả **mọi** cột khách/xe qua `isnull(ro.X, <master>.X)` ⇒ lệnh giữ dữ liệu **tại thời điểm
    //   tiếp nhận**; sửa hồ sơ khách/xe hôm nay KHÔNG được làm đổi lệnh cũ. Port cũ đọc thẳng cột lệnh
    //   ⇒ lệnh nào chưa chụp thì ra rỗng, và không có đường lấy dự phòng.
    // ⚠️ Thứ tự dự phòng của nguồn **KHÔNG đối xứng** — phải chép đúng, đừng "chuẩn hoá":
    //     CusName   : ro.CusName   → cus.**ContName** → cus.CusName      (người liên hệ ĐỨNG TRƯỚC)
    //     CusAddress: ro.CusAddress→ cus.**Address**  → cus.ContAddress  (địa chỉ KH đứng trước — NGƯỢC LẠI)
    //     CusTel    : ro.CusTel    → cus.Tel          → cus.ContTel
    //     CusMobile : ro.CusMobile → cus.Mobile       → cus.ContMobile
    //     CusTaxCode: ro.CusTaxCode→ cus.TaxCode                          (chỉ HAI cấp)
    // ⚠️ `OwnerName = cus.CusName` lấy THẲNG, không dự phòng: đó là **chủ xe**, khác `CusName` (người mang xe đến).
    var cusIds = rows.Select(r => r.CusID).Where(x => !string.IsNullOrWhiteSpace(x)).Distinct().ToList();
    var vins = rows.Select(r => r.Vin).Where(x => !string.IsNullOrWhiteSpace(x)).Distinct().ToList();
    var cusMap = cusIds.Count == 0 ? new Dictionary<string, ServiceCustomer>()
        : (await db.ServiceCustomers.Where(c => c.OrgId == t.OrgId && cusIds.Contains(c.CusCode)).ToListAsync())
            .GroupBy(c => c.CusCode).ToDictionary(g => g.Key, g => g.First());
    // ⚠️ XẤP XỈ ĐÃ KHAI: nguồn ghép xe theo `ro.CarID = car.CarID`; MiniHTC chưa có `CarID` trên lệnh nên
    //   ghép theo số khung. Trùng khung trong cùng đại lý là bất thường ⇒ chấp nhận được, nhưng ghi rõ.
    var carMap = vins.Count == 0 ? new Dictionary<string, ServiceCar>()
        : (await db.ServiceCars.Where(c => c.OrgId == t.OrgId && vins.Contains(c.FrameNo)).ToListAsync())
            .GroupBy(c => c.FrameNo).ToDictionary(g => g.Key, g => g.First());

    static string? Co(params string?[] vs) { foreach (var v in vs) if (!string.IsNullOrWhiteSpace(v)) return v; return null; }

    const string MASK = "******";
    var items = rows.Select(r =>
    {
        var own = caller.Length > 0 && string.Equals(r.DealerCode, caller, StringComparison.OrdinalIgnoreCase);
        var cus = r.CusID is not null && cusMap.TryGetValue(r.CusID, out var c0) ? c0 : null;
        var car = r.Vin is not null && carMap.TryGetValue(r.Vin, out var v0) ? v0 : null;
        return new
        {
            r.RONo,
            roRONo = "BG-" + r.RONo,                                  // tiền tố BÁO GIÁ — KHÔNG che
            normalizedRONo = own ? "LS-" + r.RONo : MASK,             // tiền tố LỆNH SỬA CHỮA — CHE nếu khác đại lý
            normalizedCreator = own ? r.Creator : MASK,
            r.DealerCode, r.Status,
            statusName = RoStatusDisplayName(r.Status),   // #284 nhãn hiển thị của nguồn
            r.CheckInDate, r.ActualDeliveryDate,
            isOwnDealer = own,
            // #320 §12: 27 cột mới có mặt ở CẢ GET lẫn POST
            r.AdvisoryCode, r.AdvisoryPhone, r.CarID, r.CarWashRequested, r.CusTypeID, r.DlrPDIReqNo,
            r.EngineerID, r.FlagOnlyPoint, r.FlagPause, r.IDCardNo, r.InsNo, r.InsuranceDeductible,
            r.InvoiceBy, r.LevelOfInspection, r.ModifyBy, r.ModifyDate, r.PayByCard, r.PlanedDuration,
            r.ReminderMaintanceDate, r.ReminderMaintanceKm, r.ServiceStatus, r.TermsOfRepair,
            r.UseSHPart, r.WorkDoneSoon, r.CreatedBy, r.LogLUBy, r.LogLUDateTime,

            // --- #301: chuỗi dự phòng ĐÚNG THỨ TỰ NGUỒN ---
            r.CusID,
            ownerName = cus?.CusName,                                        // CHỦ XE (không dự phòng)
            cusName = Co(r.CusName, cus?.ContName, cus?.CusName),            // người MANG XE ĐẾN
            cusAddress = Co(r.CusAddress, cus?.Address, cus?.ContAddress),
            cusTel = Co(r.CusTel, cus?.Tel, cus?.ContTel),
            cusMobile = Co(r.CusMobile, cus?.Mobile, cus?.ContMobile),
            cusTaxCode = Co(r.CusTaxCode, cus?.TaxCode),
            modelID = Co(r.ModelID, car?.ModelCode),
            licensePlate = Co(r.LicensePlate, car?.PlateNo),
            frameNo = Co(r.Vin, car?.FrameNo),
            vin = Co(r.Vin, car?.FrameNo),
            engineNo = Co(r.EngineNo, car?.EngineNo),
            colorCode = Co(r.ColorCode, car?.ColorCode),
            tradeMarkCode = Co(r.TradeMarkCode, car?.TradeMark),
            r.BatteryNo, r.SerialNo,
            warrantyRegistrationDate = r.WarrantyRegistrationDate ?? car?.WarrantyRegistrationDate,
            warrantyExpiresDate = r.WarrantyExpiresDate,
            r.WarrantyKM,

            // 🔴 #301 KHÔNG NHẤT QUÁN CỦA NGUỒN, giữ nguyên + khai báo:
            //   `TradeMarkNameModel = tm.TradeMarkName + ' - ' + mdl.ModelName` ghép từ **hiệu/dòng của XE**
            //   (`tm`/`mdl` join theo `car`), **bỏ qua** bản chụp `ro.TradeMarkCode`/`ro.ModelID` mà chính
            //   truy vấn đó vừa ưu tiên ở các cột `isnull(...)` bên trên. Nên cột ghép có thể mâu thuẫn với
            //   hai cột thành phần. Thêm nữa: nguồn nối bằng `+` nên **một vế NULL ⇒ CẢ CHUỖI NULL**.
            r.TrademarkNameModel,
            trademarkNameModelNote = "Nguồn ghép từ hiệu/dòng của XE, bỏ qua bản chụp trên lệnh; + với NULL ⇒ NULL.",
        };
    }).ToList();

    return Results.Ok(new
    {
        callerDealerCode = caller.Length == 0 ? null : caller,
        note = "Số lệnh (LS-) và người lập bị che ****** khi lệnh thuộc đại lý KHÁC đại lý gọi; tiền tố BG- không che.",
        // #284: nguồn DMSCarSv gộp biển số thành MỘT chuỗi ngăn bằng dấu phẩy (STUFF … FOR XML PATH).
        // #301: biển số cũng phải qua dự phòng, nếu không lệnh chưa chụp sẽ mất khỏi danh sách này.
        plateNoList = string.Join(",", rows
            .Select(r => Co(r.LicensePlate, r.Vin is not null && carMap.TryGetValue(r.Vin, out var cc) ? cc.PlateNo : null))
            .Where(p => !string.IsNullOrWhiteSpace(p)).Distinct()),
        count = items.Count, items,
    });
}).RequireAuthorization();

app.MapGet("/api/repairorders/statuses", () => Results.Ok(new
{
    flow = _roFlow,
    statuses = roStatusSourceCodes.Select(kv => new { status = kv.Key, sourceCode = kv.Value }),
    stage4Search = roStage4Search.Select(kv => new { group = kv.Key, statuses = kv.Value }),
    completed = roCompletedStatuses
})).RequireAuthorization();

app.MapGet("/api/repairorders", async (AppDbContext db, ITenantContext t, string? status, string? plate, string? stage) =>
{
    var q = db.RepairOrders.Where(r => r.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(r => r.Status == status);
    // Lọc theo NHÓM trạng thái tìm kiếm của nguồn (Wait4Repair/Repairing/Repaired/Finished/Cancel).
    if (!string.IsNullOrWhiteSpace(stage) && roStage4Search.TryGetValue(stage, out var stageStatuses))
        q = q.Where(r => stageStatuses.Contains(r.Status));
    if (!string.IsNullOrWhiteSpace(plate)) q = q.Where(r => r.LicensePlate.Contains(plate.ToUpper()));
    var items = await q.OrderByDescending(r => r.Id).Take(500).Select(r => new
    {
        r.RONo, r.LicensePlate, r.Vin, r.CusName, r.Km, r.CheckInDate, r.PlanedDeliveryDate, r.CusWaiting, r.Status, r.RejectNote,
        r.CusAddress, r.CusTel, r.CusTaxCode, r.ModelID, r.IsReRepair, r.ROType,   // #343 §12
        // #266 §12: 10 cột thẻ hội viên / điểm
        r.FlagCardExist, r.FlagIsDLQuery, r.Creator,   // #283 §12
        r.CardNoInv, r.CardTypeInv, r.CardTypeExpectInv,
        r.PointEndInv, r.PointRankTotalInv, r.PointConsumptionPrm,
        r.MemberNo, r.PointVoucher,
        services = db.RoServiceItems.Count(s => s.OrgId == t.OrgId && s.RoId == r.Id),
        parts = db.RoPartItems.Count(p => p.OrgId == t.OrgId && p.RoId == r.Id),
        total = db.RoServiceItems.Where(s => s.OrgId == t.OrgId && s.RoId == r.Id).Sum(s => (decimal?)s.Amount) ?? 0
              + (db.RoPartItems.Where(p => p.OrgId == t.OrgId && p.RoId == r.Id).Sum(p => (decimal?)(p.NeedQty * p.UnitPrice)) ?? 0)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/repairorders", async (RepairOrderDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.LicensePlate)) return Results.BadRequest(new { error = "Cần biển số (LicensePlate)." });
    var no = "RO" + DateTime.Now.ToString("yyMMddHHmmss");
    // ===== 🔴 #343 SÁU CỘT `Ser_RO` có entity nhưng CHƯA CÓ ĐƯỜNG GHI =====
    // Tìm bằng `_audit/sweep_dead_column.js` (viết ở lượt này, tổng quát hoá cách dò tay của #337/#342).
    //   Sweep đã **TỰ KIỂM**: chạy trên cây trước #337 thì tìm ra đúng hai cột `RoPartItem.ExpenseType`
    //   và `RoServiceItem.ExpenseType` — hai ca trước đây phải dò tay ⇒ sweep bắt được ca đã biết.
    // Đối chiếu nguồn, đếm số chỗ ghi vào **đúng bảng `dt_Ser_RO`**:
    //   `CusAddress` 14 · `CusTel` 14 · `IsReRepair` 14 · `ROType` 10 · `CusTaxCode` 2 · `ModelID` 2
    //
    // ⚠️ `IsReRepair` (**sửa chữa lại**) chính là dữ liệu mà KPI cần cho chỉ tiêu "số lượt sửa chữa lại",
    //   nhưng nguồn **ĐÓNG CỨNG 0** cho chỉ tiêu đó (`, 0 CountSCCLocal_SCL` — xem #335).
    //   ⇒ Cột CÓ dữ liệu mà báo cáo KHÔNG dùng. Port cột theo nguồn; **không** tự tính chỉ tiêu (lệ #299).
    // ⚠️ `ROType` ở **cấp LỆNH** khác `RoServiceItem.ROType` ở **cấp DÒNG**; KPI đếm theo cấp DÒNG (#335).
    //   Hai cột trùng tên, khác cấp — đừng dùng thay cho nhau.
    // 📌 KHÔNG port `FlagIsDLQuery` và `PointVoucher`: grep nguồn ra **0** chỗ ghi vào `Ser_RO`
    //   ⇒ nghi là cột do chính port tự thêm. Để nguyên, không bịa đường ghi.
    var r = new RepairOrder
    {
        OrgId = t.OrgId, RONo = no, LicensePlate = dto.LicensePlate.Trim().ToUpperInvariant(), Vin = dto.Vin, CusName = dto.CusName, Km = dto.Km,
        CheckInDate = dto.CheckInDate ?? DateTime.Now, PlanedDeliveryDate = dto.PlanedDeliveryDate, CusRequest = dto.CusRequest,
        CarStatus = dto.CarStatus, CusWaiting = dto.CusWaiting, Status = "HasRO",
        // 4 cột phục vụ màn Lịch sử dịch vụ (FrmServiceHistory); DealerCode là khoá của luật CanShowDetail
        DealerCode = dto.DealerCode?.Trim().ToUpperInvariant(),
        TrademarkNameModel = dto.TrademarkNameModel, ColorCode = dto.ColorCode, Assistant = dto.Assistant,
        // #266 §12: nhóm thẻ hội viên / điểm.
        //  ⚠️ Nhóm hậu tố `Inv` là SNAPSHOT lúc lập hoá đơn ⇒ CHỈ nhận `MemberNo`/`FlagCardExist` lúc tạo LSC;
        //     các cột `*Inv` và `PointVoucher` do luồng LẬP HOÁ ĐƠN (`FrmInvoice`) chốt — chưa port,
        //     KHÔNG cho client tự đặt (tránh sửa được số liệu đã chốt trên hoá đơn).
        MemberNo = dto.MemberNo,
        ReceptionFNo = string.IsNullOrWhiteSpace(dto.ReceptionFNo) ? null : dto.ReceptionFNo!.Trim().ToUpperInvariant(),   // #310 §12
        // #320 §12: gán 27 cột của bản LIVE.
        AdvisoryCode = dto.AdvisoryCode, AdvisoryPhone = dto.AdvisoryPhone, CarID = dto.CarID,
        CarWashRequested = dto.CarWashRequested, CusTypeID = dto.CusTypeID, DlrPDIReqNo = dto.DlrPDIReqNo,
        EngineerID = dto.EngineerID, FlagOnlyPoint = dto.FlagOnlyPoint, FlagPause = dto.FlagPause,
        IDCardNo = dto.IDCardNo, InsNo = dto.InsNo, InsuranceDeductible = dto.InsuranceDeductible,
        InvoiceBy = dto.InvoiceBy, LevelOfInspection = dto.LevelOfInspection,
        ModifyBy = dto.ModifyBy, ModifyDate = dto.ModifyDate, PayByCard = dto.PayByCard,
        PlanedDuration = dto.PlanedDuration, ReminderMaintanceDate = dto.ReminderMaintanceDate,
        ReminderMaintanceKm = dto.ReminderMaintanceKm, ServiceStatus = dto.ServiceStatus,
        TermsOfRepair = dto.TermsOfRepair, UseSHPart = dto.UseSHPart, WorkDoneSoon = dto.WorkDoneSoon,
        CreatedBy = dto.CreatedBy, LogLUBy = dto.LogLUBy, LogLUDateTime = dto.LogLUDateTime, FlagCardExist = dto.FlagCardExist,
        // #343 §12 — sáu cột trước nay không đường nào ghi.
        CusAddress = dto.CusAddress, CusTel = dto.CusTel, CusTaxCode = dto.CusTaxCode,
        ModelID = dto.ModelID, IsReRepair = dto.IsReRepair, ROType = dto.ROType
    };
    db.RepairOrders.Add(r); await db.SaveChangesAsync();
    foreach (var s in dto.Services ?? new())
    {
        if (string.IsNullOrWhiteSpace(s.SerCode)) continue;
        // Tiền hạng mục DỊCH VỤ theo nguồn: Factor * Price * (1 + VAT*0.01) — KHÔNG có cột Quantity riêng.
        // Client cũ vẫn truyền thẳng Amount; có Price thì tính lại cho đúng công thức nguồn.
        var serviceAmount = s.Price > 0 ? s.Factor * s.Price * (1 + s.Vat / 100m) : s.Amount;
        db.RoServiceItems.Add(new RoServiceItem { OrgId = t.OrgId, RoId = r.Id, SerCode = s.SerCode.Trim(), SerName = s.SerName, Cause = s.Cause, Engineer = s.Engineer, Amount = serviceAmount, ROType = s.ROType, Factor = s.Factor, Price = s.Price, Vat = s.Vat, ActManHour = s.ActManHour, ExpenseType = s.ExpenseType, InsurancePrice = s.InsurancePrice, CamID = s.CamID });
    }
    foreach (var p in dto.Parts ?? new())
    {
        if (string.IsNullOrWhiteSpace(p.PartCode)) continue;
        // Tiền dòng PHỤ TÙNG theo nguồn: Factor * Quantity * Price * (1 + VAT*0.01).
        var partQty = p.NeedQty <= 0 ? 1 : p.NeedQty;
        var partAmount = p.Factor * partQty * p.UnitPrice * (1 + p.Vat / 100m);
        db.RoPartItems.Add(new RoPartItem { OrgId = t.OrgId, RoId = r.Id, PartCode = p.PartCode.Trim(), PartName = p.PartName, Unit = p.Unit, NeedQty = partQty, UnitPrice = p.UnitPrice, Factor = p.Factor, Vat = p.Vat, Amount = partAmount, Note = p.Note, ExpenseType = p.ExpenseType, FlagAccessory = p.FlagAccessory ?? "0", InsurancePrice = p.InsurancePrice, CamID = p.CamID });
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { r.RONo, r.LicensePlate, status = r.Status });
}).RequireAuthorization();

// Bảng theo dõi tiến độ RO (Ser_RO_Stage — port 1:1 FrmTrackingProcess): kanban theo trạng thái
app.MapGet("/api/repairorders/board", async (AppDbContext db, ITenantContext t) =>
{
    var flow = new[] { "HasRO", "InGarage", "Repaired", "CheckEnd", "Paid", "Finished" };
    var ros = await db.RepairOrders.Where(r => r.OrgId == t.OrgId).OrderByDescending(r => r.Id).Take(1000)
        .Select(r => new { r.RONo, r.LicensePlate, r.CusName, r.Km, r.PlanedDeliveryDate, r.CusWaiting, r.Status }).ToListAsync();
    var columns = flow.Select(st => new
    {
        status = st,
        count = ros.Count(r => r.Status == st),
        items = ros.Where(r => r.Status == st).Select(r => new { r.RONo, r.LicensePlate, r.CusName, r.Km, r.PlanedDeliveryDate, r.CusWaiting }).ToList()
    }).ToList();
    return Results.Ok(new { total = ros.Count, columns });
}).RequireAuthorization();

app.MapGet("/api/repairorders/{no}", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var r = await db.RepairOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == no);
    if (r is null) return Results.NotFound(new { no });
    var services = await db.RoServiceItems.Where(s => s.OrgId == t.OrgId && s.RoId == r.Id)
        .Select(s => new { s.SerCode, s.SerName, s.Cause, s.Result, s.Engineer, s.ROType, s.Factor, s.Price, s.Vat, s.ActManHour, s.Amount, s.ExpenseType, s.InsurancePrice, s.CamID }).ToListAsync();   // #280 §12 + #342 + #367
    var parts = await db.RoPartItems.Where(p => p.OrgId == t.OrgId && p.RoId == r.Id)
        .Select(p => new { p.PartCode, p.PartName, p.Unit, p.NeedQty, p.UnitPrice, p.Factor, p.Vat, lineTotal = p.Amount, p.Note, p.CamID }).ToListAsync();
    return Results.Ok(new
    {
        r.RONo, r.LicensePlate, r.Vin, r.CusName, r.Km, r.CheckInDate, r.PlanedDeliveryDate, r.CusRequest, r.CarStatus, r.CusWaiting, r.Status,
        services, parts,
        total = services.Sum(s => s.Amount) + parts.Sum(p => p.lineTotal)
    });
}).RequireAuthorization();

// Gán kỹ thuật viên cho 1 dòng công việc trong RO (port 1:1 FrmSerItemEngineerList — picker 2 lưới chuyển qua lại,
// TCMotor DMSCarSv/Services): lưu danh sách KTV đã chọn thành chuỗi "no1,no2,..." vào RoServiceItem.Engineer.
app.MapPost("/api/repairorders/{no}/services/{serCode}/engineers", async (string no, string serCode, RoEngineersDto dto, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var r = await db.RepairOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == no);
    if (r is null) return Results.NotFound(new { no });
    var item = await db.RoServiceItems.FirstOrDefaultAsync(s => s.OrgId == t.OrgId && s.RoId == r.Id && s.SerCode == serCode);
    if (item is null) return Results.NotFound(new { serCode });
    var codes = (dto.EngineerNos ?? new List<string>()).Select(x => x.Trim()).Where(x => x.Length > 0).Distinct().ToList();
    item.Engineer = codes.Count == 0 ? null : string.Join(",", codes);
    await db.SaveChangesAsync();
    return Results.Ok(new { no, serCode, engineers = codes });
}).RequireAuthorization();

// ===== 🔴 #460 MÀN BẢO HÀNH CỦA BÁO GIÁ — `Ser_RO_GetWarranty_V2_New20230417` =====
// TRACE 4 TẦNG: `Views/Services/FrmQuotation.cs` → `SerROService.Ser_RO_GetWarranty_V2` (`:235`)
//   → WS `Ser_RO_GetWarranty_V2` → biz **`Ser_RO_GetWarranty_V2_New20230417`** (`Service01.cs:3216`).
//   ⚠️ Cùng file còn `Ser_RO_GetWarranty_V2` (`:2735`) và `Ser_RO_GetWarranty` (`:2378`).
//     WS chỉ gọi `_New20230417` và bản trần `Ser_RO_GetWarranty` ⇒ **bản `_V2` không hậu tố là CHẾT**.
//
// 🔴 DIFF HAI NHÁNH SQL TRƯỚC (luật #414): hai hàm dài **455 dòng bằng nhau**, khác biệt **NẰM TRỌN TRONG
//   DANH SÁCH CỘT**, WHERE y hệt. Bản 2023-04-17 đổi nguồn dữ liệu khách–xe:
//     cũ : `cus.CusID` · `cus.CusName` · `car.PlateNo` · `car.Frameno` · `car.WarrantyExpiresDate` …
//     mới: `ro.CusID` · `ro.CusName` · `ro.PlateNo` · `ro.Frameno` · `ro.WarrantyExpiresDate` …
//   ⇒ **ẢNH CHỤP tại thời điểm sửa chữa**, không phải dữ liệu danh mục HIỆN TẠI. Đổi tên khách hay
//     sang tên xe **không còn viết lại lịch sử** đề nghị bảo hành. Đây là ý nghĩa thật của bản mới.
//   ⚠️ Nhưng **HAI cột vẫn lấy từ danh mục**: `car.ProductYear` và `car.CusConfirmedWarrantyDate`
//     ⇒ nguồn dữ liệu **TRỘN**. Không phải quên — nhưng cũng không nhất quán; ghi cờ `mixedSnapshotAndMaster`.
//   ⚠️ Bản CŨ có `case when not ro.CusName is null then **cus.Tel**` — nhánh nói "lấy theo RO" nhưng lại đọc
//     cột của `cus`; lỗi đó **chết theo bản cũ**, ghi lại để không ai port ngược.
//
// 🔴 HAI `inner join` NỐI HAI CỘT (luật #410 — mất dòng lúc ĐỌC):
//     `inner join ser_Customer on ro.CusID=cus.CusID **and** ro.DealerCode=cus.DealerCode`
//     `inner join ser_car      on ro.CarID=car.CarID **and** ro.cusid=car.cusid`
//   ⇒ xe đã **sang tên** thì vế thứ hai gãy ⇒ **cả màn bảo hành trả VỀ RỖNG**, không báo lỗi gì.
//   Trả cờ `headerDroppedByMasterJoin` khi rơi vào đúng tình huống đó, thay vì im lặng.
// ⚪ `left join Ser_ROWarrantyReport` nối `ROID` + `DealerCode`, WHERE không đụng tới ⇒ **LEFT còn SỐNG**
//   (lệnh chưa có đề nghị bảo hành vẫn ra header). Kiểm tra âm tính, ghi để khỏi soi lại.
// 🔴 **HAI khối `union all` bị COMMENT** ở cả hai bản: chúng lấy dòng dịch vụ / phụ tùng **chỉ có trên đề
//   nghị bảo hành mà KHÔNG có trên lệnh sửa chữa** (`rs.ROID is null` / `rp.ROID is null`), gắn `FlagAdd=1`.
//   Port dòng ACTIVE ⇒ **dòng phát sinh thêm ở đề nghị bảo hành KHÔNG hiện**; mọi dòng đều `FlagAdd = "0"`.
//   Cờ `warrantyOnlyLinesHiddenByCommentedUnion` — đây là dữ liệu bị giấu, không phải dữ liệu không có.
// ⚠️ Thứ tự dịch vụ theo `odrby`: `CVC`→1, `CVPSN`→2, còn lại→100 (ORDER BY nằm ở câu SELECT cuối, hợp lệ).
// ⚠️ Bảng dịch nhãn trạng thái bảo hành có **6 mã, KHÔNG có ELSE** ⇒ mã lạ cho ra nhãn **NULL**, không phải "".
app.MapGet("/api/repairorders/{no}/warranty", async (string no, AppDbContext db, ITenantContext t) =>
{
    no = no.Trim().ToUpperInvariant();
    var r = await db.RepairOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == no);
    if (r is null) return Results.NotFound(new { no });

    // Hai INNER join hai-cột của nguồn — kiểm ĐÚNG hình dạng đó rồi mới dựng header.
    var cus = await db.ServiceCustomers.FirstOrDefaultAsync(x => x.OrgId == t.OrgId
        && x.CusCode == r.CusID && x.DealerCode == r.DealerCode);
    var car = await db.ServiceCars.FirstOrDefaultAsync(x => x.OrgId == t.OrgId
        && x.CarID == r.CarID && x.CusID == r.CusID);
    if (cus is null || car is null)
        return Results.Ok(new
        {
            no, header = (object?)null, services = Array.Empty<object>(), parts = Array.Empty<object>(),
            headerDroppedByMasterJoin = true,
            reason = cus is null
                ? "Khách của lệnh không khớp (CusID, DealerCode) trong Ser_Customer."
                : "Xe của lệnh không khớp (CarID, CusID) trong Ser_Car — thường do xe đã sang tên.",
        });

    var claim = await db.ServiceWarrantyClaims
        .FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.RONo == r.RONo && x.DealerCode == r.DealerCode);

    // 6 mã, KHÔNG có ELSE ⇒ mã lạ ra null.
    var warrantyStatusText = claim?.Status switch
    {
        "SENT" => "Chờ xem xét",
        "PEND" => "Chưa gửi",
        "CONF" => "Chờ duyệt",
        "ACCE" => "Chấp thuận B.H",
        "REJ" => "Không duyệt",
        "REVERT" => "HTC Hoàn trả",
        _ => (string?)null,
    };

    var header = new
    {
        r.RONo,
        // isnull(rowr.X, ro.X) — ưu tiên giá trị trên ĐỀ NGHỊ BẢO HÀNH, thiếu thì lấy của lệnh.
        CusRequest = claim?.CusRequest ?? r.CusRequest,
        CarStatus = claim?.CarStatus ?? r.CarStatus,
        r.CheckInDate, r.Assistant,
        StartDate = claim?.StartDate ?? r.StartDate,
        FinishedDate = claim?.FinishedDate ?? r.FinishedDate,
        r.Km, r.Status,
        // ẢNH CHỤP trên lệnh (đổi của bản 2023-04-17)
        r.CusID,
        OwnerName = r.CusName,
        // isnull(ro.CusName, isnull(cus.ContName, cus.CusName)) — ba mức, không phải hai.
        CusName = r.CusName ?? cus.ContName ?? cus.CusName,
        r.CusAddress, r.CusTel, r.CusMobile,
        TaxCode = r.CusTaxCode,
        WarrantyRegistrationDate = r.WarrantyRegistrationDate.HasValue
            ? r.WarrantyRegistrationDate.Value.ToString("yyyy-MM-dd") : null,
        r.CarID, PlateNo = r.LicensePlate, r.TradeMarkCode, r.ColorCode,
        FrameNo = r.Vin, r.EngineNo, r.BatteryNo, r.SerialNo,
        // HAI cột duy nhất vẫn lấy từ DANH MỤC xe (nguồn trộn hai lối)
        car.ProductYear, car.CusConfirmedWarrantyDate,
        r.WarrantyExpiresDate,
        WRROID = claim?.ROID, ROWID = claim?.Id, claim?.ROWNo,
        claim?.NaturalCode, claim?.CauseCode,
        WarrantyStatus = claim?.Status, warrantyStatusText,
        claim?.ErrorCodeCD, claim?.ErrorCodePN, claim?.ROWTID,
        claim?.ROWTypeCode, claim?.ROWTypeDtlCode,
        claim?.FlagReadySend, claim?.PartIDError,
    };

    // Dòng dịch vụ: sắp theo odrby CVC=1 · CVPSN=2 · còn lại=100.
    static int OdrBy(string? rowSerType) => rowSerType switch { "CVC" => 1, "CVPSN" => 2, _ => 100 };
    var svcRows = await db.RoServiceItems.Where(x => x.OrgId == t.OrgId && x.RoId == r.Id).ToListAsync();
    var services = svcRows.Select(x => new
    {
        x.SerCode, x.SerName, x.ActManHour, x.Factor, x.Price, x.Vat,
        Amount = x.Factor * x.Price * (1 + x.Vat / 100),
        x.ExpenseType, x.InsurancePrice,
        WarrantyStatus = claim?.Status ?? "PEND",   // Isnull(rsw.WarrantyStatus, PEND)
        odrby = OdrBy(x.ROType),
        FlagAdd = "0",   // union bổ sung FlagAdd=1 đã bị COMMENT ở nguồn
    }).OrderBy(x => x.odrby).ToList();

    var partRows = await db.RoPartItems.Where(x => x.OrgId == t.OrgId && x.RoId == r.Id).ToListAsync();

    return Results.Ok(new
    {
        no, header, services, partCount = partRows.Count,
        mixedSnapshotAndMaster = true,
        warrantyOnlyLinesHiddenByCommentedUnion = true,
        headerDroppedByMasterJoin = false,
        deadTwinNote = "Ser_RO_GetWarranty_V2 (Service01.cs:2735) KHÔNG có WebMethod nào gọi — bản sống là _New20230417.",
    });
}).RequireAuthorization();

// ===== 🔴 #469 BÁO CÁO TỔNG XUẤT KHO — `Ser_InvReportTotalStockOutRpt_New20230623` =====
// Nguồn: `BizCarSv.Inventory.Report.cs:1609` (WS gọi bản này; bản kho `…_WH` ở `WH.cs:10495`).
// Chọn màn này từ danh sách lệch của #468 (**15 dòng SQL → 5**) — chênh lớn nhất theo tỉ lệ.
//
// 🔴 **BẢN KHO THIẾU HẲN MỘT NỬA NGHIỆP VỤ**: bản chính `union all` hai nguồn —
//   (1) phiếu xuất kho `Ser_Inv_StockOut` + chi tiết, và
//   (2) **phiếu xuất trả nhà cung cấp** `Ser_SupplierPayment(Dtl)`, nhãn `N"Xuất trả nhà cung cấp"`.
//   Bản `_WH` **chỉ có (1)** ⇒ cùng một khoảng ngày, xem theo kho sẽ **thiếu toàn bộ hàng trả NCC**.
//   Đây là dạng lệch mà #468 dự đoán: nhánh kho **tụt hậu**, không phải thiết kế khác.
//
// 🔴 **HAI CỬA SỔ NGÀY KHÁC NHAU TRONG CÙNG MỘT TRUY VẤN** (luật #415, nhưng bất đối xứng):
//   · Nửa NCC dùng `@strDateFrom`/`@strDateTo` = ngày kèm `00:00:00` / `23:59:59` ⇒ **đủ ngày cuối**.
//   · Nửa xuất kho dùng `@FromDate`/`@ToDate` = **chuỗi THÔ người gọi truyền** ⇒ nếu chỉ có `yyyy-MM-dd` thì
//     `so.StockOutTime <= "2026-09-08"` hiểu là **nửa đêm** ⇒ **mất trọn ngày cuối** cho phiếu xuất kho,
//     trong khi nửa NCC vẫn lấy đủ. Hai nửa của CÙNG báo cáo lệch nhau một ngày.
//   ⇒ Port dùng mốc `23:59:59` cho **cả hai** nửa và trả cờ `endDateExclusiveInSourceForStockOut`
//     kèm số dòng chênh, để chỗ sửa là **cố ý và đo được**.
// 🔴 **GUARD CHẾT**: WHERE có `and so.status = 3` rồi lại `and so.Status not in ("4","5")` —
//   điều kiện sau **không bao giờ loại thêm dòng nào**. Giữ nguyên hành vi, ghi cờ `redundantStatusGuard`.
// ⚠️ `StockOutType` CASE chỉ có 1 → "Xuất dịch vụ", 2 → "Xuất thường", **không có ELSE** ⇒ loại khác cho
//   nhãn **NULL** nhưng **dòng vẫn được tính vào tổng**.
// ⚠️ Nửa NCC lọc `SupplierPaymentStatus = "A"` (đã duyệt) và mốc theo `ApprDTime`, KHÔNG theo ngày lập.
// ⚠️ Toàn bộ tham số **bake bằng `StringUtils.Replace` vào chuỗi có nháy** (`"@FromDate"`), không phải
//   SqlParameter ⇒ bề mặt tiêm SQL. Port dùng tham số thật (lệch CỐ Ý, an toàn hơn).
// ⚠️ `union all` nối hai kiểu khác nhau: nửa đầu `so.StockOutTime` (datetime), nửa sau
//   `Convert(varchar, CONVERT(date, ApprDTime))` ⇒ kiểu cột do **nửa đầu** quyết định.
app.MapGet("/api/reports/total-stockout", async (AppDbContext db, ITenantContext t,
    DateTime? fromDate, DateTime? toDate, string? dealerCode) =>
{
    if (fromDate is null || toDate is null)
        return Results.BadRequest(new { error = "Cần fromDate và toDate." });
    var from = fromDate.Value.Date;
    var to = toDate.Value.Date.AddDays(1).AddSeconds(-1);            // 23:59:59 — đúng nửa NCC của nguồn
    var toRawMidnight = toDate.Value.Date;                            // mốc THÔ mà nửa xuất kho của nguồn dùng

    var soQ = db.ServiceStockOuts.Where(x => x.OrgId == t.OrgId
        && x.Status == "3"                                            // nguồn: so.status = 3
        && x.StockOutDate >= from && x.StockOutDate <= to);
    var soRows = await soQ.ToListAsync();
    // Đếm đúng số dòng mà nguồn ĐÁNH RƠI vì mốc thô (không phải ước lượng).
    var lostByRawEndDate = soRows.Count(x => x.StockOutDate > toRawMidnight);

    var soIds = soRows.Select(x => x.Id).ToList();
    var soLines = await db.ServiceStockOutLines
        .Where(l => l.OrgId == t.OrgId && soIds.Contains(l.ServiceStockOutId)).ToListAsync();
    var lineByHead = soLines.GroupBy(l => l.ServiceStockOutId)
        .ToDictionary(g => g.Key, g => g.Sum(l => l.Quantity * l.Price + l.Quantity * l.Price * 0.01m * (l.Vat)));

    static string? TypeLabel(string? code) => code switch
    {
        "1" => "Xuất dịch vụ",
        "2" => "Xuất thường",
        _ => null,          // nguồn KHÔNG có ELSE ⇒ nhãn null, dòng vẫn tính
    };

    var partA = soRows.Select(x => new
    {
        StockOutTime = x.StockOutDate,
        x.StockOutNo,
        Note = (string?)null,
        StockOutType = TypeLabel(x.StockOutType),
        Amount = lineByHead.TryGetValue(x.Id, out var a) ? a : 0m,
        Source = "StockOut",
    }).ToList();

    // Nửa thứ hai — phiếu xuất trả nhà cung cấp (bản _WH THIẾU hẳn khối này).
    var payQ = db.SupplierPayments.Where(x => x.OrgId == t.OrgId
        && x.Status == "A"                                            // SupplierPaymentStatus = A
        && x.ApprovedAt >= from && x.ApprovedAt <= to);
    if (!string.IsNullOrWhiteSpace(dealerCode))
    {
        payQ = payQ.Where(x => x.DealerCode == dealerCode);
    }
    var pays = await payQ.ToListAsync();
    var payNos = pays.Select(x => x.PaymentNo).ToList();
    var payLines = await db.SupplierPaymentLines
        .Where(l => l.OrgId == t.OrgId && payNos.Contains(l.PaymentNo)).ToListAsync();
    var partB = pays.Select(p => new
    {
        StockOutTime = p.ApprovedAt,
        StockOutNo = p.PaymentNo,
        Note = p.Description,
        StockOutType = (string?)"Xuất trả nhà cung cấp",
        Amount = payLines.Where(l => l.PaymentNo == p.PaymentNo)
            .Sum(l => l.QtyPay * l.Price + l.QtyPay * l.Price * 0.01m * l.Vat),
        Source = "SupplierPayment",
    }).ToList();

    var items = partA.Concat(partB).OrderBy(x => x.StockOutTime).ThenBy(x => x.StockOutNo).ToList();
    return Results.Ok(new
    {
        from = from.ToString("yyyy-MM-dd HH:mm:ss"), to = to.ToString("yyyy-MM-dd HH:mm:ss"),
        count = items.Count, items,
        stockOutCount = partA.Count, supplierPaymentCount = partB.Count,
        total = items.Sum(x => x.Amount),
        endDateExclusiveInSourceForStockOut = true,
        lostByRawEndDate,
        redundantStatusGuard = true,
        typeLabelHasNoElse = true,
        bakedParamsInSource = true,
        whVariantMissesSupplierPaymentHalf = true,
    });
}).RequireAuthorization();

// ===== 🔴 #472 BÁO CÁO TỒN KHO (bản KHO) — `Ser_InvReportBalanceRpt_WH_New20221011` =====
// 🔴🔴 #475 RÚT KẾT LUẬN "BẢN KHO LÀM THÊM" CỦA #472/#473 — **TÔI SO NHẦM VĂN BẢN VỚI NGỮ NGHĨA**.
//   #472/#473 nói bản kho là "TẬP CHA", làm thêm `#tbl_sd`/`#tbl_sdo`/`#tbl_Open`. **SAI.**
//   Bản chính **CŨNG dựng đúng ba bảng đó**, nhưng bằng **MACRO thay chuỗi lúc chạy**:
//     `StringUtils.Replace(sql, "zzB_tbl_ser_inv_partInstance_StockIn_zzE",`
//       `SqlTemplate_ser_inv_partInstance_New20191112.zzB_…_StockIn_zzE(strDealerCode, strPartCodeList,`
//       `strFromDate, strToDateNext, "#tbl_sd"), …)` — trong thân hàm chỉ thấy **một dòng giữ chỗ**.
//   ⇒ Công cụ `diffwh.js` chỉ đọc **chữ SQL viết thẳng** nên khối macro **vô hình với phép đo**;
//     bản kho viết inline thì đếm ra nhiều dòng hơn. Khác biệt là **inline vs macro**, KHÔNG phải
//     "bản kho làm thêm nghiệp vụ". Cây nguồn dùng macro dày đặc: **78 chỗ** ở `Inventory.Report.cs`,
//     **71 chỗ** ở `WH.cs` ⇒ mọi con số "lệch dòng SQL" ở #468/#471 **đều phải đọc kèm cảnh báo này**.
//   📌 Bài học (họ lỗi ĐO, lần thứ TÁM): **đếm dòng SQL không đo được SQL sinh bởi macro**. Trước khi
//     nói "thiếu khối", phải grep `zzB_`/`_zzE` trong CẢ HAI thân hàm và khai triển macro rồi mới so.
// ⚪ Phần logic bên dưới **vẫn đúng và vẫn giữ**: nó port đúng nội dung ba bảng tạm đó (nhập luỹ kế,
//   xuất luỹ kế, tồn đầu) — chỉ có câu "bản kho làm thêm" là bị rút.
//
// 🔴 **PHƯƠNG PHÁP GIÁ VỐN LÀ THAM SỐ CỦA ĐẠI LÝ, VÀ NHÁNH CÒN LẠI ĐÃ CHẾT**:
//   `case when (select ParamValue from Mst_Param where DealerCode=@ and ParamCode="MCC" and ParamType="MCC")`
//   `= "FIFO" then <tổng theo giá nhập> Else "0" -- sum(GetAverageCost(...))`
//   ⇒ Đại lý **không** đặt `MCC = "FIFO"` thì **giá trị tồn trả về 0**, còn SỐ LƯỢNG vẫn đúng.
//     Nhánh bình quân gia quyền (`GetAverageCost`) **đã bị comment** ⇒ không có đường nào khác.
//     Đây là "0 im lặng": báo cáo vẫn ra, cột tiền bằng 0, không cảnh báo gì. Cờ `costMethodNotFifoGivesZero`.
//   ⚠️ `Else "0"` là **chuỗi** đặt cạnh biểu thức số trong cùng `CASE` ⇒ SQL ép kiểu; giữ nguyên ý nghĩa 0.
// ⚠️ Tồn = (nhập có `DateIn <= @ToDate`) − (xuất có `DateOut <= @ToDate`), loại `Status not in ("4","5")`.
//   Mốc dùng `@ToDate` **không kèm giờ** ⇒ lại là nửa đêm (luật #415). Nguồn CÓ dựng biến
//   `strToDateTime = strToDate + " 23:59:59"` nhưng **không dùng cho hai vế này** ⇒ biến gần như thừa.
//   Port dùng mốc 23:59:59 và đếm `lostByRawEndDate`.
// ⚠️ `strFromDate = "1900-01-01"` đóng cứng trong nguồn — không phải tham số người dùng.
// ⚪ `left join Ser_Inv_StockInDetail` nối BA cột (PartID + StockInID + LocationID), WHERE không đụng tới
//   ⇒ **LEFT còn sống**; thiếu dòng nhập chi tiết thì rơi về `spi.SIPrice`. Kiểm tra âm tính.
app.MapGet("/api/reports/inventory-balance", async (AppDbContext db, ITenantContext t,
    DateTime? toDate, string? dealerCode) =>
{
    if (toDate is null) return Results.BadRequest(new { error = "Cần toDate." });
    if (string.IsNullOrWhiteSpace(dealerCode)) return Results.BadRequest(new { error = "Cần dealerCode (nguồn lọc theo đại lý)." });
    var dealer = dealerCode!.Trim();
    var toRawMidnight = toDate.Value.Date;
    var to = toDate.Value.Date.AddDays(1).AddSeconds(-1);

    // Phương pháp giá vốn của ĐẠI LÝ (Mst_Param: MCC/MCC).
    var mcc = await db.MstParams.Where(p => p.OrgId == t.OrgId && p.DealerCode == dealer
            && p.ParamCode == "MCC" && p.ParamType == "MCC")
        .Select(p => p.ParamValue).FirstOrDefaultAsync();
    var isFifo = string.Equals(mcc, "FIFO", StringComparison.OrdinalIgnoreCase);

    var inst = await db.PartInstances.Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer
            && x.Status != "4" && x.Status != "5").ToListAsync();
    var lines = await db.PartStockInLines.Where(l => l.OrgId == t.OrgId).ToListAsync();
    // Khoá nối BA cột của nguồn (ở MiniHTC: StockInId + PartCode + Location).
    var lineByKey = lines.Where(l => l.PartCode != null)
        .GroupBy(l => l.StockInId + "|" + l.PartCode + "|" + (l.Location ?? ""))
        .ToDictionary(g => g.Key, g => g.First());
    decimal UnitPrice(PartInstance x)
    {
        var k = x.StockInId + "|" + (x.PartCode ?? "") + "|" + (x.LocationID ?? "");
        if (lineByKey.TryGetValue(k, out var l)) return l.Price;
        return x.SIPrice ?? 0m;
    }
    decimal Value(PartInstance x)
    {
        if (!isFifo) return 0m;                     // nhánh Else "0" của nguồn
        var p = UnitPrice(x);
        return p * x.Quantity + (x.SIVAT ?? 0m) * 0.01m * p * x.Quantity;
    }

    var inRows = inst.Where(x => x.DateIn != null && x.DateIn <= to).ToList();
    var outRows = inst.Where(x => x.DateOut != null && x.DateOut <= to).ToList();
    var lostByRawEndDate = inRows.Count(x => x.DateIn > toRawMidnight)
                         + outRows.Count(x => x.DateOut > toRawMidnight);

    var sd = inRows.GroupBy(x => new { x.PartID, x.LocationID })
        .ToDictionary(g => (g.Key.PartID ?? "") + "|" + (g.Key.LocationID ?? ""),
                      g => new { SD = g.Sum(x => x.Quantity), TD = g.Sum(Value) });
    var sdo = outRows.GroupBy(x => new { x.PartID, x.LocationID })
        .ToDictionary(g => (g.Key.PartID ?? "") + "|" + (g.Key.LocationID ?? ""),
                      g => new { SX = g.Sum(x => x.Quantity), TX = g.Sum(Value) });

    // #tbl_Open = LEFT join sd -> sdo (dòng chỉ có ở xuất KHÔNG xuất hiện — đúng nguồn).
    var items = sd.Select(kv => new
    {
        PartID = kv.Key.Split((char)124)[0],
        LocationID = kv.Key.Split((char)124)[1],
        SLC = kv.Value.SD - (sdo.TryGetValue(kv.Key, out var o) ? o.SX : 0m),
        TGC = kv.Value.TD - (sdo.TryGetValue(kv.Key, out var o2) ? o2.TX : 0m),
    }).OrderBy(x => x.PartID).ThenBy(x => x.LocationID).ToList();

    return Results.Ok(new
    {
        dealerCode = dealer,
        toDate = to.ToString("yyyy-MM-dd HH:mm:ss"),
        fromDateHardcodedInSource = "1900-01-01",
        costMethod = mcc, isFifo,
        costMethodNotFifoGivesZero = !isFifo,
        averageCostBranchCommentedOut = true,
        endDateExclusiveInSource = true, lostByRawEndDate,
        outOnlyRowsDroppedByLeftJoin = sdo.Keys.Count(k => !sd.ContainsKey(k)),
        count = items.Count, items,
    });
}).RequireAuthorization();

// ===== 🔴 #473 TỒN KHO THEO VỊ TRÍ — `Ser_InvReportBalanceRpt_SumLocation` (Main) vs `…_WH` =====
// ⚠️ #475 ĐÍNH CHÍNH: câu "bản kho là TẬP CHA" **đã bị rút** — bản chính dựng cùng ba bảng tạm qua
//   **macro `zzB_…_zzE`**, chỉ là không viết thẳng nên phép đếm dòng không thấy. Xem ghi chú ở #472/#475.
// Cặp thứ hai của họ báo cáo tồn kho (đếm được 23 → 45 dòng SQL **viết thẳng**).
// Phần bản kho làm THÊM **giống hệt #472**: `#tbl_sd` / `#tbl_sdo` / `#tbl_Open` dựng từ
//   `Ser_Inv_PartInstance` + `Ser_Inv_StockInDetail`, giá vốn rẽ theo `Mst_Param(MCC)` và `Else "0"`.
//   ⇒ Cùng một cặp anh em ⇒ **cùng một luật**, không phải trùng hợp. Dùng lại đúng cách tính của #472.
//
// 🔴 **CHỈ BẢN MAIN KẸP MỐC NGÀY** (đúng hình dạng #421/#422, nay gặp ở báo cáo thứ hai):
//   `if (StringCompareIgnoreCase(strToDate, TConst.HTCConst.HTC_WareHouse) < 1) strToDate = …`
//   với `HTC_WareHouse = "2017-12-31"` (`Const.Main.cs:138` — tên đọc như MÃ KHO nhưng là một **NGÀY**).
//   ⇒ Xin mốc **≤ 31-12-2017** thì bản Main **âm thầm kéo về 31-12-2017**; bản `_WH` **không kẹp**.
//   Giữ `scope=main|wh` như #422 và luôn trả `effectiveDate` để mốc thật nhìn thấy được.
// ⚪ KIỂM TRA ÂM TÍNH (#415): `select top 1 f.StockInDate … order by f.StockInDate desc` — TOP 1 **CÓ**
//   ORDER BY ⇒ xác định, lấy lần nhập **gần nhất**. Không phải bẫy "TOP không ORDER BY".
// 🔴 **TUỔI TỒN TÍNH TỚI HÔM NAY, KHÔNG TỚI MỐC BÁO CÁO**:
//   `DATEDIFF(day, g.StockInDate, GETDATE()) AgeOfExist` — dùng `GETDATE()` chứ không dùng `@ToDate`.
//   ⇒ Xem lại báo cáo của một mốc quá khứ thì cột "tuổi tồn" vẫn **đếm tới ngày chạy**; in hai lần cách
//     nhau một tuần ra hai con số khác nhau cho cùng một mốc. Đây là lỗi "báo cáo theo KỲ" (#412).
//     Port trả **cả hai**: `ageOfExist` (giữ đúng nguồn) và `ageAtReportDate` (tính tới mốc) + cờ.
app.MapGet("/api/reports/inventory-balance-by-location", async (AppDbContext db, ITenantContext t,
    DateTime? toDate, string? dealerCode, string? scope) =>
{
    if (toDate is null) return Results.BadRequest(new { error = "Cần toDate." });
    if (string.IsNullOrWhiteSpace(dealerCode)) return Results.BadRequest(new { error = "Cần dealerCode." });
    var dealer = dealerCode!.Trim();
    var isWh = string.Equals(scope?.Trim(), "wh", StringComparison.OrdinalIgnoreCase);

    // Mốc kẹp CHỈ ở bản Main (hằng HTC_WareHouse = "2017-12-31").
    var floor = new DateTime(2017, 12, 31);
    var asked = toDate.Value.Date;
    var clamped = !isWh && asked <= floor;
    var effective = clamped ? floor : asked;
    var to = effective.AddDays(1).AddSeconds(-1);

    var mcc = await db.MstParams.Where(p => p.OrgId == t.OrgId && p.DealerCode == dealer
            && p.ParamCode == "MCC" && p.ParamType == "MCC")
        .Select(p => p.ParamValue).FirstOrDefaultAsync();
    var isFifo = string.Equals(mcc, "FIFO", StringComparison.OrdinalIgnoreCase);

    var inst = await db.PartInstances.Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer
            && x.Status != "4" && x.Status != "5").ToListAsync();
    var lines = await db.PartStockInLines.Where(l => l.OrgId == t.OrgId).ToListAsync();
    var lineByKey = lines.Where(l => l.PartCode != null)
        .GroupBy(l => l.StockInId + "|" + l.PartCode + "|" + (l.Location ?? ""))
        .ToDictionary(g => g.Key, g => g.First());
    decimal Val(PartInstance x)
    {
        if (!isFifo) return 0m;
        var k = x.StockInId + "|" + (x.PartCode ?? "") + "|" + (x.LocationID ?? "");
        var p = lineByKey.TryGetValue(k, out var l) ? l.Price : (x.SIPrice ?? 0m);
        return p * x.Quantity + (x.SIVAT ?? 0m) * 0.01m * p * x.Quantity;
    }

    var inRows = inst.Where(x => x.DateIn != null && x.DateIn <= to).ToList();
    var outRows = inst.Where(x => x.DateOut != null && x.DateOut <= to).ToList();
    string Key(string? p, string? loc) => (p ?? "") + "|" + (loc ?? "");
    var sd = inRows.GroupBy(x => Key(x.PartID, x.LocationID))
        .ToDictionary(g => g.Key, g => new { SD = g.Sum(x => x.Quantity), TD = g.Sum(Val) });
    var sdo = outRows.GroupBy(x => Key(x.PartID, x.LocationID))
        .ToDictionary(g => g.Key, g => new { SX = g.Sum(x => x.Quantity), TX = g.Sum(Val) });

    // Lần nhập GẦN NHẤT của từng phụ tùng (top 1 ... order by StockInDate desc).
    var lastIn = inRows.Where(x => x.PartID != null)
        .GroupBy(x => x.PartID!)
        .ToDictionary(g => g.Key, g => g.Max(x => x.DateIn));

    var parts = await db.ServiceParts.Where(p => p.OrgId == t.OrgId)
        .Select(p => new { p.PartID, p.PartCode, p.PartName, p.Unit, p.Model }).ToListAsync();
    var partById = parts.Where(p => p.PartID != null)
        .GroupBy(p => p.PartID!).ToDictionary(g => g.Key, g => g.First());

    var now = DateTime.Now.Date;
    var items = sd.Select(kv =>
    {
        var partId = kv.Key.Split((char)124)[0];
        var loc = kv.Key.Split((char)124)[1];
        var din = lastIn.TryGetValue(partId, out var d) ? d : null;
        return new
        {
            PartID = partId,
            PartCode = partById.TryGetValue(partId, out var p) ? p.PartCode : null,
            VieName = partById.TryGetValue(partId, out var p2) ? p2.PartName : null,
            Unit = partById.TryGetValue(partId, out var p3) ? p3.Unit : null,
            Model = partById.TryGetValue(partId, out var p4) ? p4.Model : null,
            Location = loc,
            SLC = kv.Value.SD - (sdo.TryGetValue(kv.Key, out var o) ? o.SX : 0m),
            TGC = kv.Value.TD - (sdo.TryGetValue(kv.Key, out var o2) ? o2.TX : 0m),
            StockInDate = din,
            // đúng nguồn: đếm tới HÔM NAY
            AgeOfExist = din.HasValue ? (int)(now - din.Value.Date).TotalDays : (int?)null,
            // bổ sung: đếm tới MỐC báo cáo (nguồn không có)
            AgeAtReportDate = din.HasValue ? (int)(effective - din.Value.Date).TotalDays : (int?)null,
        };
    }).OrderBy(x => x.PartCode).ThenBy(x => x.Location).ToList();

    return Results.Ok(new
    {
        dealerCode = dealer, scope = isWh ? "wh" : "main",
        askedDate = asked.ToString("yyyy-MM-dd"),
        effectiveDate = effective.ToString("yyyy-MM-dd"),
        clampedToFloor = clamped, floorDate = "2017-12-31",
        costMethod = mcc, isFifo, costMethodNotFifoGivesZero = !isFifo,
        ageCountedToTodayNotReportDate = true,
        topOneHasOrderBy = true,
        count = items.Count, items,
    });
}).RequireAuthorization();

// ===== 🔴 #486 KHÁCH CHƯA QUAY LẠI — `Ser_ReportCustomerNotBack` (`BizCarSv.Service.Report.cs:5878`) =====
// Ca lệch THẬT đầu tiên tìm được trong 23 cặp của #484 (main-only 5 / wh-only 5, macro=0).
//
// 🔴🔴 **NHÁNH KHO NUỐT DÒNG — bản chính đã sửa, bản kho thì chưa** (luật #410):
//   Bản chính nối **`LEFT JOIN`** sang bốn bảng danh mục, kèm chú thích nguyên văn của tác giả:
//     *"có khoảng 200 bản ghi nhưng phải sửa inner join thành lefjoin để tăng tốc mà vẫn đảm bảo kết quả đúng"*
//     — `Mst_Dealer` · `Mst_District` · `Mst_Province` · `Ser_MST_Model`.
//   Bản `_WH` (cùng file, `:6072`) **vẫn là `INNER JOIN` cả bốn**.
//   ⇒ Khách có `DealerCode`/`DistrictCode`/`ProvinceCode`/`ModelID` **thiếu trong danh mục** thì:
//     · màn chính  → **VẪN hiện** (cột tên để trống);
//     · màn kho    → **BIẾN MẤT** khỏi danh sách "khách chưa quay lại".
//   Đây là **mất dòng lúc ĐỌC**, im lặng, và lệch **theo hướng nguy hiểm**: đúng nhóm khách hồ sơ thiếu
//   thông tin lại là nhóm dễ bị bỏ quên nhất. Port theo **bản chính** (LEFT) + đếm `droppedIfInnerJoined`
//   để thấy được đúng số dòng mà nhánh kho sẽ đánh rơi.
//
// ⚠️ **GUARD ĐẦU VÀO CHỈ NHẬN BỐN GIÁ TRỊ** (đọc `#region //Check`, trích nguyên văn):
//   `if (!(strDateCount.Equals("6") || …("12") || …("24") || …("36"))) throw …_InputInvalid_DateCount`
//   ⇒ chỉ 6 · 12 · 24 · 36. Không phải "số tháng bất kỳ".
// 🔴 **"THÁNG" Ở ĐÂY = 30 NGÀY**: `dtimeSys.AddDays(0 - Convert.ToInt16(strDateCount) * 30)` —
//   không dùng `AddMonths` ⇒ mốc 36 "tháng" thực ra là **1080 ngày**, lệch `3 tuần so với 3 năm lịch.
//   Giữ đúng nguồn (đây là con số nghiệp vụ đang chạy), trả cờ `monthIsThirtyDays`.
// ⚠️ Mốc là **`<` (nhỏ hơn)**, KHÔNG phải `<=`; và dòng `-- and t.CurrentServiceDate >= @strDate` đã bị
//   **COMMENT** ⇒ báo cáo **không có cận dưới**: xe chưa từng quay lại từ 2010 cũng vào danh sách.
// ⚠️ Lọc `f.IsActive = "1"` là của **KHÁCH**, không phải xe. Đại lý lấy từ `Ser_Customer.DealerCode`.
// ⚪ Hai `inner join` còn lại (`Ser_Customer`, `Ser_Car`) là **có chủ đích** — không có khách/xe thì bản ghi
//   không có nghĩa. Kiểm tra âm tính, không đếm vào `droppedIfInnerJoined`.
app.MapGet("/api/reports/customer-not-back", async (AppDbContext db, ITenantContext t,
    string? dealerCode, int? dateCount) =>
{
    if (string.IsNullOrWhiteSpace(dealerCode)) return Results.BadRequest(new { error = "Cần dealerCode." });
    var months = dateCount ?? 6;
    if (months != 6 && months != 12 && months != 24 && months != 36)
        return Results.BadRequest(new
        {
            error = "Ser_ReportCustomerNotBack_InputInvalid_DateCount",
            message = "dateCount chỉ nhận 6, 12, 24 hoặc 36 (đúng guard của nguồn).",
        });
    var dealer = dealerCode!.Trim();
    // Nguồn: AddDays(-months*30) — KHÔNG phải AddMonths.
    var cutoff = DateTime.Now.AddDays(-months * 30).Date;

    var pairs = await (from car in db.ServiceCars
                       join cus in db.ServiceCustomers on car.CusID equals cus.CusCode
                       where car.OrgId == t.OrgId && cus.OrgId == t.OrgId
                             && car.CurrentServiceDate < cutoff        // "<" đúng nguồn, KHÔNG có cận dưới
                             && cus.DealerCode == dealer
                             && cus.FlagActive == "1"                  // IsActive của KHÁCH
                       select new { car, cus }).ToListAsync();

    var dealers = await db.Dealers.Where(x => x.OrgId == t.OrgId)
        .Select(x => new { x.DealerCode, x.DealerName }).ToListAsync();
    var dealerName = dealers.GroupBy(x => x.DealerCode).ToDictionary(g => g.Key, g => g.First().DealerName);
    var provinces = await db.MstProvinces.Where(x => x.OrgId == t.OrgId)
        .Select(x => new { x.ProvinceCode, x.ProvinceName }).ToListAsync();
    var provName = provinces.GroupBy(x => x.ProvinceCode).ToDictionary(g => g.Key, g => g.First().ProvinceName);
    var districts = await db.MstDistricts.Where(x => x.OrgId == t.OrgId)
        .Select(x => new { x.ProvinceCode, x.DistrictCode, x.DistrictName }).ToListAsync();
    var distName = districts.GroupBy(x => x.ProvinceCode + "|" + x.DistrictCode)
        .ToDictionary(g => g.Key, g => g.First().DistrictName);
    var models = await db.ServiceModels.Where(x => x.OrgId == t.OrgId)
        .Select(x => new { x.ModelCode, x.ModelName }).ToListAsync();
    var modelName = models.GroupBy(x => x.ModelCode).ToDictionary(g => g.Key, g => g.First().ModelName);

    // Số dòng mà nhánh kho (INNER JOIN cả bốn danh mục) sẽ ĐÁNH RƠI.
    var droppedIfInnerJoined = pairs.Count(p =>
        (p.cus.DealerCode == null || !dealerName.ContainsKey(p.cus.DealerCode))
        || (p.cus.ProvinceCode == null || !provName.ContainsKey(p.cus.ProvinceCode))
        || (p.cus.ProvinceCode == null || p.cus.DistrictCode == null
            || !distName.ContainsKey(p.cus.ProvinceCode + "|" + p.cus.DistrictCode))
        || (p.car.ModelCode == null || !modelName.ContainsKey(p.car.ModelCode)));

    var items = pairs.Select(p => new
    {
        p.cus.DealerCode,
        DealerName = p.cus.DealerCode != null && dealerName.ContainsKey(p.cus.DealerCode)
            ? dealerName[p.cus.DealerCode] : null,
        p.cus.CusName, p.cus.Mobile, p.cus.Address,
        p.cus.DistrictCode,
        DistrictName = p.cus.ProvinceCode != null && p.cus.DistrictCode != null
            && distName.ContainsKey(p.cus.ProvinceCode + "|" + p.cus.DistrictCode)
            ? distName[p.cus.ProvinceCode + "|" + p.cus.DistrictCode] : null,
        p.cus.ProvinceCode,
        ProvinceName = p.cus.ProvinceCode != null && provName.ContainsKey(p.cus.ProvinceCode)
            ? provName[p.cus.ProvinceCode] : null,
        p.car.PlateNo, p.car.FrameNo,
        ModelID = p.car.ModelCode,
        ModelName = p.car.ModelCode != null && modelName.ContainsKey(p.car.ModelCode)
            ? modelName[p.car.ModelCode] : null,
        p.car.ColorCode, p.car.WarrantyExpiresDate, p.car.CurrentKm, p.car.CurrentServiceDate,
    }).OrderBy(x => x.CusName).ThenBy(x => x.PlateNo).ToList();

    return Results.Ok(new
    {
        dealerCode = dealer, dateCount = months,
        cutoff = cutoff.ToString("yyyy-MM-dd HH:mm:ss"),
        count = items.Count, items,
        droppedIfInnerJoined,
        whBranchStillInnerJoins = true,
        monthIsThirtyDays = true,
        noLowerBound = true,
        allowedDateCounts = new[] { 6, 12, 24, 36 },
    });
}).RequireAuthorization();

// ===== 🔴 #487 LỊCH SỬ GIÁ NHẬP PHỤ TÙNG — `Ser_ReportHistoryCost` (`Service.Report.cs:5686`) =====
// ⚪ Cặp `_WH` (`WH.cs:6613`) khác **ĐÚNG HAI DÒNG**, và cả hai chỉ là **dấu `--//[mylock]` có/không**
//   ⇒ **hoàn toàn tương đương**. Đóng thêm một ca của danh sách #484 (còn 15).
//
// 🔴 **LEFT JOIN CHẾT** (luật #414, cả ba câu hỏi đều "có"):
//     `left join Ser_Inv_StockInDetail sid on spi.StockInID = sid.StockInID and …`
//     `join      Ser_Inv_StockIn       si  on si.StockInID  = **sid**.StockInID and …`
//   Bảng thứ hai nối **TRONG** và nối **qua cột của bảng LEFT** ⇒ LEFT bị ép thành INNER.
//   Thêm `and si.Status not in ("4","5")` trong WHERE — lại là điều kiện trên bảng đó.
//   ⇒ Bản ghi tồn kho **không khớp dòng chi tiết phiếu nhập** bị **loại im lặng** khỏi lịch sử giá.
//   Port giữ đúng hành vi (INNER) nhưng **đếm** `droppedByStockInDetailJoin` để con số đó nhìn thấy được.
//
// 🔴 **CỘT `SLX` LUÔN BẰNG 0**: nguồn viết thẳng `0 as SLX` (số lượng XUẤT) trong khi nhãn báo cáo là
//   "lịch sử giá" ⇒ **nửa XUẤT chưa bao giờ được cài**. Ai đọc báo cáo sẽ tưởng kỳ đó không xuất phụ tùng nào.
//   Giữ nguyên cột (đúng nguồn) + cờ `slxIsAlwaysZeroPlaceholder`.
// ⚠️ Mốc ngày bake thẳng: `spi.DateIn <= "@ToDate"` — không kèm giờ ⇒ **mất trọn ngày cuối** (#415).
//   Port dùng `23:59:59` và đếm `lostByRawEndDate`.
// ⚠️ `strPartID` lấy từ `CheckPartNotFound` rồi **có guard phòng hờ** `if (dtPart != null && Rows.Count > 0)`;
//   nếu không vào nhánh đó thì `strPartID` ở lại **chuỗi rỗng** ⇒ SQL thành `PartID=""` ⇒ **0 dòng, không lỗi**.
//   Port chặn thẳng (404) — sai lệch CỐ Ý, cờ `sourceReturnsEmptyWhenPartMissing`.
// ⚠️ Tiền = `sum(Qty*SIPrice + Qty*SIPrice*0.01*VAT)` với `VAT` lấy từ bảng LEFT (`isnull(...,0)`).
// ⚠️ Kết quả là **HAI bảng**: lịch sử + thông tin phụ tùng (`Ser_Mst_Part`).
app.MapGet("/api/reports/part-cost-history", async (AppDbContext db, ITenantContext t,
    string? dealerCode, string? partCode, DateTime? fromDate, DateTime? toDate) =>
{
    if (string.IsNullOrWhiteSpace(dealerCode)) return Results.BadRequest(new { error = "Cần dealerCode." });
    if (string.IsNullOrWhiteSpace(partCode)) return Results.BadRequest(new { error = "Cần partCode." });
    if (fromDate is null || toDate is null) return Results.BadRequest(new { error = "Cần fromDate và toDate." });
    var dealer = dealerCode!.Trim();
    var code = partCode!.Trim().ToUpperInvariant();

    var part = await db.ServiceParts.FirstOrDefaultAsync(p => p.OrgId == t.OrgId && p.PartCode == code);
    if (part is null)
        return Results.NotFound(new
        {
            partCode = code,
            error = "Ser_ReportHistoryCost: không tìm thấy phụ tùng.",
            sourceReturnsEmptyWhenPartMissing = true,
            note = "Nguồn để PartID rỗng rồi lọc PartID=\"\" ⇒ trả 0 dòng mà KHÔNG báo lỗi; port chặn thẳng.",
        });

    var from = fromDate.Value.Date;
    var toRawMidnight = toDate.Value.Date;
    var to = toDate.Value.Date.AddDays(1).AddSeconds(-1);

    var inst = await db.PartInstances.Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer
            && x.PartID == part.PartID
            && x.DateIn != null && x.DateIn >= from && x.DateIn <= to
            && x.Status != "4" && x.Status != "5").ToListAsync();
    var lostByRawEndDate = inst.Count(x => x.DateIn > toRawMidnight);

    var lines = await db.PartStockInLines.Where(l => l.OrgId == t.OrgId).ToListAsync();
    var lineByKey = lines.Where(l => l.PartCode != null)
        .GroupBy(l => l.StockInId + "|" + l.PartCode)
        .ToDictionary(g => g.Key, g => g.First());

    // LEFT bị ép thành INNER ở nguồn ⇒ chỉ giữ dòng CÓ chi tiết phiếu nhập; đếm phần bị loại.
    var kept = inst.Where(x => lineByKey.ContainsKey(x.StockInId + "|" + (x.PartCode ?? ""))).ToList();
    var droppedByStockInDetailJoin = inst.Count - kept.Count;

    var items = kept
        .GroupBy(x => new { x.PartID, x.LocationID, x.StockInId, x.StockInNo, x.SIPrice, x.DateIn })
        .Select(g =>
        {
            var vat = lineByKey.TryGetValue(g.Key.StockInId + "|" + (g.First().PartCode ?? ""), out var l)
                ? l.VAT : 0m;
            var price = g.Key.SIPrice ?? 0m;
            var qty = g.Sum(x => x.Quantity);
            return new
            {
                g.Key.PartID,
                RefID = g.Key.StockInId,
                RefNo = g.Key.StockInNo,
                RefDate = g.Key.DateIn,
                Remark = "Nhập kho",
                g.Key.LocationID,
                SLN = qty,
                SLX = 0m,                                   // nguồn viết thẳng 0 — nửa XUẤT chưa cài
                TGN = qty * price + qty * price * 0.01m * vat,
                Price = price,
            };
        }).OrderBy(x => x.RefDate).ThenBy(x => x.RefNo).ToList();

    return Results.Ok(new
    {
        dealerCode = dealer, partCode = code,
        from = from.ToString("yyyy-MM-dd HH:mm:ss"), to = to.ToString("yyyy-MM-dd HH:mm:ss"),
        count = items.Count, items,
        // bảng kết quả thứ hai của nguồn: thông tin phụ tùng
        part = new { part.PartID, part.PartCode, VieName = part.PartName, part.Unit, Location = part.Location ?? "" },
        droppedByStockInDetailJoin,
        leftJoinDeadInSource = true,
        slxIsAlwaysZeroPlaceholder = true,
        endDateExclusiveInSource = true, lostByRawEndDate,
        whTwinEquivalent = true,
    });
}).RequireAuthorization();

// ===== 🔴 #488 CHÊNH LỆCH GIÁ SO VỚI DANH MỤC — `Ser_ReportRoVarianceCost` (`Service.Report.cs:5267`) =====
// ⚪ Cặp `_WH` (`WH.cs:6790`) khác **đúng một dòng**, và đó chỉ là dấu `--//[mylock]` ⇒ tương đương.
//   Đóng thêm một ca của #484 (**còn 14**).
//
// 🔴 **BỘ LỌC "TẤT CẢ ĐẠI LÝ" LÀ CODE CHẾT** (bẫy bake-param):
//   Nguồn viết `and ('@DealerCode' is null or Ro.DealerCode = '@DealerCode')` — nhưng `@DealerCode` được
//   **thay bằng StringUtils.Replace**, nên sau khi thay chuỗi là `('VN030' is null or …)`.
//   Một **hằng chuỗi** thì **không bao giờ NULL** ⇒ vế đầu **luôn FALSE**; truyền rỗng cũng chỉ thành
//   `('' is null or Ro.DealerCode = '')` ⇒ vẫn FALSE rồi lọc `DealerCode = ''` ⇒ **0 dòng**.
//   ⇒ Ý định "bỏ trống = xem mọi đại lý" **không bao giờ chạy được**. (Dòng `--and Ro.DealerCode = …` ngay
//     phía trên đã bị comment, cho thấy đây là lần sửa dở dang.) Port **bắt buộc** `dealerCode` + nêu cờ.
// 🔴 **LEFT JOIN CHẾT** ở CẢ HAI nhánh: `left join ser_Car car …` rồi WHERE có `car.DealerCode = '@DealerCode'`
//   ⇒ lệnh không có xe khớp **bị loại**. Đếm `droppedByCarJoin`.
// 🔴 **`union` (không phải `union all`)** ⇒ hai dòng **giống hệt nhau** trong cùng một nhánh bị **gộp làm một**.
//   Hai dòng dịch vụ trùng khít trên một lệnh sẽ chỉ còn một ⇒ **dòng bị nuốt**. Cờ `unionDedupesRows`.
// 🔴 **CÔNG THỨC LỆCH GIỮA HAI NHÁNH**: nhánh dịch vụ so `Price*Factor*(1+VAT)` với **`ser.Price*(1+VAT)`**
//   — giá chuẩn **KHÔNG nhân Factor**; nhánh phụ tùng thì cả hai vế đều nhân `Quantity`.
//   ⇒ Với dịch vụ có `Factor != 1`, "chênh lệch" gồm cả phần hệ số, không chỉ phần lệch đơn giá. Cờ
//     `serviceVarianceIgnoresFactorOnStandard` — giữ đúng nguồn, không tự "sửa cho cân".
// ⚠️ **HAI cửa sổ ngày cùng lúc**: cả `ActualDeliveryDate` **và** `CheckInDate` đều phải nằm trong [From,To];
//   mốc `<=` không kèm giờ ⇒ **mất trọn ngày cuối** (#415). Port dùng 23:59:59 + đếm `lostByRawEndDate`.
// ⚠️ Nhánh dịch vụ đặt `'' as Quantity` (**chuỗi rỗng**, không phải 0) rồi câu ngoài lại
//   `case when Quantity = '0' … when Quantity != '0' then Quantity end` ⇒ dịch vụ luôn rơi vào vế thứ hai
//   và `SoLuong` nhận **chuỗi rỗng**. Giữ nguyên (đúng nguồn), trả `soLuong` kiểu chuỗi.
// ⚪ `left join Sys_User su` (danh mục người dùng) — WHERE **không** đụng tới ⇒ **LEFT còn sống**. Kiểm âm tính.
// ⚠️ `round(...,0)` chỉ áp ở hai cột trình bày (`TriGia01`, `ChenhLech`), không áp vào cột gốc.
app.MapGet("/api/reports/ro-variance-cost", async (AppDbContext db, ITenantContext t,
    string? dealerCode, DateTime? fromDate, DateTime? toDate, string? plateNo, string? roNo) =>
{
    if (string.IsNullOrWhiteSpace(dealerCode))
        return Results.BadRequest(new
        {
            error = "Cần dealerCode.",
            allDealersBranchIsDeadInSource = true,
            note = "Nguồn có vế ('@DealerCode' is null or …) nhưng giá trị được BAKE nên vế đó luôn FALSE.",
        });
    if (fromDate is null || toDate is null) return Results.BadRequest(new { error = "Cần fromDate và toDate." });
    var dealer = dealerCode!.Trim();
    var from = fromDate.Value.Date;
    var toRawMidnight = toDate.Value.Date;
    var to = toDate.Value.Date.AddDays(1).AddSeconds(-1);

    var ros = await db.RepairOrders.Where(r => r.OrgId == t.OrgId && r.DealerCode == dealer
            && r.Status == "FNS"
            && r.ActualDeliveryDate >= from && r.ActualDeliveryDate <= to
            && r.CheckInDate >= from && r.CheckInDate <= to).ToListAsync();
    var lostByRawEndDate = ros.Count(r => r.ActualDeliveryDate > toRawMidnight || r.CheckInDate > toRawMidnight);

    if (!string.IsNullOrWhiteSpace(plateNo))
        ros = ros.Where(r => r.LicensePlate != null && r.LicensePlate.Contains(plateNo!.Trim())).ToList();
    if (!string.IsNullOrWhiteSpace(roNo))
        ros = ros.Where(r => r.RONo.Contains(roNo!.Trim())).ToList();

    // LEFT bị ép thành INNER: xe phải tồn tại VÀ thuộc đúng đại lý.
    var cars = await db.ServiceCars.Where(c => c.OrgId == t.OrgId && c.DealerCode == dealer)
        .Select(c => new { c.CarID, c.CusID, c.PlateNo, c.TradeMark, c.ModelCode }).ToListAsync();
    var carByKey = cars.Where(c => c.CarID != null && c.CusID != null)
        .GroupBy(c => c.CarID + "|" + c.CusID).ToDictionary(g => g.Key, g => g.First());
    var before = ros.Count;
    ros = ros.Where(r => r.CarID != null && r.CusID != null
                         && carByKey.ContainsKey(r.CarID + "|" + r.CusID)).ToList();
    var droppedByCarJoin = before - ros.Count;

    var models = await db.ServiceModels.Where(x => x.OrgId == t.OrgId)
        .Select(x => new { x.ModelCode, x.ModelName }).ToListAsync();
    var modelName = models.GroupBy(x => x.ModelCode).ToDictionary(g => g.Key, g => g.First().ModelName);
    var stdSer = await db.ServiceMstServices.Where(x => x.OrgId == t.OrgId).ToListAsync();
    var serById = stdSer.GroupBy(x => x.SerID).ToDictionary(g => g.Key, g => g.First());
    var stdPart = await db.ServiceParts.Where(x => x.OrgId == t.OrgId).ToListAsync();
    var partByCode = stdPart.Where(x => x.PartCode != null)
        .GroupBy(x => x.PartCode!).ToDictionary(g => g.Key, g => g.First());

    var roIds = ros.Select(r => r.Id).ToList();
    var svc = await db.RoServiceItems.Where(x => x.OrgId == t.OrgId && roIds.Contains(x.RoId)).ToListAsync();
    var prt = await db.RoPartItems.Where(x => x.OrgId == t.OrgId && roIds.Contains(x.RoId)).ToListAsync();
    var roById = ros.ToDictionary(r => r.Id);

    var rows = new List<object>();
    foreach (var x in svc)
    {
        if (!roById.TryGetValue(x.RoId, out var r)) continue;
        var car = carByKey[r.CarID + "|" + r.CusID];
        var std = x.SerCode != null && serById.ContainsKey(x.SerCode) ? serById[x.SerCode] : null;
        var sellPrice = x.Price; var factor = x.Factor; var vat = x.Vat;
        var triGia = sellPrice * factor + sellPrice * factor * vat * 0.01m;
        // ⚠️ giá chuẩn KHÔNG nhân Factor — đúng nguồn.
        var chuan = std is null ? 0m : std.Price + std.Price * std.Vat * 0.01m;
        rows.Add(new
        {
            r.RONo, DisplayRoNo = "BG-" + r.RONo, r.CheckInDate, r.ActualDeliveryDate,
            r.CusID, r.CarID, car.PlateNo, TradeMarkCode = car.TradeMark,
            ModelName = car.ModelCode != null && modelName.ContainsKey(car.ModelCode) ? modelName[car.ModelCode] : null,
            IDPartSer = x.SerCode, PaSeCode = x.SerCode, PaSeName = x.SerName,
            GiaBan = sellPrice, Quantity = "", VatBan = vat, x.Factor,
            GiaChuan = std?.Price ?? 0m, VATChuan = std?.Vat ?? 0m,
            TriGia = triGia, varianceCost = triGia - chuan, SPIndex = "1",
            r.Creator,
            TriGia01 = Math.Round(triGia, 0), ChenhLech = Math.Round(triGia - chuan, 0),
            SoLuong = "",
        });
    }
    foreach (var x in prt)
    {
        if (!roById.TryGetValue(x.RoId, out var r)) continue;
        var car = carByKey[r.CarID + "|" + r.CusID];
        var std = x.PartCode != null && partByCode.ContainsKey(x.PartCode) ? partByCode[x.PartCode] : null;
        var qty = x.NeedQty; var sellPrice = x.UnitPrice; var factor = x.Factor; var vat = x.Vat;
        var triGia = sellPrice * qty * factor + sellPrice * qty * factor * vat * 0.01m;
        var chuan = std is null ? 0m : std.Price * qty + std.Price * qty * (std.VAT ?? 0m) * 0.01m;
        rows.Add(new
        {
            r.RONo, DisplayRoNo = "BG-" + r.RONo, r.CheckInDate, r.ActualDeliveryDate,
            r.CusID, r.CarID, car.PlateNo, TradeMarkCode = car.TradeMark,
            ModelName = car.ModelCode != null && modelName.ContainsKey(car.ModelCode) ? modelName[car.ModelCode] : null,
            IDPartSer = x.PartCode, PaSeCode = x.PartCode, PaSeName = x.PartName,
            GiaBan = sellPrice, Quantity = qty.ToString(System.Globalization.CultureInfo.InvariantCulture),
            VatBan = vat, x.Factor,
            GiaChuan = std?.Price ?? 0m, VATChuan = std?.VAT ?? 0m,   // VAT cua ServicePart la decimal?
            TriGia = triGia, varianceCost = triGia - chuan, SPIndex = "2",
            r.Creator,
            TriGia01 = Math.Round(triGia, 0), ChenhLech = Math.Round(triGia - chuan, 0),
            SoLuong = qty == 0 ? null : qty.ToString(System.Globalization.CultureInfo.InvariantCulture),
        });
    }

    // `union` (không phải `union all`) ⇒ khử trùng dòng giống hệt. Đếm phần bị gộp.
    var before2 = rows.Count;
    var deduped = rows.Select(r => new { key = System.Text.Json.JsonSerializer.Serialize(r), r })
        .GroupBy(x => x.key).Select(g => g.First().r).ToList();
    var collapsedByUnion = before2 - deduped.Count;

    return Results.Ok(new
    {
        dealerCode = dealer,
        from = from.ToString("yyyy-MM-dd HH:mm:ss"), to = to.ToString("yyyy-MM-dd HH:mm:ss"),
        count = deduped.Count, items = deduped,
        droppedByCarJoin, collapsedByUnion, lostByRawEndDate,
        allDealersBranchIsDeadInSource = true,
        unionDedupesRows = true,
        serviceVarianceIgnoresFactorOnStandard = true,
        bothDateWindowsApplied = true,
        whTwinEquivalent = true,
    });
}).RequireAuthorization();

// ===== 🔴 #489 THỐNG KÊ KHÁCH ĐÃ SỬA CHỮA — `Ser_Count_Customer_OnlyHTC` (`Customer.cs:17780`) =====
// ⚪ Cặp `_WH` (`WH.cs:18586`) khác **đúng hai dòng**, và chỉ là **khoảng trắng** trong lời gọi `BuildClause`
//   ⇒ tương đương. Đóng thêm một ca của #484 (**còn 13**).
// ⚠️ **TÊN NÓI DỐI**: hàm tên `Count_` nhưng **không đếm** — nó trả **danh sách dòng** khách + xe + lệnh.
//
// 🔴 **BA `left join` ĐỀU CHẾT** (luật #414 — đây là ca sách giáo khoa, cả ba lý do cùng xuất hiện):
//   · `left join ser_ro ro` … rồi WHERE có `and ro.ROID is not null` ⇒ **giết thẳng** vế LEFT.
//   · `left join ser_Customer cus on car.cusid = cus.cusid **and ro.DealerCode = cus.DealerCode**`
//     ⇒ điều kiện nối lấy cột của **bảng LEFT khác** (`ro`) ⇒ chết theo.
//   · `left join ser_mst_Model mdl … **and ro.DealerCode = mdl.DealerCode**` ⇒ cùng lý do.
//   · và `join ser_mst_TradeMark tm … and ro.DealerCode = tm.DealerCode` là **INNER** ⇒ ép nốt `ro` thành INNER.
//   ⇒ Thực chất **bốn bảng đều INNER**: xe chưa có lệnh, hoặc thiếu khách/model/hãng trong danh mục,
//     đều **biến mất**. Port giữ đúng hành vi và **đếm** `droppedByRequiredJoins`.
//
// ⚪ KIỂM TRA ÂM TÍNH (#415) — **ngược với phần lớn báo cáo khác**: mốc ngày ở đây viết bằng
//   `datediff(day, convert(datetime, "@FromDate", 20), ro.CheckInDate) >= 0` và đối xứng cho `@ToDate`
//   ⇒ so **theo NGÀY**, nên **KHÔNG mất ngày cuối**. Ghi lại để lượt sau khỏi vá nhầm.
// ⚠️ **BỘ LỌC TRÊN BIỂU THỨC GHÉP**, không phải trên cột:
//   `BuildClause("and", "tm.TradeMarkName + ' - ' + mdl.modelName", strModelConditionList, …)`
//   ⇒ người gọi phải truyền **đúng chuỗi đã ghép** ("Hyundai - Accent"), không phải mã model.
// ⚠️ Phạm vi đại lý dùng `BuildClauseConditionSingle(…, "like", …)` ⇒ là **mẫu LIKE** (BU pattern),
//   giá trị bind **nguyên văn** ⇒ người gọi phải tự thêm `%`.
// ⚠️ Điện thoại: `Replace(isnull(cus.tel, cus.mobile), " ", "")` — **ưu tiên bàn, thiếu mới lấy di động**,
//   và **bỏ hết khoảng trắng**; biển số cũng bị bỏ khoảng trắng. Giữ đúng.
app.MapGet("/api/reports/customer-serviced", async (AppDbContext db, ITenantContext t,
    string? dealerPattern, DateTime? fromDate, DateTime? toDate,
    string? vin, string? plateNo, string? tradeMarkModel) =>
{
    if (fromDate is null || toDate is null) return Results.BadRequest(new { error = "Cần fromDate và toDate." });
    var from = fromDate.Value.Date;
    var to = toDate.Value.Date;            // so theo NGÀY — đúng nguồn, không cần 23:59:59

    var cars = await db.ServiceCars.Where(c => c.OrgId == t.OrgId).ToListAsync();
    if (!string.IsNullOrWhiteSpace(dealerPattern))
    {
        // LIKE nguyên văn của nguồn: người gọi tự đưa % vào.
        var pat = dealerPattern!.Trim();
        var like = new System.Text.RegularExpressions.Regex(
            "^" + System.Text.RegularExpressions.Regex.Escape(pat).Replace("%", ".*") + "$",
            System.Text.RegularExpressions.RegexOptions.IgnoreCase);
        cars = cars.Where(c => c.DealerCode != null && like.IsMatch(c.DealerCode)).ToList();
    }
    if (!string.IsNullOrWhiteSpace(plateNo))
        cars = cars.Where(c => c.PlateNo != null && c.PlateNo.Contains(plateNo!.Trim())).ToList();
    if (!string.IsNullOrWhiteSpace(vin))
        cars = cars.Where(c => c.FrameNo.Contains(vin!.Trim())).ToList();

    var ros = await db.RepairOrders.Where(r => r.OrgId == t.OrgId
            && (r.Status == "PAID" || r.Status == "FNS")
            && r.CheckInDate != null).ToListAsync();
    ros = ros.Where(r => r.CheckInDate!.Value.Date >= from && r.CheckInDate!.Value.Date <= to).ToList();

    var custs = await db.ServiceCustomers.Where(x => x.OrgId == t.OrgId).ToListAsync();
    var cusByKey = custs.Where(x => x.DealerCode != null)
        .GroupBy(x => x.CusCode + "|" + x.DealerCode).ToDictionary(g => g.Key, g => g.First());
    var models = await db.ServiceModels.Where(x => x.OrgId == t.OrgId).ToListAsync();
    var mdlByKey = models.Where(x => x.DealerCode != null)
        .GroupBy(x => x.ModelCode + "|" + x.DealerCode).ToDictionary(g => g.Key, g => g.First());
    var marks = await db.ServiceTradeMarks.Where(x => x.OrgId == t.OrgId).ToListAsync();
    var tmByCode = marks.GroupBy(x => x.TradeMarkCode).ToDictionary(g => g.Key, g => g.First());

    var carById = cars.Where(c => c.CarID != null).GroupBy(c => c.CarID!).ToDictionary(g => g.Key, g => g.First());
    var beforeJoins = 0; var rows = new List<object>();
    foreach (var r in ros)
    {
        if (r.CarID == null || !carById.TryGetValue(r.CarID, out var car)) continue;
        if (car.DealerCode != r.DealerCode) continue;      // nguồn nối car.DealerCode = ro.DealerCode
        beforeJoins++;
        // Ba bảng còn lại đều bị ép INNER (xem ghi chú) — thiếu bất kỳ cái nào là MẤT dòng.
        if (car.CusID == null || r.DealerCode == null) continue;
        if (!cusByKey.TryGetValue(car.CusID + "|" + r.DealerCode, out var cus)) continue;
        if (car.ModelCode == null || !mdlByKey.TryGetValue(car.ModelCode + "|" + r.DealerCode, out var mdl)) continue;
        if (car.TradeMark == null || !tmByCode.TryGetValue(car.TradeMark, out var tm)) continue;

        var phone = (cus.Tel ?? cus.Mobile ?? "").Replace(" ", "");
        var tmName = tm.TradeMarkName ?? "";
        var combo = tmName + " - " + (mdl.ModelName ?? "");
        if (!string.IsNullOrWhiteSpace(tradeMarkModel) && combo != tradeMarkModel!.Trim()) continue;

        rows.Add(new
        {
            cus.CusName, CusId = cus.CusCode, cus.Address, phone,
            car.CarID, PlateNo = (car.PlateNo ?? "").Replace(" ", ""), car.FrameNo,
            TradeMarkName = tmName, TradeMarkNameModel = combo,
            RONO = "LS-" + r.RONo, r.CheckInDate, r.CusRequest, r.FinishedDate,
        });
    }
    var droppedByRequiredJoins = beforeJoins - rows.Count;

    return Results.Ok(new
    {
        from = from.ToString("yyyy-MM-dd"), to = to.ToString("yyyy-MM-dd"),
        count = rows.Count, items = rows,
        droppedByRequiredJoins,
        allLeftJoinsAreDeadInSource = true,
        dateComparedByDayNoLastDayLoss = true,
        modelFilterIsConcatenatedExpression = true,
        dealerScopeIsLikePattern = true,
        functionNameSaysCountButReturnsRows = true,
        whTwinEquivalent = true,
    });
}).RequireAuthorization();

// ===== 🔴 #490 NHẮC BẢO DƯỠNG — `Ser_CustomerCareMace_Get` (`BizCarSv.Customer.cs:13215`) =====
// ⚪ Cặp `_WH` (`WH.cs:26394`) khác **ba dòng**, toàn là xuống dòng / dấu `--//[mylock]` ⇒ tương đương.
//   Đóng thêm một ca của #484 (**còn 12**).
//
// 🔴🔴 **LỌC SAI CỘT — bộ lọc "loại nhắc" bắn vào một cột KHÁC**:
//     `BuildClause("and", "t.**CareType**", str**MaceType**ConditionList, …)`
//   trong khi **mọi cột SELECT và cả bảng nhãn** đều dùng `t.**MaceType**`, và đường GHI
//   (`BizCarSv.Service01.cs:9667` …) chỉ đặt `dtCareMace.Rows[0]["MaceType"]` — **không bao giờ ghi `CareType`**.
//   ⇒ Hai cách đọc, **cả hai đều hỏng**: nếu bảng **không có** cột `CareType` thì truyền lọc là **lỗi SQL**;
//     nếu **có** cột đó (di sản) thì nó **luôn rỗng** ⇒ lọc trả **0 dòng**.
//   Không truy được DB thật ở đây nên **không chốt** cách nào; port lọc theo `MaceType` (cột đang dùng thật)
//   và trả cờ `sourceFiltersWrongColumn` + `sourceFilterColumn = "CareType"` để nghiệp vụ xác nhận.
//   ⚠️ Lỗi này xuất hiện ở **HAI** hàm (`:13354` và `:13568`) — không phải gõ nhầm một chỗ.
//
// 🔴 `join ser_ro ro on t.ROID = ro.ROID` là **INNER** ⇒ phiếu nhắc **chưa gắn lệnh sửa chữa biến mất**.
//   Đếm `droppedByRoJoin`. ⚠️ `inner join Ser_Car car on t.CarId = car.CarId` — vế thứ hai
//   `--and t.cusId = car.CusId` **ĐÃ BỊ COMMENT** ⇒ ở màn này xe sang tên **VẪN ra dòng**
//   (ngược với #460, giống #466). Port theo dòng ACTIVE.
// ⚪ `left join ser_mst_model`: WHERE không đụng tới ⇒ **LEFT còn sống** (kiểm âm tính).
// ⚠️ HAI bảng nhãn, **cả hai KHÔNG có ELSE** ⇒ mã lạ cho nhãn **null** nhưng dòng **vẫn được đếm**:
//   `MaceType` 1 = "CVDV chỉ định" · 2 = "Thời hạn sau 6 tháng" · 3 = "Thời hạn theo tần suất vào xưởng";
//   `Status` 0 = "Chưa liên hệ" · 1 = "Đã liên hệ" · 2 = "Không liên hệ".
//   ⚠️ HẰNG ≠ GIÁ TRỊ đã truy: đường ghi đặt `Status = Constants.Flag.Inactive`, mà `Flag.Inactive = "0"`
//     ⇒ phiếu mới tạo đúng là **"Chưa liên hệ"**.
app.MapGet("/api/reports/care-mace", async (AppDbContext db, ITenantContext t,
    string? dealerCode, string? cusId, string? cusName, string? frameNo, string? plateNo,
    string? status, string? maceType, DateTime? recomentFrom, DateTime? recomentTo) =>
{
    var q = db.CustomerCareMaces.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealerCode)) q = q.Where(x => x.DealerCode == dealerCode!.Trim());
    if (!string.IsNullOrWhiteSpace(cusId)) q = q.Where(x => x.CusID == cusId!.Trim());
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(x => x.Status == status!.Trim());
    // ⚠️ Nguồn lọc t.CareType; port lọc t.MaceType (cột thật đang dùng) — xem ghi chú.
    if (!string.IsNullOrWhiteSpace(maceType)) q = q.Where(x => x.MaceType == maceType!.Trim());
    if (recomentFrom.HasValue) q = q.Where(x => x.MaceRecomentDate >= recomentFrom);
    if (recomentTo.HasValue) q = q.Where(x => x.MaceRecomentDate <= recomentTo);
    var maces = await q.ToListAsync();

    var custs = await db.ServiceCustomers.Where(x => x.OrgId == t.OrgId).ToListAsync();
    var cusByCode = custs.GroupBy(x => x.CusCode).ToDictionary(g => g.Key, g => g.First());
    var cars = await db.ServiceCars.Where(x => x.OrgId == t.OrgId && x.CarID != null).ToListAsync();
    var carById = cars.GroupBy(x => x.CarID!).ToDictionary(g => g.Key, g => g.First());
    var ros = await db.RepairOrders.Where(x => x.OrgId == t.OrgId).ToListAsync();
    var roByNo = ros.GroupBy(x => x.RONo).ToDictionary(g => g.Key, g => g.First());
    var models = await db.ServiceModels.Where(x => x.OrgId == t.OrgId).ToListAsync();
    var modelName = models.GroupBy(x => x.ModelCode).ToDictionary(g => g.Key, g => g.First().ModelName);

    static string? MaceTypeText(string? c) => c switch
    {
        "1" => "CVDV chỉ định",
        "2" => "Thời hạn sau 6 tháng",
        "3" => "Thời hạn theo tần suất vào xưởng",
        _ => null,          // nguồn KHÔNG có ELSE
    };
    static string? StatusText(string? c) => c switch
    {
        "0" => "Chưa liên hệ",
        "1" => "Đã liên hệ",
        "2" => "Không liên hệ",
        _ => null,
    };

    var before = maces.Count; var rows = new List<object>();
    foreach (var m in maces)
    {
        // INNER: khách + xe + lệnh đều bắt buộc (ROID là INNER ở nguồn).
        if (m.CusID == null || !cusByCode.TryGetValue(m.CusID, out var cus)) continue;
        if (m.CarID == null || !carById.TryGetValue(m.CarID, out var car)) continue;
        if (m.RONo == null || !roByNo.TryGetValue(m.RONo, out var ro)) continue;
        if (!string.IsNullOrWhiteSpace(cusName) && !(cus.CusName ?? "").Contains(cusName!.Trim())) continue;
        if (!string.IsNullOrWhiteSpace(frameNo) && !car.FrameNo.Contains(frameNo!.Trim())) continue;
        if (!string.IsNullOrWhiteSpace(plateNo) && !(car.PlateNo ?? "").Contains(plateNo!.Trim())) continue;
        rows.Add(new
        {
            cus.CusName, cus.Tel, cus.Mobile, cus.Email,
            cus.ContName, cus.ContAddress, cus.ContEmail, cus.ContTel, cus.ContMobile,
            car.PlateNo, TradeMarkCode = car.TradeMark,
            ModelName = car.ModelCode != null && modelName.ContainsKey(car.ModelCode) ? modelName[car.ModelCode] : null,
            ro.CheckInDate, ro.Km,
            MaceId = m.CareNo, m.DealerCode, m.CreatedDate, m.MaceRecomentDate,
            m.CarID, m.CusID, m.MaceType, m.ROID, m.Status,
            MaceTypeText = MaceTypeText(m.MaceType),
            StatusText = StatusText(m.Status),
            m.ContactDate, m.ApointDate, m.Remark,
        });
    }
    var droppedByRoJoin = before - rows.Count;

    return Results.Ok(new
    {
        count = rows.Count, items = rows,
        droppedByRoJoin,
        sourceFiltersWrongColumn = true,
        sourceFilterColumn = "CareType",
        actualColumnUsedEverywhereElse = "MaceType",
        wrongColumnAppearsInTwoFunctions = true,
        carOwnerJoinCommentedOutInSource = true,
        labelTablesHaveNoElse = true,
        whTwinEquivalent = true,
    });
}).RequireAuthorization();

// ===== 🔴 #493 PHỤ TÙNG CHẬM LUÂN CHUYỂN — `Ser_Mst_Part_SP_Get` (`BizCarSv.PartOrder.cs:4196`) =====
// ⚪ Cặp `_WH` (`WH.cs:27415`) khác **đúng một dòng** và chỉ là **khoảng trắng cuối dòng** trong lời gọi
//   `Replace(…, "@iNotRotateFrom", …)` — cả hai bản đều có đủ cả hai placeholder ⇒ **tương đương**.
//   Đóng thêm một ca của #484 (**còn 9**).
//
// 🔴 **"SỐ NGÀY KHÔNG LUÂN CHUYỂN" ĐẾM TỚI HÔM NAY**:
//     `DATEDIFF(DAY, q.MaxStockInDate, GETDATE()) KLuanChuyen`
//   ⇒ mốc là **ngày CHẠY**, không phải mốc báo cáo — cùng khuôn đã gặp ở #473. Chạy lại sau một tuần
//     ra con số khác cho **cùng một danh sách**. Giữ đúng nguồn, trả cờ `ageCountedToTodayNotReportDate`.
//
// 🔴 **BỎ TRỐNG KHÔNG PHẢI "KHÔNG LỌC"**: nguồn khai `int iNotRotateFrom = 0;` rồi chỉ gán khi
//   `int.TryParse` thành công. Truyền rỗng ⇒ **cả hai đều là 0** ⇒ guard `From > To` **không bắt**
//   (0 > 0 sai) và SQL lọc `KLuanChuyen >= "0" and <= "0"` ⇒ **chỉ ra phụ tùng vừa nhập đúng hôm nay**.
//   Người dùng tưởng bỏ trống là xem tất cả; thực tế **gần như rỗng**. Port bắt buộc truyền cả hai + cờ.
// 🔴 **MÌN TRÀN SỐ**: `if (int.TryParse(s, out i)) { i = Convert.To**Int16**(s); }` — parse lọt vào `int`
//   nhưng gán lại bằng `Int16` ⇒ giá trị **> 32767 ném OverflowException** ngay tại tầng biz.
//   Port dùng `int` và chặn mềm ở biên 32767 + cờ `sourceOverflowsAboveInt16`.
// ⚠️ Guard duy nhất của `#region //Check` (đã trích nguyên văn): `if (iNotRotateFrom > iNotRotateTo) throw`
//   `Ser_Mst_Part_SP_Get_InvalidRotate`. Không có guard nào khác.
// ⚠️ Cửa sổ phân trang: `@MyRowIdx_Start = start + 1` (C# đếm từ 0), `@MyRowIdx_End = start + count`.
// ⚠️ Hai mốc bake **có nháy** quanh giá trị SỐ (`"@iNotRotateFrom"`) ⇒ so chuỗi/ép kiểu ngầm ở SQL.
app.MapGet("/api/reports/slow-moving-parts", async (AppDbContext db, ITenantContext t,
    int? notRotateFrom, int? notRotateTo, string? dealerCode, int? start, int? count) =>
{
    // Bỏ trống ở nguồn = 0/0 (xem ghi chú) ⇒ port bắt buộc truyền, tránh "rỗng mà tưởng tất cả".
    if (notRotateFrom is null || notRotateTo is null)
        return Results.BadRequest(new
        {
            error = "Cần notRotateFrom và notRotateTo.",
            emptyMeansZeroInSource = true,
            note = "Nguồn để rỗng thành 0/0 ⇒ lọc KLuanChuyen trong [0,0], gần như không ra dòng nào.",
        });
    var f = notRotateFrom.Value; var tto = notRotateTo.Value;
    if (f > tto)
        return Results.BadRequest(new { error = "Ser_Mst_Part_SP_Get_InvalidRotate", from = f, to = tto });
    var overflowsInSource = f > 32767 || tto > 32767;

    var st = Math.Max(0, start ?? 0);
    var cnt = Math.Clamp(count ?? 50, 1, 500);

    var inst = await db.PartInstances.Where(x => x.OrgId == t.OrgId && x.DateIn != null).ToListAsync();
    if (!string.IsNullOrWhiteSpace(dealerCode))
        inst = inst.Where(x => x.DealerCode == dealerCode!.Trim()).ToList();
    // MaxStockInDate theo từng phụ tùng.
    var maxIn = inst.Where(x => x.PartCode != null)
        .GroupBy(x => x.PartCode!)
        .ToDictionary(g => g.Key, g => g.Max(x => x.DateIn!.Value).Date);

    var today = DateTime.Now.Date;
    var parts = await db.ServiceParts.Where(p => p.OrgId == t.OrgId).ToListAsync();
    var rows = parts.Where(p => p.PartCode != null && maxIn.ContainsKey(p.PartCode))
        .Select(p =>
        {
            var last = maxIn[p.PartCode!];
            return new
            {
                p.PartCode, VieName = p.PartName, p.Unit, p.Location, p.Quantity,
                MaxStockInDate = last,
                KLuanChuyen = (int)(today - last).TotalDays,   // đúng nguồn: đếm tới HÔM NAY
            };
        })
        .Where(x => x.KLuanChuyen >= f && x.KLuanChuyen <= tto)
        .OrderByDescending(x => x.KLuanChuyen).ThenBy(x => x.PartCode)
        .ToList();

    var page = rows.Skip(st).Take(cnt).ToList();
    return Results.Ok(new
    {
        notRotateFrom = f, notRotateTo = tto,
        total = rows.Count, start = st, count = cnt,
        rowIdxStart = st + 1, rowIdxEnd = st + cnt,   // đúng @MyRowIdx_Start/@MyRowIdx_End
        items = page,
        ageCountedToTodayNotReportDate = true,
        emptyMeansZeroInSource = true,
        sourceOverflowsAboveInt16 = overflowsInSource,
        bakedNumericWithQuotes = true,
        whTwinEquivalent = true,
    });
}).RequireAuthorization();

// ===== 🔴 #498 THẺ KHO PHỤ TÙNG — `Ser_InvReportCardStockRpt_New20230623` (`Inventory.Report.cs:5002`) =====
// Trả một trong ba nợ `scope=main|wh` mà #496 khoanh vùng (họ **năm** báo cáo kẹp mốc ngày).
//
// 🔴 **KẸP MỐC ĐẦU KỲ** (đúng họ #422/#496, nay là ca thứ ba được port):
//   `if (StringCompareIgnoreCase(strFromDate, TConst.HTCConst.HTC_WareHouse) < 1) strFromDate = …`
//   với `HTC_WareHouse = "2017-12-31"` ⇒ xin mốc **≤ 31-12-2017** thì bản chính **âm thầm kéo về 2017-12-31**;
//   bản `_WH` **không kẹp** (đếm `HTC_WareHouse`: **2 ở bản chính · 0 ở bản kho**). Giữ `scope=main|wh`.
// ⚠️ **TỒN ĐẦU KỲ lấy tại mốc `FromDate − 1 ngày`**: `strDateDK = Convert.ToDateTime(strFromDate).AddDays(-1)`,
//   rồi ba macro `zzB_…_zzE` dựng `#tbl_sd`/`#tbl_sdo`/`#tbl_Open` với khoảng **["1900-01-01", strDateDK]**.
//   ⇒ Cận dưới của tồn đầu là **hằng 1900-01-01**, không phải tham số. (Macro ⇒ `diffwh.js` không đọc được,
//     xem cảnh báo #475.)
//
// 🔴🔴 **`@PartID` BAKE KHÔNG CÓ NHÁY — nặng hơn ca #487**:
//   Nguồn viết `AND spi.PartID=@PartID` (4 chỗ) và `AND p.PartID=@PartID`, rồi thay bằng `Replace(…, "@PartID",
//   strPartID)`. Nếu `CheckPartNotFound` không trả dòng nào thì `strPartID` ở lại **chuỗi rỗng** ⇒ SQL thành
//   `AND spi.PartID=` ⇒ **LỖI CÚ PHÁP**, không phải "0 dòng im lặng" như `PartID=''` ở #487.
//   ⇒ Cùng một khuôn lỗi, **hai hậu quả khác nhau chỉ vì có/không có nháy**. Port chặn 404 trước khi chạy.
// 🔴 **LEFT JOIN CHẾT** (giống #487): `left join Ser_Inv_StockInDetail sid` rồi `join Ser_Inv_StockIn si`
//   `on si.StockInID = **sid**.StockInID` ⇒ bản ghi không khớp dòng chi tiết phiếu nhập **bị loại im lặng**.
// ⚠️ Ba nhánh nối bằng `union all` (nhập · xuất · xuất) ⇒ **không khử trùng** (khác `union` ở #488).
// ⚠️ Nguồn **KHÔNG có ORDER BY** ở câu cuối ⇒ thứ tự thẻ kho không xác định; port sắp theo ngày + số chứng từ
//   và trả cờ `sourceHasNoOrderBy`.
// ⚠️ Mốc `spi.DateIn <= "@ToDate"` không kèm giờ ⇒ **mất trọn ngày cuối** (#415); port dùng 23:59:59 + đếm.
app.MapGet("/api/reports/part-stock-card", async (AppDbContext db, ITenantContext t,
    string? dealerCode, string? partCode, DateTime? fromDate, DateTime? toDate, string? scope) =>
{
    if (string.IsNullOrWhiteSpace(dealerCode)) return Results.BadRequest(new { error = "Cần dealerCode." });
    if (string.IsNullOrWhiteSpace(partCode)) return Results.BadRequest(new { error = "Cần partCode." });
    if (fromDate is null || toDate is null) return Results.BadRequest(new { error = "Cần fromDate và toDate." });
    var dealer = dealerCode!.Trim();
    var code = partCode!.Trim().ToUpperInvariant();

    var part = await db.ServiceParts.FirstOrDefaultAsync(p => p.OrgId == t.OrgId && p.PartCode == code);
    if (part is null)
        return Results.NotFound(new
        {
            partCode = code,
            error = "Ser_InvReportCardStockRpt: không tìm thấy phụ tùng.",
            sourceWouldEmitSyntaxError = true,
            note = "Nguồn bake @PartID KHÔNG có nháy ⇒ PartID rỗng làm câu SQL sai cú pháp (khác #487).",
        });

    var isWh = string.Equals(scope?.Trim(), "wh", StringComparison.OrdinalIgnoreCase);
    var floor = new DateTime(2017, 12, 31);
    var askedFrom = fromDate.Value.Date;
    var clamped = !isWh && askedFrom <= floor;
    var from = clamped ? floor : askedFrom;
    var toRawMidnight = toDate.Value.Date;
    var to = toDate.Value.Date.AddDays(1).AddSeconds(-1);
    var dateDK = from.AddDays(-1);          // mốc TỒN ĐẦU của nguồn

    var inst = await db.PartInstances.Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer
            && x.PartID == part.PartID && x.Status != "4" && x.Status != "5").ToListAsync();
    var lines = await db.PartStockInLines.Where(l => l.OrgId == t.OrgId).ToListAsync();
    var lineByKey = lines.Where(l => l.PartCode != null)
        .GroupBy(l => l.StockInId + "|" + l.PartCode).ToDictionary(g => g.Key, g => g.First());

    decimal Vat(PartInstance x) =>
        lineByKey.TryGetValue(x.StockInId + "|" + (x.PartCode ?? ""), out var l) ? l.VAT : 0m;
    bool HasDetail(PartInstance x) => lineByKey.ContainsKey(x.StockInId + "|" + (x.PartCode ?? ""));

    // TỒN ĐẦU: [1900-01-01, dateDK] — cận dưới là HẰNG của nguồn.
    var openIn = inst.Where(x => x.DateIn != null && x.DateIn.Value.Date <= dateDK).ToList();
    var openOut = inst.Where(x => x.DateOut != null && x.DateOut.Value.Date <= dateDK).ToList();
    var sld = openIn.Sum(x => x.Quantity) - openOut.Sum(x => x.Quantity);
    var tgd = openIn.Sum(x => (x.SIPrice ?? 0m) * x.Quantity + (x.SIPrice ?? 0m) * x.Quantity * 0.01m * Vat(x))
            - openOut.Sum(x => (x.SOPrice ?? 0m) * x.Quantity);

    // Dòng NHẬP trong kỳ (LEFT bị ép INNER ⇒ đếm phần bị loại).
    var inRows = inst.Where(x => x.DateIn != null && x.DateIn >= from && x.DateIn <= to).ToList();
    var lostByRawEndDate = inRows.Count(x => x.DateIn > toRawMidnight);
    var inKept = inRows.Where(HasDetail).ToList();
    var droppedByStockInDetailJoin = inRows.Count - inKept.Count;
    var rows = inKept
        .GroupBy(x => new { x.StockInId, x.StockInNo, x.LocationID, x.SIPrice, x.DateIn })
        .Select(g => new
        {
            PartID = part.PartID, RefID = g.Key.StockInId, RefNo = g.Key.StockInNo,
            RefDate = g.Key.DateIn, Remark = "Nhập kho", g.Key.LocationID,
            SLN = g.Sum(x => x.Quantity), SLX = 0m,
            TGN = g.Sum(x => (g.Key.SIPrice ?? 0m) * x.Quantity
                             + (g.Key.SIPrice ?? 0m) * x.Quantity * 0.01m * Vat(x)),
            TGX = 0m, Price = g.Key.SIPrice ?? 0m,
            RoNo = "", PlateNo = "",
        }).ToList<object>();

    // Dòng XUẤT trong kỳ (nguồn có hai nhánh union all cho xuất).
    var outRows = inst.Where(x => x.DateOut != null && x.DateOut >= from && x.DateOut <= to).ToList();
    rows.AddRange(outRows
        .GroupBy(x => new { x.StockOutId, x.StockOutNo, x.LocationID, x.SOPrice, x.DateOut })
        .Select(g => new
        {
            PartID = part.PartID, RefID = g.Key.StockOutId, RefNo = g.Key.StockOutNo,
            RefDate = g.Key.DateOut, Remark = "Xuất kho", g.Key.LocationID,
            SLN = 0m, SLX = g.Sum(x => x.Quantity),
            TGN = 0m, TGX = g.Sum(x => (g.Key.SOPrice ?? 0m) * x.Quantity),
            Price = g.Key.SOPrice ?? 0m, RoNo = "", PlateNo = "",
        }).ToList<object>());

    var ordered = rows.OrderBy(r => (DateTime?)r.GetType().GetProperty("RefDate")!.GetValue(r))
        .ThenBy(r => (string?)r.GetType().GetProperty("RefNo")!.GetValue(r)).ToList();

    return Results.Ok(new
    {
        dealerCode = dealer, partCode = code, scope = isWh ? "wh" : "main",
        askedFrom = askedFrom.ToString("yyyy-MM-dd"),
        effectiveFrom = from.ToString("yyyy-MM-dd"),
        clampedToFloor = clamped, floorDate = "2017-12-31",
        openingAsOf = dateDK.ToString("yyyy-MM-dd"),
        openingLowerBoundIsConstant = "1900-01-01",
        SLD = sld, TGD = tgd,
        count = ordered.Count, items = ordered,
        part = new { part.PartID, part.PartCode, VieName = part.PartName, part.Unit },
        droppedByStockInDetailJoin, lostByRawEndDate,
        leftJoinDeadInSource = true,
        unionAllNoDedup = true,
        sourceHasNoOrderBy = true,
        partIdBakedWithoutQuotes = true,
    });
}).RequireAuthorization();

// ===== 🔴 #499 NHẬP–XUẤT–TỒN PHỤ TÙNG — `Ser_InventoryReport_InOutBalance_New20191112` =====
// (`Inventory.Report.cs:713`) — trả nợ `scope` thứ hai trong ba nợ #496 khoanh vùng.
//
// ⚪🔴 **KIỂM TRA ÂM TÍNH QUAN TRỌNG — SUÝT VÁ NHẦM (#415)**:
//   SQL viết `AND spi.DateIn < "@ToDate"` — dấu **<** (nhỏ hơn hẳn), nhìn qua tưởng **mất trọn ngày cuối**.
//   Nhưng truy đến giá trị thật: `Replace(…, "@ToDate", **strToDateNext**)` với
//   `strToDateNext = Convert.ToDateTime(strToDate).AddDays(1)` ⇒ điều kiện là `< ToDate + 1 ngày`
//   ⇒ **BAO TRỌN ngày cuối**. Đây là cách viết ĐÚNG, ngược với đa số báo cáo khác trong cùng cây nguồn.
//   📌 Bài học lặp lại: **toán tử không nói lên gì nếu chưa truy tới giá trị được thay vào**.
// ⚠️ `@ToDateTime` (= ngày kế tiếp 00:00:00) **chỉ xuất hiện trong dòng đã COMMENT** (`GetAverageCost`)
//   ⇒ biến sống nhưng **không có tác dụng**; port không dùng.
//
// 🔴 **KẸP MỐC ĐẦU KỲ** (họ #496, ca thứ ba được port): `HTC_WareHouse = "2017-12-31"` chỉ có ở bản chính
//   (đếm 2 vs 0) ⇒ giữ `scope=main|wh`.
// 🔴 **GIÁ VỐN RẼ THEO THAM SỐ ĐẠI LÝ** — giống hệt #472/#473: `Mst_Param(MCC/MCC) = "FIFO"` thì tính theo
//   giá nhập, **`Else "0"`**, và nhánh `GetAverageCost` **đã bị comment** ở **cả ba** khối ⇒ đại lý không
//   đặt FIFO thì **cột tiền = 0 im lặng**, số lượng vẫn đúng.
// ⚠️ Tồn ĐẦU KỲ dựng qua macro với khoảng **["1900-01-01", strFromDate]** ⇒ mốc đầu là **chính FromDate**
//   (khác #498 lấy `FromDate − 1`). Hai báo cáo cùng họ nhưng **mốc đầu kỳ lệch nhau một ngày**.
app.MapGet("/api/reports/part-in-out-balance", async (AppDbContext db, ITenantContext t,
    string? dealerCode, DateTime? fromDate, DateTime? toDate, string? scope) =>
{
    if (string.IsNullOrWhiteSpace(dealerCode)) return Results.BadRequest(new { error = "Cần dealerCode." });
    if (fromDate is null || toDate is null) return Results.BadRequest(new { error = "Cần fromDate và toDate." });
    var dealer = dealerCode!.Trim();
    var isWh = string.Equals(scope?.Trim(), "wh", StringComparison.OrdinalIgnoreCase);
    var floor = new DateTime(2017, 12, 31);
    var askedFrom = fromDate.Value.Date;
    var clamped = !isWh && askedFrom <= floor;
    var from = clamped ? floor : askedFrom;
    var toNext = toDate.Value.Date.AddDays(1);      // nguồn: < ToDate+1 ⇒ BAO TRỌN ngày cuối

    var mcc = await db.MstParams.Where(p => p.OrgId == t.OrgId && p.DealerCode == dealer
            && p.ParamCode == "MCC" && p.ParamType == "MCC")
        .Select(p => p.ParamValue).FirstOrDefaultAsync();
    var isFifo = string.Equals(mcc, "FIFO", StringComparison.OrdinalIgnoreCase);

    var inst = await db.PartInstances.Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer
            && x.Status != "4" && x.Status != "5").ToListAsync();
    var lines = await db.PartStockInLines.Where(l => l.OrgId == t.OrgId).ToListAsync();
    var lineByKey = lines.Where(l => l.PartCode != null)
        .GroupBy(l => l.StockInId + "|" + l.PartCode).ToDictionary(g => g.Key, g => g.First());
    decimal Val(PartInstance x, decimal? price)
    {
        if (!isFifo) return 0m;                     // nhánh Else "0" của nguồn
        var p = price ?? 0m;
        var vat = lineByKey.TryGetValue(x.StockInId + "|" + (x.PartCode ?? ""), out var l) ? l.VAT : 0m;
        return p * x.Quantity + p * x.Quantity * 0.01m * vat;
    }

    // ĐẦU KỲ: ["1900-01-01", from] — đúng khoảng macro của nguồn.
    var openIn = inst.Where(x => x.DateIn != null && x.DateIn.Value.Date <= from).ToList();
    var openOut = inst.Where(x => x.DateOut != null && x.DateOut.Value.Date <= from).ToList();
    // TRONG KỲ: [from, toNext)
    var inRows = inst.Where(x => x.DateIn != null && x.DateIn >= from && x.DateIn < toNext).ToList();
    var outRows = inst.Where(x => x.DateOut != null && x.DateOut >= from && x.DateOut < toNext).ToList();

    string Key(PartInstance x) => (x.PartID ?? "") + "|" + (x.LocationID ?? "");
    var keys = openIn.Concat(openOut).Concat(inRows).Concat(outRows).Select(Key).Distinct().ToList();
    var items = keys.Select(k =>
    {
        var pid = k.Split((char)124)[0]; var loc = k.Split((char)124)[1];
        decimal SumQ(List<PartInstance> src) => src.Where(x => Key(x) == k).Sum(x => x.Quantity);
        decimal SumV(List<PartInstance> src, bool useIn) =>
            src.Where(x => Key(x) == k).Sum(x => Val(x, useIn ? x.SIPrice : x.SOPrice));
        var sld = SumQ(openIn) - SumQ(openOut);
        var tgd = SumV(openIn, true) - SumV(openOut, false);
        var sln = SumQ(inRows); var tgn = SumV(inRows, true);
        var slx = SumQ(outRows); var tgx = SumV(outRows, false);
        return new
        {
            PartID = pid, LocationID = loc,
            SLD = sld, TGD = tgd, SLN = sln, TGN = tgn, SLX = slx, TGX = tgx,
            SLC = sld + sln - slx, TGC = tgd + tgn - tgx,
        };
    }).OrderBy(x => x.PartID).ThenBy(x => x.LocationID).ToList();

    return Results.Ok(new
    {
        dealerCode = dealer, scope = isWh ? "wh" : "main",
        askedFrom = askedFrom.ToString("yyyy-MM-dd"),
        effectiveFrom = from.ToString("yyyy-MM-dd"),
        clampedToFloor = clamped, floorDate = "2017-12-31",
        toExclusiveBound = toNext.ToString("yyyy-MM-dd"),
        lastDayIncluded = true,                    // vì nguồn thay @ToDate = ToDate+1
        openingAsOf = from.ToString("yyyy-MM-dd"),
        openingLowerBoundIsConstant = "1900-01-01",
        costMethod = mcc, isFifo, costMethodNotFifoGivesZero = !isFifo,
        averageCostBranchCommentedOut = true,
        count = items.Count, items,
    });
}).RequireAuthorization();

// ===== 🔴 #500 PHỤ TÙNG CHẠM TỒN TỐI THIỂU — `Ser_InvReportPartMinQuantity_New20181027` =====
// (`Inventory.Report.cs:6395`) — **trả nợ cuối** trong ba nợ `scope` mà #496 khoanh vùng.
// ⚠️ #421/#422 đã mô tả rất kỹ màn này và **hứa** "MiniHTC thêm `scope`", nhưng grep lại thì **chưa hề có
//   endpoint nào** — chỉ có ghi chú. Đây đúng là loại nợ dễ trôi: **mô tả xong tưởng là đã làm**.
//   📌 Bài học ghi vào sổ: ghi chú "MiniHTC sẽ thêm X" phải kèm ngay endpoint, nếu không thì ghi là NỢ.
//
// 🔴 **KẸP MỐC** (họ #496, ca thứ ba và là ca cuối được port): `HTC_WareHouse = "2017-12-31"` kẹp
//   **`strToDate`** (khác #498/#499 kẹp `FromDate`) ⇒ xin mốc ≤ 31-12-2017 thì bản chính kéo về 2017-12-31;
//   bản `_WH` **không kẹp** (đếm 2 vs 0). Giữ `scope=main|wh` + luôn trả `effectiveDate`.
// ⚠️ Tồn tính qua macro với khoảng **["1900-01-01", strToDate]** ⇒ đây là **tồn LUỸ KẾ tới mốc**, không
//   phải tồn trong kỳ — báo cáo này chỉ có **một** mốc ngày, không có FromDate.
//
// 🔴 **HAI `left join` ĐỀU CHẾT** (luật #414): `left join ser_mst_part p` rồi WHERE có
//   `and p.IsActive = "1"` **và** `and p.DealerCode = "@DealerCode"` ⇒ ép thành INNER.
//   ⇒ Dòng tồn của phụ tùng **đã ngừng theo dõi** hoặc **thuộc đại lý khác** bị loại — kể cả khi vẫn còn tồn.
//   `left join ser_mst_location sml` thì WHERE không đụng ⇒ **còn sống**, nhưng cột của nó **không được
//   dùng ở đâu cả** (không có trong SELECT lẫn GROUP BY) ⇒ phép nối **thừa**.
// 🔴 **ĐIỀU KIỆN LÕI BỊ COMMENT RỒI ĐẶT LẠI Ở CÂU NGOÀI**: trong câu gộp có `--and p.Minquantity >= SLC`
//   (đã comment), còn câu cuối là `select * from #tbl_Final where Minquantity >= SLC`.
//   ⇒ Port theo **dòng ACTIVE**: lọc ở BƯỚC CUỐI, sau khi đã `sum` theo phụ tùng.
//   ⚠️ Ngữ nghĩa: `Minquantity >= SLC` tức **tồn hiện tại KHÔNG VƯỢT mức tối thiểu** (chạm hoặc dưới).
// ⚠️ `sum(Isnull(op.SLC,0)) SLC` — cộng tồn **qua mọi vị trí kho** rồi mới so với mức tối thiểu
//   ⇒ phụ tùng để rải nhiều vị trí vẫn được coi là đủ nếu TỔNG đủ.
// ⚠️ `'1' as Factor` — cột **hằng viết cứng**, không phải dữ liệu (cùng lệ #487 với `0 as SLX`).
// ⚠️ `order by p.PartCode` nằm ở câu `INTO #tbl_Final` ⇒ **vô nghĩa** (lệ #415); câu cuối **không** có
//   ORDER BY ⇒ thứ tự thật **không xác định**. Port sắp theo `PartCode` + cờ `sourceHasNoOrderBy`.
app.MapGet("/api/reports/part-min-quantity", async (AppDbContext db, ITenantContext t,
    string? dealerCode, DateTime? toDate, string? scope) =>
{
    if (string.IsNullOrWhiteSpace(dealerCode)) return Results.BadRequest(new { error = "Cần dealerCode." });
    if (toDate is null) return Results.BadRequest(new { error = "Cần toDate." });
    var dealer = dealerCode!.Trim();
    var isWh = string.Equals(scope?.Trim(), "wh", StringComparison.OrdinalIgnoreCase);
    var floor = new DateTime(2017, 12, 31);
    var asked = toDate.Value.Date;
    var clamped = !isWh && asked <= floor;
    var effective = clamped ? floor : asked;

    // Tồn LUỸ KẾ tới mốc: ["1900-01-01", effective] — đúng khoảng macro của nguồn.
    var inst = await db.PartInstances.Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer
            && x.Status != "4" && x.Status != "5").ToListAsync();
    var qtyIn = inst.Where(x => x.DateIn != null && x.DateIn.Value.Date <= effective)
        .GroupBy(x => x.PartID ?? "").ToDictionary(g => g.Key, g => g.Sum(x => x.Quantity));
    var qtyOut = inst.Where(x => x.DateOut != null && x.DateOut.Value.Date <= effective)
        .GroupBy(x => x.PartID ?? "").ToDictionary(g => g.Key, g => g.Sum(x => x.Quantity));

    // Hai left join bị ép INNER: phụ tùng phải còn hiệu lực VÀ đúng đại lý.
    var parts = await db.ServiceParts.Where(p => p.OrgId == t.OrgId
            && p.FlagActive == "1" && p.DealerCode == dealer).ToListAsync();
    var partById = parts.Where(p => p.PartID != null).GroupBy(p => p.PartID!)
        .ToDictionary(g => g.Key, g => g.First());

    var keys = qtyIn.Keys.Concat(qtyOut.Keys).Distinct().ToList();
    var beforeInner = keys.Count;
    var rows = keys.Where(k => partById.ContainsKey(k)).Select(k =>
    {
        var p = partById[k];
        // sum qua MỌI vị trí kho rồi mới so mức tối thiểu — đúng nguồn.
        var slc = (qtyIn.TryGetValue(k, out var i) ? i : 0m) - (qtyOut.TryGetValue(k, out var o) ? o : 0m);
        return new
        {
            PartID = k, p.PartCode, VieName = p.PartName, p.Unit,
            SLC = slc, p.MinQuantity, p.Price, p.EngName, p.Cost, p.VAT, p.Model, p.Note, p.Quantity,
            Factor = "1",              // cột hằng viết cứng ở nguồn
        };
    }).ToList();
    var droppedByPartMasterJoin = beforeInner - rows.Count;

    // Dòng ACTIVE: lọc ở BƯỚC CUỐI (điều kiện trong câu gộp đã bị comment).
    var items = rows.Where(x => x.MinQuantity >= x.SLC)
        .OrderBy(x => x.PartCode).ToList();

    return Results.Ok(new
    {
        dealerCode = dealer, scope = isWh ? "wh" : "main",
        askedDate = asked.ToString("yyyy-MM-dd"),
        effectiveDate = effective.ToString("yyyy-MM-dd"),
        clampedToFloor = clamped, floorDate = "2017-12-31",
        stockIsCumulativeToDate = true,
        lowerBoundIsConstant = "1900-01-01",
        count = items.Count, items,
        droppedByPartMasterJoin,
        leftJoinDeadInSource = true,
        locationJoinUnused = true,
        thresholdAppliedAtFinalSelect = true,
        stockSummedAcrossLocations = true,
        factorIsHardcoded = true,
        sourceHasNoOrderBy = true,
    });
}).RequireAuthorization();

// ===== 🔴 #506 TỔNG HỢP SỐ PHIẾU TIẾP NHẬN THEO KỲ (máy tính bảng) =====
// Nguồn: `Tab/BizCarSv.Tab.Report.cs:26 Rpt_Ser_ReceptionF_SumQtyRecepForTab` → thân thật
//   `Rpt_Ser_ReceptionF_SumQtyRecepX` (`:304`). Trả nợ #504.
//
// 🔴 **THIẾU HẲN NHÁNH `YEAR`**: khối dựng "rổ" thời gian chỉ có ba nhánh —
//   `Hour` → `zzB_Build_HourInDay_zzE` · `DAY` → `zzB_Build_Day_zzE` · `Month` → `zzB_Build_Month_zzE`.
//   Hằng `TConst.ReportType.Year = "YEAR"` **có tồn tại** nhưng **không có nhánh nào bắt** ⇒ chọn NĂM thì
//   bảng rổ **rỗng**, và câu cuối lấy `from #input_tbl_ReportType` ⇒ **báo cáo rỗng, KHÔNG báo lỗi**.
//   ⇒ Đây là "0 im lặng" thứ ba trong cụm này (sau #472 giá vốn, #504 màn kho luôn chạy nhánh giờ).
//   Port **chặn thẳng** YEAR + nêu cờ `yearBranchMissingInSource` — lệch CỐ Ý, không tái hiện im lặng.
// ⚠️ Nhánh `Hour` chỉ dùng **ngày FROM** (`StandardizeDate(strReportDTimeFrom)`) ⇒ chọn khoảng nhiều ngày
//   vẫn chỉ dựng 24 rổ giờ **của ngày đầu**; các ngày sau **không có rổ nào** để rơi vào.
//
// 🔴 `inner join #input_tbl_ReportType f on (1=1)` — **TÍCH DESCARTES trá hình**: mỗi phiếu nhân với **mọi
//   rổ**, rồi lọc bằng `CreatedDateTime` trong [`DateTimeStart`, `DateTimeEnd`]. Đúng ý đồ, nhưng nếu hai rổ
//   **chồng lấn** thì **một phiếu bị đếm ở cả hai** — bảng rổ do code dựng nên hiện không chồng, nhưng đây là
//   phụ thuộc ngầm; trả cờ `bucketsMustNotOverlap`.
// ⚪ `left join #tbl_Return` ở câu cuối đi từ **bảng rổ** ⇒ rổ không có phiếu **vẫn ra dòng với `Qty = 0`**
//   (đủ 24 giờ / đủ ngày). Kiểm tra âm tính — LEFT này **cố ý và còn sống**.
// ⚠️ So mốc bằng **CHUỖI**: `convert(nvarchar(20), srf.CreatedDateTime, 20) >= f.DateTimeStart`.
//   Định dạng 20 là `yyyy-MM-dd HH:mm:ss` nên so chuỗi **tương đương so ngày** (kiểm tra âm tính),
//   nhưng mất index. Guard `strReportDateFrom.CompareTo(strReportDateTo) > 0` cũng **so CHUỖI**.
// ⚠️ Cột `DealerCode` bị **comment trong GROUP BY** rồi gán lại bằng `'@strDealerCode'` (bake) ở câu cuối
//   ⇒ số liệu **gộp qua mọi đại lý** khớp bộ lọc, rồi dán nhãn mã đại lý đầu vào.
app.MapGet("/api/reports/reception-qty-by-period", async (AppDbContext db, ITenantContext t,
    string? dealerCode, string? reportType, DateTime? fromDate, DateTime? toDate) =>
{
    if (string.IsNullOrWhiteSpace(dealerCode))
        return Results.BadRequest(new { error = "Rpt_Ser_ReceptionF_SumQtyRecep_InvalidDealerCode" });
    if (string.IsNullOrWhiteSpace(reportType))
        return Results.BadRequest(new { error = "Rpt_Ser_ReceptionF_SumQtyRecep_InvalidReportType" });
    if (fromDate is null || toDate is null) return Results.BadRequest(new { error = "Cần fromDate và toDate." });
    if (fromDate.Value.Date > toDate.Value.Date)
        return Results.BadRequest(new { error = "Rpt_Ser_ReceptionF_SumQtyRecep_DateFromAfterDTimeTo" });

    var dealer = dealerCode!.Trim();
    var kind = reportType!.Trim().ToUpperInvariant();      // nguồn so KHÔNG phân biệt hoa thường
    if (kind == "YEAR")
        return Results.BadRequest(new
        {
            error = "reportType = YEAR không được nguồn dựng rổ.",
            yearBranchMissingInSource = true,
            note = "Hằng ReportType.Year tồn tại nhưng không có nhánh nào bắt ⇒ nguồn trả RỖNG mà không báo lỗi.",
        });
    if (kind != "HOUR" && kind != "DAY" && kind != "MONTH")
        return Results.BadRequest(new { error = "reportType chỉ nhận HOUR, DAY hoặc MONTH." });

    var from = fromDate.Value.Date;
    var to = toDate.Value.Date.AddDays(1).AddSeconds(-1);

    // Dựng "rổ" thời gian đúng ba nhánh của nguồn.
    var buckets = new List<(string MixCode, string MixName, DateTime Start, DateTime End)>();
    if (kind == "HOUR")
    {
        // ⚠️ Nguồn chỉ dùng NGÀY FROM — giữ đúng.
        for (var h = 0; h < 24; h++)
        {
            var st = from.AddHours(h);
            buckets.Add((h.ToString("00"), h.ToString("00") + " giờ", st, st.AddHours(1).AddSeconds(-1)));
        }
    }
    else if (kind == "DAY")
    {
        for (var d = from; d <= toDate.Value.Date; d = d.AddDays(1))
            buckets.Add((d.ToString("yyyy-MM-dd"), d.ToString("dd/MM/yyyy"), d, d.AddDays(1).AddSeconds(-1)));
    }
    else
    {
        var m = new DateTime(from.Year, from.Month, 1);
        var mEnd = new DateTime(toDate.Value.Year, toDate.Value.Month, 1);
        for (; m <= mEnd; m = m.AddMonths(1))
            buckets.Add((m.ToString("yyyy-MM"), m.ToString("MM/yyyy"), m, m.AddMonths(1).AddSeconds(-1)));
    }

    var recs = await db.Receptions.Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer
            && x.CreatedAt >= from && x.CreatedAt <= to).ToListAsync();

    // Tích Descartes có kiểm soát: mỗi phiếu rơi vào MỌI rổ chứa nó (đúng nguồn).
    var items = buckets.Select(b => new
    {
        b.MixCode, DealerCode = dealer, ReportType = kind, b.MixName,
        DateTimeStart = b.Start, DateTimeEnd = b.End,
        Qty = (decimal)recs.Count(r => r.CreatedAt >= b.Start && r.CreatedAt <= b.End),
    }).ToList();

    // Một phiếu rơi vào >1 rổ ⇒ rổ đang chồng lấn (nguồn không kiểm).
    var doubleCounted = recs.Count(r => buckets.Count(b => r.CreatedAt >= b.Start && r.CreatedAt <= b.End) > 1);

    return Results.Ok(new
    {
        dealerCode = dealer, reportType = kind,
        from = from.ToString("yyyy-MM-dd"), to = toDate.Value.Date.ToString("yyyy-MM-dd"),
        bucketCount = buckets.Count, receptionCount = recs.Count,
        count = items.Count, items,
        emptyBucketsKeptWithZero = true,
        bucketsMustNotOverlap = true, doubleCounted,
        hourBranchUsesFromDateOnly = kind == "HOUR",
        yearBranchMissingInSource = true,
        dateComparedAsStringInSource = true,
        dealerGroupedOutThenRelabelled = true,
    });
}).RequireAuthorization();

// ===== 🔴 #507 DOANH THU LỆNH SỬA CHỮA THEO KỲ — NỬA CÒN LẠI CỦA CỤM #504/#506 =====
// Nguồn: `Tab/BizCarSv.Tab.Report.cs:1489 Rpt_Ser_RO_RevenueByReportTypeX` — nhánh `else` của
//   `Rpt_Ser_ReceptionF_SumQtyRecepForTab` (DAY/MONTH/YEAR), trong khi HOUR đi nhánh #506.
//
// 🔴 **CỜ `strRevenue` KHÔNG ĐỔI SỐ LIỆU — CHỈ ĐỔI TÊN BẢNG**:
//     `if (StringEqualIgnoreCase(strRevenue, TConst.Flag.Active)) Tables[0].TableName = "Rpt_Ser_RO_RevenueByReportType";`
//     `else Tables[0].TableName = "Rpt_Ser_ReceptionF_SumQtyRecep";`
//   Câu SQL **giống hệt nhau** ở cả hai nhánh ⇒ gọi với `Revenue = "0"` vẫn nhận **đủ cột tiền**
//   (`ServiceAmount`, `PartAmount`, `RevenueAvg`), chỉ mang nhãn bảng "số phiếu tiếp nhận".
//   ⇒ Đây **không** là bộ lọc quyền/dữ liệu như tên gọi gợi ý; port trả cờ `revenueFlagOnlyRenamesTable`.
//   ⚠️ Và `Rpt_Ser_ReceptionF_SumQtyRecepForTab` luôn truyền `TConst.Flag.No` ⇒ ở màn máy tính bảng,
//     nhánh DAY/MONTH **luôn** đội tên "SumQtyRecep" dù dữ liệu là doanh thu đầy đủ.
//
// 🔴 `Round((IsNull(f.ServiceAmount,0.0) + IsNull(f.PartAmount,0.0)) / f.QtyRO, 2) RevenueAvg` —
//   `IsNull` **chỉ bọc tử số**, **mẫu số `f.QtyRO` để trần**. Câu cuối là `left join` từ bảng rổ, nên
//   rổ **không có lệnh nào** ⇒ `QtyRO = NULL` ⇒ phép chia ra **NULL**, không phải 0, và **không lỗi**.
//   ⇒ Cùng một dòng vừa có `Qty = 0` (đã `IsNull`) vừa có `RevenueAvg = NULL` — hai quy ước rỗng
//     lẫn trong MỘT dòng kết quả. Port giữ đúng: `RevenueAvg = null` cho rổ rỗng, kèm cờ.
//
// ⚠️ Mốc thời gian của báo cáo này là `sr.ActualDeliveryDate` (**giao xe thực tế**), KHÔNG phải
//   `CreatedDateTime` như #506 ⇒ **hai nửa cùng một màn đếm theo hai mốc khác nhau**: đổi kiểu báo cáo
//   từ GIỜ sang NGÀY là đổi luôn ý nghĩa trục thời gian. Cờ `timeAxisDiffersFromHourBranch`.
//   Lệnh **chưa giao** (`ActualDeliveryDate = NULL`) rơi khỏi mọi rổ — đúng nguồn, không phải lỗi.
// ⚠️ Vẫn `inner join #input_tbl_ReportType f on (1=1)` (tích Descartes trá hình) và vẫn **thiếu nhánh
//   YEAR** y như #506 ⇒ dùng chung guard, chặn thẳng YEAR.
// ⚠️ `count(*) Qty` và `count(*) QtyRO` là **hai cột trùng hệt nhau** trong `#tbl_Return` — không phải
//   "số lệnh" vs "số xe"; giữ nguyên để khớp hình dạng kết quả.
app.MapGet("/api/reports/ro-revenue-by-period", async (AppDbContext db, ITenantContext t,
    string? dealerCode, string? reportType, DateTime? fromDate, DateTime? toDate, string? revenue) =>
{
    if (string.IsNullOrWhiteSpace(dealerCode))
        return Results.BadRequest(new { error = "Rpt_Ser_RO_RevenueByReportType_InvalidDealerCode" });
    if (string.IsNullOrWhiteSpace(reportType))
        return Results.BadRequest(new { error = "Rpt_Ser_RO_RevenueByReportType_InvalidReportType" });
    if (fromDate is null || toDate is null) return Results.BadRequest(new { error = "Cần fromDate và toDate." });
    if (fromDate.Value.Date > toDate.Value.Date)
        return Results.BadRequest(new { error = "Rpt_Ser_RO_RevenueByReportType_DateFromAfterDTimeTo" });

    var dealer = dealerCode!.Trim();
    var kind = reportType!.Trim().ToUpperInvariant();
    if (kind == "YEAR")
        return Results.BadRequest(new { error = "reportType = YEAR không được nguồn dựng rổ.",
            yearBranchMissingInSource = true });
    if (kind != "HOUR" && kind != "DAY" && kind != "MONTH")
        return Results.BadRequest(new { error = "reportType chỉ nhận HOUR, DAY hoặc MONTH." });

    var from = fromDate.Value.Date;
    var to = toDate.Value.Date.AddDays(1).AddSeconds(-1);
    var buckets = new List<(string MixCode, string MixName, DateTime Start, DateTime End)>();
    if (kind == "HOUR")
        for (var h = 0; h < 24; h++)
        {
            var st = from.AddHours(h);
            buckets.Add((h.ToString("00"), h.ToString("00") + " giờ", st, st.AddHours(1).AddSeconds(-1)));
        }
    else if (kind == "DAY")
        for (var d = from; d <= toDate.Value.Date; d = d.AddDays(1))
            buckets.Add((d.ToString("yyyy-MM-dd"), d.ToString("dd/MM/yyyy"), d, d.AddDays(1).AddSeconds(-1)));
    else
    {
        var m = new DateTime(from.Year, from.Month, 1);
        var mEnd = new DateTime(toDate.Value.Year, toDate.Value.Month, 1);
        for (; m <= mEnd; m = m.AddMonths(1))
            buckets.Add((m.ToString("yyyy-MM"), m.ToString("MM/yyyy"), m, m.AddMonths(1).AddSeconds(-1)));
    }

    // Lọc theo NGÀY GIAO XE THỰC TẾ — khác mốc của nhánh GIỜ (#506).
    var ros = await db.RepairOrders.Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer
            && x.ActualDeliveryDate != null && x.ActualDeliveryDate >= from && x.ActualDeliveryDate <= to)
        .Select(x => new { x.Id, x.ActualDeliveryDate }).ToListAsync();
    var roIds = ros.Select(x => x.Id).ToList();

    var svc = await db.RoServiceItems.Where(i => i.OrgId == t.OrgId && roIds.Contains(i.RoId))
        .GroupBy(i => i.RoId)
        .Select(g => new { RoId = g.Key, Amt = g.Sum(i => i.Factor * i.Price * (1m + i.Vat * 0.01m)) })
        .ToDictionaryAsync(x => x.RoId, x => x.Amt);
    var prt = await db.RoPartItems.Where(i => i.OrgId == t.OrgId && roIds.Contains(i.RoId))
        .GroupBy(i => i.RoId)
        .Select(g => new { RoId = g.Key, Amt = g.Sum(i => i.Factor * i.NeedQty * i.UnitPrice * (1m + i.Vat * 0.01m)) })
        .ToDictionaryAsync(x => x.RoId, x => x.Amt);

    var items = buckets.Select(b =>
    {
        var inBucket = ros.Where(r => r.ActualDeliveryDate >= b.Start && r.ActualDeliveryDate <= b.End).ToList();
        decimal? qtyRO = inBucket.Count == 0 ? null : inBucket.Count;   // rổ rỗng ⇒ NULL (mẫu số để trần)
        var sAmt = inBucket.Sum(r => svc.TryGetValue(r.Id, out var v) ? v : 0m);
        var pAmt = inBucket.Sum(r => prt.TryGetValue(r.Id, out var v) ? v : 0m);
        return new
        {
            b.MixCode, DealerCode = dealer, ReportType = kind, b.MixName,
            DateTimeStart = b.Start, DateTimeEnd = b.End,
            Qty = (decimal)inBucket.Count, ServiceAmount = sAmt, PartAmount = pAmt,
            RevenueAvg = qtyRO is null ? (decimal?)null : Math.Round((sAmt + pAmt) / qtyRO.Value, 2),
        };
    }).ToList();

    var isRevenue = string.Equals((revenue ?? "").Trim(), "1", StringComparison.OrdinalIgnoreCase);
    return Results.Ok(new
    {
        dealerCode = dealer, reportType = kind,
        from = from.ToString("yyyy-MM-dd"), to = toDate.Value.Date.ToString("yyyy-MM-dd"),
        tableName = isRevenue ? "Rpt_Ser_RO_RevenueByReportType" : "Rpt_Ser_ReceptionF_SumQtyRecep",
        count = items.Count, roCount = ros.Count, items,
        revenueFlagOnlyRenamesTable = true,
        revenueAvgNullOnEmptyBucket = items.Count(x => x.RevenueAvg is null),
        timeAxisDiffersFromHourBranch = "ActualDeliveryDate (giao xe) vs CreatedDateTime (#506)",
        undeliveredRosExcluded = true,
        yearBranchMissingInSource = true,
    });
}).RequireAuthorization();

// ===== 🔴🔴 #508 BÁO CÁO ĐỀ NGHỊ BẢO HÀNH GỬI HÃNG (HTMV) — VÀ MỘT `inner join` LÀM RƠI DÒNG =====
// Nguồn: `BizCarSv.WarrantyReport.cs:21119 Ser_ROWarrantyReportHTMV_Get` (+ hai bản ngày
//   `_New20191108` :21611 · `_New20230417` :22112). Trả nợ #497 phần **đọc báo cáo**.
//
// 🔴 **KHỐI LÀM GIÀU TỪ DMS SALES LÀM RƠI DÒNG NGAY Ở BƯỚC ĐỌC** (luật #410, ca nặng nhất tới nay):
//   Sau khi lấy xong dữ liệu, hàm gom danh sách VIN rồi gọi WS ngoài
//   `WSDMSSale.WSHTC64.CarVINGetList_Sales(...)`, lọc `dv.RowFilter = "StoreDate > '2017-04-01'"`,
//   rồi **`DataTableUtils.Join(c_strJoinType_InnerJoin, …)`** trên `FrameNo = VIN`.
//   ⇒ Xe **không có trong DMS Sales**, hoặc **bán/nhập kho trước 01-04-2017**, thì **dòng đề nghị bảo hành
//     BIẾN MẤT khỏi báo cáo** — không cảnh báo, không đếm. Người dùng chỉ thấy "ít phiếu hơn mình nhớ".
//   ⚠️ `'2017-04-01'` là **mốc gõ cứng trong C#**, họ hàng với `HTC_WareHouse = "2017-12-31"` (#472):
//     mốc thời gian nghiệp vụ nằm trong code, không nằm trong tham số cũng không nằm trong bảng cấu hình.
//   ⚠️ Cả **ba** bản (chính, `_New20191108`, `_New20230417`) đều dùng **cùng** kiểu join và **cùng** mốc
//     ⇒ không phải lỗi của một bản cũ sót lại; đây là hành vi hiện hành của cả họ hàm.
//   ⚠️ `dv.ToTable(true)` = **distinct** trên bảng đã lọc ⇒ một VIN nhiều dòng bán chỉ còn một.
// 🔴 Khối này bọc trong `try/catch` mà `catch` chỉ gọi `CProcessException.Process(ref mdsFinal, …)`
//   rồi **chảy tiếp** xuống `MoveDataTable` + `CommitSafety` ⇒ WS DMS Sales hỏng thì báo cáo **vẫn trả về**,
//   chỉ khác là **không có cột `StoreDate`** và không bị lọc. ⇒ **Cùng một yêu cầu, hai hình dạng kết quả
//   và hai tập dòng khác nhau, tuỳ hệ ngoài đang sống hay chết.** Cờ `enrichmentFailureChangesRowSet`.
//
// ⚠️ Tiền: `#tbl_amount` ghép hai nhánh bằng `full outer join` rồi `Isnull(rsv.ROWID, rsp.ROWID)` —
//   phiếu **chỉ có phụ tùng** hoặc **chỉ có dịch vụ** vẫn ra dòng (kiểm tra âm tính: `full outer` ở đây
//   là **cố ý và đúng**, khác với các ca `left join` chết ở #414).
// ⚠️ Công thức VAT viết dạng `case when VAT is null or VAT = 0 then F*P else F*P*(1+VAT/100) end`,
//   và **ngay cạnh có comment `--F*P*(1+1/VAT)`** — công thức SAI để lại trong chú thích.
//   Port theo **dòng ĐANG CHẠY**, không theo dòng comment (luật port ACTIVE).
// ⚠️ `(select dbo.ROWarrantyGetHTCWRID(srr.ROWID)) AS HTCROWNo` — hàm vô hướng SQL **chưa có** trong
//   MiniHTC (nợ #502) ⇒ endpoint này trả `HTCROWNo = null` kèm cờ, **không bịa số**.
// 📌 Tác dụng phụ đẩy HMC (#497) **chỉ có ở bản chính**; bản port này là **ĐỌC THUẦN** — nêu cờ
//   `hmcSideEffectNotPorted` để không ai tưởng gọi endpoint này là đã đồng bộ sang hãng.
app.MapGet("/api/reports/ro-warranty-htmv", async (AppDbContext db, ITenantContext t,
    string? dealerCode, string? status, string? frameNo, string? plateNo,
    DateTime? fromDate, DateTime? toDate) =>
{
    var qy = db.ServiceWarrantyClaims.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealerCode)) qy = qy.Where(x => x.DealerCode == dealerCode!.Trim());
    if (!string.IsNullOrWhiteSpace(status)) qy = qy.Where(x => x.Status == status!.Trim());
    if (!string.IsNullOrWhiteSpace(frameNo)) qy = qy.Where(x => x.Vin == frameNo!.Trim());
    if (!string.IsNullOrWhiteSpace(plateNo)) qy = qy.Where(x => x.PlateNo == plateNo!.Trim());
    if (fromDate is not null) qy = qy.Where(x => x.CreatedAt >= fromDate.Value.Date);
    if (toDate is not null) qy = qy.Where(x => x.CreatedAt <= toDate.Value.Date.AddDays(1).AddSeconds(-1));

    var heads = await qy.OrderByDescending(x => x.Id).Take(500).ToListAsync();
    var ids = heads.Select(x => x.Id).ToList();

    var svc = await db.WarrantyClaimServiceItems.Where(i => i.OrgId == t.OrgId && ids.Contains(i.ClaimId))
        .ToListAsync();

    // ===== 🔴 #510 TRẢ NỢ #502 — SỐ ĐỀ NGHỊ BẢO HÀNH PHÍA HTC (`HTCROWNo`) =====
    // Nguồn SQL viết `(select dbo.ROWarrantyGetHTCWRID(srr.ROWID))` — hàm vô hướng **chỉ có trong DB**,
    //   grep cả **hai máy** đều **không có** `CREATE FUNCTION` (chỉ toàn chỗ gọi). Nhưng nguồn **CÓ**
    //   một bản dựng lại bằng SQL thuần: macro `SqlTemplate_Ser_ROWarrantyReport.
    //   zzB_tbl_Ser_ROWarrantyReport_HTCROWNo_zzE("ACCE")` (`BizCarSv.zSqlTemplate.Inv.cs:512`),
    //   dùng ở 4 chỗ trong `WarrantyReport.cs`/`WH.cs`. ⇒ Port theo **macro** (đọc được), không đoán hàm DB.
    // 📐 Công thức: `DealerCode + '-' + right(Year,2) + pad2(Month) + '-' + pad3(Idx)`
    //   với `Idx = Row_Number() over (partition by DealerCode, MonthROW, YearROW order by ROWID asc)`.
    // 🔴 **SỐ NÀY KHÔNG ĐƯỢC LƯU — TÍNH LẠI MỖI LẦN ĐỌC**, và chỉ đánh số các phiếu có
    //   `WarrantyStatus = 'ACCE'` (hằng **literal "ACCE"** truyền vào ở cả 4 chỗ gọi).
    //   ⇒ Một phiếu cũ trong cùng đại lý/tháng **đổi trạng thái** là **mọi phiếu sau nó ĐỔI SỐ**.
    //     Số "định danh" mà **không ổn định theo thời gian** — in ra giấy hôm nay, tra lại tháng sau ra số khác.
    // 🔴 `REPLICATE('0', 3 - LEN(HTCROIdx))`: tới phiếu thứ **1000** của một đại lý trong một tháng,
    //   `3 - LEN` = **âm** ⇒ `REPLICATE` trả **NULL** ⇒ phép nối chuỗi cho **HTCROWNo = NULL** (không lỗi).
    //   Port **không tái hiện NULL**: vượt 999 thì giữ nguyên số không đệm, và trả cờ đếm.
    // ⚠️ Phiếu **không phải ACCE** không có trong bảng đánh số ⇒ `left join` cuối cho `HTCROWNo = null`.
    //   Đây là **đúng nguồn**, không phải thiếu dữ liệu.
    // ⚠️ Macro đọc `#Ser_ROWarrantyReport t with(nolock)` — đọc bẩn, và viết `with(nolock)` **thẳng**
    //   thay vì dấu `--//[mylock]` như quy ước phần còn lại của file.
    const string kHtcRowNoStatus = "ACCE";      // hằng literal của nguồn, chép nguyên văn
    var acce = await db.ServiceWarrantyClaims
        .Where(x => x.OrgId == t.OrgId && x.Status == kHtcRowNoStatus && x.DealerCode != null)
        .Select(x => new { x.Id, x.DealerCode, x.CreatedAt }).ToListAsync();
    var htcRowNo = new Dictionary<long, string>();
    var overflow999 = 0;
    foreach (var g in acce.GroupBy(x => new { x.DealerCode, x.CreatedAt.Year, x.CreatedAt.Month }))
    {
        var idx = 0;
        foreach (var r in g.OrderBy(x => x.Id))
        {
            idx++;
            if (idx > 999) overflow999++;                    // nguồn cho NULL ở đây; ta giữ số
            htcRowNo[r.Id] = $"{g.Key.DealerCode}-{g.Key.Year % 100:00}{g.Key.Month:00}-{idx:000}";
        }
    }
    var prt = await db.WarrantyClaimPartItems.Where(i => i.OrgId == t.OrgId && ids.Contains(i.ClaimId))
        .ToListAsync();
    // VAT: dòng ĐANG CHẠY của nguồn (comment `(1+1/VAT)` là công thức sai, không port).
    decimal AmtS(WarrantyClaimServiceItem i) => i.VAT == 0m ? i.Factor * i.Price
        : i.Factor * i.Price * (1m + i.VAT / 100m);
    decimal AmtP(WarrantyClaimPartItem i) => i.Vat == 0m ? i.Factor * i.Price * i.Quantity
        : i.Factor * i.Price * i.Quantity * (1m + i.Vat / 100m);

    var items = heads.Select(h => new
    {
        ROWID = h.Id, h.ROWNo, h.ROID, h.RONo, h.DealerCode, h.Vin, h.PlateNo,
        h.Status, WarrantyStatus = h.Status,
        statusName = h.Status switch
        {
            "SENT" => "Chờ xem xét", "APPROVED" => "Đã duyệt", "REJECTED" => "Từ chối",
            _ => h.Status,
        },
        h.StartDate, h.FinishedDate, h.CreatedAt,
        ServicePrice = svc.Where(i => i.ClaimId == h.Id).Sum(AmtS),
        PartPrice = prt.Where(i => i.ClaimId == h.Id).Sum(AmtP),
        TotalAmount = svc.Where(i => i.ClaimId == h.Id).Sum(AmtS) + prt.Where(i => i.ClaimId == h.Id).Sum(AmtP),
        HTCROWNo = htcRowNo.TryGetValue(h.Id, out var hrn) ? hrn : null,   // #510 dựng lại từ macro nguồn
        StoreDate = (DateTime?)null,     // chỉ có khi làm giàu được từ DMS Sales
        serviceItems = svc.Where(i => i.ClaimId == h.Id)
            .Select(i => new { i.Id, i.SerID, i.SerCode, i.SerName, i.Factor, i.Price, i.VAT,
                AmountBeforeVat = i.Factor * i.Price, Amount = AmtS(i), i.WarrantyStatus }),
        partItems = prt.Where(i => i.ClaimId == h.Id)
            .Select(i => new { i.Id, i.PartCode, i.PartName, Need = i.Quantity, i.Factor, i.Price, i.Vat,
                AmountBeforeVat = i.Factor * i.Price * i.Quantity, Amount = AmtP(i), i.WarrantyStatus }),
    }).ToList();

    return Results.Ok(new
    {
        count = items.Count, items,
        // Nguồn CẮT dòng theo DMS Sales; bản port KHÔNG cắt vì không có nguồn StoreDate.
        dmsSaleEnrichmentNotAvailable = true,
        sourceInnerJoinDropsRowsWithoutSale = "StoreDate > '2017-04-01' + InnerJoin FrameNo=VIN",
        hardcodedCutoffDate = "2017-04-01",
        enrichmentFailureChangesRowSet = true,
        distinctAfterFilterInSource = true,
        // #510: nợ #502 đã trả — dựng lại bằng macro nguồn, không cần hàm vô hướng DB.
        htcRowNoRebuiltFromMacro = "zzB_tbl_Ser_ROWarrantyReport_HTCROWNo_zzE(\"ACCE\")",
        htcRowNoRecomputedEveryRead = true,
        htcRowNoOnlyForStatusACCE = true,
        htcRowNoOverflowPast999 = overflow999,
        htcRowNoNullInSourcePast999 = true,
        hmcSideEffectNotPorted = true,
        vatFormulaFromActiveLineNotComment = true,
    });
}).RequireAuthorization();

// ===== 🔴🔴 #511 SỐ LỆNH TRUNG BÌNH MỖI NGÀY (máy tính bảng) — KHOÁ NỐI CHỈ ĐÚNG CHO **THÁNG** =====
// Nguồn: `Tab/BizCarSv.Tab.Report.cs:544 Rpt_Ser_RO_AvgQtyROInDayX` (WS qua `…ForTab` :808).
// Endpoint: `GET /api/reports/ro-avg-per-day`.
//
// 🔴 **KHOÁ NỐI SAI HÌNH DẠNG VỚI HAI TRONG BA KIỂU BÁO CÁO** (luật #410 — lọc/nối sai CỘT):
//   Câu tổng hợp nối `#input_tbl_ReportType t` với hai bảng đếm bằng `t.MixCode = f.FinishMonth`,
//   trong khi `FinishMonth = convert(char(7), sr.ActualDeliveryDate, 126) + '-01'` ⇒ **luôn là `yyyy-MM-01`**.
//   Còn `MixCode` do hàm dựng rổ sinh ra (`TabReport.zSqlTemplate.cs`) thì:
//     · `Month` → `StandardizeMonth` = `yyyy-MM-01`  ✅ **khớp**
//     · `DAY`   → `StandardizeDate`  = `yyyy-MM-dd`  🔴 **chỉ khớp đúng ngày mồng 1**
//     · `Hour`  → **số nguyên 0..23**                🔴 **không bao giờ khớp**
//   ⇒ Chọn NGÀY thì mọi ngày ≠ 01 ra `QtyRO = 0, QtyDay = 0, AvgQtyRO = 0`; chọn GIỜ thì **cả 24 dòng đều 0**.
//     Vẫn **đủ dòng, đủ nhãn, không lỗi** — nhìn như "kỳ đó không có lệnh nào".
//     Đây là **ca "0 im lặng" thứ tư** của cụm máy tính bảng (sau #472 giá vốn, #504 màn kho, #506 thiếu YEAR).
//   ⚪ Kiểm tra âm tính: `left join` + `IsNull(...,0.0)` là **cố ý** (giữ đủ rổ) — chính vì thế mà lỗi khoá nối
//     bị **che hoàn toàn**: nếu là `inner join` thì báo cáo rỗng và người dùng đã phát hiện từ lâu.
// 📌 Port: MiniHTC nối theo **khoảng thời gian của rổ** (đúng nghiệp vụ) và trả thêm `sourceWouldZero` —
//   số rổ mà nguồn sẽ cho 0 vì khoá nối lệch — để đo được mức sai lệch, không im lặng theo nguồn.
//
// ⚠️ `QtyDay` đếm **số NGÀY riêng biệt có giao xe** (`select distinct … convert(char(10), ActualDeliveryDate)`
//   rồi `count(*) group by FinishMonth`) — **không** phải số ngày của tháng. Tháng chỉ giao xe 3 ngày thì
//   mẫu số là 3, không phải 30 ⇒ "trung bình mỗi ngày" thực chất là **trung bình mỗi NGÀY CÓ VIỆC**.
// ⚠️ `Round(QtyRO*1.00/QtyDay, 0)` — làm tròn về **số nguyên** ngay trong SQL: 1,4 → 1 và 1,5 → 2
//   (SQL `ROUND` là half-away-from-zero, khác `Convert.ToInt32` của #408). Port dùng `MidpointRounding.
//   AwayFromZero` cho khớp, và trả thêm `avgRaw` chưa làm tròn để không mất thông tin.
// ⚠️ `case when QtyDay = 0 then 0` — guard chia 0 **có thật**, khác #507 (ở đó mẫu số để trần).
app.MapGet("/api/reports/ro-avg-per-day", async (AppDbContext db, ITenantContext t,
    string? dealerCode, string? reportType, DateTime? fromDate, DateTime? toDate) =>
{
    if (string.IsNullOrWhiteSpace(dealerCode))
        return Results.BadRequest(new { error = "Rpt_Ser_RO_AvgQtyROInDay_InvalidDealerCode" });
    if (string.IsNullOrWhiteSpace(reportType))
        return Results.BadRequest(new { error = "Rpt_Ser_RO_AvgQtyROInDay_InvalidReportType" });
    if (fromDate is null || toDate is null) return Results.BadRequest(new { error = "Cần fromDate và toDate." });
    if (fromDate.Value.Date > toDate.Value.Date)
        return Results.BadRequest(new { error = "Rpt_Ser_RO_AvgQtyROInDay_DateFromAfterDTimeTo" });

    var dealer = dealerCode!.Trim();
    var kind = reportType!.Trim().ToUpperInvariant();
    if (kind != "HOUR" && kind != "DAY" && kind != "MONTH")
        return Results.BadRequest(new { error = "reportType chỉ nhận HOUR, DAY hoặc MONTH (nguồn không có nhánh YEAR — #506)." });

    var from = fromDate.Value.Date;
    var to = toDate.Value.Date.AddDays(1).AddSeconds(-1);
    var buckets = new List<(string MixCode, string MixName, DateTime Start, DateTime End)>();
    if (kind == "HOUR")
        for (var h = 0; h < 24; h++)
        {
            var st = from.AddHours(h);
            buckets.Add((h.ToString(), h.ToString("00"), st, st.AddHours(1).AddSeconds(-1)));   // MixCode = SỐ, đúng nguồn
        }
    else if (kind == "DAY")
        for (var d = from; d <= toDate.Value.Date; d = d.AddDays(1))
            buckets.Add((d.ToString("yyyy-MM-dd"), d.ToString("yyyy-MM-dd"), d, d.AddDays(1).AddSeconds(-1)));
    else
    {
        var m = new DateTime(from.Year, from.Month, 1);
        var mEnd = new DateTime(toDate.Value.Year, toDate.Value.Month, 1);
        for (; m <= mEnd; m = m.AddMonths(1))
            buckets.Add((m.ToString("yyyy-MM-01"), m.ToString("yyyy-MM-01"), m, m.AddMonths(1).AddSeconds(-1)));
    }

    var ros = await db.RepairOrders.Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer
            && x.ActualDeliveryDate != null && x.ActualDeliveryDate >= from && x.ActualDeliveryDate <= to)
        .Select(x => new { x.Id, x.ActualDeliveryDate }).ToListAsync();

    var items = buckets.Select(b =>
    {
        var inB = ros.Where(r => r.ActualDeliveryDate >= b.Start && r.ActualDeliveryDate <= b.End).ToList();
        decimal qtyRO = inB.Count;
        // QtyDay = số NGÀY riêng biệt có giao xe trong rổ (không phải số ngày của rổ).
        decimal qtyDay = inB.Select(r => r.ActualDeliveryDate!.Value.Date).Distinct().Count();
        var raw = qtyDay == 0 ? 0m : qtyRO / qtyDay;
        return new
        {
            DealerCode = dealer, b.MixCode, ReportType = kind, b.MixName,
            DateTimeStart = b.Start, DateTimeEnd = b.End,
            QtyRO = qtyRO, Qty = qtyRO, QtyDay = qtyDay,
            AvgQtyRO = qtyDay == 0 ? 0m : Math.Round(raw, 0, MidpointRounding.AwayFromZero),
            avgRaw = Math.Round(raw, 4),
        };
    }).ToList();

    // Nguồn nối `MixCode = FinishMonth` (luôn `yyyy-MM-01`) ⇒ rổ nào có MixCode khác dạng đó là ra 0.
    var sourceWouldZero = buckets.Count(b => !b.MixCode.EndsWith("-01") || b.MixCode.Length != 10);

    return Results.Ok(new
    {
        dealerCode = dealer, reportType = kind,
        from = from.ToString("yyyy-MM-dd"), to = toDate.Value.Date.ToString("yyyy-MM-dd"),
        count = items.Count, roCount = ros.Count, items,
        sourceJoinsOnMonthKeyOnly = "t.MixCode = f.FinishMonth (FinishMonth luon yyyy-MM-01)",
        sourceWouldZero,
        qtyDayIsDistinctWorkingDays = true,
        avgRoundedToIntegerInSource = true,
        divideByZeroGuardExists = true,
    });
}).RequireAuthorization();

// ===== 🔴🔴 #512 THỐNG KÊ LOẠI CÔNG VIỆC / ĐỐI TƯỢNG THANH TOÁN THEO ĐẠI LÝ (máy tính bảng) =====
// Nguồn: `Tab/BizCarSv.Tab.Report.cs:1043 Rpt_Ser_RO_ExpTpAndROTpGroupByDealerX` (WS qua `…ForTab` :919).
// Endpoint: `GET /api/reports/ro-type-expense-by-dealer`. Trả **hai** bảng như nguồn (2 `Tables`).
//
// 🔴🔴 **DANH SÁCH PIVOT ĐÓNG BĂNG — LOẠI MỚI BỊ NUỐT KHÔNG DẤU VẾT** (họ #413):
//   `pivot (sum(QtyROType) for ROType in (BDD, PDI, SCC, SCD, SCS))` — **năm** mã, gõ cứng trong macro
//   `zzB_tbl_Ser_RO_ROTypeGroupByDealer_zzE` (`TabReport.zSqlTemplate.cs:1115`).
//   Nhưng chính chú thích entity của MiniHTC (`RoServiceItem.ROType`, ghi từ nguồn ở #280) liệt kê
//   **sáu** mã: `BDD / SCC / SCD / SCS / PDI / **SPK**`. ⇒ Lệnh loại **SPK** được đếm ở bảng gộp nhưng
//   **rơi khỏi PIVOT** ⇒ không có cột nào chứa nó, tổng các cột **nhỏ hơn** tổng thật, không ai báo lỗi.
//   Tương tự `ExpenseType in (LOCAL, ROINSURANCE, ROREPAIR, ROWARRANTY)` — bốn mã gõ cứng.
//   ⇒ Port **không đóng băng**: trả đủ mọi mã gặp trong dữ liệu, kèm `typesOutsidePivotList` để đo
//     đúng phần nguồn đang nuốt.
//
// 🔴 **HÌNH DẠNG KẾT QUẢ: MỘT DÒNG = MỘT CẶP (LỆNH, LOẠI), KHÔNG PHẢI MỘT LỆNH** (§12, câu "một bản ghi
//   là một chứng từ hay một dòng?"): `select distinct t.ROID, t.RONo, f.ROType` rồi `count(*)`.
//   Một lệnh có hai loại công việc được đếm **hai lần**, ở hai cột khác nhau. Tổng các cột **≠** số lệnh.
//   Trả kèm `roCount` (số lệnh riêng biệt) để so với `sum(Qty)` và thấy ngay chênh lệch.
// ⚠️ `ExpenseType` lấy từ **cả hai** phía: hạng mục dịch vụ `union` hạng mục phụ tùng (`union` chứ không
//   `union all` ⇒ khử trùng cặp (lệnh, loại) — kiểm tra âm tính, đúng ý đồ).
// ⚠️ Hai macro gộp đều `inner join Ser_RO sr` nhưng `sr.DealerCode` bị **comment khỏi cả SELECT lẫn
//   GROUP BY** ⇒ **join CHẾT** (họ #414: nối vào rồi không dùng cột nào). Không đổi số vì lệnh nào cũng
//   có trong `Ser_RO`, nhưng là dấu vết của bản gộp-theo-đại-lý bị cắt dở.
// 🔴 `string strReportType = TConst.ReportType.Month;` **gán cứng ngay đầu hàm**, rồi bên dưới vẫn có
//   `if (string.IsNullOrEmpty(strReportType)) throw …_InvalidReportType` ⇒ **GUARD CHẾT**, không bao giờ
//   chạm tới (họ #407). Tham số kiểu báo cáo **không tồn tại** ở màn này — luôn là THÁNG.
app.MapGet("/api/reports/ro-type-expense-by-dealer", async (AppDbContext db, ITenantContext t,
    string? dealerCode, DateTime? fromDate, DateTime? toDate) =>
{
    if (string.IsNullOrWhiteSpace(dealerCode))
        return Results.BadRequest(new { error = "Rpt_Ser_RO_ExpTpAndROTpGroupByDealerX_InvalidDealerCode" });
    if (fromDate is null || toDate is null) return Results.BadRequest(new { error = "Cần fromDate và toDate." });
    if (fromDate.Value.Date > toDate.Value.Date)
        return Results.BadRequest(new { error = "Rpt_Ser_RO_ExpTpAndROTpGroupByDealerX_DateFromAfterDateTo" });

    // Danh sách gõ cứng CỦA NGUỒN — chép nguyên văn để đo phần bị nuốt, KHÔNG dùng để lọc.
    string[] pivotROType = { "BDD", "PDI", "SCC", "SCD", "SCS" };
    string[] pivotExpenseType = { "LOCAL", "ROINSURANCE", "ROREPAIR", "ROWARRANTY" };

    var dealer = dealerCode!.Trim();
    var from = fromDate.Value.Date;
    var to = toDate.Value.Date.AddDays(1).AddSeconds(-1);

    var roIds = await db.RepairOrders.Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer
            && x.ActualDeliveryDate != null && x.ActualDeliveryDate >= from && x.ActualDeliveryDate <= to)
        .Select(x => x.Id).ToListAsync();

    // distinct (lệnh, loại) — đúng nguồn: một lệnh nhiều loại thì đếm nhiều lần.
    var roTypePairs = (await db.RoServiceItems
            .Where(i => i.OrgId == t.OrgId && roIds.Contains(i.RoId) && i.ROType != null)
            .Select(i => new { i.RoId, i.ROType }).ToListAsync())
        .Distinct().ToList();

    var expSvc = await db.RoServiceItems
        .Where(i => i.OrgId == t.OrgId && roIds.Contains(i.RoId) && i.ExpenseType != null)
        .Select(i => new { i.RoId, i.ExpenseType }).ToListAsync();
    var expPrt = await db.RoPartItems
        .Where(i => i.OrgId == t.OrgId && roIds.Contains(i.RoId) && i.ExpenseType != null)
        .Select(i => new { i.RoId, i.ExpenseType }).ToListAsync();
    var expPairs = expSvc.Concat(expPrt).Distinct().ToList();      // `union`, không phải `union all`

    var roTypeRows = roTypePairs.GroupBy(x => x.ROType!)
        .Select(g => new { ROType = g.Key, QtyROType = (decimal)g.Count(),
            inSourcePivot = pivotROType.Contains(g.Key) })
        .OrderBy(x => x.ROType).ToList();
    var expRows = expPairs.GroupBy(x => x.ExpenseType!)
        .Select(g => new { ExpenseType = g.Key, QtyExpenseType = (decimal)g.Count(),
            inSourcePivot = pivotExpenseType.Contains(g.Key) })
        .OrderBy(x => x.ExpenseType).ToList();

    return Results.Ok(new
    {
        dealerCode = dealer, reportType = "MONTH",      // nguồn gán cứng, không nhận tham số
        from = from.ToString("yyyy-MM-dd"), to = toDate.Value.Date.ToString("yyyy-MM-dd"),
        roCount = roIds.Count,
        roTypeRows, expenseTypeRows = expRows,
        // Đo đúng phần nguồn nuốt vì danh sách pivot đóng băng.
        sourcePivotROType = pivotROType, sourcePivotExpenseType = pivotExpenseType,
        typesOutsidePivotList = roTypeRows.Where(x => !x.inSourcePivot).Select(x => x.ROType)
            .Concat(expRows.Where(x => !x.inSourcePivot).Select(x => x.ExpenseType)).ToList(),
        qtyDroppedByFrozenPivot = roTypeRows.Where(x => !x.inSourcePivot).Sum(x => x.QtyROType)
            + expRows.Where(x => !x.inSourcePivot).Sum(x => x.QtyExpenseType),
        rowIsRoTypePairNotRo = true,
        expenseTypeFromServiceUnionPart = true,
        deadJoinSerRoInSource = true,
        deadGuardInvalidReportType = "strReportType gan cung = MONTH ngay dau ham",
    });
}).RequireAuthorization();

// ===== #513 CÙNG THỐNG KÊ TRÊN NHƯNG GỘP THEO **CỐ VẤN DỊCH VỤ** (máy tính bảng) =====
// Nguồn: `Tab/BizCarSv.Tab.Report.cs:1322 Rpt_Ser_RO_ExpTpAndROTpGroupByCVDVX` (WS `…ForTab` :1203).
// Endpoint: `GET /api/reports/ro-type-expense-by-cvdv`.
//
// 📐 **DIFF HAI NHÁNH TRƯỚC KHI ĐỌC** (luật #414): so nguyên văn `…GroupByDealerX` (:1043) với
//   `…GroupByCVDVX` (:1322) — **khác biệt thật vỏn vẹn ba chỗ**, và đúng như luật cảnh báo,
//   **nằm ở DANH SÁCH CỘT chứ không ở WHERE**:
//     1) macro gộp đổi sang bản `…GroupByCVDV_zzE` — gộp thêm `sr.DealerCode, sr.Creator`
//        (bản Dealer **comment mất** `sr.DealerCode` nên gộp toàn bộ vào một dòng — xem #512),
//     2) hai câu trả về thêm `su.UserCode su_UserCode` · `su.UserName su_UserName` +
//        `left join Sys_User su on t.Creator = su.UserCode and t.DealerCode = su.DealerCode`,
//     3) tên hai bảng trả về đổi hậu tố `…ByDealer` → `…ByCVDV` (và tên hằng lỗi kèm theo).
//   Guard, mốc ngày, danh sách pivot: **y hệt** ⇒ mọi phát hiện #512 áp nguyên cho màn này.
// ⚪ **Kiểm tra âm tính cho `left join Sys_User`** (ba câu hỏi #414): cột nối `t.Creator`/`t.DealerCode`
//   lấy từ **chính bảng trái**, không bảng LEFT nào khác · không có bảng nào nối TRONG sau nó ·
//   `where(1=1)` **không** có điều kiện trên `su` ⇒ **LEFT còn sống**. Cố vấn đã nghỉ / khác đại lý thì
//   `su_UserName` = null nhưng **dòng vẫn còn** và số liệu **không mất** — port giữ đúng, kèm đếm.
// 🔴 Nối theo **cặp** `UserCode + DealerCode`: cùng một mã cố vấn ở đại lý khác **không khớp** ⇒ tên rỗng.
//   Đây là lọc-theo-cặp, không phải tra danh mục toàn cục — trả `rowsWithoutUserName` để đo.
// ⚠️ Danh sách pivot vẫn **đóng băng 5 mã** `BDD, PDI, SCC, SCD, SCS` (thiếu `SPK`) — như #512.
app.MapGet("/api/reports/ro-type-expense-by-cvdv", async (AppDbContext db, ITenantContext t,
    string? dealerCode, DateTime? fromDate, DateTime? toDate) =>
{
    if (string.IsNullOrWhiteSpace(dealerCode))
        return Results.BadRequest(new { error = "Rpt_Ser_RO_ExpTpAndROTpGroupByCVDVX_InvalidDealerCode" });
    if (fromDate is null || toDate is null) return Results.BadRequest(new { error = "Cần fromDate và toDate." });
    if (fromDate.Value.Date > toDate.Value.Date)
        return Results.BadRequest(new { error = "Rpt_Ser_RO_ExpTpAndROTpGroupByCVDVX_DateFromAfterDateTo" });

    string[] pivotROType = { "BDD", "PDI", "SCC", "SCD", "SCS" };
    string[] pivotExpenseType = { "LOCAL", "ROINSURANCE", "ROREPAIR", "ROWARRANTY" };

    var dealer = dealerCode!.Trim();
    var from = fromDate.Value.Date;
    var to = toDate.Value.Date.AddDays(1).AddSeconds(-1);

    var ros = await db.RepairOrders.Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer
            && x.ActualDeliveryDate != null && x.ActualDeliveryDate >= from && x.ActualDeliveryDate <= to)
        .Select(x => new { x.Id, x.DealerCode, x.Creator }).ToListAsync();
    var roOf = ros.ToDictionary(x => x.Id, x => x);
    var roIds = ros.Select(x => x.Id).ToList();

    var roTypePairs = (await db.RoServiceItems
            .Where(i => i.OrgId == t.OrgId && roIds.Contains(i.RoId) && i.ROType != null)
            .Select(i => new { i.RoId, i.ROType }).ToListAsync())
        .Distinct().ToList();
    var expSvc = await db.RoServiceItems
        .Where(i => i.OrgId == t.OrgId && roIds.Contains(i.RoId) && i.ExpenseType != null)
        .Select(i => new { i.RoId, i.ExpenseType }).ToListAsync();
    var expPrt = await db.RoPartItems
        .Where(i => i.OrgId == t.OrgId && roIds.Contains(i.RoId) && i.ExpenseType != null)
        .Select(i => new { i.RoId, i.ExpenseType }).ToListAsync();
    var expPairs = expSvc.Concat(expPrt).Distinct().ToList();

    var users = await db.SysUsers.Where(u => u.OrgId == t.OrgId)
        .Select(u => new { u.UserCode, u.UserName, u.DealerCode }).ToListAsync();
    // Nối theo CẶP (UserCode, DealerCode) — đúng nguồn.
    string? NameOf(string? creator, string? dlr) => users
        .FirstOrDefault(u => u.UserCode == creator && u.DealerCode == dlr)?.UserName;

    var roTypeRows = roTypePairs
        .GroupBy(x => new { roOf[x.RoId].DealerCode, roOf[x.RoId].Creator, x.ROType })
        .Select(g => new
        {
            g.Key.DealerCode, g.Key.Creator, ROType = g.Key.ROType!,
            QtyROType = (decimal)g.Count(),
            su_UserCode = NameOf(g.Key.Creator, g.Key.DealerCode) is null ? null : g.Key.Creator,
            su_UserName = NameOf(g.Key.Creator, g.Key.DealerCode),
            inSourcePivot = pivotROType.Contains(g.Key.ROType!),
        }).OrderBy(x => x.Creator).ThenBy(x => x.ROType).ToList();

    var expRows = expPairs
        .GroupBy(x => new { roOf[x.RoId].DealerCode, roOf[x.RoId].Creator, x.ExpenseType })
        .Select(g => new
        {
            g.Key.DealerCode, g.Key.Creator, ExpenseType = g.Key.ExpenseType!,
            QtyExpenseType = (decimal)g.Count(),
            su_UserCode = NameOf(g.Key.Creator, g.Key.DealerCode) is null ? null : g.Key.Creator,
            su_UserName = NameOf(g.Key.Creator, g.Key.DealerCode),
            inSourcePivot = pivotExpenseType.Contains(g.Key.ExpenseType!),
        }).OrderBy(x => x.Creator).ThenBy(x => x.ExpenseType).ToList();

    return Results.Ok(new
    {
        dealerCode = dealer, reportType = "MONTH",
        from = from.ToString("yyyy-MM-dd"), to = toDate.Value.Date.ToString("yyyy-MM-dd"),
        roCount = ros.Count,
        roTypeRows, expenseTypeRows = expRows,
        // LEFT join Sys_User còn sống ⇒ không mất dòng, chỉ trống tên.
        rowsWithoutUserName = roTypeRows.Count(x => x.su_UserName is null)
            + expRows.Count(x => x.su_UserName is null),
        userJoinIsPairUserCodeAndDealer = true,
        leftJoinSysUserStillAlive = true,
        sourcePivotROType = pivotROType, sourcePivotExpenseType = pivotExpenseType,
        qtyDroppedByFrozenPivot = roTypeRows.Where(x => !x.inSourcePivot).Sum(x => x.QtyROType)
            + expRows.Where(x => !x.inSourcePivot).Sum(x => x.QtyExpenseType),
        rowIsRoTypePairNotRo = true,
        deadGuardInvalidReportType = "strReportType gan cung = MONTH ngay dau ham",
        divergesFromDealerVariantOnlyInColumns = true,
    });
}).RequireAuthorization();

// ===== 🔴🔴 #514 DOANH THU GỘP THEO CVDV / ĐẠI LÝ — **`inner join Sys_User` NUỐT TIỀN** =====
// Nguồn: `Tab/BizCarSv.Tab.Report.cs:2041 Rpt_Ser_RO_RevenueGroupByMixX` (WS `…GroupByCVDVForTab` :2307
//   và `…GroupByDealerForTab` :2428 — **một biz, hai WebMethod**, phân nhánh bằng cờ `strFlagCVDV`).
// Endpoint: `GET /api/reports/ro-revenue-group-by-mix` (`groupBy=CVDV|DEALER`).
//
// 🔴🔴 **CÙNG MỘT CỤM, HAI BÁO CÁO, HAI KIỂU NỐI NGƯỢC NHAU**:
//   · #513 (`…ExpTpAndROTpGroupByCVDVX`) dùng `**left** join Sys_User` ⇒ cố vấn đã nghỉ vẫn còn dòng.
//   · Ở đây (`:2236`) là `**inner** join Sys_User su on t.DealerCode = su.DealerCode and t.Creator = su.UserCode`
//     ⇒ cố vấn **nghỉ việc / bị xoá / đổi đại lý** thì **toàn bộ doanh thu của người đó BIẾN MẤT**
//     khỏi báo cáo. Không phải mất tên — **mất TIỀN**, và tổng báo cáo **nhỏ hơn thực tế**, không cảnh báo.
//   ⇒ Luật #410 ("nối sang bảng người dùng = mất dữ liệu lúc ĐỌC") ở dạng nặng nhất: mất **số tiền**.
//   Port dùng LEFT + trả `revenueOrphanedByUserJoin` = đúng số tiền mà nguồn đang giấu.
//
// 🔴 **CỜ `strFlagCVDV` KHÔNG CÓ NHÁNH MẶC ĐỊNH**: chỉ `Flag.Active` dựng khối CVDV, `Flag.No` dựng khối
//   đại lý; giá trị **bất kỳ khác** ⇒ **cả hai macro giữ nguyên `"--Nothing"`** ⇒ câu SQL **không trả bảng nào**,
//   và hai lệnh đặt tên bảng bên dưới cũng **không chạy** ⇒ trả về DataSet **rỗng, không lỗi**.
//   (Ca "0 im lặng" thứ **năm** của cụm máy tính bảng.) Port **chặn thẳng** giá trị lạ.
// ⚠️ HẰNG ≠ GIÁ TRỊ (mở `Const.Main.cs:28-33`): `Flag.Active = "1"` · `Flag.Yes = Active` (**cùng giá trị**)
//   · `Flag.No = Inactive`. Khối dựng SQL so bằng `Flag.Active` còn khối đặt tên bảng so bằng `Flag.Yes` —
//   **hai tên hằng khác nhau cho cùng một giá trị** trong cùng một hàm; hiện vô hại, nhưng tách giá trị
//   của một trong hai là hỏng câm.
// ⚠️ Bộ cột tiền lại **đóng băng 5 loại công việc** `BDD/SCC/SCD/SCS/PDI` (thiếu `SPK` — xem #512) và
//   **4 đối tượng thanh toán** `Local/Insurance/Warranty/Repair`; lần này là **TIỀN**, không phải số đếm.
app.MapGet("/api/reports/ro-revenue-group-by-mix", async (AppDbContext db, ITenantContext t,
    string? dealerCode, string? groupBy, DateTime? fromDate, DateTime? toDate) =>
{
    if (string.IsNullOrWhiteSpace(dealerCode))
        return Results.BadRequest(new { error = "Rpt_Ser_RO_RevenueGroupByMix_InvalidDealerCode" });
    if (fromDate is null || toDate is null) return Results.BadRequest(new { error = "Cần fromDate và toDate." });
    if (fromDate.Value.Date > toDate.Value.Date)
        return Results.BadRequest(new { error = "Rpt_Ser_RO_RevenueGroupByMix_DateFromAfterDateTo" });
    var mode = (groupBy ?? "").Trim().ToUpperInvariant();
    if (mode != "CVDV" && mode != "DEALER")
        return Results.BadRequest(new
        {
            error = "groupBy chỉ nhận CVDV hoặc DEALER.",
            sourceReturnsEmptyDataSetForOtherValues = true,
        });

    string[] roTypes = { "BDD", "SCC", "SCD", "SCS", "PDI" };          // đóng băng như nguồn
    string[] expenseTypes = { "LOCAL", "ROINSURANCE", "ROWARRANTY", "ROREPAIR" };

    var dealer = dealerCode!.Trim();
    var from = fromDate.Value.Date;
    var to = toDate.Value.Date.AddDays(1).AddSeconds(-1);

    var ros = await db.RepairOrders.Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer
            && x.ActualDeliveryDate != null && x.ActualDeliveryDate >= from && x.ActualDeliveryDate <= to)
        .Select(x => new { x.Id, x.DealerCode, x.Creator }).ToListAsync();
    var roOf = ros.ToDictionary(x => x.Id, x => x);
    var roIds = ros.Select(x => x.Id).ToList();

    var svc = await db.RoServiceItems.Where(i => i.OrgId == t.OrgId && roIds.Contains(i.RoId))
        .Select(i => new { i.RoId, i.ROType, i.ExpenseType, i.Factor, i.Price, i.Vat }).ToListAsync();
    var prt = await db.RoPartItems.Where(i => i.OrgId == t.OrgId && roIds.Contains(i.RoId))
        .Select(i => new { i.RoId, i.ExpenseType, i.Factor, i.NeedQty, i.UnitPrice, i.Vat }).ToListAsync();

    // Nhóm theo (đại lý, cố vấn) khi CVDV; gộp hết về một dòng khi DEALER (nguồn bake @strDealerCode).
    var keys = mode == "CVDV"
        ? ros.Select(x => (Dealer: x.DealerCode, Creator: x.Creator)).Distinct().ToList()
        : new List<(string? Dealer, string? Creator)> { (dealer, null) };

    var users = await db.SysUsers.Where(u => u.OrgId == t.OrgId)
        .Select(u => new { u.UserCode, u.UserName, u.DealerCode }).ToListAsync();


    var rows = keys.Select(k =>
    {
        var ids = ros.Where(r => mode != "CVDV" || (r.DealerCode == k.Dealer && r.Creator == k.Creator))
            .Select(r => r.Id).ToHashSet();
        var sv = svc.Where(i => ids.Contains(i.RoId)).ToList();
        var pt = prt.Where(i => ids.Contains(i.RoId)).ToList();
        decimal ByType(string ty) => sv.Where(i => i.ROType == ty)
            .Sum(i => i.Factor * i.Price * (1m + i.Vat * 0.01m));
        decimal ByExp(string ex) => sv.Where(i => i.ExpenseType == ex)
                .Sum(i => i.Factor * i.Price * (1m + i.Vat * 0.01m))
            + pt.Where(i => i.ExpenseType == ex)
                .Sum(i => i.Factor * i.NeedQty * i.UnitPrice * (1m + i.Vat * 0.01m));
        var u = users.FirstOrDefault(x => x.UserCode == k.Creator && x.DealerCode == k.Dealer);
        return new
        {
            DealerCode = k.Dealer, Creator = k.Creator,
            su_UserCode = u?.UserCode, su_UserName = u?.UserName,
            userMissing = mode == "CVDV" && u is null,
            ServiceAmountBDD = ByType("BDD"), ServiceAmountSCC = ByType("SCC"),
            ServiceAmountSCD = ByType("SCD"), ServiceAmountSCS = ByType("SCS"),
            ServiceAmountPDI = ByType("PDI"),
            RevenueROLocal = ByExp("LOCAL"), RevenueRoInsurance = ByExp("ROINSURANCE"),
            RevenueRoWarranty = ByExp("ROWARRANTY"), RevenueRoRepair = ByExp("ROREPAIR"),
        };
    }).ToList();

    // Đúng số tiền mà `inner join Sys_User` của nguồn đang giấu đi.
    var orphaned = rows.Where(r => r.userMissing)
        .Sum(r => r.RevenueROLocal + r.RevenueRoInsurance + r.RevenueRoWarranty + r.RevenueRoRepair);

    return Results.Ok(new
    {
        dealerCode = dealer, groupBy = mode,
        from = from.ToString("yyyy-MM-dd"), to = toDate.Value.Date.ToString("yyyy-MM-dd"),
        tableName = mode == "CVDV" ? "Rpt_Ser_RO_RevenueGroupByCVDV" : "Rpt_Ser_RO_RevenueByDealer",
        roCount = ros.Count, count = rows.Count, items = rows,
        sourceUsesInnerJoinSysUser = mode == "CVDV",
        rowsDroppedBySourceUserJoin = rows.Count(r => r.userMissing),
        revenueOrphanedByUserJoin = orphaned,
        contrastWithLeftJoinVariant = "#513 dung LEFT join cho cung bang Sys_User",
        frozenTypeColumns = roTypes, frozenExpenseColumns = expenseTypes,
        sourceReturnsEmptyDataSetForOtherFlagValues = true,
    });
}).RequireAuthorization();

// ===== 🔴 #515 DOANH THU PHỤ TÙNG / DẦU NHỚT THEO KỲ (máy tính bảng) =====
// Nguồn: `Tab/BizCarSv.Tab.Report.cs:2549 Rpt_Ser_RO_RevenuePartShellX` (WS `…ForTab` :2813).
// Endpoint: `GET /api/reports/ro-revenue-part-shell`. **§12** thêm `PartStockOut.DealerCode`.
//
// 🔴 **LẶP LẠI NGUYÊN VẸN LỖI KHOÁ NỐI CỦA #511 — LẦN NÀY TRÊN BA `left join`**:
//   `t.MixCode = f.FinishMonth` · `t.MixCode = k.StockOutMonth` · `t.MixCode = z.StockOutMonth`,
//   mà cả ba khoá phải là `convert(char(7), …, 126) + '-01'` ⇒ **luôn `yyyy-MM-01`**.
//   ⇒ Chọn NGÀY: chỉ mồng 1 có số; chọn GIỜ: **cả 24 dòng = 0**. Cùng bệnh, cùng cụm, **ba** chỗ.
//   ⇒ Xác nhận đây là **khuôn lỗi dùng lại**, không phải sơ suất một lần (#511 là ca đầu).
// 🔴 **TÊN CỘT ĐÁNH LỪA**: `IsNull(f.PartAmountNotShell, 0.0) **RevenueRoRepair**` — cột trả về tên
//   "doanh thu sửa chữa" nhưng giá trị là **tiền phụ tùng KHÔNG PHẢI dầu nhớt**. Ai đọc theo tên cột
//   sẽ hiểu sai hoàn toàn. Port giữ **cả hai**: tên gốc `RevenueRoRepair` + tên đúng nghĩa
//   `partAmountNotShell`, kèm cờ `aliasRevenueRoRepairIsActuallyNotShell`.
// 🔴 Bộ lọc "dầu nhớt" là `smp.PartCode in @strListShellCode` — danh sách đọc từ **web.config**
//   (`_strConfig_ListShellCode`) rồi **thả thẳng vào SQL** (họ `[BAKE-PARAM-MIX]`): danh sách rỗng ⇒
//   `in ()` ⇒ **SQL sai cú pháp**, còn danh sách thiếu mã ⇒ **doanh thu dầu nhớt hụt câm**.
//   MiniHTC lấy từ tham số `ListShellCode` (đã có sẵn ở #337) và trả cờ khi rỗng.
// ⚠️ Hằng literal của phiếu xuất: `siso.Status = '3'` (đã duyệt) · `siso.StockOutType = '2'`
//   (*"Phieu xuat thuong"* — chú thích nguyên văn trong SQL). Chép **đúng giá trị**, không đổi tên.
// ⚠️ Mốc ngày so bằng **CHUỖI** `convert(nvarchar(20), …, 20)` và **bake** `'@objStockOutDateTimeFrom'`.
app.MapGet("/api/reports/ro-revenue-part-shell", async (AppDbContext db, ITenantContext t,
    string? dealerCode, string? reportType, DateTime? fromDate, DateTime? toDate) =>
{
    if (string.IsNullOrWhiteSpace(dealerCode))
        return Results.BadRequest(new { error = "Rpt_Ser_RO_RevenuePartShellX_InvalidDealerCode" });
    if (string.IsNullOrWhiteSpace(reportType))
        return Results.BadRequest(new { error = "Rpt_Ser_RO_RevenuePartShellX_InvalidReportType" });
    if (fromDate is null || toDate is null) return Results.BadRequest(new { error = "Cần fromDate và toDate." });
    if (fromDate.Value.Date > toDate.Value.Date)
        return Results.BadRequest(new { error = "Rpt_Ser_RO_RevenuePartShellX_DateFromAfterDateTo" });
    var kind = reportType!.Trim().ToUpperInvariant();
    if (kind != "HOUR" && kind != "DAY" && kind != "MONTH")
        return Results.BadRequest(new { error = "reportType chỉ nhận HOUR, DAY hoặc MONTH." });

    var dealer = dealerCode!.Trim();
    var from = fromDate.Value.Date;
    var to = toDate.Value.Date.AddDays(1).AddSeconds(-1);

    var prm = (await db.DealerServiceOptions.Where(x => x.OrgId == t.OrgId).ToListAsync())
        .GroupBy(x => x.ParamCode).ToDictionary(g => g.Key, g => g.First().ParamValue);
    var shellCodes = (prm.TryGetValue("ListShellCode", out var sc) ? sc : "")
        .Split(new[] { ',', ';' }, StringSplitOptions.RemoveEmptyEntries)
        .Select(x => x.Trim()).Where(x => x.Length > 0).ToHashSet();

    var buckets = new List<(string MixCode, string MixName, DateTime Start, DateTime End)>();
    if (kind == "HOUR")
        for (var h = 0; h < 24; h++)
        {
            var st = from.AddHours(h);
            buckets.Add((h.ToString(), h.ToString("00"), st, st.AddHours(1).AddSeconds(-1)));
        }
    else if (kind == "DAY")
        for (var d = from; d <= toDate.Value.Date; d = d.AddDays(1))
            buckets.Add((d.ToString("yyyy-MM-dd"), d.ToString("yyyy-MM-dd"), d, d.AddDays(1).AddSeconds(-1)));
    else
    {
        var m = new DateTime(from.Year, from.Month, 1);
        var mEnd = new DateTime(toDate.Value.Year, toDate.Value.Month, 1);
        for (; m <= mEnd; m = m.AddMonths(1))
            buckets.Add((m.ToString("yyyy-MM-01"), m.ToString("yyyy-MM-01"), m, m.AddMonths(1).AddSeconds(-1)));
    }

    // Tiền phụ tùng trên lệnh sửa chữa, tách dầu nhớt / không dầu nhớt.
    var ros = await db.RepairOrders.Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer
            && x.ActualDeliveryDate != null && x.ActualDeliveryDate >= from && x.ActualDeliveryDate <= to)
        .Select(x => new { x.Id, x.ActualDeliveryDate }).ToListAsync();
    var roIds = ros.Select(x => x.Id).ToList();
    var roAt = ros.ToDictionary(x => x.Id, x => x.ActualDeliveryDate!.Value);
    var roParts = await db.RoPartItems.Where(i => i.OrgId == t.OrgId && roIds.Contains(i.RoId))
        .Select(i => new { i.RoId, i.PartCode, i.Factor, i.NeedQty, i.UnitPrice, i.Vat }).ToListAsync();

    // Phiếu xuất kho ĐÃ DUYỆT, loại "xuất thường" — hằng literal của nguồn.
    const string kStockOutStatusApproved = "3";
    const string kStockOutTypeNormal = "2";
    var sos = await db.PartStockOuts.Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer
            && x.Status == kStockOutStatusApproved && x.StockOutType == kStockOutTypeNormal
            && x.StockOutDate >= from && x.StockOutDate <= to)
        .Select(x => new { x.Id, x.StockOutDate }).ToListAsync();
    var soIds = sos.Select(x => x.Id).ToList();
    var soAt = sos.ToDictionary(x => x.Id, x => x.StockOutDate);
    var soLines = await db.PartStockOutLines.Where(l => l.OrgId == t.OrgId && soIds.Contains(l.StockOutId))
        .Select(l => new { l.StockOutId, l.PartCode, l.Quantity, l.Price, l.Vat }).ToListAsync();

    var items = buckets.Select(b =>
    {
        var rp = roParts.Where(p => roAt[p.RoId] >= b.Start && roAt[p.RoId] <= b.End).ToList();
        var shellRepair = rp.Where(p => shellCodes.Contains(p.PartCode))
            .Sum(p => p.Factor * p.NeedQty * p.UnitPrice * (1m + p.Vat * 0.01m));
        var notShell = rp.Where(p => !shellCodes.Contains(p.PartCode))
            .Sum(p => p.Factor * p.NeedQty * p.UnitPrice * (1m + p.Vat * 0.01m));
        var sl = soLines.Where(l => soAt[l.StockOutId] >= b.Start && soAt[l.StockOutId] <= b.End).ToList();
        var shellOut = sl.Where(l => shellCodes.Contains(l.PartCode))
            .Sum(l => l.Quantity * (l.Price ?? 0m) * (1m + (l.Vat ?? 0m) * 0.01m));
        var partOut = sl.Where(l => !shellCodes.Contains(l.PartCode))
            .Sum(l => l.Quantity * (l.Price ?? 0m) * (1m + (l.Vat ?? 0m) * 0.01m));
        return new
        {
            b.MixCode, DealerCode = dealer, ReportType = kind, b.MixName,
            DateTimeStart = b.Start, DateTimeEnd = b.End,
            PartAmountShellRoRepair = shellRepair,
            RevenueRoRepair = notShell,               // TÊN GỐC của nguồn — thực chất là "không dầu nhớt"
            partAmountNotShell = notShell,            // tên đúng nghĩa, thêm để khỏi hiểu nhầm
            AllRevenuePartRepair = shellRepair + notShell,
            AllRevenuePartOut = shellOut + partOut,
            shellAmountOut = shellOut, partAmountOut = partOut,
        };
    }).ToList();

    return Results.Ok(new
    {
        dealerCode = dealer, reportType = kind,
        from = from.ToString("yyyy-MM-dd"), to = toDate.Value.Date.ToString("yyyy-MM-dd"),
        count = items.Count, roCount = ros.Count, stockOutCount = sos.Count, items,
        // Ba `left join` của nguồn đều nối theo khoá THÁNG ⇒ đo phần sẽ ra 0.
        sourceJoinsOnMonthKeyOnly = new[] { "FinishMonth", "StockOutMonth(part)", "StockOutMonth(shell)" },
        sourceWouldZero = buckets.Count(b => !b.MixCode.EndsWith("-01") || b.MixCode.Length != 10),
        aliasRevenueRoRepairIsActuallyNotShell = true,
        shellCodeListEmpty = shellCodes.Count == 0,
        shellCodeListBakedIntoSql = true,
        stockOutFilters = new { status = kStockOutStatusApproved, stockOutType = kStockOutTypeNormal },
    });
}).RequireAuthorization();

// ===== 🔴🔴 #516 LỊCH HẸN THEO KỲ VÀ TRẠNG THÁI — **NHÁNH GIỜ ĐẾM GẤP 24 LẦN** =====
// Nguồn: `Tab/BizCarSv.Tab.Report.cs:2932 Rpt_Ser_App_GroupByDateAndStatusX` (WS `…ForTab` :3196).
// Endpoint: `GET /api/reports/appointments-by-period-status`.
//
// 🔴🔴 **NHÂN ĐÔI DỮ LIỆU CÓ THẬT, KHÔNG PHẢI GIẢ THIẾT**: rổ nối kiểu `inner join … on (1=1)` rồi lọc
//     `and t.AppDate >= convert(char(10), f.DateTimeStart, 126)`
//     `and t.AppDate <= convert(char(10), f.DateTimeEnd, 126)`
//   `char(10)` **cắt mất phần GIỜ** của mốc rổ. Với `reportType = HOUR`, cả **24** rổ đều nằm trong
//   **cùng một ngày** ⇒ sau khi cắt, cả 24 rổ có mốc đầu/cuối **giống hệt nhau** ⇒ **mỗi lịch hẹn rơi vào
//   CẢ 24 RỔ** ⇒ tổng của báo cáo **gấp 24 lần** số lịch hẹn thật. Không lỗi, không cảnh báo.
//   (So với #506 dùng `nvarchar(20)` — **giữ giờ** — thì đây là cùng khuôn nhưng **sai độ dài**.)
//   Port đếm đúng theo mốc có giờ và trả `sourceHourBranchMultipliesBy24` để nêu đích danh.
//
// 🔴 `case sa.AppStatus when '1' then N'MOITAO' when '2' … when '4' then N'HUY' end` — **KHÔNG CÓ `else`**
//   ⇒ trạng thái ngoài `1..4` cho `AppStatusName = NULL`, mà `pivot … in (MOITAO, XACNHAN, TIEPNHAN, HUY)`
//   **không nhận NULL** ⇒ lịch hẹn trạng thái lạ **biến mất khỏi báo cáo**. Hai tầng nuốt chồng nhau:
//   thiếu `else` (#407) + danh sách pivot đóng băng (#512).
//   ⚠️ HẰNG ≠ GIÁ TRỊ: bốn mã trạng thái là **'1'/'2'/'3'/'4'** và tên hiển thị viết **KHÔNG DẤU**
//     (`MOITAO`, `XACNHAN`, `TIEPNHAN`, `HUY`) — chép nguyên văn, chúng là **tên CỘT** của pivot.
// 🔴 Câu cuối `from #tbl_Return_Pvt` — **đi từ bảng kết quả, KHÔNG từ bảng rổ** ⇒ rổ không có lịch hẹn
//   **không ra dòng**. Ngược hẳn #506/#511/#515 (cùng cụm, đi từ `#input_tbl_ReportType` nên rổ rỗng vẫn có
//   dòng `Qty = 0`). ⇒ **Bốn báo cáo anh em, hai quy ước trình bày khác nhau**; màn hình vẽ biểu đồ theo
//   báo cáo này sẽ **thiếu cột** ở những kỳ không có lịch hẹn.
app.MapGet("/api/reports/appointments-by-period-status", async (AppDbContext db, ITenantContext t,
    string? dealerCode, string? reportType, DateTime? fromDate, DateTime? toDate, bool? keepEmptyBuckets) =>
{
    if (string.IsNullOrWhiteSpace(dealerCode))
        return Results.BadRequest(new { error = "Rpt_Ser_App_GroupByDateAndStatus_InvalidDealerCode" });
    if (string.IsNullOrWhiteSpace(reportType))
        return Results.BadRequest(new { error = "Rpt_Ser_App_GroupByDateAndStatus_InvalidReportType" });
    if (fromDate is null || toDate is null) return Results.BadRequest(new { error = "Cần fromDate và toDate." });
    if (fromDate.Value.Date > toDate.Value.Date)
        return Results.BadRequest(new { error = "Rpt_Ser_App_GroupByDateAndStatus_DateFromAfterDateTo" });
    var kind = reportType!.Trim().ToUpperInvariant();
    if (kind != "HOUR" && kind != "DAY" && kind != "MONTH")
        return Results.BadRequest(new { error = "reportType chỉ nhận HOUR, DAY hoặc MONTH." });

    // Bảng mã trạng thái của nguồn — GIÁ TRỊ, và tên cột pivot KHÔNG DẤU.
    var statusName = new Dictionary<string, string>
    {
        ["1"] = "MOITAO", ["2"] = "XACNHAN", ["3"] = "TIEPNHAN", ["4"] = "HUY",
    };

    var dealer = dealerCode!.Trim();
    var from = fromDate.Value.Date;
    var to = toDate.Value.Date.AddDays(1).AddSeconds(-1);

    var buckets = new List<(string MixCode, string MixName, DateTime Start, DateTime End)>();
    if (kind == "HOUR")
        for (var h = 0; h < 24; h++)
        {
            var st = from.AddHours(h);
            buckets.Add((h.ToString(), h.ToString("00"), st, st.AddHours(1).AddSeconds(-1)));
        }
    else if (kind == "DAY")
        for (var d = from; d <= toDate.Value.Date; d = d.AddDays(1))
            buckets.Add((d.ToString("yyyy-MM-dd"), d.ToString("yyyy-MM-dd"), d, d.AddDays(1).AddSeconds(-1)));
    else
    {
        var m = new DateTime(from.Year, from.Month, 1);
        var mEnd = new DateTime(toDate.Value.Year, toDate.Value.Month, 1);
        for (; m <= mEnd; m = m.AddMonths(1))
            buckets.Add((m.ToString("yyyy-MM-01"), m.ToString("yyyy-MM-01"), m, m.AddMonths(1).AddSeconds(-1)));
    }

    var apps = await db.ServiceAppointments.Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer
            && x.AppFrom >= from && x.AppFrom <= to)
        .Select(x => new { x.Id, x.AppNo, x.AppFrom, x.Status }).ToListAsync();

    var rows = buckets.Select(b =>
    {
        var inB = apps.Where(x => x.AppFrom >= b.Start && x.AppFrom <= b.End).ToList();
        decimal Cnt(string code) => inB.Count(x => x.Status == code);
        return new
        {
            b.MixCode, DealerCode = dealer, ReportType = kind, b.MixName,
            DateTimeStart = b.Start, DateTimeEnd = b.End,
            MOITAO = Cnt("1"), XACNHAN = Cnt("2"), TIEPNHAN = Cnt("3"), HUY = Cnt("4"),
            other = (decimal)inB.Count(x => !statusName.ContainsKey(x.Status)),
            total = (decimal)inB.Count,
        };
    }).ToList();

    // Nguồn đi từ bảng KẾT QUẢ nên rổ rỗng biến mất; mặc định ở đây giữ đúng nguồn.
    var keep = keepEmptyBuckets ?? false;
    var items = keep ? rows : rows.Where(r => r.total > 0).ToList();

    return Results.Ok(new
    {
        dealerCode = dealer, reportType = kind,
        from = from.ToString("yyyy-MM-dd"), to = toDate.Value.Date.ToString("yyyy-MM-dd"),
        count = items.Count, appointmentCount = apps.Count, items,
        sourceHourBranchMultipliesBy24 = kind == "HOUR",
        sourceComparesDateAsChar10LosingTime = true,
        statusesOutsidePivot = apps.Where(x => !statusName.ContainsKey(x.Status))
            .Select(x => x.Status).Distinct().ToList(),
        qtyDroppedByMissingElseAndFrozenPivot = (decimal)apps.Count(x => !statusName.ContainsKey(x.Status)),
        emptyBucketsDroppedInSource = true,
        contrastWithSiblingReports = "#506/#511/#515 di tu bang RO nen ro rong van co dong Qty=0",
    });
}).RequireAuthorization();

// ===== 🔴🔴 #517 TRA THẺ DỊCH VỤ CHO MÁY TÍNH BẢNG — **HÀM LIVE CÓ THÂN RỖNG** =====
// Nguồn LIVE (đọc thân WS trước, đúng luật): `HTCWSCarSvTab/WSCarSvTab.asmx.cs:6648` gọi
//   `_biz.RptCrdCardForService_New20200822(` — **không** phải bản trần `RptCrdCardForService` (:3313).
// Endpoint: `GET /api/reports/loyalty-card-for-service`.
//
// 🔴🔴 **TOÀN BỘ PHẦN LẤY DỮ LIỆU BỊ COMMENT — HÀM CHỈ TRẢ VỀ MỘT BẢNG RỖNG**:
//   lọc bỏ mọi dòng bắt đầu bằng `//` trong thân hàm (`Tab.Report.cs:3471..3655`), phần **ĐANG CHẠY**
//   chỉ còn: `DataSet dsGetData = new DataSet();` · `DataTable dt_Return = new DataTable();` ·
//   `dsGetData.Tables.Add(dt_Return);` · `MoveDataTable` · `CommitSafety` · `return mdsFinal`.
//   Khối `#region // Update PlateNo Loyalty` — nơi gọi API Loyalty
//   (`postWebApi_RptCrdCardForService_ClientTabAndDesktop_FixBugChangeServer`, ném lỗi
//   `RptCrdCardForService_FromLoyalty_CardNotFound` / `…_FromLoyalty`) — **bị comment sạch**.
//   ⇒ Máy tính bảng gọi WebMethod này **luôn nhận bảng RỖNG**, không lỗi, không cảnh báo:
//     tính năng **đã chết mà vẫn còn cổng vào**.
//   ⚠️ **Bản trần :3313 cũng vậy** (đếm dòng active: cũng chỉ `new DataTable()` rồi `Tables.Add`)
//     ⇒ không phải "bản mới cắt mất", mà **cả hai bản đều rỗng** — nợ thật của hệ nguồn.
// 📌 Đây là **kiểm tra dương tính cho luật "port dòng ACTIVE, không port dòng COMMENT"**: nếu đọc lướt
//   khối comment mà tưởng là code, sẽ port nguyên một tầng gọi API Loyalty **không hề tồn tại lúc chạy**.
//
// 📌 **Lệch CỐ Ý**: MiniHTC **đã có** bảng thẻ (`LoyaltyCard`, #463) nên endpoint này **trả dữ liệu thật**
//   thay vì tái hiện bảng rỗng — kèm cờ `sourceReturnsEmptyTable` để không ai tưởng là port 1:1.
// ⚠️ Tên hằng lỗi của nguồn dùng **tên hàm trần** (`TError.ErrCarSv.RptCrdCardForService`) trong khi hàm
//   là bản `_New20200822` — chép nguyên văn, không "sửa cho đúng".
app.MapGet("/api/reports/loyalty-card-for-service", async (AppDbContext db, ITenantContext t,
    string? cardNo, string? memberNo) =>
{
    if (string.IsNullOrWhiteSpace(cardNo) && string.IsNullOrWhiteSpace(memberNo))
        return Results.BadRequest(new { error = "Cần cardNo hoặc memberNo." });

    var qy = db.LoyaltyCards.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(cardNo)) qy = qy.Where(x => x.CardNo == cardNo!.Trim());
    if (!string.IsNullOrWhiteSpace(memberNo)) qy = qy.Where(x => x.MemberNo == memberNo!.Trim());

    var items = await qy.OrderByDescending(x => x.Id).Take(200)
        .Select(x => new
        {
            x.Id, x.CardNo, x.MemberNo, x.NetworkID, x.RankPolicyCode,
            x.CardTypeUse, x.CardTypeInit, x.CardTypeUsePrev, x.CardNoPrev,
            x.CardStatus, x.EffDateStart, x.EffDateEnd, x.CardActiveDate,
        }).ToListAsync();

    return Results.Ok(new
    {
        cardNo, memberNo, count = items.Count, items,
        // Nguồn KHÔNG trả dữ liệu: thân hàm LIVE chỉ tạo bảng rỗng.
        sourceReturnsEmptyTable = true,
        sourceLiveFunction = "RptCrdCardForService_New20200822 (Tab.Report.cs:3471)",
        sourceLoyaltyCallCommentedOut = true,
        bareVariantAlsoEmpty = "RptCrdCardForService (:3313)",
        errorConstantUsesBareName = "TError.ErrCarSv.RptCrdCardForService",
        deliberateDivergence = "MiniHTC tra du lieu that tu bang LoyaltyCard (#463)",
    });
}).RequireAuthorization();

// ===== #518 DOANH THU TRUNG BÌNH (máy tính bảng) — VỎ BỌC **GÁN CỨNG KỲ = THÁNG** =====
// Nguồn: `Tab/BizCarSv.Tab.Report.cs:1920 Rpt_Ser_RO_RevenueAvgByForTab` — WebMethod riêng
//   (`HTCWSCarSvTab/WSCarSvTab.asmx.cs:5591`), nhưng thân chỉ là **vỏ bọc** gọi thẳng
//   `Rpt_Ser_RO_RevenueByReportTypeX(…)` (thân thật đã port ở #507).
// Endpoint: `GET /api/reports/ro-revenue-avg-by-month`.
//
// 🔴 **KỲ BÁO CÁO KHÔNG PHẢI THAM SỐ — BỊ GÁN CỨNG**: vỏ bọc truyền `TConst.ReportType.Month`
//   ("MONTH") và `TConst.Flag.Yes` ("1"); **chữ ký WebMethod không hề có tham số kiểu báo cáo**
//   (chỉ `DealerCode`, `ReportDateFrom`, `ReportDateTo`). ⇒ Màn này **luôn** xem theo THÁNG,
//   dù người dùng chọn khoảng ngày lẻ. Không có đường nào để xin GIỜ/NGÀY.
// ⚠️ `Flag.Yes` ở đây chỉ đổi **tên bảng** trả về thành `Rpt_Ser_RO_RevenueByReportType` —
//   xem #507: hai nhánh dùng **chung một câu SQL**. Nên "báo cáo doanh thu trung bình" và
//   "báo cáo số phiếu tiếp nhận" (`Flag.No`) **cùng dữ liệu, khác nhãn**.
// ⇒ Mọi phát hiện #507 áp nguyên: `RevenueAvg` = NULL ở kỳ rỗng (IsNull quên mẫu số) ·
//   mốc là `ActualDeliveryDate` · `Qty` và `QtyRO` trùng nhau.
app.MapGet("/api/reports/ro-revenue-avg-by-month", async (AppDbContext db, ITenantContext t,
    string? dealerCode, DateTime? fromDate, DateTime? toDate) =>
{
    if (string.IsNullOrWhiteSpace(dealerCode))
        return Results.BadRequest(new { error = "Rpt_Ser_RO_RevenueAvgByForTab_InvalidDealerCode" });
    if (fromDate is null || toDate is null) return Results.BadRequest(new { error = "Cần fromDate và toDate." });
    if (fromDate.Value.Date > toDate.Value.Date)
        return Results.BadRequest(new { error = "Rpt_Ser_RO_RevenueAvgByForTab_DateFromAfterDTimeTo" });

    var dealer = dealerCode!.Trim();
    var from = fromDate.Value.Date;
    var to = toDate.Value.Date.AddDays(1).AddSeconds(-1);

    // Kỳ luôn là THÁNG — gán cứng trong vỏ bọc nguồn.
    var buckets = new List<(string MixCode, string MixName, DateTime Start, DateTime End)>();
    {
        var m = new DateTime(from.Year, from.Month, 1);
        var mEnd = new DateTime(toDate.Value.Year, toDate.Value.Month, 1);
        for (; m <= mEnd; m = m.AddMonths(1))
            buckets.Add((m.ToString("yyyy-MM"), m.ToString("MM/yyyy"), m, m.AddMonths(1).AddSeconds(-1)));
    }

    var ros = await db.RepairOrders.Where(x => x.OrgId == t.OrgId && x.DealerCode == dealer
            && x.ActualDeliveryDate != null && x.ActualDeliveryDate >= from && x.ActualDeliveryDate <= to)
        .Select(x => new { x.Id, x.ActualDeliveryDate }).ToListAsync();
    var roIds = ros.Select(x => x.Id).ToList();
    var svc = await db.RoServiceItems.Where(i => i.OrgId == t.OrgId && roIds.Contains(i.RoId))
        .GroupBy(i => i.RoId)
        .Select(g => new { RoId = g.Key, Amt = g.Sum(i => i.Factor * i.Price * (1m + i.Vat * 0.01m)) })
        .ToDictionaryAsync(x => x.RoId, x => x.Amt);
    var prt = await db.RoPartItems.Where(i => i.OrgId == t.OrgId && roIds.Contains(i.RoId))
        .GroupBy(i => i.RoId)
        .Select(g => new { RoId = g.Key, Amt = g.Sum(i => i.Factor * i.NeedQty * i.UnitPrice * (1m + i.Vat * 0.01m)) })
        .ToDictionaryAsync(x => x.RoId, x => x.Amt);

    var items = buckets.Select(b =>
    {
        var inB = ros.Where(r => r.ActualDeliveryDate >= b.Start && r.ActualDeliveryDate <= b.End).ToList();
        decimal? qtyRO = inB.Count == 0 ? null : inB.Count;     // mẫu số để trần như nguồn (#507)
        var sAmt = inB.Sum(r => svc.TryGetValue(r.Id, out var v) ? v : 0m);
        var pAmt = inB.Sum(r => prt.TryGetValue(r.Id, out var v) ? v : 0m);
        return new
        {
            b.MixCode, DealerCode = dealer, ReportType = "MONTH", b.MixName,
            DateTimeStart = b.Start, DateTimeEnd = b.End,
            Qty = (decimal)inB.Count, ServiceAmount = sAmt, PartAmount = pAmt,
            RevenueAvg = qtyRO is null ? (decimal?)null : Math.Round((sAmt + pAmt) / qtyRO.Value, 2),
        };
    }).ToList();

    return Results.Ok(new
    {
        dealerCode = dealer,
        from = from.ToString("yyyy-MM-dd"), to = toDate.Value.Date.ToString("yyyy-MM-dd"),
        tableName = "Rpt_Ser_RO_RevenueByReportType",     // Flag.Yes chỉ đổi tên bảng
        count = items.Count, roCount = ros.Count, items,
        reportTypeHardcodedToMonth = true,
        webMethodHasNoReportTypeParam = true,
        sameSqlAsReceptionCountReport = "#507: hai nhanh dung chung mot cau SQL",
        revenueAvgNullOnEmptyBucket = items.Count(x => x.RevenueAvg is null),
        sharesBodyWith = "/api/reports/ro-revenue-by-period (#507)",
    });
}).RequireAuthorization();

// ===== 🔴 #520 DANH MỤC MÀU BIỂN SỐ — VÀ BA BỘ LỌC **BỊ BỎ IM LẶNG** =====
// Nguồn: `BizCarSv.Master.cs:5743 Mst_PlateColor_Get`. Hàm này **không WS nào gọi**; nó sống qua
//   **kênh vào thứ năm** `TERP.HTCService.ClientService/Services/Mst_PlateColorService.cs:40` (#519).
// Endpoint: `GET /api/platecolormsts`. **§12** thêm bảng + entity `PlateColorMst` + `DbSet` + Seeder.
//
// 🔴🔴 **BA THAM SỐ LỌC ĐỀU CHẾT** (luật #410, lần này truy được tới **giá trị thật**):
//     `BuildClause("and", "t.PlateColorCode", strPlateColorCodeList, "@p", ref …)`
//     `BuildClause("and", "t.PlateColorName", strPlateColorNameList, …)`
//     `BuildClause("and", "t.FlagActive",     strFlagActiveList,     …)`
//   `BuildClause` (`CommonUtils/DataUtils.cs`) chỉ sinh mệnh đề khi chuỗi **bắt đầu bằng toán tử**
//   (`=` · `!=` · `>` · `<` · `>=` · `<=` · `LIKE` · `NOT LIKE` · `IS NULL` · `IS NOT NULL` · `IN` · `NOT IN`);
//   **không có nhánh `else`** ⇒ chuỗi không toán tử để `nCase = 0` ⇒ **không nối gì cả**.
//   Mà bên gọi (`Mst_PlateColorService`) truyền **thẳng giá trị người dùng nhập** (`PlateColorCode`,
//   `platecolorname`, `flagactive`) — **không bọc toán tử**. ⇒ Cả ba điều kiện **biến mất**, hàm
//   **luôn trả TOÀN BỘ danh mục**, kể cả bản ghi `FlagActive = '0'` (đã ngừng dùng).
//   ⇒ Màn chọn màu biển số hiện **cả màu đã khai tử**, và ô tìm kiếm **không có tác dụng**.
//   Port: lọc **thật** + trả cờ `sourceFiltersSilentlyDropped` để nêu đúng chỗ lệch.
// ⚠️ `order by t.IndexColor` — sắp theo **cột thứ tự riêng**, không theo mã/tên; `IndexColor` NULL thì
//   SQL Server xếp **lên đầu**. Port giữ đúng thứ tự đó (NULL trước) thay vì sắp theo mã.
// ⚠️ Câu lấy `t.*` ⇒ hình dạng kết quả **bám theo lược đồ bảng**; entity phía client liệt kê bốn cột
//   (`PlateColorCode` · `PlateColorName` · `ColorHexCode` · `FlagActive`) cộng `IndexColor` dùng để sắp.
app.MapGet("/api/platecolormsts", async (AppDbContext db, ITenantContext t,
    string? code, string? name, string? flagActive, bool? all) =>
{
    var qy = db.PlateColorMsts.Where(x => x.OrgId == t.OrgId);
    // Nguồn ĐỊNH lọc ba tham số này nhưng cả ba bị BuildClause bỏ im lặng — ở đây lọc thật.
    if (!string.IsNullOrWhiteSpace(code)) qy = qy.Where(x => x.PlateColorCode == code!.Trim());
    if (!string.IsNullOrWhiteSpace(name)) qy = qy.Where(x => x.PlateColorName != null
        && x.PlateColorName!.Contains(name!.Trim()));
    if (!string.IsNullOrWhiteSpace(flagActive)) qy = qy.Where(x => x.FlagActive == flagActive!.Trim());
    else if (all != true) qy = qy.Where(x => x.FlagActive == "1");

    var items = await qy
        .OrderBy(x => x.IndexColor == null ? 0 : 1).ThenBy(x => x.IndexColor)   // NULL lên đầu, đúng SQL Server
        .ThenBy(x => x.PlateColorCode)
        .Select(x => new { x.Id, x.PlateColorCode, x.PlateColorName, x.ColorHexCode, x.IndexColor, x.FlagActive })
        .ToListAsync();

    return Results.Ok(new
    {
        count = items.Count, items,
        tableName = "Mst_PlateColor",
        sourceFiltersSilentlyDropped = new[] { "PlateColorCode", "PlateColorName", "FlagActive" },
        sourceReturnsAllRowsIncludingInactive = true,
        sourceOrdersByIndexColorOnly = true,
        liveOnlyViaClientServiceChannel = "Mst_PlateColorService.cs:40 (#519)",
    });
}).RequireAuthorization();

// ===== 🔴🔴 #523 TẢI TỆP TỪ MÁY TÍNH BẢNG — **GHI FILE HAI LẦN, GUARD TOÀN VẸN VÔ NGHĨA** =====
// Nguồn: `BizCarSv.UploadFile.cs:1986 UploadFile_ForTab` — sống qua **kênh ClientService** (#519).
// Endpoint: `POST /api/uploads/tab`. **§12** thêm entity `UploadedFile` + `DbSet` + Seeder.
//
// 🔴 **GHI RA ĐĨA HAI LẦN, LẦN ĐẦU THÀNH RÁC** (đọc nguyên văn khối `#region // Convert Input`):
//     `filePath = "UploadedFiles\\" + yyyyMMdd.HHmmss.ffffff + Guid.NewGuid() + "\\";`
//     `EnsureDirectoryExists(path); path += fileName; File.WriteAllBytes(path, fileContent);`   ← lần 1
//     … rồi `filePath = "UploadedFiles\\" + fileName; path = rootPath + filePath;`
//     `File.WriteAllBytes(path, fileContent);`                                                  ← lần 2
//   ⇒ Mỗi lần tải lên đẻ ra **một thư mục con theo GUID chứa một bản sao KHÔNG AI THAM CHIẾU**
//     (đường dẫn trả về là bản **lần hai**). Không có chỗ nào xoá ⇒ **đĩa phình vô hạn**.
// 🔴 **GUARD TOÀN VẸN PHÁT HIỆN HỎNG NHƯNG KHÔNG DỪNG**:
//     `byte[] fileContent1 = File.ReadAllBytes(path);`
//     `if (fileContent.SequenceEqual(fileContent1) == false) { fileName = <thêm tiền tố lần nữa> + fileName; }`
//   Đọc lại thấy **khác** — tức ghi hỏng — mà chỉ **đổi tên** rồi vẫn ghi tiếp, **không ném lỗi**,
//   không báo về client. ⇒ Guard tồn tại **để yên tâm**, không để bảo vệ. (Họ #407: guard chết.)
// 🔴 **VA CHẠM TÊN Ở LẦN GHI THỨ HAI**: tên cuối là `<yyyyMMdd_HHmmss_fff> + fileName` đặt **thẳng**
//   trong `UploadedFiles\` — hai tệp cùng tên trong **cùng mili-giây** thì `WriteAllBytes` **ghi đè
//   im lặng**. Bản lần một có GUID nên không đụng; bản **được dùng** thì có.
// ⚠️ Guard loại tệp: `Path.GetExtension(fileName).ToUpper()` rồi `Mst_FileTypeUpload_CheckDB(…, Flag.Yes)`
//   ⇒ đuôi tệp (**VIẾT HOA**, kèm dấu chấm) phải có trong danh mục. Tệp **không có đuôi** ⇒ mã rỗng `""`
//   vẫn đem đi tra ⇒ phụ thuộc việc danh mục có dòng rỗng hay không.
// ⚠️ `GC.Collect()` gọi tay ngay trước `Convert.FromBase64String` (chú thích nguồn: *"tránh đầy bộ nhớ"*)
//   ⇒ dấu hiệu nguồn **không giới hạn kích thước** tệp: base64 nạp trọn vào RAM.
// 📌 **Lệch CỐ Ý**: MiniHTC **lưu nội dung trong DB** (nền chạy không có đĩa bền) và **ghi MỘT lần**;
//   vẫn trả `filePath` đúng khuôn nguồn để client cũ không vỡ, kèm cờ nêu rõ.
app.MapPost("/api/uploads/tab", async (UploadFileDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.FileName))
        return Results.BadRequest(new { error = "Cần fileName." });
    if (string.IsNullOrWhiteSpace(dto.UploadFileAsBase64String))
        return Results.BadRequest(new { error = "Cần uploadFileAsBase64String." });

    // Đuôi tệp VIẾT HOA kèm dấu chấm — đúng `Path.GetExtension(...).ToUpper()` của nguồn.
    var ext = Path.GetExtension(dto.FileName!)?.ToUpperInvariant() ?? "";
    var typeOk = await db.MstFileTypes.AnyAsync(x => x.OrgId == t.OrgId && x.FileType == ext);
    if (!typeOk)
        return Results.BadRequest(new
        {
            error = "Mst_FileTypeUpload_CheckDB: loại tệp không có trong danh mục.",
            fileTypeCode = ext,
            noExtensionBecomesEmptyCode = ext.Length == 0,
        });

    byte[] content;
    try { content = Convert.FromBase64String(dto.UploadFileAsBase64String!); }
    catch (FormatException) { return Results.BadRequest(new { error = "uploadFileAsBase64String không hợp lệ." }); }

    // Nguồn gắn tiền tố thời gian rồi ghi thẳng vào UploadedFiles\ ⇒ giữ đúng khuôn tên.
    var stamped = DateTime.Now.ToString("yyyyMMdd_HHmmss_fff") + dto.FileName!.Trim();
    var filePath = "UploadedFiles\\" + stamped;

    // Nguồn ghi đè im lặng khi trùng tên; ở đây phát hiện và BÁO, không giấu.
    var clash = await db.UploadedFiles.AnyAsync(x => x.OrgId == t.OrgId && x.FilePath == filePath);

    var f = new UploadedFile
    {
        OrgId = t.OrgId, FileName = stamped, FilePath = filePath, FileTypeCode = ext,
        Content = content, SizeBytes = content.LongLength,
    };
    db.UploadedFiles.Add(f);
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        f.Id, f.FileName, f.FilePath, f.FileTypeCode, f.SizeBytes,
        remark = filePath,                       // nguồn trả đường dẫn qua CMyDataSet.SetRemark
        message = "Upload file thành công!",     // chuỗi nguyên văn của nguồn
        nameClashDetected = clash,
        sourceWritesFileTwice = "ban 1 vao UploadedFiles\\<timestamp><guid>\\ khong ai tham chieu",
        sourceIntegrityCheckDoesNotAbort = true,
        sourceOverwritesOnSameMillisecond = true,
        sourceHasNoSizeLimit = "GC.Collect() truoc FromBase64String",
        storedInDatabaseNotDisk = true,
    });
}).RequireAuthorization();

// ===== 🔴 #524 CHI TIẾT PHIẾU TIẾP NHẬN — TRẢ NỢ `ds_Ser_ReceptionFDtl` CỦA #522 =====
// Nguồn: `BizCarSv.ZTemp.cs:21199 Ser_ReceptionF_ReceptionX_New20210727`, khối
//   `#region //// Refine and Check Ser_ReceptionFDtl`. Endpoint: `POST /api/receptions/{no}/details`
//   + `GET /api/receptions/{no}/details`. **§12**: entity `ReceptionDetail` + `DbSet` + Seeder.
//
// 🔴 **BẢNG ĐẦU VÀO PHẢI ĐÚNG TÊN, KHÔNG THÌ NÉM LỖI**: nguồn kiểm
//   `if (!ds_Ser_ReceptionFDtl.Tables.Contains("Ser_ReceptionFDtl")) throw`
//   `Ser_ReceptionF_SaveX_InvalidSer_Ser_ReceptionFDtlTbl` ⇒ **tên bảng trong DataSet là một phần
//   của hợp đồng API**, không phải chi tiết nội bộ.
// 🔴 **MỘT CỘT ĐƯỢC TẠO RỒI KHÔNG BAO GIỜ GÁN**: bốn lệnh `MyForceNewColumn` thêm `ReceptionFNo`,
//   `DeliveryAudStatus`, `ReceptionFStatusDtl`, `LogLUDateTime`, `LogLUBy`; nhưng vòng lặp bên dưới
//   chỉ gán **bốn** trong số đó — `DeliveryAudStatus` **không hề được gán** ⇒ lưu xuống **rỗng**.
//   Đây **không phải lỗi**: cột ấy dành cho khâu **GIAO XE** điền sau. Nhưng nếu port theo "có cột thì
//   phải có giá trị" sẽ **bịa dữ liệu**. Ghi cờ `deliveryAudStatusFilledLaterAtDelivery`.
// ⚠️ HẰNG ≠ GIÁ TRỊ (mở `Const.Main.cs:212`): `ReceptionFStatus.Pending = **"P"**` (*Tiếp nhận*) ·
//   `Approve = **"A"**` (*Giao xe*) — **một ký tự**, không phải chữ "Pending". Nguồn gán cứng `"P"`
//   cho **mọi** dòng chi tiết lúc tiếp nhận. ⚠️ Cột `Reception.Status` của MiniHTC lại đang dùng chuỗi
//   `"Pending"` (bản port cũ) ⇒ **hai bảng, hai bảng mã trạng thái** — nêu cờ, không tự sửa lan sang
//   dữ liệu đã có.
// 🔴 Mỗi dòng chi tiết bị tra danh mục: `Ser_Mst_ReceptionFAudit_CheckDB(code, type, Flag.Yes, Flag.Active)`
//   ⇒ đầu mục kiểm tra phải **tồn tại VÀ đang hoạt động**; sai một dòng là **cả phiếu ném lỗi**
//   (guard nằm TRONG vòng lặp, trước mọi lệnh ghi) ⇒ **tất cả hoặc không gì cả**.
//   MiniHTC chưa có master `Ser_Mst_ReceptionFAudit` ⇒ kiểm qua `MasterItem` nếu có danh mục,
//   không có thì **cho qua** và nêu cờ `auditMasterNotModelled` (không giả vờ đã kiểm).
// ⚠️ Chuẩn hoá đầu vào theo `"StdParam"` (mã) / `"StdFlag"` (cờ) / `""` (ghi chú giữ nguyên) —
//   `ReceptionAudStatus` là **CỜ** nên chỉ nhận "1"/"0".
app.MapPost("/api/receptions/{no}/details", async (string no, List<ReceptionDetailDto> rows,
    AppDbContext db, ITenantContext t) =>
{
    var rec = await db.Receptions.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ReceptionFNo == no);
    if (rec is null) return Results.NotFound(new { error = "Không tìm thấy phiếu tiếp nhận: " + no });
    if (rows is null || rows.Count == 0)
        return Results.BadRequest(new { error = "Ser_ReceptionF_SaveX_InvalidSer_Ser_ReceptionFDtlTbl" });

    const string kReceptionFStatusPending = "P";      // TConst.ReceptionFStatus.Pending — GIÁ TRỊ, không phải tên
    var auditMaster = await db.Masters
        .Where(x => x.OrgId == t.OrgId && x.Category == "ReceptionFAudit")   // #526 đã có master riêng ReceptionFAuditMsts
        .Select(x => new { x.Code, x.Status }).ToListAsync();

    // Guard nằm TRONG vòng lặp và TRƯỚC mọi lệnh ghi ⇒ sai một dòng là hỏng cả phiếu.
    var bad = new List<object>();
    foreach (var r in rows)
    {
        if (string.IsNullOrWhiteSpace(r.ReceptionFAudCode) || string.IsNullOrWhiteSpace(r.ReceptionFAudType))
        { bad.Add(new { r.ReceptionFAudCode, r.ReceptionFAudType, why = "thieu ma hoac loai" }); continue; }
        if (auditMaster.Count > 0)
        {
            var m = auditMaster.FirstOrDefault(x => x.Code == r.ReceptionFAudCode!.Trim());
            if (m is null) bad.Add(new { r.ReceptionFAudCode, r.ReceptionFAudType, why = "khong co trong danh muc" });
            else if (m.Status != "1") bad.Add(new { r.ReceptionFAudCode, r.ReceptionFAudType, why = "dau muc ngung hoat dong" });
        }
        if (!string.IsNullOrWhiteSpace(r.ReceptionAudStatus) && r.ReceptionAudStatus!.Trim() is not ("1" or "0"))
            bad.Add(new { r.ReceptionFAudCode, r.ReceptionFAudType, why = "ReceptionAudStatus la CO, chi nhan 1 hoac 0" });
    }
    if (bad.Count > 0)
        return Results.BadRequest(new
        {
            error = "Ser_Mst_ReceptionFAudit_CheckDB: co dong khong hop le — nguon huy CA phieu.",
            allOrNothing = true, invalidRows = bad,
        });

    var now = DateTime.Now;
    foreach (var r in rows)
        db.ReceptionDetails.Add(new ReceptionDetail
        {
            OrgId = t.OrgId, ReceptionFNo = no,
            ReceptionFAudCode = r.ReceptionFAudCode!.Trim(), ReceptionFAudType = r.ReceptionFAudType!.Trim(),
            ReceptionAudStatus = r.ReceptionAudStatus,
            // DeliveryAudStatus: nguồn KHÔNG gán ở khâu tiếp nhận — để rỗng, đúng nguồn.
            ReceptionFStatusDtl = kReceptionFStatusPending,
            Remark = r.Remark, LogLUDateTime = now,
        });
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        receptionFNo = no, count = rows.Count,
        receptionFStatusDtl = kReceptionFStatusPending,
        deliveryAudStatusFilledLaterAtDelivery = true,
        auditMasterNotModelled = auditMaster.Count == 0,
        inputTableNameIsPartOfContract = "Ser_ReceptionFDtl",
        statusVocabMismatch = "ReceptionDetails dung \"P\" (dung nguon) con Receptions dung \"Pending\" (ban port cu)",
        sourceWritesThreeDatabases = "Main + WH + Dealer",
    });
}).RequireAuthorization();

app.MapGet("/api/receptions/{no}/details", async (string no, AppDbContext db, ITenantContext t) =>
{
    var items = await db.ReceptionDetails.Where(x => x.OrgId == t.OrgId && x.ReceptionFNo == no)
