        emptyDeliveryAudStatusIsExpected = items.Count(x => string.IsNullOrEmpty(x.DeliveryAudStatus)),
    });
}).RequireAuthorization();

// ===== #525 TỆP ĐÍNH KÈM PHIẾU TIẾP NHẬN — TRẢ NỢ `ds_Ser_ReceptionFAttachFile` (#522) =====
// Nguồn: `ZTemp.cs` khối `#region //// Refine and Check Ser_ReceptionFAttachFile` (cùng hàm #524).
// Endpoint: `POST /api/receptions/{no}/attachfiles` + `GET`. **§12**: entity + `DbSet` + Seeder.
//
// 📐 **DIFF với khối chi tiết (#524) — cùng khuôn, khác ở đúng ba điểm** (luật #414: diff trước, và
//   khác biệt nằm ở DANH SÁCH CỘT):
//   1) tên bảng hợp đồng đổi thành `Ser_ReceptionFAttachFile`, lỗi ném là
//      `Ser_ReceptionF_SaveX_InvalidSer_**ReceptionFAttachFileTbl**` — ⚠️ **thiếu chữ `Ser_`** so với
//      lỗi của khối chi tiết (`…InvalidSer_**Ser_**ReceptionFDtlTbl`). Hai hằng lệch nhau **một tiền tố**
//      trong cùng một hàm; chép **nguyên văn**, không "sửa cho đều".
//   2) **KHÔNG có guard tra danh mục** — khối chi tiết gọi `Ser_Mst_ReceptionFAudit_CheckDB` cho từng dòng,
//      còn khối này **không kiểm gì cả**: `ReceptionFileType` chỉ được `StdParam` (chuẩn hoá chuỗi),
//      **không** đối chiếu `Mst_FileTypeUpload` như `UploadFile_ForTab` (#523) vẫn làm.
//      ⇒ **Cùng hệ, hai đường nạp tệp, một đường kiểm loại tệp và một đường không.**
//   3) chỉ **ba** cột được máy điền (`ReceptionFNo`, `LogLUDateTime`, `LogLUBy`) và **cả ba đều được gán**
//      ⇒ không có ca "tạo cột rồi bỏ trống" như `DeliveryAudStatus` của #524 (kiểm tra âm tính).
// 🔴 `StdDataInTable(… "", "ReceptionFilePath", "", "ReceptionFileName" …)` — mã chuẩn hoá là **chuỗi rỗng**
//   ⇒ hai cột đường dẫn/tên tệp **không được chuẩn hoá gì**: khoảng trắng thừa, hoa thường, dấu `\\` hay `/`
//   đều giữ nguyên như client gửi. Kết hợp với #523 (đường dẫn do server sinh) thì **hai nguồn sinh đường dẫn**
//   cùng ghi vào một bảng.
// ⚠️ Nguồn lưu **đường dẫn**, không lưu nội dung ⇒ tệp thật nằm ngoài DB (thư mục `UploadedFiles\` của #523).
app.MapPost("/api/receptions/{no}/attachfiles", async (string no, List<ReceptionAttachFileDto> rows,
    AppDbContext db, ITenantContext t) =>
{
    var rec = await db.Receptions.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.ReceptionFNo == no);
    if (rec is null) return Results.NotFound(new { error = "Không tìm thấy phiếu tiếp nhận: " + no });
    if (rows is null || rows.Count == 0)
        return Results.BadRequest(new { error = "Ser_ReceptionF_SaveX_InvalidSer_ReceptionFAttachFileTbl" });

    var now = DateTime.Now;
    foreach (var r in rows)
        db.ReceptionAttachFiles.Add(new ReceptionAttachFile
        {
            OrgId = t.OrgId, ReceptionFNo = no,
            FileIndex = r.FileIndex?.Trim(),
            // Nguồn KHÔNG chuẩn hoá hai cột này (mã "") — giữ nguyên văn client gửi.
            ReceptionFilePath = r.ReceptionFilePath,
            ReceptionFileName = r.ReceptionFileName,
            ReceptionFileType = r.ReceptionFileType?.Trim(),
            Remark = r.Remark, LogLUDateTime = now,
        });
    await db.SaveChangesAsync();

    return Results.Ok(new
    {
        receptionFNo = no, count = rows.Count,
        noFileTypeMasterCheckInSource = true,
        contrastWithUploadEndpoint = "#523 UploadFile_ForTab CO kiem Mst_FileTypeUpload, duong nay KHONG",
        pathAndNameNotStandardised = true,
        errorConstantMissesSerPrefix = "Ser_ReceptionF_SaveX_InvalidSer_ReceptionFAttachFileTbl",
        storesPathNotContent = true,
    });
}).RequireAuthorization();

app.MapGet("/api/receptions/{no}/attachfiles", async (string no, AppDbContext db, ITenantContext t) =>
{
    var items = await db.ReceptionAttachFiles.Where(x => x.OrgId == t.OrgId && x.ReceptionFNo == no)
        .OrderBy(x => x.Id)
        .Select(x => new { x.Id, x.FileIndex, x.ReceptionFilePath, x.ReceptionFileName,
            x.ReceptionFileType, x.Remark, x.LogLUDateTime, x.LogLUBy })
        .ToListAsync();
    return Results.Ok(new { receptionFNo = no, count = items.Count, items });
}).RequireAuthorization();

// ===== 🔴🔴 #526 MASTER ĐẦU MỤC KIỂM TRA — **PHÂN TRANG BỊ COMMENT, VẪN TRẢ TỔNG SỐ** =====
// Nguồn: `BizCarSv.Tab.cs:14946 Ser_Mst_ReceptionFAudit_Get` (vỏ bọc) → `…_GetX` (`:15070`, có SQL).
// Endpoint: `GET /api/receptionfauditmsts`. **§12**: entity + `DbSet` + Seeder. Đây là master mà #524
//   cần để tra `Ser_Mst_ReceptionFAudit_CheckDB` — nay có thật, không còn `auditMasterNotModelled`.
//
// 🔴🔴 **HAI DÒNG PHÂN TRANG ĐỀU BỊ COMMENT** (đúng luật *port dòng ACTIVE*):
//     `--and (t.MyIdxSeq >= @nFilterRecordStart)`
//     `--and (t.MyIdxSeq <= @nFilterRecordEnd)`
//   Hai tham số `strFt_RecordStart` / `strFt_RecordCount` **vẫn được nhận, vẫn được `Convert.ToInt64`,**
//   **vẫn bind vào câu lệnh** — nhưng **không mệnh đề nào dùng** ⇒ **phân trang KHÔNG có tác dụng**:
//   mọi lời gọi trả **toàn bộ** danh mục. Trong khi đó bảng `MySummaryTable` **vẫn trả `Count(0)`**
//   ⇒ client thấy tổng số đúng, tưởng đang phân trang, thực ra **luôn nhận hết**.
//   ⚠️ Với danh mục lớn thì đây là lỗi **hiệu năng + băng thông**, không phải lỗi số liệu — nêu cờ,
//     và bản port **có phân trang thật** (`skip`/`take`) kèm `sourcePagingCommentedOut`.
// 🔴 `Convert.ToInt64(strFt_RecordStart)` **không có guard rỗng** ⇒ client không truyền là **ném lỗi**
//   `FormatException` ngay, dù giá trị đó rốt cuộc **không được dùng** vào đâu cả.
// ⚠️ `select distinct identity(bigint, 0, 1) MyIdxSeq … order by ReceptionFAudCode, ReceptionFAudType`
//   — `ORDER BY` nằm trên `SELECT … INTO` (luật #415): nó **không** bảo đảm thứ tự của kết quả TRẢ VỀ,
//   chỉ ảnh hưởng cách đánh số `identity`. Câu cuối lấy `t.MyIdxSeq, smrfa.*` **không có `order by`**
//   ⇒ thứ tự dòng là **tuỳ engine**. Port **sắp tường minh** theo (mã, loại) + cờ `sourceHasNoOrderBy`.
// ⚠️ Cờ `strIsGet_Ser_Mst_ReceptionFAudit`: chỉ cần **khác rỗng** (không so giá trị) mới ghép khối
//   trả chi tiết; rỗng ⇒ macro giữ `"-- Nothing."` ⇒ **chỉ có bảng tổng số**, không có dòng nào.
// ⚠️ Bảng nằm ở **DB khác**: `[@strDBName_CommonCenter].[dbo].Ser_Mst_ReceptionFAudit` (thay bằng
//   `_strConfig_DBName_Main`) ⇒ master dùng chung toàn hệ, không theo đại lý.
// ⚠️ Ba `BuildClause` (`ReceptionFAudCode` · `ReceptionFAudType` · `FlagActive`) — cùng bẫy #410/#520:
//   không có tiền tố toán tử là **bỏ im lặng**. Bản port lọc thật.
app.MapGet("/api/receptionfauditmsts", async (AppDbContext db, ITenantContext t,
    string? code, string? type, string? flagActive, int? recordStart, int? recordCount, bool? isGetDetail) =>
{
    var qy = db.ReceptionFAuditMsts.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(code)) qy = qy.Where(x => x.ReceptionFAudCode == code!.Trim());
    if (!string.IsNullOrWhiteSpace(type)) qy = qy.Where(x => x.ReceptionFAudType == type!.Trim());
    if (!string.IsNullOrWhiteSpace(flagActive)) qy = qy.Where(x => x.FlagActive == flagActive!.Trim());

    // MySummaryTable: nguồn LUÔN trả tổng số, kể cả khi không lấy chi tiết.
    var myCount = await qy.CountAsync();

    // Nguồn chỉ ghép khối chi tiết khi cờ KHÁC RỖNG (không so giá trị).
    var wantDetail = isGetDetail ?? true;
    var start = Math.Max(0, recordStart ?? 0);
    var count = recordCount is > 0 ? recordCount!.Value : myCount;

    var items = wantDetail
        ? await qy.OrderBy(x => x.ReceptionFAudCode).ThenBy(x => x.ReceptionFAudType)   // nguồn KHÔNG sắp ở câu cuối
            .Skip(start).Take(count)
            .Select(x => new { x.Id, x.ReceptionFAudCode, x.ReceptionFAudType, x.ReceptionFAudName, x.FlagActive })
            .ToListAsync()
        : new();

    return Results.Ok(new
    {
        myCount, count = items.Count, items,
        tableNames = new[] { "MySummaryTable", "Ser_Mst_ReceptionFAudit" },
        sourcePagingCommentedOut = "--and (t.MyIdxSeq >= @nFilterRecordStart) / <= @nFilterRecordEnd",
        sourceAlwaysReturnsAllRows = true,
        sourceThrowsOnEmptyRecordStart = "Convert.ToInt64 khong co guard rong",
        sourceHasNoOrderBy = "cau cuoi lay t.MyIdxSeq, smrfa.* ma khong co order by",
        detailFlagIsPresenceNotValue = true,
        masterLivesInCommonCenterDb = true,
    });
}).RequireAuthorization();

// ===== 🔴 #528 PHÂN CÔNG CÔNG VIỆC — **BẢY CÔNG ĐOẠN GÕ CỨNG, GỬI RỖNG KHÔNG XOÁ ĐƯỢC** =====
// Nguồn: `BizCarSv.AssignmentOfWork.cs:23 Ser_AssignmentWork_Create` (vỏ bọc) → `…_CreateX` (`:203`).
//   Sống qua **kênh ClientService** (#519). Endpoint: `POST /api/serassignmentworks` + `GET`.
// **§12**: thêm 21 cột kế hoạch + `ROID` + 2 cột loại công việc + 4 cột nhật ký (entity + Seeder + DTO + GET/POST).
//
// 🔴 **BẢY NHÓM CÔNG ĐOẠN GÕ CỨNG VÀO CHỮ KÝ HÀM**: `SCC · SCD · SCN · SCS · SCDB · SCLR · SCKSC`,
//   mỗi nhóm ba tham số (`…PlanStartDTime` · `…PlanFinishDTime` · `…CavityID`) ⇒ **21 tham số**.
//   Thêm một công đoạn mới là phải **sửa chữ ký WebMethod** — danh sách đóng băng ở tầng API
//   (họ #413/#512, nhưng lần này đóng băng ngay trong **hợp đồng gọi**, không phải trong SQL).
// 🔴 **MỌI TRƯỜNG ĐỀU BỌC `if (!StringUtils.IsEmpty(...))`** ⇒ gửi chuỗi rỗng **không ghi gì**:
//   ở tạo mới thì cột để trống, nhưng ở **sửa** (`Ser_AssignmentWork_Update` cùng khuôn) thì
//   **không có cách nào XOÁ một mốc kế hoạch đã đặt** — muốn bỏ lịch phải nhập đè giá trị khác.
//   Port giữ đúng (bỏ qua `null`/rỗng) và nêu cờ `emptyMeansKeepNotClear`.
// 🔴 Guard trùng khoang/thời gian gọi **bảy lần**, mỗi nhóm một lần:
//   `MyCheck_SerAssignmentWork_PlanDateTime_Cavity_20211007(_dbDealer, …, <nhóm>CavityID, start, finish)`
//   ⇒ kiểm **theo từng nhóm**, **không** kiểm chéo giữa các nhóm: hai công đoạn khác nhau có thể
//     đặt **cùng một khoang, cùng khung giờ** mà không ai chặn.
// 🔴 `dt_Ser_AssignmentWork.Rows[0]["ROID"] = Convert.ToInt32(strROID);` — **không guard rỗng**
//   ⇒ thiếu `ROID` là `FormatException` (họ #526).
// ⚠️ Ghi **ba** DB: `_dbMain.SaveData` → sao chép rồi `_dbWH.SaveData` → `_dbDealer.SaveData` nếu
//   `!bIsWSMain`. ⚠️ `SetDataRowStateOfAllRows(ref …, DataRowState.Added)` được gọi **HAI lần liên tiếp**
//   trên cùng bảng — lần thứ hai **thừa** (trạng thái đã là `Added`): câu lệnh chết, vô hại.
app.MapPost("/api/serassignmentworks", async (SerAssignmentWorkDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.RONo) && string.IsNullOrWhiteSpace(dto.ROID))
        return Results.BadRequest(new { error = "Cần RONo hoặc ROID (nguồn Convert.ToInt32(strROID) không guard rỗng)." });

    // MyCheck_Ser_RO: lệnh phải có thật.
    var ro = await db.RepairOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId
        && (x.RONo == dto.RONo || x.Id.ToString() == dto.ROID));
    if (ro is null) return Results.BadRequest(new { error = "MyCheck_Ser_RO: không tìm thấy lệnh sửa chữa." });

    // Bảy guard theo NHÓM — nguồn không kiểm chéo giữa các nhóm.
    if (dto.SCCPlanStartDTime is not null && dto.SCCPlanFinishDTime is not null
        && dto.SCCPlanStartDTime > dto.SCCPlanFinishDTime)
        return Results.BadRequest(new { error = "MyCheck_SerAssignmentWork_PlanDateTime_Cavity_20211007: SCC bat dau sau ket thuc." });
    if (dto.SCDPlanStartDTime is not null && dto.SCDPlanFinishDTime is not null
        && dto.SCDPlanStartDTime > dto.SCDPlanFinishDTime)
        return Results.BadRequest(new { error = "MyCheck_SerAssignmentWork_PlanDateTime_Cavity_20211007: SCD bat dau sau ket thuc." });
    if (dto.SCNPlanStartDTime is not null && dto.SCNPlanFinishDTime is not null
        && dto.SCNPlanStartDTime > dto.SCNPlanFinishDTime)
        return Results.BadRequest(new { error = "MyCheck_SerAssignmentWork_PlanDateTime_Cavity_20211007: SCN bat dau sau ket thuc." });
    if (dto.SCSPlanStartDTime is not null && dto.SCSPlanFinishDTime is not null
        && dto.SCSPlanStartDTime > dto.SCSPlanFinishDTime)
        return Results.BadRequest(new { error = "MyCheck_SerAssignmentWork_PlanDateTime_Cavity_20211007: SCS bat dau sau ket thuc." });
    if (dto.SCDBPlanStartDTime is not null && dto.SCDBPlanFinishDTime is not null
        && dto.SCDBPlanStartDTime > dto.SCDBPlanFinishDTime)
        return Results.BadRequest(new { error = "MyCheck_SerAssignmentWork_PlanDateTime_Cavity_20211007: SCDB bat dau sau ket thuc." });
    if (dto.SCLRPlanStartDTime is not null && dto.SCLRPlanFinishDTime is not null
        && dto.SCLRPlanStartDTime > dto.SCLRPlanFinishDTime)
        return Results.BadRequest(new { error = "MyCheck_SerAssignmentWork_PlanDateTime_Cavity_20211007: SCLR bat dau sau ket thuc." });
    if (dto.SCKSCPlanStartDTime is not null && dto.SCKSCPlanFinishDTime is not null
        && dto.SCKSCPlanStartDTime > dto.SCKSCPlanFinishDTime)
        return Results.BadRequest(new { error = "MyCheck_SerAssignmentWork_PlanDateTime_Cavity_20211007: SCKSC bat dau sau ket thuc." });

    var w = new SerAssignmentWork
    {
        OrgId = t.OrgId, RONo = ro.RONo, ROID = dto.ROID ?? ro.Id.ToString(),
        CreateDTime = DateTime.Now, LogLUDateTime = DateTime.Now,
    };
    // Gửi rỗng = KHÔNG ghi (đúng nguồn).
    if (dto.SCCPlanStartDTime is not null) w.SCCPlanStartDTime = dto.SCCPlanStartDTime;
    if (dto.SCCPlanFinishDTime is not null) w.SCCPlanFinishDTime = dto.SCCPlanFinishDTime;
    if (!string.IsNullOrWhiteSpace(dto.SCCCavityID)) w.SCCCavityID = dto.SCCCavityID;
    if (dto.SCDPlanStartDTime is not null) w.SCDPlanStartDTime = dto.SCDPlanStartDTime;
    if (dto.SCDPlanFinishDTime is not null) w.SCDPlanFinishDTime = dto.SCDPlanFinishDTime;
    if (!string.IsNullOrWhiteSpace(dto.SCDCavityID)) w.SCDCavityID = dto.SCDCavityID;
    if (dto.SCNPlanStartDTime is not null) w.SCNPlanStartDTime = dto.SCNPlanStartDTime;
    if (dto.SCNPlanFinishDTime is not null) w.SCNPlanFinishDTime = dto.SCNPlanFinishDTime;
    if (!string.IsNullOrWhiteSpace(dto.SCNCavityID)) w.SCNCavityID = dto.SCNCavityID;
    if (dto.SCSPlanStartDTime is not null) w.SCSPlanStartDTime = dto.SCSPlanStartDTime;
    if (dto.SCSPlanFinishDTime is not null) w.SCSPlanFinishDTime = dto.SCSPlanFinishDTime;
    if (!string.IsNullOrWhiteSpace(dto.SCSCavityID)) w.SCSCavityID = dto.SCSCavityID;
    if (dto.SCDBPlanStartDTime is not null) w.SCDBPlanStartDTime = dto.SCDBPlanStartDTime;
    if (dto.SCDBPlanFinishDTime is not null) w.SCDBPlanFinishDTime = dto.SCDBPlanFinishDTime;
    if (!string.IsNullOrWhiteSpace(dto.SCDBCavityID)) w.SCDBCavityID = dto.SCDBCavityID;
    if (dto.SCLRPlanStartDTime is not null) w.SCLRPlanStartDTime = dto.SCLRPlanStartDTime;
