        .OrderBy(x => x.FileIndex).Select(x => new { x.FileIndex, x.GPSFilePath, x.GPSFileName,
            x.GPSFileType, x.Remark, x.LogLUDateTime, x.LogLUBy }).ToListAsync();
    return Results.Ok(new { gpsClaimNo = no, count = items.Count, items });
