    int updated = 0;
    foreach (var r in rows)
    {
        var vin = r.Vin.Trim().ToUpperInvariant();
        var v = await db.VinPackings.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Vin == vin);
